window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["工业和信息化部"] = {"jiankonghuaxuepinguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"为了加强对监控化学品的监督管理，履行《禁止化学武器公约》，保障公民人身安全和保护环境，根据《中华人民共和国监控化学品管理条例》，制定本细则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事监控化学品生产、经营、使用和进出口等活动，应当遵守本细则。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责全国监控化学品的管理工作。 县级以上地方人民政府工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门负责本行政区域内监控化学品的管理工作。"},{"i":4,"n":"第四条","txt":"各级工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门履行《禁止化学武器公约》工作所需经费，依法列入同级政府预算。"},{"i":5,"n":"第五条","txt":"国家严格控制第一类监控化学品的生产。 为科研、医疗、制造药物或者防护目的需要生产第一类监控化学品的，应当报工业和信息化部批准，并在工业和信息化部指定的小型设施中生产。 严禁在未经工业和信息化部指定的设施中生产第一类监控化学品。"},{"i":6,"n":"第六条","txt":"新建、扩建或者改建用于生产第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的设施，应当填写《监控化学品生产设施新（扩、改）建申请表》并附上申请表中要求提供的相关材料，向所在地的省、自治区、直辖市工业和信息化主管部门提出申请。省、自治区、直辖市工业和信息化主管部门应当自收到全部申请材料之日起20个工作日内审查完毕并签署意见，报工业和信息化部批准。 工业和信息化部应当自收到省、自治区、直辖市工业和信息化主管部门报送的材料之日起20个工作日内作出决定。予以批准的，颁发批准文件；不予批准的，书面通知申请人并说明理由。"},{"i":7,"n":"第七条","txt":"第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的生产设施新建、扩建或者改建工程竣工后，应当自竣工之日起40个工作日内向所在地省、自治区、直辖市工业和信息化主管部门申请竣工验收。验收合格的，所在地的省、自治区、直辖市工业和信息化主管部门应当出具通过验收的审查意见书并报工业和信息化部批准。 竣工验收经工业和信息化部批准后，按照本细则第十条的规定申请监控化学品生产特别许可。"},{"i":8,"n":"第八条","txt":"第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的生产设施新建、扩建或者改建工程有下列情形之一的，不予通过竣工验收，省、自治区、直辖市工业和信息化主管部门应当出具不予通过验收的审查意见： （一）第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的生产设施的标定生产能力达到或者超过设计生产能力150%的； （二）隐瞒有关情况或者提供虚假文件资料申请竣工验收，情节严重的； （三）工业和信息化部规定的其他情形。 不予通过竣工验收的，申请人应当在6个月内完成整改，再次申请竣工验收。"},{"i":9,"n":"第九条","txt":"国家对第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的生产，实行特别许可制度。"},{"i":10,"n":"第十条","txt":"申请监控化学品生产特别许可的，应当具备下列条件： （一）申请人为法人或者非法人组织； （二）有生产监控化学品所需的资金和场所； （三）具有与生产监控化学品相适应的技术条件、生产设施，符合当地环境保护及安全生产监督管理部门的要求； （四）有与生产监控化学品相适应的专业技术人员和管理制度； （五）具备履行《禁止化学武器公约》的能力； （六）五年内无违法生产、经营、使用监控化学品的记录。"},{"i":11,"n":"第十一条","txt":"申请监控化学品生产特别许可的，应当填写《监控化学品生产特别许可申请表》并附上申请表中要求提供的相关材料，向所在地的省、自治区、直辖市工业和信息化主管部门提出申请。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市工业和信息化主管部门应当组织专家，按照《监控化学品生产特别许可现场考核表》的要求对申请人进行现场考核，并于收到全部申请材料之日起20个工作日内，将考核意见和全部申请材料报工业和信息化部。"},{"i":13,"n":"第十三条","txt":"工业和信息化部收到省、自治区、直辖市工业和信息化主管部门报送的材料后，应当对申请材料是否符合本细则第十条规定的条件进行审查，并自收到材料之日起20个工作日内作出决定。予以批准的，颁发生产特别许可证书；不予批准的，书面通知申请人并说明理由。"},{"i":14,"n":"第十四条","txt":"监控化学品生产特别许可证书有效期为5年。生产特别许可证书有效期届满需要继续生产监控化学品的，应当提前6个月通过所在地的省、自治区、直辖市工业和信息化主管部门向工业和信息化部申请延续。经审查符合本细则第十条规定的条件的，应当在有效期届满前准予延续。"},{"i":15,"n":"第十五条","txt":"因企业名称等变更需要更换监控化学品生产特别许可证书的，应当通过所在地的省、自治区、直辖市工业和信息化主管部门，将其生产特别许可证书及变更后的营业执照复印件报工业和信息化部。经审查符合本细则第十条规定条件的，应当准予更换监控化学品生产特别许可证书。"},{"i":16,"n":"第十六条","txt":"生产第二类监控化学品的，不得向未取得第二类监控化学品经营许可证书、使用许可证书的单位或者个人销售第二类监控化学品。"},{"i":17,"n":"第十七条","txt":"国家对第二类监控化学品的经营、第一类和第二类监控化学品的使用，实行许可制度。"},{"i":18,"n":"第十八条","txt":"申请第二类监控化学品经营许可的，应当具备下列条件： （一）申请人为法人或者非法人组织； （二）对第二类监控化学品的采购、运输和储存具有全过程管理能力； （三）有符合安全要求的经营设施和熟悉产品性能的技术人员； （四）有健全的监控化学品经营管理制度； （五）有熟悉监控化学品数据统计和履行《禁止化学武器公约》所需的管理人员和管理制度； （六）五年内无违法生产、经营、使用监控化学品的记录。"},{"i":19,"n":"第十九条","txt":"申请第二类监控化学品经营许可的，应当填写《第二类监控化学品经营申请表》并附上申请表中要求提供的相关材料，向所在地的省、自治区、直辖市工业和信息化主管部门提出申请。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市工业和信息化主管部门应当对申请材料进行审查并进行现场核验，并于收到全部申请材料之日起20个工作日内作出决定。予以批准的，颁发第二类监控化学品经营许可证书；不予批准的，书面通知申请人并说明理由。"},{"i":21,"n":"第二十一条","txt":"经营第二类监控化学品的，不得向未取得第二类监控化学品经营许可证书、使用许可证书的单位或者个人销售第二类监控化学品，不得向未取得第二类监控化学品生产特别许可证书、经营许可证书的单位或者个人购买第二类监控化学品。 购买第二类监控化学品的，应当查验销售人的第二类监控化学品生产特别许可证书、经营许可证书并留存复印件。销售第二类监控化学品的，应当查验购买人的第二类监控化学品经营许可证书、使用许可证书并留存复印件。"},{"i":22,"n":"第二十二条","txt":"经营第二类监控化学品的，应当保存购买、储存、销售原始记录和统计台账，保存期限不得少于3年。第二类监控化学品的经营者应当在每年1月和7月分别向所在地省、自治区、直辖市工业和信息化主管部门报送前6个月的销售记录。"},{"i":23,"n":"第二十三条","txt":"为科研、医疗、制造药物或者防护目的需要使用第一类监控化学品的，应当填写《第一类监控化学品使用申请表》并附上申请表中要求提供的相关材料，向工业和信息化部提出申请。工业和信息化部予以批准的，颁发批准文件。申请人应当凭批准文件与工业和信息化部指定的生产单位签订合同，并将合同副本报送工业和信息化部备案。"},{"i":24,"n":"第二十四条","txt":"申请第二类监控化学品使用许可的，应当具备以下条件： （一）申请人为法人或者非法人组织； （二）对第二类监控化学品的采购、运输、储存和使用具有全过程管理能力； （三）有健全的监控化学品使用管理制度； （四）具备履行《禁止化学武器公约》的能力； （五）五年内无违法生产、经营、使用监控化学品的记录。"},{"i":25,"n":"第二十五条","txt":"申请第二类监控化学品使用许可的，应当填写《第二类监控化学品使用申请表》并附上申请表中要求提供的相关材料，向所在地省、自治区、直辖市工业和信息化主管部门提出申请，并根据年使用量一并提交相关资料。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市工业和信息化主管部门应当对申请材料进行审查并进行现场核验，并于收到全部申请材料之日起20个工作日内作出决定。予以批准的，颁发第二类监控化学品使用许可证书；不予批准的，书面通知申请人并说明理由。"},{"i":27,"n":"第二十七条","txt":"取得第二类监控化学品使用许可的，应当凭第二类监控化学品使用许可证书向取得第二类监控化学品生产特别许可证书、经营许可证书的单位或者个人购买第二类监控化学品。"},{"i":28,"n":"第二十八条","txt":"第二类监控化学品经营许可证书、使用许可证书有效期为5年，许可证书的样式由工业和信息化部统一规定。 许可证书有效期届满需要继续经营、使用监控化学品的，应当提前6个月向所在地省、自治区、直辖市工业和信息化主管部门申请延续。经审查符合本细则规定的条件的，应当在有效期届满前准予延续。"},{"i":29,"n":"第二十九条","txt":"国家对第一类监控化学品和第二类、第三类监控化学品及其生产技术和专用设备的进出口，实行许可制度。"},{"i":30,"n":"第三十条","txt":"第一类监控化学品和第二类、第三类监控化学品及其生产技术和专用设备的进出口业务，按《中华人民共和国监控化学品管理条例》规定由被指定单位经营。被指定单位应当向工业和信息化部提出进出口申请。 申请进口的，应当提交下列材料：《监控化学品进口申请表》；经省、自治区、直辖市工业和信息化主管部门确认的《进口监控化学品经营申请表》或者《进口监控化学品用户申请表》；进口合同原件。 申请出口的，应当提交下列材料：《监控化学品出口申请表》；进口国政府或者政府委托机构出具的所进口的监控化学品及其生产技术和专用设备不用于生产化学武器和不转口第三国的保证书，并注明所需监控化学品的名称、数量、最终用途以及最终使用者的名称和地址；出口合同原件。"},{"i":31,"n":"第三十一条","txt":"对于申请进口或者出口第一类监控化学品的，工业和信息化部应当自收到全部申请材料之日起20个工作日内完成审查并签署意见，报国务院批准。被指定单位应当凭国务院的批准文件向商务部申领进口或者出口许可证。 对于申请进口或者出口第二类、第三类监控化学品及其生产技术和专用设备的，工业和信息化部应当自收到全部申请材料之日起20个工作日内作出决定。予以批准的，颁发批准文件，被指定单位应当凭工业和信息化部的批准文件向商务部申领进口或者出口许可证。不予批准的，书面通知申请人并说明理由。"},{"i":32,"n":"第三十二条","txt":"需要变更进口或者出口许可的，除提供本细则第三十条规定的材料外，还应当提交其进口或者出口批准文件和许可证原件。"},{"i":33,"n":"第三十三条","txt":"被指定单位应当书面向工业和信息化部报送下列信息： （一）负责此项工作的主要领导名单； （二）负责此项业务的专门机构名称； （三）对外签署进出口合同的专职人员的身份证和工作证复印件。 前款规定的信息发生变更的，应当在10个工作日内报工业和信息化部。"},{"i":34,"n":"第三十四条","txt":"工业和信息化部组织建设监控化学品数据申报系统。 在中华人民共和国境内从事监控化学品生产、使用或者进出口活动的，应当通过数据申报系统定期填报《全国监控化学品统计报表》，配合工业和信息化主管部门完成《禁止化学武器公约》规定的国家宣布工作。"},{"i":35,"n":"第三十五条","txt":"生产、使用第一类监控化学品的，应当向工业和信息化部报送《全国监控化学品统计报表》。"},{"i":36,"n":"第三十六条","txt":"第二类、第三类、第四类监控化学品的数据申报实行属地管理、逐级审核上报。省、自治区、直辖市工业和信息化主管部门应当组织、汇总、核实宣布数据，并在规定时间内报工业和信息化部。 跨省、自治区、直辖市生产、使用监控化学品的单位的二级单位，应当在厂区所在地申报《全国监控化学品统计报表》。"},{"i":37,"n":"第三十七条","txt":"生产第二类、第三类监控化学品或者使用第二类监控化学品的，应当按时申报关于年度宣布和预计宣布的《全国监控化学品统计报表》。预计宣布统计报表提交后，预计生产、使用活动超出原宣布计划的，应当在有关活动开始前不少于20个工作日申报关于变更宣布的《全国监控化学品统计报表》。 生产、使用第二类监控化学品的，应当妥善保存与第二类监控化学品的生产、使用有关的记录，保存期限不得少于3年。生产第三类监控化学品的，应当妥善保存与第三类监控化学品有关的生产记录，保存期限不得少于1年。终止生产经营活动的，应当将与监控化学品生产、使用有关的记录移交所在地设区的市级以上地方工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门存档。"},{"i":38,"n":"第三十八条","txt":"生产第四类监控化学品的，应当按时申报关于年度宣布的《全国监控化学品统计报表》。 生产第四类监控化学品的，应当妥善保存与第四类监控化学品有关的生产记录，保存期限不得少于1年。终止生产经营活动的，应当将与第四类监控化学品生产有关的生产记录移交所在地设区的市级以上地方工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门存档。"},{"i":39,"n":"第三十九条","txt":"从事第一类监控化学品和第二类、第三类监控化学品及其生产技术和专用设备进出口业务的被指定单位，应当按时向工业和信息化部申报年度第一类、第二类和第三类监控化学品进出口数据，并妥善保存与监控化学品进出口活动有关的记录，保存期限不得少于3年。终止进出口活动的，应当将与监控化学品进出口有关的记录移交工业和信息化部存档。"},{"i":40,"n":"第四十条","txt":"从事监控化学品生产、使用或者进出口活动的，应当根据《全国监控化学品统计报表》所列的填报说明和要求按时、准确进行申报，不得拒报、虚报、漏报或者瞒报，不得擅自变更申报范围和内容。 参与监控化学品数据申报的工作人员，应当对监控化学品的数据资料采取妥善的保护措施，为填报单位保守商业和技术秘密。"},{"i":41,"n":"第四十一条","txt":"生产、经营或者使用第二类监控化学品以及生产第三类监控化学品的，终止生产经营活动时应当制定监控化学品生产装置、库存和相关数据的处置方案。处置方案应当报送所在地省、自治区、直辖市工业和信息化主管部门。"},{"i":42,"n":"第四十二条","txt":"生产监控化学品以及使用第二类监控化学品的，其监控化学品达到或者超过《禁止化学武器公约》规定的核查阈值的，应当履行接受国际视察的义务，做好接受禁止化学武器组织国际视察的各项准备工作。 接受国际视察的义务包括： （一）根据《禁止化学武器公约》，提供国际视察所需的数据资料，及时回答视察组的问询； （二）确保视察组顺利查看视察任务授权范围内的设施或者区域，配合视察组进行取样和分析； （三）提供视察组及陪同人员所需的工作场所、通讯手段和必要的工作条件； （四）《禁止化学武器公约》规定的其他义务。"},{"i":43,"n":"第四十三条","txt":"接受国际视察的监控化学品相关设施所在地工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门应当组织协调本行政区域内相关部门，在交通、安全、卫生等方面给予必要保障，确保国际视察顺利进行。"},{"i":44,"n":"第四十四条","txt":"各级工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门，依法对从事监控化学品生产、经营、使用以及进出口单位的监控化学品有关情况进行监督检查。"},{"i":45,"n":"第四十五条","txt":"被监督检查单位应当配合、接受监督检查，不得拒绝或者阻碍检查人员依法执行职务，不得隐瞒或者拒绝提供相关信息。"},{"i":46,"n":"第四十六条","txt":"违反本细则第五条、第九条的规定，未经批准，生产第一类、第二类、第三类监控化学品或者第四类监控化学品中含磷、硫、氟的特定有机化学品的，按照《中华人民共和国监控化学品管理条例》第二十一条的规定处罚。"},{"i":47,"n":"第四十七条","txt":"违反本细则第六条第一款的规定，未经批准，新建、扩建或者改建用于生产第二类、第三类监控化学品和第四类监控化学品中含磷、硫、氟的特定有机化学品的设施的，由省、自治区、直辖市工业和信息化主管部门责令限期改正，停止施工，拆除相关设施，可以并处一万元以上三万元以下罚款。"},{"i":48,"n":"第四十八条","txt":"涂改、倒卖、出租、出借或者以其他方式转让生产特别许可证、经营许可证、使用许可证的，由所在地的省、自治区、直辖市工业和信息化主管部门责令限期改正，可以并处三万元以下罚款。"},{"i":49,"n":"第四十九条","txt":"监控化学品生产特别许可证、经营许可证、使用许可证有效期届满，未办理延期手续仍继续生产、经营、使用的，按照《中华人民共和国监控化学品管理条例》第二十一条、第二十二条、第二十三条的规定处罚。"},{"i":50,"n":"第五十条","txt":"违反本细则第十六条、第二十一条、第二十二条、第二十七条的规定，违法销售、购买监控化学品，或者未按照规定保存有关记录的，由所在地的省、自治区、直辖市工业和信息化主管部门责令限期改正，予以警告，可以并处三万元以下罚款。 违反本细则第三十七条第二款、第三十八条第二款的规定，未妥善保存、移送相关记录的，由所在地设区的市级以上地方工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门责令限期改正，予以警告，可以并处三万元以下罚款。 违反本细则第三十九条的规定，未妥善保存、移送相关记录的，由工业和信息化部责令限期改正，予以警告，可以并处三万元以下罚款。"},{"i":51,"n":"第五十一条","txt":"违反本细则第十七条的规定，未经批准经营、使用第二类监控化学品的，按照《中华人民共和国监控化学品管理条例》第二十二条、第二十三条的规定处罚。"},{"i":52,"n":"第五十二条","txt":"以虚假合同或者虚假保证书等文件骗取监控化学品进出口批准文件的，由工业和信息化部责令限期改正，予以警告，可以并处一万元以上三万元以下罚款。在整改合格前，该单位不得申请进出口监控化学品。"},{"i":53,"n":"第五十三条","txt":"违反本细则第三十五条、第三十七条至第三十九条的规定申报监控化学品数据，或者拒报、虚报、漏报或者瞒报有关监控化学品数据的，按照《中华人民共和国监控化学品管理条例》第二十四条的规定处罚。"},{"i":54,"n":"第五十四条","txt":"从事监控化学品的生产、使用活动的，拒绝履行接受国际视察义务，不配合国际视察，或者阻挠国际视察进行的，由所在地的省、自治区、直辖市工业和信息化主管部门责令限期改正，予以警告，可以并处三万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"违反《中华人民共和国监控化学品管理条例》及本细则规定受到行政处罚的，由各级工业和信息化主管部门或者地方人民政府确定的监控化学品管理部门依照有关法律、行政法规的规定予以公示。"},{"i":56,"n":"第五十六条","txt":"本细则所称监控化学品，是指下列四类化学品： 第一类：可作为化学武器的化学品； 第二类：可作为生产化学武器前体的化学品； 第三类：可作为生产化学武器主要原料的化学品； 第四类：除炸药和纯碳氢化合物外的特定有机化学品。 监控化学品包括其纯品和不同浓度的工业品，类别按照《各类监控化学品名录》和《列入第三类监控化学品的新增品种清单》执行。 本细则所称监控化学品生产技术，是指生产监控化学品的各种技术手段。 本细则所称监控化学品专用设备，是指采用各种监控化学品生产技术，生产监控化学品过程中所需要的产品合成、分离、提纯、热传导和自控仪表等专用设备。 本细则所称国际视察，是指禁止化学武器组织根据《禁止化学武器公约》的规定，派遣视察组对我国监控化学品相关设施进行的现场视察，包括初始视察和例行视察等。 本细则所称核查阈值，是指《禁止化学武器公约》规定应当履行接受国际视察义务的化学品数量最低值。"},{"i":57,"n":"第五十七条","txt":"《各类监控化学品名录》和《列入第三类监控化学品的新增品种清单》中的监控化学品低于一定浓度阈值时，可以豁免数据申报和进出口许可。相关浓度阈值由工业和信息化部根据实际情况制定和调整。"},{"i":58,"n":"第五十八条","txt":"工业和信息化部和省、自治区、直辖市工业和信息化主管部门作出行政许可决定，依法需要进行现场考核、核验或者评审的，所需时间不计算在本细则规定的许可时限内，但应当将所需时间书面告知申请人。"},{"i":59,"n":"第五十九条","txt":"各省、自治区、直辖市工业和信息化主管部门可以根据实际情况，制定本行政区域监控化学品管理的实施办法，发布后报送工业和信息化部。"},{"i":60,"n":"第六十条","txt":"本细则规定的行政许可表格样式，由工业和信息化部统一制作公布，并根据需要调整。"},{"i":61,"n":"第六十一条","txt":"本细则自2019年1月1日起施行。1997年3月10日公布的《<中华人民共和国监控化学品管理条例>实施细则》（原化学工业部令第12号）同时废止。"}],"yeyuwuxiandiantaiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对业余无线电台的管理，维护空中电波秩序，促进业余无线电活动的有序开展，根据《中华人民共和国无线电管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设置、使用业余无线电台，对业余无线电台实施监督管理，适用本办法。 本办法所称业余无线电台，是指开展《中华人民共和国无线电频率划分规定》确定的业余业务和卫星业余业务所需的发信机、收信机或者发信机与收信机的组合（包括附属设备）。"},{"i":3,"n":"第三条","txt":"国家无线电管理机构和省、自治区、直辖市无线电管理机构（以下简称地方无线电管理机构）依法对业余无线电台实施监督管理。 国家无线电管理机构和地方无线电管理机构统称无线电管理机构。"},{"i":4,"n":"第四条","txt":"设置业余无线电台，应当按照本办法的规定办理审批手续，取得业余无线电台执照。 国家鼓励和支持业余无线电通信技术的研究、普及和突发重大自然灾害等紧急情况下的应急无线电通信活动。 依法设置的业余无线电台受国家法律保护。"},{"i":5,"n":"第五条","txt":"国家对业余无线电台实施分类管理。 业余无线电台分类管理规定由国家无线电管理机构另行制定。"},{"i":6,"n":"第六条","txt":"申请设置业余无线电台，应当具备下列条件： （一）熟悉无线电管理规定； （二）具备国家无线电管理机构规定的操作技术能力； （三）无线电发射设备符合国家相关技术标准； （四）法律、行政法规规定的其他条件。 单位申请设置业余无线电台的，其业余无线电台负责人应当具备前款第一项规定的条件，技术负责人应当具备前款第一项和第二项规定的条件。 个人申请设置具有发信功能的业余无线电台的，应当年满十八周岁。"},{"i":7,"n":"第七条","txt":"申请设置业余无线电台，应当向设台地地方无线电管理机构提交下列书面材料： （一）《业余无线电台设置（变更）申请表》； （二）《业余无线电台技术资料申报表》； （三）个人身份证明或者设台单位证明材料的原件、复印件。申请人为单位的，还应当提交其业余无线电台负责人和技术负责人身份证明材料的原件、复印件； （四）具备相应操作技术能力证明材料的原件、复印件。 地方无线电管理机构在验证前款第三项、第四项规定的证明材料的真实性后，应当及时将原件退还申请人。"},{"i":8,"n":"第八条","txt":"设置在省、自治区、直辖市范围内通信的业余无线电台，由设台地地方无线电管理机构审批。 设置通信范围涉及两个以上的省、自治区、直辖市或者涉及境外的业余无线电台，由国家无线电管理机构审批。国家无线电管理机构可以委托设台地地方无线电管理机构负责除业余信标台、用于卫星业余业务的空间业余无线电台（“用于卫星业余业务的空间业余无线电台”以下简称“空间业余无线电台”）等特殊业余无线电台以外的业余无线电台的设置审批，核发业余无线电台执照。"},{"i":9,"n":"第九条","txt":"设置空间业余无线电台，应当符合本办法和空间电台管理的相关规定。"},{"i":10,"n":"第十条","txt":"业余中继台的设置和技术参数等应当符合国家以及设台地地方无线电管理机构的规定。 业余中继台应当设专人负责监控和管理工作，配备有效的遥控手段。"},{"i":11,"n":"第十一条","txt":"业余无线电台无线电发射设备应当依法取得《中华人民共和国无线电发射设备型号核准证》。申请人可以使用符合国家相关技术标准的自制、改装、拼装的无线电发射设备办理审批手续。 对业余无线电台专用无线电发射设备进行型号核准，应当以《中华人民共和国无线电频率划分规定》中有关无线电发射设备技术指标的规定为依据。 业余无线电台专用无线电发射设备不得用于其他无线电业务，其发射频率应当在业余业务或者卫星业余业务频段内。"},{"i":12,"n":"第十二条","txt":"申请材料不全、不符合法定形式的，无线电管理机构应当当场或者在五个工作日内一次告知申请人需要补正的全部内容。 申请材料齐全、符合法定形式和本办法规定的，无线电管理机构应当当场或者自受理申请之日起二十个工作日内，核发业余无线电台执照；不符合规定条件的，应当书面通知申请人不予核发业余无线电台执照并说明理由。"},{"i":13,"n":"第十三条","txt":"业余无线电台执照由国家无线电管理机构统一印制。 业余无线电台执照的有效期不超过五年。业余无线电台执照有效期届满后需要继续使用的，应当在有效期届满前三十日以前向核发执照的无线电管理机构申请办理延续手续。"},{"i":14,"n":"第十四条","txt":"业余无线电台执照应当载明所核定的技术参数和发射设备等信息；单位设置业余无线电台的，其执照还应当载明业余无线电台负责人和技术负责人。 业余无线电台的技术参数不得超出其业余无线电台执照所核定的范围。需要变更业余无线电台执照核定内容的，应当向核发执照的无线电管理机构申请办理变更手续，换发业余无线电台执照。"},{"i":15,"n":"第十五条","txt":"终止使用业余无线电台的，应当向核发业余无线电台执照的无线电管理机构申请注销执照。"},{"i":16,"n":"第十六条","txt":"禁止涂改、仿制、伪造、倒卖、出租或者出借业余无线电台执照。"},{"i":17,"n":"第十七条","txt":"根据国家无线电管理机构的委托核发业余无线电台执照的地方无线电管理机构，应当自核发、换发、注销执照之日起二十个工作日内，将相关情况报国家无线电管理机构。"},{"i":18,"n":"第十八条","txt":"使用业余无线电台，应当具备下列条件： （一）熟悉无线电管理规定； （二）具备国家无线电管理机构规定的操作技术能力，取得相应操作技术能力证明。"},{"i":19,"n":"第十九条","txt":"业余无线电台使用的频率应当符合《中华人民共和国无线电频率划分规定》。 业余业务、卫星业余业务作为次要业务使用频率或者与其他主要业务共同使用频率的，应当遵守无线电管理机构对该频率的使用规定。 业余无线电台在无线电管理机构核准其使用的频段内，享有平等的频率使用权。 国家对业余无线电台免收无线电频率占用费。"},{"i":20,"n":"第二十条","txt":"业余无线电台的通信对象应当限于业余无线电台。在突发重大自然灾害等紧急情况下，业余无线电台可以和非业余无线电台通信，但应当及时向所在地地方无线电管理机构报告，其通信内容应当限于与抢险救灾直接相关的紧急事务或者应急救援相关部门交办的任务。"},{"i":21,"n":"第二十一条","txt":"未经所在地地方无线电管理机构批准，业余无线电台不得以任何方式进行广播或者发射通播性质的信号。"},{"i":22,"n":"第二十二条","txt":"业余无线电台在通信过程中应当使用明语及业余无线电领域公认的缩略语和简语，数据文件交换应当使用公开的方式。但是，卫星业余业务中地面控制电台和空间电台之间交换的控制信号可以除外。 业余无线电台试验新的编码、调制方式和数字通信协议等，应当事先公开并向所在地地方无线电管理机构提交相关技术信息。"},{"i":23,"n":"第二十三条","txt":"业余无线电台设置人应当对无线电发射设备进行有效监控，确保正常工作，保证能够及时停止其造成的有害干扰。"},{"i":24,"n":"第二十四条","txt":"业余中继台应当向其覆盖区域内的所有业余无线电台提供平等的服务，并将使用业余中继台所需的各项技术参数公开。"},{"i":25,"n":"第二十五条","txt":"依法设置的通信范围涉及两个以上的省、自治区、直辖市或者涉及境外的业余无线电台，可以在设台地以外的地点进行异地发射操作，但应当遵守所在地地方无线电管理机构的相关规定。"},{"i":26,"n":"第二十六条","txt":"在业余无线电台操作培训中，已接受无线电管理规定等培训的人员，可以在业余无线电台设置人或者技术负责人的现场辅导下，在业余无线电台执照核定范围和国家有关业余无线电台操作权限规定确定的范围内，进行发射操作实习。"},{"i":27,"n":"第二十七条","txt":"业余无线电台通信不得发送、接收与业余业务和卫星业余业务无关的信号，不得传播、公布无意接收的非业余业务和卫星业余业务的信息。"},{"i":28,"n":"第二十八条","txt":"业余无线电台供其设置人、使用人用于相互通信、技术研究和自我训练。 禁止利用业余无线电台从事下列活动： （一）发布、传播违反法律或者公共道德的信息； （二）从事商业或者其他与营利有关的活动； （三）阻碍其他无线电台通信； （四）法律、行政法规禁止的其他活动。"},{"i":29,"n":"第二十九条","txt":"业余无线电台设置人、使用人应当加强自律，接受无线电管理机构或者其委托单位的指导、监督和检查。"},{"i":30,"n":"第三十条","txt":"业余无线电台的通信时间、通信频率、通信模式和通信对象等内容应当记入电台日志。 电台日志应当保留两年，供无线电管理机构检查。"},{"i":31,"n":"第三十一条","txt":"业余无线电台设置人、使用人应当正确使用业余无线电台呼号。"},{"i":32,"n":"第三十二条","txt":"业余无线电台呼号由国家无线电管理机构编制和分配。 无线电管理机构核发业余无线电台执照，应当同时指配业余无线电台呼号。业余信标台和空间业余无线电台等特殊业余无线电台呼号由国家无线电管理机构指配，其他业余无线电台呼号由地方无线电管理机构指配。 核发业余无线电台执照的无线电管理机构已经为设置人指配业余无线电台呼号的，不另行为其指配其他业余无线电台呼号。"},{"i":33,"n":"第三十三条","txt":"业余无线电台在每次通信建立及结束时，应当主动发送本台呼号；在发信过程中应当至少每十分钟发送本台呼号一次。 业余中继台应当周期性发送本台呼号，两次发送的时间间隔不得超过十分钟。"},{"i":34,"n":"第三十四条","txt":"在他人设置的业余无线电台上进行发射操作或者由国家无线电管理机构审批的业余无线电台在设台地以外的地点进行异地发射操作的，应当按照本办法所附《业余无线电台呼号说明》的规定使用业余无线电台呼号。"},{"i":35,"n":"第三十五条","txt":"禁止盗用、转让、私自编制或者违法使用业余无线电台呼号。"},{"i":36,"n":"第三十六条","txt":"无线电管理机构依法注销业余无线电台执照的，应当同时注销业余无线电台呼号。业余无线电台呼号在注销五年后可以另行指配。 业余无线电台执照被依法注销后一年内，设置人又申请设置业余无线电台的，无线电管理机构应当指配原业余无线电台呼号。 业余无线电台执照被依法注销后一年内，设置人在其他省、自治区、直辖市申请设置业余无线电台的，可以申请使用原业余无线电台呼号，但应当事先征得指配原业余无线电台呼号的无线电管理机构的书面同意。设置人应当在取得业余无线电台执照后一个月内，向指配原业余无线电台呼号的无线电管理机构备案。"},{"i":37,"n":"第三十七条","txt":"无线电管理机构应当对业余无线电台实施监督检查。业余无线电台设置人、使用人应当配合。"},{"i":38,"n":"第三十八条","txt":"有下列情形之一的，核发业余无线电台执照的无线电管理机构或者其上级无线电管理机构可以撤销执照： （一）对不具备申请资格或者不符合申请条件的申请人核发执照的； （二）以欺骗、贿赂等不正当手段取得执照的； （三）依法可以撤销执照的其他情形。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，核发业余无线电台执照的无线电管理机构应当注销执照： （一）设置业余无线电台的个人死亡或者丧失行为能力的； （二）业余无线电台执照有效期届满未延续的； （三）设置业余无线电台的单位依法终止的； （四）业余无线电台执照依法被撤销、吊销的。"},{"i":40,"n":"第四十条","txt":"有下列行为之一的，由无线电管理机构依照《中华人民共和国无线电管理条例》第四十三条的规定处罚： （一）擅自设置、使用业余无线电台的； （二）干扰无线电业务的； （三）随意变更核定项目，发送和接收与业余业务和卫星业余业务无关的信号的。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，无线电管理机构应当依据职权责令限期改正，可以处警告或者三万元以下的罚款： （一）涂改、仿制、伪造业余无线电台执照，或者倒卖、出租、出借及以其他形式非法转让业余无线电台执照的； （二）盗用、出租、出借、转让、私自编制或者违法使用业余无线电台呼号的； （三）违法使用业余无线电台造成严重后果的； （四）以不正当手段取得业余无线电台执照的； （五）不再具备设置或者使用业余无线电台条件而继续使用业余无线电台的； （六）向负责监督检查的无线电管理机构隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的； （七）超出核定范围使用频率或者有其他违反频率管理有关规定的行为的。"},{"i":42,"n":"第四十二条","txt":"中华人民共和国境外的组织或者个人在境内设置、使用业余无线电台，其所在的国家或者地区与中华人民共和国签订相关协议的，按照协议办理；未签订相关协议的，按照本办法的规定办理。"},{"i":43,"n":"第四十三条","txt":"本办法自2013年1月1日起施行。本办法施行前颁布的有关规定与本办法不一致的，按照本办法执行。 附录：1.业余无线电台设置（变更）申请表 2.业余无线电台技术资料申报表 3.业余无线电台呼号说明"}],"chengyongcheqiyepingjunranliaoxiaohaoliangyuxinnen28ff2a-2":[{"i":1,"n":"第一条","txt":"为了提升乘用车节能水平，缓解能源和环境压力，建立节能与新能源汽车管理长效机制，促进汽车产业健康发展，根据《中华人民共和国节约能源法》等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的乘用车企业平均燃料消耗量与新能源汽车积分管理，适用本办法。"},{"i":3,"n":"第三条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局实施乘用车企业平均燃料消耗量与新能源汽车积分管理。"},{"i":4,"n":"第四条","txt":"本办法所称乘用车，是指《汽车和挂车类型的术语和定义》（GB/T 3730.1-2001）第2.1.1.1款至第2.1.1.10款规定的、最大设计总质量不超过3500千克的车辆，包括新能源乘用车和传统能源乘用车。 本办法所称新能源乘用车，是指采用新型动力系统，完全或者主要依靠新型能源驱动的乘用车，包括插电式混合动力（含增程式）乘用车、纯电动乘用车和燃料电池乘用车等。 本办法所称传统能源乘用车，是指除新能源乘用车以外的，能够燃用汽油、柴油、气体燃料或者醇醚燃料等的乘用车（含非插电式混合动力乘用车）。 本办法所称低油耗乘用车，是指综合燃料消耗量不超过《乘用车燃料消耗量评价方法及指标》（GB 27999）中对应的车型燃料消耗量目标值与该核算年度的企业平均燃料消耗量要求之积（计算结果按四舍五入原则保留两位小数）的传统能源乘用车。"},{"i":5,"n":"第五条","txt":"乘用车企业包括中华人民共和国境内乘用车生产企业、进口乘用车供应企业。 本办法所称境内乘用车生产企业，是指取得工业和信息化部乘用车生产企业准入并获得强制性产品认证的乘用车企业。 本办法所称进口乘用车供应企业，是指从中华人民共和国境外进口并在境内销售获得强制性产品认证的乘用车的企业，包括获境外乘用车生产企业授权的进口乘用车供应企业和未获授权的进口乘用车供应企业。"},{"i":6,"n":"第六条","txt":"工业和信息化部建立汽车燃料消耗量与新能源汽车积分管理平台，统筹推进企业平均燃料消耗量与新能源汽车积分公示、转让、交易等工作。 乘用车企业应当按照工业和信息化部的要求（见附件1），报送其生产、进口的乘用车燃料消耗量和新能源乘用车相关数据；通过汽车燃料消耗量与新能源汽车积分管理平台，开展积分转让或者交易。"},{"i":7,"n":"第七条","txt":"境内各乘用车生产企业和各进口乘用车供应企业，是乘用车企业平均燃料消耗量积分的核算主体，单独实施核算。"},{"i":8,"n":"第八条","txt":"乘用车企业平均燃料消耗量积分，为该企业平均燃料消耗量的达标值和实际值之间的差额，与其乘用车生产量或者进口量的乘积（计算结果按四舍五入原则保留整数）。 实际值低于达标值产生正积分，高于达标值产生负积分。"},{"i":9,"n":"第九条","txt":"乘用车企业平均燃料消耗量达标值，是指该企业平均燃料消耗量目标值与该核算年度的企业平均燃料消耗量要求的乘积（计算结果按四舍五入原则保留两位小数）。 乘用车企业平均燃料消耗量目标值，按照《乘用车燃料消耗量评价方法及指标》第5.2款计算（计算结果按四舍五入原则保留两位小数）。同一车型在核算年度有多个不同的燃料消耗量目标值的，按照不同的目标值分开计算。 核算年度的企业平均燃料消耗量要求，是指《乘用车燃料消耗量评价方法及指标》第5.3款规定的相关比值。"},{"i":10,"n":"第十条","txt":"乘用车企业平均燃料消耗量实际值，按照《乘用车燃料消耗量评价方法及指标》第5.1款计算（计算结果按四舍五入原则保留两位小数）。同一车型在核算年度有多个不同的燃料消耗量的，按照不同的燃料消耗量分开计算。"},{"i":11,"n":"第十一条","txt":"境内乘用车生产企业的乘用车生产量，按照该企业在核算年度内生产的、用于境内销售的乘用车实际产量核算。 进口乘用车供应企业的乘用车进口量，按照该企业在核算年度进口用于境内销售的、获得强制性产品认证并经出入境检验检疫机构检验的乘用车数量核算。"},{"i":12,"n":"第十二条","txt":"对核算年度生产量2000辆以下并且生产、研发和运营保持独立的境内乘用车生产企业，进口量2000辆以下的获境外乘用车生产企业授权的进口乘用车供应企业，放宽其企业平均燃料消耗量积分的达标要求： （一）2016年度至2020年度，企业平均燃料消耗量较上一年度下降6%以上的，其达标值在《乘用车燃料消耗量评价方法及指标》规定的企业平均燃料消耗量要求基础上放宽60%；下降3%以上不满6%的，其达标值放宽30%； （二）2021年度至2023年度，企业平均燃料消耗量较上一年度下降达到4%以上的，其达标值在《乘用车燃料消耗量评价方法及指标》规定的企业平均燃料消耗量要求基础上放宽60%；下降2%以上不满4%的，其达标值放宽30%； （三）2024年度及以后年度的核算要求，由工业和信息化部另行公布。 未获境外乘用车生产企业授权的进口乘用车供应企业按照前款的规定管理，并自2019年度起实施企业平均燃料消耗量"},{"i":13,"n":"第十三条","txt":"境内各乘用车生产企业和各进口乘用车供应企业，是新能源汽车积分的核算主体，单独实施核算。"},{"i":14,"n":"第十四条","txt":"乘用车企业新能源汽车积分，为该企业新能源汽车积分实际值与达标值之间的差额。 实际值高于达标值产生正积分，低于达标值产生负积分。"},{"i":15,"n":"第十五条","txt":"乘用车企业新能源汽车积分实际值，是指该企业在核算年度内生产或者进口的新能源乘用车各车型的积分与该车型生产量或者进口量乘积之和（计算结果按四舍五入原则保留整数）。 前款规定的生产量、进口量，按照本办法第十一条规定的方法核算。 新能源乘用车车型积分按照《新能源乘用车车型积分计算方法》（见附件2）确定。"},{"i":16,"n":"第十六条","txt":"乘用车企业新能源汽车积分达标值，是指该企业在核算年度内传统能源乘用车的生产量或者进口量，与新能源汽车积分比例要求的乘积（计算结果按四舍五入原则保留整数）。 传统能源乘用车中低油耗乘用车的生产量或者进口量按照以下规定计算： （一）2021年度、2022年度、2023年度，低油耗乘用车的生产量或者进口量分别按照其数量的0.5倍、0.3倍、0.2倍计算； （二）2024年度及以后年度的低油耗乘用车生产量或者进口量计算倍数，由工业和信息化部另行公布。"},{"i":17,"n":"第十七条","txt":"对传统能源乘用车年度生产量或者进口量不满3万辆的乘用车企业，不设定新能源汽车积分比例要求；达到3万辆以上的，从2019年度开始设定新能源汽车积分比例要求。 2019年度、2020年度、2021年度、2022年度、2023年度的新能源汽车积分比例要求分别为10%、12%、14%、16%、18%。2024年度及以后年度的新能源汽车积分比例要求，由工业和信息化部另行公布。"},{"i":18,"n":"第十八条","txt":"乘用车企业应当于每年12月20日前，向工业和信息化部提交下一年度乘用车企业平均燃料消耗量与新能源汽车积分年度预报告。 预报告的内容包括本企业平均燃料消耗量预期达标值、预期实际值和新能源汽车积分预期值等（见附件3）。"},{"i":19,"n":"第十九条","txt":"乘用车企业应当于每年3月1日前，向工业和信息化部提交上一年度乘用车企业平均燃料消耗量与新能源汽车积分执行情况年度报告。 报告的内容包括本企业生产或者进口的各车型乘用车数量、关键参数、燃料消耗量、电能消耗量和对应车型的燃料消耗量目标值，以及本企业平均燃料消耗量达标值、实际值和新能源汽车积分等（见附件3）。"},{"i":20,"n":"第二十条","txt":"工业和信息化部于每年4月10日前，通过汽车燃料消耗量与新能源汽车积分管理平台，向社会公示上一年度乘用车企业平均燃料消耗量与新能源汽车积分相关情况。 对公示的乘用车企业平均燃料消耗量与新能源汽车积分相关情况有异议的，可以在30日内向工业和信息化部提出。工业和信息化部在收到异议后30日内作出答复。"},{"i":21,"n":"第二十一条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局于每年6月30日前，对乘用车企业提交的企业平均燃料消耗量与新能源汽车积分执行情况年度报告和相关数据进行核实，并发布上一年度乘用车企业平均燃料消耗量与新能源汽车积分核算情况报告。"},{"i":22,"n":"第二十二条","txt":"乘用车企业平均燃料消耗量正积分可以结转或者在关联企业间转让。 乘用车企业新能源汽车正积分可以依据本办法自由交易，并按照下列规定结转，结转有效期不超过三年： （一）2019年度的新能源汽车正积分可以等额结转一年； （二）2020年度的新能源汽车正积分，每结转一次，结转比例为50%； （三）2021年度及以后年度乘用车企业平均燃料消耗量实际值（仅核算传统能源乘用车）与达标值的比值不高于123%的，允许其当年度产生的新能源汽车正积分结转，每结转一次，结转比例为50%。只生产或者进口新能源汽车的乘用车企业产生的新能源汽车正积分按照50%的比例结转。 乘用车企业有平均燃料消耗量负积分、新能源汽车负积分的，应当在乘用车企业平均燃料消耗量与新能源汽车积分核算情况报告发布后60日内，向工业和信息化部提交其平均燃料消耗量负积分和新能源汽车负积分抵偿报告（见附件4），并在核算情况报告发布后90日内完成负积"},{"i":23,"n":"第二十三条","txt":"具有下列关系之一的乘用车企业，属于本办法第二十二条第一款规定的关联企业： （一）境内乘用车生产企业与其直接或者间接持股总和达到25%以上的其他境内乘用车生产企业； （二）同为第三方直接或者间接持股总和达到25%以上的境内乘用车生产企业； （三）获境外乘用车生产企业授权的进口乘用车供应企业，与该境外乘用车生产企业直接或者间接持股总和达到25%以上的境内乘用车生产企业，以及直接或者间接对该境外乘用车生产企业持股总和达到25%以上的境内乘用车生产企业。"},{"i":24,"n":"第二十四条","txt":"乘用车企业平均燃料消耗量正积分结转后续年度使用的，按照一定比例进行结转，结转有效期不超过三年。2018年度及以前年度的正积分，每结转一次，结转比例为80%；2019年度及以后年度的正积分，每结转一次，结转比例为90%。"},{"i":25,"n":"第二十五条","txt":"乘用车企业受让的平均燃料消耗量正积分，仅限其在当年度使用，不得再次转让。"},{"i":26,"n":"第二十六条","txt":"乘用车企业平均燃料消耗量负积分应当采取下列方式抵偿归零： （一）使用本企业结转的平均燃料消耗量正积分； （二）使用本企业受让的平均燃料消耗量正积分； （三）使用本企业产生的新能源汽车正积分； （四）购买新能源汽车正积分。 前款所列的抵偿方式，可以组合使用。 新能源汽车正积分可以抵扣同等数量的平均燃料消耗量负积分。"},{"i":27,"n":"第二十七条","txt":"乘用车企业的新能源汽车负积分，应当通过新能源汽车正积分抵偿归零。"},{"i":28,"n":"第二十八条","txt":"乘用车企业2019年度产生的新能源汽车负积分，可以使用2020年度产生的新能源汽车正积分进行抵偿。 工业和信息化部可以根据汽车行业发展情况，决定乘用车企业使用2021年度产生的新能源汽车正积分对2020年度产生的新能源汽车负积分进行抵偿。"},{"i":29,"n":"第二十九条","txt":"乘用车企业购买的新能源汽车正积分，仅限其在当年度使用，不得再次交易。"},{"i":30,"n":"第三十条","txt":"乘用车企业发生分立、合并等情形，影响积分结转、转让、交易、抵偿等的，应当及时向工业和信息化部办理变更手续。"},{"i":31,"n":"第三十一条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局建立乘用车企业平均燃料消耗量与新能源汽车积分信用管理制度。 乘用车企业提交平均燃料消耗量与新能源汽车积分执行情况年度报告时，应当同时向工业和信息化部提交信用承诺书（见附件5），由工业和信息化部向社会公示其信用承诺书。企业法定代表人未发生变动的，信用承诺书无需逐年提交。 乘用车企业不履行承诺的，工业和信息化部将其作为失信乘用车企业进行通报，并录入车辆生产企业信用信息管理平台。"},{"i":32,"n":"第三十二条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局对乘用车企业平均燃料消耗量与新能源汽车积分进行核查。 工业和信息化部负责对境内乘用车生产企业及其乘用车燃料消耗量、新能源乘用车参数、乘用车生产量等进行核查。 商务部负责对进口乘用车供应企业有关情况进行核查。 海关总署负责对乘用车进口量进行核查。 市场监管总局负责对获得强制性产品认证的进口新能源乘用车参数、进口乘用车燃料消耗量等进行核查。"},{"i":33,"n":"第三十三条","txt":"对违反本办法的行为，任何单位和个人都有权向工业和信息化部举报。接到举报后，工业和信息化部会同有关部门及时依法调查处理，并为举报人保密。"},{"i":34,"n":"第三十四条","txt":"乘用车企业有下列情形之一的，工业和信息化部等部门按照职责给予通报，并按照核查值核算平均燃料消耗量与新能源汽车积分；情节严重的，作为失信乘用车企业进行通报，并录入车辆生产企业信用信息管理平台： （一）未按照本办法的规定报送乘用车燃料消耗量和新能源乘用车相关数据的； （二）报送的乘用车燃料消耗量数据、新能源乘用车数据与核查结果不符的； （三）报送的乘用车生产量、进口量数据与实际数量不符的； （四）未按照本办法的规定提交企业平均燃料消耗量与新能源汽车积分报告，或者报告的内容与事实不符的。"},{"i":35,"n":"第三十五条","txt":"乘用车企业平均燃料消耗量负积分、新能源汽车负积分未按照本办法抵偿归零的，应当向工业和信息化部提交其本年度乘用车生产或者进口调整计划，使本年度预期产生的正积分能够抵偿其尚未抵偿的负积分。"},{"i":36,"n":"第三十六条","txt":"乘用车企业平均燃料消耗量与新能源汽车积分管理要求，纳入乘用车生产企业及产品准入条件。乘用车企业有下列情形之一的，在其负积分抵偿归零前，对其燃料消耗量达不到《乘用车燃料消耗量评价方法及指标》车型燃料消耗量目标值的新产品，不予列入《道路机动车辆生产企业及产品公告》或者不予核发强制性产品认证证书，并可以依照《汽车产业发展政策》《强制性产品认证管理规定》等有关规定处罚： （一）平均燃料消耗量负积分未按照本办法抵偿归零的； （二）新能源汽车负积分未按照本办法抵偿归零的； （三）未按照本办法第三十五条的规定提交年度乘用车生产或者进口调整计划，或者提交生产或者进口调整计划但本年度平均燃料消耗量积分、新能源汽车积分未满足要求的。"},{"i":37,"n":"第三十七条","txt":"本办法所称核算年度是指每年1月1日至12月31日。境内生产的乘用车以机动车整车出厂合格证上记载的制造日期为准确定相应的年度；进口乘用车以获得强制性产品认证车辆的随车检验单的签发日期为准确定相应的年度。 工业和信息化部收到乘用车企业依据本办法规定提交的材料后，转送其他相关部门。"},{"i":38,"n":"第三十八条","txt":"本办法涉及的标准修订的，按照修订后的文本执行。 本办法中的“以上”“以下”“不超过”均含本数，“不满”不含本数。"},{"i":39,"n":"第三十九条","txt":"工业和信息化部会同有关部门依据国家有关规定，完善乘用车企业平均燃料消耗量与新能源汽车积分管理的经济措施。 根据我国国情和汽车产业发展的需要，适时调整本办法有关制度、附件，并重新公布。"},{"i":40,"n":"第四十条","txt":"本办法自2018年4月1日起施行。2013年3月14日公布的《乘用车企业平均燃料消耗量核算办法》（工业和信息化部2013年15号公告）、2014年10月14日公布的《关于加强乘用车企业平均燃料消耗量管理的通知》（工信部联装〔2014〕432号）同时废止。本办法施行前制定的规定与本办法不一致的，按照本办法执行。 附件1 乘用车燃料消耗量与新能源乘用车数据报送要求 工业和信息化部建立汽车燃料消耗量与新能源汽车积分管理平台。企业应当按照要求及时通过该平台报送生产或者进口的乘用车燃料消耗量和新能源乘用车相关数据。 一、报送范围 本办法中规定的，在中华人民共和国境内生产或者进口并用于境内销售的、最大设计总质量不超过3500千克的乘用车，包括能够燃用汽油、柴油或者气体燃料的传统能源乘用车（含非插电式混合动力乘用车），以及纯电动、插电式混合动力（含增程式）、燃料电池等新能源乘用车。 二、报送要求 （"}],"chengyongcheqiyepingjunranliaoxiaohaoliangyuxinnen28ff2a":[{"i":1,"n":"第一条","txt":"为了提升乘用车节能水平，缓解能源和环境压力，建立节能与新能源汽车管理长效机制，促进汽车产业健康发展，根据《中华人民共和国节约能源法》等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的乘用车企业平均燃料消耗量与新能源汽车积分管理，适用本办法。"},{"i":3,"n":"第三条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局实施乘用车企业平均燃料消耗量与新能源汽车积分管理。"},{"i":4,"n":"第四条","txt":"本办法所称乘用车，是指《汽车和挂车类型的术语和定义》（GB/T 3730.1–2001）第2.1.1.1款至第2.1.1.10款规定的、最大设计总质量不超过3500千克的车辆，包括新能源乘用车和传统能源乘用车。 本办法所称新能源乘用车，是指采用新型动力系统，完全或者主要依靠新型能源驱动的乘用车，包括插电式混合动力（含增程式）乘用车、纯电动乘用车和燃料电池乘用车等。 本办法所称传统能源乘用车，是指除新能源乘用车以外的，能够燃用汽油、柴油、气体燃料或者醇醚燃料等的乘用车（含非插电式混合动力乘用车）。 本办法所称低油耗乘用车，是指综合燃料消耗量不超过《乘用车燃料消耗量评价方法及指标》（GB 27999）中对应的车型燃料消耗量目标值与该核算年度的企业平均燃料消耗量要求之积（计算结果按四舍五入原则保留两位小数）的传统能源乘用车。"},{"i":5,"n":"第五条","txt":"乘用车企业包括中华人民共和国境内乘用车生产企业、进口乘用车供应企业。 本办法所称境内乘用车生产企业，是指取得工业和信息化部乘用车生产企业准入并获得强制性产品认证的乘用车企业。 本办法所称进口乘用车供应企业，是指从中华人民共和国境外进口并在境内销售获得强制性产品认证的乘用车的企业，包括获境外乘用车生产企业授权的进口乘用车供应企业和未获授权的进口乘用车供应企业。"},{"i":6,"n":"第六条","txt":"工业和信息化部建立汽车燃料消耗量与新能源汽车积分管理平台，统筹推进企业平均燃料消耗量与新能源汽车积分公示、转让、交易等工作。 乘用车企业应当按照工业和信息化部的要求（见附件1），报送其生产、进口的乘用车燃料消耗量和新能源乘用车相关数据；通过汽车燃料消耗量与新能源汽车积分管理平台，开展积分转让或者交易。"},{"i":7,"n":"第七条","txt":"境内各乘用车生产企业和各进口乘用车供应企业，是乘用车企业平均燃料消耗量积分的核算主体，单独实施核算。"},{"i":8,"n":"第八条","txt":"乘用车企业平均燃料消耗量积分，为该企业平均燃料消耗量的达标值和实际值之间的差额，与其乘用车生产量或者进口量的乘积（计算结果按四舍五入原则保留整数）。 实际值低于达标值产生正积分，高于达标值产生负积分。"},{"i":9,"n":"第九条","txt":"乘用车企业平均燃料消耗量达标值，是指该企业平均燃料消耗量目标值与该核算年度的企业平均燃料消耗量要求的乘积（计算结果按四舍五入原则保留两位小数）。 乘用车企业平均燃料消耗量目标值，按照《乘用车燃料消耗量评价方法及指标》第5.2款计算（计算结果按四舍五入原则保留两位小数）。同一车型在核算年度有多个不同的燃料消耗量目标值的，按照不同的目标值分开计算。 核算年度的企业平均燃料消耗量要求，是指《乘用车燃料消耗量评价方法及指标》第5.3款规定的相关比值。"},{"i":10,"n":"第十条","txt":"乘用车企业平均燃料消耗量实际值，按照《乘用车燃料消耗量评价方法及指标》第5.1款计算（计算结果按四舍五入原则保留两位小数）。同一车型在核算年度有多个不同的燃料消耗量的，按照不同的燃料消耗量分开计算。"},{"i":11,"n":"第十一条","txt":"境内乘用车生产企业的乘用车生产量，按照该企业在核算年度内生产的、用于境内销售的乘用车实际产量核算。 进口乘用车供应企业的乘用车进口量，按照该企业在核算年度进口用于境内销售的、获得强制性产品认证并经出入境检验检疫机构检验的乘用车数量核算。"},{"i":12,"n":"第十二条","txt":"对核算年度生产量2000辆以下并且生产、研发和运营保持独立的境内乘用车生产企业，进口量2000辆以下的获境外乘用车生产企业授权的进口乘用车供应企业，放宽其企业平均燃料消耗量积分的达标要求： （一）2016年度至2020年度，企业平均燃料消耗量较上一年度下降6%以上的，其达标值在《乘用车燃料消耗量评价方法及指标》规定的企业平均燃料消耗量要求基础上放宽60%；下降3%以上不满6%的，其达标值放宽30%； （二）2021年度至2023年度，企业平均燃料消耗量较上一年度下降达到4%以上的，其达标值在《乘用车燃料消耗量评价方法及指标》规定的企业平均燃料消耗量要求基础上放宽60%；下降2%以上不满4%的，其达标值放宽30%； （三）2024年度及以后年度的核算要求，由工业和信息化部另行公布。 未获境外乘用车生产企业授权的进口乘用车供应企业按照前款的规定管理，并自2019年度起实施企业平均燃料消耗量"},{"i":13,"n":"第十三条","txt":"境内各乘用车生产企业和各进口乘用车供应企业，是新能源汽车积分的核算主体，单独实施核算。"},{"i":14,"n":"第十四条","txt":"乘用车企业新能源汽车积分，为该企业新能源汽车积分实际值与达标值之间的差额。 实际值高于达标值产生正积分，低于达标值产生负积分。"},{"i":15,"n":"第十五条","txt":"乘用车企业新能源汽车积分实际值，是指该企业在核算年度内生产或者进口的新能源乘用车各车型的积分与该车型生产量或者进口量乘积之和（计算结果按四舍五入原则保留整数）。 前款规定的生产量、进口量，按照本办法第十一条规定的方法核算。 新能源乘用车车型积分按照《新能源乘用车车型积分计算方法》（见附件2）确定。"},{"i":16,"n":"第十六条","txt":"乘用车企业新能源汽车积分达标值，是指该企业在核算年度内传统能源乘用车的生产量或者进口量，与新能源汽车积分比例要求的乘积（计算结果按四舍五入原则保留整数）。 传统能源乘用车中低油耗乘用车的生产量或者进口量按照以下规定计算： （一）2021年度、2022年度、2023年度，低油耗乘用车的生产量或者进口量分别按照其数量的0.5倍、0.3倍、0.2倍计算； （二）2024年度及以后年度的低油耗乘用车生产量或者进口量计算倍数，由工业和信息化部另行公布。"},{"i":17,"n":"第十七条","txt":"对传统能源乘用车年度生产量或者进口量不满3万辆的乘用车企业，不设定新能源汽车积分比例要求；达到3万辆以上的，从2019年度开始设定新能源汽车积分比例要求。 2019年度、2020年度、2021年度、2022年度、2023年度的新能源汽车积分比例要求分别为10%、12%、14%、16%、18%。2024年度及以后年度的新能源汽车积分比例要求，由工业和信息化部另行公布。"},{"i":18,"n":"第十八条","txt":"乘用车企业应当于每年12月20日前，向工业和信息化部提交下一年度乘用车企业平均燃料消耗量与新能源汽车积分年度预报告。 预报告的内容包括本企业平均燃料消耗量预期达标值、预期实际值和新能源汽车积分预期值等（见附件3）。"},{"i":19,"n":"第十九条","txt":"乘用车企业应当于每年3月1日前，向工业和信息化部提交上一年度乘用车企业平均燃料消耗量与新能源汽车积分执行情况年度报告。 报告的内容包括本企业生产或者进口的各车型乘用车数量、关键参数、燃料消耗量、电能消耗量和对应车型的燃料消耗量目标值，以及本企业平均燃料消耗量达标值、实际值和新能源汽车积分等（见附件3）。"},{"i":20,"n":"第二十条","txt":"工业和信息化部于每年4月10日前，通过汽车燃料消耗量与新能源汽车积分管理平台，向社会公示上一年度乘用车企业平均燃料消耗量与新能源汽车积分相关情况。 对公示的乘用车企业平均燃料消耗量与新能源汽车积分相关情况有异议的，可以在30日内向工业和信息化部提出。工业和信息化部在收到异议后30日内作出答复。"},{"i":21,"n":"第二十一条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局于每年6月30日前，对乘用车企业提交的企业平均燃料消耗量与新能源汽车积分执行情况年度报告和相关数据进行核实，并发布上一年度乘用车企业平均燃料消耗量与新能源汽车积分核算情况报告。"},{"i":22,"n":"第二十二条","txt":"乘用车企业平均燃料消耗量正积分可以结转或者在关联企业间转让。 乘用车企业新能源汽车正积分可以依据本办法自由交易，并按照下列规定结转，结转有效期不超过三年： （一）2019年度的新能源汽车正积分可以等额结转一年； （二）2020年度的新能源汽车正积分，每结转一次，结转比例为50%； （三）2021年度及以后年度乘用车企业平均燃料消耗量实际值（仅核算传统能源乘用车）与达标值的比值不高于123%的，允许其当年度产生的新能源汽车正积分结转，每结转一次，结转比例为50%。只生产或者进口新能源汽车的乘用车企业产生的新能源汽车正积分按照50%的比例结转。 乘用车企业有平均燃料消耗量负积分、新能源汽车负积分的，应当在乘用车企业平均燃料消耗量与新能源汽车积分核算情况报告发布后60日内，向工业和信息化部提交其平均燃料消耗量负积分和新能源汽车负积分抵偿报告（见附件4），并在核算情况报告发布后90日内完成负积"},{"i":23,"n":"第二十三条","txt":"具有下列关系之一的乘用车企业，属于本办法第二十二条第一款规定的关联企业： （一）境内乘用车生产企业与其直接或者间接持股总和达到25%以上的其他境内乘用车生产企业； （二）同为第三方直接或者间接持股总和达到25%以上的境内乘用车生产企业； （三）获境外乘用车生产企业授权的进口乘用车供应企业，与该境外乘用车生产企业直接或者间接持股总和达到25%以上的境内乘用车生产企业，以及直接或者间接对该境外乘用车生产企业持股总和达到25%以上的境内乘用车生产企业。"},{"i":24,"n":"第二十四条","txt":"乘用车企业平均燃料消耗量正积分结转后续年度使用的，按照一定比例进行结转，结转有效期不超过三年。2018年度及以前年度的正积分，每结转一次，结转比例为80%；2019年度及以后年度的正积分，每结转一次，结转比例为90%。"},{"i":25,"n":"第二十五条","txt":"乘用车企业受让的平均燃料消耗量正积分，仅限其在当年度使用，不得再次转让。"},{"i":26,"n":"第二十六条","txt":"乘用车企业平均燃料消耗量负积分应当采取下列方式抵偿归零： （一）使用本企业结转的平均燃料消耗量正积分； （二）使用本企业受让的平均燃料消耗量正积分； （三）使用本企业产生的新能源汽车正积分； （四）购买新能源汽车正积分。 前款所列的抵偿方式，可以组合使用。 新能源汽车正积分可以抵扣同等数量的平均燃料消耗量负积分。"},{"i":27,"n":"第二十七条","txt":"乘用车企业的新能源汽车负积分，应当通过新能源汽车正积分抵偿归零。"},{"i":28,"n":"第二十八条","txt":"乘用车企业2019年度产生的新能源汽车负积分，可以使用2020年度产生的新能源汽车正积分进行抵偿。 工业和信息化部可以根据汽车行业发展情况，决定乘用车企业使用2021年度产生的新能源汽车正积分对2020年度产生的新能源汽车负积分进行抵偿。"},{"i":29,"n":"第二十九条","txt":"乘用车企业购买的新能源汽车正积分，仅限其在当年度使用，不得再次交易。"},{"i":30,"n":"第三十条","txt":"乘用车企业发生分立、合并等情形，影响积分结转、转让、交易、抵偿等的，应当及时向工业和信息化部办理变更手续。"},{"i":31,"n":"第三十一条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局建立乘用车企业平均燃料消耗量与新能源汽车积分信用管理制度。 乘用车企业提交平均燃料消耗量与新能源汽车积分执行情况年度报告时，应当同时向工业和信息化部提交信用承诺书（见附件5），由工业和信息化部向社会公示其信用承诺书。企业法定代表人未发生变动的，信用承诺书无需逐年提交。 乘用车企业不履行承诺的，工业和信息化部将其作为失信乘用车企业进行通报，并录入车辆生产企业信用信息管理平台。"},{"i":32,"n":"第三十二条","txt":"工业和信息化部会同财政部、商务部、海关总署、市场监管总局对乘用车企业平均燃料消耗量与新能源汽车积分进行核查。 工业和信息化部负责对境内乘用车生产企业及其乘用车燃料消耗量、新能源乘用车参数、乘用车生产量等进行核查。 商务部负责对进口乘用车供应企业有关情况进行核查。 海关总署负责对乘用车进口量进行核查。 市场监管总局负责对获得强制性产品认证的进口新能源乘用车参数、进口乘用车燃料消耗量等进行核查。"},{"i":33,"n":"第三十三条","txt":"对违反本办法的行为，任何单位和个人都有权向工业和信息化部举报。接到举报后，工业和信息化部会同有关部门及时依法调查处理，并为举报人保密。"},{"i":34,"n":"第三十四条","txt":"乘用车企业有下列情形之一的，工业和信息化部等部门按照职责给予通报，并按照核查值核算平均燃料消耗量与新能源汽车积分；情节严重的，作为失信乘用车企业进行通报，并录入车辆生产企业信用信息管理平台： （一）未按照本办法的规定报送乘用车燃料消耗量和新能源乘用车相关数据的； （二）报送的乘用车燃料消耗量数据、新能源乘用车数据与核查结果不符的； （三）报送的乘用车生产量、进口量数据与实际数量不符的； （四）未按照本办法的规定提交企业平均燃料消耗量与新能源汽车积分报告，或者报告的内容与事实不符的。"},{"i":35,"n":"第三十五条","txt":"乘用车企业平均燃料消耗量负积分、新能源汽车负积分未按照本办法抵偿归零的，应当向工业和信息化部提交其本年度乘用车生产或者进口调整计划，使本年度预期产生的正积分能够抵偿其尚未抵偿的负积分。"},{"i":36,"n":"第三十六条","txt":"乘用车企业平均燃料消耗量与新能源汽车积分管理要求，纳入乘用车生产企业及产品准入条件。乘用车企业有下列情形之一的，在其负积分抵偿归零前，对其燃料消耗量达不到《乘用车燃料消耗量评价方法及指标》车型燃料消耗量目标值的新产品，不予列入《道路机动车辆生产企业及产品公告》或者不予核发强制性产品认证证书，并可以依照《汽车产业发展政策》《强制性产品认证管理规定》等有关规定处罚： （一）平均燃料消耗量负积分未按照本办法抵偿归零的； （二）新能源汽车负积分未按照本办法抵偿归零的； （三）未按照本办法第三十五条的规定提交年度乘用车生产或者进口调整计划，或者提交生产或者进口调整计划但本年度平均燃料消耗量积分、新能源汽车积分未满足要求的。"},{"i":37,"n":"第三十七条","txt":"本办法所称核算年度是指每年1月1日至12月31日。境内生产的乘用车以机动车整车出厂合格证上记载的制造日期为准确定相应的年度；进口乘用车以获得强制性产品认证车辆的随车检验单的签发日期为准确定相应的年度。 工业和信息化部收到乘用车企业依据本办法规定提交的材料后，转送其他相关部门。"},{"i":38,"n":"第三十八条","txt":"本办法涉及的标准修订的，按照修订后的文本执行。 本办法中的“以上”“以下”“不超过”均含本数，“不满”不含本数。"},{"i":39,"n":"第三十九条","txt":"工业和信息化部会同有关部门依据国家有关规定，完善乘用车企业平均燃料消耗量与新能源汽车积分管理的经济措施。 根据我国国情和汽车产业发展的需要，适时调整本办法有关制度、附件，并重新公布。"},{"i":40,"n":"第四十条","txt":"本办法自2018年4月1日起施行。2013年3月14日公布的《乘用车企业平均燃料消耗量核算办法》（工业和信息化部2013年15号公告）、2014年10月14日公布的《关于加强乘用车企业平均燃料消耗量管理的通知》（工信部联装〔2014〕432号）同时废止。本办法施行前制定的规定与本办法不一致的，按照本办法执行。 附件： 1.乘用车燃料消耗量与新能源乘用车数据报送要求.doc 2.新能源乘用车车型积分计算方法 3.乘用车企业平均燃料消耗量与新能源汽车积分报告 4.乘用车企业平均燃料消耗量负积分和新能源汽车负积分抵偿报告 5.信用承诺书"}],"hulianwangipdizhibeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对互联网IP地址资源使用的管理，保障互联网络的安全，维护广大互联网用户的根本利益，促进互联网业的健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内直接从亚太互联网信息中心等具有IP地址管理权的国际机构获得IP地址的单位和具有分配IP地址供其他单位或者个人使用的单位，适用本办法。"},{"i":3,"n":"第三条","txt":"直接从亚太互联网信息中心等具有IP地址管理权的国际机构获得IP地址自用或分配给其他用户使用的单位统称为第一级IP地址分配机构。 直接从第一级IP地址分配机构获得IP地址除自用外还分配给本单位互联网用户以外的其他用户使用的单位为第二级IP地址分配机构（以下各级IP地址分配机构的级别依此类推）。"},{"i":4,"n":"第四条","txt":"国家对IP地址的分配使用实行备案管理。"},{"i":5,"n":"第五条","txt":"中华人民共和国信息产业部（以下简称“信息产业部”）对基础电信业务经营者、公益性互联网络单位和中国互联网络信息中心的IP地址备案实施监督管理。 各省、自治区、直辖市通信管理局（以下简称“省通信管理局”）对本行政区域内其他各级IP地址分配机构的IP地址备案活动实施监督管理。"},{"i":6,"n":"第六条","txt":"信息产业部统一建设并管理全国的互联网IP地址数据库，制定和调整IP地址分配机构需报备的IP地址信息；各省通信管理局通过使用全国互联网IP地址数据库管理本行政区域内各级IP地址分配机构报备的IP地址信息。"},{"i":7,"n":"第七条","txt":"各级IP地址分配机构应当通过信息产业部指定的网站，按照IP地址备案的要求以电子形式报备IP地址信息。"},{"i":8,"n":"第八条","txt":"各级IP地址分配机构在进行IP地址备案时，应当如实、完整地报备IP地址信息（需报备的IP地址信息参见本办法附录）。"},{"i":9,"n":"第九条","txt":"各级IP地址分配机构应自取得IP地址之日起二十个工作日内完成IP地址信息的第一次报备。"},{"i":10,"n":"第十条","txt":"各级IP地址分配机构申请和分配使用的IP地址信息发生变化的，IP地址分配机构应自变化之日起五个工作日内通过信息产业部指定的网站，按照IP地址备案的要求以电子形式提交变更后的IP地址信息。 各级IP地址分配机构的联系人或联系方式发生变更的，应自变更之日起十个工作日内报备变更后的信息。"},{"i":11,"n":"第十一条","txt":"基础电信业务经营者IP地址信息的报备，由各基础电信业务经营者集团公司（总公司）和基础电信业务经营者的省级公司（省级分支机构）共同完成。 各基础电信业务经营者集团公司（总公司）按照本办法的规定完成由其申请、使用和分配到省级公司（省级分支机构）的IP地址信息的报备。各基础电信业务经营者的省级公司（省级分支机构）按照本办法的规定统一完成该省级公司（省级分支机构）及其所属公司（分支机构）申请、使用和分配的IP地址信息的报备。"},{"i":12,"n":"第十二条","txt":"中国教育和科研计算机网、中国科学技术网、中国国际经济贸易互联网、中国长城互联网等公益性互联网的网络管理单位应当按照本办法的规定，统一完成其申请、使用和分配的IP地址信息的报备。"},{"i":13,"n":"第十三条","txt":"IP地址分配机构同时是互联网接入服务提供者的，应当如实记录和保存由其提供接入服务的使用自带IP地址的用户的IP地址信息，并自提供接入服务之日起五日内，填报IP地址备案信息，进行备案。"},{"i":14,"n":"第十四条","txt":"各级IP地址分配机构应当建立健全本单位的IP地址管理制度。"},{"i":15,"n":"第十五条","txt":"各级IP地址分配机构分配IP地址时，应当通知其下一级IP地址分配机构报备IP地址信息。"},{"i":16,"n":"第十六条","txt":"信息产业部和省通信管理局及其工作人员对IP地址分配机构报备的IP地址信息，有保密的义务。 信息产业部和省通信管理局及其工作人员不得向他人提供IP地址分配机构报备的IP地址信息，但法律、行政法规另有规定的除外。"},{"i":17,"n":"第十七条","txt":"违反本办法第八条、第九条、第十条、第十三条的规定的，由信息产业部或者省通信管理局依据职权责令限期改正；逾期不改的，给予警告或者处人民币一万元罚款，或者同时处以上两种处罚。"},{"i":18,"n":"第十八条","txt":"违反本办法第十四条规定，未建立IP地址管理制度的，由信息产业部或者省通信管理局依据职权责令限期改正；逾期不改的，给予警告或者处人民币五千元以上一万元以下罚款，或者同时处以上两种处罚。"},{"i":19,"n":"第十九条","txt":"本办法实施前直接从亚太互联网信息中心等具有IP地址管理权的国际机构获得IP地址供本单位使用或者分配IP地址供其他单位或个人使用的，应自本办法施行之日起四十五个工作日内，按照本办法的规定完成备案手续。"},{"i":20,"n":"第二十条","txt":"本办法自2005年3月20日起实施。 附 录： 需报备的IP地址信息 一、备案单位基本情况，包括备案单位名称、备案单位地址、备案单位性质、电信业务经营许可证编号、联系人姓名、联系人电话、联系人电子邮件等。 二、备案单位的IP地址来源信息，包括IP地址来源机构名称、IP地址总量、各IP地址段起止地址码等。 三、备案单位的IP地址分配使用信息，包括： （一）本单位自用的IP地址信息，包括IP地址总量、各IP地址段起止IP地址码、IP地址使用方式、网关IP地址、网关所在地址； （二）尚未分配的IP地址信息，包括IP地址总量、各IP地址段起止地址码； （三）向其他用户分配的IP地址信息，包括所分配的用户基本信息（包括用户名称、单位类别、单位所属行业、单位详细地址、联系人姓名、联系人电话、联系人电子邮件）、所分配的IP地址总量、各IP地址段起止地址码、网关IP地址、网关所在地址、IP地址使用方式"}],"hulianwangxinxifuwushenduhechengguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强互联网信息服务深度合成管理，弘扬社会主义核心价值观，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内应用深度合成技术提供互联网信息服务（以下简称深度合成服务），适用本规定。法律、行政法规另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"国家网信部门负责统筹协调全国深度合成服务的治理和相关监督管理工作。国务院电信主管部门、公安部门依据各自职责负责深度合成服务的监督管理工作。 地方网信部门负责统筹协调本行政区域内的深度合成服务的治理和相关监督管理工作。地方电信主管部门、公安部门依据各自职责负责本行政区域内的深度合成服务的监督管理工作。"},{"i":4,"n":"第四条","txt":"提供深度合成服务，应当遵守法律法规，尊重社会公德和伦理道德，坚持正确政治方向、舆论导向、价值取向，促进深度合成服务向上向善。"},{"i":5,"n":"第五条","txt":"鼓励相关行业组织加强行业自律，建立健全行业标准、行业准则和自律管理制度，督促指导深度合成服务提供者和技术支持者制定完善业务规范、依法开展业务和接受社会监督。"},{"i":6,"n":"第六条","txt":"任何组织和个人不得利用深度合成服务制作、复制、发布、传播法律、行政法规禁止的信息，不得利用深度合成服务从事危害国家安全和利益、损害国家形象、侵害社会公共利益、扰乱经济和社会秩序、侵犯他人合法权益等法律、行政法规禁止的活动。 深度合成服务提供者和使用者不得利用深度合成服务制作、复制、发布、传播虚假新闻信息。转载基于深度合成服务制作发布的新闻信息的，应当依法转载互联网新闻信息稿源单位发布的新闻信息。"},{"i":7,"n":"第七条","txt":"深度合成服务提供者应当落实信息安全主体责任，建立健全用户注册、算法机制机理审核、科技伦理审查、信息发布审核、数据安全、个人信息保护、反电信网络诈骗、应急处置等管理制度，具有安全可控的技术保障措施。"},{"i":8,"n":"第八条","txt":"深度合成服务提供者应当制定和公开管理规则、平台公约，完善服务协议，依法依约履行管理责任，以显著方式提示深度合成服务技术支持者和使用者承担信息安全义务。"},{"i":9,"n":"第九条","txt":"深度合成服务提供者应当基于移动电话号码、身份证件号码、统一社会信用代码或者国家网络身份认证公共服务等方式，依法对深度合成服务使用者进行真实身份信息认证，不得向未进行真实身份信息认证的深度合成服务使用者提供信息发布服务。"},{"i":10,"n":"第十条","txt":"深度合成服务提供者应当加强深度合成内容管理，采取技术或者人工方式对深度合成服务使用者的输入数据和合成结果进行审核。 深度合成服务提供者应当建立健全用于识别违法和不良信息的特征库，完善入库标准、规则和程序，记录并留存相关网络日志。 深度合成服务提供者发现违法和不良信息的，应当依法采取处置措施，保存有关记录，及时向网信部门和有关主管部门报告；对相关深度合成服务使用者依法依约采取警示、限制功能、暂停服务、关闭账号等处置措施。"},{"i":11,"n":"第十一条","txt":"深度合成服务提供者应当建立健全辟谣机制，发现利用深度合成服务制作、复制、发布、传播虚假信息的，应当及时采取辟谣措施，保存有关记录，并向网信部门和有关主管部门报告。"},{"i":12,"n":"第十二条","txt":"深度合成服务提供者应当设置便捷的用户申诉和公众投诉、举报入口，公布处理流程和反馈时限，及时受理、处理和反馈处理结果。"},{"i":13,"n":"第十三条","txt":"互联网应用商店等应用程序分发平台应当落实上架审核、日常管理、应急处置等安全管理责任，核验深度合成类应用程序的安全评估、备案等情况；对违反国家有关规定的，应当及时采取不予上架、警示、暂停服务或者下架等处置措施。"},{"i":14,"n":"第十四条","txt":"深度合成服务提供者和技术支持者应当加强训练数据管理，采取必要措施保障训练数据安全；训练数据包含个人信息的，应当遵守个人信息保护的有关规定。 深度合成服务提供者和技术支持者提供人脸、人声等生物识别信息编辑功能的，应当提示深度合成服务使用者依法告知被编辑的个人，并取得其单独同意。"},{"i":15,"n":"第十五条","txt":"深度合成服务提供者和技术支持者应当加强技术管理，定期审核、评估、验证生成合成类算法机制机理。 深度合成服务提供者和技术支持者提供具有以下功能的模型、模板等工具的，应当依法自行或者委托专业机构开展安全评估： （一）生成或者编辑人脸、人声等生物识别信息的； （二）生成或者编辑可能涉及国家安全、国家形象、国家利益和社会公共利益的特殊物体、场景等非生物识别信息的。"},{"i":16,"n":"第十六条","txt":"深度合成服务提供者对使用其服务生成或者编辑的信息内容，应当采取技术措施添加不影响用户使用的标识，并依照法律、行政法规和国家有关规定保存日志信息。"},{"i":17,"n":"第十七条","txt":"深度合成服务提供者提供以下深度合成服务，可能导致公众混淆或者误认的，应当在生成或者编辑的信息内容的合理位置、区域进行显著标识，向公众提示深度合成情况： （一）智能对话、智能写作等模拟自然人进行文本的生成或者编辑服务； （二）合成人声、仿声等语音生成或者显著改变个人身份特征的编辑服务； （三）人脸生成、人脸替换、人脸操控、姿态操控等人物图像、视频生成或者显著改变个人身份特征的编辑服务； （四）沉浸式拟真场景等生成或者编辑服务； （五）其他具有生成或者显著改变信息内容功能的服务。 深度合成服务提供者提供前款规定之外的深度合成服务的，应当提供显著标识功能，并提示深度合成服务使用者可以进行显著标识。"},{"i":18,"n":"第十八条","txt":"任何组织和个人不得采用技术手段删除、篡改、隐匿本规定第十六条和第十七条规定的深度合成标识。"},{"i":19,"n":"第十九条","txt":"具有舆论属性或者社会动员能力的深度合成服务提供者，应当按照《互联网信息服务算法推荐管理规定》履行备案和变更、注销备案手续。 深度合成服务技术支持者应当参照前款规定履行备案和变更、注销备案手续。 完成备案的深度合成服务提供者和技术支持者应当在其对外提供服务的网站、应用程序等的显著位置标明其备案编号并提供公示信息链接。"},{"i":20,"n":"第二十条","txt":"深度合成服务提供者开发上线具有舆论属性或者社会动员能力的新产品、新应用、新功能的，应当按照国家有关规定开展安全评估。"},{"i":21,"n":"第二十一条","txt":"网信部门和电信主管部门、公安部门依据职责对深度合成服务开展监督检查。深度合成服务提供者和技术支持者应当依法予以配合，并提供必要的技术、数据等支持和协助。 网信部门和有关主管部门发现深度合成服务存在较大信息安全风险的，可以按照职责依法要求深度合成服务提供者和技术支持者采取暂停信息更新、用户账号注册或者其他相关服务等措施。深度合成服务提供者和技术支持者应当按照要求采取措施，进行整改，消除隐患。"},{"i":22,"n":"第二十二条","txt":"深度合成服务提供者和技术支持者违反本规定的，依照有关法律、行政法规的规定处罚；造成严重后果的，依法从重处罚。 构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本规定中下列用语的含义： 深度合成技术，是指利用深度学习、虚拟现实等生成合成类算法制作文本、图像、音频、视频、虚拟场景等网络信息的技术，包括但不限于： （一）篇章生成、文本风格转换、问答对话等生成或者编辑文本内容的技术； （二）文本转语音、语音转换、语音属性编辑等生成或者编辑语音内容的技术； （三）音乐生成、场景声编辑等生成或者编辑非语音内容的技术； （四）人脸生成、人脸替换、人物属性编辑、人脸操控、姿态操控等生成或者编辑图像、视频内容中生物特征的技术； （五）图像生成、图像增强、图像修复等生成或者编辑图像、视频内容中非生物特征的技术； （六）三维重建、数字仿真等生成或者编辑数字人物、虚拟场景的技术。 深度合成服务提供者，是指提供深度合成服务的组织、个人。 深度合成服务技术支持者，是指为深度合成服务提供技术支持的组织、个人。 深度合成服务使用者，是指使用深度合成服务制作、复制、发布、传"},{"i":24,"n":"第二十四条","txt":"深度合成服务提供者和技术支持者从事网络出版服务、网络文化活动和网络视听节目服务的，应当同时符合新闻出版、文化和旅游、广播电视主管部门的规定。"},{"i":25,"n":"第二十五条","txt":"本规定自2023年1月10日起施行。"}],"hulianwangyumingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范互联网域名服务，保护用户合法权益，保障互联网域名系统安全、可靠运行，推动中文域名和国家顶级域名发展和应用，促进中国互联网健康发展，根据《中华人民共和国行政许可法》《国务院对确需保留的行政审批项目设定行政许可的决定》等规定，参照国际上互联网域名管理准则，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事互联网域名服务及其运行维护、监督管理等相关活动，应当遵守本办法。 本办法所称互联网域名服务（以下简称域名服务），是指从事域名根服务器运行和管理、顶级域名运行和管理、域名注册、域名解析等活动。"},{"i":3,"n":"第三条","txt":"工业和信息化部对全国的域名服务实施监督管理，主要职责是： （一）制定互联网域名管理规章及政策； （二）制定中国互联网域名体系、域名资源发展规划； （三）管理境内的域名根服务器运行机构和域名注册管理机构； （四）负责域名体系的网络与信息安全管理； （五）依法保护用户个人信息和合法权益； （六）负责与域名有关的国际协调； （七）管理境内的域名解析服务； （八）管理其他与域名服务相关的活动。"},{"i":4,"n":"第四条","txt":"各省、自治区、直辖市通信管理局对本行政区域内的域名服务实施监督管理，主要职责是： （一）贯彻执行域名管理法律、行政法规、规章和政策； （二）管理本行政区域内的域名注册服务机构； （三）协助工业和信息化部对本行政区域内的域名根服务器运行机构和域名注册管理机构进行管理； （四）负责本行政区域内域名系统的网络与信息安全管理； （五）依法保护用户个人信息和合法权益； （六）管理本行政区域内的域名解析服务； （七）管理本行政区域内其他与域名服务相关的活动。"},{"i":5,"n":"第五条","txt":"中国互联网域名体系由工业和信息化部予以公告。根据域名发展的实际情况，工业和信息化部可以对中国互联网域名体系进行调整。"},{"i":6,"n":"第六条","txt":"“.CN”和“.中国”是中国的国家顶级域名。 中文域名是中国互联网域名体系的重要组成部分。国家鼓励和支持中文域名系统的技术研究和推广应用。"},{"i":7,"n":"第七条","txt":"提供域名服务，应当遵守国家相关法律法规，符合相关技术规范和标准。"},{"i":8,"n":"第八条","txt":"任何组织和个人不得妨碍互联网域名系统的安全和稳定运行。"},{"i":9,"n":"第九条","txt":"在境内设立域名根服务器及域名根服务器运行机构、域名注册管理机构和域名注册服务机构的，应当依据本办法取得工业和信息化部或者省、自治区、直辖市通信管理局（以下统称电信管理机构）的相应许可。"},{"i":10,"n":"第十条","txt":"申请设立域名根服务器及域名根服务器运行机构的，应当具备以下条件： （一）域名根服务器设置在境内，并且符合互联网发展相关规划及域名系统安全稳定运行要求； （二）是依法设立的法人，该法人及其主要出资者、主要经营管理人员具有良好的信用记录； （三）具有保障域名根服务器安全可靠运行的场地、资金、环境、专业人员和技术能力以及符合电信管理机构要求的信息管理系统； （四）具有健全的网络与信息安全保障措施，包括管理人员、网络与信息安全管理制度、应急处置预案和相关技术、管理措施等； （五）具有用户个人信息保护能力、提供长期服务的能力及健全的服务退出机制； （六）法律、行政法规规定的其他条件。"},{"i":11,"n":"第十一条","txt":"申请设立域名注册管理机构的，应当具备以下条件： （一）域名管理系统设置在境内，并且持有的顶级域名符合相关法律法规及域名系统安全稳定运行要求； （二）是依法设立的法人，该法人及其主要出资者、主要经营管理人员具有良好的信用记录； （三）具有完善的业务发展计划和技术方案以及与从事顶级域名运行管理相适应的场地、资金、专业人员以及符合电信管理机构要求的信息管理系统； （四）具有健全的网络与信息安全保障措施，包括管理人员、网络与信息安全管理制度、应急处置预案和相关技术、管理措施等； （五）具有进行真实身份信息核验和用户个人信息保护的能力、提供长期服务的能力及健全的服务退出机制； （六）具有健全的域名注册服务管理制度和对域名注册服务机构的监督机制； （七）法律、行政法规规定的其他条件。"},{"i":12,"n":"第十二条","txt":"申请设立域名注册服务机构的，应当具备以下条件： （一）在境内设置域名注册服务系统、注册数据库和相应的域名解析系统； （二）是依法设立的法人，该法人及其主要出资者、主要经营管理人员具有良好的信用记录； （三）具有与从事域名注册服务相适应的场地、资金和专业人员以及符合电信管理机构要求的信息管理系统； （四）具有进行真实身份信息核验和用户个人信息保护的能力、提供长期服务的能力及健全的服务退出机制； （五）具有健全的域名注册服务管理制度和对域名注册代理机构的监督机制； （六）具有健全的网络与信息安全保障措施，包括管理人员、网络与信息安全管理制度、应急处置预案和相关技术、管理措施等； （七）法律、行政法规规定的其他条件。"},{"i":13,"n":"第十三条","txt":"申请设立域名根服务器及域名根服务器运行机构、域名注册管理机构的，应当向工业和信息化部提交申请材料。申请设立域名注册服务机构的，应当向住所地省、自治区、直辖市通信管理局提交申请材料。 申请材料应当包括： （一）申请单位的基本情况及其法定代表人签署的依法诚信经营承诺书； （二）对域名服务实施有效管理的证明材料，包括相关系统及场所、服务能力的证明材料、管理制度、与其他机构签订的协议等； （三）网络与信息安全保障制度及措施； （四）证明申请单位信誉的材料。"},{"i":14,"n":"第十四条","txt":"申请材料齐全、符合法定形式的，电信管理机构应当向申请单位出具受理申请通知书；申请材料不齐全或者不符合法定形式的，电信管理机构应当场或者在5个工作日内一次性书面告知申请单位需要补正的全部内容；不予受理的，应当出具不予受理通知书并说明理由。"},{"i":15,"n":"第十五条","txt":"电信管理机构应当自受理之日起20个工作日内完成审查，作出予以许可或者不予许可的决定。20个工作日内不能作出决定的，经电信管理机构负责人批准，可以延长10个工作日，并将延长期限的理由告知申请单位。需要组织专家论证的，论证时间不计入审查期限。 予以许可的，应当颁发相应的许可文件；不予许可的，应当书面通知申请单位并说明理由。"},{"i":16,"n":"第十六条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构的许可有效期为5年。"},{"i":17,"n":"第十七条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构的名称、住所、法定代表人等信息发生变更的，应当自变更之日起20日内向原发证机关办理变更手续。"},{"i":18,"n":"第十八条","txt":"在许可有效期内，域名根服务器运行机构、域名注册管理机构、域名注册服务机构拟终止相关服务的，应当提前30日书面通知用户，提出可行的善后处理方案，并向原发证机关提交书面申请。 原发证机关收到申请后，应当向社会公示30日。公示期结束60日内，原发证机关应当完成审查并做出决定。"},{"i":19,"n":"第十九条","txt":"许可有效期届满需要继续从事域名服务的，应当提前90日向原发证机关申请延续；不再继续从事域名服务的，应当提前90日向原发证机关报告并做好善后工作。"},{"i":20,"n":"第二十条","txt":"域名注册服务机构委托域名注册代理机构开展市场销售等工作的，应当对域名注册代理机构的工作进行监督和管理。 域名注册代理机构受委托开展市场销售等工作的过程中，应当主动表明代理关系，并在域名注册服务合同中明示相关域名注册服务机构名称及代理关系。"},{"i":21,"n":"第二十一条","txt":"域名注册管理机构、域名注册服务机构应当在境内设立相应的应急备份系统并定期备份域名注册数据。"},{"i":22,"n":"第二十二条","txt":"域名根服务器运行机构、域名注册管理机构、域名注册服务机构应当在其网站首页和经营场所显著位置标明其许可相关信息。域名注册管理机构还应当标明与其合作的域名注册服务机构名单。 域名注册代理机构应当在其网站首页和经营场所显著位置标明其代理的域名注册服务机构名称。"},{"i":23,"n":"第二十三条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构应当向用户提供安全、方便、稳定的服务。"},{"i":24,"n":"第二十四条","txt":"域名注册管理机构应当根据本办法制定域名注册实施细则并向社会公开。"},{"i":25,"n":"第二十五条","txt":"域名注册管理机构应当通过电信管理机构许可的域名注册服务机构开展域名注册服务。 域名注册服务机构应当按照电信管理机构许可的域名注册服务项目提供服务，不得为未经电信管理机构许可的域名注册管理机构提供域名注册服务。"},{"i":26,"n":"第二十六条","txt":"域名注册服务原则上实行“先申请先注册”，相应域名注册实施细则另有规定的，从其规定。"},{"i":27,"n":"第二十七条","txt":"为维护国家利益和社会公众利益，域名注册管理机构应当建立域名注册保留字制度。"},{"i":28,"n":"第二十八条","txt":"任何组织或者个人注册、使用的域名中，不得含有下列内容： （一）反对宪法所确定的基本原则的; （二）危害国家安全，泄露国家秘密，颠覆国家政权，破坏国家统一的; （三）损害国家荣誉和利益的; （四）煽动民族仇恨、民族歧视，破坏民族团结的; （五）破坏国家宗教政策，宣扬邪教和封建迷信的; （六）散布谣言，扰乱社会秩序，破坏社会稳定的; （七）散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的; （八）侮辱或者诽谤他人，侵害他人合法权益的; （九）含有法律、行政法规禁止的其他内容的。 域名注册管理机构、域名注册服务机构不得为含有前款所列内容的域名提供服务。"},{"i":29,"n":"第二十九条","txt":"域名注册服务机构不得采用欺诈、胁迫等不正当手段要求他人注册域名。"},{"i":30,"n":"第三十条","txt":"域名注册服务机构提供域名注册服务，应当要求域名注册申请者提供域名持有者真实、准确、完整的身份信息等域名注册信息。 域名注册管理机构和域名注册服务机构应当对域名注册信息的真实性、完整性进行核验。 域名注册申请者提供的域名注册信息不准确、不完整的，域名注册服务机构应当要求其予以补正。申请者不补正或者提供不真实的域名注册信息的，域名注册服务机构不得为其提供域名注册服务。"},{"i":31,"n":"第三十一条","txt":"域名注册服务机构应当公布域名注册服务的内容、时限、费用，保证服务质量，提供域名注册信息的公共查询服务。"},{"i":32,"n":"第三十二条","txt":"域名注册管理机构、域名注册服务机构应当依法存储、保护用户个人信息。未经用户同意不得将用户个人信息提供给他人，但法律、行政法规另有规定的除外。"},{"i":33,"n":"第三十三条","txt":"域名持有者的联系方式等信息发生变更的，应当在变更后30日内向域名注册服务机构办理域名注册信息变更手续。 域名持有者将域名转让给他人的，受让人应当遵守域名注册的相关要求。"},{"i":34,"n":"第三十四条","txt":"域名持有者有权选择、变更域名注册服务机构。变更域名注册服务机构的，原域名注册服务机构应当配合域名持有者转移其域名注册相关信息。 无正当理由的，域名注册服务机构不得阻止域名持有者变更域名注册服务机构。 电信管理机构依法要求停止解析的域名，不得变更域名注册服务机构。"},{"i":35,"n":"第三十五条","txt":"域名注册管理机构和域名注册服务机构应当设立投诉受理机制，并在其网站首页和经营场所显著位置公布投诉受理方式。 域名注册管理机构和域名注册服务机构应当及时处理投诉；不能及时处理的，应当说明理由和处理时限。"},{"i":36,"n":"第三十六条","txt":"提供域名解析服务，应当遵守有关法律、法规、标准，具备相应的技术、服务和网络与信息安全保障能力，落实网络与信息安全保障措施，依法记录并留存域名解析日志、维护日志和变更记录，保障解析服务质量和解析系统安全。涉及经营电信业务的，应当依法取得电信业务经营许可。"},{"i":37,"n":"第三十七条","txt":"提供域名解析服务，不得擅自篡改解析信息。 任何组织或者个人不得恶意将域名解析指向他人的IP地址。"},{"i":38,"n":"第三十八条","txt":"提供域名解析服务，不得为含有本办法第二十八条第一款所列内容的域名提供域名跳转。"},{"i":39,"n":"第三十九条","txt":"从事互联网信息服务的，其使用域名应当符合法律法规和电信管理机构的有关规定，不得将域名用于实施违法行为。"},{"i":40,"n":"第四十条","txt":"域名注册管理机构、域名注册服务机构应当配合国家有关部门依法开展的检查工作，并按照电信管理机构的要求对存在违法行为的域名采取停止解析等处置措施。 域名注册管理机构、域名注册服务机构发现其提供服务的域名发布、传输法律和行政法规禁止发布或者传输的信息的，应当立即采取消除、停止解析等处置措施，防止信息扩散，保存有关记录，并向有关部门报告。"},{"i":41,"n":"第四十一条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构应当遵守国家相关法律、法规和标准，落实网络与信息安全保障措施，配置必要的网络通信应急设备，建立健全网络与信息安全监测技术手段和应急制度。域名系统出现网络与信息安全事件时，应当在24小时内向电信管理机构报告。 因国家安全和处置紧急事件的需要，域名根服务器运行机构、域名注册管理机构和域名注册服务机构应当服从电信管理机构的统一指挥与协调，遵守电信管理机构的管理要求。"},{"i":42,"n":"第四十二条","txt":"任何组织或者个人认为他人注册或者使用的域名侵害其合法权益的，可以向域名争议解决机构申请裁决或者依法向人民法院提起诉讼。"},{"i":43,"n":"第四十三条","txt":"已注册的域名有下列情形之一的，域名注册服务机构应当予以注销，并通知域名持有者： （一）域名持有者申请注销域名的； （二）域名持有者提交虚假域名注册信息的； （三）依据人民法院的判决、域名争议解决机构的裁决，应当注销的； （四）法律、行政法规规定予以注销的其他情形。"},{"i":44,"n":"第四十四条","txt":"电信管理机构应当加强对域名服务的监督检查。域名根服务器运行机构、域名注册管理机构、域名注册服务机构应当接受、配合电信管理机构的监督检查。 鼓励域名服务行业自律管理，鼓励公众监督域名服务。"},{"i":45,"n":"第四十五条","txt":"域名根服务器运行机构、域名注册管理机构、域名注册服务机构应当按照电信管理机构的要求，定期报送业务开展情况、安全运行情况、网络与信息安全责任落实情况、投诉和争议处理情况等信息。"},{"i":46,"n":"第四十六条","txt":"电信管理机构实施监督检查时，应当对域名根服务器运行机构、域名注册管理机构和域名注册服务机构报送的材料进行审核，并对其执行法律法规和电信管理机构有关规定的情况进行检查。 电信管理机构可以委托第三方专业机构开展有关监督检查活动。"},{"i":47,"n":"第四十七条","txt":"电信管理机构应当建立域名根服务器运行机构、域名注册管理机构和域名注册服务机构的信用记录制度，将其违反本办法并受到行政处罚的行为记入信用档案。"},{"i":48,"n":"第四十八条","txt":"电信管理机构开展监督检查，不得妨碍域名根服务器运行机构、域名注册管理机构和域名注册服务机构正常的经营和服务活动，不得收取任何费用，不得泄露所知悉的域名注册信息。"},{"i":49,"n":"第四十九条","txt":"违反本办法第九条规定，未经许可擅自设立域名根服务器及域名根服务器运行机构、域名注册管理机构、域名注册服务机构的，电信管理机构应当根据《中华人民共和国行政许可法》第八十一条的规定，采取措施予以制止，并视情节轻重，予以警告或者处一万元以上三万元以下罚款。"},{"i":50,"n":"第五十条","txt":"违反本办法规定，域名注册管理机构或者域名注册服务机构有下列行为之一的，由电信管理机构依据职权责令限期改正，并视情节轻重，处一万元以上三万元以下罚款，向社会公告: （一）为未经许可的域名注册管理机构提供域名注册服务,或者通过未经许可的域名注册服务机构开展域名注册服务的； （二）未按照许可的域名注册服务项目提供服务的； （三）未对域名注册信息的真实性、完整性进行核验的； （四）无正当理由阻止域名持有者变更域名注册服务机 构的。"},{"i":51,"n":"第五十一条","txt":"违反本办法规定，提供域名解析服务，有下列行为之一的，由电信管理机构责令限期改正，可以视情节轻重处一万元以上三万元以下罚款，向社会公告： （一）擅自篡改域名解析信息或者恶意将域名解析指向他人IP地址的； （二）为含有本办法第二十八条第一款所列内容的域名提供域名跳转的； （三）未落实网络与信息安全保障措施的； （四）未依法记录并留存域名解析日志、维护日志和变更记录的； （五）未按照要求对存在违法行为的域名进行处置的。"},{"i":52,"n":"第五十二条","txt":"违反本办法第十七条、第十八条第一款、第二十一条、第二十二条、第二十八条第二款、第二十九条、第三十一条、第三十二条、第三十五条第一款、第四十条第二款、第四十一条规定的，由电信管理机构依据职权责令限期改正,可以并处一万元以上三万元以下罚款，向社会公告。"},{"i":53,"n":"第五十三条","txt":"法律、行政法规对有关违法行为的处罚另有规定的，依照有关法律、行政法规的规定执行。"},{"i":54,"n":"第五十四条","txt":"任何组织或者个人违反本办法第二十八条第一款规定注册、使用域名，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由有关部门依法予以处罚。"},{"i":55,"n":"第五十五条","txt":"本办法下列用语的含义是： （一）域名：指互联网上识别和定位计算机的层次结构式的字符标识，与该计算机的IP地址相对应。 （二）中文域名：指含有中文文字的域名。 （三）顶级域名：指域名体系中根节点下的第一级域的名称。 （四）域名根服务器：指承担域名体系中根节点功能的服务器（含镜像服务器）。 （五）域名根服务器运行机构：指依法获得许可并承担域名根服务器运行、维护和管理工作的机构。 （六）域名注册管理机构：指依法获得许可并承担顶级域名运行和管理工作的机构。 （七）域名注册服务机构：指依法获得许可、受理域名注册申请并完成域名在顶级域名数据库中注册的机构。 （八）域名注册代理机构：指受域名注册服务机构的委托，受理域名注册申请，间接完成域名在顶级域名数据库中注册的机构。 （九）域名管理系统：指域名注册管理机构在境内开展顶级域名运行和管理所需的主要信息系统，包括注册管理系统、注册数据库、域名解析系统、"},{"i":56,"n":"第五十六条","txt":"本办法中规定的日期，除明确为工作日的以外，均为自然日。"},{"i":57,"n":"第五十七条","txt":"在本办法施行前未取得相应许可开展域名服务的，应当自本办法施行之日起十二个月内，按照本办法规定办理许可手续。 在本办法施行前已取得许可的域名根服务器运行机构、域名注册管理机构和域名注册服务机构，其许可有效期适用本办法第十六条的规定，有效期自本办法施行之日起计算。"},{"i":58,"n":"第五十八条","txt":"本办法自2017年11月1日起施行。2004年11月5日公布的《中国互联网络域名管理办法》（原信息产业部令第30号）同时废止。本办法施行前公布的有关规定与本办法不一致的，按照本办法执行。"}],"hulianwangdianziyoujianfuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范互联网电子邮件服务，保障互联网电子邮件服务使用者的合法权利，根据《中华人民共和国电信条例》和《互联网信息服务管理办法》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供互联网电子邮件服务以及为互联网电子邮件服务提供接入服务和发送互联网电子邮件，适用本办法。 本办法所称互联网电子邮件服务，是指设置互联网电子邮件服务器，为互联网用户发送、接收互联网电子邮件提供条件的行为。"},{"i":3,"n":"第三条","txt":"公民使用互联网电子邮件服务的通信秘密受法律保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信内容进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信秘密。"},{"i":4,"n":"第四条","txt":"提供互联网电子邮件服务，应当事先取得增值电信业务经营许可或者依法履行非经营性互联网信息服务备案手续。 未取得增值电信业务经营许可或者未履行非经营性互联网信息服务备案手续，任何组织或者个人不得在中华人民共和国境内开展互联网电子邮件服务。"},{"i":5,"n":"第五条","txt":"互联网接入服务提供者等电信业务提供者，不得为未取得增值电信业务经营许可或者未履行非经营性互联网信息服务备案手续的组织或者个人开展互联网电子邮件服务提供接入服务。"},{"i":6,"n":"第六条","txt":"国家对互联网电子邮件服务提供者的电子邮件服务器IP地址实行登记管理。互联网电子邮件服务提供者应当在电子邮件服务器开通前二十日将互联网电子邮件服务器所使用的IP地址向中华人民共和国信息产业部（以下简称“信息产业部”）或者省、自治区、直辖市通信管理局（以下简称“通信管理局”）登记。 互联网电子邮件服务提供者拟变更电子邮件服务器IP地址的，应当提前三十日办理变更手续。"},{"i":7,"n":"第七条","txt":"互联网电子邮件服务提供者应当按照信息产业部制定的技术标准建设互联网电子邮件服务系统，关闭电子邮件服务器匿名转发功能，并加强电子邮件服务系统的安全管理，发现网络安全漏洞后应当及时采取安全防范措施。"},{"i":8,"n":"第八条","txt":"互联网电子邮件服务提供者向用户提供服务，应当明确告知用户服务内容和使用规则。"},{"i":9,"n":"第九条","txt":"互联网电子邮件服务提供者对用户的个人注册信息和互联网电子邮件地址，负有保密的义务。 互联网电子邮件服务提供者及其工作人员不得非法使用用户的个人注册信息资料和互联网电子邮件地址；未经用户同意，不得泄露用户的个人注册信息和互联网电子邮件地址，但法律、行政法规另有规定的除外。"},{"i":10,"n":"第十条","txt":"互联网电子邮件服务提供者应当记录经其电子邮件服务器发送或者接收的互联网电子邮件的发送或者接收时间、发送者和接收者的互联网电子邮件地址及IP地址。上述记录应当保存六十日，并在国家有关机关依法查询时予以提供。"},{"i":11,"n":"第十一条","txt":"任何组织或者个人不得制作、复制、发布、传播包含《中华人民共和国电信条例》第五十七条规定内容的互联网电子邮件。 任何组织或者个人不得利用互联网电子邮件从事《中华人民共和国电信条例》第五十八条禁止的危害网络安全和信息安全的活动。"},{"i":12,"n":"第十二条","txt":"任何组织或者个人不得有下列行为： （一）未经授权利用他人的计算机系统发送互联网电子邮件； （二）将采用在线自动收集、字母或者数字任意组合等手段获得的他人的互联网电子邮件地址用于出售、共享、交换或者向通过上述方式获得的电子邮件地址发送互联网电子邮件。"},{"i":13,"n":"第十三条","txt":"任何组织或者个人不得有下列发送或者委托发送互联网电子邮件的行为： （一）故意隐匿或者伪造互联网电子邮件信封信息； （二）未经互联网电子邮件接收者明确同意，向其发送包含商业广告内容的互联网电子邮件； （三）发送包含商业广告内容的互联网电子邮件时，未在互联网电子邮件标题信息前部注明“广告”或者“AD”字样。"},{"i":14,"n":"第十四条","txt":"互联网电子邮件接收者明确同意接收包含商业广告内容的互联网电子邮件后，拒绝继续接收的，互联网电子邮件发送者应当停止发送。双方另有约定的除外。 互联网电子邮件服务发送者发送包含商业广告内容的互联网电子邮件，应当向接收者提供拒绝继续接收的联系方式，包括发送者的电子邮件地址，并保证所提供的联系方式在30日内有效。"},{"i":15,"n":"第十五条","txt":"互联网电子邮件服务提供者、为互联网电子邮件服务提供接入服务的电信业务提供者应当受理用户对互联网电子邮件的举报，并为用户提供便捷的举报方式。"},{"i":16,"n":"第十六条","txt":"互联网电子邮件服务提供者、为互联网电子邮件服务提供接入服务的电信业务提供者应当按照下列要求处理用户举报： （一）发现被举报的互联网电子邮件明显含有本办法第十一条第一款规定的禁止内容的，应当及时向国家有关机关报告； （二）本条第（一）项规定之外的其他被举报的互联网电子邮件，应当向信息产业部委托中国互联网协会设立的互联网电子邮件举报受理中心（以下简称“互联网电子邮件举报受理中心”）报告； （三）被举报的互联网电子邮件涉及本单位的，应当立即开展调查，采取合理有效的防范或处理措施，并将有关情况和调查结果及时向国家有关机关或者互联网电子邮件举报受理中心报告。"},{"i":17,"n":"第十七条","txt":"互联网电子邮件举报受理中心依照信息产业部制定的工作制度和流程开展以下工作： （一）受理有关互联网电子邮件的举报； （二）协助信息产业部或者通信管理局认定被举报的互联网电子邮件是否违反本办法有关条款的规定，并协助追查相关责任人; （三）协助国家有关机关追查违反本办法第十一条规定的相关责任人。"},{"i":18,"n":"第十八条","txt":"互联网电子邮件服务提供者、为互联网电子邮件服务提供接入服务的电信业务提供者，应当积极配合国家有关机关和互联网电子邮件举报受理中心开展调查工作。"},{"i":19,"n":"第十九条","txt":"违反本办法第四条规定，未取得增值电信业务经营许可或者未履行非经营性互联网信息服务备案手续开展互联网电子邮件服务的，依据《互联网信息服务管理办法》第十九条的规定处罚。"},{"i":20,"n":"第二十条","txt":"违反本办法第五条规定的，由信息产业部或者通信管理局依据职权责令改正，并处一万元以下的罚款。"},{"i":21,"n":"第二十一条","txt":"未履行本办法第六条、第七条、第八条、第十条规定义务的，由信息产业部或者通信管理局依据职权责令改正，并处五千元以上一万元以下的罚款。"},{"i":22,"n":"第二十二条","txt":"违反本办法第九条规定的，由信息产业部或者通信管理局依据职权责令改正，并处一万元以下的罚款；有违法所得的，并处三万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十一条规定的，依据《中华人民共和国电信条例》第六十七条的规定处理。 互联网电子邮件服务提供者等电信业务提供者有本办法第十一条规定的禁止行为的，信息产业部或者通信管理局依据《中华人民共和国电信条例》第七十八条、《互联网信息服务管理办法》第二十条的规定处罚。"},{"i":24,"n":"第二十四条","txt":"违反本办法第十二条、第十三条、第十四条规定的，由信息产业部或者通信管理局依据职权责令改正，并处一万元以下的罚款；有违法所得的，并处三万元以下的罚款。"},{"i":25,"n":"第二十五条","txt":"违反本办法第十五条、第十六条和第十八条规定的，由信息产业部或者通信管理局依据职权予以警告，并处五千元以上一万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"本办法所称互联网电子邮件地址是指由一个用户名与一个互联网域名共同构成的、可据此向互联网电子邮件用户发送电子邮件的全球唯一性的终点标识。 本办法所称互联网电子邮件信封信息是指附加在互联网电子邮件上，用于标识互联网电子邮件发送者、接收者和传递路由等反映互联网电子邮件来源、终点和传递过程的信息。 本办法所称互联网电子邮件标题信息是指附加在互联网电子邮件上，用于标识互联网电子邮件内容主题的信息。"},{"i":27,"n":"第二十七条","txt":"本办法自2006年3月30日起施行。"}],"hulianwangshitingjiemufuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为维护国家利益和公共利益，保护公众和互联网视听节目服务单位的合法权益，规范互联网视听节目服务秩序，促进健康有序发展，根据国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内向公众提供互联网（含移动互联网，以下简称互联网）视听节目服务活动，适用本规定。 本规定所称互联网视听节目服务，是指制作、编辑、集成并通过互联网向公众提供视音频节目，以及为他人提供上载传播视听节目服务的活动。"},{"i":3,"n":"第三条","txt":"国务院广播电影电视主管部门作为互联网视听节目服务的行业主管部门，负责对互联网视听节目服务实施监督管理，统筹互联网视听节目服务的产业发展、行业管理、内容建设和安全监管。国务院信息产业主管部门作为互联网行业主管部门，依据电信行业管理职责对互联网视听节目服务实施相应的监督管理。 地方人民政府广播电影电视主管部门和地方电信管理机构依据各自职责对本行政区域内的互联网视听节目服务单位及接入服务实施相应的监督管理。"},{"i":4,"n":"第四条","txt":"互联网视听节目服务单位及其相关网络运营单位，是重要的网络文化建设力量，承担建设中国特色网络文化和维护网络文化信息安全的责任,应自觉遵守宪法、法律和行政法规，接受互联网视听节目服务行业主管部门和互联网行业主管部门的管理。"},{"i":5,"n":"第五条","txt":"互联网视听节目服务单位组成的全国性社会团体，负责制定行业自律规范，倡导文明上网、文明办网，营造文明健康的网络环境，传播健康有益视听节目，抵制腐朽落后思想文化传播，并在国务院广播电影电视主管部门指导下开展活动。"},{"i":6,"n":"第六条","txt":"发展互联网视听节目服务要有益于传播社会主义先进文化，推动社会全面进步和人的全面发展、促进社会和谐。从事互联网视听节目服务，应当坚持为人民服务、为社会主义服务，坚持正确导向，把社会效益放在首位，建设社会主义核心价值体系，遵守社会主义道德规范，大力弘扬体现时代发展和社会进步的思想文化，大力弘扬民族优秀文化传统，提供更多更好的互联网视听节目服务，满足人民群众日益增长的需求，不断丰富人民群众的精神文化生活，充分发挥文化滋润心灵、陶冶情操、愉悦身心的作用，为青少年成长创造良好的网上空间，形成共建共享的精神家园。"},{"i":7,"n":"第七条","txt":"从事互联网视听节目服务，应当依照本规定取得广播电影电视主管部门颁发的《信息网络传播视听节目许可证》（以下简称《许可证》）或履行备案手续。 未按照本规定取得广播电影电视主管部门颁发的《许可证》或履行备案手续，任何单位和个人不得从事互联网视听节目服务。 互联网视听节目服务业务指导目录由国务院广播电影电视主管部门商国务院信息产业主管部门制定。"},{"i":8,"n":"第八条","txt":"申请从事互联网视听节目服务的，应当同时具备以下条件： （一）具备法人资格，为国有独资或国有控股单位，且在申请之日前三年内无违法违规记录； （二）有健全的节目安全传播管理制度和安全保护技术措施； （三）有与其业务相适应并符合国家规定的视听节目资源； （四）有与其业务相适应的技术能力、网络资源； （五）有与其业务相适应的专业人员，且主要出资者和经营者在申请之日前三年内无违法违规记录； （六）技术方案符合国家标准、行业标准和技术规范； （七）符合国务院广播电影电视主管部门确定的互联网视听节目服务总体规划、布局和业务指导目录； （八）符合法律、行政法规和国家有关规定的条件。"},{"i":9,"n":"第九条","txt":"从事广播电台、电视台形态服务和时政类视听新闻服务的，除符合本规定第八条规定外，还应当持有广播电视播出机构许可证或互联网新闻信息服务许可证。其中，以自办频道方式播放视听节目的，由地（市）级以上广播电台、电视台、中央新闻单位提出申请。 从事主持、访谈、报道类视听服务的，除符合本规定第八条规定外，还应当持有广播电视节目制作经营许可证和互联网新闻信息服务许可证；从事自办网络剧（片）类服务的，还应当持有广播电视节目制作经营许可证。 未经批准，任何组织和个人不得在互联网上使用广播电视专有名称开展业务。"},{"i":10,"n":"第十条","txt":"申请《许可证》，应当通过省、自治区、直辖市人民政府广播电影电视主管部门向国务院广播电影电视主管部门提出申请，中央直属单位可以直接向国务院广播电影电视主管部门提出申请。 省、自治区、直辖市人民政府广播电影电视主管部门应当提供便捷的服务，自收到申请之日起20日内提出初审意见，报国务院广播电影电视主管部门审批；国务院广播电影电视主管部门应当自收到申请或者初审意见之日起40日内作出许可或者不予许可的决定，其中专家评审时间为20日。予以许可的，向申请人颁发《许可证》，并向社会公告；不予许可的，应当书面通知申请人并说明理由。《许可证》应当载明互联网视听节目服务的播出标识、名称、服务类别等事项。 《许可证》有效期为3年。有效期届满，需继续从事互联网视听节目服务的，应于有效期届满前30日内，持符合本办法第八条规定条件的相关材料，向原发证机关申请办理续办手续。 地（市）级以上广播电台、电视台从事互联网视"},{"i":11,"n":"第十一条","txt":"取得《许可证》的单位，应当依据《互联网信息服务管理办法》，向省（自治区、直辖市）电信管理机构或国务院信息产业主管部门（以下简称电信主管部门）申请办理电信业务经营许可或者履行相关备案手续，并依法到工商行政管理部门办理注册登记或变更登记手续。电信主管部门应根据广播电影电视主管部门许可，严格互联网视听节目服务单位的域名和IP地址管理。"},{"i":12,"n":"第十二条","txt":"互联网视听节目服务单位变更股东、股权结构，有重大资产变动或有上市等重大融资行为的，以及业务项目超出《许可证》载明范围的，应按本规定办理审批手续。互联网视听节目服务单位的办公场所、法定代表人以及互联网信息服务单位的网址、网站名依法变更的，应当在变更后15日内向省级以上广播电影电视主管部门和电信主管部门备案,变更事项涉及工商登记的，应当依法到工商行政管理部门办理变更登记手续。"},{"i":13,"n":"第十三条","txt":"互联网视听节目服务单位应当在取得《许可证》90日内提供互联网视听节目服务。未按期提供服务的，其《许可证》由原发证机关予以注销。如因特殊原因，应经发证机关同意。申请终止服务的，应提前60日向原发证机关申报，其《许可证》由原发证机关予以注销。连续停止业务超过60日的，由原发证机关按终止业务处理，其《许可证》由原发证机关予以注销。"},{"i":14,"n":"第十四条","txt":"互联网视听节目服务单位应当按照《许可证》载明或备案的事项开展互联网视听节目服务，并在播出界面显著位置标注国务院广播电影电视主管部门批准的播出标识、名称、《许可证》或备案编号。 任何单位不得向未持有《许可证》或备案的单位提供与互联网视听节目服务有关的代收费及信号传输、服务器托管等金融和技术服务。"},{"i":15,"n":"第十五条","txt":"鼓励国有战略投资者投资互联网视听节目服务企业；鼓励互联网视听节目服务单位积极开发适应新一代互联网和移动通信特点的新业务，为移动多媒体、多媒体网站生产积极健康的视听节目，努力提高互联网视听节目的供给能力；鼓励影视生产基地、电视节目制作单位多生产适合在网上传播的影视剧（片）、娱乐节目，积极发展民族网络影视产业；鼓励互联网视听节目服务单位传播公益性视听节目。 互联网视听节目服务单位应当遵守著作权法律、行政法规的规定，采取版权保护措施，保护著作权人的合法权益。"},{"i":16,"n":"第十六条","txt":"互联网视听节目服务单位提供的、网络运营单位接入的视听节目应当符合法律、行政法规、部门规章的规定。已播出的视听节目应至少完整保留60日。视听节目不得含有以下内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）诱导未成年人违法犯罪和渲染暴力、色情、赌博、恐怖活动的； （八）侮辱或者诽谤他人，侵害公民个人隐私等他人合法权益的； （九）危害社会公德，损害民族优秀文化传统的； （十）有关法律、行政法规和国家规定禁止的其他内容。"},{"i":17,"n":"第十七条","txt":"用于互联网视听节目服务的电影电视剧类节目和其它节目，应当符合国家有关广播电影电视节目的管理规定。互联网视听节目服务单位播出时政类视听新闻节目，应当是地（市）级以上广播电台、电视台制作、播出的节目和中央新闻单位网站登载的时政类视听新闻节目。 未持有《许可证》的单位不得为个人提供上载传播视听节目服务。互联网视听节目服务单位不得允许个人上载时政类视听新闻节目，在提供播客、视频分享等上载传播视听节目服务时，应当提示上载者不得上载违反本规定的视听节目。任何单位和个人不得转播、链接、聚合、集成非法的广播电视频道、视听节目网站的节目。"},{"i":18,"n":"第十八条","txt":"广播电影电视主管部门发现互联网视听节目服务单位传播违反本规定的视听节目，应当采取必要措施予以制止。互联网视听节目服务单位对含有违反本规定内容的视听节目，应当立即删除，并保存有关记录，履行报告义务，落实有关主管部门的管理要求。 互联网视听节目服务单位主要出资者和经营者应对播出和上载的视听节目内容负责。"},{"i":19,"n":"第十九条","txt":"互联网视听节目服务单位应当选择依法取得互联网接入服务电信业务经营许可证或广播电视节目传送业务经营许可证的网络运营单位提供服务;应当依法维护用户权利，履行对用户的承诺，对用户信息保密,不得进行虚假宣传或误导用户、做出对用户不公平不合理的规定、损害用户的合法权益；提供有偿服务时，应当以显著方式公布所提供服务的视听节目种类、范围、资费标准和时限，并告知用户中止或者取消互联网视听节目服务的条件和方式。"},{"i":20,"n":"第二十条","txt":"网络运营单位提供互联网视听节目信号传输服务时，应当保障视听节目服务单位的合法权益，保证传输安全，不得擅自插播、截留视听节目信号;在提供服务前应当查验视听节目服务单位的《许可证》或备案证明材料，按照《许可证》载明事项或备案范围提供接入服务。"},{"i":21,"n":"第二十一条","txt":"广播电影电视和电信主管部门应建立公众监督举报制度。公众有权举报视听节目服务单位的违法违规行为，有关主管部门应当及时处理，不得推诿。广播电影电视、电信等监督管理部门发现违反本规定的行为，不属于本部门职责的，应当移交有权处理的部门处理。 电信主管部门应当依照国家有关规定向广播电影电视主管部门提供必要的技术系统接口和网站数据查询资料。"},{"i":22,"n":"第二十二条","txt":"广播电影电视主管部门依法对互联网视听节目服务单位进行实地检查，有关单位和个人应当予以配合。广播电影电视主管部门工作人员依法进行实地检查时应当主动出示有关证件。"},{"i":23,"n":"第二十三条","txt":"违反本规定有下列行为之一的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；同时，可对其主要出资者和经营者予以警告，可并处2万元以下罚款： （一）擅自在互联网上使用广播电视专有名称开展业务的； （二）变更股东、股权结构，或上市融资，或重大资产变动时，未办理审批手续的； （三）未建立健全节目运营规范，未采取版权保护措施，或对传播有害内容未履行提示、删除、报告义务的； （四）未在播出界面显著位置标注播出标识、名称、《许可证》和备案编号的； （五）未履行保留节目记录、向主管部门如实提供查询义务的； （六）向未持有《许可证》或备案的单位提供代收费及信号传输、服务器托管等与互联网视听节目服务有关的服务的； （七）未履行查验义务，或向互联网视听节目服务单位提供其《许可证》或备案载明事项范围以外的接入服务的； （八）进行虚假宣传或者误导用户的； （九）未经用户同意，擅自泄露用"},{"i":24,"n":"第二十四条","txt":"擅自从事互联网视听节目服务的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第四十七条的规定予以处罚。 传播的视听节目内容违反本规定的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第四十九条的规定予以处罚。 未按照许可证载明或备案的事项从事互联网视听节目服务的或违规播出时政类视听新闻节目的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第五十条之规定予以处罚。 转播、链接、聚合、集成非法的广播电视频道和视听节目网站内容的，擅自插播、截留视听节目信号的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第五十一条之规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"对违反本规定的互联网视听节目服务单位，电信主管部门应根据广播电影电视主管部门的书面意见，按照电信管理和互联网管理的法律、行政法规的规定，关闭其网站，吊销其相应许可证或撤销备案，责令为其提供信号接入服务的网络运营单位停止接入；拒不执行停止接入服务决定，违反《电信条例》第五十七条规定的，由电信主管部门依据《电信条例》第七十八条的规定吊销其许可证。 违反治安管理规定的，由公安机关依法予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"广播电影电视、电信等主管部门不履行规定的职责，或滥用职权的，要依法给予有关责任人处分，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"互联网视听节目服务单位出现重大违法违规行为的，除按有关规定予以处罚外，其主要出资者和经营者自互联网视听节目服务单位受到处罚之日起5年内不得投资和从事互联网视听节目服务。"},{"i":28,"n":"第二十八条","txt":"通过互联网提供视音频即时通讯服务，由国务院信息产业主管部门按照国家有关规定进行监督管理。 利用局域网络及利用互联网架设虚拟专网向公众提供网络视听节目服务，须向行业主管部门提出申请，由国务院信息产业主管部门前置审批，国务院广播电影电视主管部门审核批准，按照国家有关规定进行监督管理。"},{"i":29,"n":"第二十九条","txt":"本规定自2008年1月31日起施行。此前发布的规定与本规定不一致之处，依本规定执行。"}],"gonggongziyuanjiaoyipingtaiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范公共资源交易平台运行，提高公共资源配置效率和效益，加强对权力运行的监督制约，维护国家利益、社会公共利益和交易当事人的合法权益，根据有关法律法规和《国务院办公厅关于印发整合建立统一的公共资源交易平台工作方案的通知》（国办发[2015]63号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于公共资源交易平台的运行、服务和监督管理。"},{"i":3,"n":"第三条","txt":"本办法所称公共资源交易平台是指实施统一的制度和标准、具备开放共享的公共资源交易电子服务系统和规范透明的运行机制，为市场主体、社会公众、行政监督管理部门等提供公共资源交易综合服务的体系。 公共资源交易是指涉及公共利益、公众安全的具有公有性、公益性的资源交易活动。"},{"i":4,"n":"第四条","txt":"公共资源交易平台应当立足公共服务职能定位，坚持电子化平台的发展方向，遵循开放透明、资源共享、高效便民、守法诚信的运行服务原则。"},{"i":5,"n":"第五条","txt":"公共资源交易平台要利用信息网络推进交易电子化,实现全流程透明化管理。"},{"i":6,"n":"第六条","txt":"国务院发展改革部门会同国务院有关部门统筹指导和协调全国公共资源交易平台相关工作。 设区的市级以上地方人民政府发展改革部门或政府指定的部门会同有关部门负责本行政区域的公共资源交易平台指导和协调等相关工作。 各级招标投标、财政、国土资源、国有资产等行政监督管理部门按照规定的职责分工，负责公共资源交易活动的监督管理。"},{"i":7,"n":"第七条","txt":"公共资源交易平台的运行应当遵循相关法律法规和国务院有关部门制定的各领域统一的交易规则，以及省级人民政府颁布的平台服务管理细则。"},{"i":8,"n":"第八条","txt":"依法必须招标的工程建设项目招标投标、国有土地使用权和矿业权出让、国有产权交易、政府采购等应当纳入公共资源交易平台。 国务院有关部门和地方人民政府结合实际，推进其他各类公共资源交易纳入统一平台。纳入平台交易的公共资源项目，应当公开听取意见，并向社会公布。"},{"i":9,"n":"第九条","txt":"公共资源交易平台应当按照国家统一的技术标准和数据规范，建立公共资源交易电子服务系统，开放对接各类主体依法建设的公共资源电子交易系统和政府有关部门的电子监管系统。"},{"i":10,"n":"第十条","txt":"公共资源交易项目的实施主体根据交易标的专业特性，选择使用依法建设和运行的电子交易系统。"},{"i":11,"n":"第十一条","txt":"公共资源交易项目依法需要评标、评审的，应当按照全国统一的专家专业分类标准，从依法建立的综合评标、政府采购评审等专家库中随机抽取专家，法律法规另有规定的除外。 有关行政监督管理部门按照规定的职责分工，对专家实施监督管理。 鼓励有条件的地方跨区域选择使用专家资源。"},{"i":12,"n":"第十二条","txt":"公共资源交易平台应当按照省级人民政府规定的场所设施标准，充分利用已有的各类场所资源，为公共资源交易活动提供必要的现场服务设施。 市场主体依法建设的交易场所符合省级人民政府规定标准的，可以在现有场所办理业务。"},{"i":13,"n":"第十三条","txt":"公共资源交易平台应当建立健全网络信息安全制度，落实安全保护技术措施，保障平台平稳运行。"},{"i":14,"n":"第十四条","txt":"公共资源交易平台的服务内容、服务流程、工作规范、收费标准和监督渠道应当按照法定要求确定，并通过公共资源交易电子服务系统向社会公布。"},{"i":15,"n":"第十五条","txt":"公共资源交易平台应当推行网上预约和服务事项办理。确需在现场办理的，实行窗口集中，简化流程，限时办结。"},{"i":16,"n":"第十六条","txt":"公共资源交易平台应当将公共资源交易公告、资格审查结果、交易过程信息、成交信息、履约信息等，通过公共资源交易电子服务系统依法及时向社会公开。涉及国家秘密、商业秘密、个人隐私以及其他依法应当保密的信息除外。 公共资源交易平台应当无偿提供依法必须公开的信息。"},{"i":17,"n":"第十七条","txt":"交易服务过程中产生的电子文档、纸质资料以及音视频等，应当按照规定的期限归档保存。"},{"i":18,"n":"第十八条","txt":"公共资源交易平台运行服务机构及其工作人员不得从事以下活动： （一）行使任何审批、备案、监管、处罚等行政监督管理职能； （二）违法从事或强制指定招标、拍卖、政府采购代理、工程造价等中介服务； （三）强制非公共资源交易项目进入平台交易； （四）干涉市场主体选择依法建设和运行的公共资源电子交易系统； （五）非法扣押企业和人员的相关证照资料； （六）通过设置注册登记、设立分支机构、资质验证、投标（竞买）许可、强制担保等限制性条件阻碍或者排斥其他地区市场主体进入本地区公共资源交易市场； （七）违法要求企业法定代表人到场办理相关手续； （八）其他违反法律法规规定的情形。"},{"i":19,"n":"第十九条","txt":"公共资源交易平台运行服务机构提供公共服务确需收费的，不得以营利为目的。根据平台运行服务机构的性质，其收费分别纳入行政事业性收费和经营服务性收费管理，具体收费项目和收费标准按照有关规定执行。属于行政事业性收费的，按照本级政府非税收入管理的有关规定执行。"},{"i":20,"n":"第二十条","txt":"公共资源交易平台运行服务机构发现公共资源交易活动中有违法违规行为的，应当保留相关证据并及时向有关行政监督管理部门报告。"},{"i":21,"n":"第二十一条","txt":"各级行政监督管理部门应当将公共资源交易活动当事人资质资格、信用奖惩、项目审批和违法违规处罚等信息，自作出行政决定之日起7个工作日内上网公开，并通过相关电子监管系统交换至公共资源交易电子服务系统。"},{"i":22,"n":"第二十二条","txt":"各级公共资源交易平台应当依托统一的社会信用代码，记录公共资源交易过程中产生的市场主体和专家信用信息，并通过国家公共资源交易电子服务系统实现信用信息交换共享和动态更新。"},{"i":23,"n":"第二十三条","txt":"国务院发展改革部门牵头建立国家公共资源交易电子服务系统，与省级公共资源交易电子服务系统和有关部门建立的电子系统互联互通，实现市场主体信息、交易信息、行政监管信息的集中交换和同步共享。"},{"i":24,"n":"第二十四条","txt":"省级人民政府应当搭建全行政区域统一、终端覆盖市县的公共资源交易电子服务系统，对接国家公共资源交易电子服务系统和有关部门建立的电子系统，按照有关规定交换共享信息。有关电子招标投标、政府采购等系统应当分别与国家电子招标投标公共服务系统、政府采购管理交易系统对接和交换信息。"},{"i":25,"n":"第二十五条","txt":"公共资源交易电子服务系统应当分别与投资项目在线审批监管系统、信用信息共享系统对接，交换共享公共资源交易相关信息、项目审批核准信息和信用信息。"},{"i":26,"n":"第二十六条","txt":"市场主体已经在公共资源电子交易系统登记注册，并通过公共资源交易电子服务系统实现信息共享的，有关行政监督管理部门和公共资源交易平台运行服务机构不得强制要求其重复登记、备案和验证。"},{"i":27,"n":"第二十七条","txt":"公共资源交易电子服务系统应当支持不同电子认证数字证书的兼容互认。"},{"i":28,"n":"第二十八条","txt":"公共资源交易平台和有关行政监督管理部门在公共资源交易数据采集、汇总、传输、存储、公开、使用过程中，应加强数据安全管理。涉密数据的管理，按照有关法律规定执行。"},{"i":29,"n":"第二十九条","txt":"各级行政监督管理部门按照规定的职责分工，加强对公共资源交易活动的事中事后监管，依法查处违法违规行为。 对利用职权违规干预和插手公共资源交易活动的国家机关或国有企事业单位工作人员，依纪依法予以处理。 各级审计部门应当对公共资源交易平台运行依法开展审计监督。"},{"i":30,"n":"第三十条","txt":"设区的市级以上地方人民政府应当推动建立公共资源交易电子监管系统，实现对项目登记，公告发布，开标评标或评审、竞价，成交公示，交易结果确认，投诉举报，交易履约等交易全过程监控。 公共资源交易电子服务系统和其对接的公共资源电子交易系统应当实时向监管系统推送数据。"},{"i":31,"n":"第三十一条","txt":"建立市场主体公共资源交易活动事前信用承诺制度，要求市场主体以规范格式向社会作出公开承诺，并纳入交易主体信用记录，接受社会监督。"},{"i":32,"n":"第三十二条","txt":"各级行政监督管理部门应当将公共资源交易主体信用信息作为市场准入、项目审批、资质资格审核的重要依据。 建立行政监督管理部门、司法机关等部门联合惩戒机制，对在公共资源交易活动中有不良行为记录的市场主体，依法限制或禁止其参加招标投标、国有土地使用权出让和矿业权出让、国有产权交易、政府采购等公共资源交易活动。 建立公共资源交易相关信息与同级税务机关共享机制，推进税收协作。"},{"i":33,"n":"第三十三条","txt":"各级行政监督管理部门应当运用大数据技术，建立公共资源交易数据关联比对分析机制，开展监测预警，定期进行效果评估，及时调整监管重点。"},{"i":34,"n":"第三十四条","txt":"各级行政监督管理部门应当建立联合抽查机制，对有效投诉举报多或有违法违规记录情况的市场主体，加大随机抽查力度。 行政监督管理部门履行监督管理职责过程中，有权查阅、复制公共资源交易活动有关文件、资料和数据。公共资源交易平台运行服务机构应当如实提供相关情况。"},{"i":35,"n":"第三十五条","txt":"建立由市场主体以及第三方参与的社会评价机制，对所辖行政区域公共资源交易平台运行服务机构提供公共服务情况进行评价。"},{"i":36,"n":"第三十六条","txt":"市场主体或社会公众认为公共资源交易平台运行服务机构及其工作人员存在违法违规行为的，可以依法向政府有关部门投诉、举报。"},{"i":37,"n":"第三十七条","txt":"公共资源交易领域的行业协会应当发挥行业组织作用，加强自律管理和服务。"},{"i":38,"n":"第三十八条","txt":"公共资源交易平台运行服务机构未公开服务内容、服务流程、工作规范、收费标准和监督渠道，由政府有关部门责令限期改正。拒不改正的，予以通报批评。"},{"i":39,"n":"第三十九条","txt":"公共资源交易平台运行服务机构及其工作人员违反本办法第十八条禁止性规定的，由政府有关部门责令限期改正，并予以通报批评。情节严重的，依法追究直接责任人和有关领导的责任。构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"公共资源交易平台运行服务机构违反本办法第十九条规定收取费用的，由同级价格主管部门会同有关部门责令限期改正。拒不改正的，依照《中华人民共和国价格法》、《价格违法行为行政处罚规定》等给予处罚，并予以公示。"},{"i":41,"n":"第四十一条","txt":"公共资源交易平台运行服务机构未按照本办法规定在公共资源交易电子服务系统公开、交换、共享信息的，由政府有关部门责令限期改正。拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报。"},{"i":42,"n":"第四十二条","txt":"公共资源交易平台运行服务机构限制市场主体建设的公共资源电子交易系统对接公共资源交易电子服务系统的，由政府有关部门责令限期改正。拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分，并予以通报。"},{"i":43,"n":"第四十三条","txt":"公共资源交易平台运行服务机构及其工作人员向他人透露依法应当保密的公共资源交易信息的，由政府有关部门责令限期改正，并予以通报批评。情节严重的，依法追究直接责任人和有关领导的责任。构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"有关行政监督管理部门、公共资源交易平台运行服务机构及其工作人员徇私舞弊、滥用职权、弄虚作假、玩忽职守，未依法履行职责的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"公共资源电子交易系统是根据工程建设项目招标投标、土地使用权和矿业权出让、国有产权交易、政府采购等各类交易特点，按照有关规定建设、对接和运行，以数据电文形式完成公共资源交易活动的信息系统。 公共资源交易电子监管系统是指政府有关部门在线监督公共资源交易活动的信息系统。 公共资源交易电子服务系统是指联通公共资源电子交易系统、监管系统和其他电子系统，实现公共资源交易信息数据交换共享，并提供公共服务的枢纽。"},{"i":46,"n":"第四十六条","txt":"公共资源交易平台运行服务机构是指由政府推动设立或政府通过购买服务等方式确定的，通过资源整合共享方式，为公共资源交易相关市场主体、社会公众、行政监督管理部门等提供公共服务的单位。"},{"i":47,"n":"第四十七条","txt":"本办法由国务院发展改革部门会同国务院有关部门负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2016年8月1日起实施。"}],"gongyongdianxinwangjianhulianguanliguiding":[{"i":1,"n":"第一条","txt":"为了维护国家利益和电信用户的合法权益，保护电信业务经营者之间公平、有效竞争，保障公用电信网间及时、合理地互联，根据《中华人民共和国电信条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国境内经营基础电信业务的经营者在下列电信网间的互联： （一）固定本地电话网； （二）国内长途电话网； （三）国际电话网； （四）IP电话网； （五）陆地蜂窝移动通信网； （六）卫星移动通信网； （七）互联网骨干网； （八）工业和信息化部规定的其他电信网。"},{"i":3,"n":"第三条","txt":"电信网之间应当按照技术可行、经济合理、公平公正、相互配合的原则实现互联。"},{"i":4,"n":"第四条","txt":"工业和信息化部和省、自治区、直辖市通信管理局（以下合称“电信主管部门”）是电信网间互联的主管部门。工业和信息化部负责本规定在全国范围内的实施工作；省、自治区、直辖市通信管理局负责本规定在本行政区域内的实施工作。"},{"i":5,"n":"第五条","txt":"本规定下列用语的含义是： （一）互联，是指建立电信网间的有效通信连接，以使一个电信业务经营者的用户能够与另一个电信业务经营者的用户相互通信或者能够使用另一个电信业务经营者的各种电信业务。互联包括两个电信网网间直接相联实现业务互通的方式，以及两个电信网通过第三方的网络转接实现业务互通的方式。 （二）互联点，是指两个电信网网间直接相联时的物理接口点。 （三）主导的电信业务经营者，是指控制必要的基础电信设施，并且所经营的固定本地电话业务占本地网范围内同类业务市场50%以上的市场份额，能够对其他电信业务经营者进入电信业务市场构成实质性影响的经营者。 （四）非主导的电信业务经营者，是指主导的电信业务经营者以外的电信业务经营者。"},{"i":6,"n":"第六条","txt":"电信业务经营者应当设立互联工作机构负责互联工作。互联工作机构应当建立正常的工作联系制度，保证电信业务经营者与电信主管部门之间以及电信业务经营者之间工作渠道的畅通。"},{"i":7,"n":"第七条","txt":"主导的电信业务经营者应当根据本规定制定包括网间互联的程序、时限、互联点的数量、用于网间互联的交换机局址、非捆绑网络元素提供或出租的目录及费用等内容的互联规程。互联规程报工业和信息化部批准后执行。互联规程对主导的电信业务经营者的互联互通活动具有约束力。"},{"i":8,"n":"第八条","txt":"电信业务经营者不得拒绝其他电信业务经营者提出的互联要求，不得违反国家有关规定擅自限制用户选择其他电信业务经营者依法开办的电信业务。"},{"i":9,"n":"第九条","txt":"主导的电信业务经营者有义务向非主导的电信业务经营者提供与互联有关的网络功能（含网络组织、信令方式、计费方式、同步方式等）、设备配置（光端机、交换机等）的信息，以及与互联有关的管道（孔）、杆路、线缆引入口及槽道、光缆（纤）、带宽、电路等通信设施的使用信息。非主导的电信业务经营者有义务向主导的电信业务经营者提供与互联有关的网络功能、设备配置的计划和规划信息。 双方应当对对方提供的信息保密，并不得利用该信息从事与互联无关的活动。"},{"i":10,"n":"第十条","txt":"非主导的电信业务经营者的电信网与主导的电信业务经营者的电信网网间互联，互联传输线路必须经由主导的电信业务经营者的管道（孔）、杆路、线缆引入口及槽道等通信设施的，主导的电信业务经营者应当予以配合提供使用，并不得附加任何不合理的条件。 两个非主导的电信业务经营者的电信网网间直接相联，互联传输线路必须经由主导的电信业务经营者的楼层院落、管道（孔）、杆路、线缆引入口及槽道等通信设施的，主导的电信业务经营者应当予以配合提供使用，并不得附加任何不合理的条件。 前款主导的电信业务经营者的通信设施经省、自治区、直辖市通信管理局确认无法提供使用的，非主导的电信业务经营者可以通过架空、直埋等其他方式解决互联传输线路问题。"},{"i":11,"n":"第十一条","txt":"主导的电信业务经营者应当在规定的互联时限内提供互联，非主导的电信业务经营者应当在规定的互联时限内实施互联。双方均不得无故拖延互联时间。"},{"i":12,"n":"第十二条","txt":"电信业务经营者应当执行工业和信息化部制定的相关网间互联技术规范、技术规定。 网间通信质量应当符合国家有关标准。电信业务经营者应当保证网间通信质量不低于其网络内部同类业务的通信质量。"},{"i":13,"n":"第十三条","txt":"应非主导的电信业务经营者的要求，主导的电信业务经营者应当向对方网的用户提供电话号码查询业务，并经双方协商后，可按查号规则查询到对方网的可查询用户号码。非主导的电信业务经营者应当按查号规则向对方提供本网的可查询用户号码资料。 应非主导的电信业务经营者的要求，主导的电信业务经营者应当向对方网的用户提供火警、匪警、医疗急救、交通事故报警等紧急特种业务。非主导的电信业务经营者应当每日进行紧急特种业务的拨叫例测。双方应当共同保证紧急特种业务的通信质量。"},{"i":14,"n":"第十四条","txt":"电信业务经营者向本网开放的各种电信业务接入号码（含短号码）、其他特种业务号码（含电信业务经营者所用的业务号码、政府公务类业务号码、社会服务类业务号码）、智能业务号码等，应一方的要求，应当及时向对方网开放，并保证通信质量。"},{"i":15,"n":"第十五条","txt":"两个非主导的电信业务经营者的电信网网间直接相联，由双方协商解决。 两个非主导的电信业务经营者的电信网网间未直接相联的，其网间业务应当经第三方的固定本地电话网或工业和信息化部指定的机构的网络转接实现互通。非主导电信业务经营者选择主导的电信业务经营者的固定本地电话网作为第三方的网络时，主导的电信业务经营者不得拒绝提供转接，并应当保证转接的通信质量。"},{"i":16,"n":"第十六条","txt":"非主导的电信业务经营者的电信网与主导的电信业务经营者的电信网网间互联时，互联点应当设置在互联传输线路的一端，即远离非主导的电信业务经营者侧的设备的一端（例如，当互联传输线路为光缆时，互联点设置在主导的电信业务经营者光配线架外侧）。 两个非主导的电信业务经营者的电信网网间直接相联时，互联点的具体位置由双方协商确定。"},{"i":17,"n":"第十七条","txt":"互联点数量应当根据双方业务发展以及网间通信安全的需要协商确定。在一个本地网内各电信网网间互联原则上应当有两个以上（含两个）互联点。 互联点两侧的电信设备可以由各电信网共用，也可以由各电信网分设。当互联点两侧的电信设备由各电信网共用时，如果各电信网网间结算标准不一致，双方又不易采用技术手段进行计费核查的，互联中继电路可以分群设置。"},{"i":18,"n":"第十八条","txt":"非主导的电信业务经营者的电信网与主导的电信业务经营者的电信网网间互联的，互联传输线路及管道由双方各自承担一半。 两个非主导的电信业务经营者的电信网网间直接相联的，互联传输线路的费用分摊由双方协商确定。"},{"i":19,"n":"第十九条","txt":"互联点两侧的电信设备（含各自网内的电信设备，下同）的建设、扩容改造的费用（含信令方式、局数据修改、软件版本升级等费用）由双方各自承担。 互联点两侧的电信设备的配套设施（含机房、空调、电源、测试仪器、计费设备及其他配套设施）的费用由双方各自承担。"},{"i":20,"n":"第二十条","txt":"互联传输线路经由主导的电信业务经营者的管道（孔）、杆路、线缆引入口及槽道等通信设施的，主导的电信业务经营者应当按规定标准收取租用费。暂无规定标准的，相关费用以建设成本为基础由双方协商解决。"},{"i":21,"n":"第二十一条","txt":"电信业务经营者在互联互通中应当执行《电信网间通话费结算办法》，不得在规定标准以外加收费用。 电信业务经营者应当按互联协议规定的结算周期进行网间结算，不得无故拖延应向对方结算的费用。"},{"i":22,"n":"第二十二条","txt":"电信业务经营者应当按国家有关规定核算本网与互联有关的收支情况及互联成本，经相关中介机构审查验证后，于每年3月31日前将上一年度的数据报工业和信息化部。 网间结算标准应当以成本为基础核定。在电信业务经营者互联成本尚未确定之前，网间结算标准暂以资费为基础核定。"},{"i":23,"n":"第二十三条","txt":"互联协议应当由电信业务经营者省级以上（含省级）机构之间签订（含修订）。电信业务经营者省级以下机构不再另行签订互联协议。互联双方应当本着友好合作和相互配合的原则协商互联协议。"},{"i":24,"n":"第二十四条","txt":"互联协商的主要内容包括：签订协议的依据、互联工程进度时间表、互通的业务、互联技术方案（包括互联点的设置、互联点两侧的设备设置、拨号方式、路由组织、中继容量，以及信令、计费、同步、传输质量等）、与互联有关的网络功能及通信设施的提供、与互联有关的设备配置、互联费用的分摊、互联后的网络管理（包括互联双方维护范围、网间通信质量相互通报制度、网间通信障碍处理制度、网间通信重大障碍报告制度、网间通信应急方案等）、网间结算、违约责任等。"},{"i":25,"n":"第二十五条","txt":"互联双方省级以上机构应当按照《中华人民共和国合同法》及国家有关规定签订互联协议，互联协议不得含有歧视性内容和损害第三方利益的内容。"},{"i":26,"n":"第二十六条","txt":"互联双方省级以上机构应当自协议签订之日起15日内将协议发至各自下属机构，并报送电信主管部门。 第二十七条互联双方应当在规定的互联时限内，根据商定的互联工程进度、互联技术方案，在各自的建设范围内组织施工建设，并协同组织互联测试，全部工程初验合格后即可开通业务。 第五章互联时限与互联监管"},{"i":27,"n":"第二十八条","txt":"涉及全国范围（跨省、自治区、直辖市）同步实施的网间互联，非主导的电信业务经营者应当根据本网工程进度情况或网络运行情况，向主导的电信业务经营者当面提交互联的书面要求，并向工业和信息化部备案后，互联工作开始启动。 互联双方应当从互联启动之日起两个月内签订互联协议。 涉及全国范围同步实施的网间互联需要新设互联点的，应当自互联启动之日起七个月内实现业务开通。 涉及全国范围同步实施的网间互联不需新设互联点，只需进行网络扩容改造的，应当自互联启动之日起四个月内实现业务开通。 涉及全国范围同步实施的网间互联只涉及局数据修改的，应当自互联启动之日起两个月内实现业务开通。 必要时，工业和信息化部对涉及全国范围同步实施的网间互联提出具体的业务开通时间要求。"},{"i":28,"n":"第二十九条","txt":"不涉及全国范围同步实施的网间互联，非主导的电信业务经营者省级以上机构应当根据本网工程进度情况或者网络运行情况，向主导的电信业务经营者省级机构当面提交互联的书面要求，并向省、自治区、直辖市通信管理局备案后，互联工作开始启动。主导的电信业务经营者省级机构不得拒收对方提交的互联书面要求。 互联双方应当在互联工程实施以前签订工程协议，工程协议的签订应当不影响整个互联工程的进度。双方应当在业务开通前签订网间业务互通、互联后的网络管理以及网间结算协议。协议的协商可与工程实施同步进行。 网间互联需新设互联点的，应当自互联启动之日起七个月内实现业务开通。 网间互联不需新设互联点，只需进行网络扩容改造的，应当自互联启动之日起四个月内实现业务开通。 网间互联只涉及局数据修改的，应当自互联启动之日起一个月内实现业务开通。 必要时，省、自治区、直辖市通信管理局对网间互联提出具体的业务开通时间要求。"},{"i":29,"n":"第三十条","txt":"互联实施中，因客观原因致使互联不能在规定的互联时限内完成的，经互联双方认可并向电信主管部门备案后，可以顺延互联时间。"},{"i":30,"n":"第三十一条","txt":"互联双方应当在业务开通后30日内，将互联启动日期、业务开通日期及业务开通后3日内的网间通信质量情况，以书面形式向电信主管部门报告。电信主管部门根据具体情况以适当方式予以公布。"},{"i":31,"n":"第三十二条","txt":"电信主管部门应当定期或不定期地召开相关电信业务经营者的互联协调会，督促解决互联实施过程中存在的问题。 工业和信息化部电信管理局应当向省、自治区、直辖市通信管理局及相关电信业务经营者通报互联工作情况。"},{"i":32,"n":"第三十三条","txt":"在工业和信息化部确定的用于网间互联的交换机局址上实施的互联，互联点应当保持相对稳定，已设互联点原则上不允许变更。 主导的电信业务经营者对已设互联点单方面提出变更要求的，应当事先向相关电信业务经营者提交拟变更的方案，经与对方协商一致后，方可启动改造工程。改造工程应当在七个月内完成。改造工程的费用原则上由主导的电信业务经营者承担。"},{"i":33,"n":"第三十四条","txt":"互联一方因网内扩容改造，可能影响对方网的用户通信的，应当提前三个月以书面形式向对方通报情况。 互联一方因网内发生路由组织、中继电路、信令方式、局数据、软件版本等的调整，可能影响到对方网的用户通信的，应当提前15日以书面形式向对方通报情况。"},{"i":34,"n":"第三十五条","txt":"电信业务经营者对网间路由组织、中继电路、信令方式、局数据、软件版本等的调整应当予以配合，保证网间通信质量符合要求。"},{"i":35,"n":"第三十六条","txt":"电信业务经营者应当明确划分网间运行维护责任，定期协同分析网间通信质量，建立网间通信质量相互通报制度，并定期向电信主管部门报告。电信主管部门根据具体情况组织召开通信质量协调会。"},{"i":36,"n":"第三十七条","txt":"电信业务经营者应当建立网间通信障碍处理制度，互联一方发现网间通信障碍时，应当及时通知对方，双方相互配合共同处理网间通信障碍。网间通信障碍的处理时限与本网处理同类障碍的时限相同。"},{"i":37,"n":"第三十八条","txt":"电信业务经营者应当保障网间通信畅通，不得擅自中断互联互通。电信业务经营者应当建立网间通信重大障碍报告制度。发生网间通信中断或网间通信严重不畅时，电信业务经营者应当立即采取有效措施恢复通信，并及时向电信主管部门报告。 前款所称网间通信严重不畅，是指网间接通率（应答试呼比）低于20%，以及用户有明显感知的时延、断话、杂音等情况。"},{"i":38,"n":"第三十九条","txt":"电信主管部门应当依据工业和信息化部制定的电信网间互联争议解决办法解决电信业务经营者之间的互联争议。"},{"i":39,"n":"第四十条","txt":"在互联实施中，电信业务经营者发生下列争议，致使互联不能继续进行，或者互联后电信业务经营者发生下列争议影响网间业务互通时，任何一方均可以向电信主管部门申请协调： （一）互联技术方案； （二）与互联有关的网络功能及通信设施的提供； （三）互联时限； （四）电信业务的提供； （五）网间通信质量； （六）与互联有关的费用； （七）其他需要协调的问题。"},{"i":40,"n":"第四十一条","txt":"电信主管部门收到协调申请后，对申请的内容进行初步审核。经审核发现申请的内容与国家有关规定明显不符或者超出电信主管部门职责权限的，应当书面答复不予受理。经审查申请的内容符合要求的，电信主管部门正式开始协调工作。"},{"i":41,"n":"第四十二条","txt":"电信主管部门组织相关人员对电信业务经营者的互联争议进行协调。 协调应当自开始协调之日起45日内结束。"},{"i":42,"n":"第四十三条","txt":"协调结束后，争议双方不能达成一致意见的，电信主管部门应当随机邀请电信技术、经济、法律方面的专家进行公开论证。电信主管部门根据论证意见或建议对互联争议作出决定，强制争议双方执行。"},{"i":43,"n":"第四十四条","txt":"决定应当在协调结束之日起45日内作出。省、自治区、直辖市通信管理局作出的决定应当向工业和信息化部备案。电信主管部门对作出的决定以适当方式向社会公布。"},{"i":44,"n":"第四十五条","txt":"决定作出后，争议双方应当在决定规定的时限内予以履行。 争议一方或双方对决定不服，可以依法申请行政复议或者提起行政诉讼。复议或诉讼期间，决定不停止执行。"},{"i":45,"n":"第四十六条","txt":"违反本规定第九条、第十条、第十一条、第十二条第一款、第十三条、第十四条、第十五条、第二十一条第二款、第三十三条、第三十五条、第三十六条、第三十七条规定的，由电信主管部门视情节轻重，依据职权责令改正、处五千元以上三万元以下罚款。 因违反前款规定给其他的电信业务经营者造成直接经济损失的，应当予以经济赔偿。"},{"i":46,"n":"第四十七条","txt":"违反本规定第八条、第十二条第二款和第四十五条规定的，由电信主管部门依据职权责令改正，并按《中华人民共和国电信条例》中的有关规定处以罚款。"},{"i":47,"n":"第四十八条","txt":"违反本规定第二十一条第一款、第三十八条的，由电信主管部门依据职权责令改正，有违法所得的，没收违法所得，并按《中华人民共和国电信条例》的有关规定处以罚款。"},{"i":48,"n":"第四十九条","txt":"本规定自发布之日起施行。1999年9月7日信息产业部发布的《电信网间互联管理暂行规定》同时废止。"}],"gongyiguanggaocujinheguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为促进公益广告事业发展，规范公益广告管理，发挥公益广告在社会主义经济建设、政治建设、文化建设、社会建设、生态文明建设中的积极作用，根据《中华人民共和国广告法》和有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称公益广告，是指传播社会主义核心价值观，倡导良好道德风尚，促进公民文明素质和社会文明程度提高，维护国家和社会公共利益的非营利性广告。 政务信息、服务信息等各类公共信息以及专题宣传片等不属于本办法所称的公益广告。"},{"i":3,"n":"第三条","txt":"国家鼓励、支持开展公益广告活动，鼓励、支持、引导单位和个人以提供资金、技术、劳动力、智力成果、媒介资源等方式参与公益广告宣传。 各类广告发布媒介均有义务刊播公益广告。"},{"i":4,"n":"第四条","txt":"公益广告活动在中央和各级精神文明建设指导委员会指导协调下开展。 工商行政管理部门履行广告监管和指导广告业发展职责，负责公益广告工作的规划和有关管理工作。 新闻出版广电部门负责新闻出版和广播电视媒体公益广告制作、刊播活动的指导和管理。 通信主管部门负责电信业务经营者公益广告制作、刊播活动的指导和管理。 网信部门负责互联网企业公益广告制作、刊播活动的指导和管理。 铁路、公路、水路、民航等交通运输管理部门负责公共交通运载工具及相关场站公益广告刊播活动的指导和管理。 住房城乡建设部门负责城市户外广告设施设置、建筑工地围挡、风景名胜区公益广告刊播活动的指导和管理。 精神文明建设指导委员会其他成员单位应当积极做好公益广告有关工作，涉及本部门职责的，应当予以支持 ，并做好相关管理工作。"},{"i":5,"n":"第五条","txt":"公益广告应当保证质量，内容符合下列规定： （一）价值导向正确，符合国家法律法规和社会主义道德规范要求； （二）体现国家和社会公共利益； （三）语言文字使用规范； （四）艺术表现形式得当，文化品位良好。"},{"i":6,"n":"第六条","txt":"公益广告内容应当与商业广告内容相区别，商业广告中涉及社会责任内容的，不属于公益广告 。"},{"i":7,"n":"第七条","txt":"企业出资设计、制作、发布或者冠名的公益广告，可以标注企业名称和商标标识，但应当符合以下要求： （一）不得标注商品或者服务的名称以及其他与宣传、推销商品或者服务有关的内容，包括单位地址、网址、电话号码、其他联系方式等； （二）平面作品标注企业名称和商标标识的面积不得超过广告面积的1/5； （三）音频、视频作品显示企业名称和商标标识的时间不得超过5秒或者总时长的1/5，使用标版形式标注企业名称和商标标识的时间不得超过3秒或者总时长的1/5； （四）公益广告画面中出现的企业名称或者商标标识不得使社会公众在视觉程度上降低对公益广告内容的感受和认知； （五）不得以公益广告名义变相设计、制作、发布商业广告。 违反前款规定的，视为商业广告。"},{"i":8,"n":"第八条","txt":"公益广告稿源包括公益广告通稿、公益广告作品库稿件以及自行设计制作稿件。 各类广告发布媒介均有义务刊播精神文明建设指导委员会审定的公益广告通稿作品。 公益广告主管部门建立公益广告作品库，稿件供社会无偿选择使用。 单位和个人自行设计制作发布公益广告，公益广告主管部门应当无偿提供指导服务 。"},{"i":9,"n":"第九条","txt":"广播电台、电视台按照新闻出版广电部门规定的条（次），在每套节目每日播出公益广告。其中，广播电台在6﹕00至8﹕00之间、11:00至13:00之间，电视台在19:00至21:00之间，播出数量不得少于主管部门规定的条（次）。 中央主要报纸平均每日出版16版（含）以上的，平均每月刊登公益广告总量不少于8个整版；平均每日出版少于16版多于8版的，平均每月刊登公益广告总量不少于6个整版；平均每日出版8版（含）以下的，平均每月刊登公益广告总量不少于4个整版。省（自治区、直辖市）和省会、副省级城市党报平均每日出版12版（含）以上的，平均每月刊登公益广告总量不少于6个整版；平均每日出版12版（不含）以下的，平均每月刊登公益广告总量不少于4个整版。其他各级党报、晚报、都市报和行业报，平均每月刊登公益广告总量不少于2个整版。 中央主要时政类期刊以及各省（自治区、直辖市）和省会、副省级城市时政类期刊平均"},{"i":10,"n":"第十条","txt":"有关部门和单位应当运用各类社会媒介刊播公益广告。 机场、车站、码头、影剧院、商场、宾馆、商业街区、城市社区、广场、公园、风景名胜区等公共场所的广告设施或者其他适当位置，公交车、地铁、长途客车、火车、飞机等公共交通工具的广告刊播介质或者其他适当位置，适当地段的建筑工地围挡、景观灯杆等构筑物，均有义务刊播公益广告通稿作品或者经主管部门审定的其他公益广告。此类场所公益广告的设置发布应当整齐、安全，与环境相协调，美化周边环境。 工商行政管理、住房城乡建设等部门鼓励、支持有关单位和个人在商品包装或者装潢、企业名称、商标标识、建筑设计、家具设计、服装设计等日常生活事物中，合理融入社会主流价值，传播中华文化，弘扬中国精神。"},{"i":11,"n":"第十一条","txt":"国家支持和鼓励在生产、生活领域增加公益广告设施和发布渠道，扩大社会影响。 住房城乡建设部门编制户外广告设施设置规划，应当规划一定比例公益广告空间设施。发布广告设施招标计划时，应当将发布一定数量公益广告作为前提条件。"},{"i":12,"n":"第十二条","txt":"公益广告主管部门应当制定并公布年度公益广告活动规划。 公益广告发布者应当于每季度第一个月5日前，将上一季度发布公益广告的情况报当地工商行政管理部门备案。广播、电视、报纸、期刊以及电信业务经营者、互联网企业等还应当将发布公益广告的情况分别报当地新闻出版广电、通信主管部门、网信部门备案。 工商行政管理部门对广告媒介单位发布公益广告情况进行监测和检查，定期公布公益广告发布情况。"},{"i":13,"n":"第十三条","txt":"发布公益广告情况纳入文明城市、文明单位、文明网站创建工作测评。 广告行业组织应当将会员单位发布公益广告情况纳入行业自律考评。"},{"i":14,"n":"第十四条","txt":"公益广告设计制作者依法享有公益广告著作权，任何单位和个人应依法使用公益广告作品，未经著作权人同意，不得擅自使用或者更改使用。"},{"i":15,"n":"第十五条","txt":"公益广告活动违反本办法规定，有关法律、法规、规章有规定的，由有关部门依法予以处罚；有关法律、法规、规章没有规定的，由有关部门予以批评、劝诫，责令改正。"},{"i":16,"n":"第十六条","txt":"本办法自2016年3月1日起施行。"}],"guanyujingneiqiyechengjiefuwuwaibaoyewuxinxibaohud9c2dba":[{"i":1,"n":"第一条","txt":"为促进承接服务外包业务的中国境内企业（以下称接包方）妥善保护保密信息，维护公平竞争环境，促进我国服务外包产业的进一步发展，根据《中华人民共和国合同法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的承接服务外包业务是指接包方通过合同向境内外的企业、机构、组织或个人（以下称发包方）提供的信息技术外包服务、技术性业务流程外包服务等服务的行为。"},{"i":3,"n":"第三条","txt":"本规定所称保密信息是指符合以下条件的业务资料或数据： （一）接包方在承接服务外包业务过程中从发包方所获取； （二）发包方采取了保密措施且不为公众知悉； （三）接包方根据合同约定应当承担保密义务。"},{"i":4,"n":"第四条","txt":"接包方及其股东、董事、监事、经理和员工不得违反服务外包合同的约定，披露、使用或者允许他人使用其所掌握的发包方的保密信息。"},{"i":5,"n":"第五条","txt":"接包方应成立信息保护机构或指定专职人员负责制定本企业的信息保护规章制度，对保密信息采取合理的、具体的、有效的保密措施，包括： （一）限定涉密人员的范围； （二）对保密信息载体及其存储场所采取技术物理控制，以避免信息被他人不当访问或获取； （三）对保密信息的记录载体进行分级管理； （四）对配方含量和程序步骤等重要信息加密保存或保存于受限区域； （五）对保密信息载体使用密码； （六）对存有保密信息的厂房、车间、办公室等场所限制来访者或者对他们提出保密要求； （七）对存有保密信息的计算机建立有效的网络管理和数据保护措施，建立严格的身份认证和访问授权体系，采用完善的系统备份和故障恢复手段，定期进行安全补丁和病毒库的升级； （八）接包方与发包方约定的其他措施。"},{"i":6,"n":"第六条","txt":"接包方应通过与员工，特别是涉密人员签订保密协议、竞业禁止协议，以及与涉密的第三方人员签订保密协议等措施确保信息安全。"},{"i":7,"n":"第七条","txt":"接包方应当加强对员工的信息安全培训，增强员工的保密意识，避免泄漏保密信息事故的发生。"},{"i":8,"n":"第八条","txt":"鼓励接包方积极借鉴国内外信息安全认证要求、行业最佳实践来制定企业内部信息安全管理体系，并获取国内、国际信息安全认证。"},{"i":9,"n":"第九条","txt":"接包方应积极开展对内部信息安全管理体系的检查及维护，持续改进企业内部信息安全体系。"},{"i":10,"n":"第十条","txt":"接包方违反与发包方之间的保密协议或服务外包合同中的保密条款，发包方可以根据保密协议或服务外包合同的约定提起仲裁或向有管辖权的法院起诉。"},{"i":11,"n":"第十一条","txt":"接包方应与发包方明确约定接包方在为发包方提供服务、履行信息保密义务的过程中所产生的知识产权或技术成果的归属。"},{"i":12,"n":"第十二条","txt":"接包方不得侵犯发包方依法享有的商标、专利、著作权等知识产权权利。"},{"i":13,"n":"第十三条","txt":"相关行业协会等中介组织应加强行业自律管理，可根据需要定期公布接包方的信息保密工作情况。"},{"i":14,"n":"第十四条","txt":"本规定由商务部、工业和信息化部负责解释。"},{"i":15,"n":"第十五条","txt":"本规定自2010年2月1日起施行。"}],"nongyehuaxuewuzhichanpinxingzhengbaohutiaolishishi00cfea":[{"i":1,"n":"第一条","txt":"根据《农业化学物质产品行政保护条例》（以下简称条例）第二十一条规定，制定本细则。"},{"i":2,"n":"第二条","txt":"条例所称国务院化学工业行政主管部门是指中华人民共和国化学工业部（以下简称化工部）。 化工部设立行政保护评审办公室，具体负责农业化学物质产品行政保护申请的受理和审查，行政保护证书的颁发，行政保护有关事项的登记、公告和侵权纠纷处理等工作。"},{"i":3,"n":"第三条","txt":"条例所称农业化学物质产品独占权人，是指对申请行政保护的农业化学物质产品的制造、使用和销售享有完全权利的人。"},{"i":4,"n":"第四条","txt":"条例第五条第（三）项所称尚未在中国销售的，是指申请行政保护的农业化学物质产品尚未通过合法的商业渠道在中国农药市场上流通过。"},{"i":5,"n":"第五条","txt":"条例所称代理机构是指中华正达化工法律事务中心。"},{"i":6,"n":"第六条","txt":"向化工部递交行政保护申请书或者办理各种手续，应当使用化工部制定的统一表式。"},{"i":7,"n":"第七条","txt":"化工部有关行政保护的文件需要送交申请人的，应当通过代理机构转交。"},{"i":8,"n":"第八条","txt":"条例和本细则规定的各种期限的第一日不计算在期限内。期限以年或月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日。期限届满日是法定节假日的，以节假后的第一个工作日为期限届满日。"},{"i":9,"n":"第九条","txt":"条例第八条所称的外文，是指申请人所在国的官方语言。"},{"i":10,"n":"第十条","txt":"申请人委托代理机构办理申请行政保护事宜时，双方应当签订委托书，写明委托权限。 代理机构在递交条例第八条和本细则规定的申请文件的同时，应当递交委托书。"},{"i":11,"n":"第十一条","txt":"在中国没有经常居所或者营业所的申请人申请行政保护，化工部认为必要时，可以要求其提供下列文件： （一）国籍证明； （二）申请人是企业或者其他组织的，其营业所或者总部所在地的证明文件。"},{"i":12,"n":"第十二条","txt":"一件农业化学物质产品行政保护申请应当限于一种农业化学物质产品。"},{"i":13,"n":"第十三条","txt":"条例第八条第（一）项规定的行政保护申请书应当写明下列事项： （一）申请人姓名或者名称、地址； （二）申请人的国籍； （三）申请人是企业或者其他组织的，其总部所在的国家或者地区； （四）农业化学物质产品名称、化学结构式和生产工艺简介等； （五）申请人和代理机构签名或者盖章； （六）申请文件清单； （七）其他需要注明的事项。"},{"i":14,"n":"第十四条","txt":"申请人递交的各种文件应当整齐清晰，不得涂改。申请文件的文字应当横向书写，附图应当用制图工具绘制。对于中国统一规定的科技术语，应当采用规范用语。"},{"i":15,"n":"第十五条","txt":"在行政保护证书颁发之前，申请人要求撤回行政保护申请的，应当通过代理机构向化工部提出书面申请，写明申请人的姓名或者名称和产品名称。"},{"i":16,"n":"第十六条","txt":"申请人向化工部递交的文件，有下列情形之一的，被视为未提出申请： （一）未使用规定的表式或者填写不符合规定的； （二）未按照规定递交有关证明材料的。"},{"i":17,"n":"第十七条","txt":"化工部应当在条例第十一条规定的审查期限内，及时完成审查工作。"},{"i":18,"n":"第十八条","txt":"条例第十三条所称行政保护证书颁发之日，是指行政保护证书上写明的日期。"},{"i":19,"n":"第十九条","txt":"依照条例第十六条的规定，对化工部给予行政保护的农业化学物质产品，可以提出撤销的理由是指该产品不符合条例第五条的规定。"},{"i":20,"n":"第二十条","txt":"依照条例第十六条规定，请求化工部撤销行政保护的，应当递交撤销行政保护请求书和有关证明文件一式二份，说明请求撤销行政保护所依据的事实和理由。"},{"i":21,"n":"第二十一条","txt":"化工部自收到撤销行政保护请求书后，应当进行审查。 撤销行政保护请求书中未写明撤销行政保护所依据的事实和理由或者提出的理由不符合本细则第十九条规定的，化工部不予受理。 化工部应当将受理的撤销行政保护请求书的副本和有关证明文件的副本送交农业化学物质产品独占权人，要求其在指定的期限内陈述意见。"},{"i":22,"n":"第二十二条","txt":"化工部行政保护评审办公室设置行政保护登记簿，对行政保护的申请和批准等有关事项进行登记。"},{"i":23,"n":"第二十三条","txt":"条例和本细则规定的公告事项，在化工部发布公告后，一律刊登在《中国化工报》上。"},{"i":24,"n":"第二十四条","txt":"向化工部申请行政保护和办理其他手续，应当缴纳下列费用： （一）申请费； （二）审查费； （三）证书费、公告费； （四）年费； （五）撤销请求费； （六）侵权处理费。 上述各种费用数额， 由化工部另行规定。"},{"i":25,"n":"第二十五条","txt":"申请人应当在递交农业化学物质产品行政保护申请书的同时缴纳申请费，在收到受理通知书之日起一个月内缴纳审查费，无正当理由逾期未缴纳或者未缴足的，其申请被视为撤回。"},{"i":26,"n":"第二十六条","txt":"农业化学物质产品独占权人应当在行政保护证书颁发之日起一个月内缴纳证书费、公告费和当年的年费；行政保护持续期间，应当于每年度最初的两个月内缴纳当年的年费，无正当理由逾期未缴纳或者未缴足的，视为自动放弃行政保护。"},{"i":27,"n":"第二十七条","txt":"依照条例第十六条请求化工部撤销行政保护的，应当在递交撤销行政保护请求书的同时缴纳撤销请求费。"},{"i":28,"n":"第二十八条","txt":"依照条例第十八条规定，请求化工部制止未获得农业化学物质产品行政保护的独占权人的许可在中国制造或者销售该产品的，应当在递交行政保护侵权处理请求书的同时缴纳侵权处理费。"},{"i":29,"n":"第二十九条","txt":"本细则第二十四条规定的各种费用由代理机构代收。"},{"i":30,"n":"第三十条","txt":"本细则由化工部负责解释。"},{"i":31,"n":"第三十一条","txt":"本细则自 1993 年 1 月 1 日起施行。"}],"nongyejixiechanpinxiuligenghuantuihuozerenguiding":[{"i":1,"n":"第一条","txt":"为维护农业机械产品用户的合法权益，提高农业机械产品质量和售后服务质量，明确农业机械产品生产者、销售者、修理者的修理、更换、退货（以下简称为三包）责任，依照《中华人民共和国产品质量法》、《中华人民共和国农业机械化促进法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称农业机械产品（以下称农机产品），是指用于农业生产及其产品初加工等相关农事活动的机械、设备。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事农机产品的生产、销售、修理活动的，应当遵守本规定。"},{"i":4,"n":"第四条","txt":"农机产品实行谁销售谁负责三包的原则。 销售者承担三包责任，换货或退货后，属于生产者的责任的，可以依法向生产者追偿。 在三包有效期内，因修理者的过错造成他人损失的，依照有关法律和代理修理合同承担责任。"},{"i":5,"n":"第五条","txt":"本规定是生产者、销售者、修理者向农机用户承担农机产品三包责任的基本要求。国家鼓励生产者、销售者、修理者做出更有利于维护农机用户合法权益的、严于本规定的三包责任承诺。 销售者与农机用户另有约定的，销售者的三包责任依照约定执行，但约定不得免除依照法律、法规以及本规定应当履行的义务。"},{"i":6,"n":"第六条","txt":"国务院工业主管部门负责制定并组织实施农业机械工业产业政策和有关规划。国务院产品质量监督部门、工商行政管理部门、农业机械化主管部门在各自职责范围内按照本规定的要求，根据生产者的三包凭证样本、产品使用说明书以及农机用户投诉等，建立信息披露制度，对生产者、销售者和修理者的三包承诺、农机用户集中反映的农机产品质量问题和服务质量问题向社会进行公布，督促生产者、销售者、修理者改进产品质量和服务质量。"},{"i":7,"n":"第七条","txt":"生产者应当建立农机产品出厂记录制度，严格执行出厂检验制度，未经检验合格的农机产品，不得销售。 依法实施生产许可证管理或强制性产品认证管理的农机产品，应当获得生产许可证证书或认证证书并施加生产许可证标志或认证标志。"},{"i":8,"n":"第八条","txt":"农机产品应当具有产品合格证、产品使用说明书、产品三包凭证等随机文件： （一）产品使用说明书应当按照农业机械使用说明书编写规则的国家标准或行业标准规定的要求编写，并应列出该机中易损件的名称、规格、型号；产品所具有的使用性能、安全性能，未列入国家标准的，其适用范围、技术性能指标、工作条件、工作环境、安全操作要求、警示标志或说明应当在使用说明书中明确； （二）有关工具、附件、备件等随附物品的清单； （三）农机产品三包凭证应当包括以下内容：产品品牌、型号规格、生产日期、购买日期、产品编号，生产者的名称、联系地址和电话，已经指定销售者、修理者的，应当注明名称、联系地址、电话、三包项目、三包有效期、销售记录、修理记录和按照本规定"},{"i":9,"n":"第二十四条","txt":"规定应当明示的内容等相关信息；销售记录应当包括销售者、销售地点、销售日期和购机发票号码等项目；修理记录应当包括送修时间、交货时间、送修故障、修理情况、换退货证明等项目。"},{"i":10,"n":"第九条","txt":"生产者应当在销售区域范围内建立农机产品的维修网点，与修理者签订代理修理合同，依法约定农机产品三包责任等有关事项。"},{"i":11,"n":"第十条","txt":"生产者应当保证农机产品停产后五年内继续提供零部件。"},{"i":12,"n":"第十一条","txt":"生产者应当妥善处理农机用户的投诉、查询，提供服务，并在农忙季节及时处理各种农机产品三包问题。"},{"i":13,"n":"第十二条","txt":"销售者应当执行进货检查验收制度，严格审验生产者的经营资格，仔细验明农机产品合格证明、产品标识、产品使用说明书和三包凭证。对实施生产许可证管理、强制性产品认证管理的农机产品，应当验明生产许可证证书和生产许可证标志、认证证书和认证标志。"},{"i":14,"n":"第十三条","txt":"销售者销售农机产品时，应当建立销售记录制度，并按照农机产品使用说明书告知以下内容： （一）农机产品的用途、适用范围、性能等； （二）农机产品主机与机具间的正确配置； （三）农机产品已行驶的里程或已工作时间及使用的状况。"},{"i":15,"n":"第十四条","txt":"销售者交付农机产品时，应当符合下列要求： （一）当面交验、试机； （二）交付随附的工具、附件、备件； （三）提供财政税务部门统一监制的购机发票、三包凭证、中文产品使用说明书及其它随附文件； （四）明示农机产品三包有效期和三包方式； （五）提供由生产者或销售者授权或委托的修理者的名称、联系地址和电话； （六）在三包凭证上填写销售者有关信息； （七）进行必要的操作、维护和安全注意事项的培训。 对于进口农机产品，还应当提供海关出具的货物进口证明和检验检疫机构出具的入境货物检验检疫证明。"},{"i":16,"n":"第十五条","txt":"销售者可以同修理者签订代理修理合同，在合同中约定三包有效期内的修理责任以及在农忙季节及时排除各种农机产品故障的措施。"},{"i":17,"n":"第十六条","txt":"销售者应当妥善处理农机产品质量问题的咨询、查询和投诉。"},{"i":18,"n":"第十七条","txt":"修理者应当与生产者或销售者订立代理修理合同，按照合同的约定，保证修理费用和维修零部件用于三包有效期内的修理。 代理修理合同应当约定生产者或销售者提供的维修技术资料、技术培训、维修零部件、维修费、运输费等。"},{"i":19,"n":"第十八条","txt":"修理者应当承担三包期内的属于本规定范围内免费修理业务，按照合同接受生产者、销售者的监督检查。"},{"i":20,"n":"第十九条","txt":"修理者应当严格执行零部件的进货检查验收制度，不得使用质量不合格的零部件，认真做好维修记录，记录修理前的故障和修理后的产品质量状况。"},{"i":21,"n":"第二十条","txt":"修理者应当完整、真实、清晰地填写修理记录。修理记录内容应当包括送修时间、送修故障、检查结果、故障原因分析、维护和修理项目、材料费和工时费，以及运输费、农机用户签名等；有行驶里程的，应当注明。"},{"i":22,"n":"第二十一条","txt":"修理者应当向农机用户当面交验修理后的农机产品及修理记录，试机运行正常后交付其使用，并保证在维修质量保证期内正常使用。"},{"i":23,"n":"第二十二条","txt":"修理者应当保持常用维修零部件的合理储备，确保维修工作的正常进行，避免因缺少维修零部件而延误维修时间。农忙季节应当有及时排除农机产品故障的能力和措施。"},{"i":24,"n":"第二十三条","txt":"修理者应当积极开展上门修理和电话咨询服务，妥善处理农机用户关于修理的查询和修理质量的投诉。"},{"i":25,"n":"第二十四条","txt":"农机产品的三包有效期自销售者开具购机发票之日起计算，三包有效期包括整机三包有效期，主要部件质量保证期，易损件和其它零部件的质量保证期。 内燃机、拖拉机、联合收割机、插秧机的整机三包有效期及其主要部件的质量保证期应当不少于本规定附件 1 规定的时间。内燃机单机作为商品出售给农机用户的，计为整机，其包含的主要零部件由生产者明示在三包凭证上。拖拉机、联合收割机、插秧机的主要部件由生产者明示在三包凭证上。 其他农机产品的整机三包有效期及其主要部件或系统的名称和质量保证期，由生产者明示在三包凭证上，且有效期不得少于一年。 内燃机作为农机产品配套动力的，其三包有效期和主要部件的质量保证期按农机产品的整机的三包有效期和主要部件质量保证期执行。 农机产品的易损件及其它零部件的质量保证期达不到整机三包有效期的，其所属的部件或系统的名称和合理的质量保证期由生产者明示在三包凭证上。"},{"i":26,"n":"第二十五条","txt":"农机用户丢失三包凭证，但能证明其所购农机产品在三包有效期内的，可以向销售者申请补办三包凭证，并依照本规定继续享受有关权利。销售者应当在接到农机用户申请后 10 个工作日内予以补办。销售者、生产者、修理者不得拒绝承担三包责任。 由于销售者的原因，购机发票或三包凭证上的农机产品品牌、型号等与要求三包的农机产品不符的，销售者不得拒绝履行三包责任。 在三包有效期内发生所有权转移的，三包凭证和购机发票随之转移，农机用户凭原始三包凭证和购机发票继续享有三包权利。"},{"i":27,"n":"第二十六条","txt":"三包有效期内，农机产品出现质量问题，农机用户凭三包凭证在指定的或者约定的修理者处进行免费修理，维修产生的工时费、材料费及合理的运输费等由三包责任人承担；符合本规定换货、退货条件，农机用户要求换货、退货的，凭三包凭证、修理记录、购机发票更换、退货；因质量问题给农机用户造成损失的，销售者应当依法负责赔偿相应的损失。"},{"i":28,"n":"第二十七条","txt":"三包有效期内，农机产品存在本规定范围的质量问题的，修理者一般应当自送修之日起 30 个工作日内完成修理工作，并保证正常使用。"},{"i":29,"n":"第二十八条","txt":"三包有效期内，送修的农机产品自送修之日起超过 30 个工作日未修好，农机用户可以选择继续修理或换货。要求换货的，销售者应当凭三包凭证、维护和修理记录、购机发票免费更换同型号同规格的产品。"},{"i":30,"n":"第二十九条","txt":"三包有效期内，农机产品因出现同一严重质量问题，累计修理 2 次后仍出现同一质量问题无法正常使用的；或农机产品购机的第一个作业季开始 30 日内，除因易损件外，农机产品因同一一般质量问题累计修理 2 次后，又出现同一质量问题的，农机用户可以凭三包凭证、维护和修理记录、购机发票，选择更换相关的主要部件或系统，由销售者负责免费更换。"},{"i":31,"n":"第三十条","txt":"三包有效期内或农机产品购机的第一个作业季开始 30 日内，农机产品因本规定第二十九条的规定更换主要部件或系统后，又出现相同质量问题，农机用户可以选择换货，由销售者负责免费更换；换货后仍然出现相同质量问题的，农机用户可以选择退货，由销售者负责免费退货。"},{"i":32,"n":"第三十一条","txt":"三包有效期内，符合本规定更换主要部件的条件或换货条件的，销售者应当提供新的、合格的主要部件或整机产品，并更新三包凭证，更换后的主要部件的质量保证期或更换后的整机产品的三包有效期自更换之日起重新计算。 符合退货条件或因销售者无同型号同规格产品予以换货，农机用户要求退货的，销售者应当按照购机发票金额全价一次退清货款。"},{"i":33,"n":"第三十二条","txt":"因生产者、销售者未明确告知农机产品的适用范围而导致农机产品不能正常作业的，农机用户在农机产品购机的第一个作业季开始 30 日内可以凭三包凭证和购机发票选择退货，由销售者负责按照购机发票金额全价退款。"},{"i":34,"n":"第三十三条","txt":"整机三包有效期内，联合收割机、拖拉机、播种机、插秧机等产品在农忙作业季节出现质量问题的，在服务网点范围内，属于整机或主要部件的，修理者应当在接到报修后 3 日内予以排除；属于易损件或是其他零件的质量问题的，应当在接到报修后 1 日内予以排除。在服务网点范围外的，农忙季节出现的故障修理由销售者与农机用户协商。 国家鼓励农机产品生产者、销售者、修理者农忙时期开展现场的有关售后服务活动。"},{"i":35,"n":"第三十四条","txt":"三包有效期内，销售者不履行三包义务的，或者农机产品需要进行质量检验或鉴定的，三包有效期自农机用户的请求之日起中止计算，三包有效期按照中止的天数延长；造成直接损失的，应当依法赔偿。"},{"i":36,"n":"第三十五条","txt":"农机用户应当按照有关规定和农机产品的使用说明书进行操作或使用。"},{"i":37,"n":"第三十六条","txt":"赠送的农机产品，不得免除生产者、销售者和修理者依法应当承担的三包责任。"},{"i":38,"n":"第三十七条","txt":"销售者、生产者、修理者能够证明发生下列情况之一的，不承担三包责任： （一）农机用户无法证明该农机产品在三包有效期内的； （二）产品超出三包有效期的。"},{"i":39,"n":"第三十八条","txt":"销售者、生产者、修理者能够证明发生下列情况之一的，对于所涉及部分，不承担三包责任： （一）因未按照使用说明书要求正确使用、维护，造成损坏的； （二）使用说明书中明示不得改装、拆卸，而自行改装、拆卸改变机器性能或者造成损坏的； （三）发生故障后，农机用户自行处置不当造成对故障原因无法做出技术鉴定的； （四）因非产品质量原因发生其他人为损坏的； （五）因不可抗力造成损坏的。"},{"i":40,"n":"第三十九条","txt":"产品质量监督部门、工商行政管理部门、农业机械化主管部门应当认真履行三包有关质量问题监管职责。 生产者未按照本规定第二十四条履行明示义务的，或通过明示内容有意规避责任的，由产品质量监督部门依法予以处理。 销售者未按照本规定履行三包义务的，由工商行政管理部门依法予以处理。 维修者未按照本规定履行三包义务的，由农业机械化主管部门依法予以处理。"},{"i":41,"n":"第四十条","txt":"农机用户因三包责任问题与销售者、生产者、修理者发生纠纷的，可以按照公平、诚实、信用的原则进行协商解决。 协商不能解决的，农机用户可以向当地工商行政管理部门、产品质量监督部门或者农业机械化主管部门设立的投诉机构进行投诉，或者依法向消费者权益保护组织等反映情况，当事人要求调解的，可以调解解决。"},{"i":42,"n":"第四十一条","txt":"因三包责任问题协商或调解不成的，农机用户可以依照《中华人民共和国仲裁法》的规定申请仲裁，也可以直接向人民法院起诉。"},{"i":43,"n":"第四十二条","txt":"需要进行质量检验或者鉴定的，农机用户可以委托依法取得资质的农机产品质量检验机构进行质量检验或者鉴定。 质量检验或者鉴定所需费用按照法律、法规的规定或者双方约定的办法解决。"},{"i":44,"n":"第四十三条","txt":"本规定下列用语的含义： 本规定所称质量问题，是指在合理使用的情况下，农机产品的使用性能不符合产品使用说明中明示的状况；或者农机产品不具备应当具备的使用性能；或者农机产品不符合生产者在农机或其包装上注明执行的产品标准。质量问题包括： （一）严重质量问题，是指农机产品的重要性能严重下降，超过有关标准要求或明示的范围；或者农机产品主要部件报废或修理费用较高，必须更换的；或者正常使用的情况下农机产品自身出现故障影响人身安全的质量问题。 （二）一般质量问题，是指除严重质量问题外的其他质量问题，包括易损件的质量问题，但不包括农机用户按照农机产品使用说明书的维修、保养、调整或检修方法能用随机工具可以排除的轻度故障。 内燃机、拖拉机、联合收割机、插秧机严重质量问题见本规定附件 2 。 本规定所称农业机械产品用户（简称农机用户），是指为从事农业生产活动购买、使用农机产品的公民、法人和其他经济组织。 本规"},{"i":45,"n":"第四十四条","txt":"农机产品因用于非农业生产活动而出现的质量问题符合法律规定的有关修理、更换或退货条件的，可以参照本规定执行。"},{"i":46,"n":"第四十五条","txt":"本规定由国家质量监督检验检疫总局、国家工商行政管理总局、农业部、工业和信息化部按职责分工负责解释。"},{"i":47,"n":"第四十六条","txt":"本规定自 2010 年 6 月 1 日 起施行。 1998 年 3 月 12 日 原国家经济贸易委员会、国家技术监督局、国家工商行政管理局、国内贸易部、机械工业部、农业部发布的《农业机械产品修理、更换、退货责任规定》（国经贸质 [1998]123 号）同时废止。 附件：三包有效期以及主要部件的名称、质量保证期.wps 内燃机、拖拉机、联合收割机、插秧机严重质量问题表 .wps"}],"weixingyidongtongxinxitongzhongduandiqiuzhanguanlid846b5":[{"i":1,"n":"第一条","txt":"为了规范卫星移动通信系统终端地球站的设置使用，避免和减少卫星移动通信系统之间、卫星移动通信系统与其他无线电业务系统之间的干扰，根据《中华人民共和国无线电管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设置使用卫星移动通信系统终端地球站，适用本办法。 本办法所称卫星移动通信系统终端地球站（以下简称“移动地球站”），是指使用卫星移动业务频率的卫星移动通信系统中民用 的船载终端、航空器载终端、车载终端、固定终端、便携式终端和手持机。"},{"i":3,"n":"第三条","txt":"设置使用移动地球站的，应当使用 中华人民共和国 工业和信息化部 （以下简称“工业和信息化部”） 批准 的 卫星移动通信系统 或者 卫星移动业务频率 ，通过工业和信息化部批准的境内关口地球站 进行通信，并通过国家批准的在境内经营卫 星移动通信业务的服务提供者（以下简称“境内经营者”）办理入网手续。但是，本办法另有规定的除外。"},{"i":4,"n":"第四条","txt":"设置使用卫星移动通信系统车载终端、固定终端、便携式终端和手持机（以下统称“陆地移动地球站”）的，应当按照本办法的规定向无线电管理机构申请办理无线电台注册登记手续，领取电台执照。 在具有中华人民共和国 国籍 的船舶或者航空器上设置使用卫星移动通信系统船载终端、航空器载终端的，应当按照《中华人民共和国无线电管理条例》的规定办理设置使用无线电台手续，领取电台执照。"},{"i":5,"n":"第五条","txt":"工业和信息化部委托省、自 治区、直辖市无线电管理机构负责受理陆地移动地球站无线电台注册登记手续的申请 ，核发电台执照。"},{"i":6,"n":"第六条","txt":"陆地移动地球站的设置使用人可以自行办理无线电台注册登记手续，也可以委托为其办理入网手续的境内经营者代办。"},{"i":7,"n":"第七条","txt":"陆地移动地球站的设置使用人或者其代理人应当向设置使用人住所地的省、自治区、直辖市无线电管理机构申请办理无线电台注册登记手续，领取电台执照。 申请办理无线电台注册登记手续，应当提交下列材料： （一）《移动地球站注册登记申请表》（附录一）； （二） 单位证明或者个人身份证明材料的 原件、复印件或者扫描 件 ； （三）已办理相关卫星移动通信系统入网手续的证明材料的原件、复印件或者扫描件。 受理单位在验证前款第二项、第三项材料的真实性后应当及时将原件退还申请人。 申请人可以通过受理单位 指 定的信息系统，进行网上申请。"},{"i":8,"n":"第八条","txt":"申请材料不全、不符合法定形式的，无线电管理机构应当当场或者在五个工作日内一次告知申请人需要补正的全部内容。 申请材料齐全、符合法定形式和本办法规定的，无线电管理机构应当当场或者在二十个工作日内核发电台执照；不符合规定条件的，应当书面通知申请人不予核发电台执照并说明理由。"},{"i":9,"n":"第九条","txt":"变更已领取电台执照的陆地移动地球站的设备或者使用人的，应当按照本办法的规定重新办理无线电台注册登记手续，换发电台执照。 停止使用已领取电台执照的陆地移动地球站的，应当到原发照机构办理注销手续，交回电台执照，并告知设备处理情况。"},{"i":10,"n":"第十条","txt":"无线电管理机构应当自核发、换发或者注销电台执照之日起三十日内，将相关陆地移动地球站的有关资料和电台执照编号录入工业和信息化部的无线电管理相关数据库。"},{"i":11,"n":"第十一条","txt":"境内经营者入网开通各种类型或者型号的陆地移动地球站设备，应当提前四十五日填写《移动地球站技术资料备案表》（附录二），报工业和信息化部备案。 资料齐备、真实的，工业和信息化部应当在相关设备入网使用前将上述陆地移动地球站技术资料录入工业和信息化部无线电管理相关数据库，并通知各省、自治区、直辖市无线电管理机构。"},{"i":12,"n":"第十二条","txt":"境内经营者为陆地移动地球站设置使用人办理入网手续，应当告知其需按照本办法的规定办理无线电台注册登记手续，领取电台执照。"},{"i":13,"n":"第十三条","txt":"境内经营者应当按照工业和信息化部的要求报送系统中移动地球站的有关资料，配合无线电管理机构对系统中移动地球站进行 的监督 管理。"},{"i":14,"n":"第十四条","txt":"应对突发事件、 危及人民生命财产安全等紧急情况的，可以临时设置使用未取得电台执照的陆地移动地球站，但是应当及时向临时设置使用地的省、自治区、直辖市无线电管理机构报告。紧急情况解除后需要继续使用的，应当按照本办法的规定办理无线电台注册登记手续，领取电台执照。"},{"i":15,"n":"第十五条","txt":"临时设置使用移动地球站，涉及使用未经批准的卫星移动通信系统或者卫星移动业务频率的，应当向工业和信息化部提出申请。经审查批准、领取电台执照后方可设置使用，使用期限不得超过六个月。"},{"i":16,"n":"第十六条","txt":"境外短期来华的团体和个人拟临时入境使用已在境外办理入网手续的陆地移动地球站的，由国内接待单位或者对口的业务主管部门向工业和信息化部提交书面申请、使用人身份证明材料和相关技术材料。经审查批准、领取电台执照后方可在境内设置使用，使用期限不得超过六个月。"},{"i":17,"n":"第十七条","txt":"外国船载、航空器载移动地球站需要在我国境内使用的， 其 使用的频率应当经工业和信息化部批准 ，并遵守 中华人民共和国 缔结或者参加的国际条约和 中华人民共和国 的 法律 规定。"},{"i":18,"n":"第十八条","txt":"移动地球站的设置使用人，应当接受无线电管理机构对其使用的设备和无线电台执照的核验和监督检查。"},{"i":19,"n":"第十九条","txt":"违反本办法第三条、第十五条、第十六条规定，擅自设置使用陆地移动地球站的， 按照 《中华人民共和国无线电管理条例》 第四十三条的 规定处罚。"},{"i":20,"n":"第二十条","txt":"违反本办法第四条第一款、第九条第一款规定的，由有关省、自治区、直辖市无线电管理机构责令限期改正；逾期不改的，按照《中华人民共和国无线电管理条例》 第四十三条的 规定处罚。"},{"i":21,"n":"第二十一条","txt":"各国驻中华人民共和国使（领）馆和享有外交特权与豁免的国际组织驻中华人民共和国的代表机构设置使用移动地球站、外国领导人访华临时设置使用移动地球站的，应当事先通过外交途径向工业和信息化部提出申请。"},{"i":22,"n":"第二十二条","txt":"本办法自 2011 年 6 月 1 日起施行。 附录一：移动地球站注册登记申请表.wps 附录二：移动地球站技术资料备案表.wps"}],"geleijiankonghuaxuepinminglu":[],"guofangkexuejishujianglibanfa-2":[{"i":1,"n":"第一条","txt":"为了奖励在推动国防科学技术进步中做出突出贡献的 单位和个人 ，鼓励自主创新，促进国防现代化建设和国民经济的发展，根据《国家科学技术奖励条例》及其实施细则，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国工业和信息化部（以下简称工业和信息化部）设立 下列 国防科学技术奖： （一）国防技术发明奖； （二）国防科学技术进步奖； （三） 国防科技工业杰出人才奖 。"},{"i":3,"n":"第三条","txt":"国防科学技术奖励工作贯彻 “ 尊重劳动、尊重知识、尊重人才、尊重创造 ” 的方针，坚持精神奖励与物质奖励相结合的原则。"},{"i":4,"n":"第四条","txt":"为了维护国防科学技术奖的严肃性，国防科学技术奖的评审、授予，不受任何组织和个人的非法干涉。"},{"i":5,"n":"第五条","txt":"国防科学技术奖的评审和管理工作要严格保守国家秘密，尊重和保护知识产权。"},{"i":6,"n":"第六条","txt":"国防技术发明奖授予在国防建设和因保密不能公开的军民结合技术开发中运用科学技术知识做出产品、工艺、材料及其系统等技术发明成果的单位和个人。 前款所称技术发明成果应当具备下列条件： （一）前人尚未发明或者尚未公开； （二）具有先进性和创造性； （三）经实施，创造显著的军事效益、社会效益或者经济效益。"},{"i":7,"n":"第七条","txt":"国防科学技术进步奖授予在完成下列创新科技成果中做出突出贡献的单位和个人： （一）在武器装备及其配套产品的科研、生产、试验及相关工作中取得的科技成果； （二）在军民结合高技术产业的型号工程及技术、产品开发和成果转化中取得的因保密不能公开的科技成果； （三）在国防基础性技术研究中取得的科技成果； （四）在为决策科学化和管理现代化而进行的国防科技工业软科学研究中取得的科技成果。"},{"i":8,"n":"第八条","txt":"国防科技工业杰出人才奖授予在国防科学技术研究和技术开发中做出杰出贡献的下列科学技术工作者： （一）在当代国防科学技术前沿取得重大突破或者在国防科学技术发展中有卓越建树的； （二）在国防科学技术研究、型号研制和军民结合高技术产业化等领域及重大工程建设项目中，取得重大创新性成果，创造显著军事效益、社会效益或者经济效益的。 国防科技工业杰出人才奖的推荐、评审、授予等具体办法另行制定。"},{"i":9,"n":"第九条","txt":"国防技术发明奖和国防科学技术进步奖分为特等奖、一等奖、二等奖、三等奖 4 个等级。"},{"i":10,"n":"第十条","txt":"国防技术发明奖和国防科学技术进步奖实行限额申报、限额授奖，每年评审一次。"},{"i":11,"n":"第十一条","txt":"工业和信息化部设立国防科学技术奖励委员会 ( 以下简称奖励委员会 ) ，负责国防科学技术奖的管理。 国防科学技术奖评审的组织工作，委托国家国防科技工业局（以下简称国防科工局）负责。"},{"i":12,"n":"第十二条","txt":"奖励委员会的主要职责： ( 一 ) 审定国防科学技术奖励项目评审结果； ( 二 ) 监督国防科学技术奖励项目的申报、评审和异议处理工作； ( 三 ) 对国防科学技术奖励工作提供政策性意见和建议。"},{"i":13,"n":"第十三条","txt":"奖励委员会由 19-23 人组成。主任由工业和信息化部部级领导担任。成员分别由国防科技领域的专家和有关行政主管部门的负责同志组成。组成人选由工业和信息化部相关司局提出，征求国防科工局意见后，由工业和信息化部批准。 奖励委员会实行聘任制，每届任期三年。"},{"i":14,"n":"第十四条","txt":"奖励委员会下设评审委员会 ， 主要职责： （一）对各专业评审委员会初评通过的国防科学技术奖项目进行评审； （二）向奖励委员会报告国防科学技术奖励项目的评审结果； （三）向奖励委员会报告国防科学技术奖励项目的申报、评审和异议处理情况； （四） 协调处理重大异议及评审工作中出现的其他问题。"},{"i":15,"n":"第十五条","txt":"评审委员会由 25-29 人组成。主任由国防科工局负责同志担任，委员分别由各专业评审委员会主任、本专业专家，以及行政主管部门负责同志组成。评审委员会成员由国防科工局批准。"},{"i":16,"n":"第十六条","txt":"根据工作需要，评审委员会可设若干专业评审委员会 ， 负责相应专业的国防科学技术奖 励 项目的初评。各专业评审委员会成员由国防科工局批准。"},{"i":17,"n":"第十七条","txt":"奖励委员会的日常工作由工业和信息化部相关司局承担，评审委员会、专业评审委员会的日常工作由国防科工局负责。"},{"i":18,"n":"第十八条","txt":"国防技术发明奖和国防科学技术进步奖的项目不得重复申报。已申报国家级或其他省部级科技奖励的项目，不得再申报国防技术发明奖或国防科学技术进步奖。同一技术内容不能同时申报国防技术发明奖和国防科学技术进步奖。 在技术上又取得重大进步或新的突破的，可就其进步或突破的部分申报国防技术发明奖或国防科学技术进步奖。"},{"i":19,"n":"第十九条","txt":"申报国防技术发明奖和国防科学技术进步奖项 目 必须按规定格式填写相应的《国防科学技术奖申报书》，并提供所要求的附件材料及相应的电子文档。提供的有关材料必须真实、可靠。"},{"i":20,"n":"第二十条","txt":"申报国防技术发明奖和国防科学技术进步奖的材料应按下列渠道报送： （一）军工集团公司负责对其所属单位申报项目材料进行审查后，统一报送国防科工局。 （二）各省、自治区、直辖市国防科学技术工业行政主管部门，负责对本地区承担军工任务的地方单位申报项目材料审查后，统一报送国防科工局。 （三）工业和信息化部所属单位和国防科工局所属单位对申报项目材料审查后，直接报送国防科工局； （四）其他企事业单位申报项目材料，由其主管部门（单位）审查后报送国防科工局。"},{"i":21,"n":"第二十一条","txt":"国防技术发明奖和国防科学技术进步奖的奖励等级按下列指标进行综合评定： （一）自主创新程度； （二）难易程度、复杂程度； （三）先进程度； （四）成熟性、完备性； （五）综合效益（军事效益、社会效益、经济效益）； （六）应用情况与效果、科学技术价值。"},{"i":22,"n":"第二十二条","txt":"申报国防技术发明奖和国防科学技术进步奖的项目，由国防科工局进行形式审查后，按所属专业划分到相应的专业评审委员会进行初评。"},{"i":23,"n":"第二十三条","txt":"专业评审委员会的初评结果应在适当范围内公布。自公布之日起 50 日内为异议期。自公布之日起 70 日内异议处理完毕的，继续参加本年度评审；自公布之日起一年内异议处理完毕的，提交下一年度评审；自公布之日起一年后异议处理完毕的，可以重新申报。"},{"i":24,"n":"第二十四条","txt":"经过异议程序后，各专业评审委员会的初评结果，提交评审委员会进行评审。"},{"i":25,"n":"第二十五条","txt":"评审委员会对初评通过的奖励项目进行评审后，将评审结果，以及奖励项目和奖励等级的建议提交奖励委员会审定，并向奖励委员会报告申报、评审和异议处理工作情况。"},{"i":26,"n":"第二十六条","txt":"奖励委员会对评审结果，以及获奖人选和奖励等级的建议进行审定。符合授奖条件的项目，由工业和信息化部批准授奖，向获奖人员和单位颁发奖励证书，并按有关规定颁发奖金。"},{"i":27,"n":"第二十七条","txt":"国防技术发明奖和国防科学技术进步奖采取评委集体讨论、投票的方法进行评审。特等奖和一等奖项目，应有投票人数三分之二 及 以上的票数通过；二等奖和三等奖项目，应有投票人数五分之三 及 以上的票数通过。 奖励委员会、评审委员会和专业评审委员会的评审表决应当有三分之二以上多数 ( 含三分之二 ) 委员参加，表决结果方有效。"},{"i":28,"n":"第二十八条","txt":"国防技术发明奖和国防科学技术进步奖的评审实行回避制度。被评项目的完成人或来自项目完成单位的人员是评委的，在该项目讨论和投票时均应回避。"},{"i":29,"n":"第二十九条","txt":"获奖人员的情况及主要贡献，应记入本人档案，作为综合考核、评价科技人员的依据之一。"},{"i":30,"n":"第三十条","txt":"奖金应按完成单位、完成人的贡献大小进行合理分配，不得挪作它用。"},{"i":31,"n":"第三十一条","txt":"国防科学技术奖的奖金数额由国防科工局商请财政部规定。国防科学技术奖的奖励经费由中央财政列支。"},{"i":32,"n":"第三十二条","txt":"在异议期内，任何单位和个人都有权对公布国防技术发明奖和国防科学技术进步奖项目的内容真实性、成果权属、获奖资格、完成单位和完成人及其排序等问题提出异议。"},{"i":33,"n":"第三十三条","txt":"对公布国防技术发明奖和国防科学技术进步奖项目提出异议的，要填写异议书，并提供必要的证明材料。有下列情况之一的不予受理： （一）匿名的异议； （二）无正当理由超过异议期提出的异议； （三）关于奖励等级的异议。"},{"i":34,"n":"第三十四条","txt":"申报单位内部提出的异议，由申报单位负责处理；军工集团公司所属单位间的异议由军工集团公司负责处理；各军工集团公司之间的异议，以及其他的单位和个人提出的异议，由国防科工局负责处理。 必要时，国防科工局可以组织评审委员和专家对重大异议进行调查，提出处理意见。"},{"i":35,"n":"第三十五条","txt":"对于剽窃、侵占他人科技成果的，或者以其他不正当手段骗取国防科学技术奖的，经工业和信息化部批准后撤销其奖励，追回奖励证书和奖金，并建议其主管部门或单位依法给予处分。"},{"i":36,"n":"第三十六条","txt":"参与国防科学技术奖评审活动和有关工作的人员在评审活动中弄虚作假、徇私舞弊的，建议有关部门或单位依法给予处分。"},{"i":37,"n":"第三十七条","txt":"本办法的实施细则由国防科工局负责制定。"},{"i":38,"n":"第三十八条","txt":"本办法自 2010 年 7 月 1 日起施行。2006 年 12 月 27 日 发布的《国防科学技术奖励办法》（国防科学技术工业委员会令第 19 号）同时废止。"}],"guofangkexuejishugongyeweiyuanhuitingzhengguize":[{"i":1,"n":"第一条","txt":"为了规范听证行为，维护公民、法人和其他组织的合法权益，促进依法行政，根据有关法律、行政法规，制定本规则。"},{"i":2,"n":"第二条","txt":"国防科学技术工业委员会（以下简称国防科工委）根据当事人的申请组织的听证和依据职权主动组织的听证适用本规则。 本规则所称当事人，包括行政处罚当事人、行政许可申请人和行政许可利害关系人。"},{"i":3,"n":"第三条","txt":"听证应当遵循公平、公正、便民和效率的原则。除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。"},{"i":4,"n":"第四条","txt":"依据当事人申请组织的听证，由法制工作机构负责实施；依据职权主动组织的听证，由听证事项承办部门负责实施。"},{"i":5,"n":"第五条","txt":"听证不得向当事人收取或者变相收取任何费用。"},{"i":6,"n":"第六条","txt":"听证人员包括听证主持人、听证员和记录员。 听证主持人由听证组织部门的有关负责人担任并报委领导批准，负责主持听证会。 听证员、记录员由听证组织部门指定，协助听证主持人工作。 行政处罚或者行政许可听证事项的具体承办人员，不得作为听证主持人、听证员和记录员。"},{"i":7,"n":"第七条","txt":"听证由一名听证主持人、两名听证员组织，也可视具体情况由一名听证主持人组织。"},{"i":8,"n":"第八条","txt":"听证人员应当公正地履行职责，保证听证参加人行使陈述、申辩、质证等权利，对听证中知悉的国家秘密、商业秘密和个人隐私负有保密的义务。"},{"i":9,"n":"第九条","txt":"当事人认为听证人员与听证事项有利害关系可能影响公正的，有权申请回避，并说明理由。 听证主持人的回避由委领导决定；听证员和记录员的回避由听证组织部门决定。"},{"i":10,"n":"第十条","txt":"听证参加人包括行政处罚或者行政许可事项的具体承办人、当事人、听证会代表、鉴定人、证人、翻译人员等。 听证参加人应当按时参加听证会，服从听证主持人指挥，遵守听证会纪律。"},{"i":11,"n":"第十一条","txt":"当事人可以委托一至二名代理人参加听证，收集、提供相关材料和证据，进行质证和申辩。"},{"i":12,"n":"第十二条","txt":"当事人在听证中享有以下权利： （一）知悉作出行政处罚或行政许可的事实、证据和法律依据； （二）申请听证人员的回避； （三）陈述主张和理由，提出证据； （四）进行质证和申辩； （五）依法享有的其他权利。 听证会代表在听证中享有以下权利： （一）知悉听证事项的情况； （二）对听证内容发表意见； （三）进行质询。"},{"i":13,"n":"第十三条","txt":"行政处罚或行政许可事项承办部门在作出行政决定前，有下列情形之一的，应当书面告知当事人有申请举行听证的权利： （一）作出责令停产停业、吊销许可证或者执照、 3 万元以上（不含 3 万元）罚款等行政处罚决定的； （二）行政许可直接涉及申请人与他人之间重大利益关系的； （三）法律、行政法规或者规章规定的其他情形。"},{"i":14,"n":"第十四条","txt":"行政许可事项当事人应当自收到书面告知之日起 5 日内，行政处罚事项当事人应当自收到书面告知之日起 3 日内，向国防科工委法制工作机构提出书面听证申请。 逾期未提出的，视为放弃听证。"},{"i":15,"n":"第十五条","txt":"听证申请应当包括以下内容： （一）申请人的名称，住所，联系方式； （二）申请听证的具体事项； （三）申请听证的依据、理由及其他证明材料。"},{"i":16,"n":"第十六条","txt":"法制工作机构收到听证书面申请后，应当对申请材料进行审查，并根据下列情况作出处理： （一）申请人不具备法定条件或者超过法定期限提出申请的，应当告知申请人不予受理，并书面说明理由； （二）申请材料不齐全的，应当一次告知申请人补正全部材料； （三）申请人符合法定条件，申请材料齐全、申请事项符合听证条件的，受理听证申请。"},{"i":17,"n":"第十七条","txt":"法制工作机构受理听证申请，应当制作听证通知书，并于举行听证 7 日前送达申请人和行政处罚或者行政许可事项承办部门。 听证通知书应当载明下列事项： （一）听证的事由、依据； （二）听证的时间、地点； （三）听证人员的姓名、职务； （四）当事人的权利和义务； （五）其他注意事项。 听证事项涉及其他公民、法人或者其他组织重大利益关系的，应当通知其参加听证。"},{"i":18,"n":"第十八条","txt":"当事人收到听证通知书后，无正当理由不参加听证的，或者未经听证主持人允许中途退出的，视为放弃听证。放弃听证的，记入听证笔录。"},{"i":19,"n":"第十九条","txt":"听证会开始前，记录员应当查明听证参加人的身份和到场情况，宣布听证纪律和听证会场有关注意事项。"},{"i":20,"n":"第二十条","txt":"听证会按下列程序进行： （一）听证主持人宣布听证开始，宣布听证事由和听证人员名单； （二）告知听证参加人的权利和义务，询问当事人是否申请回避； （三）行政处罚或者行政许可事项承办部门陈述意见； （四）当事人进行质证、申辩； （五）听证主持人、听证员对听证参加人进行询问； （六）听证各方最后陈述； （七）听证主持人宣布听证会结束。"},{"i":21,"n":"第二十一条","txt":"记录员应当制作听证笔录。听证笔录应当载明下列事项： （一）听证时间、地点、事由； （二）听证人员的姓名、职务； （三）听证参加人的基本情况； （四）行政处罚或者行政许可事项承办部门的意见； （五）当事人辩论、申辩情况； （六）其他需要记载的事项。 听证笔录经听证参加人确认无误或者补正后当场签字或者盖章；拒绝签字或者盖章的，记录员应当记明情况附卷。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，可以延期举行听证： （一）因不可抗力的事由致使听证无法按期举行的； （二）当事人有正当理由申请延期的； （三）其他可以延期的情形。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，应当中止听证： （一）听证主持人认为听证过程中提出新的事实、理由和依据有待调查核实的； （二）申请听证的公民死亡、法人或者其他组织终止，尚未确定权利、义务承受人的； （三）其他应当中止听证的情形。"},{"i":24,"n":"第二十四条","txt":"延期听证和中止听证的，法制工作机构应当书面通知听证参加人。延期和中止听证的情形消失后，法制工作机构应当恢复听证，并书面通知听证参加人。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，应当终止听证： （一）申请听证的公民死亡，没有继承人，或者继承人放弃听证权利的； （二）申请听证的法人或者其他组织终止，承受其权利的法人或者组织放弃听证权利的； （三）申请人在听证过程中声明退出的； （四）其他应当终止听证的情形。"},{"i":26,"n":"第二十六条","txt":"听证会结束后，法制工作机构应当根据听证笔录，提出听证建议。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，承办部门应当报委领导批准后组织听证： （一）起草、修订的法律、行政法规和规章直接涉及公民、法人或者其他组织的切身利益，有关机关、组织或者公民对其有重大分歧意见的 ; （二）法律、行政法规和规章规定实施行政许可应当听证的事项，或者行政机关认为需要听证的其他涉及公共利益的重大行政许可事项； （三）作出涉及重大公共利益的行政决策前，认为需要听证的； （四）国防科工委认为需要听证的其他事项。"},{"i":28,"n":"第二十八条","txt":"承办部门应当在举行听证会 30 日前，向社会公告听证会的时间、地点、内容和申请参加的条件。"},{"i":29,"n":"第二十九条","txt":"符合规定条件的公民、法人和其他组织，可以申请参加听证会，也可以推选代表参加听证会。 承办部门根据听证事项情况及公民、法人和其他组织的申请情况，指定听证会代表；指定的听证会代表应当具有广泛性、代表性。"},{"i":30,"n":"第三十条","txt":"承办部门应当在举行听证会 10 日前将听证会材料送达听证会代表。"},{"i":31,"n":"第三十一条","txt":"听证会代表应当亲自参加听证，并有权对听证事项的必要性、可行性以及具体内容发表意见和质询，查阅听证纪要。 听证会代表应当忠于事实，实事求是地反映所代表的公民、法人和其他组织的意见，遵守听证纪律，保守国家秘密。"},{"i":32,"n":"第三十二条","txt":"听证会按照以下程序进行： （一）听证主持人宣布听证会开始； （二）承办部门对听证事项进行说明； （三）听证会代表提问和发表意见； （四）听证主持人询问； （五）听证主持人宣布听证会结束。"},{"i":33,"n":"第三十三条","txt":"承办部门应当制作听证会记录，如实记录各方的主要观点和理由。"},{"i":34,"n":"第三十四条","txt":"听证会结束后，承办部门应当根据听证会记录制作听证纪要，听证纪要应包括听证会的基本情况、听证会代表的意见及采纳情况。 依据听证作出行政许可决定、行政决策应当附具相关听证纪要。"},{"i":35,"n":"第三十五条","txt":"当事人扰乱听证秩序或者有其他妨碍听证正常进行行为的，由主持人给予警告；情节严重的，责令其退离听证会场。"},{"i":36,"n":"第三十六条","txt":"行政处罚和行政许可事项承办部门及其工作人员违反本规则规定，应当履行听证告知义务而不履行的，由有关部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":37,"n":"第三十七条","txt":"当事人依法要求举行听证或者法律、行政法规和规章规定应当举行听证的，而法制工作机构或者承办部门违反本规则未依法组织听证的，由有关部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":38,"n":"第三十八条","txt":"听证工作人员违反本规则规定，在听证活动中履行职责不当、妨碍听证参加人行使陈述、申辩、质证等权利的，由有关部门批评教育；情节严重的，依法给予行政处分。"},{"i":39,"n":"第三十九条","txt":"本规则所称 3 日、 5 日、 7 日为工作日。"},{"i":40,"n":"第四十条","txt":"本规则自 2007 年 3 月 1 日起施行。"}],"guofangkexuejishugongyeweiyuanhuixingzhengchufashi9ab3c9":[{"i":1,"n":"第一条","txt":"为了规范行政处罚行为，保障行政处罚的合法性，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》等有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国防科学技术工业委员会（以下简称国防科工委）依据法律、行政法规或者规章，对公民、法人和其他组织违反国防科技工业行政管理秩序的行为实施行政处罚，适用本办法。"},{"i":3,"n":"第三条","txt":"实施行政处罚应当遵循合法、公正、公开原则。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对国防科工委作出的行政处罚，享有陈述权、申辩权；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。 公民、法人或者其他组织因国防科工委违法作出行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":5,"n":"第五条","txt":"国防科工委在法定职权范围内实施行政处罚。 国防科工委依照法律、行政法规或者规章的规定，可以在其法定权限内委托符合《中华人民共和国行政处罚法》第十八条、第十九条规定条件的组织实施行政处罚。 国防科工委相关业务部门、直属单位和受委托的组织不得以自己的名义实施行政处罚。"},{"i":6,"n":"第六条","txt":"国防科工委相关业务部门对涉嫌违反国防科技工业行政管理秩序的行为，经初步审查认为应当依法作出行政处罚的，报委领导批准立案并确定承办部门。"},{"i":7,"n":"第七条","txt":"承办部门应当指派案件承办人员组成案件调查组调查违法行为，收集有关证据。 案件承办人员与当事人有直接利害关系的，应当回避。"},{"i":8,"n":"第八条","txt":"案件承办人员进行调查时，不得少于两人，并应当向当事人或者有关人员出示有效证件。当事人或者有关人员应当协助调查，不得阻挠或者拒绝。 对在调查中知悉的国家秘密、商业秘密和个人隐私，案件承办人员负有保密义务。"},{"i":9,"n":"第九条","txt":"案件承办人员对当事人及其他有关人员进行询问或者调查应当制作笔录。 笔录应当记载时间、地点、询问情况，由被询问人和案件承办人员签字或者盖章；被询问人要求补正的，应当允许。 被询问人拒绝签字或者盖章的，案件承办人员应当在笔录中予以说明。"},{"i":10,"n":"第十条","txt":"案件承办人员在调查中可以要求当事人及其他有关人员提供相关证明材料，材料提供人应当在有关材料上签名或者盖章。材料提供人拒绝签名或者盖章的，案件承办人应当在材料上予以注明。"},{"i":11,"n":"第十一条","txt":"调查终结，承办部门应当作出案件调查报告。 调查报告应当包括下列内容： （一）当事人的基本情况； （二）经调查核实的事实、证据； （三）拟作出行政处罚、不予行政处罚的建议及其法律依据。"},{"i":12,"n":"第十二条","txt":"拟作出行政处罚的，承办部门应当将调查报告及相关材料移送法制工作机构进行审查。 不予行政处罚的，由承办部门报委领导批准撤销案件。"},{"i":13,"n":"第十三条","txt":"法制工作机构应当对承办部门移交的调查报告及相关材料进行审查。审查内容包括： （一）是否在法定职权管辖范围； （二）违法事实是否清楚，证据是否确凿充分，调查取证程序是否合法； （三）确定违法行为性质是否准确； （四）适用法律、行政法规或者规章是否正确； （五）处罚种类、幅度是否适当； （六）其他依法应当审查的内容。"},{"i":14,"n":"第十四条","txt":"法制工作机构在审查过程中可以要求承办部门对案件有关情况作出解释、说明。必要时，法制工作机构可以直接向有关单位及人员调查、了解情况。"},{"i":15,"n":"第十五条","txt":"法制工作机构根据下列情况作出审查意见： （一）违法事实清楚，证据充分，定性准确，适用法律、行政法规或者规章正确，程序合法，处罚种类、幅度适当的，签署同意意见； （二）违法事实清楚，证据充分，程序合法，但确定违法行为性质不准确或者适用法律、行政法规、规章错误的，提出纠正意见，退回承办部门； （三）违法事实不清，证据不足，程序不合法的，提出纠正意见，退回承办部门，重新进行调查取证。"},{"i":16,"n":"第十六条","txt":"对法制工作机构审查通过的案件，承办部门应当书面告知当事人拟作出行政处罚决定的事实、理由和法律依据，以及当事人依法享有的权利。 当事人要求陈述和申辩的，承办部门应当充分听取当事人意见，对有关情况进行复核，不得因当事人的申辩而加重处罚。"},{"i":17,"n":"第十七条","txt":"对拟作出 3 万元以上（不含 3 万元）罚款、责令停产停业、吊销许可证或者执照等行政处罚的，承办部门应当告知当事人享有听证的权利。当事人要求听证的，应当在收到告知后 3 个工作日内提出申请。 行政处罚的听证由法制工作机构组织。"},{"i":18,"n":"第十八条","txt":"拟作出 3 万元以上罚款、责令停产停业、吊销许可证或者执照等行政处罚的，承办部门应当将起草的行政处罚决定书、调查报告及其他相关材料报委主任办公会议审查决定。 拟作出警告、 3 万元以下罚款等其他行政处罚的，承办部门应当将起草的行政处罚决定书、调查报告及其他相关材料报委领导审查决定。"},{"i":19,"n":"第十九条","txt":"国防科工委决定依法作出行政处罚的，法制工作机构应当制作正式的行政处罚决定书，由承办部门负责送达当事人。"},{"i":20,"n":"第二十条","txt":"行政处罚决定作出后，国防科工委相关业务部门应当依照《中华人民共和国行政处罚法》的相关规定执行。 行政处罚决定执行完毕后，法制工作机构和承办部门应当及时将案件材料立卷归档。"},{"i":21,"n":"第二十一条","txt":"案件承办人员因履行职责不当，给公民人身或财产造成损害、给法人或者其它组织造成损失的，由有关部门批评教育；情节严重的，给予行政处分。"},{"i":22,"n":"第二十二条","txt":"国防科工委工作人员玩忽职守，对应当予以制止和处罚的违法行为不予制止、处罚，致使公民、法人或者其他组织的合法权益、公共利益和社会秩序遭受损害的，对直接负责的主管人员和其他责任人员依法给予行政处分。"},{"i":23,"n":"第二十三条","txt":"国防科工委工作人员在行政处罚过程中利用职务上的便利，索取或者收受他人财物、收缴罚款据为己有的，由有关部门批评教育；情节严重的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本办法自 2007 年 3 月 1 日起施行。"}],"guofangkexuejishugongyeweiyuanhuixingzhengfuyishis9bed63":[{"i":1,"n":"第一条","txt":"为了规范国防科学技术工业委员会（以下简称国防科工委）的行政复议工作，防止和纠正违法或者不当的行政行为，维护公民、法人和其他组织的合法权益，保障和监督国防科工委依法行政，根据《中华人民共和国行政复议法》，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织向国防科工委提出行政复议申请，国防科工委受理行政复议申请、作出行政复议决定，适用本办法。"},{"i":3,"n":"第三条","txt":"国防科工委法制工作机构是国防科工委的行政复议机构，具体办理行政复议事项，履行下列职责： （一）受理向国防科工委提出的行政复议申请； （二）向有关组织和人员调查取证，查阅文件和资料； （三）审查申请行政复议的具体行政行为是否合法与适当； （四）对违反规定的具体行政行为提出处理建议； （五）拟订行政复议决定； （六）办理因不服国防科工委行政复议决定提起行政诉讼的应诉事项； （七）法律、法规和规章规定的其他职责。"},{"i":4,"n":"第四条","txt":"国防科工委行政复议工作遵循合法、公正、公开、及时、便民的原则，坚持有错必纠，保障法律、法规和规章的正确实施。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织对国防科工委行政复议决定不服的，可以依照行政诉讼法的规定向人民法院提起行政诉讼，也可以依照行政复议法的规定向国务院申请裁决。但是法律、法规规定国防科工委行政复议决定为最终裁决的除外。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织对于国防科工委或者省、自治区、直辖市人民政府国防科技工业管理部门作出的下列具体行政行为不服的，可以依照本办法申请行政复议： （一）符合法定条件，但没有依法办理许可、审批、登记等有关事项的； （二）作出的有关许可证、资格证、资质证等证书变更、中止、撤销的决定； （三）作出的警告、罚款、没收违法所得、责令停产停业、暂扣或者吊销许可证等行政处罚决定； （四）其他侵犯公民、法人或者其他组织合法权益的行为。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织认为国防科工委的具体行政行为所依据的规定不合法，在对具体行政行为申请行政复议时，可以一并提出对该规定的审查申请。 前款规定不含国防科工委规章，规章的审查依照法律、行政法规办理。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织对下列事项不服，不能依照本办法申请行政复议： （一）国防科工委颁布的规章以及具有规章效力的规范性文件； （二）国防科工委作出的行政处分或者其他人事处理决定； （三）国防科工委或者国防科工委依法委托的单位作出的对有关纠纷的调解或者处理。"},{"i":9,"n":"第九条","txt":"对国防科工委依法委托的单位作出的具体行政行为不服的，可以向国防科工委申请行政复议。"},{"i":10,"n":"第十条","txt":"公民、法人或者其他组织认为国防科工委或者省、自治区、直辖市人民政府国防科技工业管理部门作出的具体行政行为侵害其合法权益的，可以自知道该具体行政行为之日起 60 日内向国防科工委提出行政复议申请；但是法律规定的申请期限超过 60 日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。"},{"i":11,"n":"第十一条","txt":"依照本办法申请行政复议的公民、法人或者其他组织是申请人。 公民、法人或者其他组织对国防科工委或者省、自治区、直辖市人民政府国防科技工业管理部门的具体行政行为不服申请行政复议的，作出具体行政行为的行政机关是被申请人。 同申请行政复议的具体行政行为有利害关系的其他公民、法人或者其他组织可以作为第三人参加行政复议。 申请人、第三人可以委托代理人代为参加行政复议。委托代理人参加行政复议应当向国防科工委提交授权委托书。"},{"i":12,"n":"第十二条","txt":"申请行政复议应当符合下列条件： （一）申请人是认为被申请人的具体行政行为直接侵犯其合法权益的利害关系人； （二）有具体的行政复议请求和事实根据； （三）属于国防科工委行政复议范围； （四）在规定的申请期限内。"},{"i":13,"n":"第十三条","txt":"申请人向国防科工委申请行政复议，可以书面申请，也可以口头申请。 书面申请的，应递交行政复议申请书（一式三份）和相关材料。行政复议申请书应当载明下列内容： （一）申请人的姓名、性别、年龄、职业、住址（法人或者其他组织的名称、地址、法定代表人或主要负责人的姓名），委托代理人的姓名、住址； （二）被申请人的名称、地址； （三）行政复议请求、事实和理由； （四）申请人签名及申请日期。 口头申请的，行政复议机构应当当场记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、理由和时间，并由申请人签名或者盖章确认。"},{"i":14,"n":"第十四条","txt":"申请人向国防科工委申请行政复议，国防科工委已经受理的，在法定行政复议期限内不得向人民法院提起行政诉讼。 公民、法人或者其他组织向人民法院提起行政诉讼，人民法院已经受理的，不得申请行政复议。"},{"i":15,"n":"第十五条","txt":"国防科工委行政复议机构收到行政复议申请后，应当在 5 日内进行审查，并分别作出以下处理： （一）行政复议申请符合本办法规定的，应予受理，并书面通知申请人； （二）行政复议申请不符合本办法规定的，决定不予受理，制作《不予受理决定书》，并送达申请人； （三）对不属于国防科工委受理的行政复议申请，应当告知申请人向有关行政复议机关提出； （四）行政复议申请书未载明本办法规定内容的，应当将行政复议申请书发还申请人，限期补正。过期不补正的，视为未申请。 行政复议机构对行政复议申请进行审查后，应当以书面形式将有关情况报委领导。"},{"i":16,"n":"第十六条","txt":"法律、法规规定应当先向国防科工委申请行政复议、对行政复议决定不服再向人民法院提起行政诉讼的，国防科工委决定不予受理或者受理后超过行政复议期限不作答复的，公民、法人或者其他组织可以自收到不予受理决定书之日起或者行政复议期满之日起 15 日内，依法向人民法院提起行政诉讼。"},{"i":17,"n":"第十七条","txt":"行政复议期间具体行政行为不停止执行；但是，有下列情形之一的，可以停止执行： （一）被申请人认为需要停止执行的； （二）国防科工委认为需要停止执行的； （三）申请人申请停止执行，国防科工委认为其要求合理，决定停止执行的； （四）法律、法规规定停止执行的。"},{"i":18,"n":"第十八条","txt":"行政复议原则上采取书面审查的办法，但是申请人提出要求或者行政复议机构认为有必要时，可以听取申请人、被申请人、第三人的意见，也可以召集申请人、被申请人、第三人当面质证，并进行必要的调查取证，包括实地勘查、委托鉴定、向有关单位或者个人调查取证、查阅文件和资料。"},{"i":19,"n":"第十九条","txt":"行政复议机构应当自受理行政复议申请之日起 7 日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到行政复议申请书副本或者申请笔录复印件之日起 10 日内，向行政复议机构提出书面答复，并提交当初作出具体行政行为的证据、依据及其他有关材料。 书面答复应当载明以下内容： （一）被申请人的名称、地址、法定代表人姓名； （二）作出具体行政行为的事实、证据及法律依据； （三）对申请人的复议申请要求、事实、理由逐条进行答辩并举证； （四）作出答复的时间，并加盖印章。"},{"i":20,"n":"第二十条","txt":"行政复议机构对行政复议申请书、被申请人提交的书面答复，重点审查以下内容： （一）行政复议的请求和理由； （二）书面答复的事实和理由； （三）双方争议的焦点。"},{"i":21,"n":"第二十一条","txt":"申请人、第三人查阅不涉及国家秘密、商业秘密或者个人隐私的书面答复、作出具体行政行为的证据和有关材料，应当依照下列规定办理： （一）向行政复议机构提出申请，出示有效证件； （二）查阅材料时，应当有行政复议机构工作人员在场； （三）查阅时不得涂改、毁损、拆换、取走、增添查阅的材料；未经行政复议机构同意，不得复印、翻拍、翻录。"},{"i":22,"n":"第二十二条","txt":"在行政复议过程中，被申请人不得自行向申请人、其他有关组织或者个人收集证据。"},{"i":23,"n":"第二十三条","txt":"国防科工委行政复议决定作出前，申请人要求撤回行政复议申请的，经说明理由，可以撤回。 撤回行政复议申请的，行政复议终止。 因申请人撤回行政复议申请或者其他原因终止行政复议的，应当制作《行政复议终止通知书》，并送达申请人、被申请人、第三人。"},{"i":24,"n":"第二十四条","txt":"申请人在申请行政复议时，一并提出对具体行政行为所依据的规定审查申请的，或者行政复议机构在对被申请的具体行政行为进行审查时，认为其依据不合法，国防科工委有权处理的，行政复议机构应当在 30 日内提出处理意见报委领导批准；无权处理的，应当在 7 日内按照法定程序转送有权处理的行政机关依法处理。处理期间，中止对具体行政行为的审查。"},{"i":25,"n":"第二十五条","txt":"行政复议机构应当对被申请人的具体行政行为进行审查，提出意见，经委领导同意或者委主任办公会讨论通过后，按照下列规定作出行政复议决定： （一）具体行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，决定维持； （二） 被申请人不履行法定职责的，决定其在一定期限内履行； （三）具体行政行为有下列情形之一的，决定撤销、变更或者确认该具体行政行为违法： 1 ．主要事实不清、证据不足的； 2 ．适用依据错误的； 3 ．违反法定程序的； 4 ．超越或者滥用职权的； 5 ．具体行政行为明显不当的。 决定撤销或者确认被申请人的具体行政行为违法的，可以责令其在一定期限内重新作出具体行政行为。 （四）被申请人不按照本办法提出书面答复、提交当初作出具体行政行为的证据、依据和其他有关材料的，视为该具体行政行为没有证据、依据，决定撤销该具体行政行为。"},{"i":26,"n":"第二十六条","txt":"国防科工委责令被申请人重新作出具体行政行为的，被申请人不得以同一的事实和理由作出与原具体行政行为相同或者基本相同的具体行政行为。"},{"i":27,"n":"第二十七条","txt":"申请人在申请行政复议时可以一并提出行政赔偿请求，国防科工委对符合国家赔偿法的有关规定应当给予赔偿的，在决定撤销、变更具体行政行为或者确认具体行政行为违法时，应当同时决定被申请人依法给予赔偿。"},{"i":28,"n":"第二十八条","txt":"国防科工委应当自受理申请之日起 60 日内作出行政复议决定。情况复杂，不能在规定期限内作出行政复议决定的，经委领导批准，可以适当延长，并由行政复议机构告知申请人和被申请人；但是延长期限最长不超过 30 日。 延长复议期限的，应当制作《决定延期通知书》，并送达申请人、被申请人、第三人。"},{"i":29,"n":"第二十九条","txt":"国防科工委作出行政复议决定，应当制作《国防科工委行政复议决定书》，并加盖印章。行政复议机构应当在法定期限内将行政复议决定书送达申请人、被申请人、第三人。 行政复议决定书一经送达，即发生法律效力。 除涉及国家秘密外，行政复议决定书应当在国防科工委政府网站公开。"},{"i":30,"n":"第三十条","txt":"被申请人应当履行行政复议决定。被申请人不履行或者无正当理由拖延履行行政复议决定的，国防科工委应当责令其限期履行。"},{"i":31,"n":"第三十一条","txt":"对国防科工委作出的维持或者变更具体行政行为的行政复议决定，申请人逾期不起诉又不履行的，按照下列规定分别处理： （一）维持具体行政行为的行政复议决定，由作出具体行政行为的行政机关依法执行，或者申请人民法院强制执行； （二） 变更具体行政行为的行政复议决定，由国防科工委依法执行，或者申请人民法院强制执行。"},{"i":32,"n":"第三十二条","txt":"国防科工委工作人员和被申请人在行政复议活动中，有违反《中华人民共和国行政复议法》规定的行为的，依照该法追究其责任。"},{"i":33,"n":"第三十三条","txt":"申请人、第三人及委托代理人扰乱行政复议工作秩序或者有弄虚作假、欺骗等违法行为的，国防科工委可予以警告、责令其改正，并可移送公安机关依法处理。"},{"i":34,"n":"第三十四条","txt":"行政复议期间的计算和行政复议文书的送达，依照行政复议法、民事诉讼法的相关规定执行。 本办法关于行政复议期间有关“5日”、“7日”的规定是指工作日，不含节假日。"},{"i":35,"n":"第三十五条","txt":"国防科工委受理行政复议申请，不得向申请人收取任何费用。 行政复议活动所需经费，依照行政复议法相关规定执行。"},{"i":36,"n":"第三十六条","txt":"国防科工委行政复议使用统一的文书格式。"},{"i":37,"n":"第三十七条","txt":"本办法自发布之日起施行。 附：国防科工委行政复议文书格式（略）"}],"guofangkegongweixingzhengshenpiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范行政审批行为，提高行政效能，促进依法行政，保护公民、法人和其他组织的合法权益，根据国家有关法律法规以及国务院行政审批制度改革工作有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国防科学技术工业委员会（以下简称国防科工委）根据公民、法人或者其他组织依法提出的申请，经依法审查，准予其从事特定活动、认可其资格资质等行政审批的设定和实施，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"行政审批的设定和实施应当遵循合法合理、公正公开、精简高效、责权一致的原则。"},{"i":4,"n":"第四条","txt":"行政审批的设定和实施必须加强事先调查研究、过程监督检查和事后评估评价，坚持做到充分论证、严格把关、依法审批、科学决策。"},{"i":5,"n":"第五条","txt":"行政审批项目的设定，应当以法律、行政法规、国务院有普遍约束力的决定为依据，并通过国防科工委规章或规范性文件对行政审批对象、条件、程序、期限以及监督方式等加以具体明确。"},{"i":6,"n":"第六条","txt":"拟设定的行政审批项目，由具有相关职能的司局研究提出，具体内容应当包括行政审批项目名称、设定依据、审批程序等。对无法律、行政法规、国务院有普遍约束力的决定作为依据，但确需设定的行政审批项目，具有相关职能的司局应当在提出设定行政审批项目的同时，提出立法建议和行政法规（或者国务院文件）草案。"},{"i":7,"n":"第七条","txt":"拟设定的行政审批项目提出后，国防科工委法制工作机构应当对其合法性进行审核，并会同办公厅以及监察、人事等机构对该行政审批项目是否符合合理、效能、责任、监督原则进行审核、评估。经审核通过后，报国防科工委主任办公会议审议决定。"},{"i":8,"n":"第八条","txt":"拟取消的行政审批项目，由具有相关职能的司局研究提出，同时应说明理由并制定相应的后续监管措施，经国防科工委法制工作机构审核后，报国防科工委主任办公会议审议决定。"},{"i":9,"n":"第九条","txt":"除涉及国家秘密外，行政审批的项目名称、依据及其条件、程序、期限、费用以及需要提交的全部材料、申请书示范文本应当予以公示。"},{"i":10,"n":"第十条","txt":"行政审批申请应当以书面形式提出。申请人可以通过送交、邮寄、数据电文等方式提出行政审批申请。但涉及国家秘密的，按国家有关规定办理。"},{"i":11,"n":"第十一条","txt":"申请事项属于国防科工委职责和行政审批范围，申请材料齐全、符合法定形式和法定程序的，国防科工委行政审批承办司局（以下简称承办司局）应当予以受理，并告知申请人。 申请事项不属于国防科工委职责和行政审批范围，或者不符合法定程序的，承办司局应当作出不予受理的决定，并告知申请人。 申请材料不齐全或者不符合法定形式的，承办司局应当告知申请人在合理期限内予以补正。申请人未补正或未按期补正的，视为撤消申请。"},{"i":12,"n":"第十二条","txt":"依照有关规定需要经过初审的行政审批项目，初审机构（单位）应在该项行政审批项目规定的期限内进行审查，并将初审意见和申请材料报送国防科工委。承办司局不得要求申请人重复提供申请材料。"},{"i":13,"n":"第十三条","txt":"行政审批申请受理后，承办司局应当依据法定条件和程序进行实质审查。对行政审批申请进行实质审查时，应当充分听取各方面的意见。"},{"i":14,"n":"第十四条","txt":"涉及两个以上司局的行政审批，应当确定一个司局牵头，并由其负责征求其他有关司局意见后统一办理。 涉及国务院其他部门职能的，承办司局应当按照有关规定和法定程序征求相关部门的意见。"},{"i":15,"n":"第十五条","txt":"行政审批项目有明确办理时限规定的，承办司局应严格从其规定。行政审批项目未规定办理时限的，承办司局应当自受理申请之日起 30 日内进行实质审查，并依程序做出决定； 30 日内不能作出决定的，经主管委领导批准可以延长，但承办司局应当将延长审查时限及理由告知申请人。"},{"i":16,"n":"第十六条","txt":"依法不予批准的行政审批申请，承办司局应在本办法第十五条规定的时限内通知申请人，并说明理由。"},{"i":17,"n":"第十七条","txt":"承办司局对其所负责的行政审批项目应当建立完备的案卷登记档案，并妥善保管。凡不涉及国家秘密、企业商业秘密的案卷登记材料，申请人及其他相关人员可以查阅。"},{"i":18,"n":"第十八条","txt":"除涉及国家秘密外，承办司局在作出行政审批决定后，应当公布行政审批结果。"},{"i":19,"n":"第十九条","txt":"建立行政审批执法检查制度，对申请人从事行政审批项目活动进行监督检查，对已取消行政审批项目的后续监管措施进行监督检查。"},{"i":20,"n":"第二十条","txt":"公民、法人或者其他组织认为国防科工委的行政审批行为侵犯其合法权益的，可以依法申请行政复议或者提起行政诉讼。"},{"i":21,"n":"第二十一条","txt":"不需要继续保留的行政审批项目，应当按照本办法第八条规定的程序予以取消；对程序不规范、条件不明确、效率不高的行政审批项目，应当及时改进完善。"},{"i":22,"n":"第二十二条","txt":"行政审批项目依法委托给其他有关组织实施的，承办司局应当对其审批行为进行监督，并对其审批行为的后果承担责任。"},{"i":23,"n":"第二十三条","txt":"建立行政审批责任追究制度。国防科工委监察机构负责对行政审批工作人员履行职责情况进行监督，对违反本办法规定的，按照《国防科工委行政审批责任追究暂行办法》追究其责任。"},{"i":24,"n":"第二十四条","txt":"本办法关于行政审批期限的规定，是指工作日，不含法定节假日。"},{"i":25,"n":"第二十五条","txt":"本办法由国防科工委负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自 2003 年 9 月 1 日起施行。"}],"guofangkejigongyejunyonghesheshianquanjianduguanlidd5910-2":[{"i":1,"n":"第一条","txt":"为实施国防科技工业军用核设施（以下简称军用核设施）的安全监督管理，保证军用核设施的安全，保障设施工作人员和公众的健康，保护环境，促进国防核科学技术工业的顺利发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于下列军用核设施的安全监督管理： （一）核材料的生产、加工、贮存及乏燃料后处理设施； （二）核动力装置； （三）各种陆基反应堆，包括生产堆、研究堆、试验堆、临界装置等； （四）放射性废物管理设施； （五）其他需要监督管理的军用核设施。 交付军队使用的核设施除外。"},{"i":3,"n":"第三条","txt":"军用核设施的选址、设计、建造、运行和退役必须贯彻 “ 安全第一 ” 的方针，并应当实现下列安全目标： （一）建立和保持有效的防御措施，保护工作人员、公众及环境免遭辐射危害； （二）确保在设施运行状态下工作人员和公众所受到的辐射照射低于国家规定限值，并保持在可合理达到的尽量低水平，保证减轻事故引起的辐射照射； （三）采取一切合理可行的措施预防事故的发生，缓解事故的后果。确保设施设计中考虑的所有事故的辐射后果是可以接受的，并保证那些可能导致严重辐射后果的事故发生的可能性足够低。"},{"i":4,"n":"第四条","txt":"国防科学技术工业委员会（以下简称国防科工委）对军用核设施实行统一的安全监督管理。其主要职责是： （一）组织起草、制定有关的安全法律、规章及安全标准； （二）负责组织安全审评，批准颁发或吊销有关安全许可证件； （三）负责实施安全监督检查； （四）监督、协调核事故应急计划的制定和实施； （五）负责安全执法和事故、事件的调查与处理； （六）会同有关部门调解安全纠纷； （七）组织有关的安全研究及运行经验反馈。"},{"i":5,"n":"第五条","txt":"国防科工委根据军用核设施安全监督管理的需要设立相应的独立行使安全监督管理职权的机构，配备必要的合适人员，并组成军用核设施安全专家委员会。 安全专家委员会为军用核设施安全政策与法规、规章的制定、许可证的颁发、安全研究规划的确定等重大事项的决策提供咨询。"},{"i":6,"n":"第六条","txt":"营运单位负责对所申请的军用核设施的安全承担全面的责任。其主要职责是： （一）遵守国家有关法律、法规及规章，并制定相应的措施； （二）确保设施的选址、设计、建造、调试、运行和退役符合国家有关法律、法规、规章及标准的要求，足以保证安全； （三）提供保证设施安全所需要的资源，配备足够的合格工作人员，并对它们进行充分的培训和定期再培训； （四）接受国防科工委的安全监督管理； （五）及时、如实地报告设施的安全状况，并提供有关资料。"},{"i":7,"n":"第七条","txt":"对军用核设施所实施的安全监督管理不减轻也不转移营运单位对所申请的设施应承担的全面安全责任。 营运单位应负的安全责任也不因设计者、供货商、建造者等各自的活动和责任而发生任何改变。"},{"i":8,"n":"第八条","txt":"对军用核设施实行安全许可制度。安全许可证件包括： （一）军用核设施厂址选择审查意见书； （二）军用核设施建造许可证； （三）军用核设施装（投）料调试批准书； （四）军用核设施运行许可证； （五）军用核设施退役批准书； （六）军用核设施安全关键岗位操纵（作）员执照； （七）其他需要的批准文件。 有关军用核设施的各种活动必须遵循相应安全许可证件所规定的条件。"},{"i":9,"n":"第九条","txt":"军用核设施的厂址，需经国防科工委根据《可行性研究报告》中的厂址选择部分组织安全审评并出具《厂址选择审查意见书》，从安全方面确认所选厂址的适宜性后，方可予以批准。"},{"i":10,"n":"第十条","txt":"军用核设施开始建造（包括改建、扩建）前，其营运单位必须向国防科工委提交军用核设施建造申请书、初步安全分析报告及其他有关资料，经审核批准，获得《军用核设施建造许可证》后，方可动工建造。"},{"i":11,"n":"第十一条","txt":"军用核设施开始启动、运行前，其营运单位必须向国防科工委提交军用核设施启动、运行申请书、最终安全分析报告以及其他有关资料，经审核批准，获得《军用核设施装（投）料调试批准书》后，方可开始装载或投放燃料进行启动调试，在获得《军用核设施运行许可证》后，方可正式运行。"},{"i":12,"n":"第十二条","txt":"军用核设施开始退役前，其营运单位必须向国防科工委提交军用核设施退役申请书、退役安全分析报告以及其他有关资料，经审核批准，获《军用核设施退役批准书》后，方可开始退役活动。 军用核设施退役的最终状态必须经国防科工委会同有关部门验收，确认符合有关安全要求后，营运单位的责任方可终止。"},{"i":13,"n":"第十三条","txt":"本规定发布前已在建、在役或退役中的军用核设施，其营运单位应当在规定的期限内向国防科工委补交相应的申请书，提交有关安全分析报告及资料，以获得必需的安全许可证件。"},{"i":14,"n":"第十四条","txt":"获得并持有军用核设施安全关键岗位操纵（作）员执照的人员方可在相应安全关键岗位进行操作；具有大专以上文化水平、担任安全关键岗位操纵（作）员两年以上、成绩优秀者，方可指导他人在相应安全关键岗位进行操作。"},{"i":15,"n":"第十五条","txt":"军用核设施安全许可证件的颁发以安全审评为基础。国防科工委确认营运单位的申请符合国家有关法律、法规及规章的规定，并满足有关安全要求时，方可颁发相应的安全许可证件。"},{"i":16,"n":"第十六条","txt":"安全许可证件期满后终止；安全许可证件的变更、延期或更换，必须向国防科工委提出申请，经审查批准后方为有效。 未经国防科工委批准，任何法人或个人均不得转让按照本规定所获得的任何安全许可证件。"},{"i":17,"n":"第十七条","txt":"军用核设施安全监督检查的依据是： （一）国家的有关法律、法规及规章； （二）有关的国家标准、国家军用标准及核行业标准； （三）安全许可证件所规定的条件； （四）其他具有约束力的文件。"},{"i":18,"n":"第十八条","txt":"军用核设施安全监督检查的任务包括： （一）审核申请者所提交的安全文件与资料是否符合实际； （二）监督检查设施的选址、设计、建造、调试、运行和退役是否符合有关法律、法规、规章及标准和相应安全许可证件所规定的条件，是否满足预定的技术要求； （三）监督检查安全有关活动是否按审评认可的设计、程序和质量保证大纲进行； （四）考察营运单位是否具备确保设施安全运行及执行应急计划的能力与措施； （五）评估营运单位的安全文化素养； （六）其他必需的监督检查任务。"},{"i":19,"n":"第十九条","txt":"对军用核设施安全监督检查可以采取查阅有关文件与记录、现场见证、座谈访问、验证性检验和测量等方式。"},{"i":20,"n":"第二十条","txt":"国防科工委根据需要组织合适的人员（必要时邀请专家）执行指定的监督检查任务。 监督检查人员执行任务时，凭其有效证件有权进入设施内及与监督检查任务有关的建造、运行或退役现场，调查、收集有关安全的资料。"},{"i":21,"n":"第二十一条","txt":"从事军用核设施安全监督检查的人员必须客观、公正地履行监督检查职能，遵守监督检查纪律，保守国家秘密，不得介入与被监督检查设施有关的商业性质的活动和其他不利于监督检查任务有效完成的活动。"},{"i":22,"n":"第二十二条","txt":"营运单位应按规定向国防科工委提交其安全有关活动的进度及有关文件与资料，并为监督检查提供必要的条件，保证监督检查任务有计划地实施。"},{"i":23,"n":"第二十三条","txt":"国防科工委确认必要时，有权采取强制性行动，命令营运单位采取安全措施或停止危及安全的活动。"},{"i":24,"n":"第二十四条","txt":"营运单位有权拒绝有害于安全的监督检查要求，但必须执行国防科工委的强制性命令。"},{"i":25,"n":"第二十五条","txt":"对保证军用核设施安全作出显著成绩的单位和个人，国防科工委应给予表彰。"},{"i":26,"n":"第二十六条","txt":"凡违反本规定，有下列行为之一的，国防科工委可视情节轻重，给予警告、罚款、停工或停运整顿或吊销安全许可证件的处罚： （一）未经许可或违章从事军用核设施建造、运行、退役或擅自变更、转让安全许可证件的； （二）隐瞒、谎报有关资料或事实的； （三）无故拒绝或阻挠安全监督检查的； （四）无执照或违章在安全关键岗位操作的； （五）拒不执行强制性命令的。 不服从管理、违章或强迫他人违章作业，造成严重后果构成犯罪的，由司法机关依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"军用核设施的安全监督检查人员，玩忽职守、徇私舞弊、滥用职权的，视情节轻重给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"当事人对行政处罚不服的，可在接到处罚通知之日起六十日内向国防科工委申请行政复议，但对于吊销安全许可证件的处罚必须立即执行。"},{"i":29,"n":"第二十九条","txt":"军用核设施安全监督管理中涉及的保密事项按国家保密法规及有关规定处理。"},{"i":30,"n":"第三十条","txt":"申请军用核设施安全许可证件的营运单位应缴纳所需的安全审评费用，具体收费办法另行制定。"},{"i":31,"n":"第三十一条","txt":"本规定由国防科工委负责解释，并制定实施细则。"},{"i":32,"n":"第三十二条","txt":"本规定自发布之日起施行。"}],"guofangkejigongyejiliangjianduguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强国防科技工业计量工作的监督管理，保证国防科技工业产品的量值准确一致，测量数据可靠，根据《中华人民共和国计量法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国防科技工业计量，是指国防科技工业科研（含设计、试验等，下同）、生产、服务中实现产品量值准确一致、测量数据可靠的全部活动。"},{"i":3,"n":"第三条","txt":"国防科学技术工业委员会（以下简称国防科工委）统一监督管理国防科技工业计量工作。国防科技工业计量在业务上接受国务院计量行政部门的指导。"},{"i":4,"n":"第四条","txt":"国防科技工业面向社会的科研、生产、服务中的计量活动接受政府计量行政部门的监督；国防科技工业面向社会出具公正数据的产品质量检验机构，应当按国家有关规定进行计量认证。"},{"i":5,"n":"第五条","txt":"国防科技工业计量实行国家法定计量单位。对军品科研、生产中特殊需要保留的非法定计量单位，由使用单位提出，经国防科工委批准，报国务院计量行政部门备案。"},{"i":6,"n":"第六条","txt":"国防科技工业计量坚持面向科研、面向生产、面向使用；坚持军用与民用相结合、计量与测试相结合、服务与监督相结合、内部与外部相结合，为国防现代化建设和国民经济建设服务。"},{"i":7,"n":"第七条","txt":"国防科工委计量管理机构是国防科技工业计量监督管理的职能部门，其职责是： （一）贯彻执行国家计量法律、法规，拟定国防科技工业计量工作方针、政策及规章； （二）编制并组织实施国防科技工业计量工作规划、计划； （三）组织建立与调整国防科技工业计量技术机构； （四）组织研究、建立与保持国防科技工业需要的最高计量标准器具、校准装置和测试系统；组织国防最高计量标准以外的计量标准器具、校准装置、测试系统考核和计量人员考核； （五）组织实施从事国防科技工业计量检定、校准、测试的校准实验室和测试实验室认可； （六）组织国防科技工业计量工作的监督检查； （七）组织国防科技工业计量检定规程和校准规范的制定和贯彻实施； （八）组织国防科技工业系统的国际计量技术合作与交流； （九）指导有关部门（单位）开展国防科技工业计量工作。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府国防科技工业行政主管部门，依据其职能和国防科工委计量管理机构的授权，对本地区的国防科技工业计量工作实施监督管理，其职责是： （一）贯彻执行国家计量法律、法规和国防科技工业计量工作的方针、政策及规章； （二）监督检查和协调本地区的国防科技工业计量工作； （三）负责本地区军工企业事业单位最高计量标准器具和计量人员的考核工作； （四）承办国防科工委计量管理机构交办其他计量工作。"},{"i":9,"n":"第九条","txt":"军工集团公司计量管理机构，依据本规定对本集团的计量工作实施监督管理，组织本集团计量业务技术活动，承办国防科工委计量管理机构交办的其他计量工作。"},{"i":10,"n":"第十条","txt":"军工企业事业单位（含委属各高校），依法对本单位的计量工作实施自主管理，保证产品的测量质量，接受国防科技工业计量管理机构的监督检查。"},{"i":11,"n":"第十一条","txt":"其他承担国防科技工业产品科研、生产任务的部门（单位），应当按本规定的要求，对本部门（单位）的计量工作实施监督管理。"},{"i":12,"n":"第十二条","txt":"国防科工委批准设置的计量测试研究中心、专业计量站，接受国防科工委计量管理机构的监督检查。其职责是： （一）研究、建立国防科技工业需要的最高计量标准器具、校准装置和测试系统，并保持其服务能力； （二）承担国防科技工业的量值传递和量值溯源工作，根据委托承担因计量器具准确度引起纠纷的仲裁检定； （三）根据委托承担国防科技工业计量人员、计量标准器具、校准装置和测试系统的技术考核； （四）跟踪国内外计量测试新技术，研究新的测量理论与方法； （五）研究产品科研、生产、使用中的关键计量测试技术，专用测试设备及其校准手段和方法； （六）承担型号试验中使用的计量器具和专用测试设备的计量检查与保障工作； （七）承办国防科工委计量管理机构交办的其他任务。"},{"i":13,"n":"第十三条","txt":"国防科工委批准设置的区域校准实验室，在业务上接受计量测试研究中心、专业计量站的指导。其职责是： （一）研究、建立计量标准器具、校准装置和测试系统，并保持其服务能力； （二）承担军工企业事业单位的最高计量标准器具和其委托的工作计量器具的强制检定与校准工作，承担产品质量保证中的测试任务； （三）根据委托承担企业事业单位的计量人员、计量标准器具、校准装置和测试系统的技术考核。"},{"i":14,"n":"第十四条","txt":"军工企业事业单位，根据所承担科研、生产和服务任务设置的计量技术机构，在业务上接受国防科技工业计量测试研究中心、专业计量站和区域校准实验室的指导。其职责是： （一）贯彻执行国防科技工业计量工作的方针、政策及规章，提高设计、工艺及管理人员的计量意识； （二）负责本单位强制检定和其他检定、校准、测试工作； （三）确保在用计量器具及专用测试设备的量值准确和测量数据可靠。"},{"i":15,"n":"第十五条","txt":"国防科工委根据国防科技工业布局和任务的需要，对批准设置的计量技术机构，实行动态管理。"},{"i":16,"n":"第十六条","txt":"国防最高计量标准器具，须经国防科工委计量管理机构审查，由国务院计量行政部门组织考核合格后使用。"},{"i":17,"n":"第十七条","txt":"国防科技工业的区域校准实验室建立的最高计量标准器具，以及国防科技工业的计量测试研究中心、专业计量站和区域校准实验室建立的校准装置、测试系统，由国防科工委计量管理机构组织考核合格后使用，并向国务院计量行政部门备案。"},{"i":18,"n":"第十八条","txt":"军工企业事业单位建立的最高计量标准器具，由国防科工委计量管理机构授权省、自治区、直辖市人民政府国防科技工业行政主管部门组织考核合格后使用，并向所在省、自治区、直辖市计量行政部门备案。"},{"i":19,"n":"第十九条","txt":"国防科技工业用于量值传递的有证标准物质，作为计量标准器具按有关规定进行管理。"},{"i":20,"n":"第二十条","txt":"国防科技工业建立的计量标准器具、校准装置、测试系统，以及用于产品性能评定、定型鉴定和保证安全的工作计量器具，必须按规定实行计量检定。其他用于产品科研、生产、服务的工作计量器具和专用测试设备，应按规定实行校准。经检定或经校准不满足预期使用要求的，不得使用。"},{"i":21,"n":"第二十一条","txt":"计量检定按照国家计量检定系统表和计量检定规程进行。国家未制定计量检定系统表和计量检定规程的，按照国防科工委制定的国防科技工业计量器具等级图和计量检定规程进行。 国家计量检定规程不能满足国防科技工业的特殊使用要求的，计量检定按照国防科工委制定的计量检定规程进行。 国防科工委制定的国防科技工业计量器具等级图和计量检定规程报国务院计量行政部门备案。"},{"i":22,"n":"第二十二条","txt":"计量器具的校准按照校准技术规范进行。校准技术规范可由国防科工委、有关部门、军工集团公司或军工企业事业单位根据需要制定，经组织技术评审后发布实施。"},{"i":23,"n":"第二十三条","txt":"国防科技工业计量技术机构的计量检定、校准人员，必须经国防科工委计量管理机构或其授权的机构考核合格后，持证上岗。"},{"i":24,"n":"第二十四条","txt":"武器装备重点型号设置的型号计量师系统（或型号计量工作系统），负责重点型号的计量保证工作。其职责是： （一）提出型号研制过程中总体或分系统对计量测试工作的要求； （二）根据型号总体或分系统的技术指标，提出计量测试的技术指标要求； （三）提出型号总体或分系统研制过程中需要研制的计量标准器具、校准装置和专用测试设备的研究课题，并组织落实承担单位及有关保障条件； （四）组织协调型号总体或分系统研制过程中的计量保障工作。"},{"i":25,"n":"第二十五条","txt":"型号研制单位的计量机构，根据型号计量师提出的计量测试技术指标，制定可行性论证方案，并组织实施。 型号试验单位的计量机构，根据型号计量师提出的计量测试工作要求，负责组织实施。"},{"i":26,"n":"第二十六条","txt":"型号设计定型前，研制单位的计量机构应对定型组织批准的专用测试设备的计量控制状况和计量技术文件（包括计量检定规程、校准技术规范）的有效性进行审查。"},{"i":27,"n":"第二十七条","txt":"型号试验时，计量工作应列入型号的试验大纲或试验计划；计量器具和专用测试设备进入试验基地（靶场），必须进行计量检查。"},{"i":28,"n":"第二十八条","txt":"生产单位必须按照产品的技术指标和工艺规范的要求，配备满足生产要求的计量器具和检测手段。"},{"i":29,"n":"第二十九条","txt":"生产单位向使用单位交付型号产品时，按合同向使用单位交付的专用测试设备及其技术资料，应符合相应的计量规定。"},{"i":30,"n":"第三十条","txt":"产品的质量评定、成果鉴定，必须经产品的研制和生产单位的计量机构进行计量审查，并对其测量方法的正确性和测量数据的可靠性签署意见。"},{"i":31,"n":"第三十一条","txt":"产品的设计定型和生产定型，凡涉及产品技术指标量值的准确度及可信性，必须经技术能力满足要求的计量机构签署意见。"},{"i":32,"n":"第三十二条","txt":"用于产品设计定型、生产定型、质量评定和成果鉴定的计量器具和专用测试设备，必须经过检定或校准，并在检定或校准证书注明的有效期内使用。"},{"i":33,"n":"第三十三条","txt":"军工企业事业单位引进技术和仪器设备时，应同时引进必要的计量保证手段和技术资料；有关计量机构应当对引进技术和仪器设备的计量保证条件进行审查。"},{"i":34,"n":"第三十四条","txt":"军工企业事业单位承担的重点工程项目，应参照武器装备型号计量师制度，设置工程项目计量师，确保测量数据准确，质量可靠。"},{"i":35,"n":"第三十五条","txt":"军工企业事业单位在型号和重点工程项目可行性论证时，相应的计量机构应对其技术指标的计量保证手段进行审查；当不具备计量保证手段时，负责可行性论证的单位应采取有效措施予以保证。"},{"i":36,"n":"第三十六条","txt":"国防科工委计量管理机构组织建立国防科技工业计量工作监督机制，对国防科技工业科研、生产、服务全过程的计量工作，按领域、分层次实施监督。"},{"i":37,"n":"第三十七条","txt":"国防科工委计量管理机构统一组织建立国防科技工业计量监督员队伍，依法对国防科技工业计量工作实施监督。其主要任务是： （一）监督检查国防科技工业计量法律、法规及规章制度的执行情况； （二）监督检查国防科技工业计量和测试人员资格的有效性； （三）监督检查国防科技工业计量标准器具、校准装置和测试系统的考核情况及测量设备的控制状况； （四）监督检查国防科技工业计量技术机构和测试实验室的能力保持状况和资格的有效性。"},{"i":38,"n":"第三十八条","txt":"承担国防科技工业计量监督任务的人员，必须经国防科工委计量管理机构考核合格，取得资格。"},{"i":39,"n":"第三十九条","txt":"国防科技工业计量工作的监督检查情况，依据监督检查的对象和内容，由国防科工委计量管理机构或授权省、自治区、直辖市人民政府国防科技工业行政主管部门发布通报。"},{"i":40,"n":"第四十条","txt":"违反本规定的，由国防科工委计量管理机构按照有关规定进行处理。"},{"i":41,"n":"第四十一条","txt":"国防科技工业系统开展计量检定、校准，计量人员和计量标准考核，校准实验室和测试实验室认可工作，参照有关规定收取费用。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市人民政府国防科技工业行政主管部门、军工集团公司，其他承担国防科技工业科研、生产任务的部门，可以根据本规定制定具体实施办法，并报国防科工委备案。"},{"i":43,"n":"第四十三条","txt":"本规定由国防科工委负责解释。"},{"i":44,"n":"第四十四条","txt":"本规定自发布之日起施行。"}],"guofangkeyanshengchananquanshigubaogaohediaochachu732428":[{"i":1,"n":"第一条","txt":"为了规范国防科研生产安全事故报告和调查处理工作，落实生产安全事故责任追究制度，防止和减少国防科研生产安全事故，根据《中华人民共和国安全生产法》、《中华人民共和国保守国家秘密法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"国防科研生产安全事故报告和调查处理，适用本办法。 本办法所称国防科研生产安全事故（以下简称事故），是指取得武器装备科研生产许可的单位在武器装备科研、生产、试验、储存、销毁等活动中发生的造成人身伤亡或者直接经济损失的事故。"},{"i":3,"n":"第三条","txt":"根据事故造成的人员伤亡或者直接经济损失，事故分为四个等级： （一）特别重大事故，是指造成30人以上死亡，或者100人以上重伤（包括急性工业中毒，下同），或者1亿元以上直接经济损失的事故； （二）重大事故，是指造成10人以上30人以下死亡，或者50人以上100人以下重伤，或者5000万元以上1亿元以下直接经济损失的事故； （三）较大事故，是指造成3人以上10人以下死亡，或者10人以上50人以下重伤，或者1000万元以上5000万元以下直接经济损失的事故； （四）一般事故，是指造成3人以下死亡，或者10人以下重伤，或者直接经济损失1000万元以下的事故。"},{"i":4,"n":"第四条","txt":"事故报告应当及时、准确、完整，任何单位和个人对事故不得迟报、漏报、谎报或者瞒报。 事故调查处理应当坚持实事求是、尊重科学的原则，及时、准确地查清事故经过、事故原因和事故损失，查明事故性质，认定事故责任，总结事故教训，提出整改措施，并对事故责任者依法追究责任。"},{"i":5,"n":"第五条","txt":"国家国防科技工业局（以下简称国防科工局）负责全国事故统计、事故报告和调查处理工作；省级国防科技工业管理部门根据本办法的规定，负责本行政区域内的事故报告和调查处理工作，并向国防科工局报告事故调查处理情况。"},{"i":6,"n":"第六条","txt":"事故报告和调查处理、应急工作及其信息发布，应当遵守国家法律、行政法规有关保密的规定。 未经国防科工局批准，任何单位和个人不得对外发布有关涉密信息。"},{"i":7,"n":"第七条","txt":"事故发生后，事故现场有关人员应当立即向本单位负责人报告；单位负责人接到报告后，应当于1小时内向事故发生地省级国防科技工业管理部门报告。中央所属军工企事业单位还应当逐级向所属军工集团公司报告。 发生燃烧爆炸和有毒有害物质泄漏事故及其他需要社会救援的事故的，应当立即报告当地人民政府及有关应急救援组织。"},{"i":8,"n":"第八条","txt":"省级国防科技工业管理部门和军工集团公司接到事故报告后，应当依照下列时限向国防科工局报告： （一）特别重大事故、重大事故立即报告； （二）较大事故2小时内报告； （三）一般事故12小时内报告。 省级国防科技工业管理部门接到事故报告后，应当通报省级公安机关、安全生产监督管理部门。 国防科工局接到较大以上事故报告后，应当根据事故等级，按照本条第一款第一项、第二项规定的时限向工业和信息化部、国家安全生产监督管理总局报告。"},{"i":9,"n":"第九条","txt":"报告事故应当包括下列内容： （一）事故发生单位概况； （二）事故发生的时间、地点以及事故现场情况； （三）事故的简要经过； （四）事故已经或者可能造成的伤亡人数（包括下落不明的人数）和初步估计的直接经济损失； （五）已经采取的措施； （六）其他应当报告的情况。"},{"i":10,"n":"第十条","txt":"事故报告后30日内（火灾事故自发生之日起7日内）伤亡人数出现变化的，应当及时补报。"},{"i":11,"n":"第十一条","txt":"事故发生单位接到事故报告后，应当立即启动事故应急预案，采取有效措施组织抢救，防止事故扩大，减少人员伤亡和财产损失。 事故现场存在发生爆炸、急性中毒等次生事故危险的，现场应急抢险救援工作应当在事故应急指挥部的统一指挥和安全技术专家的指导下进行。"},{"i":12,"n":"第十二条","txt":"接到事故报告后，省级国防科技工业管理部门、军工集团公司应当立即派员赶赴现场，开展相关工作；属于重大以上事故的，国防科工局应当派员赶赴现场，开展有关工作。"},{"i":13,"n":"第十三条","txt":"事故发生后，事故单位和有关人员应当妥善保护事故现场以及相关证据，任何单位和个人不得破坏事故现场、毁灭相关证据。 因抢救人员、防止事故扩大以及疏通交通等原因，需要移动事故现场物件的，应当做出标志，绘制现场简图并做出书面记录或者影像记录，妥善保存现场重要痕迹、物证。"},{"i":14,"n":"第十四条","txt":"国防科工局、省级国防科技工业管理部门和军工集团公司应当建立安全生产值班制度，公布值班电话，受理事故报告和举报。"},{"i":15,"n":"第十五条","txt":"发生特别重大事故，国防科工局应当配合国务院或者国务院授权的部门组织调查；重大事故由国防科工局组织调查；较大事故、一般事故由省级国防科技工业管理部门组织调查。 事故发生单位所属的军工集团公司应当参加相关部门组织的事故调查工作。 造成3人以下重伤或者直接经济损失300万元以下的事故，负责事故调查的部门可以委托事故发生单位的上级单位组织调查。"},{"i":16,"n":"第十六条","txt":"自事故发生之日起30日内（火灾事故自发生之日起7日内），因事故伤亡人数变化导致事故等级发生变化的，根据变化后的事故等级可以由相应部门对事故调查情况进行复核，必要时应当另行组织调查。"},{"i":17,"n":"第十七条","txt":"负责事故调查的部门应当遵循精简、效能、保密的原则组成调查组，开展调查工作。 负责事故调查的部门可以根据事故的具体情况，邀请有关安全生产监督管理部门、监察机关、公安机关、检察机关、工会派人参与事故调查，事故发生单位的上级单位应当派人参加。 事故调查组可以聘请有关专家参与调查。"},{"i":18,"n":"第十八条","txt":"负责事故调查的部门指定事故调查组组长，由其主持事故调查组的工作。调查组成员应当具有事故调查所需要的知识和专长，并与所调查的事故没有直接利害关系。"},{"i":19,"n":"第十九条","txt":"事故调查组履行下列职责： （一）查明事故发生经过、原因、伤亡情况及直接经济损失； （二）认定事故的性质和事故责任； （三）提出对事故责任者的处理建议； （四）总结事故教训，提出防范和整改措施； （五）提交事故调查报告。"},{"i":20,"n":"第二十条","txt":"事故调查组有权向有关单位和个人了解与事故有关的情况，并要求其提供相关文件、资料，有关单位和个人不得拒绝。 事故发生单位的负责人和有关人员在事故调查期间不得擅离职守，并应当随时接受事故调查组的询问，如实提供有关情况。 事故调查中发现涉嫌犯罪的，事故调查组应当及时将有关材料或者其复印件移交司法机关处理。"},{"i":21,"n":"第二十一条","txt":"事故调查中需要进行技术鉴定的，事故调查组可以委托具有国家规定资质的单位进行技术鉴定，也可以直接组织专家进行技术鉴定。 技术鉴定所需时间不计入事故调查期限。"},{"i":22,"n":"第二十二条","txt":"事故调查组成员在事故调查工作中应当诚信公正、恪尽职守，遵守事故调查组的纪律，保守事故调查秘密。 事故调查组成员不得擅自发布有关事故的信息。"},{"i":23,"n":"第二十三条","txt":"事故调查组应当自事故发生之日起60日内提交事故调查报告；特殊情况下，经负责事故调查的部门批准，提交事故调查报告的期限可以适当延长，延长期限不得超过60日。"},{"i":24,"n":"第二十四条","txt":"事故调查报告应当包括下列内容： （一）事故发生单位概况； （二）事故发生经过和事故救援情况； （三）事故造成的人员伤亡和直接经济损失； （四）事故发生的原因和事故性质； （五）事故责任的认定以及对事故责任者的处理建议； （六）事故防范和整改措施。 事故调查报告应当附有关证据材料。事故调查组成员应当在事故调查报告上签名。事故报告涉及国家秘密的，应确定密级并按照保密规定管理。"},{"i":25,"n":"第二十五条","txt":"事故调查结束后，负责事故调查的部门应当收回事故调查资料，归档保存。"},{"i":26,"n":"第二十六条","txt":"重大事故、较大事故、一般事故，负责组织事故调查的部门应当自收到事故调查报告之日起15日内做出批复；特殊情况下，批复时间可以适当延长，延长时间最长不超过30日。批复中应当明确对事故发生单位和有关人员的处理意见。 有关部门和单位应当按照批复，依照法律、行政法规的规定和干部管理权限，对事故发生单位和相关责任人员进行处理。 负有事故责任的人员构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"事故发生单位应当及时落实防范和整改措施，防止事故再次发生。 国防科技工业管理部门和事故发生单位的上级单位应当对事故发生单位落实防范和整改措施的情况进行监督检查。"},{"i":28,"n":"第二十八条","txt":"事故调查处理结果，由负责事故调查的部门在相关范围内通报。事故通报涉及国家秘密的，应当注明密级，并严格控制知悉范围。"},{"i":29,"n":"第二十九条","txt":"省级国防科技工业管理部门负责组织调查的事故，应当自结案之日起15日内将经批复的事故调查报告报送国防科工局备案，并同时通报地方人民政府安全生产监督管理等有关部门。"},{"i":30,"n":"第三十条","txt":"事故发生单位主要负责人、直接负责的主管人员和其他直接责任人员有下列行为之一，构成违反治安管理行为的，由公安机关依法给予处罚；构成犯罪的，依法追究刑事责任；属于国家工作人员的，还应当依法给予处分。 （一）谎报或者瞒报事故的； （二）伪造或者故意破坏事故现场的； （三）转移、隐匿资金、财产，或者销毁有关证据、资料的； （四）拒绝接受调查或者拒绝提供有关情况和资料的； （五）在事故调查中作伪证或者指使他人作伪证的； （六）事故发生后逃匿的。"},{"i":31,"n":"第三十一条","txt":"事故发生单位主要负责人未依法履行安全生产管理职责，导致事故发生的，依照有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"发生较大以上事故单位管理混乱，不具备法律规定的安全生产条件，经整顿仍不能满足安全生产条件的，由发证机关依法暂扣或者吊销其有关证照；事故发生单位主要负责人受到刑事处罚或者撤职处分的，自刑罚执行完毕或者受处分之日起，5年内不得担任军工企事业单位的主要负责人。"},{"i":33,"n":"第三十三条","txt":"有安全生产管理职责的部门或者单位有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。 （一）不立即组织应急救援的； （二）故意漏报、迟报或者谎报、瞒报事故的； （三）阻碍、干涉事故调查工作的； （四）在事故调查中作伪证或者指使他人作伪证的。"},{"i":34,"n":"第三十四条","txt":"参与事故调查的人员在事故调查中有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任。 （一）对事故调查工作不负责任，致使事故调查工作有重大疏漏的； （二）包庇、袒护负有事故责任的人员或者借机打击报复的。"},{"i":35,"n":"第三十五条","txt":"参与事故报告和调查处理的人员，违反有关保密规定的，按照有关法律、行政法规进行处理。"},{"i":36,"n":"第三十六条","txt":"核事故、军队组织的国防科研试验活动中发生的事故和海事事故引起的事故的报告和调查处理，不适用本办法。"},{"i":37,"n":"第三十七条","txt":"工业和信息化部所属高校发生生产安全事故的，应当立即向工业和信息化部报告。"},{"i":38,"n":"第三十八条","txt":"本办法所称的“以上”包括本数，所称的“以下”不包括本数。"},{"i":39,"n":"第三十九条","txt":"本办法自2011年6月1日起施行。"}],"guojitongxinchurukoujuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强国际通信出入口局管理，维护国家利益，促进国际通信健康、有序地发展，依据《中华人民共和国电信条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设置国际通信出入口局、从事国际电信业务，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"国际通信出入口局（以下简称 \" 国际通信出入口 \" ）分为国际通信信道出入口、国际通信业务出入口和边境地区国际通信出入口。 国际通信信道出入口，是指国内通信传输信道与国际通信传输信道之间的转接点。包括： （一）国际通信光缆、电缆、微波等在国内的登陆或入境站； （二）国际通信光缆、电缆、微波等在国内的登陆或入境延伸终端站； （三）国际卫星通信系统设在我国的关口站、地球站等； （四）其他国内通信传输信道与国际通信传输信道相互链接的转接点。 国际通信业务出入口，是指国内通信业务网络与国际通信业务网络之间的业务转接点。包括： （一）电话业务网国际交换局（含国际电话业务网信令转接点）； （二）帧中继、数字数据网（ DDN ）、 ATM 业务网国际交换局； （三）互联网国际出入口路由器； （四）其他国内通信业务网与国际通信业务网之间的业务转接点。 边境地区国际通信出入口，是指利用国内交换机与境外接"},{"i":4,"n":"第四条","txt":"信息产业部负责国际通信出入口的设置审批和监督管理。"},{"i":5,"n":"第五条","txt":"国际通信出入口应当由国有独资的电信业务经营者申请设置，并承担其运行维护工作。 未经信息产业部批准，任何单位和个人不得以任何形式设置国际通信出入口。"},{"i":6,"n":"第六条","txt":"在中华人民共和国境内从事国际通信业务，必须通过信息产业部批准设立的国际通信出入口进行。任何组织和个人不得利用其它途径进行国际通信。 与香港特别行政区、澳门特别行政区和台湾地区的通信，参照国际通信管理。"},{"i":7,"n":"第七条","txt":"设置国际通信出入口的，应当遵守国家有关法律、法规，接受信息产业部和相关省、自治区、直辖市通信管理局的监督、检查和指导。"},{"i":8,"n":"第八条","txt":"国际通信出入口的设置数量、地点，由信息产业部根据我国国际通信网发展总体规划、电信业务经营者的申请和国际电信业务发展的需要确定。"},{"i":9,"n":"第九条","txt":"国际通信信道出入口应当设置在国际海光缆或陆地光缆易于登陆或者入境的地点，并应考虑网络的安全可靠及方便向国内网络延伸等因素。"},{"i":10,"n":"第十条","txt":"国际通信业务出入口应当设置在国际通信业务集中的中心城市。"},{"i":11,"n":"第十一条","txt":"边境地区国际通信出入口应当设置在与境外接壤的地市级以上（含地市级）城市，并应考虑该城市的未来发展，及与其接壤的境外地区之间通信业务量水平等因素。 边境地区国际通信出入口只能用于所在区域与境外相应的区域之间点对点的通信，不得用于转接此范围之外的电信业务。"},{"i":12,"n":"第十二条","txt":"设置国际通信出入口，应当向信息产业部提出申请并提交下列材料： （一）设置国际通信出入口的申请报告； （二）国际通信基础设施经营许可证或国际电信业务经营许可证； （三）设置国际通信出入口的技术方案； （四）信息产业部要求提交的其他材料。"},{"i":13,"n":"第十三条","txt":"信息产业部在收到第十二条规定的全部材料之日起 60 日内审查完毕，并作出批准或不予批准的批复。"},{"i":14,"n":"第十四条","txt":"撤销已设立的国际通信出入口，须提前 30 日向信息产业部提出书面申请，经信息产业部批准后方可实施，并应作好善后处理工作。书面申请应当包括要撤销的国际通信出入口的现状以及撤销后的善后处理措施。 对已设立的国际通信出入口进行扩容调整，其建设项目须按有关规定经审批同意。电信业务经营者应当在开工前 90 日将扩容调整方案报信息产业部备案。国家另有规定的除外。"},{"i":15,"n":"第十五条","txt":"获准设置国际通信出入口后的建设项目，按照国家规定的项目建设管理程序，报相关部门审批。"},{"i":16,"n":"第十六条","txt":"经营用于国际通信的甚小地球站（ VSAT ）业务的，经营者应当办理国际通信出入口审批手续，并在获准设置后，按照有关规定办理无线电台（站）设置审批手续。 设置用于国际通信的无线电台（站），获准设置国际通信出入口后，应当按照有关规定办理无线电台（站）设置审批手续。"},{"i":17,"n":"第十七条","txt":"设置国际通信信道出入口的电信业务经营者，必须加强对国际通信传输信道的管理，不得利用国际通信传输信道从事非法活动；发现他人利用国际通信传输信道从事非法活动的，应当根据国家有关规定及时协助有关部门采取制止措施。"},{"i":18,"n":"第十八条","txt":"获准设置国际通信信道出入口的电信业务经营者，有义务向获准设立国际通信业务出入口的电信业务经营者提供国际通信传输信道，不得对其采取歧视性措施；不得向未获准设置国际通信业务出入口的电信业务经营者提供国际通信传输信道。"},{"i":19,"n":"第十九条","txt":"设置国际通信信道出入口的电信业务经营者，可以向用户出租国际通信传输信道专线，并集中建立用户档案；该国际通信传输信道专线只能在规定的业务范围内用于点对点的通信，并仅供用户内部使用，不得用于经营电信业务。 经营甚小地球站（ VSAT ）通信业务出租国际通信传输信道专线的，按前款规定执行。"},{"i":20,"n":"第二十条","txt":"设置国际通信出入口的电信业务经营者，应当按有关规定同步建设相应的信息安全配套设施，经信息产业部审查验收合格后方可开通运行。在改建、扩建国际通信出入口时，必须保证信息安全配套设施的正常运行。"},{"i":21,"n":"第二十一条","txt":"设置国际通信出入口的电信业务经营者，应当建立健全安全管理制度，落实技术防范措施，保证网络运行安全、可靠。国际通信出入口出现重大故障或重大安全问题，应及时通知相关的电信业务经营者，采取紧急措施恢复正常运行，并于事件发生后 24 小时内将情况报告信息产业部。"},{"i":22,"n":"第二十二条","txt":"以经营电信业务为目的，通过互联网国际出入口设置虚拟网络的，应当报信息产业部批准。以内部使用为目的，通过互联网国际出入口设置虚拟专用网的，应当报信息产业部备案。"},{"i":23,"n":"第二十三条","txt":"设置国际通信出入口的电信业务经营者有义务对国家有关部门依法实施的安全检查和采取的相应措施给予配合。"},{"i":24,"n":"第二十四条","txt":"设置国际通信出入口的电信业务经营者，应当按照信息产业部的要求，在每年 6 月 30 日前和 12 月 31 日前两次向信息产业部和所在地省、自治区、直辖市通信管理局报告国际通信出入口的有关情况。报告的具体内容和要求在本办法附录中列出。信息产业部可以根据实际情况，对附录中所列报送材料的具体内容和要求进行调整，重新公布。"},{"i":25,"n":"第二十五条","txt":"未获得国际通信基础设施经营权的电信业务经营者，不得直接租用境外的国际通信传输信道，不得购买、自建或参与建设国际通信传输信道。 未获得国际通信业务经营权的电信业务经营者，不得租用国际通信传输信道用于经营国际通信业务，不得购买、自建或参与建设国际通信传输信道。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，未经信息产业部批准，擅自设置国际通信出入口进行国际通信的，由信息产业部或省、自治区、直辖市通信管理局依据职权责令其 3 日内拆除非法国际通信设施，没收违法所得，处违法所得 3 倍以上 5 倍以下罚款；没有违法所得或者违法所得不足 5 万元的，处 10 万元以上 100 万元以下罚款；情节严重的，责令停业整顿。"},{"i":27,"n":"第二十七条","txt":"违反本办法第十一条规定，利用边境地区国际通信出入口超范围转接电信业务的，由信息产业部或省、自治区、直辖市通信管理局依据职权责令其 2 日内改正，没收违法所得，处违法所得 3 倍以上 5 倍以下罚款；没有违法所得或者违法所得不足 5 万元的，处 10 万元以上 100 万元以下罚款；情节严重的，责令停业整顿。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，有下列行为之一的，由信息产业部或省、自治区、直辖市通信管理局依据职权责令改正，并处3 万元以下罚款： （一）未经信息产业部批准，擅自设置国际通信出入口但尚未进行国际通信的； （二）未经信息产业部批准，以经营电信业务为目的，通过互联网国际出入口设置虚拟网络的； （三）电信业务经营者为他人不经国际通信出入口进行国际通信提供协助的。"},{"i":29,"n":"第二十九条","txt":"违反本办法第十八条规定，国际通信信道经营者在向获准设立国际通信业务出入口的电信业务经营者提供国际通信信道时，采取歧视性措施，或向未获准设置国际通信业务出入口的电信业务经营者提供国际通信信道的，由信息产业部或者省、自治区、直辖市通信管理局依据职权责令改正，并处 1 万元以上 3 万元以下罚款。"},{"i":30,"n":"第三十条","txt":"违反本办法第十七条、第十九条、第二十条、第二十一条、第二十三条、第二十四条规定，不按规定建设、管理、使用国际通信信道，不履行义务或不按规定向信息产业部报送材料的，由信息产业部或者省、自治区、直辖市通信管理局依据职权责令改正，并处 1 万元罚款。相关责任人员，由所在单位根据情节轻重给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"违反本办法第二十五条规定的，由信息产业部或者省、自治区、直辖市通信管理局依据职权责令改正，并处 1万元罚款。"},{"i":32,"n":"第三十二条","txt":"非经营性互联网国际互联单位设置国际通信出入口，参照本办法管理。"},{"i":33,"n":"第三十三条","txt":"本办法自 2002 年 10 月 1 日起施行。 附录： 一、国际通信信道出入口经营者需定期报送的材料内容 （一）国际通信信道出入口所在地详细地址； （二）负责人及联系电话； （三）信道的使用情况，包括通达国家或地区、对端企业名称、承载业务种类及对应通信总容量； （四）租用国际通信传输信道专线的用户名称、专线使用性质（自用或用于经营国际电信业务）、通达方向、对端企业名称、及通信容量。 二、国际通信业务出入口经营者需定期报送的材料内容 （一）国际通信业务出入口所在地详细地址； （二）负责人及联系电话； （三）通达国家或地区、信道提供单位名称、对端企业名称、业务种类及对应通信容量。 三、边境地区国际通信出入口经营者需定期报送的材料内容 （一）边境地区国际通信业务出入口所在地详细地址； （二）负责人及联系电话； （三）通达地区、对端企业名称、传输方式、业务种类及对应通信容量。 四、设置互联网"}],"guojitongxinsheshijiansheguanliguiding":[{"i":1,"n":"第一条","txt":"为加强国际通信设施建设的统筹规划和行业管理，维护国家利益，保障国家通信主权和安全，促进国际通信网健康、有序发展，根据《中华人民共和国电信条例》和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事国际通信设施建设（含新建、改建、扩建和产权变更）活动，必须遵守本规定。 本规定所称的国际通信设施，包括国际通信出入口和国际传输网等电信设施。 国际通信出入口包括国际通信信道出入口、国际通信业务出入口和边境地区国际通信出入口。 国际传输网是指从境内的国际通信信道出入口至境外国家和地区间进行通信的所有有线、无线和卫星等电信设施。"},{"i":3,"n":"第三条","txt":"信息产业部依照本规定对国际通信设施建设实施监督管理。 省、自治区、直辖市通信管理局在信息产业部领导下，依照本规定对本行政区域内的国际通信设施建设实施监督管理。"},{"i":4,"n":"第四条","txt":"国际通信设施建设管理遵循维护国家通信主权，保证通信网络和信息安全，破除垄断、鼓励竞争，促进资源合理利用，维护通信建设市场秩序和公开、公平、公正的原则。"},{"i":5,"n":"第五条","txt":"进行国际传输网和国际通信信道出入口建设，必须拥有国际通信基础设施经营权。 进行国际通信业务出入口和边境地区国际通信出入口建设，必须拥有国际通信业务经营权。"},{"i":6,"n":"第六条","txt":"国际通信设施建设必须遵守我国的有关法律、法规，维护我国国家权益。 国际通信设施建设必须符合国家国际通信发展规划的要求。 国际通信设施建设必须符合国家安全的有关规定，配置国家有关部门要求的安全设施。"},{"i":7,"n":"第七条","txt":"我国领土、领海内国际传输网、国际通信信道出入口的经营权和维护权，必须由获得我国国际通信基础设施经营权的电信业务经营者拥有。 我国领土、领海内国际通信业务出入口和边境地区国际通信出入口的经营权和维护权，必须由获得我国国际通信业务经营权的电信业务经营者拥有。"},{"i":8,"n":"第八条","txt":"信息产业部综合规划司具体负责编制国际通信发展规划，并依据规划对国际通信设施建设进行管理。"},{"i":9,"n":"第九条","txt":"进行国际通信设施建设必须经信息产业部初审或审批同意。"},{"i":10,"n":"第十条","txt":"国际通信设施建设项目的审批应当遵循下列程序： （一）国家规定的限额以上基本建设项目，经信息产业部初审同意后，由国家发展计划委员会审批； （二）国家规定的限额以上的技术改造项目，经信息产业部初审同意后，由国家经济贸易委员会审批； （三）国家规定的限额以下建设项目由信息产业部审批。 除按前款规定的程序和权限对国际通信设施建设项目进行审批外，其他任何部门或单位无权审批国际通信设施建设项目。"},{"i":11,"n":"第十一条","txt":"国际通信设施建设单位与外国的组织或个人或者我国香港特别行政区、澳门特别行政区、台湾地区的组织或个人签署国际传输网建设谅解备忘录和建设维护协议，应在签署前报信息产业部审批，经批准后方可签署。"},{"i":12,"n":"第十二条","txt":"建设单位申请审批国际传输网建设谅解备忘录或建设维护协议应当提供下列材料： （一）申请报告。报告内容应包括合作方的主要情况，谅解备忘录或协议的主要内容及重大问题； （二）谅解备忘录或协议的文本。"},{"i":13,"n":"第十三条","txt":"信息产业部应在受理建设单位的国际传输网建设谅解备忘录或建设维护协议审批申请后 20 个工作日内书面答复申请人。对不予批准的，应当书面通知申请人并说明理由。"},{"i":14,"n":"第十四条","txt":"对不涉及与外国的组织或个人或者我国香港特别行政区、澳门特别行政区、台湾地区的组织或个人合作的国际通信设施建设项目，建设单位向信息产业部申请项目初审或审批时，应当提供下列材料： （一）申请报告。包括项目建设原因、主要建设内容及规模、投资估算及资金筹措、进度安排等主要内容； （二）项目建议书、可行性研究报告或项目建设方案。其内容及编制单位的资质应符合国家有关规定； （三）营业执照及相关的电信业务经营许可证复印件； （四）资信证明； （五）信息产业部要求提交的其他材料。 涉及国际通信出入口建设的，还应提供获准设置国际通信出入口的批准文件。"},{"i":15,"n":"第十五条","txt":"对涉及与外国的组织或个人或者我国香港特别行政区、澳门特别行政区、台湾地区的组织或个人合作的国际通信设施建设项目，建设单位向信息产业部申请项目初审或审批时，除应提供第十四条所列各项材料外，还应提供谅解备忘录文本和建设维护协议文本。"},{"i":16,"n":"第十六条","txt":"信息产业部进行国际通信设施建设项目的初审或审批，可以采用组织专家评议、委托咨询机构评估等方式，并在此基础上出具初审意见或批复。"},{"i":17,"n":"第十七条","txt":"信息产业部受理企业所报限额以上国际通信设施建设项目行业初审申请后，应当在 30 个工作日内书面答复申请人。对未通过初审的，应当书面通知申请人并说明理由。 信息产业部受理企业所报限额以下国际通信设施建设项目审批申请后，应当在 45 个工作日内书面答复申请人。对不予批准的，应当书面通知申请人并说明理由。"},{"i":18,"n":"第十八条","txt":"建设单位在国际通信设施建设项目实施过程中应接受信息产业部和国际通信设施建设所在地省、自治区、直辖市通信管理局的监督、检查和指导。"},{"i":19,"n":"第十九条","txt":"未经信息产业部审批同意私自与外国的组织或个人或者我国香港特别行政区、澳门特别行政区、台湾地区的组织或个人签署协议的国际通信设施建设项目，以及在申请初审或审批过程中隐瞒有关问题的国际通信设施建设项目，信息产业部不予初审或审批；已通过信息产业部初审或审批的，信息产业部撤消原初审意见或批准文件；已经国家发展计划委员会或国家经济贸易委员会审批同意的，信息产业部告知审批单位撤消批准文件；已经进行建设的，不得运营。"},{"i":20,"n":"第二十条","txt":"未经信息产业部批准，擅自建设国际通信设施进行国际通信的，由信息产业部或者省、自治区、直辖市通信管理局按照《中华人民共和国电信条例》第七十条的规定处罚。构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"从事国际通信设施建设管理的国家工作人员违反本规定的，按照《中华人民共和国电信条例》第七十九条的规定处罚。"},{"i":22,"n":"第二十二条","txt":"与我国香港特别行政区、澳门特别行政区、台湾地区进行通信的通信设施建设，参照国际通信设施建设管理。"},{"i":23,"n":"第二十三条","txt":"本规定自 2002 年 8 月 1 日起施行。"},{"i":24,"n":"第一条","txt":"为了加强国际通信出入口局管理，维护国家利益，促进国际通信健康、有序地发展，依据《中华人民共和国电信条例》，制定本办法。"},{"i":25,"n":"第二条","txt":"在中华人民共和国境内设置国际通信出入口局、从事国际电信业务，必须遵守本办法。"},{"i":26,"n":"第三条","txt":"国际通信出入口局（以下简称 \" 国际通信出入口 \" ）分为国际通信信道出入口、国际通信业务出入口和边境地区国际通信出入口。 国际通信信道出入口，是指国内通信传输信道与国际通信传输信道之间的转接点。包括： （一）国际通信光缆、电缆、微波等在国内的登陆或入境站； （二）国际通信光缆、电缆、微波等在国内的登陆或入境延伸终端站； （三）国际卫星通信系统设在我国的关口站、地球站等； （四）其他国内通信传输信道与国际通信传输信道相互链接的转接点。 国际通信业务出入口，是指国内通信业务网络与国际通信业务网络之间的业务转接点。包括： （一）电话业务网国际交换局（含国际电话业务网信令转接点）； （二）帧中继、数字数据网（ DDN ）、 ATM 业务网国际交换局； （三）互联网国际出入口路由器； （四）其他国内通信业务网与国际通信业务网之间的业务转接点。 边境地区国际通信出入口，是指利用国内交换机与境外接"},{"i":27,"n":"第四条","txt":"信息产业部负责国际通信出入口的设置审批和监督管理。"},{"i":28,"n":"第五条","txt":"国际通信出入口应当由国有独资的电信业务经营者申请设置，并承担其运行维护工作。 未经信息产业部批准，任何单位和个人不得以任何形式设置国际通信出入口。"},{"i":29,"n":"第六条","txt":"在中华人民共和国境内从事国际通信业务，必须通过信息产业部批准设立的国际通信出入口进行。任何组织和个人不得利用其它途径进行国际通信。 与香港特别行政区、澳门特别行政区和台湾地区的通信，参照国际通信管理。"},{"i":30,"n":"第七条","txt":"设置国际通信出入口的，应当遵守国家有关法律、法规，接受信息产业部和相关省、自治区、直辖市通信管理局的监督、检查和指导。"},{"i":31,"n":"第八条","txt":"国际通信出入口的设置数量、地点，由信息产业部根据我国国际通信网发展总体规划、电信业务经营者的申请和国际电信业务发展的需要确定。"},{"i":32,"n":"第九条","txt":"国际通信信道出入口应当设置在国际海光缆或陆地光缆易于登陆或者入境的地点，并应考虑网络的安全可靠及方便向国内网络延伸等因素。"},{"i":33,"n":"第十条","txt":"国际通信业务出入口应当设置在国际通信业务集中的中心城市。"},{"i":34,"n":"第十一条","txt":"边境地区国际通信出入口应当设置在与境外接壤的地市级以上（含地市级）城市，并应考虑该城市的未来发展，及与其接壤的境外地区之间通信业务量水平等因素。 边境地区国际通信出入口只能用于所在区域与境外相应的区域之间点对点的通信，不得用于转接此范围之外的电信业务。"},{"i":35,"n":"第十二条","txt":"设置国际通信出入口，应当向信息产业部提出申请并提交下列材料： （一）设置国际通信出入口的申请报告； （二）国际通信基础设施经营许可证或国际电信业务经营许可证； （三）设置国际通信出入口的技术方案； （四）信息产业部要求提交的其他材料。"},{"i":36,"n":"第十三条","txt":"信息产业部在收到第十二条规定的全部材料之日起 60 日内审查完毕，并作出批准或不予批准的批复。"},{"i":37,"n":"第十四条","txt":"撤销已设立的国际通信出入口，须提前 30 日向信息产业部提出书面申请，经信息产业部批准后方可实施，并应作好善后处理工作。书面申请应当包括要撤销的国际通信出入口的现状以及撤销后的善后处理措施。 对已设立的国际通信出入口进行扩容调整，其建设项目须按有关规定经审批同意。电信业务经营者应当在开工前 90 日将扩容调整方案报信息产业部备案。国家另有规定的除外。"},{"i":38,"n":"第十五条","txt":"获准设置国际通信出入口后的建设项目，按照国家规定的项目建设管理程序，报相关部门审批。"},{"i":39,"n":"第十六条","txt":"经营用于国际通信的甚小地球站（ VSAT ）业务的，经营者应当办理国际通信出入口审批手续，并在获准设置后，按照有关规定办理无线电台（站）设置审批手续。 设置用于国际通信的无线电台（站），获准设置国际通信出入口后，应当按照有关规定办理无线电台（站）设置审批手续。"},{"i":40,"n":"第十七条","txt":"设置国际通信信道出入口的电信业务经营者，必须加强对国际通信传输信道的管理，不得利用国际通信传输信道从事非法活动；发现他人利用国际通信传输信道从事非法活动的，应当根据国家有关规定及时协助有关部门采取制止措施。"},{"i":41,"n":"第十八条","txt":"获准设置国际通信信道出入口的电信业务经营者，有义务向获准设立国际通信业务出入口的电信业务经营者提供国际通信传输信道，不得对其采取歧视性措施；不得向未获准设置国际通信业务出入口的电信业务经营者提供国际通信传输信道。"},{"i":42,"n":"第十九条","txt":"设置国际通信信道出入口的电信业务经营者，可以向用户出租国际通信传输信道专线，并集中建立用户档案；该国际通信传输信道专线只能在规定的业务范围内用于点对点的通信，并仅供用户内部使用，不得用于经营电信业务。 经营甚小地球站（ VSAT ）通信业务出租国际通信传输信道专线的，按前款规定执行。"},{"i":43,"n":"第二十条","txt":"设置国际通信出入口的电信业务经营者，应当按有关规定同步建设相应的信息安全配套设施，经信息产业部审查验收合格后方可开通运行。在改建、扩建国际通信出入口时，必须保证信息安全配套设施的正常运行。"},{"i":44,"n":"第二十一条","txt":"设置国际通信出入口的电信业务经营者，应当建立健全安全管理制度，落实技术防范措施，保证网络运行安全、可靠。国际通信出入口出现重大故障或重大安全问题，应及时通知相关的电信业务经营者，采取紧急措施恢复正常运行，并于事件发生后 24 小时内将情况报告信息产业部。"},{"i":45,"n":"第二十二条","txt":"以经营电信业务为目的，通过互联网国际出入口设置虚拟网络的，应当报信息产业部批准。以内部使用为目的，通过互联网国际出入口设置虚拟专用网的，应当报信息产业部备案。"},{"i":46,"n":"第二十三条","txt":"设置国际通信出入口的电信业务经营者有义务对国家有关部门依法实施的安全检查和采取的相应措施给予配合。"},{"i":47,"n":"第二十四条","txt":"设置国际通信出入口的电信业务经营者，应当按照信息产业部的要求，在每年 6 月 30 日前和 12 月 31 日前两次向信息产业部和所在地省、自治区、直辖市通信管理局报告国际通信出入口的有关情况。报告的具体内容和要求在本办法附录中列出。信息产业部可以根据实际情况，对附录中所列报送材料的具体内容和要求进行调整，重新公布。"},{"i":48,"n":"第二十五条","txt":"未获得国际通信基础设施经营权的电信业务经营者，不得直接租用境外的国际通信传输信道，不得购买、自建或参与建设国际通信传输信道。 未获得国际通信业务经营权的电信业务经营者，不得租用国际通信传输信道用于经营国际通信业务，不得购买、自建或参与建设国际通信传输信道。"},{"i":49,"n":"第二十六条","txt":"违反本办法规定，未经信息产业部批准，擅自设置国际通信出入口进行国际通信的，由信息产业部或省、自治区、直辖市通信管理局依据职权责令其 3 日内拆除非法国际通信设施，没收违法所得，处违法所得 3 倍以上 5 倍以下罚款；没有违法所得或者违法所得不足 5 万元的，处 10 万元以上 100 万元以下罚款；情节严重的，责令停业整顿。"},{"i":50,"n":"第二十七条","txt":"违反本办法第十一条规定，利用边境地区国际通信出入口超范围转接电信业务的，由信息产业部或省、自治区、直辖市通信管理局依据职权责令其 2 日内改正，没收违法所得，处违法所得 3 倍以上 5 倍以下罚款；没有违法所得或者违法所得不足 5 万元的，处 10 万元以上 100 万元以下罚款；情节严重的，责令停业整顿。"},{"i":51,"n":"第二十八条","txt":"违反本办法规定，有下列行为之一的，由信息产业部或省、自治区、直辖市通信管理局依据职权责令改正，并处3 万元以下罚款： （一）未经信息产业部批准，擅自设置国际通信出入口但尚未进行国际通信的； （二）未经信息产业部批准，以经营电信业务为目的，通过互联网国际出入口设置虚拟网络的； （三）电信业务经营者为他人不经国际通信出入口进行国际通信提供协助的。"},{"i":52,"n":"第二十九条","txt":"违反本办法第十八条规定，国际通信信道经营者在向获准设立国际通信业务出入口的电信业务经营者提供国际通信信道时，采取歧视性措施，或向未获准设置国际通信业务出入口的电信业务经营者提供国际通信信道的，由信息产业部或者省、自治区、直辖市通信管理局依据职权责令改正，并处 1 万元以上 3 万元以下罚款。"},{"i":53,"n":"第三十条","txt":"违反本办法第十七条、第十九条、第二十条、第二十一条、第二十三条、第二十四条规定，不按规定建设、管理、使用国际通信信道，不履行义务或不按规定向信息产业部报送材料的，由信息产业部或者省、自治区、直辖市通信管理局依据职权责令改正，并处 1 万元罚款。相关责任人员，由所在单位根据情节轻重给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第三十一条","txt":"违反本办法第二十五条规定的，由信息产业部或者省、自治区、直辖市通信管理局依据职权责令改正，并处 1万元罚款。"},{"i":55,"n":"第三十二条","txt":"非经营性互联网国际互联单位设置国际通信出入口，参照本办法管理。"},{"i":56,"n":"第三十三条","txt":"本办法自 2002 年 10 月 1 日起施行。 附录： 一、国际通信信道出入口经营者需定期报送的材料内容 （一）国际通信信道出入口所在地详细地址； （二）负责人及联系电话； （三）信道的使用情况，包括通达国家或地区、对端企业名称、承载业务种类及对应通信总容量； （四）租用国际通信传输信道专线的用户名称、专线使用性质（自用或用于经营国际电信业务）、通达方向、对端企业名称、及通信容量。 二、国际通信业务出入口经营者需定期报送的材料内容 （一）国际通信业务出入口所在地详细地址； （二）负责人及联系电话； （三）通达国家或地区、信道提供单位名称、对端企业名称、业务种类及对应通信容量。 三、边境地区国际通信出入口经营者需定期报送的材料内容 （一）边境地区国际通信业务出入口所在地详细地址； （二）负责人及联系电话； （三）通达地区、对端企业名称、传输方式、业务种类及对应通信容量。 四、设置互联网"}],"dimianwuxiandiantaiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强地面无线电台（站）管理，维护空中电波秩序，保证无线电业务的正常进行，保障电磁空间安全，根据《中华人民共和国无线电管理条例》和相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设置、使用地面无线电台（站），适用本规定。 本规定所称地面无线电台（站），是指为开展地面无线电业务在某一地点或者地域设置、使用的一个或者多个发信机、收信机，或者发信机与收信机的组合。 本规定所称地面无线电业务，是指除空间无线电业务、射电天文以外的无线电业务，主要包括固定业务、移动业务、广播业务、无线电测定业务、气象辅助业务、标准频率和时间信号业务、业余业务、安全业务、特别业务等。"},{"i":3,"n":"第三条","txt":"国家无线电管理机构负责全国地面无线电台（站）设置、使用的监督管理。 省、自治区、直辖市无线电管理机构依照本规定负责本行政区域内地面无线电台（站）设置、使用的监督管理。 国家无线电管理机构和省、自治区、直辖市无线电管理机构统称无线电管理机构。"},{"i":4,"n":"第四条","txt":"设置、使用除地面公众移动通信终端、单收无线电台（站）以及国家无线电管理机构规定的微功率短距离无线电发射设备以外的地面无线电台（站），应当申请取得无线电台执照。法律、行政法规另有规定的，从其规定。"},{"i":5,"n":"第五条","txt":"申请取得无线电台执照，应当符合《中华人民共和国无线电管理条例》规定的条件，按照下列途径提出申请： （一）设置、使用有固定台址的地面无线电台（站）的，向无线电台（站）所在地的省、自治区、直辖市无线电管理机构提出申请； （二）设置、使用没有固定台址的地面无线电台（站）的，向申请人住所地的省、自治区、直辖市无线电管理机构提出申请； （三）设置、使用15瓦以上短波地面无线电台（站）以及涉及国家主权、安全的重要地面无线电台（站）的，向国家无线电管理机构提出申请。"},{"i":6,"n":"第六条","txt":"申请取得无线电台执照，应当提交下列申请材料，并对申请材料的真实性、完整性负责： （一）申请书以及申请人的营业执照、身份证等证件材料（复印件），申请人为单位的，还应当提交经办人的证件材料以及单位的授权委托书； （二）无线电频率使用许可证或者其他批准文件； （三）所使用的无线电发射设备依法取得无线电发射设备型号核准且符合国家规定的产品质量要求的证明材料； （四）熟悉无线电管理规定、具备相关业务技能人员的情况说明材料； （五）设置、使用地面无线电台（站）的具体用途和技术方案； （六）无线电台（站）电磁环境测试报告。 需要使用无线电台识别码的，应当同时提交识别码使用申请。"},{"i":7,"n":"第七条","txt":"申请取得无线电台执照，依法不需要取得无线电频率使用许可的，无需提交本规定第六条第二项规定的材料。 申请取得下列无线电台执照，可以不提交本规定第六条第六项规定的材料： （一）广播电视地面无线电台（站）等只具有发射功能的无线电台（站），但地面航空无线电导航台（站）除外； （二）地面移动通信基站； （三）无固定台址的地面无线电台（站）； （四）承诺不提出免受有害干扰保护要求的地面无线电台（站）。"},{"i":8,"n":"第八条","txt":"无线电管理机构应当依法对申请材料进行审查。申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次性告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理；申请材料齐全、符合法定形式，或者申请人按照要求补正全部申请材料的，应当予以受理，并向申请人出具受理通知书。"},{"i":9,"n":"第九条","txt":"无线电管理机构应当自受理申请之日起30个工作日内审查完毕，作出许可或者不予许可的决定。予以许可的，颁发无线电台执照，需要使用无线电台识别码的，同时核发无线电台识别码；不予许可的，书面通知申请人并说明理由。 无线电管理机构审查设置、使用没有固定台址的地面无线电台（站）无线电台执照申请，发现无线电台（站）使用区域超出本行政区域的，应当征求相关省、自治区、直辖市无线电管理机构的意见，并在无线电台执照中载明使用要求。 无线电管理机构审查无线电台执照申请依法组织听证、检测、专家评审，以及开展有关国内、国际协调或者履行国际规则规定程序所需时间，不计算在本条第一款规定的审查期限内，但应当将所需时间告知申请人。"},{"i":10,"n":"第十条","txt":"无线电台执照应当载明无线电台（站）的设置、使用人，台址或者使用区域，使用频率，发射功率，占用带宽，无线电发射设备型号核准代码，有效期，使用要求，执照编号，发证机关及签发时间等事项。同时核发无线电台识别码的，还应当在无线电台执照上载明无线电台识别码。 无线电台执照的样式由国家无线电管理机构统一规定。"},{"i":11,"n":"第十一条","txt":"无线电台执照的有效期不得超过无线电频率使用许可规定的期限；设置、使用依法不需要取得无线电频率使用许可的地面无线电台（站）的，无线电台执照的有效期不得超过5年。"},{"i":12,"n":"第十二条","txt":"无线电台执照有效期届满后需要继续使用地面无线电台（站）的，应当在期限届满30个工作日前向作出许可决定的无线电管理机构申请延续。无线电管理机构应当依照本规定进行审查，作出是否延续的决定。准予延续的，更换无线电台执照；不予延续的，书面通知申请人并说明理由。 变更无线电台执照载明的事项的，应当向作出许可决定的无线电管理机构办理变更手续。"},{"i":13,"n":"第十三条","txt":"无线电台执照被依法撤销、吊销的，应当立即停止使用地面无线电台（站），拆除无线电台（站）及天线等附属设备，交回无线电台执照。 无线电台执照有效期届满或者因其他原因终止使用地面无线电台（站）的，应当立即停止使用地面无线电台（站），及时向作出许可决定的无线电管理机构办理注销手续，交回无线电台执照，并自无线电台执照注销之日起60个工作日内拆除地面无线电台（站）及天线等附属设备。"},{"i":14,"n":"第十四条","txt":"遇有危及国家安全、公共安全、生命财产安全的紧急情况或者为了保障重大社会活动的特殊需要，可以不经批准临时设置、使用应当申请取得无线电台执照的地面无线电台（站），但是应当在设置、使用地面无线电台（站）之日起5日内向无线电台（站）所在地的省、自治区、直辖市无线电管理机构报告，并在紧急情况消除或者重大社会活动结束后拆除无线电台（站）及天线等附属设备。"},{"i":15,"n":"第十五条","txt":"外国领导人访华、各国驻华使领馆和享有外交特权与豁免的国际组织驻华代表机构设置、使用应当申请取得无线电台执照的地面无线电台（站）的，应当通过外交途径经国家无线电管理机构批准。 其他境外组织、个人在我国境内设置、使用应当申请取得无线电台执照的地面无线电台（站）的，应当经相关业务主管部门按照本规定第五条的规定报请无线电管理机构批准。"},{"i":16,"n":"第十六条","txt":"使用地面无线电台（站）的单位、个人应当遵守下列行为规范： （一）按照无线电台执照载明的事项和条件使用地面无线电台（站）； （二）不得故意收发无线电台执照许可事项之外的无线电信号，不得传播、公布或者利用无意接收的信息； （三）定期维护无线电台（站），保证其性能指标符合国家标准和国家无线电管理的有关规定，避免对其他依法设置、使用的无线电台（站）产生有害干扰；书面记录维护情况，并在无线电管理机构检查时根据要求提供； （四）遵守国家环境保护的有关规定，采取必要措施防止无线电波发射产生的电磁辐射污染环境； （五）保障无线电台（站）安全运行，提高干扰的防护能力，必要时积极配合开展与其他依法设置、使用的无线电台（站）之间的干扰协调； （六）不得利用无线电台（站）进行违法犯罪活动； （七）法律、行政法规以及国家无线电管理的其他行为规范。"},{"i":17,"n":"第十七条","txt":"依法设置、使用的地面无线电台（站）受到有害干扰的，可以向无线电管理机构投诉；受理投诉的无线电管理机构应当依照《中华人民共和国无线电管理条例》的有关规定及时处理，并将处理情况告知投诉人。"},{"i":18,"n":"第十八条","txt":"无线电管理机构应当定期对在用的地面无线电台（站）进行检查和检测。属于广播电视地面无线电台（站）、雷达站、微波站等大型无线电台（站）的，无线电管理机构应当在无线电台执照载明的有效期起始之日起1年内完成首次检查和检测。"},{"i":19,"n":"第十九条","txt":"无线电管理机构及其工作人员应当对在履行职责中知悉的通信秘密、商业秘密和个人隐私信息严格保密，不得泄露或者非法向他人提供。"},{"i":20,"n":"第二十条","txt":"违反本规定的，由无线电管理机构责令改正，依照《中华人民共和国行政许可法》《中华人民共和国无线电管理条例》等法律、行政法规予以处罚。构成违反治安管理行为的，移交公安机关处理；构成犯罪的，移交司法机关处理。"},{"i":21,"n":"第二十一条","txt":"无线电管理机构及其工作人员不依照《中华人民共和国无线电管理条例》和本规定履行职责的，对负有责任的领导人员和其他直接责任人员依法给予处分。"},{"i":22,"n":"第二十二条","txt":"在边境地区设置、使用地面无线电台（站）的，还应当遵守《边境地区地面无线电业务频率国际协调规定》的相关要求。"},{"i":23,"n":"第二十三条","txt":"军事系统地面无线电台（站），在船舶、航空器、铁路机车（含动车组列车）上设置、使用的无线电台，业余无线电台，按照相关规定执行。"},{"i":24,"n":"第二十四条","txt":"本规定自2023年2月1日起施行。"}],"gongyehexinxihuaxingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范工业和信息化行政处罚程序，保障和监督工业和信息化管理部门依法实施行政管理，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织违反工业和信息化行政管理秩序，依法应当给予行政处罚的，由工业和信息化管理部门依照《中华人民共和国行政处罚法》和本规定规定的程序实施。 本规定所称工业和信息化管理部门，包括工业和信息化部，省、自治区、直辖市电信管理机构、无线电管理机构，县级以上地方人民政府工业和信息化主管部门，以及法律、法规授权的具有工业和信息化行政管理职能的组织。"},{"i":3,"n":"第三条","txt":"工业和信息化管理部门实施行政处罚，应当遵循公正、公开的原则，坚持处罚与教育相结合，做到事实清楚、证据确凿、适用依据正确、程序合法、过罚相当。"},{"i":4,"n":"第四条","txt":"工业和信息化管理部门实施行政处罚，应当在法定权限范围内实施。 工业和信息化管理部门依照法律、法规、规章的规定，可以在法定权限范围内书面委托符合法律规定条件的组织实施行政处罚。 受委托的组织应当在委托范围内，以委托机关的名义实施行政处罚；不得再委托其他组织或者个人实施行政处罚。"},{"i":5,"n":"第五条","txt":"工业和信息化管理部门及其工作人员对在实施行政处罚过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织对工业和信息化管理部门给予的行政处罚，享有陈述权、申辩权；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。因违法行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":7,"n":"第七条","txt":"行政处罚由违法行为发生地的工业和信息化管理部门管辖。法律、行政法规、部门规章另有规定的，从其规定。 通过电信网络实施的违法行为发生地，包括违法行为人住所地、实际经营地、网络接入地、取得电信和互联网信息服务相关许可（备案）所在地。"},{"i":8,"n":"第八条","txt":"两个以上工业和信息化管理部门都有管辖权的，由最先立案的工业和信息化管理部门管辖。 两个以上工业和信息化管理部门对管辖发生争议的，应当在发生争议之日起7日内协商解决，协商不成的，应当在7日内报请共同的上一级工业和信息化管理部门指定管辖；也可以直接由共同的上一级工业和信息化管理部门指定管辖。"},{"i":9,"n":"第九条","txt":"工业和信息化管理部门发现立案的案件应当由工业和信息化管理部门以外的其他行政机关管辖的，应当及时将案件移送其他行政机关。 工业和信息化管理部门发现违法行为涉嫌犯罪的，应当依法及时将案件移送司法机关，不得以行政处罚代替刑事处罚。"},{"i":10,"n":"第十条","txt":"工业和信息化管理部门实施行政处罚，应当查明事实；违法事实不清、证据不足的，不得给予行政处罚。"},{"i":11,"n":"第十一条","txt":"行政处罚的实施机关、立案依据、实施程序和救济渠道等信息应当公示。"},{"i":12,"n":"第十二条","txt":"行政处罚应当由具有行政执法资格的执法人员实施。执法人员不得少于2人，法律另有规定的除外。 执法人员应当文明执法，尊重和保护当事人合法权益。"},{"i":13,"n":"第十三条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当主动回避。 当事人认为执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，有权申请回避。 当事人提出回避申请的，工业和信息化管理部门应当依法审查，并于5日内作出决定。决定作出之前，不停止对案件的调查。"},{"i":14,"n":"第十四条","txt":"工业和信息化管理部门在作出行政处罚决定前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利。 当事人有权进行陈述、申辩。工业和信息化管理部门应当充分听取当事人的意见，对当事人提出的事实、理由和证据进行复核；当事人提出的事实、理由或者证据成立的，工业和信息化管理部门应当采纳。 工业和信息化管理部门不得因当事人陈述、申辩而给予更重的处罚。"},{"i":15,"n":"第十五条","txt":"证据必须经查证属实，方可作为认定案件事实的根据。以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":16,"n":"第十六条","txt":"工业和信息化管理部门应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，并按照档案管理规定归档保存。"},{"i":17,"n":"第十七条","txt":"具有一定社会影响的行政处罚决定，工业和信息化管理部门应当自作出决定之日起7日内予以公开，法律、行政法规另有规定的，从其规定。 公开行政处罚决定信息，不得泄露国家秘密，不得危害国家安全、公共安全、经济安全和社会稳定，对涉及商业秘密和个人隐私的，应当作必要的处理。 公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，工业和信息化管理部门应当在3日内撤回行政处罚决定信息并公开说明理由。"},{"i":18,"n":"第十八条","txt":"发现公民、法人或者其他组织有违反工业和信息化行政管理秩序的行为，事实确凿并有法定依据，对公民处以200元以下、对法人或者其他组织处以3000元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。法律另有规定的，从其规定。"},{"i":19,"n":"第十九条","txt":"执法人员当场作出行政处罚决定的，应当向当事人出示执法证件，填写预定格式、编有号码的行政处罚决定书，并当场交付当事人。当事人拒绝签收的，执法人员应当在行政处罚决定书上注明。 前款规定的行政处罚决定书应当载明当事人的违法行为，行政处罚的种类和依据、罚款数额、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及工业和信息化管理部门的名称，并由执法人员签名或者盖章。"},{"i":20,"n":"第二十条","txt":"执法人员当场作出行政处罚决定的，应当在3日内报所属的工业和信息化管理部门备案。"},{"i":21,"n":"第二十一条","txt":"除本规定第十八条规定的可以当场作出的行政处罚外，工业和信息化管理部门发现公民、法人或者其他组织有违反工业和信息化行政管理秩序的行为，依法应当给予行政处罚的，应当全面、客观、公正地调查，收集有关证据；必要时，依照法律、法规的规定，可以进行检查。"},{"i":22,"n":"第二十二条","txt":"符合以下条件的，工业和信息化管理部门应当在15日内立案： （一）有证据初步证明公民、法人或者其他组织存在违反工业和信息化行政管理秩序的行为； （二）依据法律、法规、规章的规定应当受到行政处罚； （三）在给予行政处罚的法定期限内； （四）属于本部门管辖。 因特殊情况不能在前款规定的期限内立案的，经工业和信息化管理部门负责人批准，可以延长15日。 法律、法规、规章对于立案的期限另有规定的，从其规定。"},{"i":23,"n":"第二十三条","txt":"执法人员开展案件调查的，应当向当事人送达案件调查通知书，告知案件调查的依据、内容、时间、要求等事项。 执法人员在调查或者进行检查时，应当主动向当事人或者有关人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。 当事人或者有关人员应当如实回答询问，协助调查或者检查，不得拒绝或者阻挠。"},{"i":24,"n":"第二十四条","txt":"执法人员询问当事人或者有关人员，应当分别进行，并制作询问笔录。 询问笔录应当交被询问人核对；被询问人阅读有困难的，应当向其宣读。经核对无误后，由被询问人在笔录上逐页签名或者以其他方式确认。笔录有差错、遗漏的，应当允许被询问人更正或者补充，更正或者补充部分应当由被询问人签名或者以其他方式确认；被询问人拒绝确认的，执法人员应当在笔录上注明并签名。"},{"i":25,"n":"第二十五条","txt":"执法人员收集、调取的书证、物证应当是原件、原物。收集、调取原件、原物确有困难的，可以收集、调取经证据持有人或者执法人员核对无误的复制件、节录本或者能够证明该书证、物证的照片、录像等其他证据。"},{"i":26,"n":"第二十六条","txt":"执法人员收集的电子数据或者录音、录像等视听资料应当是原始载体。收集原始载体有困难的，可以收集复制件，并注明制作方法、制作时间、制作人和证明对象等情况，声音资料应当附有文字记录。"},{"i":27,"n":"第二十七条","txt":"为了查明案情，需要对专门性问题进行检测、检验或者鉴定的，工业和信息化管理部门应当委托具备法定资质的机构进行；没有具备法定资质的机构的，可以委托其他具备相应条件的机构进行。检测、检验、鉴定结果应当告知当事人。"},{"i":28,"n":"第二十八条","txt":"执法人员对与案件有关的物品或者场所进行勘验或者检查时，应当通知当事人到场，制作勘验笔录或者检查笔录，交当事人签名或者以其他方式确认。当事人拒不到场、无法找到当事人或者当事人拒绝签名或者以其他方式确认的，执法人员应当在笔录或者其他材料上注明并签名。有其他人在现场的，可以由其他人签名。"},{"i":29,"n":"第二十九条","txt":"执法人员抽样取证的，应当通知当事人到场，制作抽样取证凭证，对样品加贴封条，并由执法人员、当事人在抽样取证凭证上签名或者以其他方式确认。当事人拒不到场、无法找到当事人或者当事人拒绝签名或者以其他方式确认的，执法人员应当在抽样取证凭证上注明并签名。有其他人在现场的，可以由其他人签名。"},{"i":30,"n":"第三十条","txt":"在证据可能灭失或者以后难以取得的情况下，经工业和信息化管理部门负责人批准，执法人员可以先行登记保存。情况紧急、需要当场采取先行登记保存措施的，执法人员应当在24小时内向工业和信息化管理部门负责人报告，并补办批准手续。工业和信息化管理部门负责人认为不应当采取先行登记保存措施的，应当立即解除。 执法人员先行登记保存证据的，应当当场清点并制作先行登记保存通知书，由执法人员、当事人签名或者以其他方式确认后，各执1份。 先行登记保存期间，当事人或者有关人员不得销毁或者转移证据。"},{"i":31,"n":"第三十一条","txt":"对先行登记保存的证据，工业和信息化管理部门应当在7日内作出下列处理决定： （一）及时采取记录、复制、拍照、录像等证据保全措施，不再需要采取登记保存措施的，决定解除先行登记保存措施； （二）需要检测、检验、鉴定的，送交检测、检验、鉴定； （三）依法可以采取查封、扣押等行政强制措施的，决定采取相应的行政强制措施； （四）违法事实成立，依法应当予以没收的，作出行政处罚决定，没收违法所得或者非法财物； （五）违法事实不成立，或者违法事实成立但依法不应当予以查封、扣押或者没收的，决定解除先行登记保存措施； （六）依法应当移交有关部门处理的，移交有关部门并书面告知当事人。 逾期未作出处理决定的，先行登记保存措施自动解除。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，经工业和信息化管理部门负责人批准，应当中止案件调查： （一）行政处罚决定必须以相关案件的裁判结果或者其他行政决定为依据，而相关案件尚未审结或者其他行政决定尚未作出的； （二）涉及法律适用等问题，需要有权机关作出解释或者确认的； （三）因不可抗力致使案件暂时无法调查的； （四）因当事人下落不明或者无法取得联系致使案件暂时无法调查的； （五）其他依法应当中止调查的情形。 中止案件调查的原因消除后，应当立即恢复案件调查。"},{"i":33,"n":"第三十三条","txt":"存在涉嫌违法的公民死亡、法人或者其他组织终止且无权利义务承受人等应当终止调查的情形，致使案件调查无法继续进行的，终止案件调查。"},{"i":34,"n":"第三十四条","txt":"案件调查终结，工业和信息化管理部门负责人应当对调查结果进行审查，根据不同情况，依法分别作出行政处罚、不予行政处罚或者移送司法机关的决定。 对于情节复杂或者重大违法行为给予行政处罚的，工业和信息化管理部门负责人应当集体讨论决定。"},{"i":35,"n":"第三十五条","txt":"工业和信息化管理部门拟作出行政处罚决定的，应当制作行政处罚意见告知书，告知当事人拟给予的行政处罚的内容、事实、理由、依据和依法享有陈述、申辩的权利。 当事人陈述和申辩的，应当自收到行政处罚意见告知书之日起5日内提出。工业和信息化管理部门未告知当事人，或者拒绝听取当事人的陈述、申辩的，不得作出行政处罚决定；当事人明确放弃陈述或者申辩权利的除外。"},{"i":36,"n":"第三十六条","txt":"工业和信息化管理部门拟作出下列行政处罚决定的，应当告知当事人有要求听证的权利，当事人要求听证的，工业和信息化管理部门应当组织听证： （一）对公民处以1万元以上、对法人或者其他组织处以10万元以上的罚款。法律、法规、规章对罚款数额另有规定的，从其规定； （二）没收与前项所列数额同等的违法所得或者同等价值的非法财物； （三）降低资质等级、吊销许可证件； （四）责令停产停业、责令关闭、限制从业； （五）其他较重的行政处罚； （六）法律、法规、规章规定应当听证的其他情形。 当事人不承担工业和信息化管理部门组织听证的费用。"},{"i":37,"n":"第三十七条","txt":"当事人要求听证的，应当自收到行政处罚意见告知书之日起5日内以书面或者口头形式提出。口头提出的，工业和信息化管理部门应当当场记录申请人的基本情况、申请听证的主要理由以及申请时间等内容，并由当事人签名或者以其他方式确认。"},{"i":38,"n":"第三十八条","txt":"工业和信息化管理部门组织听证的，应当在举行听证7日前，将听证时间、地点书面通知当事人及有关人员。 除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证应当公开举行。"},{"i":39,"n":"第三十九条","txt":"听证设听证主持人1名，负责组织听证；听证记录员1名，负责听证准备和记录工作；必要时，可以设1至2名听证员，协助开展听证。 听证主持人、听证员、听证记录员由工业和信息化管理部门指定的非案件调查人员担任。"},{"i":40,"n":"第四十条","txt":"当事人可以亲自参加听证，也可以委托1至2人代理。 当事人认为听证主持人、听证员或者听证记录员与案件有直接利害关系的，有权申请回避。"},{"i":41,"n":"第四十一条","txt":"听证按照下列程序进行： （一）听证记录员核对听证参加人身份； （二）听证主持人宣布听证纪律、听证参加人名单和听证参加人权利义务，询问当事人是否申请回避； （三）听证主持人宣布听证开始并介绍案由； （四）案件调查人员提出当事人违法的事实、证据，说明拟作出的行政处罚的内容及法律依据； （五）当事人或者其代理人进行陈述、申辩，并可以出示相应证据材料；涉及第三人的，由第三人或者其代理人进行陈述； （六）听证主持人就案件的有关问题向案件调查人员、当事人、第三人或者其代理人等询问； （七）案件调查人员、当事人、第三人或者其代理人经听证主持人允许相互质证、辩论； （八）案件调查人员、当事人、第三人或者其代理人作最后陈述； （九）听证主持人宣布听证结束。"},{"i":42,"n":"第四十二条","txt":"当事人及其代理人无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，工业和信息化管理部门终止听证。"},{"i":43,"n":"第四十三条","txt":"听证应当制作听证笔录，经当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。"},{"i":44,"n":"第四十四条","txt":"听证结束后，工业和信息化管理部门应当根据听证笔录，依照本规定第三十四条的规定，作出决定。"},{"i":45,"n":"第四十五条","txt":"有下列情形之一的，在工业和信息化管理部门负责人作出行政处罚的决定前，应当由从事行政处罚决定法制审核的人员进行法制审核；未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 工业和信息化管理部门初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":46,"n":"第四十六条","txt":"法制审核的主要内容包括： （一）执法主体是否合法，执法人员是否具备执法资格； （二）执法程序是否合法； （三）案件事实是否清楚，证据是否合法充分； （四）适用法律、法规、规章是否准确，裁量基准运用是否适当； （五）执法是否超越法定权限； （六）执法文书是否完备、规范； （七）违法行为是否涉嫌犯罪、需要移送司法机关； （八）依法需要审核的其他内容。"},{"i":47,"n":"第四十七条","txt":"工业和信息化管理部门作出行政处罚的决定的，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的工业和信息化管理部门的名称和日期。 行政处罚决定书应当盖有作出行政处罚决定的工业和信息化管理部门的印章。"},{"i":48,"n":"第四十八条","txt":"工业和信息化管理部门应当自案件立案之日起90日内作出行政处罚决定；因案情复杂或者其他原因，不能在期限内作出决定的，经工业和信息化管理部门负责人批准，可以延长90日。法律、法规、规章另有规定的，从其规定。 案件处理过程中，检验、检测、鉴定、中止、听证、公告等时间不计入前款规定的期限。"},{"i":49,"n":"第四十九条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，工业和信息化管理部门应当在7日内依照《中华人民共和国民事诉讼法》的有关规定，将行政处罚决定书送达当事人。 当事人同意并签订送达确认书的，工业和信息化管理部门可以采用传真、电子邮件、移动通信等电子方式将行政处罚决定书等送达当事人。"},{"i":50,"n":"第五十条","txt":"因当事人提供的送达地址不准确、送达地址变更未书面告知工业和信息化管理部门，导致行政处罚决定书等未能被当事人实际接收，直接送达的，行政处罚决定书等留在该地址之日为送达之日；邮寄送达的，行政处罚决定书等被退回之日为送达之日。"},{"i":51,"n":"第五十一条","txt":"行政处罚决定依法作出后，当事人应当在行政处罚决定书载明的期限内，履行行政处罚决定。 当事人确有经济困难，需要延期或者分期缴纳罚款的，应当向工业和信息化管理部门提出申请。工业和信息化管理部门应当在15日内作出是否批准的决定，并书面告知当事人。予以批准的，应当告知当事人暂缓或者分期缴纳的期限及金额。"},{"i":52,"n":"第五十二条","txt":"当事人逾期不履行行政处罚决定的，工业和信息化管理部门可以依法采取下列措施： （一）到期不缴纳罚款的，每日按照罚款数额的3%加处罚款，加处罚款的数额不得超出罚款的数额； （二）根据法律规定，将查封、扣押的财物拍卖、依法处理或者将冻结的存款、汇款划拨抵缴罚款； （三）根据法律规定，采取其他行政强制执行方式； （四）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。"},{"i":53,"n":"第五十三条","txt":"当事人对行政处罚决定不服，申请行政复议或者提起行政诉讼的，行政处罚不停止执行，法律另有规定的除外。 当事人申请行政复议或者提起行政诉讼的，加处罚款的数额在行政复议或者行政诉讼期间不予计算。"},{"i":54,"n":"第五十四条","txt":"有下列情形之一的，工业和信息化管理部门可以办理案件结案： （一）案件终止调查的； （二）不予行政处罚的； （三）案件移送司法机关追究刑事责任的； （四）行政处罚决定执行完毕的；  （五）行政处罚决定被依法撤销的； （六）其他可以结案的情形。 申请人民法院强制执行，人民法院受理的，可以按照结案处理。"},{"i":55,"n":"第五十五条","txt":"行政处罚案件结案后，工业和信息化管理部门应当及时将案件材料立卷归档。案卷归档应当一案一卷、文书齐全、手续完备。"},{"i":56,"n":"第五十六条","txt":"外国人、无国籍人、外国组织在中华人民共和国领域内有违反工业和信息化行政管理秩序的违法行为，应当给予行政处罚的，适用本规定。"},{"i":57,"n":"第五十七条","txt":"本规定中“3日”“5日”“7日”的规定是指工作日，不含法定节假日。 本规定中的期间开始之日不计算在内。期间届满的最后一日为法定节假日的，以法定节假日后的第一日为期间届满的日期。期间不包括在途时间，行政执法文书在期满前交邮的，不视为过期。 本规定中的“以上”“以下”“内”“前”均包括本数或者本级。"},{"i":58,"n":"第五十八条","txt":"国防科技工业、烟草专卖领域行政处罚程序规定，另行制定。"},{"i":59,"n":"第五十九条","txt":"本规定自2023年9月1日起施行。2001年5月10日公布的《通信行政处罚程序规定》（原信息产业部令第10号）同时废止。"}],"gongyehexinxihuabuzhuanyebiaozhunhuajishuweiyuanhu753e0d":[{"i":1,"n":"第一条","txt":"为了加强工业和信息化部专业标准化技术委员会管理，根据《中华人民共和国标准化法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"工业和信息化部专业标准化技术委员会（以下简称标委会）的组建、运行、换届、调整、注销和监督管理等活动，适用本办法。 本办法所称标委会，是指由工业和信息化部组建，在工业和信息化相关专业领域内承担行业标准起草、技术审查等标准化工作的非法人技术组织。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责标委会的规划、组建和监督管理。 省、自治区、直辖市工业和信息化主管部门协助工业和信息化部管理本行政区域内的标委会，为标委会开展工作创造条件。"},{"i":4,"n":"第四条","txt":"标委会开展工作应当遵循公平公正、开放透明、充分协商原则，在所属专业领域内承担下列工作职责： （一）提出所属专业领域标准化工作的政策和措施建议，研究编制所属专业领域标准体系，管理下设的分技术委员会（以下简称分标委会）； （二）根据行业管理实际和产业发展需求，提出所属专业领域制定、修订行业标准的项目建议，负责所属专业领域行业标准起草、技术审查、复审、修订，以及行业标准外文版的组织翻译和审查工作； （三）组织开展所属专业领域国内外标准一致性比对分析，跟踪、研究相关领域国际标准化的发展趋势和工作动态； （四）开展所属专业领域行业标准的宣传和培训，行业标准实施情况的评估和行业标准起草人员的培训等工作； （五）受工业和信息化部委托承担归口行业标准的解释工作，并承担工业和信息化部交办的其他工作。"},{"i":5,"n":"第五条","txt":"有关行业协会（联合会）和标准化专业机构等根据工业和信息化部委托，承担材料初审等工作。"},{"i":6,"n":"第六条","txt":"组建标委会，应当具备下列条件： （一）涉及的专业领域为工业和信息化部管理领域，符合工业和信息化部标准化发展战略、规划要求； （二）业务范围明晰，原则上与已有标委会的业务范围无明显交叉； （三）标准体系框架明确，有较多的行业标准制定、修订工作需求； （四）秘书处承担单位具备开展标准化工作的能力和本办法规定的条件。"},{"i":7,"n":"第七条","txt":"标委会由委员组成，委员应当具有广泛性和代表性，人数不少于25名，其中主任委员1名，副主任委员一般不超过5名。来自同一单位的委员人数不得超过3名。主任委员和副主任委员一般不得来自同一单位。同一人不得同时在3个以上标委会担任委员。"},{"i":8,"n":"第八条","txt":"委员应当具备下列条件： （一）具有中级以上专业技术职称或者相对应的职务； （二）熟悉本专业领域业务工作，具有较高理论水平、扎实的专业知识和丰富的实践经验； （三）掌握标准化基础知识，热心标准化事业，能够积极参加标准化活动，认真履行委员职责和义务； （四）在我国境内依法设立的法人组织中任职，并经任职单位推荐； （五）标委会章程规定的其他条件。"},{"i":9,"n":"第九条","txt":"主任委员和副主任委员除应当具备本办法第八条规定的条件外，还应当具备下列条件： （一）本专业领域的技术专家； （二）在本专业领域内享有较高声誉，具有影响力； （三）具有高级以上专业技术职称或者相对应的职务； （四）熟悉标委会管理程序和工作流程； （五）能够公正履行职责，兼顾各方利益。"},{"i":10,"n":"第十条","txt":"秘书处承担单位应当具备下列条件： （一）在我国境内依法设立、具有法人资格的社会团体或者企业事业组织； （二）有较强的技术实力和行业影响力； （三）将秘书处工作纳入本单位工作计划和日常工作，并为秘书处开展工作提供必要的经费和办公条件； （四）有标准化专职工作人员。 秘书处设秘书长1名，副秘书长一般不超过5名。秘书长和副秘书长由委员兼任，不得来自同一单位。秘书长一般由秘书处承担单位技术专家担任，应当具有较强的组织协调能力，熟悉本领域技术发展情况以及国内外标准化工作情况，具有连续3年以上标准化工作经历。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市工业和信息化主管部门、社会团体、企业事业组织等可以根据行业管理实际和产业发展需求，向工业和信息化部提出筹建标委会的申请，并提交筹建申请材料，说明组建标委会的必要性、可行性、业务范围、标准体系、国内外相关技术组织情况、秘书处承担单位有关情况等。"},{"i":12,"n":"第十二条","txt":"工业和信息化部对筹建申请材料进行审查，满足组建条件的，将标委会的名称、业务范围、秘书处承担单位等材料向社会公开征求意见。 工业和信息化部对社会公众意见进行汇总、协调和处理。对没有不同意见或者相关意见已处理完毕的，工业和信息化部组织专家进行评审，根据评审意见，决定是否准予筹建。"},{"i":13,"n":"第十三条","txt":"准予筹建的，秘书处承担单位应当在6个月内向工业和信息化部报送组建方案。组建方案包括下列材料： （一）标委会基本信息表，标委会委员名单和委员登记表； （二）标委会章程草案，内容包括工作原则、范围、任务、程序，秘书处职责，委员、顾问、观察员的条件和职责，经费管理制度等； （三）秘书处工作细则草案，内容包括工作原则、秘书处工作人员条件和职责、会议制度、文件制度、档案制度、财务制度等； （四）标准体系框架及标准体系表草案，秘书处承担单位的支持措施，近期工作计划等； （五）工业和信息化部规定的其他材料。 不能如期报送组建方案的，应当在前款规定的期限届满30日前向工业和信息化部提交延期组建申请。逾期未报送组建方案且未提交延期组建申请的，取消筹建。"},{"i":14,"n":"第十四条","txt":"工业和信息化部对组建方案进行审查，审查通过后，将组建方案中的委员名单向社会公开征求意见。 工业和信息化部对社会公众意见进行汇总、协调和处理，对没有不同意见或者相关意见已处理完毕的，公告成立标委会。"},{"i":15,"n":"第十五条","txt":"标委会组建分标委会的，应当具备下列条件： （一）业务范围明晰，并在所属标委会业务范围内； （二）标准体系框架明确，有具体的工作任务。 分标委会委员不少于15名，其中主任委员和秘书长各1名，副主任委员和副秘书长一般各不超过3名。 组建分标委会，应当由标委会表决通过后公开征集委员，制定组建方案并报送工业和信息化部。工业和信息化部按照本办法第十四条有关规定公告成立分标委会。"},{"i":16,"n":"第十六条","txt":"新技术、新产业、新业态等领域暂不具备组建标委会或者分标委会条件的，工业和信息化部可以成立标准化工作组。 标准化工作组成立后，工业和信息化部适时组织评估。具备组建标委会或者分标委会条件的，按照本办法有关规定组建。"},{"i":17,"n":"第十七条","txt":"标委会、分标委会、标准化工作组由工业和信息化部统一顺序编号，分别为MIIT/TC×××、MIIT/TC×××/SC××、MIIT/SWG×××。"},{"i":18,"n":"第十八条","txt":"标委会应当加强内部管理，规范组织建设，履行工作职责，接受社会监督。标委会应当每年向工业和信息化部报送年度工作报告。"},{"i":19,"n":"第十九条","txt":"委员应当积极参加标委会活动，履行下列职责： （一）提出行业标准制定、修订等方面的工作建议； （二）按时参加行业标准技术审查和行业标准复审，按时参加标委会年会等工作会议，履行委员投票表决义务； （三）监督主任委员、副主任委员、秘书长、副秘书长及秘书处的工作，监督标委会经费的使用，及时反馈标委会归口行业标准的实施情况； （四）参与本专业领域国际标准化工作，参加工业和信息化部及标委会组织的培训； （五）承担标委会职责范围内和标委会章程规定的相关工作。 委员享有表决权，有权获取标委会的资料和文件。"},{"i":20,"n":"第二十条","txt":"主任委员负责标委会全面工作，负责签发会议决议、行业标准报批文件等标委会重要文件。主任委员可以委托副主任委员签发会议决议、行业标准报批文件等标委会重要文件。"},{"i":21,"n":"第二十一条","txt":"秘书长负责秘书处日常工作，副秘书长协助秘书长开展工作。秘书处具体职责和工作制度由标委会章程和秘书处工作细则规定。秘书处由两个以上单位联合承担的，应当在秘书处工作细则中明确牵头承担单位及各自职责。"},{"i":22,"n":"第二十二条","txt":"根据工作需要，标委会可以聘任顾问，设观察员和联络员。 顾问应当为本专业领域的专家学者，无表决权。观察员可以获得标委会的资料和文件，列席相关工作会议，发表意见、提出建议，无表决权。 鼓励专业领域关联的标委会联合开展跨行业跨领域标准制定。专业领域关联的标委会之间应当互派联络员，协调跨领域或者存在争议的问题。联络员可以获得其负责联络的标委会的资料和文件，列席相关工作会议，发表意见、提出建议，无表决权。联络员应当及时向所属标委会报告联络工作情况。"},{"i":23,"n":"第二十三条","txt":"标委会每年至少召开一次年会，总结上年度工作，安排下年度计划，通报经费使用情况等。标委会可以根据需要不定期召开会议，研究处理相关工作。标委会召开会议，应当提前通知全体委员。 标委会日常工作的文件材料应当及时归档、妥善保管，保管期限不得少于5年。"},{"i":24,"n":"第二十四条","txt":"下列事项由秘书处形成提案，提交标委会审议表决： （一）标委会章程和秘书处工作细则，工作计划； （二）所属专业领域标准体系表，行业标准制定、修订项目的立项建议，行业标准送审稿； （三）标委会委员增补和调整建议，工作经费的预决算及执行情况； （四）分标委会的组建、换届、调整、撤销、注销等事项，分标委会的决议； （五）标委会章程规定应当审议的其他事项。 参加投票的委员不得少于委员总数的3/4。参加投票委员2/3以上赞成且反对意见不超过1/4的，方为通过。表决结果应当形成决议，由秘书处存档。"},{"i":25,"n":"第二十五条","txt":"标委会印章由工业和信息化部制发，由标委会秘书处管理。标委会撤销、变更名称后，应当在5个工作日内将原印章交还至工业和信息化部。 标委会印章属于业务专用章，在开展所属专业领域标准化工作时使用，主要用于上报材料、请示工作、征求意见、召开会议、对外联络以及工业和信息化部规定的其他事项。印章使用应当经标委会主任委员或者其授权的副主任委员签字批准。标委会印章不得用于标委会职责范围以外事项。"},{"i":26,"n":"第二十六条","txt":"标委会不得以营利为目的收取费用，不得采取摊派、有偿署名等方式收取不合理费用。行业标准制定、修订补助经费按照国家有关规定进行管理。 秘书处承担单位应当遵守国家有关财务制度，将标委会的工作经费纳入单位财务统一管理，单独核算，专款专用，每年向全体委员报告年度经费收支情况。"},{"i":27,"n":"第二十七条","txt":"标委会每届任期5年。标委会应当在任期届满6个月前公开征集委员，制定换届方案并报送工业和信息化部。工业和信息化部对换届方案进行审查，审查通过后将换届方案中的委员名单、秘书处承担单位等材料向社会公开征求意见。 工业和信息化部对社会公众意见进行汇总、协调和处理，对没有不同意见或者相关意见已处理完毕的，予以换届。"},{"i":28,"n":"第二十八条","txt":"标委会任期内调整委员的，应当向工业和信息化部提出调整建议，工业和信息化部审查通过后予以调整。 涉及调整主任委员、秘书长，或者一次性调整委员人数超过委员总数1/5的，工业和信息化部还应当将审查通过的调整建议向社会公开征求意见。工业和信息化部对社会公众意见进行汇总、协调和处理，对没有不同意见或者相关意见已处理完毕的，予以调整。"},{"i":29,"n":"第二十九条","txt":"标委会可以根据工作需要，向工业和信息化部提出调整名称、业务范围、秘书处承担单位或者注销标委会等建议。工业和信息化部审查通过后予以调整、注销。"},{"i":30,"n":"第三十条","txt":"工业和信息化部定期对标委会工作进行考核评估，并将考核评估结果向社会公开。 工业和信息化部对行业标准制定、修订补助经费使用情况进行监督检查。"},{"i":31,"n":"第三十一条","txt":"标委会有下列情形之一的，由工业和信息化部责令限期整改： （一）未按照计划完成行业标准制定、修订和复审任务，且无正当理由的； （二）行业标准质量出现严重问题的； （三）未按照本办法有关规定审议表决的； （四）未按照规定使用和管理工作经费的； （五）对分标委会管理不规范的； （六）存在其他违法违规行为的。 整改期满后仍不满足要求的，工业和信息化部视情况对秘书处承担单位进行调整，对标委会进行重新组建或者撤销。"},{"i":32,"n":"第三十二条","txt":"标委会有下列情形之一的，由工业和信息化部重新组建或者撤销： （一）排斥相关方参与行业标准制定、修订活动，为相关方谋取不正当利益，或者有其他严重影响行业标准制定、修订工作公平公正开展的行为的； （二）在工作中有弄虚作假行为的； （三）长期无法正常开展工作的； （四）存在其他重大违法违规行为的。"},{"i":33,"n":"第三十三条","txt":"秘书处承担单位有下列情形之一的，由工业和信息化部对秘书处承担单位进行调整： （一）因秘书处原因致使标委会无法正常开展工作的； （二）利用工作便利为本单位或者相关方谋取不正当利益的； （三）违反规定使用标委会经费，逾期未改正的； （四）存在其他重大违法违规行为的。"},{"i":34,"n":"第三十四条","txt":"委员有下列情形之一的，由标委会报工业和信息化部撤销委员资格： （一）未履行本办法和标委会章程规定职责的； （二）连续两次无故不参加标委会活动的； （三）利用委员身份为本人或者他人谋取不正当利益的； （四）对标委会工作造成不良影响的； （五）存在其他重大违法违规行为的。"},{"i":35,"n":"第三十五条","txt":"在标委会整改或者重新组建期间，工业和信息化部不为其安排行业标准制定、修订项目等任务。被撤销的标委会承担的相关标准化工作可以并入工业和信息化部指定的其他标委会。"},{"i":36,"n":"第三十六条","txt":"本办法第十二条第一款、第十四条第一款、第二十七条第一款、第二十八条第二款规定的向社会公开征求意见的期限，一般不少于30日。 本办法规定的材料式样，由工业和信息化部统一公布和调整。 除本办法另有规定外，分标委会和标准化工作组的工作职责、组建、运行、换届、调整、注销和监督管理等参照标委会相关规定执行。"},{"i":37,"n":"第三十七条","txt":"本办法自2023年2月1日起施行。"}],"gongyehexinxihuabuxingzhengfuyishishibanfa":[{"i":1,"n":"第一条","txt":"为了规范工业和信息化部的行政复议工作，防止和纠正违法的或者不当的具体行政行为，维护公民、法人和其他组织的合法权益，根据《中华人民共和国行政复议法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织向工业和信息化部提出行政复议申请，工业和信息化部受理行政复议申请、作出行政复议决定，适用本办法。"},{"i":3,"n":"第三条","txt":"工业和信息化部法制工作机构具体办理行政复议事项，履行下列职责： （一）受理行政复议申请； （二）向有关组织和人员调查取证，组织听证； （三）审查被复议的具体行政行为是否合法、适当； （四）依法决定行政复议中止、终止； （五）拟订行政复议决定，督促行政复议决定的履行； （六）提出行政复议意见书或者建议书； （七）指导下级部门行政复议相关工作，组织行政复议人员培训； （八）法律、行政法规和规章规定的其他职责。"},{"i":4,"n":"第四条","txt":"工业和信息化部履行行政复议职责，遵循合法、公正、公开、及时、便民的原则，坚持有错必纠，保障法律、法规和规章的正确实施。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织认为工业和信息化部或者省、自治区、直辖市通信管理局及工业和信息化主管部门的具体行政行为侵犯其合法权益的，可以自知道该具体行政行为之日起60日内向工业和信息化部提出行政复议申请；但是法律规定的申请期限超过60日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。"},{"i":6,"n":"第六条","txt":"依照本办法申请行政复议的公民、法人或者其他组织是申请人；作出具体行政行为的行政机关是被申请人。 同申请行政复议的具体行政行为有利害关系的其他公民、法人或者其他组织，可以作为第三人参加行政复议。"},{"i":7,"n":"第七条","txt":"申请人对工业和信息化部或者省、自治区、直辖市通信管理局的具体行政行为不服的，向工业和信息化部申请行政复议。 申请人对省、自治区、直辖市工业和信息化主管部门的具体行政行为不服的，可以向该部门的本级人民政府申请行政复议，也可以依法向工业和信息化部申请行政复议。"},{"i":8,"n":"第八条","txt":"申请人申请行政复议，应当提交行政复议申请书，并载明下列事项： （一）申请人的基本情况，包括：公民的姓名、性别、年龄、身份证号码、工作单位、住所、邮政编码、送达地址、联系方式；法人或者其他组织的名称、住所、邮政编码、统一社会信用代码和法定代表人或者主要负责人的姓名、职务； （二）被申请人的名称； （三）行政复议请求、申请行政复议的主要事实和理由； （四）申请人的签名或者盖章； （五）申请行政复议的日期。 申请人为自然人的，应当提交居民身份证或者其他有效证件复印件；申请人为法人或者其他组织的，应当提交营业执照或者其他有效证件复印件、法定代表人或者主要负责人居民身份证或者其他有效证件复印件。申请人委托代理人代为申请的，还应当提交授权委托书和代理人的居民身份证或者其他有效证件复印件。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，申请人应当提供证明材料： （一）认为被申请人不履行法定职责的，提供曾经要求被申请人履行法定职责而被申请人未履行的证明材料； （二）申请行政复议时一并提出行政赔偿请求的，提供受具体行政行为侵害而造成损害的证明材料； （三）行政复议申请超出本办法第五条规定的申请期限的，提供因不可抗力或者其他正当理由耽误法定申请期限的证明材料； （四）法律、法规规定需要申请人提供证据材料的其他情形。"},{"i":10,"n":"第十条","txt":"申请人书面申请有困难的，可以口头申请行政复议，由工业和信息化部法制工作机构按照本办法第八条规定的事项，当场制作行政复议申请笔录，交申请人核对或者向申请人宣读，并由申请人签字确认。"},{"i":11,"n":"第十一条","txt":"工业和信息化部收到行政复议申请后，应当在5日内进行审查，并分别作出如下处理： （一）行政复议申请符合《中华人民共和国行政复议法》及其实施条例规定的，决定予以受理，并告知申请人； （二）行政复议申请不符合《中华人民共和国行政复议法》及其实施条例规定的，决定不予受理，制作不予受理行政复议申请决定书并告知申请人； （三）行政复议申请符合《中华人民共和国行政复议法》及其实施条例规定，但不属于工业和信息化部受理范围的，告知申请人向有关行政复议机关提出； （四）行政复议申请材料不齐全或者表述不清楚的，制作补正行政复议申请通知书，一次性通知申请人需要补正的所有材料和合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请。补正申请材料所用时间不计入行政复议审理期限。 予以受理的行政复议申请，自工业和信息化部法制工作机构收到行政复议申请之日起即为受理。"},{"i":12,"n":"第十二条","txt":"工业和信息化部法制工作机构应当自受理行政复议申请之日起7日内，制作行政复议答复通知书，连同相关行政复议申请材料发送被申请人。"},{"i":13,"n":"第十三条","txt":"被申请人应当自收到行政复议答复通知书之日起10日内提出书面答复，提交当初作出具体行政行为的证据、依据及其他有关材料，在行政复议过程中不得自行向申请人和其他有关组织或者个人收集证据。 被申请人的书面答复应当载明下列内容： （一）被申请人名称、地址、法定代表人姓名； （二）作出具体行政行为的事实、证据及法律依据，对有关事实的陈述应当注明相应的证据材料； （三）对申请人的行政复议请求、事实、理由作出全面答复及必要的举证； （四）提出维持、变更、撤销、驳回或者确认违法的答复意见； （五）作出答复的时间、联系人，并加盖印章。 被申请人是工业和信息化部的，由承办具体行政行为的有关司局依前款规定负责提出书面答复。"},{"i":14,"n":"第十四条","txt":"行政复议期间具体行政行为不停止执行。但是有下列情形之一的，可以停止执行： （一）被申请人认为需要停止执行的； （二）工业和信息化部认为需要停止执行的； （三）申请人申请停止执行，工业和信息化部认为其要求合理，决定停止执行的； （四）法律规定停止执行的。 工业和信息化部决定停止执行的，应当书面告知被申请人、申请人、第三人。"},{"i":15,"n":"第十五条","txt":"行政复议原则上采取书面审查的办法。工业和信息化部法制工作机构在办理行政复议事项过程中可以调取、查阅、复制相关证据材料。 工业和信息化部法制工作机构认为必要的，可以实地调查取证。需要现场勘验或者鉴定的，现场勘验、鉴定所用时间不计入行政复议审理期限。"},{"i":16,"n":"第十六条","txt":"对重大、复杂的案件，工业和信息化部法制工作机构可以组织法律顾问、专家进行研究论证；申请人提出要求或者工业和信息化部法制工作机构认为必要时，可以采取听证的方式审理。听证按照下列程序进行： （一）工业和信息化部法制工作机构应当将听证的时间、地点、具体要求等事项提前5日通知有关当事人； （二）行政复议听证人员为不少于3人的单数，由工业和信息化部法制工作机构确定，并指定其中1人为听证主持人； （三）举行听证时，被申请人应当提供书面答复及相关证据、依据等材料，证明其具体行政行为的合法性、合理性，申请人、第三人可以提出证据进行申辩和质证； （四）听证应当制作笔录，听证笔录应当交听证参加人确认无误后签字或者盖章。"},{"i":17,"n":"第十七条","txt":"申请人、第三人需要查阅被申请人提交的书面材料的，应当向工业和信息化部法制工作机构提出查阅申请，并提供有效证件。查阅时不得毁损、篡改材料。"},{"i":18,"n":"第十八条","txt":"申请人在申请行政复议时，依法一并提出审查《中华人民共和国行政复议法》第七条所列的、被申请人作出具体行政行为所依据的规定的，工业和信息化部一并受理。有权处理的，应当在30日内依法处理；无权处理的，应当在7日内按照法定程序转送有权处理的国家机关依法处理。处理期间，中止对具体行政行为的审查。"},{"i":19,"n":"第十九条","txt":"行政复议期间出现法定的中止情形的，行政复议中止。行政复议中止的原因消除后，应当及时恢复审理。 中止审理、恢复审理的决定由工业和信息化部法制工作机构作出，并书面通知申请人、被申请人、第三人。"},{"i":20,"n":"第二十条","txt":"行政复议期间出现法定的终止情形的，行政复议终止。 行政复议决定作出前，申请人要求撤回行政复议申请，并经工业和信息化部法制工作机构同意的，行政复议终止。 行政复议终止的，工业和信息化部制作行政复议终止决定书，并送达申请人、被申请人、第三人。"},{"i":21,"n":"第二十一条","txt":"工业和信息化部法制工作机构应当对被申请人作出的具体行政行为进行审查，提出意见，经工业和信息化部负责人同意或者集体讨论通过后，按照下列规定作出行政复议决定： （一）具体行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，决定维持； （二）被申请人不履行法定职责的，决定其在一定期限内履行； （三）具体行政行为有下列情形之一的，决定撤销、变更或者确认该具体行政行为违法： 1.主要事实不清、证据不足的； 2.适用依据错误的； 3.违反法定程序的； 4.超越或者滥用职权的； 5.具体行政行为明显不当的。 （四）被申请人未依法提出书面答复、提交当初作出具体行政行为的证据、依据和其他有关材料的，视为该具体行政行为没有证据、依据，决定撤销该具体行政行为。 决定撤销或者确认被申请人的具体行政行为违法的，可以责令其在一定期限内重新作出具体行政行为。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，工业和信息化部驳回行政复议申请： （一）申请人认为被申请人不履行法定职责申请行政复议，受理后发现该被申请人没有相应的法定职责或者在受理前已经履行法定职责的； （二）受理行政复议申请后，发现该行政复议申请不符合法定受理条件的。"},{"i":23,"n":"第二十三条","txt":"工业和信息化部自受理行政复议申请之日起60日内作出行政复议决定。案件情况复杂，不能在规定期限内作出行政复议决定的，经工业和信息化部负责人批准，可以适当延长，延长期限最多不超过30日。 延长行政复议期限的，应当制作延期审理通知书并送达申请人、被申请人、第三人。"},{"i":24,"n":"第二十四条","txt":"工业和信息化部作出行政复议决定，应当制作行政复议决定书，送达申请人、被申请人、第三人。"},{"i":25,"n":"第二十五条","txt":"被申请人应当履行行政复议决定。被申请人不履行或者无正当理由拖延履行行政复议决定的，由工业和信息化部责令其限期履行，制作责令履行行政复议决定通知书并送达被申请人、申请人、第三人。 被申请人收到责令履行行政复议决定通知书后，应当在规定期限内履行行政复议决定，并将履行情况报送工业和信息化部法制工作机构。"},{"i":26,"n":"第二十六条","txt":"工业和信息化部在行政复议期间发现被申请人的相关具体行政行为违法或者需要做好善后工作的，可以制作行政复议意见书并送达被申请人；被申请人应当自收到行政复议意见书之日起60日内，将执行意见书的情况通报工业和信息化部法制工作机构。 行政复议意见书应当载明具体行政行为存在的问题、认定事实、判断依据以及整改意见等。"},{"i":27,"n":"第二十七条","txt":"工业和信息化部法制工作机构在行政复议期间发现法律、法规、规章实施中带有普遍性问题的，可以制作行政复议建议书，向有关机关提出完善制度和改进执法的建议。"},{"i":28,"n":"第二十八条","txt":"工业和信息化部建立行政复议工作通报制度。工业和信息化部法制工作机构应当每年将复议案件办理情况上报工业和信息化部负责人并进行通报。 工业和信息化部法制工作机构协助考核机构，将行政复议工作情况纳入年度考核。"},{"i":29,"n":"第二十九条","txt":"工业和信息化部法制工作机构应当定期组织行政复议人员业务培训，提高行政复议人员的专业素质。"},{"i":30,"n":"第三十条","txt":"工业和信息化部对在行政复议工作中做出显著成绩的机构和个人，根据实际情况给予表彰或者奖励。"},{"i":31,"n":"第三十一条","txt":"工业和信息化部受理行政复议申请不得向申请人收取任何费用。行政复议所需经费，列入工业和信息化部行政经费予以保障。"},{"i":32,"n":"第三十二条","txt":"本办法关于行政复议期间有关“5日”“7日”的规定是指工作日，不含节假日。"},{"i":33,"n":"第三十三条","txt":"本办法自2017年9月1日起施行。2002年10月22日公布的《信息产业部行政复议实施办法》（原信息产业部令第25号）同时废止。"}],"gongyehexinxihuabuxingzhengxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范行政许可实施行为，保护公民、法人和其他组织的合法权益，维护公共利益和社会秩序，按照《国务院对确需保留的行政审批项目设定行政许可的决定》有关“国务院有关部门应当对实施本决定所列各项行政许可的条件等作出具体规定，并予以公布”的要求，依据《中华人民共和国行政许可法》的相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国工业和信息化部（以下称工业和信息化部）及受其委托实施行政许可的单位、省、自治区、直辖市通信管理局等单位（以下统称行政许可实施机关）实施行政许可，应当遵守法定权限、范围、条件和程序，遵循公开、公平、公正、便民和高效的原则。"},{"i":3,"n":"第三条","txt":"行政许可实施机关应当建立健全监督制度，依法对被许可人从事行政许可事项的活动实施监督检查。监督检查可以采取书面检查、实地检查、抽样检查或者检验、检测等方式。实施监督检查时，行政许可实施机关有权向被许可人询问有关情况，要求被许可人提供相关材料，进入被许可人的机房等场所调查情况，被许可人应当予以配合。 行政许可实施机关依法对被许可人进行检查时，应当记录检查的情况和处理结果，由检查人员签字后归档，公众有权查阅执法检查记录。 行政许可实施机关实施监督检查不得向被许可人收取任何费用，不得妨碍被许可人正常的生产经营活动，不得索取或者收受被许可人的财物，不得谋取其他利益。"},{"i":4,"n":"第四条","txt":"申请人隐瞒有关情况或提供虚假材料申请行政许可的，行政许可实施机关不予受理或者不予行政许可，并给予警告；行政许可申请属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在一年内不得再次申请该行政许可。"},{"i":5,"n":"第五条","txt":"被许可人以欺骗、贿赂等不正当手段取得行政许可的，行政许可实施机关应当撤销其行政许可，给予警告，并视情节轻重处5000元以上3万元以下的罚款；但撤销行政许可可能对公共利益造成重大损害的，不予撤销；行政许可申请属于直接关系公共安全、人身健康、生命财产安全事项的，申请人三年内不得再次申请该行政许可。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，行政许可实施机关应当依法注销行政许可，并向社会公告： （一）行政许可有效期届满未延续的。 （二）取得资格许可的公民死亡或者丧失行为能力的。 （三）取得行政许可的法人或者其他组织依法终止的。 （四）行政许可依法被撤销、撤回，或者行政许可证件依法被吊销的。 （五）因不可抗力导致行政许可事项无法实施的。 （六）法律、行政法规规定的应当注销行政许可的其他情形。"},{"i":7,"n":"第七条","txt":"行政许可实施机关发现被许可人不再符合相关行政许可条件的，应当责令被许可人限期改正，处以3万元以下的罚款，并将上述情况向社会公告。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织未经行政许可，擅自从事相关行政许可活动的，或者被许可人超越行政许可范围从事相关活动的，行政许可实施机关应当依法采取措施予以制止，并依据相关法律、行政法规、规章的规定予以处罚；法律、行政法规、规章未作规定的，应当责令其停止违法行为，可以并处3万元以下的罚款。"},{"i":9,"n":"第九条","txt":"被许可人转让、涂改、伪造、倒卖、出租、出借行政许可证件的，由发证机关依据相关法律、行政法规、规章的规定予以处罚；法律、行政法规、规章未作规定的，由发证机关责令改正，给予警告，可以并处3万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":10,"n":"第十条","txt":"被许可人从事行政许可活动违反相关法律、行政法规或者规章的，依照相关法律、行政法规或者规章的规定处理。"},{"i":11,"n":"第十一条","txt":"行政许可实施机关及其工作人员有下列情形之一的，由上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分： （一）对符合法定条件的行政许可申请不予受理的。 （二）不在办公场所公示依法应当公示的材料的。 （三）在受理、审查、决定行政许可过程中，未向申请人、利害关系人履行法定告知义务的。 （四）申请人提交的申请材料不齐全、不符合法定形式，不一次告知申请人应当补正的全部内容的。 （五）未依法说明不受理行政许可申请或者不予行政许可的理由的。 （六）依法应当举行听证而不举行听证的。"},{"i":12,"n":"第十二条","txt":"本办法自2009年4月10日起施行。本办法施行前颁布的有关规定与本办法不一致的，按照本办法执行。2004年12月2日公布的《信息产业部负责实施的行政许可项目及其条件、程序、期限规定（第一批）》（中华人民共和国信息产业部令第31号）同时废止。 附件：行政许可项目的条件和程序规定（第一批）"}],"gongyejienengjianchabanfa":[{"i":1,"n":"第一条","txt":"为了规范工业节能监察，促进企业节约能源和提高能源利用效率，加快绿色低碳发展，推动工业领域碳达峰碳中和，根据《中华人民共和国节约能源法》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称工业节能监察，是指工业节能监察部门依法对工业和信息化领域能源生产、使用、服务等相关企业、机构执行节能管理有关法律、法规、规章以及强制性国家标准情况进行监督检查，查处违法用能，提出依法用能、合理用能建议的行为。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责全国工业节能监察工作，组织制定和实施全国工业节能监察年度工作计划，加强全国工业节能监察的指导和统筹协调。 县级以上地方人民政府工业和信息化主管部门或者县级以上地方人民政府确定的其他管理工业节能监察的部门负责本行政区域内工业节能监察，制定和实施本行政区域内工业节能监察年度工作计划。 工业和信息化部、县级以上地方人民政府工业和信息化主管部门、县级以上地方人民政府确定的其他管理工业节能监察的部门，统称工业节能监察部门。"},{"i":4,"n":"第四条","txt":"工业节能监察遵循依法、公开、公平、公正和效能原则。 工业节能监察不得向被监察单位收取费用。"},{"i":5,"n":"第五条","txt":"被监察单位应当配合工业节能监察，如实说明情况，提供有关资料，不得隐瞒、虚构事实，不得伪造、隐匿、销毁、篡改有关资料，不得拒绝和阻碍工业节能监察。"},{"i":6,"n":"第六条","txt":"工业节能监察部门可以依据法律、法规、规章的规定，在其法定权限范围内书面委托符合法律规定条件的组织实施工业节能监察。 受委托组织应当在委托范围内以委托部门的名义实施工业节能监察，及时向委托部门报告工业节能监察情况；不得再委托其他组织或者个人实施工业节能监察。 委托部门应当加强对受委托组织实施工业节能监察的监督。"},{"i":7,"n":"第七条","txt":"工业节能监察应当由2名以上取得行政执法资格的工业节能监察人员实施。"},{"i":8,"n":"第八条","txt":"工业节能监察人员与被监察单位有直接利害关系或者有其他关系可能影响公正监察的，应当回避。 被监察单位认为工业节能监察人员与被监察单位有直接利害关系或者有其他关系可能影响公正监察的，有权申请回避。"},{"i":9,"n":"第九条","txt":"工业节能监察部门、受委托实施工业节能监察的组织，因工业节能监察需要，可以聘请第三方机构或者有关专家开展工业节能监察辅助工作。 从事工业节能监察辅助工作的机构、人员，不得独立开展工业节能监察。"},{"i":10,"n":"第十条","txt":"工业节能监察包括下列内容： （一）执行单位产品能耗限额，用能产品、设备能源效率等强制性国家标准情况； （二）执行落后的耗能过高的用能产品、设备和生产工艺淘汰制度情况； （三）加强能源计量管理情况； （四）建立能源消费统计和能源利用状况分析制度情况； （五）建立节能目标责任制情况，加强节能管理，制定并实施节能计划和节能技术措施情况； （六）开展节能宣传教育和岗位节能培训情况； （七）工业节能监察意见落实情况； （八）法律、法规、规章规定的其他需要开展工业节能监察的事项。"},{"i":11,"n":"第十一条","txt":"对重点用能企业的工业节能监察还包括下列内容： （一）完成年度工业节能目标情况； （二）执行能源管理岗位设立和能源管理负责人聘任、培训制度情况； （三）执行能源利用状况报告制度情况； （四）建立和实施能源管理体系情况、测量管理体系情况； （五）开展能源计量审查情况； （六）法律、法规、规章规定的对重点用能企业其他需要开展工业节能监察的事项。"},{"i":12,"n":"第十二条","txt":"工业节能监察采取现场监察或者书面监察方式。鼓励采用信息化手段开展工业节能监察。"},{"i":13,"n":"第十三条","txt":"实施下列工业节能监察，应当采取现场监察方式： （一）单位产品能耗限额，用能产品、设备能源效率等强制性国家标准执行情况； （二）落后的耗能过高的用能产品、设备和生产工艺淘汰制度执行情况； （三）加强能源计量管理情况； （四）建立能源消费统计制度情况； （五）节能监察意见落实情况； （六）重点用能企业年度工业节能目标完成情况； （七）法律、法规、规章规定应当采取现场监察的其他事项。 实施前款规定以外事项的工业节能监察，可以采取书面监察方式。"},{"i":14,"n":"第十四条","txt":"实施现场监察的，应当提前5个工作日以书面形式告知被监察单位实施工业节能监察的依据、内容、时间和要求。因查处违法案件、以抽查方式实施的监察，以及依据本办法第十九条规定实施的监察除外。"},{"i":15,"n":"第十五条","txt":"实施现场监察的，工业节能监察人员应当主动向被监察单位出示行政执法证件。未出示行政执法证件或者行政执法证件无效的，被监察单位有权拒绝接受工业节能监察。"},{"i":16,"n":"第十六条","txt":"实施现场监察，可以采取以下措施： （一）进入有关场所进行勘察、采样、拍照、录音、录像； （二）查阅、复制或者摘录有关资料； （三）询问有关人员，要求说明相关事项、提供相关材料； （四）对用能产品、设备和生产工艺的能源利用状况等进行监测和分析评价； （五）法律、法规、规章规定可以采取的其他措施。"},{"i":17,"n":"第十七条","txt":"实施现场监察，应当制作现场监察笔录，如实记录监察时间、地点、内容、参加人员、过程等事项，经被监察单位核对无误后签字或者盖章确认。被监察单位拒绝确认的，由2名以上工业节能监察人员在现场监察笔录中注明。"},{"i":18,"n":"第十八条","txt":"实施书面监察，应当以书面形式告知被监察单位监察的依据、内容，列明被监察单位需报送资料的名称、内容、时间和其他要求等。"},{"i":19,"n":"第十九条","txt":"实施书面监察，发现被监察单位所报材料不完整或者存在疑问的，应当要求被监察单位补充或者书面说明；发现所报材料存在隐瞒事实、弄虚作假等行为的，应当实施现场监察。"},{"i":20,"n":"第二十条","txt":"实施工业节能监察，发现被监察单位有违反节能管理有关法律、法规、规章以及强制性国家标准的行为，依法应当给予行政处罚的，按照《中华人民共和国节约能源法》《中华人民共和国行政处罚法》以及其他相关法律、法规、规章的规定处理。 依据前款规定给予被监察单位行政处罚的，应当责令被监察单位改正或者限期改正违法行为。"},{"i":21,"n":"第二十一条","txt":"实施工业节能监察，发现被监察单位有违反节能管理有关法律、法规、规章以及强制性国家标准的行为，但依法可以不予行政处罚的，应当对被监察单位进行教育，责令被监察单位改正或者限期改正违法行为。"},{"i":22,"n":"第二十二条","txt":"限期改正违法行为的期限一般不超过6个月。确需延长改正期限的，经被监察单位申请和工业节能监察部门或者受委托实施工业节能监察的组织批准，可以延长3个月。法律、法规、规章另有规定的，从其规定。"},{"i":23,"n":"第二十三条","txt":"实施工业节能监察，发现被监察单位有不合理用能行为，但未违反节能管理有关法律、法规、规章以及强制性国家标准的，应当依法向被监察单位提出合理用能的监察意见。"},{"i":24,"n":"第二十四条","txt":"工业节能监察部门应当加强工业节能监察能力建设，健全工业节能监察体系。"},{"i":25,"n":"第二十五条","txt":"工业节能监察部门应当加强部门联动，统筹制定工业节能监察年度工作计划。 在同一年度内对同一被监察单位的同一监察事项，不得重复实施工业节能监察，但确认被监察单位落实监察意见、改正违法行为，以及查处违法案件等原因实施的工业节能监察除外。法律、法规、规章另有规定的，从其规定。"},{"i":26,"n":"第二十六条","txt":"工业节能监察部门、受委托实施工业节能监察的组织应当以文字、录像等形式，对工业节能监察进行全过程记录，并按照国家有关规定归档保存。"},{"i":27,"n":"第二十七条","txt":"工业节能监察部门、受委托实施工业节能监察的组织及其工作人员，以及其他参加工业节能监察的机构、人员，对在工业节能监察中知悉的国家秘密、商业秘密或者个人隐私信息，应当依法予以保密。"},{"i":28,"n":"第二十八条","txt":"工业节能监察人员在工业节能监察中滥用职权、玩忽职守、徇私舞弊构成犯罪的，依法追究刑事责任；不构成犯罪的，依法给予处分。"},{"i":29,"n":"第二十九条","txt":"本办法自2023年2月1日起施行。"}],"gongyejienengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强工业节能管理，健全工业节能管理体系，持续提高能源利用效率，推动绿色低碳循环发展，促进生态文明建设，根据《中华人民共和国节约能源法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称工业节能，是指在工业领域贯彻节约资源和保护环境的基本国策，加强工业用能管理，采取技术上可行、经济上合理以及环境和社会可以承受的措施，在工业领域各个环节降低能源消耗，减少污染物排放，高效合理地利用能源。"},{"i":3,"n":"第三条","txt":"本办法适用于中华人民共和国境内工业领域的用能及节能监督管理活动。"},{"i":4,"n":"第四条","txt":"工业和信息化部负责全国工业节能监督管理工作，组织制定工业能源战略和规划、能源消费总量控制和节能目标、节能政策和标准，组织协调工业节能新技术、新产品、新设备、新材料的推广应用，指导和组织工业节能监察工作等。 县级以上地方人民政府工业和信息化主管部门负责本行政区域内工业节能监督管理工作。"},{"i":5,"n":"第五条","txt":"工业企业是工业节能主体，应当严格执行节能法律、法规、规章和标准，加快节能技术进步，完善节能管理机制，提高能源利用效率，并接受工业和信息化主管部门的节能监督管理。"},{"i":6,"n":"第六条","txt":"鼓励行业协会等社会组织在工业节能规划、节能标准的制定和实施、节能技术推广、能源消费统计、节能宣传培训和信息咨询、能效水平对标达标等方面发挥积极作用。"},{"i":7,"n":"第七条","txt":"各级工业和信息化主管部门应当编制并组织实施工业节能规划或者行动方案。"},{"i":8,"n":"第八条","txt":"各级工业和信息化主管部门应当加强产业结构调整，会同有关部门制定有利于工业节能减排的产业政策，综合运用阶梯电价、差别电价、惩罚性电价等价格政策，以及财税支持、绿色金融等手段，推动传统产业绿色化改造和节能产业发展。 各级工业和信息化主管部门应当推动高效节能产品和设备纳入政府采购名录，在政府性投资建设项目招标中优先采用。"},{"i":9,"n":"第九条","txt":"工业和信息化部建立工业节能技术、产品的遴选、评价及推广机制，发布先进适用工业节能技术、高效节能设备（产品）推荐目录，以及达不到强制性能效标准的落后工艺技术装备淘汰目录。加快先进工业节能技术、工艺和设备的推广应用，加强工业领域能源需求侧管理，培育工业行业能效评估中心，推进工业企业节能技术进步。 鼓励关键节能技术攻关和重大节能装备研发，组织实施节能技术装备产业化示范，促进节能装备制造业发展。"},{"i":10,"n":"第十条","txt":"工业和信息化部依法组织制定并适时修订单位产品能耗限额、工业用能设备（产品）能源利用效率等相关标准以及节能技术规范，并组织实施和监督。 鼓励地方和工业企业依法制定严于国家标准、行业标准的地方工业节能标准和企业节能标准。 引导行业协会等社会组织和产业技术联盟根据本行业特点制定团体节能标准。"},{"i":11,"n":"第十一条","txt":"工业和信息化部组织编制工业能效指南，发布主要耗能行业产品（工序）等工业能效相关指标，建立行业能效水平指标体系并实行动态调整。"},{"i":12,"n":"第十二条","txt":"各级工业和信息化主管部门根据工业能源消费状况和工业经济发展情况，研究提出本行政区域工业能源消费总量控制目标和节能目标，实行目标管理。"},{"i":13,"n":"第十三条","txt":"各级工业和信息化主管部门应当依据职责对工业企业固定资产投资项目节能评估报告开展有关节能审查工作。对通过审查的项目，应当加强事中事后监管，对节能措施落实情况进行监督管理。"},{"i":14,"n":"第十四条","txt":"各级工业和信息化主管部门应当定期分析工业能源消费和工业节能形势，建立工业节能形势研判和工业能耗预警机制。"},{"i":15,"n":"第十五条","txt":"各级工业和信息化主管部门应当建立工业节能管理岗位人员和专业技术人员的教育培训机制，制定教育培训计划和大纲，组织开展专项教育和岗位培训。 各级工业和信息化主管部门应当开展工业节能宣传活动，积极宣传工业节能政策法规、节能技术和先进经验等。"},{"i":16,"n":"第十六条","txt":"各级工业和信息化主管部门应当培育节能服务产业发展，支持节能服务机构开展工业节能咨询、设计、评估、计量、检测、审计、认证等服务，积极推广合同能源管理、节能设备租赁、政府和社会资本合作模式、节能自愿协议等节能机制。科学确立用能权、碳排放权初始分配，开展用能权、碳排放权交易相关工作。"},{"i":17,"n":"第十七条","txt":"工业和信息化部指导全国的工业节能监察工作，组织制定和实施全国工业节能监察年度工作计划。 县级以上地方人民政府工业和信息化主管部门应当结合本地区实际情况，组织实施本地区工业节能监察工作。"},{"i":18,"n":"第十八条","txt":"各级工业和信息化主管部门应当加强节能监察队伍建设，建立健全节能监察体系。 节能监察机构所需经费依法列入同级财政预算，支持完善硬件设施、加强能力建设、开展业务培训。实施节能监察不得向监察对象收取费用。"},{"i":19,"n":"第十九条","txt":"各级工业和信息化主管部门应当组织节能监察机构，对工业企业执行节能法律法规情况、强制性单位产品能耗限额及其他强制性节能标准贯彻执行情况、落后用能工艺技术设备（产品）淘汰情况、固定资产投资项目节能评估和审查意见落实情况、节能服务机构执行节能法律法规情况等开展节能监察。 各级工业和信息化主管部门应当明确年度工业节能监察重点任务，并根据需要组织节能监察机构开展联合监察、异地监察等。 工业和信息化部可以根据需要委托地方节能监察机构执行有关专项监察任务。"},{"i":20,"n":"第二十条","txt":"工业节能监察应当主要采取现场监察方式，必要时可以采取书面监察等方式。现场监察应当由两名以上节能监察人员进行，可以采取勘察、采样、拍照、录像、查阅有关文件资料和账目，约见和询问有关人员，对用能产品、设备和生产工艺的能源利用状况进行监测和分析评价等措施。"},{"i":21,"n":"第二十一条","txt":"节能监察机构应当建立工业节能监察情况公布制度，定期公开工业节能监察结果，主动接受社会监督。"},{"i":22,"n":"第二十二条","txt":"工业企业应当加强节能减排工作组织领导，建立健全能源管理制度，制定并实施企业节能计划，提高能源利用效率。"},{"i":23,"n":"第二十三条","txt":"工业企业应当设立可测量、可考核的年度节能指标，完善节能目标考核奖惩制度，明确岗位目标责任，加强激励约束。"},{"i":24,"n":"第二十四条","txt":"工业企业对各类能源消耗实行分级分类计量，合理配备和使用符合国家标准的能源计量器具，提高能源计量基础能力，确保原始数据真实、准确、完整。"},{"i":25,"n":"第二十五条","txt":"工业企业应当明确能源统计人员，建立健全能源原始记录和统计台账，加强能源数据采集管理，并按照规定报送有关统计数据和资料。"},{"i":26,"n":"第二十六条","txt":"工业企业应当严格执行国家用能设备（产品）能效标准及单位产品能耗限额标准等强制性标准，禁止购买、使用和生产国家明令淘汰的用能设备（产品），不得将国家明令淘汰的用能工艺、设备（产品）转让或者租借他人使用。"},{"i":27,"n":"第二十七条","txt":"鼓励工业企业加强节能技术创新和技术改造，开展节能技术应用研究，开发节能关键技术，促进节能技术成果转化，采用高效的节能工艺、技术、设备（产品）。 鼓励工业企业创建“绿色工厂”，开发应用智能微电网、分布式光伏发电、余热余压利用和绿色照明等技术，发展和使用绿色清洁低碳能源。"},{"i":28,"n":"第二十八条","txt":"工业企业应当定期对员工进行节能政策法规宣传教育和岗位技术培训。"},{"i":29,"n":"第二十九条","txt":"加强对重点用能工业企业的节能管理。重点用能工业企业包括: （一）年综合能源消费总量一万吨标准煤（分别折合8000万千瓦时用电、6800吨柴油或者760万立方米天然气）以上的工业企业； （二）省、自治区、直辖市工业和信息化主管部门确定的年综合能源消费总量五千吨标准煤（分别折合4000万千瓦时用电、3400吨柴油或者380万立方米天然气）以上不满一万吨标准煤的工业企业。"},{"i":30,"n":"第三十条","txt":"工业和信息化部加强对全国重点用能工业企业节能管理的指导、监督。 省、自治区、直辖市工业和信息化主管部门对本行政区域内重点用能工业企业节能实施监督管理。 设区的市和县级人民政府工业和信息化主管部门在上级工业和信息化主管部门的指导下，对重点用能工业企业实施属地管理，并可以根据实际情况，确定重点用能工业企业以外的工业企业开展节能监督管理。"},{"i":31,"n":"第三十一条","txt":"重点用能工业企业应当根据能源消费总量和生产场所集中程度、生产工艺复杂程度，设立能源统计、计量、技术和综合管理岗位，任用具有节能专业知识、实际工作经验及中级以上技术职称的企业高级管理人员担任能源管理负责人，形成有岗、有责、全员参与的能源管理组织体系。 重点用能工业企业能源管理岗位设立和能源管理负责人任用情况应当报送有关的工业和信息化主管部门备案。"},{"i":32,"n":"第三十二条","txt":"鼓励重点用能工业企业开展能源审计，并根据审计结果制定企业节能规划和节能技术改造方案，跟踪、落实节能改造项目的实施情况。"},{"i":33,"n":"第三十三条","txt":"重点用能工业企业应当每年向有关的工业和信息化主管部门报送上年度的能源利用状况报告。能源利用状况报告包括能源购入、加工、转换与消费情况，单位产品能耗、主要耗能设备和工艺能耗、能源利用效率，能源管理、节能措施、节能效益分析、节能目标完成情况以及能源消费预测等内容。"},{"i":34,"n":"第三十四条","txt":"重点用能工业企业不能完成年度节能目标的，由有关的工业和信息化主管部门予以通报。"},{"i":35,"n":"第三十五条","txt":"重点用能工业企业应当积极履行社会责任，鼓励重点用能工业企业定期发布包含能源利用、节能管理、员工关怀等内容的企业社会责任报告。"},{"i":36,"n":"第三十六条","txt":"重点用能工业企业应当开展能效水平对标达标活动，确立能效标杆，制定实施方案，完善节能管理，实施重大节能技术改造工程，争创能效“领跑者”。"},{"i":37,"n":"第三十七条","txt":"鼓励重点用能工业企业建设能源管控中心系统，利用自动化、信息化技术，对企业能源系统的生产、输配和消耗实施动态监控和管理，改进和优化能源平衡，提高企业能源利用效率和管理水平。"},{"i":38,"n":"第三十八条","txt":"重点用能工业企业应当建立能源管理体系，采用先进节能管理方法与技术，完善能源利用全过程管理，促进企业节能文化建设。"},{"i":39,"n":"第三十九条","txt":"各级工业和信息化主管部门和相关部门依据职权，对有下列情形之一的工业企业，依照《中华人民共和国节约能源法》等法律法规予以责令限期改正、责令停用相关设备、警告、罚款等，并向社会公开： （一）用能不符合强制性能耗限额和能效标准的； （二）能源统计和能源计量不符合国家相关要求的； （三）能源数据弄虚作假的； （四）生产、使用国家明令淘汰的高耗能落后用能产品、设备和工艺的； （五）违反节能法律、法规的其他情形。"},{"i":40,"n":"第四十条","txt":"各级工业和信息化主管部门及节能监察机构工作人员，在工业节能管理中有下列情形之一的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）泄露企业技术秘密、商业秘密的； （二）利用职务上的便利谋取非法利益的； （三）违法收取费用的； （四）滥用职权、玩忽职守、徇私舞弊的。"},{"i":41,"n":"第四十一条","txt":"县级以上地方人民政府工业和信息化主管部门可以依据本办法和本地实际，制定具体实施办法。"},{"i":42,"n":"第四十二条","txt":"本办法自2016年6月30日起施行。"}],"gongyetongxinyehangyebiaozhunzhidingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范工业通信业行业标准制定程序，提高标准制定质量，根据《中华人民共和国标准化法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"工业通信业行业标准（以下简称行业标准）的立项、起草、技术审查、批准、发布、复审等制定活动，适用本办法。"},{"i":3,"n":"第三条","txt":"制定行业标准，应当遵循公平公正、开放透明、充分协商原则，有利于科学合理利用资源，推广科学技术成果，保证标准的科学性、规范性、时效性，做到技术上先进、经济上合理。"},{"i":4,"n":"第四条","txt":"制定行业标准，应当重点围绕重要产品、工程技术、服务和行业管理标准。涉及融合发展的新兴技术领域的，支持联合制定行业标准。"},{"i":5,"n":"第五条","txt":"工业和信息化部负责行业标准制定的管理工作。 省、自治区、直辖市工业和信息化主管部门协助工业和信息化部做好行业标准制定管理相关工作。"},{"i":6,"n":"第六条","txt":"标准化技术委员会、标准化专家组等单位和组织（以下统称标准化技术组织）按照本办法规定，负责所属领域行业标准起草、技术审查、复审、修订等具体工作。"},{"i":7,"n":"第七条","txt":"有关行业协会（联合会）和标准化专业机构等（以下统称初审机构）按照本办法规定，承担行业标准制定相关工作。"},{"i":8,"n":"第八条","txt":"政府部门、社会团体、企业事业组织以及公民可以向工业和信息化部提出行业标准制定或者修订的立项建议。 提出立项建议，应当书面说明制定或者修订行业标准的必要性、可行性、适用范围等内容。"},{"i":9,"n":"第九条","txt":"工业和信息化部组织有关标准化技术组织对立项建议进行论证评估。 标准化技术组织应当围绕有关政府部门、企业、社会团体、消费者等方面的实际需求进行研究，对标准制定或者修订的必要性、可行性进行论证评估，形成评估意见报送对应初审机构，经初审机构初审后报送工业和信息化部；没有对应初审机构的，直接报送工业和信息化部。 工业和信息化部可以根据行业管理和产业发展需要提出行业标准制定或者修订项目。"},{"i":10,"n":"第十条","txt":"工业和信息化部对立项建议、评估意见和初审意见进行研究，制定行业标准制定、修订计划草案，向社会公开征求意见。"},{"i":11,"n":"第十一条","txt":"工业和信息化部对社会公众意见进行汇总、协调和处理。对没有不同意见或者相关意见已处理完毕的立项建议，工业和信息化部组织专家进行评审，根据评审意见制定并公布行业标准制定、修订计划。 行业标准制定、修订计划应当明确项目名称、主要起草单位、完成时限等内容。行业标准制定周期一般不超过24个月，修订周期一般不超过18个月。"},{"i":12,"n":"第十二条","txt":"标准化技术组织在行业标准制定、修订计划执行中需要对项目作合并、撤销等重大调整的，应当向对应初审机构提出，经初审机构初审后报送工业和信息化部审批；没有对应初审机构的，直接报送工业和信息化部审批。"},{"i":13,"n":"第十三条","txt":"标准化技术组织负责行业标准起草的组织工作，成立标准起草工作组具体负责起草工作。 标准起草工作组应当广泛征求有关方面意见，组织对标准相关事项进行调查分析、实验、论证，形成行业标准征求意见稿和编制说明。"},{"i":14,"n":"第十四条","txt":"行业标准征求意见稿和编制说明由标准化技术组织向社会公开征求意见。 标准起草工作组应当对社会公众意见进行汇总和研究，填写行业标准征求意见汇总处理表，形成行业标准送审稿，报送标准化技术组织进行技术审查。"},{"i":15,"n":"第十五条","txt":"标准化技术组织对行业标准送审稿进行技术审查，可以采用会议审查或者函审形式。对经济技术意义重大、涉及面广、分歧意见多的行业标准，应当会议审查。 会议审查的，标准化技术组织应当形成会议纪要，内容包括审查结论和参加会议人员情况等。函审的，标准化技术组织应当组织填写行业标准送审稿函审单，形成函审结论。"},{"i":16,"n":"第十六条","txt":"行业标准送审稿由标准化技术委员会进行技术审查的，参加投票的委员不得少于委员总数的3/4。 参加投票委员2/3以上赞成且反对意见不超过1/4的，方为技术审查通过。"},{"i":17,"n":"第十七条","txt":"行业标准送审稿由标准化技术委员会以外的标准化技术组织进行技术审查的，一般应当组织生产者、经营者、使用者、消费者、公共利益方等相关方面的专家进行审查。 专家人数一般不少于15人，起草人所在单位成员应当回避。参加投票专家2/3以上赞成且反对意见不超过1/4的，方为技术审查通过。"},{"i":18,"n":"第十八条","txt":"行业标准送审稿通过技术审查的，标准起草工作组应当根据审查结论进行完善，形成行业标准报批稿和编制说明等报批材料；未通过技术审查的，标准起草工作组应当根据审查结论修改后，再次报送标准化技术组织进行技术审查。 行业标准涉及专利问题的，根据国家有关规定执行。报批材料应当就行业标准是否涉及专利以及相应处理意见作出说明。"},{"i":19,"n":"第十九条","txt":"标准化技术组织应当将行业标准报批材料报送对应初审机构，经初审机构初审后报送工业和信息化部；没有对应初审机构的，直接报送工业和信息化部。"},{"i":20,"n":"第二十条","txt":"工业和信息化部对行业标准报批材料进行审查，审查通过后向社会公开征求意见。"},{"i":21,"n":"第二十一条","txt":"工业和信息化部对社会公众意见进行汇总、协调和处理，对没有不同意见或者相关意见已处理完毕的行业标准报批稿予以批准，编号并公告发布。"},{"i":22,"n":"第二十二条","txt":"工业和信息化部依法组织行业标准的出版和备案，推动行业标准文本向社会免费公开。"},{"i":23,"n":"第二十三条","txt":"工业和信息化部根据经济社会发展和技术进步需要，制定并公布行业标准复审计划。"},{"i":24,"n":"第二十四条","txt":"标准化技术组织应当根据复审计划对行业标准进行复审，提出复审结论建议，形成复审材料报送对应初审机构，经初审机构初审后报送工业和信息化部；没有对应初审机构的，直接报送工业和信息化部。 行业标准复审结论建议分为继续有效、修订和废止三种。复审结论建议为废止的，应当对废止的理由重点说明。"},{"i":25,"n":"第二十五条","txt":"工业和信息化部对行业标准复审材料进行审查，审查通过后向社会公开征求意见。 工业和信息化部对社会公众意见进行汇总、协调和处理。没有不同意见或者相关意见已处理完毕的，由工业和信息化部公告发布复审结论。"},{"i":26,"n":"第二十六条","txt":"复审结论为继续有效的行业标准再次出版时，应当在封面上标明复审信息。 对复审结论为修订的行业标准，相关标准化技术组织应当及时组织修订。进行少量修改能够符合当前科技水平、适应产业发展需求、满足行业管理需要的，可采用修改单方式修改。"},{"i":27,"n":"第二十七条","txt":"本办法第十条、第十四条第一款、第二十条、第二十五条第一款规定的向社会公开征求意见的期限，一般不少于30日。"},{"i":28,"n":"第二十八条","txt":"本办法规定的材料式样和内容，由工业和信息化部统一公布和调整。"},{"i":29,"n":"第二十九条","txt":"本办法自2020年10月1日起施行。"}],"jianliweixingtongxinwangheshezhishiyongdiqiuzhangu54b80c":[{"i":1,"n":"第一条","txt":"为了规范建立卫星通信网和设置使用地球站的行为，避免和减少卫星网络之间、地球站与共用频段的其他无线电台之间的相互干扰，促进卫星通信事业健康发展，根据《中华人民共和国无线电管理条例》和相关行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内建立卫星通信网和设置使用地球站，适用本规定。 本规定所称的卫星通信网，是指利用卫星空间电台进行通信的地球站组成的通信网。 本规定所称的地球站，是指设置在地球表面或者地球大气层主要部分以内的、与空间电台通信或者通过空间电台与同类电台进行通信的电台。"},{"i":3,"n":"第三条","txt":"国家对建立卫星通信网实行许可制度。 建立卫星通信网的，应当经中华人民共和国工业和信息化部（以下称工业和信息化部）批准；未经批准，任何单位或者个人不得建立卫星通信网。"},{"i":4,"n":"第四条","txt":"设置使用地球站的，应当按照本规定办理审批手续，取得工业和信息化部或者省、自治区、直辖市无线电管理机构颁发的无线电台执照。 设置使用单收地球站，不需要无线电管理机构对其信息接收提供电磁环境保护的，可以不按本规定办理审批手续；要求无线电管理机构保护其信息接收免受有害无线电干扰的，应当按照本规定办理审批手续并取得无线电台执照。"},{"i":5,"n":"第五条","txt":"建立卫星通信网的，应当具备下列条件： （一）具有法人资格。 （二）拟使用的国内空间电台经工业和信息化部批准，并取得无线电台执照。 （三）拟使用的国外空间电台已完成与我国相关卫星网络空间电台和地面电台的频率协调，其技术特性符合双方主管部门之间达成的协议的要求。 （四）无线电频率的使用符合国家无线电频率划分、规划和有关管理规定。 （五）有合理可行的技术方案。 （六）有与卫星通信网建设、运营相适应的资金和专业人员。 （七）有可利用的、由合法经营者提供的卫星频率资源。 （八）法律、行政法规规定的开展有关业务应当具备的其他条件。 建立涉及电信业务经营的卫星通信网的，还应当持有相应的电信业务经营许可证。"},{"i":6,"n":"第六条","txt":"建立卫星通信网的，应当符合国家通信网建设的统筹规划，遵守国家建设管理规定。"},{"i":7,"n":"第七条","txt":"申请建立卫星通信网的，应当向工业和信息化部提交书面申请和下列材料： （一）法人资格证明。 （二）申请单位基本情况说明。 （三）包含本规定附录所列基本资料的技术方案。 （四）可用资金证明材料。 （五）可使用相关卫星频率资源的证明材料。 （六）国家规定的开展有关业务应当提交的其他材料。 申请建立涉及电信业务经营的卫星通信网的，还应当提交相应的电信业务经营许可证复印件。"},{"i":8,"n":"第八条","txt":"申请材料齐全、符合法定形式的，工业和信息化部应当受理，并向申请人出具书面受理通知；申请材料不齐全或者不符合法定形式的，工业和信息化部应当当场或者在 5 个工作日内一次告知申请人需要补正的全部内容；依法不予受理的，应当书面通知申请人。"},{"i":9,"n":"第九条","txt":"工业和信息化部应自受理申请之日起 20 个工作日内作出审批决定。经审查合格的，出具批准建立卫星通信网证明，并书面通知网内地球站所在地的省、自治区、直辖市无线电管理机构。经审查不合格的，书面通知申请人不予批准并说明理由。"},{"i":10,"n":"第十条","txt":"工业和信息化部批准建立卫星通信网时，应当确定其频率使用期限，该期限最长不超过 10 年。频率使用期限届满需要继续使用的，应当在期限届满 30 日前向工业和信息化部提出书面申请，由工业和信息化部在期限届满前作出是否准予继续使用的决定，并书面通知申请人。"},{"i":11,"n":"第十一条","txt":"获准建立卫星通信网的，应当自批准之日起一年内将该卫星通信网投入使用。 不能在前款规定的期限内启用的，应当在该期限届满 30 日前书面告知工业和信息化部，说明理由和启用日期。 终止运行卫星通信网的，应当提前 30 日向工业和信息化部申请办理注销手续。 获准建立卫星通信网的法人或者其他组织依法终止的，工业和信息化部应当注销对其建立卫星通信网的批准，并书面通知网内地球站所在地的省、自治区、直辖市无线电管理机构。"},{"i":12,"n":"第十二条","txt":"需要变更卫星通信网使用的卫星、频率、极化、传输带宽或者通信覆盖范围的，应当提前 30 日向工业和信息化部提出书面申请，并取得批准。 未经批准，不得改变卫星通信网使用的卫星、频率、极化、传输带宽或者通信覆盖范围。 获准建立卫星通信网的单位变更名称、法定代表人或者注册住所的，应当自变更发生之日起 30 日内向工业和信息化部备案。"},{"i":13,"n":"第十三条","txt":"获准建立卫星通信网的单位与卫星转发器经营者签署的转发器租赁协议，以及涉及租赁卫星、频率、极化、带宽和有效期变更的补充修改协议，应当自签署之日起 30 日内向工业和信息化部备案。"},{"i":14,"n":"第十四条","txt":"获准建立卫星通信网的单位设置网内地球站，应当按照本规定办理地球站设置审批手续并领取无线电台执照；由用户设置网内地球站的，获准建立卫星通信网的单位应当协助用户办理地球站设置审批手续。 获准建立卫星通信网的单位不得向未办理地球站设置审批手续的用户提供卫星信道，但是根据本规定第四条第二款的规定可以不办理审批手续的单收地球站除外。"},{"i":15,"n":"第十五条","txt":"获准建立卫星通信网的单位应当在每年一月三十一日前向工业和信息化部书面报送上年度卫星通信网建设和运行的材料，包括： （一）开通业务的城市或地区、业务种类。 （二）卫星频率资源使用情况，包括空间电台的名称和轨道经度、实际使用带宽、上下行频率范围和极化。 （三）网内用户名单、双向和发射地球站数量、单收地球站数量。 （四）已领取无线电台执照的地球站数量。 （五）工业和信息化部要求报送的其他材料。 上述材料应当同时送地球站所在地的省、自治区、直辖市无线电管理机构备案。"},{"i":16,"n":"第十六条","txt":"获准建立卫星通信网的单位应当接受无线电管理机构的监督检查，配合无线电管理机构对网内地球站进行管理。"},{"i":17,"n":"第十七条","txt":"设置使用下列地球站，应当经工业和信息化部审查批准： （一）中央国家机关及其在京直属单位在北京地区设置使用的地球站。 （二）与国外或者港澳台地区通信的地球站。 （三）涉及与境外电台协调的地球站。 （四）各类空间无线电通信业务的馈线链路地球站、关口站或者测控站。 设置使用前款规定之外的地球站，由地球站所在地的省、自治区、直辖市无线电管理机构审查批准。 在北京以外的省、自治区、直辖市辖区内设置使用第一款第（二）项、第（三）项、第（四）项所列地球站的，工业和信息化部委托省、自治区、直辖市无线电管理机构负责对站址和电磁兼容情况进行初步审查，报工业和信息化部批准。"},{"i":18,"n":"第十八条","txt":"设置国际通信地球站的，应当按照有关规定向工业和信息化部申请办理国际通信出入口审批手续。"},{"i":19,"n":"第十九条","txt":"地球站的技术特性、站址选择应当符合国家规定的标准和有关规定。 在城市市区的限制区域内设置使用的发射地球站，其天线直径不应超过 4.5 米，实际发射功率不应超过 20 瓦。 设置地球站所使用的发射设备，应当通过国家无线电发射设备型号核准。"},{"i":20,"n":"第二十条","txt":"申请设置使用属于某个卫星通信网的地球站的，应当按照本规定第十七条的规定，向工业和信息化部或者地球站所在地的省、自治区、直辖市无线电管理机构提交书面申请和下列材料： （一）设置无线电台（站）申请表。 （二）地球站技术资料申报表。 （三）地球站站址电磁环境 测试 报告。 设置天线直径不超过 4.5 米的地球站，站址周围视距传播范围内不存在其他同频段无线电台的，可以不提交地球站站址电磁环境 测试 报告。"},{"i":21,"n":"第二十一条","txt":"申请设置使用不属于某个卫星通信网的地球站的，除本规定第二十条所列申请材料外，还应当提交下列材料： （一）法人资格证明。 （二）卫星传输链路计算材料。 （三）可使用相关卫星频率资源的证明材料。 （四）国家规定的开展有关业务所需提供的其他材料。 申请设置涉及电信业务经营的地球站的，还应当提交相应的电信业务经营许可证复印件。"},{"i":22,"n":"第二十二条","txt":"申请材料齐全、符合法定形式的，工业和信息化部或者省、自治区、直辖市无线电管理机构应当受理，并向申请人出具书面受理通知；申请材料不齐全或者不符合法定形式的，应当当场或者在 5 个工作日内一次告知申请人需要补正的全部内容；依法不予受理的，应当书面通知申请人。"},{"i":23,"n":"第二十三条","txt":"设置使用属于某个卫星通信网的地球站，应当符合下列条件： （一）地球站所属卫星通信网已获得批准。 （二）所使用的空间电台、频率和极化与所属卫星通信网获得的批准文件一致。 （三）地球站的技术特性、站址选择符合本规定的相关要求。 （四）地球站与周围已建或者已受理申请的同频段其他无线电台之间不会相互产生有害干扰。"},{"i":24,"n":"第二十四条","txt":"设置使用不属于某个卫星通信网的地球站，除应当符合本规定第二十三条第（三）项、第（四）项规定的条件外，还应当符合下列条件： （一）拟使用的国内空间电台经工业和信息化部批准，并取得空间电台执照。 （二）拟使用的国外空间电台已完成与我国相关卫星网络空间电台和地面电台的频率协调，其技术特性符合双方主管部门之间达成的协议的要求。 （三）无线电频率的使用符合国家无线电频率划分、规划和有关管理规定。 （四）拟使用的卫星频率资源由合法经营者提供。 （五）法律、行政法规规定的开展有关业务应当具备的其他条件。"},{"i":25,"n":"第二十五条","txt":"除本规定第十七条第三款所列的申请外，工业和信息化部或者省、自治区、直辖市无线电管理机构应当自受理申请之日起 20 个工作日内作出审批决定。经审查合格的，书面批准申请人设置使用地球站；经审查不合格的，书面通知申请人不予批准并说明理由。 无线电管理机构在审查期间，需要邀请专家进行干扰分析、测试验证的，所需时间不计算在上述期限内，但无线电管理机构应当将所需时间书面告知申请人。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市无线电管理机构根据本规定第十七条第三款受理设置使用地球站申请的，应当自受理申请之日起 15 个工作日内完成初步审查，并将初审意见和全部申请材料报送工业和信息化部。 工业和信息化部应当自省、自治区、直辖市无线电管理机构受理申请之日起 20 个工作日内，作出批准或者不予批准的书面决定。"},{"i":27,"n":"第二十七条","txt":"工业和信息化部或者省、自治区、直辖市无线电管理机构批准申请人设置使用不属于某个卫星通信网的地球站的，应当确定其频率使用期限，该期限最长不超过 10 年。频率使用期限届满需继续使用的，应当在该期限届满 30 日前向原审批机构提出书面申请，由原审批机构作出是否准予继续使用的决定，并书面通知申请人。"},{"i":28,"n":"第二十八条","txt":"拟建地球站与已建或者已受理申请的同频段其他无线电台之间将产生有害干扰的，工业和信息化部或者省、自治区、直辖市无线电管理机构应当书面通知申请人不予批准，并告知将受其干扰影响者的情况。 申请人可以与将受其干扰影响者直接协商，寻求解决干扰问题的可行方案；或者提请工业和信息化部或者省、自治区、直辖市无线电管理机构组织技术专家和有关单位进行论证和协调。 在完成干扰协调后，申请人可以重新向工业和信息化部或者省、自治区、直辖市无线电管理机构提出设置使用该地球站的申请。"},{"i":29,"n":"第二十九条","txt":"在沿海和与其他国家或者地区相邻的省、自治区、直辖市辖区内设置使用与其他无线电业务共用频段的大、中型地球站，并且该地球站的协调区覆盖其他国家或者地区的，受理申请的省、自治区、直辖市无线电管理机构应当在实质审查合格后，将有关情况书面告知申请人，并按照国际电信联盟《无线电规则》的有关规定，向工业和信息化部报送有关资料和审查意见。 工业和信息化部应当按照《无线电规则》的有关规定或者双边协议，与相关国家或者地区进行协调，协调时间为 4 至 6个月。 在完成有关协调后，工业和信息化部应当作出予以批准或者不予批准的决定，书面通知申请人和受理申请的省、自治区、直辖市无线电管理机构。"},{"i":30,"n":"第三十条","txt":"申请人应当自收到无线电管理机构批准设置使用地球站的文件之日起 15 日内，到工业和信息化部或者省、自治区、直辖市无线电管理机构办理设置使用无线电台手续，领取无线电台执照。"},{"i":31,"n":"第三十一条","txt":"地球站应当按照核定的项目进行工作。变更地球站站址、频率、极化、发射功率、天线特性或所使用的卫星的，应当提前 30 日向原审批机构提出书面申请。 未经批准，不得改变地球站的站址、频率、极化、发射特性或所使用的卫星。"},{"i":32,"n":"第三十二条","txt":"停止使用地球站的，应当在停止使用后 30 日内向原审批机构申请办理注销手续，交回无线电台执照，并采取拆除、封存或者销毁措施保证已停止使用的地球站终止发射信号。 未经批准，任何单位和个人不得重新启用已办理注销手续的地球站。"},{"i":33,"n":"第三十三条","txt":"地球站的无线电台执照持照者应当按规定在指定期限内缴纳年度频率占用费，接受无线电管理机构对其无线电台执照的核验。"},{"i":34,"n":"第三十四条","txt":"临时设置使用地球站的，应当根据本规定第十七条的规定，在启用日期 15 日前，向工业和信息化部或者省、自治区、直辖市无线电管理机构提交书面申请和相关申请材料。经审查批准后，办理临时设站手续。 临时设置使用的地球站，使用期限不超过 6 个月。"},{"i":35,"n":"第三十五条","txt":"违反本规定第三条第二款、第四条第一款、第三十二条第二款规定的，由工业和信息化部或者省、自治区、直辖市无线电管理机构依据职责责令改正，并按照《中华人民共和国无线电管理条例》等行政法规的规定给予处罚。"},{"i":36,"n":"第三十六条","txt":"违反本规定第十二条第二款、第三十一条第二款规定的，由工业和信息化部或者省、自治区、直辖市无线电管理机构责令限期改正；逾期不改的，按照《中华人民共和国无线电管理条例》等行政法规的规定给予处罚。"},{"i":37,"n":"第三十七条","txt":"违反本规定第十四条第二款规定的，由工业和信息化部或者省、自治区、直辖市无线电管理机构依据职责责令限期改正，处 5000 元以上 3 万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"外国领导人访华、各国驻中华人民共和国使领馆和享有外交特权与豁免的国际组织驻中华人民共和国代表机构设置使用地球站，应当通过外交途径向工业和信息化部提出申请。"},{"i":39,"n":"第三十九条","txt":"卫星移动业务涉及的终端地球站的使用管理规定，由工业和信息化部另行制定。"},{"i":40,"n":"第四十条","txt":"本规定自 2009 年 4 月 10 日起 施行 。 2002 年 6 月 21 日公布的《建立卫星通信网和设置使用地球站管理规定》（中华人民共和国信息产业部令第 21 号）同时废止。 附录：卫星通信网技术方案应包含的基本资料 一、网络的一般特性 １、业务需求和功能 网络用途和功能；业务类型和业务量；传输容量。 ２、组网方式 网络结构（含网络拓扑结构图）；通信覆盖范围。 3 、 网络规模 网络规模；实施计划；启用日期。 4 、技术体制 基本信号形式；信源编码方式、复用方式、纠错方式；调制方式；多址联接和分配方式；网络监控系统等。 二、工作频段和卫星空间电台特性 拟使用的上、下行频率范围。 拟使用的卫星空间电台名称、轨道位置。 相关转发器的编号、类别、极化和带宽。 相关发射、接收波束的天线增益等值线图。 卫星接收系统噪声温度。 相关转发器的饱和等效全向辐射功率（ EIRPs ）图或表、接"}],"xinjianchundiandongchengyongcheqiyeguanliguiding":[{"i":1,"n":"第一条","txt":"为促进新能源汽车产业发展，发挥市场主体的作用，支持社会资本和具有技术创新能力的企业参与纯电动乘用车科研生产，根据《中华人民共和国行政许可法》及《政府核准投资项目管理办法》、《汽车产业发展政策》等有关法律、法规和规章，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中国境内投资新建独立法人纯电动乘用车生产企业（以下简称“新建企业”）。"},{"i":3,"n":"第三条","txt":"本规定所称“纯电动乘用车”，包括纯电动和增程式（具备外接充电功能的串联式混合动力）乘用车，分别指国家标准GB/T 19596-2004《电动汽车术语》中第3.1.1.1.1款和第3.1.1.1.2.1款所定义的车辆。“乘用车”包含轿车和其他乘用车，是指整车（含底盘）为自制的、国家标准GB/T 3730.1-2001《汽车和挂车类型的术语和定义》中第2.1.1.1款至第2.1.1.10款所定义的车辆。"},{"i":4,"n":"第四条","txt":"国家发展改革委、工业和信息化部在各自职责范围内负责新建企业投资项目和车辆生产企业及产品准入的监督管理。"},{"i":5,"n":"第五条","txt":"新建企业投资项目应执行《国务院关于发布政府核准的投资项目目录（2014年本）的通知》（国发[2014]53号）和《汽车产业发展政策》有关规定。"},{"i":6,"n":"第六条","txt":"新建企业投资项目的投资总额和生产规模不受《汽车产业发展政策》有关最低要求限制，由投资主体自行决定。 新建企业可生产纯电动乘用车，不能生产任何以内燃机为驱动动力的汽车产品。"},{"i":7,"n":"第七条","txt":"新建企业的投资主体应按照《政府核准投资项目管理办法》有关要求编制投资项目申请报告，并向国家发展改革委提供投资项目申请企业的企业概况、基础能力、试制样车说明及证明材料（见附件一）。"},{"i":8,"n":"第八条","txt":"新建企业的投资主体应具备以下基本条件： （一）在中国境内注册，具备与项目投资相适应的自有资金规模和融资能力。 （二）具有纯电动乘用车产品从概念设计、系统和结构设计到样车研制、试验、定型的完整研发经历。具有专业研发团队和整车正向研发能力，掌握整车控制系统、动力蓄电池系统、整车集成和整车轻量化方面的核心技术以及相应的试验验证能力，拥有纯电动乘用车自主知识产权和已授权的相关发明专利。 （三）具有整车试制能力，具备完整的纯电动乘用车样车试制条件，包括车身及底盘制造、动力蓄电池系统集成、整车装配等主要试制工艺和装备。 （四）自行试制同一型式的纯电动乘用车样车数量不少于15辆。提供的样车经过国家认定的检测机构检验，在符合汽车国家标准和电动汽车相关标准的前提下，在安全性、可靠性、动力性、整车轻量化、经济性等方面达到规定的技术要求（见附件二）。"},{"i":9,"n":"第九条","txt":"新建企业投资项目申请报告应包括以下内容: （一）具备纯电动乘用车整车正向开发能力的研发机构。至少具备整车及动力系统匹配、整车管理系统、车载能源管理系统、车辆轻量化、车辆安全等关键技术的设计开发能力、试验检测能力以及对整车产品运行状态的监控能力。 （二）与生产纲领、产品结构相适应的车身成型、涂装、总装等整车生产工艺和装备，以及动力蓄电池系统集成等关键部件的生产能力和一致性保证能力。 （三）纯电动乘用车产品的销售及售后服务体系。 （四）新建企业要有履行保障消费者权益等社会责任的承诺和措施，并提供担保企业和经公证的担保期不低于5年（以项目建成投产为起始点）的担保合同。"},{"i":10,"n":"第十条","txt":"国家发展改革委应当依据《政府核准投资项目管理办法》有关规定对新建企业投资项目申请进行审查，并征求工业和信息化部的意见。"},{"i":11,"n":"第十一条","txt":"国家发展改革委应当对新建企业投资项目申请组织专家进行评估，由纯电动乘用车行业专家库中的专家组成投资项目评审委员会，对投资项目申请企业提供的附件一和附件二的真实性和符合性进行审查，并在30个工作日内出具评审意见。 纯电动乘用车行业专家库由国家发展改革委会同工业和信息化部负责组建。"},{"i":12,"n":"第十二条","txt":"投资项目完成建设后，新建企业及产品按照工业和信息化部《乘用车生产企业及产品准入管理规则》和《新能源汽车生产企业及产品准入管理规则》的相关要求，通过考核后列入《车辆生产企业及产品公告》，并按单独类别管理。"},{"i":13,"n":"第十三条","txt":"新建企业生产的纯电动乘用车产品应使用该企业拥有所有权的注册商标和品牌，且符合乘用车、电动汽车相关国家标准和行业标准的要求，所采用动力蓄电池单体和系统应当是符合汽车动力蓄电池行业规范条件的企业生产的产品。新建企业须提交对纯电动乘用车电池、电机、电控系统等核心部件的质保承诺，质保承诺的内容应符合国家支持新能源汽车推广应用的相关规定。"},{"i":14,"n":"第十四条","txt":"新建企业列入《车辆生产企业及产品公告》的纯电动乘用车产品有效期为3年，有效期届满前30日可提出延期申请，审查通过可以延长有效期，每次延期不超过3年。"},{"i":15,"n":"第十五条","txt":"新建企业应建立生产一致性管理体系，保证实际生产的产品与列入《车辆生产企业及产品公告》的产品相符。对企业生产未经许可或不符合标准的产品，依照《道路交通安全法》和工业和信息化部《车辆生产企业及产品一致性监督管理办法》有关规定进行处理。"},{"i":16,"n":"第十六条","txt":"工业和信息化部对新建企业承诺履行情况、售后服务保障情况、产品安全性和一致性等方面开展评价，评价结果向社会公开。"},{"i":17,"n":"第十七条","txt":"工业和信息化部对新建企业准入条件保持情况进行抽查，对不能保持生产准入相关条件或已经破产的企业，依法撤销、注销或暂停其《车辆生产企业及产品公告》。暂停期间，企业不得办理更名、迁址等变更手续。"},{"i":18,"n":"第十八条","txt":"新建企业投资项目和准入管理的监管及法律责任，按照国家有关法律法规以及《政府核准投资项目管理办法》等规定执行。"},{"i":19,"n":"第十九条","txt":"本规定由国家发展和改革委员会、工业和信息化部负责解释。"},{"i":20,"n":"第二十条","txt":"本规定自2015年7月10日起施行。"}],"xinnengyuanqicheshengchanqiyejichanpinzhunruguanli27065c":[{"i":1,"n":"第一条","txt":"为了落实发展新能源汽车的国家战略，规范新能源汽车生产活动，保障公民生命财产安全和公共安全，促进新能源汽车产业持续健康发展，根据《中华人民共和国行政许可法》《中华人民共和国道路交通安全法》《国务院对确需保留的行政审批项目设定行政许可的决定》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产新能源汽车的企业（以下简称新能源汽车生产企业），及其生产在境内使用的新能源汽车产品的活动，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称汽车，是指《汽车和挂车类型的术语和定义》国家标准（GB/T3730.1-2001）第2.1款所规定的汽车整车（完整车辆）及底盘（非完整车辆），不包括整车整备质量超过400千克的三轮车辆。 本规定所称新能源汽车，是指采用新型动力系统，完全或者主要依靠新型能源驱动的汽车，包括插电式混合动力（含增程式）汽车、纯电动汽车和燃料电池汽车等。"},{"i":4,"n":"第四条","txt":"工业和信息化部负责实施全国新能源汽车生产企业及产品的准入和监督管理。 省、自治区、直辖市工业和信息化主管部门负责本行政区域内新能源汽车生产企业及产品的日常监督管理，并配合工业和信息化部实施准入管理相关工作。"},{"i":5,"n":"第五条","txt":"申请新能源汽车生产企业准入的，应当符合以下条件： （一）符合国家有关法律、行政法规、规章和汽车产业发展政策及宏观调控政策的要求。 （二）申请人是已取得道路机动车辆生产企业准入的汽车生产企业，或者是已按照国家有关投资管理规定完成投资项目手续的新建汽车生产企业。 汽车生产企业跨产品类别生产新能源汽车的，也应当按照国家有关投资管理规定完成投资项目手续。 （三）具备生产新能源汽车产品所必需的生产能力、产品生产一致性保证能力、售后服务及产品安全保障能力，符合《新能源汽车生产企业准入审查要求》（见附件1，以下简称《准入审查要求》）。 具备工业和信息化部规定条件的大型汽车企业集团，在企业集团统一规划、统一管理、承担相应监管责任的前提下，其下属企业（包括下属子公司及分公司）的准入条件予以简化，适用《企业集团下属企业的准入审查要求》（见附件2）。 （四）符合相同类别的常规汽车生产企业准入管理规则。"},{"i":6,"n":"第六条","txt":"汽车生产企业在已列入《道路机动车辆生产企业及产品公告》（以下简称《公告》）的新能源汽车整车或者底盘基础上改装生产新能源汽车产品，改装未影响到底盘、车载能源系统、驱动系统和控制系统的，不需要申请新能源汽车生产企业准入。"},{"i":7,"n":"第七条","txt":"申请准入的新能源汽车产品，应当符合以下条件： （一）符合国家有关法律、行政法规、规章。 （二）符合《新能源汽车产品专项检验项目及依据标准》（见附件3），以及相同类别的常规汽车产品相关标准。 （三）经国家认定的检测机构（以下简称检测机构）检测合格。 （四）符合工业和信息化部规定的安全技术条件。 工业和信息化部根据新能源汽车产业发展的实际情况和相关标准制修订情况，及时调整《新能源汽车产品专项检验项目及依据标准》的有关内容，并在施行前向社会公布。"},{"i":8,"n":"第八条","txt":"申请新能源汽车生产企业准入的，应当向工业和信息化部提交以下材料： （一）申请新能源汽车生产企业准入审查的文件。 （二）《新能源汽车生产企业准入申请书》（见附件4）及相关证明材料。 （三）新建新能源汽车生产企业的企业法人营业执照复印件，以及根据国家有关投资管理规定办理投资项目手续的文件。中外合资企业还应当提交中外股东持股比例证明。"},{"i":9,"n":"第九条","txt":"申请新能源汽车产品准入的，应当向工业和信息化部提交以下材料： （一）新能源汽车产品主要技术参数表（见附件5）。 （二）检测机构出具的新能源汽车产品检测报告。 （三）其他需要说明的情况。"},{"i":10,"n":"第十条","txt":"工业和信息化部收到准入申请后，对于申请材料不齐全或者不符合法定形式的，应当当场或者在5日内一次性告知申请人需要补正的全部内容。申请材料齐全、符合法定形式的，应当予以受理，并自受理之日起20个工作日内作出批准或者不予批准的决定。20个工作日内不能作出决定的，经工业和信息化部负责人批准，可以延长10个工作日，并应当将延长期限的理由告知申请人。"},{"i":11,"n":"第十一条","txt":"工业和信息化部委托第三方技术服务机构，组织专家对新能源汽车生产企业、新能源汽车产品准入申请进行技术审查，审查方式包括现场审查、资料审查。 工业和信息化部建立新能源汽车领域专家库，从中选取专家组成审查组。 第三方技术服务机构技术审查所需时间不计算在本规定第十条规定的期限内。"},{"i":12,"n":"第十二条","txt":"申请新能源汽车生产企业准入的，如已按照相同类别的常规汽车生产企业准入管理规则通过了审查的，免予审查《准入审查要求》中的相关要求。"},{"i":13,"n":"第十三条","txt":"检测机构应当严格按照工业和信息化部有关规定开展新能源汽车产品检测工作，不得擅自变更检测要求。"},{"i":14,"n":"第十四条","txt":"通过审查的新能源汽车生产企业及产品，由工业和信息化部通过《公告》发布。 不符合本规定所规定的条件、标准的新能源汽车生产企业及产品，工业和信息化部不予列入《公告》。 新能源汽车生产企业应当按照《公告》载明的许可要求生产新能源汽车产品。"},{"i":15,"n":"第十五条","txt":"新能源汽车生产企业应当加强管理、规范使用新能源汽车产品出厂合格证，确保出厂合格证及其信息与实际产品唯一对应、保持一致。"},{"i":16,"n":"第十六条","txt":"新能源汽车生产企业应当建立新能源汽车产品售后服务承诺制度。售后服务承诺应当包括新能源汽车产品质量保证承诺、售后服务项目及内容、备件提供及质量保证期限、售后服务过程中发现问题的反馈、零部件（如电池）回收，出现产品质量、安全、环保等严重问题时的应对措施以及索赔处理等内容，并在本企业网站上向社会发布。"},{"i":17,"n":"第十七条","txt":"新能源汽车生产企业应当建立新能源汽车产品运行安全状态监测平台，按照与新能源汽车产品用户的协议，对已销售的全部新能源汽车产品的运行安全状态进行监测。企业监测平台应当与地方和国家的新能源汽车推广应用监测平台对接。 新能源汽车生产企业及其工作人员应当妥善保管新能源汽车产品运行安全状态信息，不得泄露、篡改、毁损、出售或者非法向他人提供，不得监测与产品运行安全状态无关的信息。"},{"i":18,"n":"第十八条","txt":"新能源汽车生产企业应当在产品全生命周期内，为每一辆新能源汽车产品建立档案，跟踪记录汽车使用、维护、维修情况，实施新能源汽车动力电池溯源信息管理，跟踪记录动力电池回收利用情况。 新能源汽车生产企业应当对新能源汽车产品的技术状况、故障及主要问题等运行情况进行分析、总结，编写年度报告（见附件6）。年度报告应当在新能源汽车产品全生命周期内存档备查。"},{"i":19,"n":"第十九条","txt":"新能源汽车生产企业申请准入的新能源汽车产品类别或者动力系统（包括插电式混合动力、纯电动、燃料电池等）与已列入《公告》的新能源汽车产品不同的，或者增加、变更生产地址的，应当向工业和信息化部提交本规定第八条所列的材料，原则上应当进行现场审查。 取得插电式混合动力汽车或者燃料电池汽车产品准入的新能源汽车生产企业，申请相同类别的纯电动汽车产品准入的，只进行资料审查。"},{"i":20,"n":"第二十条","txt":"新能源汽车生产企业应当持续满足《准入审查要求》和生产一致性等相关规定，确保新能源汽车产品安全保障体系正常运行。"},{"i":21,"n":"第二十一条","txt":"新能源汽车生产企业发现新能源汽车产品存在安全、环保、节能等严重问题的，应当立即停止相关产品的生产、销售，采取措施进行整改，并及时向工业和信息化部和相关省、自治区、直辖市工业和信息化主管部门报告。"},{"i":22,"n":"第二十二条","txt":"工业和信息化部应当对新能源汽车生产企业的《准入审查要求》保持情况、生产一致性情况和监测平台运行情况等进行监督检查，检查方式包括资料审查、实地核查、市场抽样和性能检测等。 省、自治区、直辖市工业和信息化主管部门应当对本行政区域内新能源汽车生产企业的生产情况、监测平台运行情况进行监督检查。发现新能源汽车生产企业有《准入审查要求》所列要求发生重大变化、生产管理存在重大安全隐患、产品不符合安全技术标准，以及违法行为等的，应当及时向工业和信息化部报告。"},{"i":23,"n":"第二十三条","txt":"对于停止生产新能源汽车产品24个月及以上的新能源汽车生产企业，工业和信息化部予以特别公示。 经特别公示的新能源汽车生产企业在恢复生产之前，工业和信息化部应当对其保持《准入审查要求》的情况进行核查。"},{"i":24,"n":"第二十四条","txt":"工业和信息化部建立新能源汽车生产企业信用数据库，将企业违反生产一致性要求、申请材料弄虚作假、行政处罚等情况列入信用数据库。"},{"i":25,"n":"第二十五条","txt":"新能源汽车生产企业不能保持《准入审查要求》，存在公共安全、人身健康、生命财产安全隐患的，工业和信息化部应当责令其停止生产、销售活动，并责令立即改正。"},{"i":26,"n":"第二十六条","txt":"新能源汽车生产企业破产或者自愿终止生产新能源汽车产品的，工业和信息化部应当撤销、注销其相应的新能源汽车生产企业、产品准入。"},{"i":27,"n":"第二十七条","txt":"隐瞒有关情况或者提供虚假材料申请新能源汽车生产企业、新能源汽车产品准入的，工业和信息化部不予受理或者不予准入，并给予警告，申请人在一年内不得再次申请准入。 以欺骗、贿赂等不正当手段取得新能源汽车生产企业、新能源汽车产品准入的，工业和信息化部应当撤销其新能源汽车生产企业、产品准入，申请人在三年内不得再次申请准入。"},{"i":28,"n":"第二十八条","txt":"新能源汽车生产企业擅自生产、销售未列入工业和信息化部《公告》的新能源汽车车型的，工业和信息化部应当依据《中华人民共和国道路交通安全法》有关规定予以处罚。"},{"i":29,"n":"第二十九条","txt":"本规定自2017年7月1日起施行。2009年6月17日工业和信息化部公布的《新能源汽车生产企业及产品准入管理规则》（工产业〔2009〕第44号）同时废止。本规定施行前公布的有关规定与本规定不一致的，以本规定为准。 附件： 1.新能源汽车生产企业准入审查要求 2.企业集团下属企业的准入审查要求 3.新能源汽车产品专项检验项目及依据标准 4.新能源汽车生产企业准入申请书 5.新能源汽车产品主要技术参数表 6.新能源汽车年度报告"}],"wuxiandianfasheshebeiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强无线电发射设备管理，防止和减少无线电干扰，维护空中电波秩序，促进无线电技术应用和产业发展，根据《中华人民共和国无线电管理条例》和相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内研制、生产、进口、销售和维修无线电发射设备，应当遵守本规定。 前款所称无线电发射设备是指为开展各类无线电业务而发射无线电波的设备。"},{"i":3,"n":"第三条","txt":"国家无线电管理机构负责全国无线电发射设备研制、生产、进口、销售和维修活动的监督管理。 省、自治区、直辖市无线电管理机构依照本规定负责本行政区域内无线电发射设备研制、生产、进口、销售和维修活动的监督管理。 国家无线电管理机构和省、自治区、直辖市无线电管理机构统称无线电管理机构。"},{"i":4,"n":"第四条","txt":"研制无线电发射设备使用的无线电频率，应当符合国家无线电频率划分规定。"},{"i":5,"n":"第五条","txt":"生产或者进口在国内销售、使用的无线电发射设备，应当符合产品质量等法律法规、国家标准和国家无线电管理的有关规定。"},{"i":6,"n":"第六条","txt":"生产或者进口在国内销售、使用除微功率短距离无线电发射设备以外的无线电发射设备，应当向国家无线电管理机构申请无线电发射设备型号核准。无线电发射设备型号核准目录由国家无线电管理机构公布。"},{"i":7,"n":"第七条","txt":"申请无线电发射设备型号核准，应当符合下列条件： （一）申请人有相应的生产能力、技术力量、质量保证体系； （二）无线电发射设备的工作频率、功率等技术指标符合国家标准和国家无线电管理的有关规定； （三）法律、行政法规规定的其他条件。"},{"i":8,"n":"第八条","txt":"申请无线电发射设备型号核准，应当向国家无线电管理机构提交下列申请材料，并对申请材料的真实性、完整性负责： （一）经申请人法定代表人或者其委托人签署的型号核准申请表和承诺书； （二）加盖申请人签章的营业执照副本、事业单位法人证书复印件或者组织机构证明材料（后者仅限境外申请人）； （三）与无线电发射设备生产相适应的生产能力、技术力量和质量保证体系说明材料； （四）无线电发射设备使用说明（含电子显示的说明）、技术手册、彩色照片，以及与无线电发射和接收功能相关的电路图、电路原理方框图、关键射频元器件清单； （五）法律、行政法规规定的其他材料。"},{"i":9,"n":"第九条","txt":"国家无线电管理机构应当依法对申请型号核准的无线电发射设备是否符合本规定第七条规定的条件进行审查，并自受理申请之日起15个工作日内作出核准或者不予核准的决定。予以核准的，核发纸质或者电子型号核准证；不予核准的，书面通知申请人并说明理由。电子型号核准证与纸质型号核准证具有同等效力。 型号核准证应当载明申请人名称、设备名称、设备型号、核定的主要技术指标、型号核准代码、发证机关、发证日期、型号核准有效期等内容。 型号核准证的有效期不短于2年，不超过5年，但因无线电频率规划调整以及频率使用许可期限另有要求的除外。"},{"i":10,"n":"第十条","txt":"国家无线电管理机构可以委托省、自治区、直辖市无线电管理机构对申请型号核准的无线电发射设备是否符合本规定第七条第二项规定的条件进行技术检测。 受委托的省、自治区、直辖市无线电管理机构应当按照政府购买服务有关法律法规的要求确定检测机构，并在国家无线电管理机构规定的时限内组织开展技术检测，提交检测报告。 无线电管理机构组织开展无线电发射设备技术检测，不得收取任何费用，所需时间不计算在本规定第九条第一款规定的期限内，但应当将所需时间书面告知申请人。 组织开展无线电发射设备技术检测所需时间包括样品寄递、运输、调试、测试时间。 因测试样品质量或者体积过大等原因不便寄递的，申请人应当与检测机构协商进行现场测试。"},{"i":11,"n":"第十一条","txt":"条件完备、具有良好质量管理水平和信用的申请人，可以在作出相关承诺的前提下，免于提交本规定第八条第三项规定的材料；除网络安全等特殊检测项目外，可以采用申请人检测报告替代本规定第十条规定的检测报告。具体实施办法另行制定。"},{"i":12,"n":"第十二条","txt":"型号核准证有效期届满需要延续的，应当在有效期届满30日前向国家无线电管理机构申请延续。 国家无线电管理机构依照本规定进行审查，在有效期届满前作出是否准予延续的决定。准予延续的，收回原型号核准证并换发新型号核准证，型号核准代码保持不变；不予延续的，书面告知申请人并说明理由。 型号核准证每次延续的有效期不超过5年。"},{"i":13,"n":"第十三条","txt":"型号核准证需要变更的，应当依据有关规定向国家无线电管理机构提出变更申请。符合有关规定的，国家无线电管理机构应当依法办理变更手续。"},{"i":14,"n":"第十四条","txt":"取得无线电发射设备型号核准的，应当保证在型号核准证有效期内无线电发射设备生产能力、技术力量、质量水平不降低，无线电发射设备技术参数与型号核准证核定的指标相一致。"},{"i":15,"n":"第十五条","txt":"型号核准代码应当在无线电发射设备上标注或者采用电子形式显示。确因设备尺寸过小等原因无法标注或者显示型号核准代码的，应当在设备的独立外包装或者使用说明中标注。 国家无线电管理机构制定发布无线电发射设备型号核准代码编码规则。申请人可以按照编码规则自主编制型号核准代码，但在无线电发射设备取得型号核准前不得在国内销售、使用。"},{"i":16,"n":"第十六条","txt":"国家无线电管理机构定期向社会公布核发的无线电发射设备型号核准信息，接受社会监督。"},{"i":17,"n":"第十七条","txt":"无线电发射设备型号核准证或者型号核准代码不得涂改、倒卖、出租、出借或者以其他形式非法转让。"},{"i":18,"n":"第十八条","txt":"进口应当取得型号核准的无线电发射设备，货物收货人、携带无线电发射设备入境的人员、寄递无线电发射设备的收件人应当依法向海关申报，凭型号核准证向海关办理通关手续。"},{"i":19,"n":"第十九条","txt":"携带、寄递或者以其他方式运输应当取得型号核准而未取得型号核准的无线电发射设备临时进关的，应当按照下列途径报经无线电管理机构批准，凭临时进关批准文件向海关办理通关手续： （一）用于体育比赛、科学实验、产品研发测试等活动的，向进关所在地的省、自治区、直辖市无线电管理机构提出申请； （二）用于办理型号核准的，向国家无线电管理机构提出申请。"},{"i":20,"n":"第二十条","txt":"申请临时进关批准文件应当符合以下条件： （一）申请临时进关的无线电发射设备具有明确具体、合法的用途； （二）无线电发射设备的工作频率、功率等技术指标符合国家标准和国家无线电管理的有关规定； （三）法律、行政法规规定的其他条件。"},{"i":21,"n":"第二十一条","txt":"申请临时进关批准文件，应当向无线电管理机构提交下列申请材料，并对申请材料的真实性、完整性负责： （一）经申请人法定代表人或者委托人签署的无线电发射设备进关核准申请表； （二）加盖申请人签章的营业执照副本、事业单位法人证书复印件或者组织机构证明材料（后者仅限境外申请人）； （三）临时进关合同或者设备运单； （四）无线电发射设备在有效期届满前复运出境的承诺书； （五）法律、行政法规规定的其他材料。"},{"i":22,"n":"第二十二条","txt":"无线电管理机构应当自受理临时进关申请之日起20个工作日内作出批准或者不予批准的决定。予以批准的，签发批准文件；不予批准的，应当书面通知申请人并说明理由。 临时进关批准文件有效期不超过6个月。有效期届满的，应当按照规定及时复运出境。"},{"i":23,"n":"第二十三条","txt":"销售应当取得型号核准的无线电发射设备的，应当向省、自治区、直辖市无线电管理机构办理销售备案。备案信息应当真实、有效并及时更新。"},{"i":24,"n":"第二十四条","txt":"维修应当取得型号核准的无线电发射设备的，不得改变型号核准证核定的技术指标。"},{"i":25,"n":"第二十五条","txt":"生产或者进口在国内销售、使用的微功率短距离无线电发射设备，应当符合国家无线电管理机构的有关规定和技术要求，在微功率短距离无线电发射设备及使用说明中标注微功率短距离无线电发射设备的专用标识。专用标识标注方式和样式另行制定。 微功率短距离无线电发射设备使用说明中应当注明“使用微功率短距离无线电发射设备应当符合国家无线电管理有关规定”字样。"},{"i":26,"n":"第二十六条","txt":"研制、生产、销售和维修大功率无线电发射设备，应当采取加装滤波器、安装屏蔽设备以及更换电子元器件等措施有效抑制电波发射，不得对依法设置、使用的无线电台（站）产生有害干扰。产生有害干扰的，应当立即停止电波发射。进行实效发射试验的，应当依法办理临时设置、使用无线电台（站）手续。"},{"i":27,"n":"第二十七条","txt":"无线电管理机构应当加强对研制、生产、进口、销售和维修无线电发射设备的监督检查，建立和完善随机抽查监督管理制度，随机选派检查人员，随机抽取被检查对象，及时向社会公布抽查事项目录、抽查情况和查处结果。 被检查对象应当配合无线电管理机构的监督检查，如实提供有关情况及材料。"},{"i":28,"n":"第二十八条","txt":"无线电管理机构及其工作人员应当对在履行职责中知悉的商业秘密和个人隐私信息严格保密，不得泄露或者非法向他人提供。"},{"i":29,"n":"第二十九条","txt":"研制、生产、进口、销售、维修无线电发射设备违反本规定的，由无线电管理机构责令改正，依照《中华人民共和国行政许可法》《中华人民共和国无线电管理条例》等法律、行政法规予以处罚。 生产、销售无线电发射设备违反产品质量管理法律法规的，由市场监督管理部门依法处罚；进口、携带、寄递或者以其他方式运输无线电发射设备入境，违反海关监管法律法规的，由海关依法处罚。 构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"无线电管理机构及其工作人员不依照《中华人民共和国无线电管理条例》和本规定履行职责的，对负有责任的领导人员和其他直接责任人员依法给予处分。"},{"i":31,"n":"第三十一条","txt":"使用无线电发射设备，应当遵守无线电台（站）管理的相关规定，国家另有规定的，从其规定。"},{"i":32,"n":"第三十二条","txt":"本规定自2023年7月1日起施行。"}],"wuxiandiantaizhizhaoguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强无线电台（站）管理，保护合法无线电台（站）正常工作，根据《中华人民共和国无线电管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"无线电台执照是合法设置、使用无线电台（站）的法定凭证。使用各类无线电台（站），包括在机车、船舶和航空器上设置、使用制式电台，应当持有无线电台执照，但中华人民共和国工业和信息化部（以下称工业和信息化部）规定不需要取得无线电台执照的除外。 无线电台（站）是指开展无线电业务所必需的一个或者多个发射机、接收机、或者发射机和接收机的组合（包括附属设备）。"},{"i":3,"n":"第三条","txt":"无线电台执照分为《中华人民共和国无线电台执照》、《中华人民共和国船舶电台执照》和《中华人民共和国航空器电台执照》。 无线电台执照由工业和信息化部统一印制。"},{"i":4,"n":"第四条","txt":"无线电台执照由工业和信息化部或者省、自治区、直辖市无线电管理机构根据《中华人民共和国无线电管理条例》规定的无线电台（站）审批权限和各类无线电台（站）的管理规定核发，或者由工业和信息化部委托的国务院有关部门核发。"},{"i":5,"n":"第五条","txt":"无线电台执照的有效期不超过三年，临时无线电台（站）执照的有效期不超过半年。"},{"i":6,"n":"第六条","txt":"设置、使用无线电台（站）的单位和个人，应当向无线电管理机构提交书面申请和必要的技术资料，经审查批准并按照国家有关规定缴纳频率占用费后领取无线电台执照。"},{"i":7,"n":"第七条","txt":"持照者应当妥善保管无线电台执照。遗失无线电台执照的，应当追查下落，并立即报告原执照核发机构。"},{"i":8,"n":"第八条","txt":"变更无线电台执照中所核定的内容的，应当向原执照核发机构提交申请，经审查批准后重新核发无线电台执照。"},{"i":9,"n":"第九条","txt":"无线电台执照有效期届满后需要继续使用无线电台（站）的，应当在有效期届满一个月前向原执照核发机构申请办理无线电台执照延续手续。 无线电台执照有效期届满未延续的，原执照核发机构应当注销无线电台执照，持照者应当立即停止使用其无线电台（站）。"},{"i":10,"n":"第十条","txt":"停用或者撤销无线电台（站）的，持照者应当自停用或者撤销之日起一个月内向原执照核发机构交回无线电台执照，并报告设备处理情况。"},{"i":11,"n":"第十一条","txt":"严禁仿制、伪造或者出借无线电台执照。"},{"i":12,"n":"第十二条","txt":"各级无线电管理机构每年应当对无线电台执照进行核验，对持照者执行本规定第七条、第八条、第九条、第十条和缴纳频率占用费的情况进行检查，并记录核验和缴费情况。 各级无线电管理机构 对 持照者 实行监督检查时，应当记录监督检查的情况和处理结果，由监督检查人员签字后归档。公众有权查阅监督检查记录。 各级无线电管理机构 对 持照者 实行监督检查，不得妨碍 持照者 正常的生产经营活动，不得收取任何费用。"},{"i":13,"n":"第十三条","txt":"违反本规定的，由工业和信息化部或者省、自治区、直辖市无线电管理机构依据《中华人民共和国无线电管理条例》等有关规定处罚。"},{"i":14,"n":"第十四条","txt":"军事用途无线电台（站）执照管理办法，由中国人民解放军无线电管理机构另行制定。"},{"i":15,"n":"第十五条","txt":"本规定自2009年4月10日起施行。本规定施行前颁布的有关规定与本规定不一致的，按照本规定执行。"}],"wuxiandianpinlvshiyongxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强无线电频率使用许可管理，规范无线电频率使用行为，有效利用无线电频谱资源，根据《中华人民共和国无线电管理条例》及其他法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"向国家无线电管理机构和省、自治区、直辖市无线电管理机构（以下统称无线电管理机构）申请无线电频率使用许可，以及无线电管理机构实施无线电频率使用许可和监督管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"无线电频谱资源属于国家所有，实行有偿使用。 使用无线电频率应当按照国家有关规定缴纳无线电频率占用费。"},{"i":4,"n":"第四条","txt":"使用无线电频率应当取得许可，但《中华人民共和国无线电管理条例》第十四条第一项至第三项所列的频率除外。"},{"i":5,"n":"第五条","txt":"取得无线电频率使用许可，应当符合下列条件： （一）所申请的无线电频率符合无线电频率划分和使用规定，有明确具体的用途； （二）使用无线电频率的技术方案可行； （三）有相应的专业技术人员； （四）对依法使用的其他无线电频率不会产生有害干扰； （五）法律、行政法规规定的其他条件。 使用卫星无线电频率，还应当符合空间无线电业务管理相关规定。"},{"i":6,"n":"第六条","txt":"申请办理无线电频率使用许可，应当向无线电管理机构提交下列材料： （一）使用无线电频率的书面申请及申请人身份证明材料； （二）申请人基本情况，包括开展相关无线电业务的专业技术人员、技能和管理措施等； （三）拟开展的无线电业务的情况说明，包括功能、用途、通信范围（距离）、服务对象和预测规模以及建设计划等； （四）技术可行性研究报告，包括拟采用的通信技术体制和标准、系统配置情况、拟使用系统（设备）的频率特性、频率选用（组网）方案和使用率、主要使用区域的电波传播环境、干扰保护和控制措施，以及运行维护措施等； （五）依法使用无线电频率的承诺书； （六）法律、行政法规规定的其他材料。 无线电频率拟用于开展射电天文业务的，还应当提供具体的使用地点和有害干扰保护要求；用于开展空间无线电业务的，还应当提供拟使用的空间无线电台、卫星轨道位置、卫星覆盖范围、实际传输链路设计方案和计算等信息，以及关于可用的相"},{"i":7,"n":"第七条","txt":"国家无线电管理机构和省、自治区、直辖市无线电管理机构应当依据《中华人民共和国无线电管理条例》第十八条第一款规定的审批权限，实施无线电频率使用许可。"},{"i":8,"n":"第八条","txt":"无线电管理机构应当对申请无线电频率使用许可的材料进行审查。申请材料齐全、符合法定形式的，应当予以受理，并向申请人出具受理申请通知书。申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次性告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理。"},{"i":9,"n":"第九条","txt":"无线电管理机构应当自受理申请之日起20个工作日内审查完毕，依照本办法第五条规定的条件，并综合考虑国家安全需要和可用频率的情况，作出准予许可或者不予许可的决定。20个工作日内不能作出决定的，经无线电管理机构负责人批准可以延长10个工作日，并应当将延长期限的理由告知申请人。 无线电管理机构作出准予许可的决定的，应当自作出决定之日起10个工作日内向申请人颁发无线电频率使用许可证。不予许可的，应当出具不予许可决定书，向申请人说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 无线电管理机构采取招标、拍卖的方式实施无线电频率使用许可的，应当遵守有关法律、行政法规规定的程序。"},{"i":10,"n":"第十条","txt":"无线电管理机构对无线电频率使用许可申请进行审查时，可以组织专家评审、依法举行听证。专家评审和听证所需时间不计算在本办法第九条规定的许可期限内，但无线电管理机构应当将所需时间书面告知申请人。 实施无线电频率使用许可需要完成有关国内、国际协调或者履行国际规则规定程序的，进行协调以及履行程序的时间不计算在本办法第九条规定的许可期限内。"},{"i":11,"n":"第十一条","txt":"无线电管理机构作出无线电频率使用许可的决定时，应当明确无线电频率使用许可的期限。 无线电频率使用许可的期限不得超过10年。临时使用无线电频率的，无线电频率使用许可的期限不超过12个月。"},{"i":12,"n":"第十二条","txt":"无线电频率使用许可证由正文、特别规定事项、许可证使用须知、无线电频率使用人的权利义务等内容组成。 无线电频率使用许可证正文应当载明无线电频率使用人、使用频率、使用地域、业务用途、使用期限、使用率要求、许可证编号、发证机关及签发时间等事项。 无线电频率使用许可证的具体内容由国家无线电管理机构制定并公布。国家无线电管理机构可以根据实际情况调整无线电频率使用许可证的内容。 对于临时使用无线电频率、试验使用无线电频率和国家无线电管理机构确定的其他情形，无线电管理机构可以颁发无线电频率使用批准文件，并载明本条第二款规定的事项。无线电频率使用批准文件与无线电频率使用许可证具有同等效力。"},{"i":13,"n":"第十三条","txt":"无线电频率使用许可证由无线电管理机构负责人签发，加盖发证机关印章。"},{"i":14,"n":"第十四条","txt":"无线电频率使用许可证样式由国家无线电管理机构统一规定。"},{"i":15,"n":"第十五条","txt":"使用无线电频率，应当遵守国家无线电管理的有关规定和无线电频率使用许可证的要求，接受、配合无线电管理机构的监督管理。"},{"i":16,"n":"第十六条","txt":"无线电频率使用许可证应当妥善保存。任何组织或者个人不得伪造、涂改、冒用无线电频率使用许可证。"},{"i":17,"n":"第十七条","txt":"国家根据维护国家安全、保障国家重大任务、处置重大突发事件等需要依法实施无线电管制的，管制区域内的无线电频率使用人应当遵守有关管制规定。"},{"i":18,"n":"第十八条","txt":"无线电频率使用人不得擅自转让无线电频率使用权，不得擅自扩大使用范围或者改变用途。 需要转让无线电频率使用权的，受让人应当符合本办法第五条规定的条件，提交双方转让协议和本办法第六条规定的材料，依照本办法第九条规定的程序报请无线电管理机构批准。"},{"i":19,"n":"第十九条","txt":"依法使用的无线电频率受到有害干扰的，可以向无线电管理机构投诉，无线电管理机构应当及时协调处理，并将处理情况告知投诉人。"},{"i":20,"n":"第二十条","txt":"无线电频率使用人拟变更无线电频率使用许可证所载事项的，应当向作出许可决定的无线电管理机构提出申请。符合法定条件的，无线电管理机构应当依法办理变更手续。"},{"i":21,"n":"第二十一条","txt":"无线电频率使用期限届满需要继续使用的，应当在期限届满30个工作日前向作出许可决定的无线电管理机构提出延续申请。无线电管理机构应当依照本办法第五条、第九条的规定进行审查，作出是否准予延续的决定。"},{"i":22,"n":"第二十二条","txt":"无线电管理机构应当对无线电频率使用行为进行监督检查。 无线电管理机构根据需要可以组织开展无线电频率使用评估，对无线电频率使用情况、使用率等进行检查。"},{"i":23,"n":"第二十三条","txt":"无线电频率使用人应当于每年第一季度末前，按照无线电频率使用许可证的要求，向作出许可决定的无线电管理机构报送上一年度的无线电频率使用报告，包括上一年度无线电频率使用情况、执行无线电管理规定的情况等。无线电频率使用人应当对报告的真实性负责。"},{"i":24,"n":"第二十四条","txt":"任何组织或者个人对未经许可擅自使用无线电频率或者违法使用无线电频率的行为，有权向无线电管理机构举报，无线电管理机构应当及时核实、处理。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，作出许可决定的无线电管理机构或者国家无线电管理机构可以撤销无线电频率使用许可： （一）无线电管理机构工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权或者违反法定程序作出准予许可决定的； （三）对不具备申请资格或者不符合法定条件的申请人作出准予许可决定的； （四）除因不可抗力外，取得无线电频率使用许可后超过2年不使用或者使用率达不到无线电频率许可证规定要求的； （五）依法可以撤销无线电频率使用许可的其他情形。 无线电频率使用人以欺骗、贿赂等不正当手段取得无线电频率使用许可的，应当予以撤销。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，无线电管理机构应当依法办理无线电频率使用许可的注销手续： （一）无线电频率使用许可的期限届满未书面申请延续或者未准予延续的； （二）无线电频率使用人在无线电频率使用期限内申请终止使用频率的； （三）无线电频率使用许可被依法撤销、撤回，或者无线电频率使用许可证依法被吊销的； （四）因不可抗力导致无线电频率使用许可事项无法实施的； （五）取得无线电频率使用许可的自然人死亡、丧失行为能力或者法人、其他组织依法终止的； （六）法律、法规规定的其他情形。 无线电管理机构注销无线电频率使用许可的，同时收回无线电频率。"},{"i":27,"n":"第二十七条","txt":"申请人隐瞒有关情况或者提供虚假材料申请无线电频率使用许可的，无线电管理机构不予受理或者不予许可，并给予警告，申请人在一年内不得再次申请该许可。 以欺骗、贿赂等不正当手段取得无线电频率使用许可的，无线电管理机构给予警告，并视情节轻重处五千元以上三万元以下的罚款，申请人在三年内不得再次申请该许可。"},{"i":28,"n":"第二十八条","txt":"未经许可擅自使用无线电频率、擅自转让无线电频率、未按照国家有关规定缴纳无线电频率占用费的，无线电管理机构应当分别依照《中华人民共和国无线电管理条例》第七十条、第七十一条、第七十四条的规定处理。"},{"i":29,"n":"第二十九条","txt":"无线电频率使用人违反无线电频率使用许可证的要求使用频率，或者拒不接受、配合无线电管理机构依法实施的监督管理的，无线电管理机构应当责令改正，给予警告，可以并处五千元以上三万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"伪造、涂改、冒用无线电频率使用许可证的，无线电管理机构应当责令改正，给予警告或者处三万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"无线电频率使用人在无线电频率使用许可的期限内，降低其申请取得无线电频率使用许可时所应当符合的条件的，无线电管理机构应当责令改正；拒不改正的，处三万元以下的罚款并将上述情况向社会公告。"},{"i":32,"n":"第三十二条","txt":"无线电频率使用人对无线电管理机构作出的行政许可或者行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":33,"n":"第三十三条","txt":"无线电管理机构工作人员在实施无线电频率使用许可和监督管理工作中，滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定，构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"无线电频率使用许可的涉外事宜，依照《中华人民共和国无线电管理条例》和其他相关法律、行政法规规定办理。 无线电频率使用人取得的相应使用许可中未确定频率使用期限的，如频率使用时间已超过10年并且需要继续使用，应当自本办法施行之日起6个月内办理延续手续。"},{"i":36,"n":"第三十六条","txt":"本办法自2017年9月1日起施行。本办法施行前颁布的有关规定与本办法不一致的，按照本办法执行。"}],"heshigufusheyingxiangyuejingyingjiguanliguiding":[{"i":1,"n":"第一条","txt":"为规范核事故辐射影响越境时的应急管理工作，保证所需要的应急响应能力与秩序，根据《核电厂核事故应急管理条例》和履行我国加入的有关国际公约义务，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于我国境内发生的对境外造成或者可能造成辐射影响的核事故（以下简称 “ 影响境外的核事故 ” ）的对外通报与信息传递的管理，以及我国受到或者可能受到境外核事故辐射影响时应急响应的管理。"},{"i":3,"n":"第三条","txt":"核事故辐射影响越境应急管理工作贯彻 “ 常备不懈，积极兼容，统一指挥，大力协同，保护公众，保护环境 ”的方针，严格遵守我国加入的有关国际公约（我国政府声明保留的条款除外）。"},{"i":4,"n":"第四条","txt":"我国发生影响境外的核事故时，由国家核事故应急办公室（以下简称国家核应急办）汇总有关事故信息，按照《及早通报核事故公约》的要求，直接或者通过国际原子能机构向那些受影响或者可能受影响的国家或者地区进行下列事故通报和事故信息传递： （一）　立即通报事故及其性质、事故发生的时间和地点。 （二）　迅速提供事故发生时可以获得的初始事故信息，包括： （ 1 ）　事故的时间、地点及性质； （ 2 ）　涉及的核设施或者核活动； （ 3 ）　预计的或者已确定的事故的起因及发展趋势； （ 4 ）　放射性释放的一般特征，包括释放的放射性物质的性质、可能的物理与化学形态、组成、数量和释放的有效高度； （ 5 ）　与事故释放的放射性物质越境有关的气象与水文资料； （ 6 ）　有关的环境监测结果； （ 7 ）　已采取或者计划采取的场外防护措施； （ 8 ） 放射性物质释放的性状随时间的预期演变。 （三）　以适当的间"},{"i":5,"n":"第五条","txt":"国家核应急办对外通报和传递的核事故信息须经国家核应急主管部门批准，必要时报国务院批准。"},{"i":6,"n":"第六条","txt":"国家核应急办应当将对外通报和传递的核事故信息适时抄送国家核事故应急协调委员会成员单位和事故发生地的核应急组织或部门（省、自治区、直辖市和省级人民政府指定的部门，下同）。"},{"i":7,"n":"第七条","txt":"我国发生影响境外的核事故时，有关部门或者核事故发生地的核应急组织或部门可以根据我国与有关国家或者地区之间的双边或者多边协议进行事故信息交换，所交换的信息须经国家核应急主管部门批准，并向国家核应急办通报。"},{"i":8,"n":"第八条","txt":"我国受到或者可能受到境外核事故辐射影响时的应急响应由国家核事故应急协调委员会统一协调；国家核事故应急协调委员会各成员单位按照《国家核应急计划》规定的职责分工履行各自的职责。"},{"i":9,"n":"第九条","txt":"国家核应急办负责有关应急响应的具体组织管理，并根据《国家核应急计划》的规定，组织实施有关应急响应程序。"},{"i":10,"n":"第十条","txt":"境外发生使我国境内受到或者可能受到辐射影响的核事故时，由国家核应急办按照《及早通报核事故公约》的规定，直接或者通过国际原子能机构要求事故发生国家（地区）迅速提供本规定第四条所列的各项初始事故信息及有关后续信息，并向国际原子能机构通报我国受影响或者可能受影响的情况。"},{"i":11,"n":"第十一条","txt":"对境内造成或者可能造成辐射影响的境外核事故信息，由国家核应急办负责迅速向下列部门或单位通报或者传递： （一）　国家核事故应急协调委员会成员单位； （二） 受影响或者可能受影响地区的核应急组织或者部门； （三）　其他有关部门或者单位。 其他部门或单位由其他渠道接收到此类境外核事故信息时，应当立即将所接收到的信息通报国家核应急办。"},{"i":12,"n":"第十二条","txt":"受到境外核事故辐射影响时，有关部门应当按照《核电厂核事故应急管理条例》及《国家核应急计划》规定的职责进行所需要的公众信息发布。"},{"i":13,"n":"第十三条","txt":"受影响地区的核应急组织或部门负责组织实施本地区所需要的应急响应行动及防护措施。"},{"i":14,"n":"第十四条","txt":"受影响地区的应急响应组织应当进行必要的应急辐射监测与评价，必要时由国家核事故应急协调委员会调用支援力量进行监测与评价，以便为应急决策提供技术依据。所进行的监测与评价应当包括： （一）　空气中、地面上或者受影响海域的放射性污染水平； （二）　境内食品或者进口食品的放射性污染水平； （三） 来自污染区人员的放射性污染水平； （四）　来自污染区的车辆、船舶、飞行器以及其它物资的放射性污染水平； （五）　对进入境内的放射性烟羽的跟踪监测； （六）　利用上述各种数据和来自境外的有关资料，对事态的变化进行连续评价，预测其发展趋势。"},{"i":15,"n":"第十五条","txt":"对于来自事故发生国家（地区）的人员与物资，在放射性沉积地区活动的人员，以及可能受污染的食品与饮用水等，有关应急响应组织应当采取适当的防护或者控制措施。"},{"i":16,"n":"第十六条","txt":"如果境外核事故的发生地点距离我国较近或者带辐射源的空间飞行体坠入境内，在受影响严重的地区，有关应急组织或部门应当考虑采取紧急防护措施（如隐蔽、撤离、碘防护等）。"},{"i":17,"n":"第十七条","txt":"本规定下列术语的定义： （一）核事故，是指核设施或者核活动中发生的严重偏离运行工况的状态。在这种状态下，若有关的专设安全设施不能按设计要求发挥作用，则放射性物质的释放可能会达到不可接受的水平。 （二）核设施或者核活动是指： （ 1 ）　位于任何场所的各类核反应堆； （ 2 ）　核燃料循环设施； （ 3 ）　放射性废物管理设施； （ 4 ）　核燃料或者放射性废物的运输与贮存； （ 5 ）　用于农业、工业、医学和科学研究的放射性同位素的生产、使用、贮存、处置和运输； （ 6 ）　放射性同位素作空间飞行体的动力源。 （三）辐射影响，是指因事故释放或者失控的放射性物质，在其所到达地区所造成的从辐射安全角度考虑不可忽视的辐射照射和放射性污染。 （四）应急，是指需要立即采取某些超出正常工作程序的行动，以避免事故发生或者减轻事故后果的状态，有时也称为紧急状态；同时，也泛指立即采取超出正常工作程序的行"},{"i":18,"n":"第十八条","txt":"本规定由国防科学技术工业委员会负责解释。"},{"i":19,"n":"第十九条","txt":"本规定自 2002 年 4 月 1 日起施行。"}],"hejinchukoujiduiwaihehezuobaozhangjianduguanliguid1dc8ed":[{"i":1,"n":"第一条","txt":"为加强对核进出口及其他对外核合作保障监督事务的管理，切实履行《中华人民共和国和国际原子能机构关于在中国实施保障的协定》及其附加议定书、中国政府与有关国家政府签订的和平利用核能合作协定以及与核保障监督有关的其他条约或协定规定的义务，根据《中华人民共和国核出口管制条例》和国务院有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于进口和出口本规定附件一、二所列清单中的核材料、核设备、反应堆用非核材料及相关技术，以及通过其使用产生的特种可裂变材料和附件三所列其他对外核合作。 本规定所述 “ 相关技术 ” ，系指供应方在转让前与接受方磋商后指定的与核不扩散有关并专门用于附件一、二所列核材料、反应堆用非核材料的加工或专门用于对附件二所列核设备的设计、制造、运行、维护或与附件三所列其他对外核合作有关的技术数据或文件。"},{"i":3,"n":"第三条","txt":"本规定附件二清单所列物项中有关浓缩铀生产设施、设备、技术，辐照燃料后处理设施、设备、技术，以及重水生产设施、设备、技术均属于核扩散敏感物项。出口此类物项应根据中国核不扩散政策及所承担的国际义务严格控制。"},{"i":4,"n":"第四条","txt":"凡涉及核保障监督的核进出口及其他对外核合作应报国防科学技术工业委员会（以下简称国防科工委）审查。"},{"i":5,"n":"第五条","txt":"禁止向未接受国际原子能机构保障监督的无核武器国家的核设施提供帮助，不对其进行核出口和人员、技术交流与合作。"},{"i":6,"n":"第六条","txt":"国防科工委负责对核进出口及其他对外核合作保障监督进行管理，其职责是： （一）根据国家法律、法规和中国缔结或参加的有关国际协定，制定核进出口及其他对外核合作保障监督工作的管理规定； （二）组织实施《中华人民共和国和国际原子能机构关于在中国实施保障的协定》及其附加议定书； （三）就核进出口及其他对外核合作中涉及的重要的保障监督问题，商外交部、外经贸部提出处理意见，必要时报国务院审批； （四）掌握受保障监督物项的核进出口及有关对外核合作情况；指导涉及核保障监督事项的谈判；审查核进出口及其他对外核合作报告或申请，以及商务合同或合作协议中有关保障监督条款；办理有关的政府担保事宜； （五）建立和管理受保障监督的核材料衡算与控制系统；组织研究和开发核材料衡算与控制的技术和方法； （六）建立国家核进出口及其他对外核合作资料档案；向国际原子能机构通报中国核进出口及有关对外核合作情况； （七）培训保障监督"},{"i":7,"n":"第七条","txt":"国防科工委根据工作需要可委托相关机构，负责全国受保障监督的核材料衡算资料的管理和全国核进出口及其他对外核合作资料档案的管理，并在需要时派人陪同国际原子能机构视察员进行现场视察。该机构可就其受委托的业务同各受保障监督单位直接发生联系。"},{"i":8,"n":"第八条","txt":"核进出口单位应根据进口和出口的不同情况，分别按照本规定向国防科工委提交相应的报告或申请。"},{"i":9,"n":"第九条","txt":"受保障监督单位负责本单位保障监督的日常业务，其主要职责是： （一）研究提出核进口物项及相关设施接受保障监督的方案，经其上级主管单位同意后，报国防科工委审查； （二）确保受保障监督的核材料的物料平衡、不发生非法转用，并且受到必要的实物保护； （三）填写受保障监督设施情况报告表，按照国际原子能机构规定的统一格式，载明设施名称、地点、类型、能力及其他有关资料； （四）建立受保障监督的核材料账目，记录运进、运出、消耗、产生的核材料的种类、数量、同位素组成及其变化的数据； （五）根据本条第四项所记录的数据，对受保障监督设施中核材料的种类、数量、同位素组成进行定期衡算，并作出相应报告； （六）接待国际原子能机构视察员对受保障监督设施的现场视察，协助视察员起讫标记、清点实物、设置监视仪表、取样分析等，并将视察情况报国防科工委。"},{"i":10,"n":"第十条","txt":"参与对外核合作的单位应根据本规定第二十六条、第二十七条向国防科工委提交有关的报告和资料。"},{"i":11,"n":"第十一条","txt":"受保障监督单位的上级主管单位根据需要可设立管理保障监督业务的相关机构，研究审查受保障监督单位呈报的方案，指导和协调所属单位的保障监督业务。"},{"i":12,"n":"第十二条","txt":"进口单位应严格执行国家关于核进出口的政策、中国同国际原子能机构签订的保障监督协定的有关规定、中国与有关国家签订的政府间和平利用核能合作协定中的有关规定。"},{"i":13,"n":"第十三条","txt":"进口单位应在核进口合同谈判前，把拟从其进口的国家，以及进口物项（包括相关技术）的名称、数量，最终用户及最终用户是否具备接受保障监督的条件等事项预先报告国防科工委。合同谈判过程中如涉及保障监督问题应及时向国防科工委作出报告。核进口合同正式签署前应报国防科工委对涉及保障监督事项进行审查。"},{"i":14,"n":"第十四条","txt":"进口单位进口本规定附件一、二所列物项及相关技术，如供应方要求，经最终用户及其主管单位同意，可在进口合同中写明以下内容： （一）进口物项及相关技术的最终用户和用途； （二）进口物项及相关技术只用于和平和非爆炸目的； （三）未经供应方同意不向第三方再转让； （四）实施必要的实物保护措施。"},{"i":15,"n":"第十五条","txt":"进口单位从无核武器国家进口本规定附件一、二清单所列物项及相关技术，如供应方根据该国与中国签订的政府间和平利用核能协定的有关规定，提出保障监督要求，经最终用户及其上级主管单位同意，报国防科工委批准后，可承诺按照《中华人民共和国和国际原子能机构关于在中国实施保障的协定》，将使用此种物项或相关技术的核设施列入提交国际原子能机构保障监督的清单，并由国家原子能机构出具载有上述第十四条和本条中所载内容和所作承诺的书面担保文件。如供应方需要由中国外经贸部就进口物项的最终用户和用途出具证明，由外经贸部办理此种证明。"},{"i":16,"n":"第十六条","txt":"进口单位从有核武器国家进口本规定附件一、二清单所列物项及相关技术，一般无保障监督条件；如供应方提出保障监督要求，应依据中国与该国政府签订的和平利用核能合作协定及其他双边安排的规定办理。在确属必要的情况下，经最终用户及其主管单位同意，报国防科工委批准，可承诺按照《中华人民共和国和国际原子能机构关于在中国实施保障的协定》 ,将使用此种物项或相关技术的核设施列入提交国际原子能机构保障监督的清单，并由国家原子能机构出具载有上述第十四条和本条中所载内容和所作承诺的书面担保文件。如供应方需要由中国外经贸部就进口物项的最终用户和用途出具证明，由外经贸部办理此种证明。"},{"i":17,"n":"第十七条","txt":"进口本规定附件一、二清单所列物项及相关技术，进口单位应在收到供货后 15 日内，将该供货的名称和数量（相关技术的主要内容）、供应国、最终用户等事项报国防科工委备案。"},{"i":18,"n":"第十八条","txt":"核出口应严格按照《中华人民共和国核出口管制条例》、中国同国际原子能机构签订的保障监督协定及其附加议定书和中国同有关国家签订的核能合作协定中有关保障监督的规定执行。商务谈判中涉及到保障监督问题应及时报告国防科工委。"},{"i":19,"n":"第十九条","txt":"出口单位出口本规定附件一、二清单所列物项及相关技术，其出口合同中应写明以下内容： （一）出口物项及相关技术的最终用户和用途； （二）出口物项及相关技术只用于和平和非爆炸目的； （三）未经供应方事先书面同意不向第三方再转让；经同意再转让的，接受再转让的第三方应承担相当于由中国直接供应时所承担的义务； （四）该出口合同须经中国政府主管部门审核后方能生效。"},{"i":20,"n":"第二十条","txt":"出口单位向未接受国际原子能机构全面保障监督的无核武器国家出口本规定附件一或附件二清单所列物项及相关技术，接受方政府主管部门应就中国供应的物项或相关技术以及通过其使用所产生的特种可裂变材料，向中国国家原子能机构出具含有下述内容的担保文件： （一）最终用户和用途； （二）只用于和平和非爆炸目的； （三）通过其已有保障协定或新签订保障协定接受国际原子能机构的保障监督，在任何情况下都不转用于未接受国际原子能机构保障监督的核设施； （四）未经中国国家原子能机构事先书面同意，不向第三方再转让；经同意再转让的，接受再转让的第三方应承担相当于由中国直接供应时应承担的义务； （五）参照国际原子能机构的有关文件，采取必要的实物保护措施。"},{"i":21,"n":"第二十一条","txt":"出口单位向已接受国际原子能机构全面保障监督的无核武器国家出口本规定附件一、二清单所列物项及相关技术，接受方政府主管部门应向中国国家原子能机构出具含有下述内容的担保文件： （一）最终用户和用途； （二）将中国供应的物项纳入其已有的全面保障监督协定，由国际原子能机构实施保障监督； （三）未经中国国家原子能机构事先书面同意，不向第三方再转让； （四）对此种物项采取必要的实物保护措施。"},{"i":22,"n":"第二十二条","txt":"向有核武器国家出口本规定附件一、二清单所列物项及相关技术，一般无保障要求；但当此种出口涉及到第三条所述敏感物项及相关技术时是否提出保障要求以及出口附件一、二清单所列物项及相关技术是否要求接受方政府主管部门提供书面文件担保，应依据中国与该国政府签订的和平利用核能合作协定及其他双边安排的规定办理。"},{"i":23,"n":"第二十三条","txt":"如接受方提出再转让我出口的本规定附件一、二清单所列物项及相关技术，该项转让须由原出口单位报原审批单位审批。"},{"i":24,"n":"第二十四条","txt":"出口申请单位应填写核出口申请表并提交下列文件： （一）出口申请单位从事核出口的专营资格证明； （二）出口申请单位的法定代表人、主要经营管理人及经办人的身份证明； （三）合同或协议的副本； （四）核材料或反应堆用非核材料分析报告单（当出口物项为核材料或反应堆用非核材料时）； （五）最终用户证明； （六）本规定第二十条、二十一条、二十二条规定的接受方政府主管部门提供的书面担保文件； （七）审查机关要求提交的其他文件。"},{"i":25,"n":"第二十五条","txt":"核出口申请单位在收到核出口许可证后，应在发货日前 20 天内，将出口物项（包括相关技术）的名称、数量、发货日期、最终用户和受货国家等事项书面报告国防科工委。如果出口物项是核材料，且数量小于本规定附件一所列之数量，应在发货日前 10 天内将出口物项的名称、数量、发货日期、最终用户和受货国家等报国防科工委备案。"},{"i":26,"n":"第二十六条","txt":"同无核武器国家进行核进出口以外的核合作的单位，应根据中国关于不扩散核武器的政策，严格执行中国同上述有关国家签订的和平利用核能合作协定以及中国同国际原子能机构签订的保障协定附加议定书的有关规定。"},{"i":27,"n":"第二十七条","txt":"从事与附件三有关的对外核合作的单位，应在与对方签订合作协议前将协议文本报国防科工委审核，并在此种合作实际开始（含合作内容、规模发生变化）后 30 日内，根据实际合作的内容按照附件九所列格式向国防科工委提交相应的报告。"},{"i":28,"n":"第二十八条","txt":"核进出口单位、参与对外核合作的单位、受保障监督单位及其有关人员应严格遵守本规定。如违反本规定，未按程序及时报告或弄虚作假，给国家利益造成损害的，视情节轻重，给予批评教育，或依法给予行政处分；构成犯罪的，依法追究其刑事责任。"},{"i":29,"n":"第二十九条","txt":"保障监督的管理机构及其工作人员应严格履行本规定的职责。如违反本规定，玩忽职守、徇私舞弊或滥用职权，给国家利益造成损失的，依法给予行政处分；构成犯罪的，依法追究其刑事责任。"},{"i":30,"n":"第三十条","txt":"本规定由国防科工委会同外交部、外经贸部负责解释。"},{"i":31,"n":"第三十一条","txt":"本规定自 2002 年 3 月 1 日起施行。 附件： 1. 核材料进出口管制清单 （略） 2. 核设备和反应堆用非核材料进出口管制清单（略） 3. 其他对外核合作管制清单 （略） 4. 核进口谈判预先报告单 （略） 5. 核材料进口到货报告单 （略） 6. 核设备或反应堆用核材料进口到货报告单 （略） 7. 核材料出口发货报告单 （略） 8. 核设备或反应堆用非核材料出口发货报告单 （略） 9. 其他对外核合作报告单 （略）"}],"wuqizhuangbeikeyanshengchanxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范武器装备科研生产许可管理，根据《武器装备科研生产许可管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"从事武器装备科研生产许可目录（以下简称许可目录）所列的武器装备科研生产活动，应当依照本办法申请取得武器装备科研生产许可； 未取得武器装备科研生产许可的，不得从事许可目录所列的武器装备科研生产活动。但是，经国务院、中央军委批准的，以及 专门的武器装备科学研究活动 除外。 本办法所称武器装备科研生产活动，是指武器装备的总体、系统、专用配套产品的科研生产活动。 本办法所称专门的武器装备科学研究活动，是指武器装备领域的理论性、基础性科学研究活动。"},{"i":3,"n":"第三条","txt":"武器装备科研生产许可管理，应当根据国防建设和武器装备发展需要，遵循统筹兼顾、合理布局、鼓励竞争、安全保密、严格管理、公平公正的原则。"},{"i":4,"n":"第四条","txt":"武器装备科研生产许可根据武器装备及其专用配套产品的重要程度，分为第一类许可和第二类许可，武器装备科研生产许可的具体分类在许可目录中规定。许可目录由国家国防科技工业局（以下简称国防科工局）会同中国人民解放军总装备部（以下简称总装备部）共同制定和发布，并适时调整。"},{"i":5,"n":"第五条","txt":"国防科工局负责全国的武器装备科研生产许可管理，履行下列职责： （一）制定武器装备科研生产许可管理的政策、规定； （二）会同总装备部制定许可目录； （三）受理、审查第一类许可的申请，审批、颁发、撤销、吊销武器装备科研生产许可证，办理武器装备科研生产许可证的变更、延续及注销； （四）组织开展武器装备科研生产许可监督检查。 国防科工局武器装备科研生产许可管理办公室负责日常工作。"},{"i":6,"n":"第六条","txt":"总装备部负责全国武器装备科研生产许可的协同管理。总装备部武器装备科研生产许可协同管理部门（以下简称总装备部许可协同管理部门）履行下列职责： （一）参与制定武器装备科研生产许可管理的政策、规定； （二）会同编制许可目录； （三）协同审查武器装备科研生产许可的申请、发放、变更、延续、撤销和注销，对行政处罚提出意见； （四）组织中国人民解放军派出的驻相关单位或者地区的军事代表机构（以下简称派驻军事代表机构）参与武器装备科研生产许可现场审查； （五）协同开展武器装备科研生产许可监督检查。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府国防科技工业管理部门（以下称地方国防科技工业管理部门）履行下列职责： （一）受理、审查本行政区域内的第二类许可申请，并提出审查意见； （二）负责本行政区域内取得第二类许可的武器装备科研生产单位的监督管理 ； 调查核实本行政区域内违法从事武器装备科研生产的单位和行为，并向国防科工局提出处理建议； （三）协助国防科工局对本行政区域内申请第一类许可的单位进行现场审查； （四）协助国防科工局对本行政区域内取得第一类许可的武器装备科研生产单位进行监督管理。"},{"i":8,"n":"第八条","txt":"派驻军事代表机构按照军队内部职责分工协同地方国防科技工业管理部门开展派驻地区的武器装备科研生产许可审查和监督管理工作。"},{"i":9,"n":"第九条","txt":"国防科工局按照国家武器装备科研生产能力布局要求，根据武器装备科研生产的实际需要，经征求总装备部意见，对第一类许可实行数量限制。实行数量限制的具体专业或者产品和限制数量另行规定。"},{"i":10,"n":"第十条","txt":"申请 武器装备科研生产许可的单位，应当具备《武器装备科研生产许可管理条例》第七条规定的条件。其中，申请武器装备总体和系统科研生产许可的，还应当具有相应的工程组织、协调能力。"},{"i":11,"n":"第十一条","txt":"申请 武器装备科研生产许可的单位， 应当提交《武器装备科研生产许可证申请书》，同时提交以下文件、材料（复印件）： （一）企业法人营业执照或者事业单位法人证书； （二）相应的质量管理体系认证证书； （三）安全生产达标证明文件（其中申请从事危险品生产的，提交安全生产许可证或者安全生产评价报告）； （四）保密资格证书； （五）法律、行政法规规定的环保、消防验收文件或者达标文件； （六）申请单位认为可以证明其能力条件的其他文件、材料。"},{"i":12,"n":"第十二条","txt":"申请 武器装备科研生产许可的单位，按照下列规定提出申请： （一） 申请第一类许可的，或者同时申请第一类、第二类许可的，向国防科工局提出申请，并提交申请材料一式三份（含电子版光盘）。 （二）申请第二类许可的，向其所在省、自治区、直辖市的国防科技工业管理部门提出申请，并提交申请材料一式三份（含电子版光盘）。 第一类许可、第二类许可的申请材料（含电子版光盘）应当同时报送总装备部许可协同管理部门一份。"},{"i":13,"n":"第十三条","txt":"国 防科工局和地方国防科技工业管理部门应当依照《中华人民共和国行政许可法》第三十二条的规定进行审查，符合受理条件的，应当在 5 日内作出受理决定。申请材料不齐全或者不符合法定形式的，应当当场或者在 5 日内一次告知申请单位需要补正的全部内容。作出不予受理决定的，应当书面告知并说明理由。"},{"i":14,"n":"第十四条","txt":"总装备部许可协同管 理部门对许可申请材料的审查意见，应当自收到申请材料之日起 4 日内向国防科工局或者地方国防科技工业管理部门反馈。"},{"i":15,"n":"第十五条","txt":"国防科工局和地方国防科技工业管理部门 受理申请后，应当组织专家对武器装备科研生产 许可申请进行现场审查，总装备部许可协同管理部 门指派派驻军事代表机构参 加。对因涉及国家核心机密不宜进行现场审查的，可以根据实际情况进行书面审查。专家现场审查所需时间不计算在本章规定的许可时限内。 武器装备科研生产许可现场审查和专家管理的具体办法，由国防科工局和总装备部另行制定。"},{"i":16,"n":"第十六条","txt":"地方国防科技 工业管理部门负责组织对申请单位进行审查的，应当自受理申请之日起 30 日内完成审查和征求派驻军事代表机构意见的工作，并将审查意见和全 部申请材料报送国防科工局，同时报送总装备部许可协同管理部门。"},{"i":17,"n":"第十七条","txt":"国防科工局应 当自收到地方国防科技工业管理部门报送的审查意见和全部申请材料之日起 30 日内，作出许可决定。 国防科工局直接受理申请并组织进行审查的，应当自受理申请之日起 60 日内，作出许可决定。 国防科工局在作出许可决定前，应当书面征求总装备部的意见。总装备部应当在 10 日内反馈意见。 作出准予许可决定的，应当自作出决定之日起 10 日内向申请单位颁发武器装备科研生产许可证；作出不准予许可决定的，应当书面通知申请单位并说明理由。"},{"i":18,"n":"第十八条","txt":"武器装备科研生产许可证应当包括以下内容： （一）法人名称； （二）法定代表人； （三）注册地址； （四）科研生产场所地址； （五）许可的专业或者产品名称； （ 六）证书编号； （七）发证机关； （八）发证（换证）日期； （九）证书有效期限。"},{"i":19,"n":"第十九条","txt":"武器装备科研生产许可证的有效期限为 5 年。武器装备科研生产许可证由国防科工局统一印制。"},{"i":20,"n":"第二十条","txt":"取得武器装备科研生产许可的单位在武器装备科研生产许可证有效期限内，其法人名称、法定代表人、注册地址发生变更的，应当自发生变更之日起 60 日内向国防科工局提出武器装备科研生产许可证变更申请，同时抄送总装备部许可协同管理部门和原许可审查部门。"},{"i":21,"n":"第二十一条","txt":"申请变更法人名称或者注册地址的，应当提交其上级部门或者国家有关部门的批准文件，变更后的企业法人营业执照或者事业单位法人证书，以及变更后的保密资格证书等材料。 申请变更法定代表人的，应当提交法定代表人的任职文件或者其他有关证明文件，以及变更后的企业法人营业执照或者事业单位法人证书和保密资格证书。 其中，对因资产重组或者其他涉及资产变化问题，导致法人名称、注册地址或者法定代表人发生变化的，申请单位应当书面说明有关情况，并提供公司章程等相关证明材料。"},{"i":22,"n":"第二十二条","txt":"国防科工局收到变更申请后，应当依照法定条件和程序进行审查，必要时组织专家进行现场核查。符合变更条件的，由国防科工局自受理申请之日起 30 日内办理变更手续。专家现场核查所需时间不计算在本条规定的时限内。"},{"i":23,"n":"第二十三条","txt":"取得武器装备科研生产许可的单位在武器装备科研生产许可证有效期限内，申请增加武器装备科研生产许可专业或者产品的，应当按照本办法的规定重新提出申请。"},{"i":24,"n":"第二十四条","txt":"取得武器装备科研生产许可的单位拟申请延续武器装备科研生产许可期限的，应当在武器装备科研生产许可证有效期届满 6 个月前，按照本办法第十二条的规定提出许可延续申请。 国防科工局和地方国防科技工业管理部门应当在该许可有效期届满前，按照本办法规定的条件和程序对许可延续申请进行审查，由国防科工局按照本办法第十七条的规定作出是否准予延续的决定。作出准予延续决定的，应当换发武器装备科研生产许可证；作出不予延续决定的，应当书面告知申请单位并说明理由。"},{"i":25,"n":"第二十五条","txt":"取得武器装备科研生产许可的单 位，拟不再延续武器装备科研生产许可期限的，应当在许可证有效期届满 6个月前向国防科工局书面报告。在国防科工局商总装备部作出妥善安排前，不得擅自停止武器装备科研生产。"},{"i":26,"n":"第二十六条","txt":"国防 科工局对全国从事许可目录所列的武器装备科研生产活动的单位实施监督，建立监督检查制度，组织开展监督检查工作，并对地方国防科技工业管理部门依法履行武器装备科研生产许可管理有关职责的情况实施监督检查。 总装备部协同对全国从事许可目录所列的武器装备科研生产活动的单位实施监督，并对派驻军事代表机构履行武器装备科研生产许可协同管理职责的情况进行监督 。 地方国防科技工业管理部门应当按照本办法第七条的规定，对本行政区域内从事许可目录所列的武器装备科研生产活动的单位实施监督。 派驻军事代表机构对取得武器装备科研生产许可单位的武器装备科研生产许可条件保持情况和任务完成情况进行监督。发现问题的，应当及时逐级上报并告知 国防科工局或者地方国防科技工业管理部门 。 武器装备科研生产许可监督检查的具体办法，由国防科工局和总装备部另行制定。"},{"i":27,"n":"第二十七条","txt":"取得武器装备科研生产许可的单位，应当履行下列义务： （一）遵守法律、行政法规和本办法的规定； （二）妥善保管武器装备科研生产许可证，严格保密管理，不得泄露武器装备科研生产许可证载明的相关内容； （三）在已取得的武器装备科研生产许可的范围内从事武器装备科研生产活动； （四）保持与所从事的武器装备科研生产活动相适应的科研生产能力； （五）按照国家要求承担武器装备科研生产任务，接受国家武器装备科研生产订货，按照合同要求提供合格的科研成果和武器装备或者配套产品； （六）在武器装备科研生产合同、产品出厂证书上标注武器装备科研生产许可证编号； （七）建立年度自查制度，按照要求提交年度自查报告； （八）接受国防科工局、地方国防科技工业管理部门和 总装备部、 派驻军事代表机构的监督检查。"},{"i":28,"n":"第二十八条","txt":"取得武器装备科研生产许可的单位应当建立重大事项报告制度。在许可有效期内，发生上市、破产、歇业、改制、重组、科研生产场所搬迁、关键科研生产设备设施缺失等重大变化的，应当自发生变化之日起 30 日内向国防科工局书面报告变化情况，同时抄送总装备部许可协同管理部门和地方国防科技工业管理部门。国防科工局应当组织审查，根据审查情况商总装备部作出处理决定，并书面告知相关单位。 其中，取得武器装备科研生产许可的单位涉及外资进入资产重组或者境外上市的，应当在事前向国防科工局书面报告。经国防科工局商总装备部同意后，方可实施。"},{"i":29,"n":"第二十九条","txt":"取得武器装备科研生产许可的单位应当遵守国家保密法律、行政法规和有关规定，应当按照《武器装备科研生产许可管理条例》第三章的规定，建立健全保密管理制度，实行保密管理领导责任制，落实保密机构和人员，明确保密责任，进行保密培训，严格涉密人员管理，在保密要害部门、部位设置安全防护设施，保证涉密载体和国家秘密安全。"},{"i":30,"n":"第三十条","txt":"任何单位和个人不得伪造、变造武器装备科研生产许可证。取得武器装备科研生产许可的单位不得倒卖、出租、出借或者以其他形式转让武器装备科研生产许可证。武器装备科研生产许可证丢失、损毁的，应当及时向国防科工局报告有关情况并申请补发。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，国防科工局商总装备部后可以依法作出撤销武器装备科研生产许可的决定 : （一）国防科工局和地方国防科技工业管理部门的工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权作出准予许可决定的； （三）违反法定程序作出准予许可决定的； （四）对不具备申请资格或者不符合法定条件的申请单位准予许可的； （五）依法可以撤销的其他情形。"},{"i":32,"n":"第三十二条","txt":"取得武器装备科研生产许可的单位有下列情形之一的，经商总装备部后，国防科工局依法办理许可注销手续，并告知有关部门： （一）武器装备科研生产许可有效期届满不再准予延续的； （二）武器装备科研生产许可证依法被吊销的； （三）武器装备科研生产许可依法被撤销的； （四）法人依法终止或者破产的； （五）依法应当注销的其他情形。"},{"i":33,"n":"第三十三条","txt":"国防科工局应当建立武器装备科研生产许可档案管理制度和武器装备科研生产许可管理数据库，并与总装备部共享相关信息；编制并定向发布《武器装备科研生产许可证名录》，及时将武器装备科研生产许可证的发放、变更、延续、撤销、吊销、注销，以及对违法单位的行政处罚等情况通知相关部门。"},{"i":34,"n":"第三十四条","txt":"国防科工局和地方国防科技工业管理部门 应当将办理武器装备科研生产许可的有关材料及时归档，妥善保管，严格保密 。"},{"i":35,"n":"第三十五条","txt":"未依照本办法规定取得武器装备科研生产许可， 擅自从事许可 目录所列的武器装备科研生产活动的，责令改正，没收违法生产的产品，处违法生产产品货值金额 1 倍以上 3 倍以下的罚款；有违法所得的，没收违法所得。 其中，未经许可擅自从事武器装备总体或者枪支、弹药、放射性核材料和军用危险化学品等对社会公共安全有严重危害的武器装备科研生产活动的，处违法生产产品货值金额 3 倍的罚款；有违法所得的，没收违法所得。"},{"i":36,"n":"第三十六条","txt":"取得武器装备科研生产许可的单位在许可有效期内未能保持与所从事的武器装备科研生产活动相适应的科研生产能力和条件的，责令限期恢复；逾期未恢复的，根据其对武器装备科研生产任务影响的严重程度，给予警告或者处 1 万元以上 3 万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"取得武器装备科研生产许可的单位违反本办法规定，擅自停止武器装备科研生产或者拒绝依法承担相应的武器装备科研生产任务的，责令改正，给予警告；拒不改正的，处 1 万元以上 3 万元以下罚款。"},{"i":38,"n":"第三十八条","txt":"取得武器装备科研生产许可的单位出现本办法第二十八条所列的重大变化未按照规定时限报告的，给予警告，责令在 10 日内补报重大变化说明材料；经审查，不再符合许可条件的，由国防科工局商总装备部作出处理决定。"},{"i":39,"n":"第三十九条","txt":"取得武器装备科研生产许可的单位倒卖、出租、出借或者以其他形式转让武器装备科研生产许可证的，处 10 万元罚款；情节严重的，吊销武器装备科研生产许可证。违法接受并使用他人提供的武器装备科研生产许可证的，责令停止武器装备生产活动，没收违法生产的产品，处违法生产产品货值金额 1 倍以上 3 倍以下罚款；有违法所得的，没收违法所得。"},{"i":40,"n":"第四十条","txt":"取得武器装备科研生产许可的单位向本办法第二十七条规定的监督检查机关或者机构隐瞒有关情况、提供虚假材料或者拒绝接受监督检查的，以及未按照规定提交年度检查材料的，给予警告；情节严重的，处 1 万元以上 3 万元以下罚款。"},{"i":41,"n":"第四十一条","txt":"取得武器装备科研生产许可的单位违反《武器装备科研生产许可管理条例》第三章规定的，按照《武器装备科研生产许可管理条例》有关规定进行处理；对于造成国家秘密泄露的其他行为，处 1 万元以上 3 万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"伪造、变造武器装备科研生产许可证的，责令停止违法行为，处 10 万元罚款；有违法所得的，没收违法所得。 丢失武器装备科研生产许可证造成泄密的，依照《中华人民共和国保守国家秘密法》有关规定处理。"},{"i":43,"n":"第四十三条","txt":"以欺骗、贿赂等不正当手段取得武器装备科研生产许可的，处 5 万元以上 20 万元以下罚款，并依照《中华人民共和国行政许可法》的有关规定作出处理。"},{"i":44,"n":"第四十四条","txt":"国防科工局和地方国防科技工业管理部门的 工作人员违反本办法的规定，有下列情形之一的，由同级监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）对符合本办法规定条件的许可申请不予受理的； （二）申请单位提交的申请材料不齐全、不符合法定形式，不一次告知申请单位需要补正的全部内容的； （三）未依法说明不予许可的理由的。"},{"i":45,"n":"第四十五条","txt":"国防科工局和地方国防科技工业管理部门 有下列情形之一的，由同级监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）对不符合本办法规定条件的申请单位准予许可或者超越法定职权作出准予许可决定的； （二）对符合本办法规定条件的申请单位不予许可或者不在法定期限内作出准予许可决定的； （三）发现未依照本办法规定申请取得武器装备科研生产许可而擅自从事许可目录所列的武器装备科研生产活动，不及时依法查处的。"},{"i":46,"n":"第四十六条","txt":"总装备部许可协同管理部门和派驻军事代表机构参与许可管理的工作人员违反本办法规定的，由总装备部会同军队有关部门依法作出处理。"},{"i":47,"n":"第四十七条","txt":"取得武器装备科研生产许可的单位违反本办法规定，被吊销武器装备科研生产许可证的，在 3 年内不得再次申请武器装备科研生产许可。"},{"i":48,"n":"第四十八条","txt":"武器装备科研生产许可申请单位隐瞒有关情况或者提供虚假材料造成许可现场审查终止的，给予警告；申请单位在 1 年内不得再次申请武器装备科研生产许可。"},{"i":49,"n":"第四十九条","txt":"本办法规定的行政处罚，由国防科工局实施。"},{"i":50,"n":"第五十条","txt":"本办法施行前已取得的《军工电子装备科研生产许可证》在证书有效期内继续有效，后续管理工作按照本办法规定执行。"},{"i":51,"n":"第五十一条","txt":"军队所属单位从事武器装备科研生产活动的许可管理办法另行制定。"},{"i":52,"n":"第五十二条","txt":"本办法自 2010 年 5 月 10 日起 施行。 2004 年 12 月 14 日 公布的《军工电子装备科研生产许可证管理办法》（ 中华人民共和国信息产业部令第 32 号）和 2005 年 5 月 26 日 公布的《武器装备科研生产许可实施办法》（中华人民共和国国防科学技术工业委员会令第 15 号）同时废止。"}],"minyongbaozhawupinanquanshengchanxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了加强民用爆炸物品安全生产监督管理，预防生产安全事故，根据《中华人民共和国安全生产法》、《安全生产许可证条例》和《民用爆炸物品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"取得《民用爆炸物品生产许可证》的企业，在基本建设完成后，应当依照本办法申请民用爆炸物品安全生产许可。 企业未获得《民用爆炸物品安全生产许可证》的，不得从事民用爆炸物品生产活动。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责指导、监督全国民用爆炸物品生产企业安全生产许可的审批和管理工作。 省、自治区、直辖市人民政府民用爆炸物品行业主管部门（以下简称省级民爆行业主管部门）负责民用爆炸物品生产企业安全生产许可的审批和监督管理。 设区的市和县级人民政府民用爆炸物品行业主管部门在各自职责范围内依法对民用爆炸物品安全生产工作实施监督管理。 为方便申请人，省级民爆行业主管部门可委托设区的市或者县级人民政府民用爆炸物品行业主管部门（以下简称初审机关）承担本行政区内民用爆炸物品生产企业安全生产许可申请的受理、初审工作。"},{"i":4,"n":"第四条","txt":"民用爆炸物品生产作业场所的安全生产，实行属地管理的原则。民用爆炸物品生产作业场所（含现场混装作业场所）安全生产应当接受生产作业场所所在地民用爆炸物品行业主管部门的监督管理。"},{"i":5,"n":"第五条","txt":"申请民用爆炸物品安全生产许可，应当具备下列条件： （一）取得相应的民用爆炸物品生产许可； （二）具有健全的企业、车间、班组三级安全生产责任制以及完备的安全生产规章制度和操作规程； （三）安全投入符合民用爆炸物品安全生产要求； （四）设置安全生产管理机构，配备专职安全生产管理人员，并具有从事安全生产管理的注册安全工程师； （五）主要负责人和安全生产管理人员经过民用爆炸物品安全生产培训并考核合格； （六）特种作业人员经有关业务主管部门考核合格，取得特种作业操作资格证书； （七）生产作业人员通过有关民用爆炸物品基本知识的安全生产教育和培训，并经考试合格取得上岗资格证书； （八）依法参加工伤保险，为从业人员交纳保险费； （九）厂房、库房、作业场所和安全设施、设备、工艺、产品符合有关安全生产法律、法规和《民用爆破器材工程设计安全规范》（GB50089）、《民用爆炸物品生产、销售企业安全管理规程》"},{"i":6,"n":"第六条","txt":"申请民用爆炸物品安全生产许可的企业自主选择具有民用爆炸物品制造业安全评价资质的安全评价机构，对本企业的生产条件进行安全评价。 省级民爆行业主管部门不得以任何形式指定安全评价机构。"},{"i":7,"n":"第七条","txt":"安全评价机构应当按照《民用爆炸物品安全评价导则》（WJ9048）及有关安全技术标准、规范的要求，对申请民用爆炸物品安全生产许可的企业是否符合本办法第五条规定的条件逐项进行安全评价，出具安全评价报告。 安全评价机构对其安全评价结论负责。"},{"i":8,"n":"第八条","txt":"企业对安全评价报告中提出的问题应当及时加以整改，安全评价机构应当对企业的整改情况进行确认，并将有关确认资料作为安全评价报告的附件。"},{"i":9,"n":"第九条","txt":"取得《民用爆炸物品生产许可证》的生产企业在从事民用爆炸物品生产活动前，应当向生产作业场所所在地省级民爆行业主管部门或者初审机关提出民用爆炸物品安全生产许可申请，填写《民用爆炸物品安全生产许可证申请审批表》（一式3份，由工业和信息化部提供范本），并完整、真实地提供本办法第五条规定的相关文件、材料。"},{"i":10,"n":"第十条","txt":"省级民爆行业主管部门或者初审机关自收到申请之日起5日内，根据下列情况分别作出处理： （一）申请事项不属于本行政机关职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （二）申请材料存在错误，可以当场更正的，应当允许申请人当场更正； （三）申请材料不齐全或者不符合法定形式的，应当当场或者在5日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请事项属于本行政机关职权范围，申请材料齐全、符合法定形式，或者申请人按照本行政机关的要求提交全部补正申请材料的，应当予以受理。"},{"i":11,"n":"第十一条","txt":"省级民爆行业主管部门自收到申请之日起45日内审查完毕。由初审机关初审的，初审机关应当自受理申请之日起20日内完成对申请材料的审查及必要的安全生产条件核查，并将下列材料报送省级民爆行业主管部门： （一）《民用爆炸物品安全生产许可证申请审批表》； （二）企业提交的全部申请材料； （三）对申请企业安全生产条件的初审意见。 对符合本办法第五条规定条件的，核发《民用爆炸物品安全生产许可证》；对不符合条件的，不予核发《民用爆炸物品安全生产许可证》，书面通知申请人并说明理由。 安全生产许可需要组织专家现场核查的，应当书面告知申请人并组织现场核查。现场核查所需时间不计算在许可期限内。 省级民爆行业主管部门应当自《民用爆炸物品安全生产许可证》颁发之日起15日内，将发证情况报告工业和信息化部并通过有关政府网站等渠道予以公布。 《民用爆炸物品安全生产许可证》应当载明企业名称、注册地址、法定代表人、登记类型、"},{"i":12,"n":"第十二条","txt":"《民用爆炸物品安全生产许可证》有效期为3年。有效期届满需要继续从事民用爆炸物品生产活动的，应当在有效期届满前3个月向省级民爆行业主管部门或者初审机关申请延续。 经省级民爆行业主管部门审查，符合民用爆炸物品安全生产许可条件的，应当在有效期届满前准予延续，并向社会公布；不符合民用爆炸物品安全生产许可条件的，不予延续，书面通知申请人并说明理由。"},{"i":13,"n":"第十三条","txt":"《民用爆炸物品安全生产许可证》有效期内，企业名称、注册地址、法定代表人、登记类型发生变更的，企业应当自《民用爆炸物品生产许可证》变更之日起20日内向省级民爆行业主管部门提出《民用爆炸物品安全生产许可证》变更申请，省级民爆行业主管部门应当在10日内完成变更手续，并将结果告知初审机关。 安全生产的品种和能力、生产地址发生变更的，企业应当依照本办法重新申请办理《民用爆炸物品安全生产许可证》。重新核发的《民用爆炸物品安全生产许可证》有效期不变。"},{"i":14,"n":"第十四条","txt":"《民用爆炸物品安全生产许可证》实行年检制度。民用爆炸物品生产企业应当于每年3月向省级民爆行业主管部门或者初审机关报送下列材料： （一）《民用爆炸物品安全生产许可证年检表》（由工业和信息化部提供范本）； （二）落实安全生产管理责任和安全隐患整改情况； （三）安全生产费用提留和使用、主要负责人和安全管理人员培训、实际生产量与销售情况； （四）省级民爆行业主管部门要求报送的其他材料。 初审机关应当在5日内完成初审工作并将相关材料报送省级民爆行业主管部门。"},{"i":15,"n":"第十五条","txt":"省级民爆行业主管部门自收到相关材料之日起20日内，根据下列情况分别作出处理： （一）企业严格遵守有关安全生产的法律法规和民用爆炸物品行业安全生产有关规定，安全生产条件没有发生变化，没有发生一般及以上等级的生产安全事故的，在《民用爆炸物品安全生产许可证》标注“年检合格”； （二）企业严重违反有关安全生产的法律法规和民用爆炸物品行业安全生产有关规定或者发生一般及以上等级的生产安全事故，限期未完成整改的，在《民用爆炸物品安全生产许可证》标注“年检不合格”； （三）企业不具备本办法规定安全生产条件的，在《民用爆炸物品安全生产许可证》标注“年检不合格”。"},{"i":16,"n":"第十六条","txt":"对《民用爆炸物品安全生产许可证》年检不合格的企业，由省级民爆行业主管部门责令其限期整改。整改完成后，企业重新申请年检。"},{"i":17,"n":"第十七条","txt":"企业发生一般及以上等级的生产安全事故的，应当依据《生产安全事故报告和调查处理条例》进行报告。企业安全生产条件发生重大变化或者发生生产安全事故造成人员死亡的，还必须向所在地省级民爆行业主管部门和工业和信息化部报告。"},{"i":18,"n":"第十八条","txt":"民用爆炸物品生产企业应当建立健全生产安全事故隐患排查治理制度，采取技术、管理措施，及时发现并消除事故隐患，事故隐患排查治理情况应当如实记录，并向从业人员通报。"},{"i":19,"n":"第十九条","txt":"各级民用爆炸物品行业主管部门应当建立健全监督制度，加强对民用爆炸物品生产企业的日常监督检查，督促其依法进行生产。 实施监督检查，不得妨碍民用爆炸物品生产企业正常的生产经营活动，不得索取或者收受企业的财物或者谋取其他利益。"},{"i":20,"n":"第二十条","txt":"企业未获得《民用爆炸物品安全生产许可证》擅自组织民用爆炸物品生产的，由省级民爆行业主管部门责令停止生产，处10万元以上50万元以下的罚款，没收非法生产的民用爆炸物品及其违法所得；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"企业不具备本办法规定安全生产条件的，省级民爆行业主管部门应当责令停产停业整顿；经停产停业整顿仍不具备安全生产条件的，吊销其《民用爆炸物品安全生产许可证》，并报请工业和信息化部吊销其《民用爆炸物品生产许可证》。"},{"i":22,"n":"第二十二条","txt":"安全评价机构出具虚假安全评价结论或者出具的安全评价结论严重失实的，由省级民爆行业主管部门报工业和信息化部提请有关部门取消安全评价机构资质和安全评价人员执业资格。"},{"i":23,"n":"第二十三条","txt":"以欺骗、贿赂等不正当手段取得《民用爆炸物品安全生产许可证》的，省级民爆行业主管部门撤销其《民用爆炸物品安全生产许可证》，3年内不再受理其该项许可申请。"},{"i":24,"n":"第二十四条","txt":"负责民用爆炸物品安全生产许可的工作人员，在安全生产许可的受理、审查、审批和监督管理工作中，索取或者接受企业财物，或者谋取其他利益的，给予降级或者撤职处分；有其他滥用职权、玩忽职守、徇私舞弊行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本办法施行前已经取得民用爆炸物品安全生产许可的企业，应当自本办法施行之日起1年内，依照本办法的规定办理《民用爆炸物品安全生产许可证》。"},{"i":26,"n":"第二十六条","txt":"省级民爆行业主管部门应当依据本办法和本地实际，制定实施细则。"},{"i":27,"n":"第二十七条","txt":"本办法自2015年6月30日起施行。原国防科学技术工业委员会2006年8月31日公布的《民用爆炸物品安全生产许可实施办法》（原国防科学技术工业委员会令第17号）同时废止。"}],"minyongbaozhawupinshengchanxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了加强民用爆炸物品生产许可管理，规范民用爆炸物品生产活动，保障公民生命、财产安全和公共安全，根据《民用爆炸物品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立民用爆炸物品生产企业应当依据本办法取得民用爆炸物品生产许可。"},{"i":3,"n":"第三条","txt":"民用爆炸物品生产许可管理应当遵循统筹规划、合理布局、动态调整、严格管理、公平公正的原则。"},{"i":4,"n":"第四条","txt":"工业和信息化部负责民用爆炸物品生产许可的审批和监督管理。 省、自治区、直辖市人民政府民用爆炸物品行业主管部门（以下简称省级民爆行业主管部门）依照本办法规定负责本行政区域内民用爆炸物品生产许可监督管理有关工作。"},{"i":5,"n":"第五条","txt":"鼓励民用爆炸物品生产企业采用提高民用爆炸物品安全性能的新产品、新设备、新技术、新工艺、新材料以及现场混装生产技术。"},{"i":6,"n":"第六条","txt":"申请民用爆炸物品生产许可，应当具备下列条件： （一）符合国家产业结构规划、产业技术标准和民爆行业发展规划； （二）厂房和专用仓库的设计、结构、建筑材料、安全距离以及安全设备、设施符合国家有关标准和规范； （三）生产设备、工艺技术符合有关安全生产的技术标准和规程； （四）主要负责人具有与所生产民用爆炸物品相适应的安全生产知识和管理能力，与民用爆炸物品生产相关专业的技术人员占职工人数的比例不得低于15%； （五）有健全的安全、质量管理制度和岗位安全责任制度； （六）法律、行政法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请民用爆炸物品生产许可，应当向工业和信息化部提出申请，并提交以下材料： （一）民用爆炸物品生产许可申请文件； （二）《民用爆炸物品生产许可证申请审批表》（一式三份，示范文本见附件1）； （三）民用爆炸物品生产许可项目申请报告（一式三份，示范文本见附件2）； （四）省级民爆行业主管部门出具的书面意见； （五）民用爆炸物品安全评价机构出具的安全预评价报告； （六）法定代表人无刑事处罚材料； （七）专业技术人员资质证明复印件； （八）法律、行政法规规定的其他材料。"},{"i":8,"n":"第八条","txt":"工业和信息化部应当依法对申请材料进行审查，对于申请材料不齐全或者不符合法定形式的，当场或在5日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理；申请材料齐全、符合法定形式，或者申请人按照要求补正全部申请材料的，应当予以受理。"},{"i":9,"n":"第九条","txt":"工业和信息化部自受理申请之日起45日内对申请材料进行审查，对符合本办法第六条规定条件的，核发《民用爆炸物品生产许可证》；对不符合条件的，不予核发《民用爆炸物品生产许可证》，书面告知申请人并说明理由。 需要组织专家现场评审的，工业和信息化部应当将评审所需时间书面告知申请人。评审所需时间不计算在前款规定的期限内。"},{"i":10,"n":"第十条","txt":"《民用爆炸物品生产许可证》的内容包括：企业名称、法定代表人、注册地址、登记类型、有效期、证书编号、生产地址、生产品种和年生产能力等。 《民用爆炸物品生产许可证》由正本、副本和附件组成，式样由工业和信息化部统一规定。附件作为备注栏信息，随《民用爆炸物品生产许可证》一并发放，与正本、副本具有同等效力。"},{"i":11,"n":"第十一条","txt":"《民用爆炸物品生产许可证》有效期为3年。有效期届满需要继续从事民用爆炸物品生产的，应当在有效期届满前3个月向工业和信息化部申请延续，并提交本办法第七条第（一）项至第（四）项规定的材料。 工业和信息化部应当在有效期届满前作出是否准予延续的决定。准予延续的，收回原证并换发新证；不予延续的，书面告知申请人并说明理由。"},{"i":12,"n":"第十二条","txt":"《民用爆炸物品生产许可证》有效期内，民用爆炸物品生产企业申请变更企业名称、注册地址、登记类型的，应当向工业和信息化部提出申请，提交本办法第七条第（一）项至第（三）项规定的材料以及有关机构批准变更的文件；涉及变更法定代表人的，还应当提交本办法第七条第（六）项规定的材料。 工业和信息化部应当在接到申请之日起15日内作出是否同意变更的决定。"},{"i":13,"n":"第十三条","txt":"民用爆炸物品生产企业为调整生产品种及年生产能力进行改建、扩建、异地建设，或者采用现场混装生产方式生产民用爆炸物品的，应当依照本办法重新申请办理《民用爆炸物品生产许可证》，提交本办法第七条第（一）项至第（四）项规定的材料；涉及变更生产地址的，还应当提交本办法第七条第（五）项规定的材料。"},{"i":14,"n":"第十四条","txt":"民用爆炸物品生产企业不改变生产品种及年生产能力，在现有生产线原址进行技术改造的，应当报省级民爆行业主管部门备案。省级民爆行业主管部门将备案情况按年度汇总后报工业和信息化部。"},{"i":15,"n":"第十五条","txt":"《民用爆炸物品生产许可证》及其编号仅限本企业使用，不得转让、买卖、出租、出借。"},{"i":16,"n":"第十六条","txt":"民用爆炸物品生产企业经工业和信息化部批准，可以授权其持股比例（包括直接持有和间接持有）不少于51%并符合民用爆炸物品生产条件的企业生产其获准生产的民用爆炸物品。工业和信息化部应当在《民用爆炸物品生产许可证》附件中载明该被授权企业名称、注册地址、生产品种、生产地址、年生产能力、有效期等内容。"},{"i":17,"n":"第十七条","txt":"民用爆炸物品生产企业应当按照《民用爆炸物品生产许可证》核定的事项进行生产，生产作业应当执行安全技术规程等规定。 无民事行为能力人、限制民事行为能力人或者曾因犯罪受过刑事处罚的人不得从事民用爆炸物品生产。"},{"i":18,"n":"第十八条","txt":"工业和信息化部对民用爆炸物品生产许可实行年度报告制度。民用爆炸物品生产企业应当于每年5月31日前向注册地省级民爆行业主管部门报送《民用爆炸物品生产许可证年度报告表》（一式三份，示范文本见附件3），省级民爆行业主管部门汇总后报送工业和信息化部。"},{"i":19,"n":"第十九条","txt":"工业和信息化部应当加强对民用爆炸物品生产企业的监督检查，建立和完善随机抽查监督管理制度，公布抽查事项目录，随机选派检查人员，随机抽取被检查企业。抽查情况和查处结果及时向社会公布。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，工业和信息化部可以撤销民用爆炸物品生产许可： （一）民用爆炸物品生产许可申请受理、审查的工作人员滥用职权、玩忽职守作出许可决定的； （二）超越法定职权或者违反法定程序作出许可决定的； （三）对不具备申请资格或者不符合法定许可条件的申请人作出许可决定的； （四）依法可以撤销民用爆炸物品生产许可的其他情形。"},{"i":21,"n":"第二十一条","txt":"以欺骗、贿赂等不正当手段取得《民用爆炸物品生产许可证》的，工业和信息化部应当撤销民用爆炸物品生产许可。企业3年内不得再次提出民用爆炸物品生产许可申请。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，工业和信息化部应当依法办理《民用爆炸物品生产许可证》注销手续： （一）《民用爆炸物品生产许可证》有效期届满，未申请延续或者申请延续未经批准的； （二）民用爆炸物品生产许可依法被撤销、吊销的； （三）因不可抗力因素导致民用爆炸物品生产许可事项无法实施的； （四）法律、行政法规规定的应当注销许可证的其他情形。 工业和信息化部定期向社会公布被依法注销《民用爆炸物品生产许可证》的企业名单。"},{"i":23,"n":"第二十三条","txt":"工业和信息化部建立民用爆炸物品生产企业信用记录制度，将民用爆炸物品生产企业违反本办法并受到行政处罚的行为记入信用档案。"},{"i":24,"n":"第二十四条","txt":"任何单位或个人对违反《民用爆炸物品安全管理条例》和本办法的行为，有权向负有监督管理职责的部门举报。"},{"i":25,"n":"第二十五条","txt":"未经许可从事民用爆炸物品生产的，由省级民爆行业主管部门责令停止非法生产活动，处10万元以上50万元以下的罚款，并没收非法生产的民用爆炸物品及其违法所得。"},{"i":26,"n":"第二十六条","txt":"民用爆炸物品生产企业有下列行为之一的，由省级民爆行业主管部门责令限期改正，处10万元以上50万元以下的罚款；逾期不改正的，责令停产整顿；情节严重的，由省级民爆行业主管部门提请工业和信息化部吊销《民用爆炸物品生产许可证》： （一）超出许可核定的生产品种、能力进行生产的； （二）违反安全技术规程生产作业的； （三）民用爆炸物品的质量不符合相关标准的； （四）因存在严重安全问题被吊销民用爆炸物品安全生产许可的； （五）违反法律、行政法规应予吊销民用爆炸物品生产许可的其他情形。"},{"i":27,"n":"第二十七条","txt":"民用爆炸物品生产企业有下列行为之一的，由省级民爆行业主管部门责令限期改正；逾期不改正的，处3万元以下的罚款： （一）未按规定提交年度报告的； （二）年度报告提供虚假材料或者拒绝提供反映其生产经营活动情况真实材料的。"},{"i":28,"n":"第二十八条","txt":"省级民爆行业主管部门可以委托市级或者县级地方人民政府民用爆炸物品行业主管部门实施本办法规定的行政处罚。 省级民爆行业主管部门应当加强对市级或者县级地方人民政府民用爆炸物品行业主管部门实施行政处罚的监督，并对行政处罚的后果承担法律责任。"},{"i":29,"n":"第二十九条","txt":"负责民用爆炸物品生产许可的工作人员，在民用爆炸物品生产许可受理、审查、审批和监督管理工作中，有弄虚作假、徇私舞弊以及受贿、渎职等行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法自2019年1月1日起施行。原国防科学技术工业委员会2006年8月31日公布的《民用爆炸物品生产许可实施办法》（原国防科学技术工业委员会令第16号）同时废止。"}],"minyongbaozhawupinjinchukouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对民用爆炸物品进出口的管理，维护国家经济秩序，保障社会公共安全，根据《民用爆炸物品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"进出口民用爆炸物品，适用本办法。 本办法所称民用爆炸物品，是指用于非军事目的、列入民用爆炸物品品名表的各类火药、炸药及其制品和雷管、导火索等点火、起爆器材。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责民用爆炸物品进出口的审批。 公安机关负责民用爆炸物品境内运输的安全监督管理。 海关负责民用爆炸物品进出口环节的管理。"},{"i":4,"n":"第四条","txt":"进出口民用爆炸物品，应当依照本办法的规定逐单申请办理审批手续。 严禁进出口未经工业和信息化部核发《民用爆炸物品进/出口审批单》的民用爆炸物品。"},{"i":5,"n":"第五条","txt":"取得《民用爆炸物品生产许可证》的企业可以申请进口用于本企业生产的民用爆炸物品原材料（含半成品），出口本企业生产的民用爆炸物品（含半成品）。 取得《民用爆炸物品销售许可证》的企业可以申请进出口其《民用爆炸物品销售许可证》核定品种范围内的民用爆炸物品。"},{"i":6,"n":"第六条","txt":"申请进出口民用爆炸物品，应当向工业和信息化部提交下列材料： （一）民用爆炸物品进出口申请报告及已填写相关内容的《民用爆炸物品进/出口审批单》（一式五份）； （二）工商营业执照原件及复印件； （三）《民用爆炸物品生产许可证》或者《民用爆炸物品销售许可证》原件及复印件； （四）企业法定代表人及经办人的身份证明原件及复印件； （五）进出口合同原件、复印件及中文译本（译本应当加盖申请人的公章，下同）； （六）进口民用爆炸物品，应当提交具备与进口量相适应的仓储条件和满足行业安全要求的证明材料、不低于我国现行产品标准的证明材料、符合国家有关安全运输和储存标准的证明材料、符合《民用爆炸物品警示标识、登记标识通则》的证明材料、符合国家有关环保标准的证明材料和产品使用说明（相关材料应当提供中文译本）； （七）出口民用爆炸物品，应当提交民用爆炸物品进口国的许可文件原件、复印件及中文译本、最终用户证明和最终"},{"i":7,"n":"第七条","txt":"工业和信息化部对申请材料进行审查。申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部内容；逾期不告知的，自收到申请材料之日起即为受理。 申请材料齐全、符合法定形式，或者已按要求提交全部补正申请材料的，应当予以受理，并出具受理通知书。"},{"i":8,"n":"第八条","txt":"工业和信息化部自受理申请之日起二十个工作日内作出是否批准的决定。批准进出口民用爆炸物品的，应当向申请人核发《民用爆炸物品进/出口审批单》；不予批准的，应当书面告知申请人。 国家禁止进口或者明令淘汰的民用爆炸物品，工业和信息化部不予批准进口。 《民用爆炸物品进/出口审批单》实行“一批一单”和“一单一关”管理。"},{"i":9,"n":"第九条","txt":"进出口企业应当将获准进出口的民用爆炸物品的品种和数量等信息向收货地或者出境口岸所在地县级人民政府公安机关备案，并同时向所在地省级民用爆炸物品行业主管部门备案。 运输民用爆炸物品，应当依法取得公安机关核发的《民用爆炸物品运输许可证》。"},{"i":10,"n":"第十条","txt":"企业进出口民用爆炸物品的，凭《民用爆炸物品进/出口审批单》向口岸海关办理进出口手续。"},{"i":11,"n":"第十一条","txt":"违反海关有关规定进出口民用爆炸物品的，依照海关法律、行政法规及规章的规定处理。"},{"i":12,"n":"第十二条","txt":"海关无法确定进出口物品是否属于民用爆炸物品的，由进出口企业将物品样品送交具有民用爆炸物品检测资质的机构鉴定，海关依据有关鉴定结论实施进出口管理。"},{"i":13,"n":"第十三条","txt":"民用爆炸物品在海关特殊监管区域或者场所与境外之间进出的，应当依据本办法的规定办理审批手续，接受监督和管理。"},{"i":14,"n":"第十四条","txt":"以不正当手段取得民用爆炸物品进出口批准文件的，由工业和信息化部撤销其民用爆炸物品进出口批准文件，申请人在三年内不得再次申请进出口民用爆炸物品。"},{"i":15,"n":"第十五条","txt":"未经批准或者超出批准范围进出口民用爆炸物品的，依照有关法律、行政法规的规定处罚。"},{"i":16,"n":"第十六条","txt":"进出口民用爆炸物品未按照规定向公安机关备案的，由公安机关依照《民用爆炸物品安全管理条例》第四十六条的规定处罚。"},{"i":17,"n":"第十七条","txt":"民用爆炸物品进出口企业涂改、倒卖或者以其他形式非法转让《民用爆炸物品进/出口审批单》的，由工业和信息化部责令限期改正，予以警告，并处三万元以下的罚款。"},{"i":18,"n":"第十八条","txt":"民用爆炸物品进出口管理人员在民用爆炸物品进出口管理活动中滥用职权、玩忽职守、徇私舞弊或者违反《中华人民共和国行政许可法》等有关规定的，依法给予处理；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"国家禁止进出口的民用爆炸物品目录，由工业和信息化部、海关总署按照《中华人民共和国对外贸易法》的有关规定商请对外贸易主管部门制定、调整并公布。"},{"i":20,"n":"第二十条","txt":"硝酸铵的进口，按照国家有关规定管理。硝酸铵的出口，由工业和信息化部委托省级民用爆炸物品行业主管部门参照本办法的规定管理。"},{"i":21,"n":"第二十一条","txt":"《民用爆炸物品进/出口审批单》的式样由工业和信息化部会同海关总署制定。"},{"i":22,"n":"第二十二条","txt":"本办法自2012年9月1日起施行。"}],"minyongbaozhawupinxiaoshouxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了加强民用爆炸物品销售管理，规范民用爆炸物品销售许可行为，保障公民生命、财产安全和公共安全，根据《民用爆炸物品安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称民用爆炸物品销售是指销售企业销售民用爆炸物品和生产企业销售本企业生产的民用爆炸物品的活动。"},{"i":3,"n":"第三条","txt":"从事《民用爆炸物品品名表》所列产品销售活动的企业，必须依照本办法申请取得《民用爆炸物品销售许可证》。 民用爆炸物品生产企业凭《民用爆炸物品生产许可证》，可以销售本企业生产的民用爆炸物品。"},{"i":4,"n":"第四条","txt":"国防科学技术工业委员会（以下简称国防科工委）负责制定民用爆炸物品销售许可的政策、规章、审查标准和技术规范，对民用爆炸物品销售许可实施监督管理。 省、自治区、直辖市人民政府国防科技工业主管部门（以下简称省级国防科技工业主管部门）负责本辖区内民用爆炸物品销售许可申请的受理、审查和《民用爆炸物品销售许可证》的颁发及日常监督管理。 地（市）、县级人民政府民用爆炸物品主管部门，协助省级国防科技工业主管部门做好本行政区内民用爆炸物品销售许可的监督管理工作，其职责由省级国防科技工业主管部门规定。"},{"i":5,"n":"第五条","txt":"省级国防科技工业主管部门实施销售许可管理，应当遵循统筹规划、合理布局、规模经营、确保安全的原则。"},{"i":6,"n":"第六条","txt":"鼓励发展民用爆炸物品生产、配送、爆破服务一体化的经营模式。"},{"i":7,"n":"第七条","txt":"申请从事民用爆炸物品销售的企业，应当具备下列条件： （一）具有企业法人资格； （二）符合本地区民用爆炸物品销售企业规划的要求； （三）符合规模经营和确保安全的要求； （四）安全评价达到安全级标准； （五）销售场所和专用仓库的设计、结构和材料、安全距离以及防火、防爆、防雷、防静电等安全设备、设施符合国家有关标准和规范； （六）有相应资格的安全管理人员、仓库管理人员、押运员、驾驶员，以及符合规定的爆炸品专用运输车辆； （七）有健全的安全管理制度、岗位责任制度； （八）法律、法规规定的其他条件。"},{"i":8,"n":"第八条","txt":"申请从事民用爆炸物品销售的企业，应当向所在地省级国防科技工业主管部门提交以下材料： （一）民用爆炸物品销售许可申请文件； （二）《民用爆炸物品销售许可证申请审批表》（一式2份，见附件1）； （三）地（市）、县级人民政府民用爆炸物品主管部门意见； （四）可行性研究报告； （五）民用爆炸物品安全评价机构出具的安全评价报告； （六）单位主要负责人、安全管理人员和业务人员（仓库管理人员、销售人员、押运员、驾驶员）任职安全资格证书或专业培训合格证书原件及复印件； （七）安全管理制度、岗位责任制度档案文件； （八）法律、法规规定的其他证明材料。"},{"i":9,"n":"第九条","txt":"申请《民用爆炸物品销售许可证》的企业自主选择具有民用爆炸物品安全评价资质的安全评价机构，对本企业的销售条件进行安全评价。"},{"i":10,"n":"第十条","txt":"安全评价机构应当按照《民用爆破器材安全评价导则》及有关安全技术标准、规范的要求，对申请销售许可的企业进行安全评价，出具安全评价报告。 安全评价机构对其安全评价结论承担法律责任。"},{"i":11,"n":"第十一条","txt":"对安全评价报告中提出的问题，申请企业应当及时加以整改。安全评价机构应当对申请企业的整改情况进行确认，并将有关资料作为安全评价报告书的附件。"},{"i":12,"n":"第十二条","txt":"省级国防科技工业主管部门自收到申请之日起5日内，根据下列情况分别作出处理： （一）申请事项不属于本行政机关职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （二）申请材料存在错误，可以当场更正的，应当允许申请人当场更正； （三）申请材料不齐全或者不符合法定形式的，当场或在5日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （四）申请事项属于本行政机关职权范围，申请材料齐全、符合法定形式，或者申请人按照本行政机关的要求提交全部补正申请材料的，应当予以受理。"},{"i":13,"n":"第十三条","txt":"省级国防科技工业主管部门自受理申请之日起30日内对申请材料进行审查，对符合本办法第七条规定条件的，核发《民用爆炸物品销售许可证》；对不符合条件的，不予核发《民用爆炸物品销售许可证》，书面告知申请人，并说明理由。"},{"i":14,"n":"第十四条","txt":"省级国防科技工业主管部门认为需要组织专家对申请单位进行现场核查的，应当书面告知申请人。现场核查所需时间不计算在许可期限内。"},{"i":15,"n":"第十五条","txt":"省级国防科技工业主管部门，应当在《民用爆炸物品销售许可证》颁发之日起15日内，将发证情况向国防科工委报告。"},{"i":16,"n":"第十六条","txt":"民用爆炸物品销售企业，持《民用爆炸物品销售许可证》到工商行政管理部门办理工商登记后，方可销售民用爆炸物品。 民用爆炸物品销售企业应当在办理工商登记后3日内，向所在地县级人民政府公安机关备案。"},{"i":17,"n":"第十七条","txt":"《民用爆炸物品销售许可证》的内容包括：企业名称、地址、法定代表人、登记类型、有效期、许可销售的品种和储存能力。《民用爆炸物品销售许可证》式样由国防科工委统一规定。"},{"i":18,"n":"第十八条","txt":"《民用爆炸物品销售许可证》有效期为3年。有效期届满，企业继续从事民用爆炸物品销售活动的，应当在届满前3个月内向原发证机关提出换证申请。原发证机关应当在销售许可证有效期届满前按照本办法第七条规定的条件进行审查，符合条件的，换发新证；不符合条件的，不予换发新证，书面告知申请人，并说明理由。"},{"i":19,"n":"第十九条","txt":"《民用爆炸物品销售许可证》有效期内，企业名称、法定代表人、登记类型等内容发生变更的，企业应当依法办理变更登记，由原发证机关审核后换发新证。 销售品种、储存能力发生变更的，应当在变更前30日内向省级国防科技工业主管部门提出变更申请。经审查，符合第七条规定条件的，办理变更手续；不符合条件的，不予换发新证，书面通知申请人，并说明理由。"},{"i":20,"n":"第二十条","txt":"民用爆炸物品销售企业应当严格按照《民用爆炸物品销售许可证》核定的销售品种、核定储存能力从事销售活动，不得超范围销售或者超能力储存民用爆炸物品。"},{"i":21,"n":"第二十一条","txt":"民用爆炸物品生产企业销售本企业生产的民用爆炸物品，不得超出《民用爆炸物品生产许可证》核定的品种、产量。"},{"i":22,"n":"第二十二条","txt":"销售民用爆炸物品的企业，应当自民用爆炸物品买卖成交之日起3日内，将销售的品种、数量和购买单位向企业所在地省级国防科技工业主管部门和所在地县级人民政府公安机关备案。"},{"i":23,"n":"第二十三条","txt":"销售民用爆炸物品的企业应当制定安全生产事故应急救援预案，建立应急救援组织，配备应急救援人员和必要的应急救援器材、设备。"},{"i":24,"n":"第二十四条","txt":"省级国防科技工业主管部门应当加强对《民用爆炸物品销售许可证》的监督管理，建立健全许可申请受理、审查、颁证等各项管理制度，并于每季度第一个月20日之前将上季度销售许可证变更情况向国防科工委报告。"},{"i":25,"n":"第二十五条","txt":"销售民用爆炸物品的企业应当建立销售台账制度及出入库检查、登记制度，收存和发放民用爆炸物品必须及时登记，做到账目清楚，账物相符。"},{"i":26,"n":"第二十六条","txt":"省级国防科技工业主管部门负责对已取得《民用爆炸物品销售许可证》的企业进行年检。民用爆炸物品销售企业应当于每年3月底前向发证机关提交《民用爆炸物品销售许可证年检表》（一式3份，见附件2）。"},{"i":27,"n":"第二十七条","txt":"省级国防科技工业主管部门应当自收到年检表之日起20日内完成年检工作。符合条件的，在年检表上盖章；不符合条件的，书面告知企业并限期整改。"},{"i":28,"n":"第二十八条","txt":"取得《民用爆炸物品销售许可证》的企业不得降低安全经营条件。省级国防科技工业主管部门发现企业不再具备本办法第七条规定条件的，应当暂扣其销售许可证，责令其停业整顿。企业经过整改并由省级国防科技工业主管部门重新组织验收合格后，方可恢复其销售活动。"},{"i":29,"n":"第二十九条","txt":"《民用爆炸物品销售许可证》及其编号仅限本企业使用，不得转让、买卖、出租、出借。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，省级国防科技工业主管部门可以撤销已经作出的民用爆炸物品销售许可决定： （一）民用爆炸物品销售许可申请受理、审查的工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权或者违反法定程序作出准予许可决定的； （三）对不具备申请资格或不符合法定安全生产条件的申请人作出准予许可决定的； （四）依法可以撤销民用爆炸物品销售许可决定的其他情形。"},{"i":31,"n":"第三十一条","txt":"以欺骗、贿赂等不正当手段取得《民用爆炸物品销售许可证》的，省级国防科技工业主管部门撤销其销售许可证，3年内不再受理其该项许可申请。"},{"i":32,"n":"第三十二条","txt":"企业未经许可从事民用爆炸物品销售活动的，由省级国防科技工业主管部门责令停止非法销售活动，处10万元以上50万元以下的罚款，没收非法销售的民用爆炸物品及其违法所得。"},{"i":33,"n":"第三十三条","txt":"民用爆炸物品销售企业有下列行为之一的，由省级国防科技工业主管部门责令限期改正，处10万元以上50万元以下的罚款；逾期不改正的，责令停业整顿；情节严重的，吊销《民用爆炸物品销售许可证》： （一）超出销售许可的品种进行销售的； （二）向没有《民用爆炸物品生产许可证》、《民用爆炸物品销售许可证》、《民用爆炸物品购买许可证》的单位销售民用爆炸物品的； （三）因管理不善致使民用爆炸物品丢失或被盗的； （四）未按规定程序和手续销售民用爆炸物品的； （五）超量储存民用爆炸物品或者将性质相抵触的爆炸物品同处储存的； （六）销售民用爆炸物品未按规定向省级国防科技工业主管部门备案的； （七）因存在严重安全隐患，整改期限内，仍不能达到要求的； （八）发生重特大事故不宜恢复销售活动的； （九）销售企业转让、买卖、出租、出借销售许可证的。"},{"i":34,"n":"第三十四条","txt":"民用爆炸物品生产企业有下列行为之一的，由国防科工委责令限期改正，处10万元以上50万元以下的罚款；逾期不改正的，责令停业整顿；情节严重的，吊销《民用爆炸物品生产许可证》： （一）销售非本企业生产产品的； （二）销售产品的品种、数量超出生产许可范围的。"},{"i":35,"n":"第三十五条","txt":"省级国防科技工业部门工作人员在销售许可的受理、审查、颁证和监督管理工作中，有弄虚作假、徇私舞弊以及受贿、渎职等行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"在本办法施行前已经从事民用爆炸物品销售活动的企业，应当自本办法施行之日起1年内，依照本办法的规定申请办理《民用爆炸物品销售许可证》。"},{"i":37,"n":"第三十七条","txt":"本办法规定的许可期限以工作日计算，不含法定节假日。"},{"i":38,"n":"第三十八条","txt":"本办法自2006年9月1日起施行。原《民用爆破器材经营企业凭照管理暂行办法》（科工法字〔2000〕562号）同时废止。 附件： 1、民用爆炸物品销售许可证申请审批表 2、民用爆炸物品销售许可证年检表"}],"minyonghangtianfashexiangmuxukezhengguanlizanxingbba28f6":[{"i":1,"n":"第一条","txt":"为了规范民用航天发射项目管理，促进民用航天产业健康发展，维护国家安全及公众利益，履行我国作为外层空间国际公约缔约国的义务，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称民用航天发射项目是指非军事用途，在中国境内的卫星等航天器进入外层空间的行为，以及中华人民共和国自然人、法人或其他组织已拥有产权的或者通过在轨交付方式拥有产权的卫星等航天器在中国境外进入外层空间的行为。"},{"i":3,"n":"第三条","txt":"民用航天发射项目实行许可证管理制度。凡从事民用航天发射项目的自然人、法人或其他组织，应当依照本办法的规定申请审查批准，经审查合格取得民用航天发射项目许可证（以下简称许可证）后，方可从事民用航天发射项目。"},{"i":4,"n":"第四条","txt":"国防科学技术工业委员会（以下简称国防科工委）对民用航天发射项目实行统一规划和管理，负责审查、批准和监督民用航天发射项目（以下简称项目）。"},{"i":5,"n":"第五条","txt":"项目总承包人是许可证申请人。若无国内的项目总承包人，卫星等航天器产权的最终所有人是许可证申请人。 许可证申请人应当具备下列条件： （一）遵守国家法律、法规，保守国家秘密； （二）申请的项目不危害国家安全，不损害国家利益，不违反国家的外交政策和已签署并发生效力的国际公约； （三）申请的项目不会因重大过失或故意行为对公众的健康、安全和财产构成无法补偿的危害； （四）具有国家有关部门发放的从事所申请项目的相关许可文件； （五）具备从事所申请项目的技术力量、经济实力及完善的技术资料； （六）法律、法规、规章规定的其它条件。"},{"i":6,"n":"第六条","txt":"申请人应当在项目预定发射月的 9 个月之前，向国防科工委提交下列文件（一式三份）： （一）民用航天发射项目许可证申请书及许可证申请人资格审查材料。 （二）证明该项目符合国家环境保护法律、法规的有关材料。 （三）国内执行发射场工作阶段的项目，需提供项目预定发射时间，卫星、运载火箭、发射和测控通信系统之间的技术要求，运载火箭详细轨道参数及落区或回收场区的勘察报告，卫星详细轨道参数、频率资源使用情况的文件。 国外执行发射场工作阶段的项目，需提交运载火箭、卫星轨道参数等具有法律效力的文件副本，以及使用有关频率资源的许可文件副本。 我国的卫星发射者应当提供信息产业部颁发的该空间电台的《中华人民共和国无线电台执照》副本。 （四）与该项目相关的安全设计报告及保障公众安全的材料，关键安全系统的可靠性、运载火箭发射过程中正常及故障状态对发射场附近及发射轨迹范围内的财产及人身安全构成的影响、如何避免污染和"},{"i":7,"n":"第七条","txt":"国防科工委在收到申请材料之日起 30 日内，对申请的项目组织审查。对审查合格的项目，颁发许可证；对审查不合格的项目，不予颁发许可证，并书面通知申请人及相关部门。"},{"i":8,"n":"第八条","txt":"申请人对审查结论持有异议的，可向国防科工委申请复审一次或依法申请行政复议。"},{"i":9,"n":"第九条","txt":"涉外项目必须由中国政府指定的外贸公司组织相关事宜，涉外项目的合同必须经国防科工委批准后方能生效。"},{"i":10,"n":"第十条","txt":"许可证主要包括下列内容： （一）申请人及法定代表人； （二）注册地址（申请人住址）； （三）项目主要内容； （四）预定发射时间； （五）许可证有效期； （六）发证机关和发证时间。"},{"i":11,"n":"第十一条","txt":"许可证仅限于批准的项目使用，该项目结束后，许可证自动失效。"},{"i":12,"n":"第十二条","txt":"许可证不得涂改、转让。"},{"i":13,"n":"第十三条","txt":"许可证内容需要变更的，许可证持有人应在许可证有效期期满之前 90 天，向国防科工委提出变更申请，经审查批准后，方可变更许可证。"},{"i":14,"n":"第十四条","txt":"对拟取消的项目，许可证持有人应当在许可证有效期期满之前 90 天，向国防科工委提出取消申请，经审查批准后，予以注销许可证。"},{"i":15,"n":"第十五条","txt":"因许可证持有人管理不善无力完成的项目，由国防科工委注销该项目许可证。"},{"i":16,"n":"第十六条","txt":"许可证持有人有下列情形之一的，国防科工委责令其限期改正；情节严重的，吊销其许可证： （一）在项目执行期间违反国家有关法律、法规以及国家间的保密协定； （二）在项目执行期间有危害国家安全，损害国家利益，违反国家的外交政策和已签署并发生效力的国际公约的行为； （三）未按许可证核定的范围从事民用航天发射活动； （四）其他违反本办法的行为。"},{"i":17,"n":"第十七条","txt":"被吊销许可证的项目，自吊销之日起两年内，该项目申请人不得再次就同一项目提出许可证申请。"},{"i":18,"n":"第十八条","txt":"因许可证持有人的原因造成项目内容更改、时间延期或取消，并导致相关方面发生费用的，其相关责任及应承担的费用，由许可证持有人与有关各方以合同明确。"},{"i":19,"n":"第十九条","txt":"许可证持有人必须遵照国家有关规定购买发射空间物体的第三方责任保险和其他相关保险。"},{"i":20,"n":"第二十条","txt":"在国内执行发射场工作阶段的项目，许可证持有人应在预定发射月的 6 个月之前，向国防科工委上报项目发射计划。 进入发射场工作阶段之前，许可证持有人应向国防科工委上报出厂申请，并提交下列材料： （一）运载火箭技术状态文件、质量状态控制文件、飞行试验大纲、安全、保密及其他需出具的文件。 （二）该项目已生效的第三方责任保险保单副本及相关文件副本一式三份，以及相关已生效保险保单副本一式三份。特殊情况应向国防科工委提出书面材料，依据具体情况处理。 经批准后，该项目方可进入发射场工作阶段。"},{"i":21,"n":"第二十一条","txt":"在国外执行发射场工作阶段的项目，许可证持有人应在预定发射日之前 60 天，向国防科工委上报出厂申请，并附已生效的第三方责任保险、相关保险、安全、保密等方面具有法律效力的最终文件副本一式三份。经批准后，方可继续实施该项目。"},{"i":22,"n":"第二十二条","txt":"许可证持有人必须在项目发射结束后一个月内向国防科工委书面上报项目完成情况。"},{"i":23,"n":"第二十三条","txt":"国防科工委将不定期监督检查已批准项目的实施情况，其授权的公务人员有权现场检查项目执行过程中的相关活动。"},{"i":24,"n":"第二十四条","txt":"对许可证持有人在申报和执行过程中隐瞒真相、弄虚作假，损害国家利益的，依法给予行政处罚；构成犯罪的，依法追究其刑事责任。"},{"i":25,"n":"第二十五条","txt":"对未取得许可证擅自从事项目的自然人、法人或其他组织，由国防科工委责令其停止非法活动，并对有关当事人依法给予行政处罚；构成犯罪的，依法追究其刑事责任。"},{"i":26,"n":"第二十六条","txt":"对审查机构及其工作人员在许可证审批过程中玩忽职守、滥用职权，给国家造成损失的，依法给予行政处分；构成犯罪的，依法追究其刑事责任。"},{"i":27,"n":"第二十七条","txt":"本办法由国防科工委负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自 2002 年 12 月 21 日起施行。 附件：民用航天发射项目许可证申请书 （略）"}],"yancaozhuanmaipinzhunyunzhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强烟草专卖品准运证的管理，规范烟草专卖品流通秩序，根据《中华人民共和国烟草专卖法》及其实施条例，制定本办法。"},{"i":2,"n":"第二条","txt":"运输卷烟、雪茄烟、烟丝、复烤烟叶、烟叶（包括再造烟叶和烟梗）、卷烟纸、滤嘴棒、烟用丝束、烟草专用机械等烟草专卖品，应当持有烟草专卖品准运证。 无烟草专卖品准运证，不得运输烟草专卖品。"},{"i":3,"n":"第三条","txt":"本办法适用于中华人民共和国境内烟草专卖品准运证的管理。"},{"i":4,"n":"第四条","txt":"各级烟草专卖局应当对办理烟草专卖品准运证的部门及其工作人员、烟草专卖品准运证使用和管理情况进行监督检查。"},{"i":5,"n":"第五条","txt":"签发烟草专卖品准运证，应当使用国家烟草专卖局统一管理的烟草专卖品准运证计算机网络管理系统。"},{"i":6,"n":"第六条","txt":"烟草专卖品准运证应当由省级以上（含省级，下同）烟草专卖局签发。地（市）级烟草专卖局可以按照省级烟草专卖局的委托，代签烟草专卖品准运证。"},{"i":7,"n":"第七条","txt":"国家烟草专卖局有权签发所有烟草专卖品准运证，并可以授权或者委托省级烟草专卖局签发烟草专卖品准运证。 下列烟草专卖品的运输，应当由国家烟草专卖局签发烟草专卖品准运证： （一）需由国家烟草专卖局有关业务主管部门调剂的烟草专卖品； （二）中国烟草总公司直属专业公司进口的卷烟纸、滤嘴棒和烟用丝束； （三）出口退货的烟草专卖品； （四）依法没收的走私烟草专卖品。"},{"i":8,"n":"第八条","txt":"下列烟草专卖品的运输，由国家烟草专卖局授权或者委托省级烟草专卖局签发烟草专卖品准运证： （一）进口本办法第七条第二款第二项以外的烟草专卖品； （二）滤嘴棒、烟用丝束和烟草专用机械。"},{"i":9,"n":"第九条","txt":"卷烟、雪茄烟、烟丝、烟叶、复烤烟叶和卷烟纸的运输，由省级烟草专卖局签发烟草专卖品准运证。"},{"i":10,"n":"第十条","txt":"省级烟草专卖局经国家烟草专卖局批准，可以委托地（市）级烟草专卖局代签国产的卷烟、雪茄烟、烟丝、烟叶、复烤烟叶、卷烟纸、滤嘴棒和烟用丝束的烟草专卖品准运证。"},{"i":11,"n":"第十一条","txt":"烟草专卖品准运证由烟草专卖品所在地有权签发准运证的烟草专卖局负责办理。"},{"i":12,"n":"第十二条","txt":"上级烟草专卖局授权或者委托下级烟草专卖局签发烟草专卖品准运证，应当符合下列条件： （一）根据实际情况确实需要授权或者委托； （二）符合烟草专卖管理的分级管理、属地管辖原则； （三）被授权或者受委托人应当是省级或地（市）级烟草专卖局； （四）被授权或者受委托人应当具备签发烟草专卖品准运证所需的计算机设备和网络通讯以及专门人员等。"},{"i":13,"n":"第十三条","txt":"申请办理烟草专卖品准运证应当具备下列条件： （一）调出方和调入方是合法的烟草专卖品生产企业或者批发企业； （二）申请运输的是符合法律规定的烟草专卖品； （三）申办人应当持有申请人的委托书和本人身份证等合法证明； （四）具有合法有效的购销合同或者调拨单以及其他应当具备的证明材料原件。"},{"i":14,"n":"第十四条","txt":"烟草专卖局应当按照下列程序签发烟草专卖品准运证： （一）对申请人提交的相关材料进行审核； （二）符合办理烟草专卖品准运证条件的，经主管领导批准后，由专人负责办理； （三）不符合办理烟草专卖品准运证条件的，不予签发，应当通知申请人，并说明理由。"},{"i":15,"n":"第十五条","txt":"签发烟草专卖品准运证，应当以国家烟草专卖局统一管理的烟草专卖品准运证计算机网络管理系统中储存的购销合同或者调拨单信息等为基本依据。"},{"i":16,"n":"第十六条","txt":"对符合办理烟草专卖品准运证条件的，烟草专卖局应当在收到全部申请材料之日起1个工作日内办理，并将烟草专卖品准运证交付申请人。 如遇计算机故障、不可抗力等特殊情况，经主管办理烟草专卖品准运证的负责人批准后，可以自收到办理申请之日起3个工作日内办理完毕，并将烟草专卖品准运证交付申请人。"},{"i":17,"n":"第十七条","txt":"烟草专卖品准运证的签发机关应当根据申请人申请运输烟草专卖品的运输距离、运输方式等情况，合理确定准运证的有效期限。烟草专卖品准运证的有效期限，公路运输最长不得超过20天，其他运输方式最长不得超过30天。 烟草专卖品准运证的有效期限，从签发之日开始计算。"},{"i":18,"n":"第十八条","txt":"烟草专卖局应当将签发烟草专卖品准运证的有关材料及烟草专卖品准运证存根存档备查。保存期为3年。"},{"i":19,"n":"第十九条","txt":"因打印错误、计算机故障等原因造成烟草专卖品准运证作废的，应当及时更正错误，排除计算机故障，并在更正和排除故障当日内完成作废手续。"},{"i":20,"n":"第二十条","txt":"签发烟草专卖品准运证的机关，应当依据本办法建立健全有关烟草专卖品准运证的管理制度，接受上级烟草专卖局的监督检查。 签发烟草专卖品准运证的权限、条件、程序以及工作人员的职责，应当公开、透明。"},{"i":21,"n":"第二十一条","txt":"烟草专卖品准运证是运输烟草专卖品必备的合法证件，应随货同行，证货相符，并只能在有效期限内使用1次。 在运输烟叶、复烤烟叶、卷烟过程中，鉴章的购销合同（出口合同除外）原件应与烟草专卖品准运证一起随货同行。运输货物的规格、等级、数量、发货地和到货地以准运证的数据和标注为准。"},{"i":22,"n":"第二十二条","txt":"因不可抗力或者意外事件致使在烟草专卖品准运证有效期内不能完成运输的，申请人应当提供相关证明材料，并向原发证机关申请办理更换手续。"},{"i":23,"n":"第二十三条","txt":"使用烟草专卖品准运证运输烟草专卖品，货物抵达目的地时，调入方验货无误后，应及时在准运证上加盖“货已收讫”印章，并上网确认。"},{"i":24,"n":"第二十四条","txt":"烟草专卖局应当将因办理差错而作废的烟草专卖品准运证及时收回，并存档备查。"},{"i":25,"n":"第二十五条","txt":"下列行为属于《中华人民共和国烟草专卖法》第二十九条规定的无烟草专卖品准运证运输： （一）未办理烟草专卖品准运证运输烟草专卖品的； （二）烟草专卖品准运证没有随货同行的； （三）重复使用烟草专卖品准运证的； （四）证货不符，超出或者少于烟草专卖品准运证规定数量、品种或者规格的部分； （五）使用过期、涂改、复印、传真、伪造、变造的烟草专卖品准运证的； （六）利用隐瞒、欺骗等手段取得烟草专卖品准运证运输烟草专卖品的； （七）无烟草专卖品准运证又无法提供在当地购买烟草专卖品的有效证明的； （八）无烟草专卖品准运证运输烟草专卖品的其他行为。 持有烟草专卖品准运证但实际改变到货地点的，或者运输烟叶、复烤烟叶、卷烟过程中鉴章的购销合同原件（出口合同除外）没有随货同行的，均视为无烟草专卖品准运证运输。"},{"i":26,"n":"第二十六条","txt":"各级烟草专卖局按照《中华人民共和国烟草专卖法实施条例》第四十七条的规定，在对非法运输烟草专卖品活动进行检查和处理过程中，可以采取下列措施： （一）烟草专卖行政主管部门或者烟草专卖行政主管部门会同有关部门依法对涉嫌从事非法运输烟草专卖品活动和场所进行检查，依法对违法行为进行处理； （二）对涉嫌非法运输的烟草专卖品及其运输工具进行暂存检查，但应当在7个工作日内进行处理； （三）对涉嫌非法运输烟草专卖品的有关合同、发票、帐册、单据、记录、文件、业务函电和其他资料等进行查阅、复制； （四）对涉嫌非法运输烟草专卖品的当事人、嫌疑人、证人进行调查和询问。"},{"i":27,"n":"第二十七条","txt":"对违反本办法行为的行政处罚，按照《中华人民共和国烟草专卖法》及其实施条例的规定执行。"},{"i":28,"n":"第二十八条","txt":"违反本办法签发烟草专卖品准运证的机关，由上级烟草专卖局视其情节轻重分别给予以下处理： （一）通报批评，责令限期整改； （二）取消被授权或者受委托签发烟草专卖品准运证的资格； （三）情节严重涉嫌犯罪的，依法移交司法部门处理。"},{"i":29,"n":"第二十九条","txt":"经办人或者批准人未按照本办法签发烟草专卖品准运证的，视其情节轻重分别给予以下处理： （一）通报批评，责令限期改正； （二）取消经办人或者批准人办理或批准签发烟草专卖品准运证的资格； （三）行政处分； （四）情节严重涉嫌犯罪的，依法移交司法部门处理。"},{"i":30,"n":"第三十条","txt":"调入方没有及时加盖“货已收讫”印章并上网确认的，应当对有关单位进行通报批评，并视情节轻重对直接责任人员和有关责任人依法给予行政处分。"},{"i":31,"n":"第三十一条","txt":"申请人通过隐瞒或者欺骗等手段非法取得烟草专卖品准运证，应当由原发证机关收回或者撤销其烟草专卖品准运证，并依法追究有关单位和个人的行政责任。情节严重涉嫌犯罪的，依法移交司法部门处理。"},{"i":32,"n":"第三十二条","txt":"烟草专卖执法部门及其工作人员，不得以任何理由对合法运输烟草专卖品进行非法扣留。因烟草专卖执法人员滥用职权、非法扣留造成当事人经济损失的，应当依法赔偿，并追究直接责任人和有关负责人的行政责任。情节严重涉嫌犯罪的，依法移交司法部门处理。"},{"i":33,"n":"第三十三条","txt":"上一级烟草专卖局依法授权下一级烟草专卖局签发烟草专卖品准运证，被授权的烟草专卖局以自身名义签发烟草专卖品准运证，并承担相应的责任。"},{"i":34,"n":"第三十四条","txt":"上一级烟草专卖局依法委托下一级烟草专卖局签发烟草专卖品准运证的，受委托的烟草专卖局以委托人的名义签发烟草专卖品准运证，委托人承担由此产生的责任。"},{"i":35,"n":"第三十五条","txt":"烟草专卖品准运证的规格和式样以及准运证的专用章的印模式样，由国家烟草专卖局统一制定。"},{"i":36,"n":"第三十六条","txt":"签发烟草专卖品准运证的机关不得以任何形式收费或者变相收费。"},{"i":37,"n":"第三十七条","txt":"本办法由国家烟草专卖局负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2016年7月20日起施行。原国家经济贸易委员会2002年6月4日公布的《烟草专卖品准运证管理办法》（原国家经济贸易委员会令第31号）同时废止。"}],"yancaozhuanmaixingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范烟草专卖行政处罚的实施，保障和监督烟草专卖局有效实施行政管理，维护国家烟草专卖制度，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国烟草专卖法》《中华人民共和国未成年人保护法》以及《中华人民共和国烟草专卖法实施条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"各级烟草专卖局实施行政处罚，适用本规定。"},{"i":3,"n":"第三条","txt":"烟草专卖局实施行政处罚，应当遵循下列原则： （一）以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当； （二）主体适格、程序合法、手续完备； （三）处罚与教育相结合，教育公民、法人或者其他组织自觉守法； （四）公平公正、公开透明，保障当事人的合法权益。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对烟草专卖局给予的行政处罚，依法享有陈述、申辩的权利；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。 公民、法人或者其他组织因烟草专卖局违法给予行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":5,"n":"第五条","txt":"各级烟草专卖局应当建立健全行政处罚内部监督制度，保证依法实施行政处罚。"},{"i":6,"n":"第六条","txt":"烟草专卖行政处罚案件由违法行为发生地的县级以上烟草专卖局管辖。"},{"i":7,"n":"第七条","txt":"县级烟草专卖局管辖本辖区内发生的案件。 地市级烟草专卖局管辖本辖区内发生的有重大影响的案件。 省、自治区、直辖市烟草专卖局管辖本辖区内发生的重大、复杂案件。 国家烟草专卖局管辖在全国范围内有重大影响的案件。"},{"i":8,"n":"第八条","txt":"两个以上烟草专卖局都有管辖权的，由最先立案的烟草专卖局管辖。 对管辖发生争议的，应当协商解决，协商不成的，报请共同的上一级烟草专卖局指定管辖；也可以直接由共同的上一级烟草专卖局指定管辖。"},{"i":9,"n":"第九条","txt":"烟草专卖局发现所查处的案件应当由其他烟草专卖局管辖的，应当将案件移送有管辖权的烟草专卖局。 受移送的烟草专卖局对管辖权有异议的，应当报请共同的上一级烟草专卖局指定管辖，不得再自行移送。"},{"i":10,"n":"第十条","txt":"上级烟草专卖局可以直接查处下级烟草专卖局管辖的案件。 烟草专卖局认为案件有重大影响的，可以报请上一级烟草专卖局管辖。"},{"i":11,"n":"第十一条","txt":"有管辖权的烟草专卖局由于特殊原因不能或者不宜管辖的，由其上一级烟草专卖局直接管辖或者指定其他烟草专卖局管辖。"},{"i":12,"n":"第十二条","txt":"烟草专卖局因实施行政处罚的需要，可以向其他烟草专卖局或者有关机关提出协助请求，并应当出具协助函。协助事项属于被请求烟草专卖局或者有关机关职权范围内的，应当依法予以协助。需要邮政、电信、银行、交通运输管理等单位予以协助、配合的，应当按照国家有关规定办理。"},{"i":13,"n":"第十三条","txt":"烟草专卖局发现所查处的案件应当由其他行政机关管辖的，应当依法移送其他行政机关。 违法行为涉嫌犯罪的，烟草专卖局应当及时将案件移送司法机关，依法追究刑事责任，不得以行政处罚代替刑事处罚。 烟草专卖局应当加强与司法机关的协调配合，建立健全案件移送制度，加强证据材料移交、接收衔接，完善案件处理信息通报机制。"},{"i":14,"n":"第十四条","txt":"烟草专卖局实施行政处罚时，应当责令当事人改正或者限期改正违法行为。 当事人有违法所得，除依法应当退赔的外，应当予以没收。违法所得是指实施违法行为所取得的款项。"},{"i":15,"n":"第十五条","txt":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。"},{"i":16,"n":"第十六条","txt":"不满十四周岁的未成年人有违法行为的，不予行政处罚，责令监护人加以管教；已满十四周岁不满十八周岁的未成年人有违法行为的，应当从轻或者减轻行政处罚。"},{"i":17,"n":"第十七条","txt":"精神病人、智力残疾人在不能辨认或者不能控制自己行为时有违法行为的，不予行政处罚，但应当责令其监护人严加看管和治疗。间歇性精神病人在精神正常时有违法行为的，应当给予行政处罚。尚未完全丧失辨认或者控制自己行为能力的精神病人、智力残疾人有违法行为的，可以从轻或者减轻行政处罚。"},{"i":18,"n":"第十八条","txt":"当事人有下列情形之一的，应当从轻或者减轻行政处罚： （一）主动消除或者减轻违法行为危害后果的； （二）受他人胁迫或者诱骗实施违法行为的； （三）主动供述烟草专卖局尚未掌握的违法行为的； （四）配合烟草专卖局查处违法行为有立功表现的； （五）法律、法规、规章规定其他应当从轻或者减轻行政处罚的。"},{"i":19,"n":"第十九条","txt":"违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。 当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。 对当事人的违法行为依法不予行政处罚的，烟草专卖局应当对当事人进行教育。"},{"i":20,"n":"第二十条","txt":"烟草专卖局应当依法制定行政处罚裁量基准，规范行使行政处罚裁量权。行政处罚裁量基准应当向社会公布。"},{"i":21,"n":"第二十一条","txt":"烟草专卖局应当公示行政处罚的实施机关、立案依据、实施程序和救济渠道等信息。"},{"i":22,"n":"第二十二条","txt":"行政处罚应当由烟草专卖局中具有行政执法资格的执法人员实施。执法人员不得少于2人，法律另有规定的除外。 执法人员应当文明执法，尊重和保护当事人合法权益。"},{"i":23,"n":"第二十三条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当主动回避。 当事人认为执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，有权申请回避。 当事人提出回避申请的，烟草专卖局应当依法审查。执法人员的回避，由本烟草专卖局负责人决定；烟草专卖局负责人的回避，由上一级烟草专卖局决定。决定作出之前，不停止调查。"},{"i":24,"n":"第二十四条","txt":"烟草专卖局在作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利，以及行使权利的期限。"},{"i":25,"n":"第二十五条","txt":"当事人有权进行陈述、申辩。烟草专卖局必须充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，烟草专卖局应当采纳。 烟草专卖局不得因当事人陈述、申辩而给予更重的处罚。"},{"i":26,"n":"第二十六条","txt":"证据包括： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。 证据必须经查证属实，方可作为认定案件事实的根据。 以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":27,"n":"第二十七条","txt":"烟草专卖局应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。"},{"i":28,"n":"第二十八条","txt":"具有一定社会影响的行政处罚决定应当依法公开。 公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，作出行政处罚决定的烟草专卖局应当在3日内撤回行政处罚决定信息并公开说明理由。"},{"i":29,"n":"第二十九条","txt":"烟草专卖局及其工作人员对实施行政处罚过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":30,"n":"第三十条","txt":"违法事实确凿并有法定依据，对公民处以200元以下、对法人或者其他组织处以3000元以下罚款或者警告的行政处罚的，执法人员可以当场作出行政处罚决定。"},{"i":31,"n":"第三十一条","txt":"执法人员依法当场作出行政处罚决定的，应当主动向当事人出示执法证件，填写预定格式、统一编号的烟草专卖行政处罚决定书，并当场交当事人签收。当事人拒绝签收的，执法人员应当在行政处罚决定书上注明情况。 前款规定的烟草专卖行政处罚决定书应当载明当事人的基本情况、违法行为，行政处罚的种类和依据、罚款数额、缴纳方式及期限、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及烟草专卖局名称等内容，并由执法人员签名。 执法人员当场作出行政处罚决定的，应当在2日内报本烟草专卖局备案。烟草专卖局收到备案材料后，应当及时进行审核并按照规定立卷归档。发现错误的，应当及时纠正。"},{"i":32,"n":"第三十二条","txt":"除本规定第三十条规定的可以当场作出的行政处罚外，烟草专卖局发现公民、法人或者其他组织有依法应当给予行政处罚的行为的，必须全面、客观、公正地调查，收集有关证据；必要时，依照法律、法规的规定，可以进行检查。 符合立案标准的，烟草专卖局应当及时立案。"},{"i":33,"n":"第三十三条","txt":"烟草专卖局应当自发现违法线索或者收到举报、其他机关移送、上级机关交办的材料之日起7日内予以核查并决定是否立案；案情重大、复杂需要延长立案决定期限的，应当经本烟草专卖局负责人批准，并书面告知当事人。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，烟草专卖局应当立案查处： （一）经初步调查，掌握了一定的违法事实，依法应当给予行政处罚的； （二）根据举报人提供的当事人违法事实和证据，依法应当立案查处的； （三）掌握了当事人违法活动线索，且有违法嫌疑需要继续进行调查的； （四）上级烟草专卖局指定管辖的案件； （五）依法应当立案查处的其他情形。"},{"i":35,"n":"第三十五条","txt":"办理立案的，应当由承办人填写立案报告表并附办案相关材料，报本烟草专卖局负责人审核批准。烟草专卖局负责人批准的日期为立案日期。 对正在发生的违法活动，有管辖权的烟草专卖局应当立即查处，并在查处后7日内依法补办立案手续。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，烟草专卖局应当不予立案；已经立案的，应当予以撤销： （一）违法行为超过法律规定的行政处罚时限的； （二）不属于本机关管辖的； （三）违法事实不成立或者违法行为轻微依法可以不予行政处罚的； （四）法律、行政法规规定不予立案的其他情形。 不予立案或者撤销立案的，应当填写不予立案或者撤销立案报告表，报本烟草专卖局负责人批准。属于其他行政机关管辖的案件，烟草专卖局应当在7日内移送其他行政机关。"},{"i":37,"n":"第三十七条","txt":"对于举报或者其他机关移送的案件，烟草专卖局决定不予立案的，应当书面告知具名的举报人或者移送机关。 烟草专卖局应当将不予立案的情况立卷归档。"},{"i":38,"n":"第三十八条","txt":"执法人员在调查或者进行检查时，应当主动向当事人或者有关人员出示执法证件。当事人或者有关人员有权要求执法人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。 当事人或者有关人员应当如实回答询问，并协助调查或者检查，不得拒绝或者阻挠。询问或者检查应当制作笔录。"},{"i":39,"n":"第三十九条","txt":"执法人员需要从有关单位查阅、复制与违法活动有关的合同、发票、账册、单据、记录、文件、业务函电和其他材料的，应当出示县级以上烟草专卖局出具的协助函。 执法人员应当收集、调取与案件有关的原始凭证作为证据；调取原始证据确有困难的，可以将原件复印、复制、摘抄、拍照，并由原始证据持有人签名或者以其他方式确认复印件、复制件、摘抄件、照片与原件相符。"},{"i":40,"n":"第四十条","txt":"提取物证应当当场清点，出具物品清单并由执法人员、当事人签名或者以其他方式确认。当事人拒绝确认或者不在场的，应当有2名以上见证人在场确认；见证人不足2名或者拒绝确认的，执法人员应当在物品清单上注明情况并签名。"},{"i":41,"n":"第四十一条","txt":"执法人员应当收集视听资料的原始载体。收集原始载体有困难的，可以收集复制件并注明制作方法、制作时间、制作人等情况。视听资料应当附相关话语的文字记录。"},{"i":42,"n":"第四十二条","txt":"执法人员应当收集电子数据的原始载体。 收集电子数据原始载体有困难的，可以提取电子数据。执法人员提取电子数据应当制作笔录，并附电子数据清单，交电子数据持有人签名或者以其他方式确认。 依照前两款规定收集电子数据证据有困难的，可以采取打印、拍照或者录像等方式固定相关证据，并附情况说明，交电子数据持有人签名或者以其他方式确认。 持有人拒绝确认或者不在场的，应当有2名以上见证人在场确认；见证人不足2名或者拒绝确认的，执法人员应当注明情况并签名。"},{"i":43,"n":"第四十三条","txt":"执法人员询问当事人、证人应当单独进行，向其说明依法享有的权利和提供伪证或者隐匿证据的法律责任，并制作询问笔录。 询问笔录应当交被询问人核对；被询问人阅读有困难的，应当向其宣读。经核对无误后，由被询问人在笔录上逐页签名或者以其他方式确认。笔录有差错、遗漏的，应当允许被询问人更正或者补充，涂改部分应当由被询问人签名或者以其他方式确认；被询问人拒绝确认的，执法人员应当在笔录上注明情况并签名。"},{"i":44,"n":"第四十四条","txt":"需要对烟草专卖品的真伪等专门事项进行鉴定的，烟草专卖局应当委托国务院市场监督管理部门或者省、自治区、直辖市人民政府市场监督管理部门指定的烟草质量检测机构实施，并出具载明委托鉴定事项及相关材料的委托鉴定书。"},{"i":45,"n":"第四十五条","txt":"对涉嫌违法行为发生的现场进行检查时，执法人员应当制作现场笔录并交当事人签名或者以其他方式确认。当事人拒绝确认或者不在场的，应当有2名以上见证人在场确认；见证人不足2名或者拒绝确认的，执法人员应当在现场笔录上注明情况并签名。参与调查的人员不得作为见证人。"},{"i":46,"n":"第四十六条","txt":"在证据可能灭失或者以后难以取得的情况下，经本烟草专卖局负责人批准，可以依法对与涉嫌违法行为有关的证据进行先行登记保存。 烟草专卖局先行登记保存证据，应当出具先行登记保存通知书，由执法人员、当事人签名或者以其他方式确认后，分别交当事人和本烟草专卖局。当事人拒绝确认或者不在场的，应当有2名以上见证人在场确认；见证人不足2名或者拒绝确认的，执法人员应当在先行登记保存通知书上注明情况并签名。 先行登记保存期间，任何人不得销毁或者转移先行登记保存的证据。"},{"i":47,"n":"第四十七条","txt":"对于依法先行登记保存的证据，应当根据情况在7日内采取下列措施： （一）及时采取复制、拍照、录像等证据保全措施； （二）需要鉴定的，及时送交有关机构鉴定并告知当事人所需时间； （三）依法应当移送其他有关部门处理的，作出移送决定并书面告知当事人； （四）违法事实不成立，或者依法可以不予行政处罚的，决定解除先行登记保存措施并告知当事人。"},{"i":48,"n":"第四十八条","txt":"执法人员在调查过程中发现立案事由以外的涉嫌违法行为的，应当及时报请本烟草专卖局负责人决定是否对该涉嫌违法行为一并进行调查。"},{"i":49,"n":"第四十九条","txt":"调查终结的，执法人员应当提交案件处理审批表。案件处理审批表包括当事人的基本情况、经调查核实的事实和证据、对涉嫌违法行为的定性意见、处理建议及其法律依据等内容。"},{"i":50,"n":"第五十条","txt":"烟草专卖局的专卖执法机构在将案件处理审批表报送本局负责人审查决定前，应当先由本局法制工作机构或者专职法制工作人员对涉嫌违法行为的定性意见、处理建议及其法律依据进行法制审核并签署意见。未经法制审核或者审核未通过的，不得作出决定。 烟草专卖局中初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":51,"n":"第五十一条","txt":"烟草专卖局负责人应当对案件处理审批表及法制审核意见进行综合审查，依法作出是否给予行政处罚等决定。对于拟移送司法机关的案件，烟草专卖局负责人应当在3日内作出批准移送或者不批准移送的决定。"},{"i":52,"n":"第五十二条","txt":"烟草专卖局负责人应当根据案件的不同情况，分别作出下列决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，依法移送司法机关。 对情节复杂或者重大违法行为给予行政处罚，烟草专卖局负责人应当集体讨论决定。"},{"i":53,"n":"第五十三条","txt":"烟草专卖局实施行政处罚，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址等基本情况； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的烟草专卖局的名称和日期。 行政处罚决定书应当加盖作出行政处罚决定的烟草专卖局的印章。"},{"i":54,"n":"第五十四条","txt":"烟草专卖局应当自行政处罚案件立案之日起90日内作出行政处罚决定。90日内不能作出的，经本烟草专卖局负责人批准，可以延长30日。案情重大、复杂或者有其他特殊情况，经延期仍不能作出决定的，应当由上一级烟草专卖局决定是否继续延期，决定继续延期的，应当同时确定延长的合理期限。决定延期的，应当将延长的期限及理由书面告知当事人。 案件处理过程中，听证、鉴定、公告等时间不计入前款规定的期限。 根据本规定第四十八条决定一并调查的，经本烟草专卖局负责人批准，可以重新计算行政处罚决定作出期限。"},{"i":55,"n":"第五十五条","txt":"烟草专卖行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，烟草专卖局应当在7日内依照《中华人民共和国民事诉讼法》和本规定，将行政处罚决定书送达当事人： （一）直接送达当事人的，由当事人或者其同住成年家属在送达回证上注明收到日期并签名、盖章或者以其他方式确认。当事人或者其同住成年家属在送达回证上注明的签收日期为送达日期； （二）直接送达时，受送达人或者其同住成年家属拒绝接收送达文书的，依法适用留置送达； （三）直接送达有困难的，可以委托当地烟草专卖局代为送达，或者通过邮寄方式送达。邮寄送达的，以回执上注明的收件日期为送达日期； （四）受送达人下落不明或者采取本条规定的其他方式无法送达的，可以公告送达。烟草专卖局应当在其所在地公开发行的报纸上予以公告，也可以同时在受送达人原住所地或者烟草专卖局的公告栏张贴公告。烟草专卖局设有向社会公众开放的网站的，可以同时在网站上公告。公告送达的，"},{"i":56,"n":"第五十六条","txt":"烟草专卖局及其执法人员在作出行政处罚决定之前，未依法向当事人告知拟作出的行政处罚内容及事实、理由、依据，或者拒绝听取当事人的陈述、申辩，不得作出行政处罚决定；当事人明确放弃陈述或者申辩权利的除外。"},{"i":57,"n":"第五十七条","txt":"烟草专卖局拟作出下列行政处罚决定，应当告知当事人有要求听证的权利，当事人要求听证的，烟草专卖局应当组织听证： （一）1万元以上的罚款； （二）没收较大数额的违法所得或者违法烟草专卖品； （三）取消从事烟草专卖业务的资格、吊销许可证； （四）责令停产停业、责令关闭； （五）其他较重的行政处罚；　　 （六）法律、法规、规章规定的其他情形。 省级烟草专卖局可以结合本地实际，调整和确定本行政区域内罚款、没收违法所得或者违法烟草专卖品的听证数额标准，报国家烟草专卖局批准后施行。"},{"i":58,"n":"第五十八条","txt":"烟草专卖局不得因当事人要求听证而给予更重的处罚。 当事人不承担烟草专卖局组织听证的费用。"},{"i":59,"n":"第五十九条","txt":"当事人要求举行听证的，应当在烟草专卖局告知权利后5日内提出申请。 当事人可以通过书面或者口头方式提出听证申请。口头申请的，烟草专卖局应当当场记录申请人的基本情况、申请听证的主要理由以及申请时间等内容，并由当事人签名或者以其他方式确认。"},{"i":60,"n":"第六十条","txt":"听证应当公开举行，允许公众旁听，但涉及国家秘密、商业秘密或者个人隐私依法予以保密的除外。"},{"i":61,"n":"第六十一条","txt":"烟草专卖局决定组织听证的，应当自收到听证申请之日起20日内举行听证，并在举行听证7日前，将听证时间、听证地点书面通知当事人及有关人员并同时报告上一级烟草专卖局。"},{"i":62,"n":"第六十二条","txt":"当事人可以亲自参加听证，也可以委托1至2人代理。"},{"i":63,"n":"第六十三条","txt":"听证主持人由烟草专卖局指定。听证主持人应当符合下列条件： （一）非调查本案的执法人员； （二）非本规定第二十三条规定应当回避的人员。 主持人不符合前款规定条件的，应当主动回避。当事人或者其代理人认为主持人与本案有直接利害关系的，有权申请其回避。"},{"i":64,"n":"第六十四条","txt":"当事人及其代理人无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，烟草专卖局终止听证。"},{"i":65,"n":"第六十五条","txt":"听证按照下列程序进行： （一）主持人核对到场的当事人或者其代理人及其他参加听证人员的身份，说明案由，告知当事人或者其代理人的权利、义务，宣布听证纪律，询问当事人或者其代理人是否申请主持人回避，宣布听证开始； （二）由执法人员指出当事人违法的事实，出示有关证据，提出处罚建议和依据； （三）当事人或者其代理人进行陈述和申辩； （四）有第三人的，由第三人或者其代理人进行陈述和申辩； （五）执法人员与当事人或者其代理人相互辩论、质证； （六）当事人或者其代理人进行最后陈述、申辩； （七）有第三人的，由第三人或者其代理人进行最后陈述； （八）执法人员进行最后陈述； （九）主持人宣布听证结束。 听证应当制作笔录并由主持人、记录人签名。听证笔录交当事人或者其代理人核对无误后签字或者以其他方式确认；当事人或者其代理人拒绝确认的，主持人应当注明情况并签名。"},{"i":66,"n":"第六十六条","txt":"听证结束后，烟草专卖局应当根据听证笔录，依照本规定第五十二条的规定，作出决定。"},{"i":67,"n":"第六十七条","txt":"行政处罚决定作出后，当事人应当在行政处罚决定书载明的期限内全面履行。 到期不缴纳罚款的，烟草专卖局可以每日按照罚款数额的3%加处罚款，加处罚款的数额不得超出罚款的数额。  当事人确有经济困难，需要延期或者分期缴纳罚款的，经当事人申请和烟草专卖局批准，可以暂缓或者分期缴纳。"},{"i":68,"n":"第六十八条","txt":"依法取消公民、法人或者其他组织从事烟草专卖业务资格的，原发证机关应当及时收回烟草专卖许可证并依法办理烟草专卖许可注销手续；因客观原因无法收回的，原发证机关应当注明情况，依法注销烟草专卖许可并向社会公告。"},{"i":69,"n":"第六十九条","txt":"当事人对烟草专卖局作出的行政处罚决定不服的，可以自接到行政处罚决定书之日起60日内，向其上一级烟草专卖局申请复议；当事人也可以自接到行政处罚决定书之日起15日内直接向人民法院提起行政诉讼。 行政复议或者行政诉讼期间，除法律另有规定外，不停止烟草专卖行政处罚决定的执行。 当事人申请行政复议或者提起行政诉讼的，加处罚款的数额在行政复议或者行政诉讼期间不予计算。"},{"i":70,"n":"第七十条","txt":"当事人逾期既不申请行政复议，也不向人民法院提起行政诉讼，又不履行行政处罚决定的，作出行政处罚决定的烟草专卖局可以依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。"},{"i":71,"n":"第七十一条","txt":"当事人逾期既不对复议机关维持行政处罚的行政复议决定提起行政诉讼，又不履行行政复议决定的，由最初作出行政处罚的烟草专卖局依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。"},{"i":72,"n":"第七十二条","txt":"当事人逾期既不对复议机关变更行政处罚的行政复议决定提起行政诉讼，又不履行行政复议决定的，由复议机关依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。"},{"i":73,"n":"第七十三条","txt":"对于依法查获的烟草专卖品，自烟草专卖局采取张贴通告、发布公告等措施之日起60日内无法找到当事人的，经本烟草专卖局负责人批准，可以采取变卖等处理措施，变卖款上缴国库。"},{"i":74,"n":"第七十四条","txt":"依法查获的霉坏变质的烟草制品不得上市流通。烟草专卖局采取销毁等处理措施的，应当符合国家有关规定，并经上一级烟草专卖局批准。"},{"i":75,"n":"第七十五条","txt":"除依照《中华人民共和国行政处罚法》第六十八条、第六十九条的规定当场收缴的罚款外，作出行政处罚决定的烟草专卖局及其执法人员不得自行收缴罚款。 罚款、变卖款、没收的违法所得应当全部上缴国库，任何单位和个人不得截留、私分或者变相私分。"},{"i":76,"n":"第七十六条","txt":"上级烟草专卖局的法制工作机构或者专职法制工作人员应当定期对下级烟草专卖局办理的行政处罚案件进行案卷评查。对评查中发现的问题，应当及时指出。"},{"i":77,"n":"第七十七条","txt":"上级烟草专卖局有权对下级烟草专卖局依照本规定作出的行政处理决定重新进行审查。 上级烟草专卖局发现下级烟草专卖局的行政处理决定确有错误的，有权变更、撤销该决定，或者责令下级烟草专卖局重新作出处理决定。"},{"i":78,"n":"第七十八条","txt":"对于上级烟草专卖局作出的纠正决定，下级烟草专卖局应当遵照执行并及时上报执行情况。"},{"i":79,"n":"第七十九条","txt":"烟草专卖局的法制工作机构或者专职法制工作人员可以对本局专卖执法机构办理行政处罚案件的合法性进行监督。"},{"i":80,"n":"第八十条","txt":"烟草专卖局应当建立健全对行政处罚的监督制度。上级烟草专卖局的法制工作机构应当定期对下级烟草专卖局组织开展行政执法评议、考核，加强对行政处罚的监督检查，规范和保障行政处罚的实施。 烟草专卖局实施行政处罚应当接受社会监督。公民、法人或者其他组织对烟草专卖局实施行政处罚的行为，有权申诉或者检举；烟草专卖局应当认真审查，发现有错误的，应当主动改正。"},{"i":81,"n":"第八十一条","txt":"烟草专卖局实施行政处罚，有下列情形之一的，由上级烟草专卖局责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）没有法定的行政处罚依据的； （二）擅自变更行政处罚种类、幅度的； （三）违反法定的行政处罚程序的； （四）违法委托其他单位或者个人实施行政处罚的； （五）执法人员未取得执法证件的。 烟草专卖局对符合立案标准的案件不及时立案的，依照前款规定予以处理。"},{"i":82,"n":"第八十二条","txt":"烟草专卖局违反本规定自行收缴罚款的，由上级烟草专卖局责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":83,"n":"第八十三条","txt":"烟草专卖局截留、私分或者变相私分罚款、变卖款、没收的违法所得或者烟草专卖品的，由财政部门或者有关机关予以追缴，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。 执法人员利用职务上的便利，索取或者收受他人财物、将收缴的罚款据为己有，构成犯罪的，依法追究刑事责任；情节轻微不构成犯罪的，依法给予处分。"},{"i":84,"n":"第八十四条","txt":"烟草专卖局违法实施检查等执法措施，给公民人身或者财产造成损害、给法人或者其他组织造成损失的，应当依法予以赔偿；对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"烟草专卖局对应当依法移送司法机关追究刑事责任的案件不移送，以行政处罚代替刑事处罚的，由上级烟草专卖局责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":86,"n":"第八十六条","txt":"烟草专卖局对应当予以制止和处罚的违法行为不予制止、处罚，致使公民、法人或者其他组织的合法权益、公共利益和社会秩序遭受损害的，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":87,"n":"第八十七条","txt":"外国人、无国籍人、外国组织在中华人民共和国领域内有违反烟草专卖管理秩序的违法行为，应当给予行政处罚的，适用本规定。"},{"i":88,"n":"第八十八条","txt":"本规定中“2日”“3日”“5日”“7日”的规定是指工作日，不含法定节假日。 本规定中的期间开始之日不计算在内。期间不包括在途时间。期间届满的最后一日为法定节假日的，以法定节假日后的第一日为期间届满的日期。"},{"i":89,"n":"第八十九条","txt":"本规定中的“以上”“以下”“内”“前”均包括本数或者本级。"},{"i":90,"n":"第九十条","txt":"烟草专卖局应当建立健全行政处罚案件档案管理制度，依法及时制作、收集、整理并妥善保存有关涉案材料。移交、借阅、调用涉案材料应当按照档案管理要求办理相应的手续。"},{"i":91,"n":"第九十一条","txt":"烟草专卖局对涉及电子烟等新型烟草制品的违法行为实施行政处罚的，适用本规定。"},{"i":92,"n":"第九十二条","txt":"本规定由工业和信息化部、国家烟草专卖局负责解释。"},{"i":93,"n":"第九十三条","txt":"本规定自2023年7月20日起施行。2010年1月21日公布的《烟草专卖行政处罚程序规定》（工业和信息化部令第12号）同时废止。"}],"yancaozhuanmaixukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范烟草专卖许可证管理，保护公民、法人和其他组织的合法权益，根据《中华人民共和国烟草专卖法》、《中华人民共和国行政许可法》、《中华人民共和国烟草专卖法实施条例》及相关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内烟草专卖许可证的管理。"},{"i":3,"n":"第三条","txt":"烟草专卖局应当依照法定的权限、范围、条件和程序审批、发放烟草专卖许可证，并进行有效的监督管理。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对烟草专卖局发放的烟草专卖许可证，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼。其合法权益因烟草专卖局违法发放烟草专卖许可证受到损害的，有权依法要求赔偿。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织依法取得的烟草专卖许可证受法律保护。 烟草专卖许可证所依据的法律、法规、规章修改、废止，或者办理烟草专卖许可证所依据的客观情况发生重大变化的，为了公共利益的需要，烟草专卖局可以依法变更或者撤回已经生效的烟草专卖许可证。"},{"i":6,"n":"第六条","txt":"本办法所称的烟草专卖许可证，包括烟草专卖生产企业许可证、烟草专卖批发企业许可证、烟草专卖零售许可证三类。"},{"i":7,"n":"第七条","txt":"烟草专卖局依法审批发放和管理烟草专卖许可证。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织从事烟草专卖品的生产、批发、零售、进出口等业务的，应当依法向烟草专卖局申请领取烟草专卖许可证。 法人所属的不具备法人资格的单位单独领取烟草专卖生产企业许可证或者烟草专卖批发企业许可证的，其所属法人单位应当向相关的烟草专卖局提出申请，并提交有关申请材料。"},{"i":9,"n":"第九条","txt":"申请人一般以书面方式提出申请，也可以通过信函、电报、传真、电子数据交换和电子邮件等方式提出申请，并按烟草专卖局要求填报格式文本。 申请人可以委托代理人提出申请。委托代理人提出申请的，应当提供委托人的授权委托书及代理人的身份证明。"},{"i":10,"n":"第十条","txt":"烟草专卖局应当根据申请人申请的不同事项确定申请类型，并要求提供相应的申请材料。 烟草专卖许可证申请类型包括新办申请、延续申请、变更申请、停业申请、恢复营业申请、歇业申请等。"},{"i":11,"n":"第十一条","txt":"申请烟草专卖生产企业许可证，应当具备下列条件： （一）有与生产烟草专卖品相适应的资金； （二）有生产烟草专卖品所需要的技术、设备条件； （三）符合国家烟草行业的产业政策要求及企业组织结构调整的需要； （四）国家烟草专卖局规定的其他条件。"},{"i":12,"n":"第十二条","txt":"申请烟草专卖批发企业许可证，应当具备下列条件： （一）有与经营烟草制品批发业务相适应的资金； （二）有固定的经营场所和必要的专业人员； （三）符合烟草专卖批发企业合理布局的要求； （四）国家烟草专卖局规定的其他条件。"},{"i":13,"n":"第十三条","txt":"申请烟草专卖零售许可证，应当具备下列条件： （一）有与经营烟草制品零售业务相适应的资金； （二）有与住所相独立的固定经营场所； （三）符合当地烟草制品零售点合理布局的要求； （四）国家烟草专卖局规定的其他条件。"},{"i":14,"n":"第十四条","txt":"本办法第十一条、第十二条、第十三条所规定的国家烟草专卖局规定的其他条件，在实施前应当公布。"},{"i":15,"n":"第十五条","txt":"制订烟草制品零售点合理布局规划时，应当根据辖区内的人口数量、交通状况、经济发展水平、消费能力等因素，在举行听证后确定零售点的合理布局。 烟草制品零售点合理布局规划、经营资金要求和经营场所条件，由县级以上烟草专卖局制定，并报上一级烟草专卖局备案。"},{"i":16,"n":"第十六条","txt":"连锁经营企业在申请烟草专卖零售许可证时，应当由各个分店分别向所在地烟草专卖局提出申请。"},{"i":17,"n":"第十七条","txt":"外商投资的商业企业或者个体工商户不得从事烟草专卖品批发或者零售业务，不得以特许、吸纳加盟店及其他再投资等形式变相从事烟草专卖品经营业务。"},{"i":18,"n":"第十八条","txt":"烟草专卖局应当将办理烟草专卖许可证的条件、要求、程序、时限等需公示的内容通过公示栏、电子查询系统或者互联网等方式予以公示。"},{"i":19,"n":"第十九条","txt":"办理烟草专卖许可证的场所应当公示下列内容： （一）烟草专卖许可证名称； （二）办理烟草专卖许可证所依据的法律、法规、规章； （三）各类烟草专卖许可证的审批机关； （四）申请烟草专卖许可证的条件； （五）申请人需要提交的全部材料目录； （六）烟草专卖许可证申请的方式、途径； （七）烟草专卖许可证审批程序、时限； （八）办理烟草专卖许可证的办公场所准确地址、联系方式； （九）其他需要公示的内容。"},{"i":20,"n":"第二十条","txt":"申请人要求烟草专卖局对公示内容予以说明、解释的，烟草专卖局应当予以说明、解释，提供准确、可靠的信息。"},{"i":21,"n":"第二十一条","txt":"烟草专卖局对申请人提出的申请，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得烟草专卖许可证的，应当即时告知申请人不受理； （二）申请事项不属于本烟草专卖局法定职权范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； （三）申请材料存在可以当场更正的错误的，应当允许申请人当场更正； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五日内以书面形式一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于本烟草专卖局法定职权范围，申请材料齐全、符合法定形式，或者申请人按照烟草专卖局的要求提交全部补正申请材料的，烟草专卖局应当受理烟草专卖许可证申请。"},{"i":22,"n":"第二十二条","txt":"烟草专卖局受理或者不予受理烟草专卖许可证申请，应当向申请人出具加盖专用印章和注明日期的书面凭证。"},{"i":23,"n":"第二十三条","txt":"经审查，申请人的申请符合法定条件的，烟草专卖局应当自受理申请之日起二十日内作出许可书面决定。二十日内不能作出决定的，经本单位负责人批准，可以延长十日，并应当将延长期限理由告知申请人。但法律、法规另有规定的，依照其规定。 烟草专卖局应当自作出予以发放烟草专卖许可证决定之日起十日内向申请人送达烟草专卖许可证。"},{"i":24,"n":"第二十四条","txt":"依法作出不予发放烟草专卖许可证的书面决定的，应当向申请人说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，不予发放烟草专卖零售许可证： （一）经营场所基于安全因素不适宜经营卷烟的； （二）中、小学校周围； （三）取消从事烟草专卖业务资格不满三年的； （四）因申请人隐瞒有关情况或者提供虚假材料，烟草专卖局作出不予受理或者不予发证决定后，申请人一年内再次提出申请的； （五）因申请人以欺骗、贿赂等不正当手段取得的烟草专卖许可证被撤销后，申请人三年内再次提出申请的； （六）未领取烟草专卖零售许可证经营烟草专卖品业务，并且一年内被执法机关处罚两次以上，在三年内申请领取烟草专卖零售许可证的； （七）国家烟草专卖局规定的其他不予发证的情形。"},{"i":26,"n":"第二十六条","txt":"烟草专卖局依法作出发放烟草专卖许可证的情况应当公开，允许和方便公众查阅。"},{"i":27,"n":"第二十七条","txt":"烟草专卖许可证的有效期限最长为五年，自发证之日起计算。"},{"i":28,"n":"第二十八条","txt":"取得烟草专卖许可证的，应当按照烟草专卖许可证的许可范围和有效期限依法生产和经营烟草专卖品。"},{"i":29,"n":"第二十九条","txt":"取得烟草专卖零售许可证的公民、法人或者其他组织，可以依法从事国产或者外国卷烟的零售业务，并在烟草专卖零售许可证标明的当地烟草批发企业进货。"},{"i":30,"n":"第三十条","txt":"烟草专卖许可证的持证人应当将取得的烟草专卖许可证正本摆放在经营场所的显著位置。"},{"i":31,"n":"第三十一条","txt":"烟草专卖许可证的持证人改变经营地址（因道路规划、城市建设等客观原因除外）或者具有国家烟草专卖局规定的其他情形的，应当重新申领烟草专卖许可证；所持有的烟草专卖许可证其他登记事项发生改变的，应当及时变更烟草专卖许可证。"},{"i":32,"n":"第三十二条","txt":"烟草专卖许可证有效期届满需要继续生产经营的，应当在该烟草专卖许可证有效期届满三十日前向原发证机关提出延续申请。"},{"i":33,"n":"第三十三条","txt":"烟草专卖许可证有效期届满需要继续生产经营的，因生产经营能力、条件发生重大变化导致不符合法定条件的或者有严重违法行为的，不予延续。"},{"i":34,"n":"第三十四条","txt":"烟草专卖许可证发证机关有权对辖区内取得烟草专卖许可证的公民、法人或者其他组织的生产经营活动进行监督检查，也可以授权或者委托下级烟草专卖局进行监督检查。"},{"i":35,"n":"第三十五条","txt":"上级烟草专卖局应当加强对下级烟草专卖局办理烟草专卖许可证的监督检查，及时纠正违法行为，并建立完善烟草专卖行政执法责任追究制度和考评机制。"},{"i":36,"n":"第三十六条","txt":"监督检查可以采取书面检查、现场检查或者书面检查与现场检查相结合的方式。 烟草专卖局可以依法对持证人生产经营的烟草专卖品进行抽样检查、检验、检测，对其生产经营场所（包括仓储场所）进行实地检查。检查时，可以查阅或者要求持证人提供有关情况和报送有关材料，持证人应当如实提供有关情况和材料。"},{"i":37,"n":"第三十七条","txt":"监督检查的主要内容有： （一）遵守烟草专卖法律、法规、规章的情况； （二）名称或者字号、法定代表人（负责人）、经营地址、经营方式、经营范围、经营期限等重要事项，是否与烟草专卖许可证登记事项相符合； （三）烟草专卖许可证变更、注销、延续等手续的执行和办理情况； （四）国家烟草专卖局规定需要检查的其他事项。"},{"i":38,"n":"第三十八条","txt":"烟草专卖局依法对烟草专卖许可证持证人的生产经营活动进行监督检查时，应当有两名以上烟草专卖执法人员进行，并将监督检查的情况和处理结果予以记录，由监督检查人员签字后归档。公众可以查阅烟草专卖局的监督检查记录。"},{"i":39,"n":"第三十九条","txt":"取得烟草专卖许可证的公民、法人或者其他组织，应当按照有关法律、法规、规章及本办法的规定接受烟草专卖局的监督检查。"},{"i":40,"n":"第四十条","txt":"公民、法人或者其他组织不得利用自动售货机销售烟草制品。 除了取得烟草专卖生产企业许可证或者烟草专卖批发企业许可证的企业依法销售烟草专卖品外，任何公民、法人或者其他组织不得通过信息网络销售烟草专卖品。"},{"i":41,"n":"第四十一条","txt":"任何企业或者个人不得涂改、伪造、变造烟草专卖许可证。不得买卖、出租、出借或者以其他形式非法转让烟草专卖许可证。"},{"i":42,"n":"第四十二条","txt":"登记事项发生改变，取得烟草专卖许可证的公民、法人或者其他组织不依法进行变更登记的，烟草专卖局应当责令其依法进行变更登记。"},{"i":43,"n":"第四十三条","txt":"公民、法人或者其他组织未领取烟草专卖许可证擅自从事烟草专卖品生产经营活动的，烟草专卖局应当依法查处。构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一的，发证机关可以责令持证人暂停烟草专卖业务、进行整顿，直至依法取消其从事烟草专卖业务的资格： （一）经检查不符合烟草专卖法、烟草专卖法实施条例及本办法规定条件的； （二）买卖、出租、出借或者以其他形式非法转让烟草专卖许可证的； （三）因违法生产经营烟草专卖品一年内被烟草专卖局或者其他执法机关处罚两次以上的； （四）被烟草专卖局或者其他执法机关一次性查获假烟、走私烟50条以上的； （五）因非法生产经营烟草专卖品被追究刑事责任的； （六）不执行烟草专卖局行政处罚决定的； （七）被工商行政管理部门吊销营业执照的； （八）持有烟草专卖批发企业许可证的企业，擅自将烟叶、卷烟纸、滤嘴棒、烟用丝束、烟草专用机械出售给无烟草专卖生产企业许可证、烟草专卖批发企业许可证企业的； （九）登记事项发生改变，拒绝变更登记的； （十）法律、法规、规章规定的其他情形。"},{"i":45,"n":"第四十五条","txt":"烟草专卖许可证的发证机关或者其上级烟草专卖局发现有下列情形之一的，可以根据利害关系人的请求或者依职权撤销烟草专卖许可证，收回烟草专卖许可证： （一）滥用职权、玩忽职守审批发放烟草专卖许可证的； （二）超越职权审批发放烟草专卖许可证的； （三）违反法定程序审批发放烟草专卖许可证的； （四）对不具备申请资格或者不符合烟草专卖许可证申领条件的申请人审批发证的； （五）依法可以撤销烟草专卖许可证的其他情形。"},{"i":46,"n":"第四十六条","txt":"公民、法人或者其他组织以欺骗、贿赂等不正当手段取得烟草专卖许可证的，烟草专卖局应当予以撤销并收回烟草专卖许可证。"},{"i":47,"n":"第四十七条","txt":"烟草专卖品生产经营企业法人资格发生变更，需要收回烟草专卖许可证的，发证机关应当及时收回。"},{"i":48,"n":"第四十八条","txt":"有下列情形之一的，发证机关应当依法注销烟草专卖许可证： （一）烟草专卖许可证有效期限届满未延续的； （二）烟草专卖许可证核定的经营主体为自然人，自然人死亡或者丧失民事行为能力的； （三）烟草专卖许可证核定的经营主体为法人或者其他组织依法终止的； （四）因不可抗力导致经营主体无法继续从事烟草专卖品生产经营业务的； （五）法律、法规规定的应当注销烟草专卖许可证的其他情形。"},{"i":49,"n":"第四十九条","txt":"取得烟草专卖许可证的公民、法人或者其他组织需要停业的，应当在停业前七日内向发证机关提出停业申请，停业期限最长不得超过一年。停业期满或者提前恢复营业的，持证人应当向发证机关提出恢复营业的申请。"},{"i":50,"n":"第五十条","txt":"取得烟草专卖许可证的公民、法人或者其他组织停止经营业务六个月以上不办理停业手续的，经发证机关公告一个月后仍未办理手续的，由发证机关收回烟草专卖许可证。"},{"i":51,"n":"第五十一条","txt":"取得烟草专卖许可证的公民、法人或者其他组织在领取烟草专卖许可证后满六个月尚未开展生产经营活动的，视同歇业。烟草专卖局应当收回其烟草专卖许可证。"},{"i":52,"n":"第五十二条","txt":"取得烟草专卖生产企业许可证的企业，不得为无烟草专卖许可证的企业或者个人提供烟草专卖品加工服务。"},{"i":53,"n":"第五十三条","txt":"取得烟草专卖许可证的企业，不得向无烟草专卖许可证的企业或者个人提供残次烟叶或者废弃的烟叶、烟末。不能回收利用的残次烟叶或者废弃的烟叶、烟末，应当予以销毁。"},{"i":54,"n":"第五十四条","txt":"因申请人隐瞒有关情况或者提供虚假材料的，应当不予受理或者不予发证，给予警告；申请人在一年内不得再次申请烟草专卖许可证。"},{"i":55,"n":"第五十五条","txt":"因申请人以欺骗、贿赂等不正当手段取得的烟草专卖许可证被撤销的，申请人三年内不得再次提出申请。"},{"i":56,"n":"第五十六条","txt":"使用涂改、伪造、变造的烟草专卖许可证的，由烟草专卖局处以1000元以下的罚款。"},{"i":57,"n":"第五十七条","txt":"违反本办法规定，不及时办理烟草专卖许可证变更、注销手续的，由烟草专卖局责令改正，拒不改正的，处以1000元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"烟草专卖局及其工作人员违反本办法的规定，有下列情形之一的，由其上级烟草专卖局责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分： （一）对符合法定条件的申请不予受理的； （二）不在办公场所公示依法应当公示的材料的； （三）在受理、审查、发放烟草专卖许可证过程中，未向申请人、利害关系人履行法定告知义务的； （四）申请人提交的申请材料不齐全、不符合法定形式，不一次告知申请人必须补正全部内容的； （五）未依法说明不受理申请或者不发证理由的。"},{"i":59,"n":"第五十九条","txt":"烟草专卖局工作人员办理烟草专卖许可证或者依法进行监督检查时，索取、收受他人财物或者谋取其他利益的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"烟草专卖局发放烟草专卖许可证，有下列情形之一的，由其上级烟草专卖局责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人发放烟草专卖许可证或者超越法定职权发放烟草专卖许可证的； （二）对符合法定条件的申请人不予发放烟草专卖许可证或者不在法定期限内发放烟草专卖许可证的。"},{"i":61,"n":"第六十一条","txt":"烟草专卖许可证的证件式样，由国家烟草专卖局统一规定。"},{"i":62,"n":"第六十二条","txt":"本办法所称外商投资商业企业，包括中外合资企业、中外合作企业、外商独资企业、港澳台地区投资企业等。"},{"i":63,"n":"第六十三条","txt":"持有烟草专卖零售许可证的国有企业，按照国家关于发展混合所有制经济的要求，经国家有关部门批准为国有控股的混合所有制企业的，可以重新申领烟草专卖零售许可证。"},{"i":64,"n":"第六十四条","txt":"本办法规定的期限以工作日计算，遇到法定节假日的，工作日顺延。"},{"i":65,"n":"第六十五条","txt":"本办法由国家烟草专卖局负责解释。"},{"i":66,"n":"第六十六条","txt":"本办法自2016年7月20日起施行。本办法施行前颁布的有关规定与本办法不一致的，按照本办法执行。"}],"dianxinyewujingyingxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强电信业务经营许可管理，根据《中华人民共和国电信条例》及其他法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请、审批、使用和管理电信业务经营许可证（以下简称经营许可证），适用本办法。"},{"i":3,"n":"第三条","txt":"工业和信息化部和省、自治区、直辖市通信管理局（以下统称电信管理机构）是经营许可证的审批管理机构。 经营许可证审批管理应当遵循便民、高效、公开、公平、公正的原则。 工业和信息化部建立电信业务综合管理平台（以下简称管理平台），推进经营许可证的网上申请、审批和管理及相关信息公示、查询、共享，完善信用管理机制。"},{"i":4,"n":"第四条","txt":"经营电信业务，应当依法取得电信管理机构颁发的经营许可证。 电信业务经营者在电信业务经营活动中，应当遵守经营许可证的规定，接受、配合电信管理机构的监督管理。 电信业务经营者按照经营许可证的规定经营电信业务受法律保护。"},{"i":5,"n":"第五条","txt":"经营基础电信业务，应当具备下列条件： （一）经营者为依法设立的专门从事基础电信业务的公司，并且公司的国有股权或者股份不少于51%； （二）有业务发展研究报告和组网技术方案； （三）有与从事经营活动相适应的资金和专业人员； （四）有从事经营活动的场地、设施及相应的资源； （五）有为用户提供长期服务的信誉或者能力； （六）在省、自治区、直辖市范围内经营的，注册资本最低限额为1亿元人民币；在全国或者跨省、自治区、直辖市范围经营的，注册资本最低限额为10亿元人民币； （七）公司及其主要投资者和主要经营管理人员未被列入电信业务经营失信名单； （八）国家规定的其他条件。"},{"i":6,"n":"第六条","txt":"经营增值电信业务，应当具备下列条件： （一）经营者为依法设立的公司； （二）有与开展经营活动相适应的资金和专业人员； （三）有为用户提供长期服务的信誉或者能力； （四）在省、自治区、直辖市范围内经营的，注册资本最低限额为100万元人民币；在全国或者跨省、自治区、直辖市范围经营的，注册资本最低限额为1000万元人民币； （五）有必要的场地、设施及技术方案； （六）公司及其主要投资者和主要经营管理人员未被列入电信业务经营失信名单； （七）国家规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请办理基础电信业务经营许可证的，应当向工业和信息化部提交下列申请材料： （一）公司法定代表人签署的经营基础电信业务的书面申请，内容包括：申请经营电信业务的种类、业务覆盖范围、公司名称和联系方式等； （二）公司营业执照副本及复印件； （三）公司概况，包括公司基本情况，拟从事电信业务的机构设置和管理情况、技术力量和经营管理人员情况，与从事经营活动相适应的场地、设施等情况； （四）公司章程、公司股权结构及股东的有关情况； （五）业务发展研究报告，包括：经营电信业务的业务发展和实施计划、服务项目、业务覆盖范围、收费方案、预期服务质量、效益分析等； （六）组网技术方案，包括：网络结构、网络规模、网络建设计划、网络互联方案、技术标准、电信设备的配置、电信资源使用方案等； （七）为用户提供长期服务和质量保障的措施； （八）网络与信息安全保障措施； （九）证明公司信誉的有关材料； （十）公司法定代表"},{"i":8,"n":"第八条","txt":"申请办理增值电信业务经营许可证的，应当向电信管理机构提交下列申请材料： （一）公司法定代表人签署的经营增值电信业务的书面申请，内容包括：申请经营电信业务的种类、业务覆盖范围、公司名称和联系方式等； （二）公司营业执照副本及复印件； （三）公司概况，包括：公司基本情况，拟从事电信业务的人员、场地和设施等情况； （四）公司章程、公司股权结构及股东的有关情况； （五）经营电信业务的业务发展和实施计划及技术方案； （六）为用户提供长期服务和质量保障的措施； （七）网络与信息安全保障措施； （八）证明公司信誉的有关材料； （九）公司法定代表人签署的公司依法经营电信业务的承诺书。 申请经营的电信业务依照法律、行政法规及国家有关规定须经有关主管部门事先审核同意的，应当提交有关主管部门审核同意的文件。"},{"i":9,"n":"第九条","txt":"经营许可证分为《基础电信业务经营许可证》和《增值电信业务经营许可证》两类。其中，《增值电信业务经营许可证》分为《跨地区增值电信业务经营许可证》和省、自治区、直辖市范围内的《增值电信业务经营许可证》。 《基础电信业务经营许可证》和《跨地区增值电信业务经营许可证》由工业和信息化部审批。省、自治区、直辖市范围内的《增值电信业务经营许可证》由省、自治区、直辖市通信管理局审批。 外商投资电信企业的经营许可证，由工业和信息化部根据《外商投资电信企业管理规定》审批。"},{"i":10,"n":"第十条","txt":"工业和信息化部应当对申请经营基础电信业务的申请材料进行审查。申请材料齐全、符合法定形式的，应当向申请人出具受理申请通知书。申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部内容。 工业和信息化部受理申请之后，应当组织专家对第七条第五项、第六项、第八项申请材料进行评审，形成评审意见。 工业和信息化部应当自受理申请之日起180日内审查完毕，作出批准或者不予批准的决定。予以批准的，颁发《基础电信业务经营许可证》。不予批准的，应当书面通知申请人并说明理由。"},{"i":11,"n":"第十一条","txt":"电信管理机构应当对申请经营增值电信业务的申请材料进行审查。申请材料齐全、符合法定形式的，应当向申请人出具受理申请通知书。申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部内容。 电信管理机构根据管理需要，可以组织专家对第八条第五项、第六项和第七项申请材料进行评审，形成评审意见。 电信管理机构应当自收到全部申请材料之日起60日内审查完毕，作出批准或者不予批准的决定。予以批准的，颁发《跨地区增值电信业务经营许可证》或者省、自治区、直辖市范围内的《增值电信业务经营许可证》。不予批准的，应当书面通知申请人并说明理由。"},{"i":12,"n":"第十二条","txt":"电信管理机构需要对申请材料实质内容进行核实的，可以自行或者委托其他机构对申请人实地查验，申请人应当配合。 电信管理机构组织专家评审的，专家评审时间不计算在本办法第十条第三款和第十一条第三款规定的审查期限内。"},{"i":13,"n":"第十三条","txt":"经营许可证由正文和附件组成。 经营许可证正文应当载明公司名称、法定代表人、业务种类（服务项目）、业务覆盖范围、有效期限、发证机关、发证日期、经营许可证编号等内容。 经营许可证附件可以规定特别事项，由电信管理机构对电信业务经营行为、电信业务经营者权利义务等作出特别要求。 经营许可证应当加盖发证机关印章。 工业和信息化部可以根据实际情况，调整经营许可证的内容，重新公布。"},{"i":14,"n":"第十四条","txt":"《基础电信业务经营许可证》的有效期，根据电信业务种类分为5年、10年。 《跨地区增值电信业务经营许可证》和省、自治区、直辖市范围内的《增值电信业务经营许可证》的有效期为5年。"},{"i":15,"n":"第十五条","txt":"经营许可证由公司法定代表人领取，或者由其委托的公司其他人员凭委托书领取。"},{"i":16,"n":"第十六条","txt":"电信业务经营者应当按照经营许可证所载明的电信业务种类，在规定的业务覆盖范围内，按照经营许可证的规定经营电信业务。 电信业务经营者应当在公司主要经营场所、网站主页、业务宣传材料等显著位置标明其经营许可证编号。"},{"i":17,"n":"第十七条","txt":"获准经营无线电通信业务的，应当按照国家无线电管理相关规定，持经营许可证向无线电管理机构申请取得无线电频率使用许可。"},{"i":18,"n":"第十八条","txt":"电信业务经营者经发证机关批准，可以授权其持股比例（包括直接持有和间接持有）不少于51%并符合经营电信业务条件的公司经营其获准经营的电信业务。发证机关应当在电信业务经营者的经营许可证中载明该被授权公司的名称、法定代表人、业务种类、业务覆盖范围等内容。 获准跨地区经营基础电信业务的公司在一个地区不能授权两家或者两家以上公司经营同一项基础电信业务。"},{"i":19,"n":"第十九条","txt":"任何单位和个人不得伪造、涂改、冒用和以任何方式转让经营许可证。"},{"i":20,"n":"第二十条","txt":"基础电信业务经营者应当按照公开、平等的原则为取得经营许可证的电信业务经营者提供经营相关电信业务所需的电信服务和电信资源，不得为无经营许可证的单位或者个人提供用于经营电信业务的电信资源或者提供网络接入、业务接入服务。"},{"i":21,"n":"第二十一条","txt":"电信业务经营者不得以任何方式实施不正当竞争。"},{"i":22,"n":"第二十二条","txt":"为增值电信业务经营者提供网络接入、代理收费和业务合作的基础电信业务经营者，应当对相应增值电信业务的内容、收费、合作行为等进行规范、管理，并建立相应的发现、监督和处置制度及措施。"},{"i":23,"n":"第二十三条","txt":"基础电信业务经营者调整与增值电信业务经营者之间的合作条件的，应当事先征求相关增值电信业务经营者的意见。 有关意见征求情况及记录应当留存，并在电信管理机构监督检查时予以提供。"},{"i":24,"n":"第二十四条","txt":"提供接入服务的增值电信业务经营者应当遵守下列规定： （一）应当租用取得相应经营许可证的基础电信业务经营者提供的电信服务或者电信资源从事业务经营活动，不得向其他从事接入服务的增值电信业务经营者转租所获得的电信服务或者电信资源； （二）为用户办理接入服务手续时，应当要求用户提供真实身份信息并予以查验； （三）不得为未依法取得经营许可证或者履行非经营性互联网信息服务备案手续的单位或者个人提供接入或者代收费等服务； （四）按照电信管理机构的规定，建立相应的业务管理系统，并按要求实现同电信管理机构相应系统对接，定期报送有关业务管理信息； （五）对所接入网站传播违法信息的行为进行监督，发现传播明显属于《中华人民共和国电信条例》第五十六条规定的信息的，应当立即停止接入和代收费等服务，保存有关记录，并向国家有关机关报告； （六）按照电信管理机构的要求终止或者暂停对违法网站的接入服务。"},{"i":25,"n":"第二十五条","txt":"电信管理机构建立电信业务市场监测制度。相关电信业务经营者应当按照规定向电信管理机构报送相应的监测信息。"},{"i":26,"n":"第二十六条","txt":"电信业务经营者应当按照国家和电信管理机构的规定，明确相应的网络与信息安全管理机构和专职网络与信息安全管理人员，建立网络与信息安全保障、网络安全防护、违法信息监测处置、新业务安全评估、网络安全监测预警、突发事件应急处置、用户信息安全保护等制度，并具备相应的技术保障措施。"},{"i":27,"n":"第二十七条","txt":"经营许可证有效期届满需要继续经营的，应当提前90日向原发证机关提出延续经营许可证的申请；不再继续经营的，应当提前90日向原发证机关报告，并做好善后工作。 未在前款规定期限内提出延续经营许可证的申请，或者在经营许可证有效期内未开通电信业务的，有效期届满不予延续。"},{"i":28,"n":"第二十八条","txt":"电信业务经营者或者其授权经营电信业务的公司，遇有因合并或者分立、股东变化等导致经营主体需要变更的情形，或者业务范围需要变化的，应当自公司作出决定之日起30日内向原发证机关提出申请。 电信业务经营者变更经营主体、股东的，应当符合本办法第五条、第六条、第九条第三款的有关规定。"},{"i":29,"n":"第二十九条","txt":"在经营许可证的有效期内，变更公司名称、法定代表人、注册资本的，应当在完成公司的工商变更登记手续之日起30日内向原发证机关申请办理电信业务经营许可证变更手续。"},{"i":30,"n":"第三十条","txt":"在经营许可证的有效期内，电信业务经营者需要终止经营的，应当符合下列条件： （一）终止经营基础电信业务的，应当符合电信管理机构确定的电信行业管理总体布局； （二）有可行的用户妥善处理方案并已妥善处理用户善后问题。"},{"i":31,"n":"第三十一条","txt":"在经营许可证的有效期内，电信业务经营者需要终止经营的，应当向原发证机关提交下列申请材料： （一）公司法定代表人签署并加盖印章的终止经营电信业务书面申请，内容包括：公司名称、联系方式、经营许可证编号、申请终止经营的电信业务种类、业务覆盖范围等； （二）公司股东会或者股东大会关于同意终止经营电信业务的决定； （三）公司法定代表人签署的做好用户善后处理工作的承诺书； （四）公司关于解决用户善后问题的情况说明，内容包括：用户处理方案、社会公示情况说明、用户意见汇总、实施计划等； （五）公司的经营许可证原件、营业执照复印件。 原发证机关收到终止经营电信业务的申请后应当向社会公示，公示期为30日。自公示期结束60日内，原发证机关应当完成审查工作，作出予以批准或者不予批准的决定。对于符合终止经营电信业务条件的，原发证机关应当予以批准，收回并注销电信业务经营许可证或者注销相应的电信业务种类、业务覆盖范"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，发证机关或者其上级机关可以撤销经营许可证： （一）发证机关工作人员滥用职权、玩忽职守作出准予行政许可决定的； （二）超越法定职权或者违反法定程序作出准予行政许可决定的； （三）对不具备申请资格或者不符合申请条件的申请人准予行政许可的； （四）依法可以撤销经营许可证的其他情形。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，发证机关应当注销经营许可证： （一）电信业务经营者依法终止的； （二）经营许可证有效期届满未延续的； （三）电信业务经营者被有关机关依法处罚或者因不可抗力，导致电信业务经营许可事项无法实施的； （四）经营许可证依法被撤销、吊销的； （五）法律、法规规定应当注销经营许可证的其他情形。"},{"i":34,"n":"第三十四条","txt":"发证机关吊销、撤销或者注销电信业务经营者的经营许可证后，应当向社会公布。 电信业务经营者被吊销、撤销或者注销经营许可证的，应当按照国家有关规定做好善后工作。 被吊销、撤销或者注销经营许可证的，应当将经营许可证交回原发证机关。"},{"i":35,"n":"第三十五条","txt":"电信业务经营者应当在每年第一季度通过管理平台向发证机关报告下列信息： （一）上一年度的电信业务经营情况； （二）网络建设、业务发展、人员及机构变动情况； （三）服务质量情况； （四）网络与信息安全保障制度和措施执行情况； （五）执行国家和电信管理机构有关规定及经营许可证特别事项的情况； （六）发证机关要求报送的其他信息。 前款第一项至第三项规定的信息（涉及商业秘密的信息除外）应当向社会公示，第五项、第六项规定的信息由电信业务经营者选择是否向社会公示。 电信业务经营者应当对本条第一款规定的年报信息的真实性负责，不得弄虚作假或者隐瞒真实情况。"},{"i":36,"n":"第三十六条","txt":"电信管理机构建立随机抽查机制，对电信业务经营者的年报信息、日常经营活动、执行国家和电信管理机构有关规定的情况等进行检查。 电信管理机构可以采取书面检查、实地核查、网络监测等方式，并可以委托第三方机构开展有关检查工作。 电信管理机构在抽查中发现电信业务经营者有违反电信管理规定的违法行为的，应当依法处理。"},{"i":37,"n":"第三十七条","txt":"电信管理机构根据随机抽查、日常监督检查及行政处罚记录等情况，建立电信业务经营不良名单和电信业务经营失信名单。 电信业务经营不良名单和失信名单应当定期通过管理平台更新并向社会公示。"},{"i":38,"n":"第三十八条","txt":"电信管理机构发现电信业务经营者未按照本办法第三十五条的规定报告年报信息的,应当要求其限期报告。电信业务经营者未按照电信管理机构要求的期限报告年报信息的，由电信管理机构列入电信业务经营不良名单。 依照前款规定列入电信业务经营不良名单的电信业务经营者，依照本办法规定履行报告年报信息义务的，经电信管理机构确认后移出。"},{"i":39,"n":"第三十九条","txt":"获准跨地区经营电信业务的公司在有关省、自治区、直辖市设立、变更或者撤销分支机构的，应当自作出决定之日起30日内通过管理平台向原发证机关和当地电信管理机构报送有关信息。 省、自治区、直辖市通信管理局应当对跨地区电信业务经营者在当地开展电信业务的有关情况进行监督检查，并向工业和信息化部报告有关检查结果。"},{"i":40,"n":"第四十条","txt":"电信管理机构开展监督检查，不得妨碍电信业务经营者正常的生产经营活动，不得收取任何费用。 电信管理机构开展监督检查时，应当记录监督检查的情况和处理结果，由监督检查人员签字后归档。 电信管理机构应当通过管理平台公示监督检查情况。"},{"i":41,"n":"第四十一条","txt":"电信管理机构应当通过管理平台向社会公示电信业务经营者受到行政处罚的情况，并向相关基础电信业务经营者和提供接入服务的增值电信业务经营者通报。"},{"i":42,"n":"第四十二条","txt":"电信业务经营者受到电信管理机构行政处罚的，由电信管理机构自作出行政处罚决定之日起30日内列入电信业务经营不良名单，但受到电信管理机构吊销经营许可证的处罚或者具有本办法规定直接列入电信业务经营失信名单情形的，直接列入失信名单。 列入电信业务经营不良名单的电信业务经营者，一年内未再次受到电信管理机构行政处罚的，由电信管理机构移出不良名单；三年内再次受到电信管理机构责令停业整顿、吊销经营许可证的处罚，或者具有工业和信息化部规定的其他情形的，由电信管理机构列入电信业务经营失信名单。 列入电信业务经营失信名单后，三年内未再次受到电信管理机构行政处罚的，由电信管理机构移出失信名单。 列入或者移出电信业务经营失信名单，应当同时将电信业务经营者的主要经营管理人员列入或者移出。"},{"i":43,"n":"第四十三条","txt":"电信管理机构对列入电信业务经营不良名单和失信名单的电信业务经营者实施重点监管。 基础电信业务经营者和提供接入服务的增值电信业务经营者向其他增值电信业务经营者提供网络接入、代收费和业务合作时，应当把电信业务经营不良名单和失信名单作为重要考量因素。"},{"i":44,"n":"第四十四条","txt":"任何单位或者个人发现电信业务经营者违反电信管理规定应当受到行政处罚的，可以向有关电信管理机构举报。"},{"i":45,"n":"第四十五条","txt":"隐瞒有关情况或者提供虚假材料申请电信业务经营许可的，电信管理机构不予受理或者不予行政许可，给予警告，申请人在一年内不得再次申请该行政许可。 以欺骗、贿赂等不正当手段取得电信业务经营许可的，电信管理机构撤销该行政许可，给予警告并直接列入电信业务经营失信名单，并视情节轻重处5000元以上3万元以下的罚款，申请人在三年内不得再次申请该行政许可；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"违反本办法第十六条第一款、第二十八条第一款规定，擅自经营电信业务或者超范围经营电信业务的，依照《中华人民共和国电信条例》第六十九条规定予以处罚，其中情节严重、给予责令停业整顿处罚的，直接列入电信业务经营失信名单。"},{"i":47,"n":"第四十七条","txt":"违反本办法第十九条规定的，依照《中华人民共和国电信条例》第六十八条规定予以处罚。"},{"i":48,"n":"第四十八条","txt":"违反本办法第四条第二款、第二十条、第二十二条、第二十三条、第二十四条、第二十九条、第三十一条或者第三十五条第三款规定的，由电信管理机构责令改正，给予警告，可以并处5000元以上3万元以下的罚款。 《中华人民共和国网络安全法》《中华人民共和国电信条例》对前款规定的情形规定法律责任的，电信管理机构从其规定处理。"},{"i":49,"n":"第四十九条","txt":"当事人对电信管理机构作出的行政许可、行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。 当事人逾期不申请行政复议也不提起行政诉讼，又不履行行政处罚决定的，由作出行政处罚决定的电信管理机构申请人民法院强制执行，并列入电信业务经营失信名单。"},{"i":50,"n":"第五十条","txt":"电信管理机构的工作人员在经营许可证管理工作中，玩忽职守、滥用职权、徇私舞弊，构成犯罪的，移交司法机关依法追究刑事责任；尚不构成犯罪的，由所在单位或者上级主管部门依法给予处分。"},{"i":51,"n":"第五十一条","txt":"经营许可证由工业和信息化部统一印制。"},{"i":52,"n":"第五十二条","txt":"电信管理机构可以参照本办法组织开展电信业务商用试验活动。"},{"i":53,"n":"第五十三条","txt":"本办法自2017年9月1日起施行。2009年3月5日公布的《电信业务经营许可管理办法》（工业和信息化部令第5号）同时废止。"}],"dianxinhehulianwangyonghugerenxinxibaohuguiding-2":[{"i":1,"n":"第一条","txt":"为了保护电信和互联网用户的合法权益，维护网络信息安全，根据《全国人民代表大会常务委员会关于加强网络信息保护的决定》、《中华人民共和国电信条例》和《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供电信服务和互联网信息服务过程中收集、使用用户个人信息的活动，适用本规定。"},{"i":3,"n":"第三条","txt":"工业和信息化部和各省、自治区、直辖市通信管理局（以下统称电信管理机构）依法对电信和互联网用户个人信息保护工作实施监督管理。"},{"i":4,"n":"第四条","txt":"本规定所称用户个人信息，是指电信业务经营者和互联网信息服务提供者在提供服务的过程中收集的用户姓名、出生日期、身份证件号码、住址、电话号码、账号和密码等能够单独或者与其他信息结合识别用户的信息以及用户使用服务的时间、地点等信息。"},{"i":5,"n":"第五条","txt":"电信业务经营者、互联网信息服务提供者在提供服务的过程中收集、使用用户个人信息，应当遵循合法、正当、必要的原则。"},{"i":6,"n":"第六条","txt":"电信业务经营者、互联网信息服务提供者对其在提供服务过程中收集、使用的用户个人信息的安全负责。"},{"i":7,"n":"第七条","txt":"国家鼓励电信和互联网行业开展用户个人信息保护自律工作。"},{"i":8,"n":"第八条","txt":"电信业务经营者、互联网信息服务提供者应当制定用户个人信息收集、使用规则，并在其经营或者服务场所、网站等予以公布。"},{"i":9,"n":"第九条","txt":"未经用户同意，电信业务经营者、互联网信息服务提供者不得收集、使用用户个人信息。 电信业务经营者、互联网信息服务提供者收集、使用用户个人信息的，应当明确告知用户收集、使用信息的目的、方式和范围，查询、更正信息的渠道以及拒绝提供信息的后果等事项。 电信业务经营者、互联网信息服务提供者不得收集其提供服务所必需以外的用户个人信息或者将信息用于提供服务之外的目的，不得以欺骗、误导或者强迫等方式或者违反法律、行政法规以及双方的约定收集、使用信息。 电信业务经营者、互联网信息服务提供者在用户终止使用电信服务或者互联网信息服务后，应当停止对用户个人信息的收集和使用，并为用户提供注销号码或者账号的服务。 法律、行政法规对本条第一款至第四款规定的情形另有规定的，从其规定。"},{"i":10,"n":"第十条","txt":"电信业务经营者、互联网信息服务提供者及其工作人员对在提供服务过程中收集、使用的用户个人信息应当严格保密，不得泄露、篡改或者毁损，不得出售或者非法向他人提供。"},{"i":11,"n":"第十一条","txt":"电信业务经营者、互联网信息服务提供者委托他人代理市场销售和技术服务等直接面向用户的服务性工作，涉及收集、使用用户个人信息的，应当对代理人的用户个人信息保护工作进行监督和管理，不得委托不符合本规定有关用户个人信息保护要求的代理人代办相关服务。"},{"i":12,"n":"第十二条","txt":"电信业务经营者、互联网信息服务提供者应当建立用户投诉处理机制，公布有效的联系方式，接受与用户个人信息保护有关的投诉，并自接到投诉之日起十五日内答复投诉人。"},{"i":13,"n":"第十三条","txt":"电信业务经营者、互联网信息服务提供者应当采取以下措施防止用户个人信息泄露、毁损、篡改或者丢失： （一）确定各部门、岗位和分支机构的用户个人信息安全管理责任； （二）建立用户个人信息收集、使用及其相关活动的工作流程和安全管理制度； （三）对工作人员及代理人实行权限管理，对批量导出、复制、销毁信息实行审查，并采取防泄密措施； （四）妥善保管记录用户个人信息的纸介质、光介质、电磁介质等载体，并采取相应的安全储存措施； （五）对储存用户个人信息的信息系统实行接入审查，并采取防入侵、防病毒等措施； （六）记录对用户个人信息进行操作的人员、时间、地点、事项等信息； （七）按照电信管理机构的规定开展通信网络安全防护工作； （八）电信管理机构规定的其他必要措施。"},{"i":14,"n":"第十四条","txt":"电信业务经营者、互联网信息服务提供者保管的用户个人信息发生或者可能发生泄露、毁损、丢失的，应当立即采取补救措施；造成或者可能造成严重后果的，应当立即向准予其许可或者备案的电信管理机构报告，配合相关部门进行的调查处理。 电信管理机构应当对报告或者发现的可能违反本规定的行为的影响进行评估；影响特别重大的，相关省、自治区、直辖市通信管理局应当向工业和信息化部报告。电信管理机构在依据本规定作出处理决定前，可以要求电信业务经营者和互联网信息服务提供者暂停有关行为，电信业务经营者和互联网信息服务提供者应当执行。"},{"i":15,"n":"第十五条","txt":"电信业务经营者、互联网信息服务提供者应当对其工作人员进行用户个人信息保护相关知识、技能和安全责任培训。"},{"i":16,"n":"第十六条","txt":"电信业务经营者、互联网信息服务提供者应当对用户个人信息保护情况每年至少进行一次自查，记录自查情况，及时消除自查中发现的安全隐患。"},{"i":17,"n":"第十七条","txt":"电信管理机构应当对电信业务经营者、互联网信息服务提供者保护用户个人信息的情况实施监督检查。 电信管理机构实施监督检查时，可以要求电信业务经营者、互联网信息服务提供者提供相关材料，进入其生产经营场所调查情况，电信业务经营者、互联网信息服务提供者应当予以配合。 电信管理机构实施监督检查，应当记录监督检查的情况，不得妨碍电信业务经营者、互联网信息服务提供者正常的经营或者服务活动，不得收取任何费用。"},{"i":18,"n":"第十八条","txt":"电信管理机构及其工作人员对在履行职责中知悉的用户个人信息应当予以保密，不得泄露、篡改或者毁损，不得出售或者非法向他人提供。"},{"i":19,"n":"第十九条","txt":"电信管理机构实施电信业务经营许可及经营许可证年检时，应当对用户个人信息保护情况进行审查。"},{"i":20,"n":"第二十条","txt":"电信管理机构应当将电信业务经营者、互联网信息服务提供者违反本规定的行为记入其社会信用档案并予以公布。"},{"i":21,"n":"第二十一条","txt":"鼓励电信和互联网行业协会依法制定有关用户个人信息保护的自律性管理制度，引导会员加强自律管理，提高用户个人信息保护水平。"},{"i":22,"n":"第二十二条","txt":"电信业务经营者、互联网信息服务提供者违反本规定第八条、第十二条规定的，由电信管理机构依据职权责令限期改正，予以警告，可以并处一万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"电信业务经营者、互联网信息服务提供者违反本规定第九条至第十一条、第十三条至第十六条、第十七条第二款规定的，由电信管理机构依据职权责令限期改正，予以警告，可以并处一万元以上三万元以下的罚款，向社会公告；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"电信管理机构工作人员在对用户个人信息保护工作实施监督管理的过程中玩忽职守、滥用职权、徇私舞弊的，依法给予处理；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本规定自2013年9月1日起施行。"}],"dianxinjiansheguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强电信建设的统筹规划和行业管理，促进电信业健康、有序发展，根据《中华人民共和国电信条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国境内新建、改建和扩建公用电信网、专用电信网和广播电视传输网，均须遵守本办法。"},{"i":3,"n":"第三条","txt":"信息产业部依法对全国公用电信网、专用电信网和广播电视传输网的建设实施监督管理。 各省、自治区、直辖市通信管理局，在信息产业部领导下，依法对本行政区域内的公用电信网、专用电信网和广播电视传输网的建设实施监督管理。"},{"i":4,"n":"第四条","txt":"全国性电信网络工程和国际电信建设项目是电信建设管理的重点。 本办法所称全国性电信网络工程是指跨省（自治区、直辖市）公用电信网、专用电信网和广播电视传输网以及其组成部分的建设工程。"},{"i":5,"n":"第五条","txt":"电信网络和电信设施建设须严格遵守国家有关法律、政策，符合电信网体制标准及通信工程建设标准、建设规范。"},{"i":6,"n":"第六条","txt":"电信建设管理应维护国家通信主权，破除垄断，鼓励竞争，促进资源合理利用，维护通信建设市场秩序，营造公开、公平、公正的竞争环境。"},{"i":7,"n":"第七条","txt":"信息产业部负责编制电信行业发展规划，各省、自治区、直辖市通信管理局负责编制所辖行政区电信行业发展规划。 投资建设公用电信网、广播电视传输网的企业（或单位），必须根据行业规划的要求，编制本企业（或单位）五年规划（含传输网五年专题规划），并逐年编制滚动规划（含传输网滚动专题规划）。 投资建设专用电信网的企业（或单位），应根据本企业（或单位）对通信传输线路及带宽的需求编制本企业（或单位）传输网五年专题规划，并根据实际建设和发展情况逐年编制传输网滚动专题规划（含自建、购买、租用等）。 企业（或单位）可以根据情况确定滚动规划期限为三年或五年。"},{"i":8,"n":"第八条","txt":"企业（或单位）五年规划应当包括以下内容： （一）本企业（或单位）电信网现状； （二）本企业（或单位）五年发展思路、目标、重点； （三）本企业（或单位）建设资金估算和资金筹措计划； （四）本企业（或单位）五年重点建设项目框架等。"},{"i":9,"n":"第九条","txt":"企业（或单位）滚动规划应当包括以下内容： （一）本企业（或单位）电信网现状及上年度完成情况； （二）本企业（或单位）当年发展目标、重点及建设项目框架、资金估算和资金筹措计划； （三）本企业（或单位）滚动期末发展思路、目标。"},{"i":10,"n":"第十条","txt":"传输网五年专题规划应当包括以下内容： （一）本企业（或单位）传输网现状（含路由图）； （二）本企业（或单位）传输网五年需求、发展目标、重点及规划路由图； （三）本企业（或单位）传输网五年建设项目框架（含路由、距离、容量、投资等）。"},{"i":11,"n":"第十一条","txt":"传输网滚动专题规划应当包括以下内容： （一）本企业（或单位）传输网现状（含路由图、上一年度传输网建设项目完成情况）； （二）本年度传输网项目建设计划（含项目路由、距离、容量、投资以及资金来源等）； （三）本年度传输网建设路由图； （四）滚动期末传输网发展思路、目标及建设项目框架。"},{"i":12,"n":"第十二条","txt":"企业（或单位）五年规划、传输网五年专题规划和滚动规划实行备案制度。 企业（或单位）五年规划、传输网五年专题规划应于国家每个五年规划期开始前上报备案，滚动规划应于每年一月底前上报备案。 拥有全国性电信网络的非计划单列企业（或单位）的规划，报信息产业部。拥有全国性电信网络的计划单列企业的规划，同时报国家计委和信息产业部。 各省、自治区、直辖市行政区域内的公用电信网和广播电视传输网、专用电信网建设企业（或单位）的规划，报本省、自治区、直辖市通信管理局。 国家计委、信息产业部或省、自治区、直辖市通信管理局在收到上报备案规划 30 个工作日内未提出不同意见的，该规划即自动生效，国家另有规定的从其规定。"},{"i":13,"n":"第十三条","txt":"企业（或单位）传输网滚动专题规划实行审批制度。 企业（或单位）年度传输网滚动专题规划应于当年一月底前报信息产业部或省、自治区、直辖市通信管理局。行业主管部门应在收到上报规划的 45 个工作日内作出审批。 信息产业部或省、自治区、直辖市通信管理局对企业（或单位）上报的传输网滚动专题规划组织专家咨询、评审，并在此基础上出具批复意见。"},{"i":14,"n":"第十四条","txt":"国家计委、信息产业部和省、自治区、直辖市通信管理局，依据国民经济和社会发展五年规划及其重点专项规划、电信行业规划，指导各相关企业（或单位）规划、传输网五年专题规划和滚动规划、传输网滚动专题规划的编制工作，并监督检查其执行情况。"},{"i":15,"n":"第十五条","txt":"公用电信网、专用电信网、广播电视传输网的建设必须严格执行国家有关规定。其建设程序应包括编制和批准项目建议书、可行性研究报告、初步设计和进行竣工验收等。其中：利用外资的电信建设项目按照有关法律法规规定，履行报批手续；自筹资金的电信建设项目可由业主单位自行进行初步设计和竣工验收，限额以下项目可以可行性研究报告代项目建议书一并审批。"},{"i":16,"n":"第十六条","txt":"建设项目要严格按照国家规定的项目审批权限进行审批。各项目建设单位不得将整体项目化整为零，规避主管部门审查。审批项目应以业主单位的电信业务许可证范围为依据。"},{"i":17,"n":"第十七条","txt":"国内传输网新建或改建、扩建项目在按照国家基本建设程序审批前，须经相应通信主管部门初审，行业初审同意的项目方可获得批准。 项目审批部门对行业初审结果有不同意见的，由项目审批部门和出具初审意见的部门协商解决。"},{"i":18,"n":"第十八条","txt":"申报国内传输网跨省建设项目或国家规定的限额以上项目，应同时抄报信息产业部；申报国内传输网省内限额以下建设项目，应同时抄报本省、自治区、直辖市通信管理局。计划单列企业按照项目审批权限自行审批的限额以下国内传输网项目，应抄报国家计委和信息产业部。申报项目单位应提供电信业务经营许可证等材料。 行业主管部门在收到抄报文件 20 个工作日内，向项目审批部门出具行业初审意见。"},{"i":19,"n":"第十九条","txt":"信息产业部或省、自治区、直辖市通信管理局对企业（或单位）当年传输网滚动专题规划的批复同意意见，视同对该滚动规划中国内传输网当年建设项目的行业初审同意。未列入企业（或单位）当年滚动规划内的项目，在审批前必须报信息产业部或者省、自治区、直辖市通信管理局初审。"},{"i":20,"n":"第二十条","txt":"国际传输网、国际通信出入口等国际电信建设项目由国家统一审批。其中，限额以上基本建设项目或限额以上的技术改造项目经信息产业部初审同意后，由国家计委或国家经贸委审批或核报国务院审批；限额以下项目由信息产业部审批，其他部门（或单位）无权审批国际电信建设项目。投资建设或参与投资建设国际电信项目的单位必须拥有国际通信基础设施经营权。 信息产业部在受理国际电信建设项目行业初审申请后，应在 30 个工作日内予以答复。限额以下国际电信建设项目审批应在申请之日起 45 个工作日内予以批复。"},{"i":21,"n":"第二十一条","txt":"国家鼓励有权建设传输网的电信运营企业和有关单位联合建设国内传输网络。联合建设项目应依照本办法第十七条规定按一个项目联合报批。申报联合建设项目除规定内容外，还应注明合建方及牵头单位，并补充各自的建设规模和出资额。 参与军民合建项目的地方企业或单位必须与经总参通信部批准的军队项目联合建设。"},{"i":22,"n":"第二十二条","txt":"参与联合建设国内传输网的各投资方必须事先签署联合建设协议，并明确联合建设的牵头单位和各方的权利与义务。全国性网络联合建设协议报信息产业部备案，省、自治区、直辖市内网络联合建设协议报省、自治区、直辖市通信管理局备案。"},{"i":23,"n":"第二十三条","txt":"项目审批或初审应采取专家咨询、专家评审等方式，并在此基础上批复或出具行业初审意见。"},{"i":24,"n":"第二十四条","txt":"信息产业部对全国电信建设市场、电信建设工程质量、招标投标等电信建设活动以及通信工程建设强制性标准的执行情况实施监督管理。 省、自治区、直辖市通信管理局对本行政区域内电信建设市场、电信建设工程质量、招标投标等电信建设活动，以及通信工程建设强制性标准的执行情况实施监督管理。"},{"i":25,"n":"第二十五条","txt":"基础电信业务经营者可以在电信业务经营许可证规定的范围内投资建设和经营电信设施。 任何企业（或单位）不得从无网络元素出租、出售业务许可证的企业（或单位）购买、租用网络资源。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市通信管理局负责本行政区内电信管道建设的统筹规划和协调。地方各级人民政府应将电信管道建设规划纳入城镇建设总体规划，电信管道的建设规模、容量应当满足电信业务发展的需要。"},{"i":27,"n":"第二十七条","txt":"公共场所的经营者或管理者有义务协助基础电信业务经营者依法在该场所内从事电信设施建设，不得阻止或者妨碍基础电信业务经营者向电信用户提供公共电信服务。"},{"i":28,"n":"第二十八条","txt":"在民用建筑物上设置小型天线、移动通信基站等公用电信设施时，必须满足建筑物荷载等条件，不得破坏建筑物的安全性。"},{"i":29,"n":"第二十九条","txt":"建设地下、水底等隐蔽电信设施，应当设置标志并注明产权人。其中光缆线路建设应当按照通信工程建设标准的有关规定设置光缆线路标石和水线标志牌；海缆登陆点处应设置明显的海缆登陆标志，海缆路由应向国家海洋管理部门和港监部门备案。产权人发现标志受损或丢失的，应及时修复、补齐，并有权依法追究破坏电信设施标志的单位或个人的责任。 在已设置标志或备案的情况下电信设施损坏所造成的损失由责任方承担；因无标志或未备案而发生的电信设施损坏造成的损失由产权人自行承担。"},{"i":30,"n":"第三十条","txt":"任何单位或者个人不得擅自改动或者迁移他人的电信线路及其他电信设施；遇有特殊情况必须迁改的，应当征得该电信设施产权人的同意，并签订协议。在迁改过程中，双方应采取措施尽量保证通信不中断。迁改费用、保证通信不中断所发生的费用以及中断通信造成的损失，由提出迁改要求的单位或者个人承担或赔偿，割接期间的中断除外。"},{"i":31,"n":"第三十一条","txt":"从事施工、生产、种植树木等活动，应与电信线路或者其他电信设施保持一定的安全距离，不得危及电信线路等电信设施的安全或者妨碍线路畅通。可能危及电信安全时，应当事先通知有关电信业务经营者，并由从事该活动的单位或者个人负责采取必要的安全防护措施。建筑物、其他设施、树木等与电信线路及其他电信设施的最小安全距离应根据通信工程建设标准的有关规定确定。"},{"i":32,"n":"第三十二条","txt":"从事电信线路建设，在路由选择时应尽量避开已建电信线路，并根据通信工程建设标准的有关规定与已建的电信线路保持必要的安全距离，避免同路由、近距离敷设。受地形限制必须近距离甚至同沟敷设或者线路必须交越的，电信线路建设项目的建设单位应当与已建电信线路的产权人协商并签订协议，制定安全措施，在双方监督下进行施工，确保已建电信线路的畅通。 经协商不能达成协议的，根据电信线路建设情况，跨省线路由信息产业部协调解决，省内线路由相关省、自治区、直辖市通信管理局协调解决。"},{"i":33,"n":"第三十三条","txt":"从事微波通信建设，应按国家无线电管理的有关规定到当地无线电管理机构办理设台手续，其微波传输通道应向当地城市规划部门备案。 建设微波通信设施、移动通信基站等无线通信设施不得妨碍已建通信设施的通信畅通。妨碍已建无线通信设施的通信畅通的，由当地省、自治区、直辖市无线电管理机构责令其改正。"},{"i":34,"n":"第三十四条","txt":"信息产业部和省、自治区、直辖市通信管理局可委托经信息产业部考核合格的通信工程质量监督机构具体实施电信建设项目的质量监督。 参与电信建设的各方主体应当遵循国家法律、法规及强制性标准的规定，对其承接的项目质量和安全负责。"},{"i":35,"n":"第三十五条","txt":"按有关规定必须进行招标的电信建设项目实行招标备案制。电信建设项目业主单位应在确定中标人之日起 15日内填写 “ 通信建设项目招标情况备案表 ” ，其中跨省（自治区、直辖市）建设的项目报国家计委和信息产业部备案，其他建设项目报省、自治区、直辖市通信管理局备案。涉及机电设备的国际招标项目应遵守国家有关规定。"},{"i":36,"n":"第三十六条","txt":"参与电信网络建设的单位应经信息产业部或省、自治区、直辖市电信建设管理部门审查同意后，按照国家有关规定，办理资质审批和年检手续，未经信息产业部或省、自治区、直辖市电信建设管理部门审查同意的，不得承接电信建设项目。 通信信息网络系统集成和通信用户管线建设企业，应当按信息产业部有关规定取得通信信息网络系统集成企业资质或通信用户管线建设许可证书。否则不得承接电信建设项目。"},{"i":37,"n":"第三十七条","txt":"电信建设项目业主单位不得选择未经通信主管部门审查同意或未取得相应电信建设资质证书的设计、施工、监理、咨询、系统集成、用户管线建设、招投标代理单位承担电信建设项目。"},{"i":38,"n":"第三十八条","txt":"信息产业部和省、自治区、直辖市通信管理局对电信建设进行监督检查时，被检查单位应当按要求提供有关电信建设的文件和资料，配合有关人员进入工作现场进行检查，并接受信息产业部和省、自治区、直辖市通信管理局对违规行为作出的处理。妨碍监督检查工作，或拒不接受处理的，应依法追究有关责任。"},{"i":39,"n":"第三十九条","txt":"违反本办法第十五条、第十六条、第十七条、第十九条、第二十条、第二十一条有关规定审批的项目，审批无效。 违反本办法规定擅自进行电信建设的，在建项目一律停止建设、整顿，并由国家计委、信息产业部或省、自治区、直辖市通信管理局会同有关部门依据职责查处，对建设单位及审批单位给予通报批评并责令改正，已建成的项目暂不允许投入运营。造成国家资源浪费、扰乱电信市场秩序、危害电信安全等后果的，对建设单位和审批单位的主管人员和直接责任人依法给予行政处分，构成犯罪的，移交司法机关追究刑事责任。"},{"i":40,"n":"第四十条","txt":"企业（或单位）没有电信业务经营许可证或超出电信业务经营许可证规定范围进行电信建设活动的，信息产业部或省、自治区、直辖市通信管理局应当责令其改正；情节严重的，责令停业整顿，并处一万元以上、三万元以下罚款。"},{"i":41,"n":"第四十一条","txt":"违反第三十条、第三十一条、第三十二条规定，危及电信线路等电信设施的安全或者妨碍线路畅通的，省、自治区、直辖市通信管理局应当责令其恢复原状或者予以修复，并赔偿由此造成的经济损失。中断电信业务给电信业务经营者造成的经济损失包括直接经济损失、电信企业采取临时措施疏通电信业务的费用以及因中断电信业务而向用户支付的损失赔偿费。情节严重的，处一万元以上、三万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"参与电信建设的各方主体违反国家有关电信建设工程质量管理规定的，信息产业部或省、自治区、直辖市通信管理局可依据《建设工程质量管理条例》的规定责令其改正或予以处罚，已竣工验收的须在整改后重新组织竣工验收。"},{"i":43,"n":"第四十三条","txt":"电信建设项目投资业主单位委托未经通信主管部门审查同意或未取得相应电信建设资质证书的单位承担电信建设项目设计、施工、监理、咨询、系统集成、用户管线建设、招投标代理的，信息产业部或省、自治区、直辖市通信管理局应责令改正，已竣工的不得投入使用，造成重大经济损失的，电信建设单位和相关设计、施工、监理、咨询、系统集成、用户管线建设、招投标代理等单位领导应承担相应法律责任。"},{"i":44,"n":"第四十四条","txt":"设计、施工、监理、咨询、系统集成、用户管线建设、招投标代理等单位发生违规、违纪行为，或出现质量、安全事故的，除按《建设工程质量管理条例》的规定予以相应处罚外，信息产业部或省、自治区、直辖市通信管理局应视情节轻重给予下列处罚： （一）发生一般质量事故的，给予通报批评； （二）转包、违法分包、越级承揽电信建设项目或者发生重大质量事故、安全事故的，取消责任单位 1-2 年参与电信建设活动的资格。"},{"i":45,"n":"第四十五条","txt":"本办法由信息产业部、国家计委解释。"},{"i":46,"n":"第四十六条","txt":"本办法自 2002 年 2 月 1 日起施行。"}],"dianxinfuwuguifan":[{"i":1,"n":"第一条","txt":"为了提高电信服务的质量，维护电信用户的合法权利，保证电信服务和监管工作的系统化和规范化，依据《中华人民共和国电信条例》，制定本规范。"},{"i":2,"n":"第二条","txt":"本规范适用于在中华人民共和国境内依法经营电信业务的电信业务经营者提供电信服务的活动。"},{"i":3,"n":"第三条","txt":"本规范为电信业务经营者提供电信服务时应当达到的基本质量要求，是电信行业对社会公开的最低承诺，同时适用于单一电信业务网或多个电信业务网共同提供的电信业务。 电信业务经营者提供电信服务，应当符合本规范规定的服务质量指标和通信质量指标。 本规范所称服务质量指标，是指反映电信服务固有特性满足要求程度的，主要反映非技术因素的一组参数。 本规范所称通信质量指标，是指反映通信准确性、有效性和安全性的，主要反映技术因素的一组参数。"},{"i":4,"n":"第四条","txt":"中华人民共和国信息产业部（以下简称信息产业部）组织制定全国的电信服务规范，监督检查电信服务规范在全国的实施。 各省、自治区、直辖市通信管理局（以下简称通信管理局）监督检查电信服务规范在本行政区域内的实施。 本规范中，信息产业部和通信管理局统称为电信管理机构。"},{"i":5,"n":"第五条","txt":"电信业务经营者可以制定本企业的企业服务标准，电信业务经营者制定的企业服务标准不得低于本规范。"},{"i":6,"n":"第六条","txt":"电信业务经营者应当采取有效措施，持续改进电信服务工作。"},{"i":7,"n":"第七条","txt":"电信业务经营者应建立健全服务质量管理体系，并按规定的时间、内容和方式向电信管理机构报告，同时向社会通报本企业服务质量状况。 发生重大通信阻断时，电信业务经营者应当按规定的要求和时限向电信管理机构报告。在事故处理过程中，电信业务经营者应对所有与事故有关的数据进行采集、记录和保存，相关数据和书面记录至少保存六个月。"},{"i":8,"n":"第八条","txt":"电信业务经营者提供电信服务时，应公布其业务种类、服务时限、资费标准和服务范围等内容，并报当地通信管理局备案。 由于电信业务经营者检修线路、设备搬迁、工程割接、网络及软件升级等可预见的原因，影响或可能影响用户使用的，应提前七十二小时通告所涉及的用户。影响用户的时间超过二十四小时或影响有特殊需求的用户使用时，应同时向当地通信管理局报告。 电信业务经营者停止经营某种业务时，应提前三十日通知所涉及用户，并妥善做好用户善后工作。"},{"i":9,"n":"第九条","txt":"电信业务经营者应当执行国家电信资费管理的有关规定，明码标价，并采取有效措施，为用户交费和查询费用提供方便。"},{"i":10,"n":"第十条","txt":"用户申请办理电信业务时，电信业务经营者应当向用户提供该项业务的说明。该说明应当包括该业务的业务功能、通达范围、业务取消方式、费用收取办法、交费时间、障碍申告电话、咨询服务电话等。电信业务宣传资料应针对业务全过程，通俗易懂，真实准确。 对用户暂停或停止服务时，应在二十四小时前通知用户。"},{"i":11,"n":"第十一条","txt":"电信业务经营者不得以任何方式限定用户使用其指定的业务或购买其指定的电信终端设备。用户要求开通、变更或终止电信业务时，电信业务经营者无正当理由不得拖延、推诿和拒绝，不得胁迫、刁难用户。 经营本地电话业务和移动电话业务的电信业务经营者，应当全面建立公开、公平的电话号码用户选择机制。"},{"i":12,"n":"第十二条","txt":"电信业务经营者应以书面形式或其他形式明确经营者与用户双方的权利和义务，其格式合同条款应做到公平合理、准确全面、简单明了。"},{"i":13,"n":"第十三条","txt":"电信业务经营者应合理设置服务网点或代办点，合理安排服务时间或开设多种方式受理业务，方便用户。 上门服务人员应遵守预约时间，出示工作证明或佩带本企业标识，代经销人员应主动明示电信业务代理身份，爱护用户设施，保持环境整洁。 电信业务经营者应为残疾人和行动不便的老年用户提供便捷的服务。"},{"i":14,"n":"第十四条","txt":"电信业务经营者应当建立与用户沟通的渠道和制度，听取用户的意见和建议，自觉改善服务工作。 电信业务经营者应当向用户提供业务咨询、查询和障碍申告受理等服务，并采取公布监督电话等形式，受理用户投诉。对于用户关于电信服务方面的投诉，电信业务经营者应在接到用户投诉之日起十五日内答复用户。 电信业务经营者在电信服务方面与用户发生纠纷的，在纠纷解决前，应当保存相关原始资料。"},{"i":15,"n":"第十五条","txt":"电信业务经营者提供电信卡类业务时，应当向用户提供相应的服务保证，不得发行超出服务能力的电信卡。 电信业务经营者应当采取适当的方式明确电信业务经营者与持卡用户双方的权利、义务和违约责任，告知用户使用方法、资费标准、计费方式、有效期限以及其他应当告知用户的事项。 电信业务经营者不得做出对持卡用户不公平、不合理的规定，不得单方面免除或者限制电信业务经营者的责任，损害用户的合法权益。"},{"i":16,"n":"第十六条","txt":"以代理形式开展电信服务的，代理人在提供电信服务活动时，应当执行本规范。电信业务经营者应加强对其业务代理商的管理，并负责管理和监督检查代办电信业务单位或个人的服务质量。"},{"i":17,"n":"第十七条","txt":"通信管理局可以根据本地实际情况，对本规范的服务质量指标进行局部调整或补充。调整后的指标低于本规范的，应当报信息产业部批准。 通信管理局按照前款规定调整服务质量指标的，该行政区域应当执行调整后的服务质量指标。"},{"i":18,"n":"第十八条","txt":"电信业务经营者可以根据用户的特殊需要，约定有关的业务受理、开通时限、故障处理时限等问题，但其服务质量不得低于本规范或者当地通信管理局制定的服务质量指标。"},{"i":19,"n":"第十九条","txt":"电信业务经营者提供的电信服务未能达到本规范或者当地通信管理局制定的服务质量指标的，由电信管理机构责令改正。拒不改正的，处以警告，并处一万元以上三万元以下的罚款。"},{"i":20,"n":"第二十条","txt":"信息产业部根据实际情况，可以对电信业务项目及其服务质量指标和通信质量指标（详见附录）做出调整，并重新公布实施。"},{"i":21,"n":"第二十一条","txt":"本规定自 2005 年 4 月 20 日起施行，信息产业部制定的《电信服务标准（试行）》（信部电 [2000]27 号）同时废止。 附录1：电信服务规范-固定网本地及国内长途电话业务.wps 附录2：电信服务规范-数字蜂窝移动通信业务.wps 附录3：电信服务规范-因特网及其他数据通信业务.wps 附录4：电信服务规范-国内 IP 电话业务.wps 附录5：电信服务规范-无线寻呼业务.wps 附录6：电信服务规范-信息服务业务.wps 附录7：电信服务规范-国内甚小口径终端地球站（VSAT）通信业务.wps 附录8：电信服务规范-国内通信设施服务业务.wps"}],"dianxinfuwuzhiliangjianduguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了促进我国电信事业健康、有序、快速地发展，维护电信用户的合法权益，加强对电信业务经营者服务质量的监督管理，根据《中华人民共和国电信条例》及有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内所有获得经营许可的电信业务经营者。"},{"i":3,"n":"第三条","txt":"工业和信息化部根据国家有关法律、行政法规对电信业务经营者提供的电信服务质量进行监督管理。 省、自治区、直辖市通信管理局负责对电信业务经营者在本行政区域提供的电信服务质量进行监督管理。（工业和信息化部，省、自治区、直辖市通信管理局以下统称电信管理机构）"},{"i":4,"n":"第四条","txt":"电信服务质量监督管理工作遵循公平、公正、公开的原则，实行政府监管、企业自律、社会监督相结合的机制。"},{"i":5,"n":"第五条","txt":"电信服务质量监督管理的任务是对电信业务经营者提供的电信服务质量实施管理和监督检查；监督电信服务标准的执行情况；依法对侵犯用户合法利益的行为进行处罚；总结和推广先进、科学的电信服务质量管理经验。"},{"i":6,"n":"第六条","txt":"电信管理机构服务质量监督的职责是： （一）制定颁布电信服务质量有关标准、管理办法并监督实施； （二）组织用户对电信服务质量进行评价，实时掌握服务动态； （三）纠正和查处电信服务中的质量问题，并对处理决定的执行情况进行监督，实施对违规电信业务经营者的处罚，对重大的质量事故进行调查、了解，并向社会公布重大服务质量事件的处理过程和结果； （四）表彰和鼓励电信服务工作中用户满意的先进典型； （五）对电信业务经营者执行资费政策标准情况、格式条款内容进行监督； （六）负责组织对有关服务质量事件的调查和争议的调解。"},{"i":7,"n":"第七条","txt":"电信管理机构工作人员在监督检查服务质量和处理用户申诉案件时，可以行使下列职权： （一）询问被检查的单位及相关人员，并要求提供相关材料； （二）有权进入被检查的工作场所，查询、复印有关单据、文件、记录和其他资料，暂时封存有关原始记录。 电信管理机构工作人员实施监督检查过程中，应出示有效证件，并由两名或两名以上工作人员共同进行。"},{"i":8,"n":"第八条","txt":"电信管理机构不定期组织对电信业务经营者的服务质量进行抽查，并向社会公布有关抽查结果。"},{"i":9,"n":"第九条","txt":"电信管理机构将用户满意度指数作为对电信业务经营者服务质量评价的核心指标，组织进行电信服务质量的用户满意度评价活动。鼓励电信业务经营者建立科学的用户满意度评价体系。"},{"i":10,"n":"第十条","txt":"电信管理机构定期向社会公布电信服务质量状况和用户满意度指数。"},{"i":11,"n":"第十一条","txt":"电信管理机构可以依靠全国电信用户委员会以及社会舆论等，沟通与广大用户的联系，听取用户的意见与建议，充分发挥用户的监督作用。 电信用户申诉受理中心应当定期通报受理用户申诉和统计分析情况。"},{"i":12,"n":"第十二条","txt":"电信用户有对电信业务经营者的服务质量及保护用户权益工作进行监督的权利，有权向电信业务经营者及电信管理机构提出改善电信服务的意见和建议，有权检举、控告损害用户权益的行为及有关工作人员在监督检查工作中的违法失职行为。"},{"i":13,"n":"第十三条","txt":"电信管理机构有权要求并督促电信业务经营者采取有效措施，保证所提供的服务质量得以持续改进。"},{"i":14,"n":"第十四条","txt":"电信业务经营者应当按规定向电信用户申诉受理中心交纳服务质量保证金。"},{"i":15,"n":"第十五条","txt":"电信业务经营者制定和使用格式条款应当符合国家有关法律、行政法规的规定，全面、准确地界定经营者与用户间的权利和义务，并采取合理的方式提请用户注意免除或限制电信业务经营者责任的条款，按照对方的要求，对该条款予以说明。根据业务发展情况，应及时规范和调整格式条款的有关内容。"},{"i":16,"n":"第十六条","txt":"电信业务经营者应对外公布投诉电话，配备受理用户投诉的人员；对用户投诉应在规定的时限内予以答复，不得互相推诿；对电信管理机构督办的事宜，应在规定的时限内将处理结果或处理过程向其报告；对用户提出的改善电信服务的意见和建议要认真研究，主动沟通。"},{"i":17,"n":"第十七条","txt":"用户要求查询通信费用时，在计费原始数据保存期限内，电信业务经营者应提供查询方便，做好解释工作。在与用户发生争议、尚未解决的情况下，电信业务经营者应负责保存相关原始资料。 计费原始数据保存期限为5个月。"},{"i":18,"n":"第十八条","txt":"电信业务经营者应定期对照电信服务标准进行自查。跨省经营的电信业务经营者将自查情况每半年向工业和信息化部报告，其分支经营单位及取得省内经营电信业务许可证的经营者将自查情况每半年向本省（自治区、直辖市）通信管理局报告。"},{"i":19,"n":"第十九条","txt":"代办电信业务单位（或个人）的服务质量，由委托的电信业务经营者负责，并负责管理和监督检查。"},{"i":20,"n":"第二十条","txt":"电信业务经营者必须配合电信管理机构的检查或调查工作，如实提供有关资料和情况，不得干扰检查或调查活动。"},{"i":21,"n":"第二十一条","txt":"对电信业务经营者违反电信服务标准，并损害用户合法权益的行为，由电信管理机构发出限期整改书；对逾期不改者，视情节轻重给予警告或者处以500元以上、10000元以下罚款。"},{"i":22,"n":"第二十二条","txt":"电信业务经营者妨碍电信管理机构进行监督检查和调查工作或提供虚假资料的，责令改正并予以警告，逾期不改的，处以10000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"电信业务经营者不能按期、如实向电信管理机构报告服务质量自查情况的，给予警告。"},{"i":24,"n":"第二十四条","txt":"电信业务经营者对行政处罚决定不服的，可以向其上一级机关申请复议，对复议决定不服的，可以向人民法院提起诉讼；也可以直接向人民法院提起诉讼。"},{"i":25,"n":"第二十五条","txt":"电信管理机构工作人员对调查所得资料中涉及当事人隐私、商业秘密等事项有保密义务。"},{"i":26,"n":"第二十六条","txt":"电信管理机构工作人员滥用职权、玩忽职守或包庇电信业务经营者侵害用户合法权益的，由其所在部门或上级机关给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"本办法自发布之日起施行。"}],"dianxinyonghushensuchulibanfa":[{"i":1,"n":"第一条","txt":"为了保护电信用户的合法权益，规范用户申诉处理行为，根据《中华人民共和国电信条例》及其他有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于处理用户在接受电信服务的过程中与电信业务经营者发生的争议。"},{"i":3,"n":"第三条","txt":"本办法所称电信管理机构，是指工业和信息化部或省、自治区、直辖市通信管理局。 本办法所称申诉受理机构，是指工业和信息化部电信用户申诉受理中心和省、自治区、直辖市电信用户申诉受理机构。 本办法所称申诉人，是指在使用电信业务、接受电信服务中，与电信业务经营者发生争议并向申诉受理机构提出申诉的电信用户。 本办法所称被申诉人，是指因与用户发生争议而被用户申告的电信业务经营者。"},{"i":4,"n":"第四条","txt":"工业和信息化部对全国电信用户申诉处理工作进行监督指导。工业和信息化部电信用户申诉受理中心受工业和信息化部委托，依据本办法开展全国电信用户申诉受理工作。 省、自治区、直辖市通信管理局可以根据本地实际情况设立电信用户申诉受理机构。电信用户申诉受理机构受省、自治区、直辖市通信管理局的委托并在其监督指导下，依据本办法开展本行政区电信用户申诉受理工作。"},{"i":5,"n":"第五条","txt":"申诉处理以事实为依据，以法律为准绳，坚持公正、合理、合法的原则。"},{"i":6,"n":"第六条","txt":"申诉受理机构对电信用户申诉事项实行调解制度，并可以出具调解书。"},{"i":7,"n":"第七条","txt":"申诉受理机构每季度将受理用户申诉的统计报表上报同级电信管理机构。"},{"i":8,"n":"第八条","txt":"电信业务经营者应当认真受理用户的投诉，并在接到用户投诉之日起15日内答复用户。用户对电信业务经营者的处理结果不满意或者电信业务经营者在接到投诉后15日内未答复的，可以向申诉受理机构提出申诉。"},{"i":9,"n":"第九条","txt":"申诉人应当向被申诉人所在省、自治区、直辖市的申诉受理机构提出申诉。被申诉人所在省、自治区、直辖市没有设立申诉受理机构的，申诉人可以向工业和信息化部电信用户申诉受理中心提出申诉。"},{"i":10,"n":"第十条","txt":"用户申诉应当符合下列条件： （一）申诉人是与申诉事项有直接利害关系的当事人； （二）有明确的被申诉人； （三）有具体的申诉请求和事实根据； （四）已经向被申诉人投诉且对其处理结果不满意或者其未在15日内答复。"},{"i":11,"n":"第十一条","txt":"申诉受理机构对有下列情形之一的申诉事项不予受理： （一）属于收费争议的申诉，申诉事项发生时距提起申诉时超过五个月的，其他申诉，申诉事项发生时距提起申诉时超过二年的； （二）申诉人与被申诉人已经达成和解协议并执行的； （三）申诉受理机构已经受理或者处理的； （四）人民法院、仲裁机构、消费者组织或者其他行政机关已经受理或者处理的； （五）不符合本办法第十条规定的申诉条件的； （六）国家法律、行政法规及部门规章另有规定的。"},{"i":12,"n":"第十二条","txt":"申诉采用书面形式。申诉材料应当包括下列内容： （一）申诉人姓名或名称、地址、电话号码、邮政编码； （二）被申诉人名称、地址； （三）申诉要求、理由、事实根据； （四）申诉日期。"},{"i":13,"n":"第十三条","txt":"申诉受理机构在接到用户申诉时，应当询问用户是否就申诉事项向电信业务经营者提出过投诉，电信业务经营者是否给予处理或答复。 对于未经电信业务经营者处理的用户申诉，申诉受理机构应当告知用户先向电信业务经营者投诉。 对于咨询有关电信政策的用户申诉，申诉受理机构应当向用户作出解答。"},{"i":14,"n":"第十四条","txt":"申诉受理机构应当自收到申诉材料之日起5个工作日内，作出受理或者不予受理的决定，并通知申诉人。对于不予受理的申诉，应当告知不予受理的理由。"},{"i":15,"n":"第十五条","txt":"对于决定受理的用户申诉，申诉受理机构应当在受理用户申诉后2个工作日内将用户申诉内容和转办通知书发送被申诉人。 转办通知书应当载明申诉受理机构名称及联系方式、申诉人名称及联系方式、申诉人的申诉请求摘要、申诉受理机构对申诉处理的要求等。"},{"i":16,"n":"第十六条","txt":"对申诉受理机构要求回复处理意见的，被申诉人收到转办通知书后，应当在10日内将申诉事项的事实情况和处理结果或者处理意见以及申诉人对处理结果的意见（满意程度）反馈给申诉受理机构。"},{"i":17,"n":"第十七条","txt":"申诉受理机构应当自收到全部申诉材料之日起30日内向申诉人作出答复，将申诉处理情况告知申诉人。 对于被申诉人与申诉人协商和解的申诉，申诉受理机构可以作办结处理。 对于被申诉人与申诉人未能协商和解的申诉，应任何一方申请，申诉受理机构在征得对方同意后应当进行调解。"},{"i":18,"n":"第十八条","txt":"对于属于民事争议的下列情形，申诉受理机构可以组织双方当事人进行调解： （一）申诉人与被申诉人已经就申诉事项进行过协商，但未能和解的； （二）申诉人、被申诉人同意由申诉受理机构进行调解的； （三）工业和信息化部规定的其他情形。"},{"i":19,"n":"第十九条","txt":"申诉受理机构应当自争议双方同意调解之日起30日内调解完毕。调解达成协议的，视为办结；调解不成的，应当终止调解并告知申诉人，视为办结。调解达成协议的，应任何一方请求，申诉受理机构应当制作调解书。"},{"i":20,"n":"第二十条","txt":"申诉受理机构调解无效的，争议双方可以依照国家有关法律规定就申诉事项向仲裁机构申请仲裁或者向人民法院提起诉讼。"},{"i":21,"n":"第二十一条","txt":"申诉受理机构可以通过电话、传真、书信以及实地调查等方式向申诉人和被申诉人了解有关情况，要求提供有关证据；申诉受理机构可以根据有关法律、行政法规和部门规章的规定，收集证据或者召集有关当事人进行调查。"},{"i":22,"n":"第二十二条","txt":"申诉受理机构的调查人员有权行使下列权利： （一）询问当事人和有关人员； （二）要求有关单位和个人提供书面材料和证明； （三）要求当事人提供有关技术材料； （四）查阅、复制有关文件等。"},{"i":23,"n":"第二十三条","txt":"调查应当由两名工作人员共同进行，调查时应当出示有效证件和有关证明，并应当制作调查笔录。调查人员对涉及当事人隐私、商业秘密等事项负有保密义务。"},{"i":24,"n":"第二十四条","txt":"被调查人员必须如实回答调查人员的询问，提供相关证据。"},{"i":25,"n":"第二十五条","txt":"申诉受理机构认为需要对有关设备、系统进行检测或者鉴定的，经同级电信管理机构批准后，交由指定检测或者鉴定机构进行检测、鉴定。被申诉的电信业务经营者应当予以配合。"},{"i":26,"n":"第二十六条","txt":"申诉受理机构每季度将受理用户申诉的统计报表向电信业务经营者进行通报。"},{"i":27,"n":"第二十七条","txt":"对于电信用户与公用电信等代办点的争议，电信用户可以向委托代办的电信业务经营者投诉；对于电信用户与宾馆、饭店等电信业务代办点的争议，电信用户可以直接向申诉受理机构提出申诉。"},{"i":28,"n":"第二十八条","txt":"本办法自2016年7月30日起施行。原信息产业部2001年1月11日公布的《电信用户申诉处理暂行办法》（原信息产业部令第7号）同时废止。"}],"dianxinwangmahaoziyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为有效利用电信网码号资源，保障公平竞争，促进电信事业的健康发展，依据《中华人民共和国电信条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内管理和使用电信网码号资源（以下简称码号资源），应当遵守本办法。 本办法所称码号资源,是指由数字、符号组成的用于实现电信功能的用户编号和网络编号。"},{"i":3,"n":"第三条","txt":"码号资源属于国家所有。国家对码号资源实行有偿使用制度，具体收费标准和收费办法另行制定。"},{"i":4,"n":"第四条","txt":"工业和信息化部负责全国码号资源的统一管理工作。 省、自治区、直辖市通信管理局在工业和信息化部授权范围内，依照本办法的规定，对本行政区域内的码号资源实施管理。"},{"i":5,"n":"第五条","txt":"国家对码号资源的使用实行审批制度。 未经工业和信息化部和省、自治区、直辖市通信管理局（以下合称“电信主管部门”）批准，任何单位或者个人不得擅自启用码号资源。"},{"i":6,"n":"第六条","txt":"码号资源管理应当遵循公开、公平、公正的原则，统一规划，集中管理，合理分配，有效利用。"},{"i":7,"n":"第七条","txt":"电信主管部门管理的码号资源范围包括： （一）固定电话网码号 1、长途区号、网号、过网号和国际来话路由码； 2、国际、国内长途字冠； 3、本地网号码中的短号码、接入码、局号等； 4、智能网业务等新业务号码。 （二）移动通信网码号 1、数字蜂窝移动通信网的网号、归属位置识别码、短号码、接入码等； 2、卫星移动通信网网号、归属位置识别码、短号码； 3、标识不同运营者的代码。 （三）数据通信网码号 1、数据网网号； 2、网内紧急业务号码、网间互通号码； 3、国际、国内呼叫前缀。 （四）信令点编码 1、国际No.7信令点编码； 2、国内No.7信令点编码。 工业和信息化部根据电信技术、业务和市场的发展需要，可以对码号资源的管理范围进行调整。"},{"i":8,"n":"第八条","txt":"电信主管部门分配管理的码号资源范围、各种码号的结构、位长、含义和管理要求见本办法所附的《电信网码号资源分类管理目录》（以下简称目录）。 工业和信息化部根据实际情况，可以对该目录作局部调整，重新公布。"},{"i":9,"n":"第九条","txt":"工业和信息化部代表国家向国际电信组织或其它有关机构申请码号资源，提出国际码号资源修改、分配建议。 工业和信息化部授权的机构向国际电信组织或其它有关机构申请码号资源，或提出国际码号资源修改、分配建议，应当向工业和信息化部备案。"},{"i":10,"n":"第十条","txt":"工业和信息化部根据国际电信组织的相关建议，以及电信网网络、技术、业务发展和码号资源使用情况，组织编制全国码号资源规划。各省、自治区、直辖市通信管理局依据工业和信息化部制定的码号资源总体规划，组织编制授权管理的行政区域内码号资源使用规划。"},{"i":11,"n":"第十一条","txt":"申请跨省、自治区、直辖市行政区域范围使用的码号，应当向工业和信息化部提出申请。 申请在省、自治区、直辖市行政区域范围内使用的码号，应当向当地省、自治区、直辖市通信管理局提出申请。 电信主管部门可以委托码号资源咨询受理机构承担码号资源申请的受理工作。"},{"i":12,"n":"第十二条","txt":"码号申请人的资格条件以及可提出使用申请的码号资源范围，参见本办法所附目录。 码号申请人提出码号资源使用申请，应当提交本办法所附目录中要求的申请材料。"},{"i":13,"n":"第十三条","txt":"有下述情形之一的，电信主管部门不受理码号申请： 1、码号申请人不具备本办法所附目录规定的申请人资格的； 2、码号申请人提出的码号资源超出本办法所附目录规定范围的； 3、提交的申请材料不完备的； 4、申请人违反本办法受到电信主管部门的行政处罚，申请人无法定事由拒不履行行政处罚决定的； 5、申请人欠缴码号资源占用费的。"},{"i":14,"n":"第十四条","txt":"电信业务经营者违反本办法，一年内受到工业和信息化部行政处罚1次的，自行政处罚做出之日起一年内，工业和信息化部不受理其码号申请；超过1次的，自第2次行政处罚做出之日起两年内，工业和信息化部不受理其码号申请。 电信业务经营者各省子公司、分公司或其他分支机构违反本办法，一年内受到省、自治区、直辖市通信管理局行政处罚3次的，自第3次行政处罚做出之日起一年内，当地省、自治区、直辖市通信管理局不受理其码号申请，且其不得在当地省、自治区、直辖市行政区域内使用工业和信息化部在此期间分配的码号资源；所受行政处罚超过3次的，自第4次行政处罚做出之日起两年内，当地省、自治区、直辖市通信管理局不受理其码号申请，且其不得在当地省、自治区、直辖市行政区域内使用工业和信息化部在此期间分配的码号资源。"},{"i":15,"n":"第十五条","txt":"电信主管部门应当根据码号资源规划、申请码号的用途和申请人的预期服务能力审批码号。 前款所称预期服务能力，是指申请人申请码号时提出的、表明其在一定时间内服务应当达到的覆盖范围和用户容量等。"},{"i":16,"n":"第十六条","txt":"工业和信息化部应当自收到申请人的申请材料之日起10个工作日内，发出是否受理的通知。自发出受理通知之日起50个工作日内，完成对申请材料的审查，作出批准或不予批准的决定。予以批准的，发给申请人正式批准文件，并抄送相关省、自治区、直辖市通信管理局和相关基础电信业务经营者；不予批准的，书面通知申请人并说明理由。 省、自治区、直辖市通信管理局应当自收到申请人的申请材料之日起10个工作日内，发出是否受理的通知。自发出受理通知之日起30个工作日内，完成对申请材料的审查，作出批准或不予批准的决定。予以批准的，发给申请人正式批准文件，并报工业和信息化部备案；不予批准的，书面通知申请人并说明理由。"},{"i":17,"n":"第十七条","txt":"专用电信网单位应根据网内用户情况申请码号资源，需要使用本地网局号资源的，应向当地省、自治区、直辖市通信管理局提出申请。当地省、自治区、直辖市通信管理局根据本办法第十六条第二款的规定予以办理。 专用电信网单位需要使用千层号、百层号码号资源的，可与当地基础电信业务经营者协商，基础电信业务经营者无正当理由不得拒绝。基础电信业务经营者与专用电信网单位就码号资源的使用达成一致的，应将有关情况向当地省、自治区、直辖市通信管理局备案。 自基础电信业务经营者收到专用电信网单位的协商要求之日起30个工作日内，双方未能达成一致的，任何一方均可以申请当地省、自治区、直辖市通信管理局协调。省、自治区、直辖市通信管理局应当自收到书面申请之日起10个工作日内完成协调，经协调仍不能达成一致的，省、自治区、直辖市通信管理局组织专家公开论证，并作出是否允许专用电信网单位使用千层号、百层号码号资源的决定。"},{"i":18,"n":"第十八条","txt":"码号申请人获准使用码号资源后，电信主管部门可以采用指配、随机选择和拍卖等方式分配码号。 码号资源拍卖管理办法由工业和信息化部另行制定。 电信业务经营者取得码号使用权后，不得向用户收取选号费或占用费。"},{"i":19,"n":"第十九条","txt":"电信业务经营者使用码号资源的期限和范围，应当与电信业务经营许可证或相关批准文件的期限和使用范围相一致。其它码号使用者的使用期限为5年，使用范围由工业和信息化部或省、自治区、直辖市通信管理局根据具体情况确定。 码号使用期限届满或因业务发生变化停用的，码号使用者应自届满或停用之日起10个工作日内上报原码号分配机关。码号使用者需要延长码号使用期、扩大使用范围和改变码号用途的，应当向原码号分配机关办理有关手续。 本办法所称码号使用者，是指获准使用码号资源的电信业务经营者、专用电信网单位、政府部门、社会团体和其它企事业单位等。"},{"i":20,"n":"第二十条","txt":"码号使用者应当在规定的时限内启用所分配的码号。有最低使用规模要求的，应达到规定的最低使用规模；无最低使用规模要求的，应达到预期的服务能力。 前款所称码号最低使用规模，是指码号使用者在规定的时限内利用码号开展业务时应当达到的最低业务覆盖范围和服务能力。 各类码号启用时限和最低使用规模参见本办法所附目录。"},{"i":21,"n":"第二十一条","txt":"码号使用者应当严格按照电信主管部门审批时规定的码号结构、位长、用途、用户拨号方式和使用范围使用码号。 码号使用者不得转让或出租码号，不得超范围或跨本地网使用码号，不得将码号作为商标进行注册；未经工业和信息化部或省、自治区、直辖市通信管理局批准，码号使用者不得擅自改变码号用途。"},{"i":22,"n":"第二十二条","txt":"专用电信网单位使用本地网码号资源实行属地管理。对跨本地网的专用电信网，应根据所跨本地网的服务范围，分别使用所属本地网的码号资源；本地网内的专用电信网应使用所属本地网码号资源。"},{"i":23,"n":"第二十三条","txt":"码号使用者从工业和信息化部获得码号使用权后，应与相关基础电信业务经营者总公司协商签署码号开通协议。相关基础电信业务经营者总公司应自协议签署之日起10个工作日内，通知码号使用范围内所有子公司或者其他分支机构，配合码号使用者开通码号。 码号使用者对规定范围内码号开通的前期工作准备就绪后，应持工业和信息化部的批准文件和备案材料（包括码号启用技术方案、码号启用前期准备情况、码号启用实施进度安排和联系方式）向当地省、自治区、直辖市通信管理局备案。省、自治区、直辖市通信管理局应当自收齐上述材料之日起10个工作日内，向本地相关电信业务经营者和专用电信网单位发出备案通知。 各本地网内相关电信业务经营者或专用电信网单位应自码号使用者提出开通码号的书面要求和当地省、自治区、直辖市通信管理局备案通知收齐之日起10个工作日内，配合码号使用者完成局数据制作，开通码号，并在码号开通后5个工作日内将开通情况报当地省"},{"i":24,"n":"第二十四条","txt":"码号使用者从省、自治区、直辖市通信管理局获得码号使用权后，应当与省、自治区、直辖市内相关基础电信业务经营者协商签署码号开通协议。相关基础电信业务经营者应自协议签署之日起10个工作日内，通知码号使用范围内所有子公司或者其他分支机构，配合码号使用者开通码号，并在码号开通后5个工作日内将开通情况报当地省、自治区、直辖市通信管理局。 各本地网内相关电信业务经营者或专用电信网单位应自码号使用者提出开通码号的书面要求和当地省、自治区、直辖市通信管理局的批准文件收齐之日起10个工作日内，配合码号使用者完成局数据制作，开通码号。"},{"i":25,"n":"第二十五条","txt":"码号使用者应当有效使用码号资源。电信业务经营者和专用电信网单位应于每年3月底前向原码号分配机关报告上年度码号资源使用情况和本年度码号资源使用需求。上报工业和信息化部的报告应同时抄报当地通信管理局。 报告的内容应当包括： （一）码号启用时间、范围或数量； （二）业务种类和服务能力； （三）本企业（或单位）本年度电信网络、业务发展对码号资源的需求。"},{"i":26,"n":"第二十六条","txt":"电信主管部门应当向社会公布码号资源分配和使用情况，并对使用情况实施监督检查。 码号使用者改变地址或联系方式的，应在变更后10个工作日内通知原码号分配机关。"},{"i":27,"n":"第二十七条","txt":"电信主管部门对本地网用户电话号码升位实行计划管理，对局部用户号码调整实行备案管理，对长途编号区调整和短号码位长拓展实行审批管理。 未经工业和信息化部批准，任何单位和个人不得擅自调整长途编号区。具体长途编号区调整管理办法另行制定。"},{"i":28,"n":"第二十八条","txt":"达到下列条件之一的，当地主导的电信业务经营者应当向其总公司提出本地网用户电话号码7位升8位计划，并同时报当地通信管理局： （一）在7位编号本地网中，交换机容量达到120万门，局号利用率达到35%的； （二）根据未来10年城市发展规划和电信网发展规划，交换机容量达到350万门，局号利用率达到30%的； （三）尚未完全达到第（一）项、第（二）项条件，但由于城市发展，使原7位编号的某些P位局号严重紧张的； （四）因城市信息化发展的需要以及基础电信业务经营者对电信网能力和新业务需求的增加，要求升8位的。"},{"i":29,"n":"第二十九条","txt":"符合本办法第二十八条规定升8位条件，当地主导的电信业务经营者未提出升位计划的，当地通信管理局也可以提出升位建议。省、自治区通信管理局向工业和信息化部提出下年度用户电话号码升位建议的，应提前征求当地基础电信业务经营者意见，并于每年3月底前上报下年度需升位的本地网名称和各本地网升位建议。工业和信息化部收到省、自治区通信管理局升位建议后，初审符合本地网升位条件的，应通知相关基础电信业务经营者总公司和当地省、自治区通信管理局。"},{"i":30,"n":"第三十条","txt":"本地网全网升位实施方案由所在本地网主导电信业务经营者总公司负责组织制订。当地主导电信业务经营者总公司应于每年8月底前统一将下年度需升位的本地网名称和各本地网具体升位实施方案报工业和信息化部。 前款所称升位实施方案的主要内容应当包括： （一）码号使用现状及码号升位的必要性； （二）未来5年、10年城市发展对号码资源的需求； （三）号码升位技术方案和宣传方案； （四）号码升位实施进度和宣传方案； （五）技术保证措施； （六）需要其它电信业务经营者配合的技术方案。 制定升位实施方案时，需要其他电信业务经营者配合的，省、自治区、直辖市通信管理局应负责协调。"},{"i":31,"n":"第三十一条","txt":"工业和信息化部收到当地主导电信业务经营者总公司升位实施方案后，当年9月组织专家和基础电信业务经营者论证。经论证升位实施方案周密可行的，工业和信息化部列入下年度升位计划，于当年11月底前向社会公布，并通知相关基础电信业务经营者总公司做好升位前期准备和按时实施工作。"},{"i":32,"n":"第三十二条","txt":"具体升位方案由当地主导电信业务经营者总公司负责组织实施，其他基础电信业务经营者总公司和专用电信网单位应予以配合，根据实施方案统一组织对本企业网络进行同步调整。 在号码升位方案具体实施中，当地通信管理局负责对行政区域内基础电信业务经营者和专网单位进行协调和监督，并在升位方案实施之前至少20个工作日组织现场测试。 在协调、监督和现场测试过程中发现可能影响升位的问题时，当地通信管理局应在5个工作日内报工业和信息化部。"},{"i":33,"n":"第三十三条","txt":"电信业务经营者利用电信主管部门分配的码号资源提供电信业务时，应当保证电信用户的合法权益，不得随意更改调整号码。 电信业务经营者对局部用户号码进行调整的，应制订周密的调整方案，并将局部用户号码调整实施方案和用户权益保障措施提前向原码号分配机关备案。"},{"i":34,"n":"第三十四条","txt":"拓展短号码位长的，码号使用者应向原码号分配机关提出申请，并报送相应拓展方案、技术实施方案和用户权益保障措施。 原码号分配机关自收到申请之日起30个工作日内，对申请人提交的申请和实施方案审查完毕，作出批准或不予批准的决定。予以批准的，发给申请人正式批准文件，并通知相关基础电信业务经营者；不予批准的，书面通知申请人并说明理由。"},{"i":35,"n":"第三十五条","txt":"工业和信息化部根据码号资源情况，可以组织本地网用户电话号码升位、本地网长途编号区调整、短号码位长拓展和其它码号调整。省、自治区、直辖市通信管理局可以组织对授权管理的码号进行调整和位长拓展。 工业和信息化部或省、自治区、直辖市通信管理局要求或批准进行的本地网用户电话号码升位、长途编号区调整、短号码位长拓展和其它码号调整，电信用户和相关码号使用者应当予以配合。"},{"i":36,"n":"第三十六条","txt":"本地网用户电话号码升位、短号码位长拓展和其它码号调整产生的码号资源，由工业和信息化部或省、自治区、直辖市通信管理局统一规划，重新分配。"},{"i":37,"n":"第三十七条","txt":"本地网用户电话号码升位后，国际、国内长途来话（含IP来话）新旧号码并存服务时间为2个月，号码并存补位和冲突检测，由升位的本地网承担。并存期届满后，各基础电信业务经营者应对国际、国内长途来话（含IP来话）在网内实施拦截和语音提示，语音提从示服务时间为3个月。 短号码位长拓展和局部用户号码调整的，码号使用者应至少提前45天向用户公告；短号码位长拓展和局部用户号码调整后，码号使用者应提示来话，来话提示服务时间不得少于45天。短号码位长拓展需要新、旧号码并存服务的，相关基础电信业务经营者应予以配合。"},{"i":38,"n":"第三十八条","txt":"工业和信息化部或省、自治区、直辖市通信管理局在码号资源管理中，发现有下列情形之一的，可以收回已分配的码号资源： （一）已终止占用码号资源的业务的； （二）在规定时间内未启用码号资源的； （三）以欺诈手段获得码号资源的； （四）超过规定期限使用码号资源的； （五）改变电信主管部门从规定的码号结构、位长、拨号方式和使用范围使用码号资源的； （六）擅自启用、扩大范围、改变用途、改变长途编号区或跨本地网使用用户号码资源的； （七）转让、出租码号资源或将码号作为商标进行注册的； （八）拒不按照规定缴纳码号资源使用费的； （九）拒不执行电信主管部门的码号调整要求的。"},{"i":39,"n":"第三十九条","txt":"电信主管部门决定收回的码号，相关基础电信业务经营者应按照电信主管部门的要求在规定的时间内对码号局数据进行调整。"},{"i":40,"n":"第四十条","txt":"违反本办法的规定有下列情形之一的，工业和信息化部或者省、自治区、直辖市通信管理局责令改正，视情节轻重可以给予警告，并处5000元以上3万元以下的罚款： （一）以欺诈手段获得码号资源的； （二）无正当理由拒绝专用电信网单位对码号资源需求的； （三）向用户收取选号费或占用费的； （四）改变用户拨号方式的，或将码号作为商标擅自进行注册的； （五）未按照规定时间启用码号或未达到最低使用规模或预期服务能力的； （六）未按规定报告码号从资源使用情况的； （七）未按规定向电信主管部门备案的； （八）未按规定配合码号使用者制作局数据，开通码号的； （九）未按规定组织或配合本地网号码升位方案制订或实施的； （十）不配合或不按规定配合电信主管部门要求或批准进行的本地网号码升位、长途编号区调整、号码位长拓展和码号调整的； （十一）未按规定保护电信用户号码使用权益的。"},{"i":41,"n":"第四十一条","txt":"违反本办法，有下列情形之一的，由工业和信息化部或者省、自治区、直辖市通信管理局依据《中华人民共和国电信条例》第七十条的规定责令改正，没收违法所得，处违法所得3倍以上5倍以下罚款；没有违法所得或者违法所得不足5万元的，处１0万元以上100万元以下罚款： （一）擅自启用码号资源的； （二）擅自拓展号码位长使用的； （三）超过规定的使用期限继续使用码号资源的； （四）擅自改变长途编号区或跨本地网使用用户号码资源的； （五）擅自转让、出租或变相转让、出租码号资源的； （六）擅自改变码号资源用途的。"},{"i":42,"n":"第四十二条","txt":"当事人对工业和信息化部或省、自治区、直辖市通信管理局行政处罚决定不服的，可依法申请行政复议或者向人民法院提起诉讼。"},{"i":43,"n":"第四十三条","txt":"从事码号资源管理的工作人员玩忽职守，滥用职权，徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":44,"n":"第四十四条","txt":"未与公用电信网互联的专用电信网的用户编号和网络编号资源管理，不适用本办法。"},{"i":45,"n":"第四十五条","txt":"本办法自2003年3月1日起施行。信息产业部2000年4月25日发布的《电信网码号资源管理暂行办法》（信息产业部令第1号）同时废止。 附件：电信网码号资源分类管理目录.doc"}],"dianxinwangjianhulianzhengyichulibanfa":[{"i":1,"n":"第一条","txt":"为了妥善处理电信网间互联争议，保障电信网各方的合法权益，提高电信网的综合效益，根据《中华人民共和国电信条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内的基础电信业务经营者之间及其与专用电信网单位（以下简称 “ 专用网单位” ）之间发生的下列电信网间的互联争议： （一）因互联技术方案而产生的争议； （二）因与互联有关的网络功能及通信设施的提供而产生的争议； （三）因互联时限而产生的争议； （四）因电信业务的提供而产生的争议； （五）因网间通信质量而产生的争议； （六）因与互联有关的费用而产生的争议； （七）信息产业部规定应当依照本办法处理的其他电信网间互联争议。"},{"i":3,"n":"第三条","txt":"信息产业部负责全国电信网间互联争议处理协调、指导和监督。信息产业部电信管理局具体负责对经营全国性基础电信业务公司总部之间及其与跨省、自治区、直辖市专用网单位之间的互联争议的处理。 省、自治区、直辖市通信管理局负责对全国性基础电信业务公司总部以下的经营机构之间及其与专用电信网单位之间的互联争议的处理。"},{"i":4,"n":"第四条","txt":"基础电信业务经营者和专用网单位是电信网间互联争议的当事人。"},{"i":5,"n":"第五条","txt":"处理电信网间互联争议应当遵循下列原则： （一）着重协调，及时处理； （二）以事实为基础，以法律、行政法规和部门规章为依据； （三）当事人在适用法律、行政法规和部门规章上一律平等。"},{"i":6,"n":"第六条","txt":"发生电信网间互联争议，争议双方当事人应当协商解决；协商不成的，可以向信息产业部或者省、自治区、直辖市通信管理局（以下简称 “ 电信主管部门 ” ）申请协调；协调不成的，由电信主管部门作出行政决定；对行政决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":7,"n":"第七条","txt":"基础电信业务经营者之间及其与专用网单位之间发生互联争议，经双方当事人协商解决不成的，其中任何一方均可以向电信主管部门提出互联争议协调申请。 互联争议协调申请应当以书面形式提出（电信网间互联争议协调申请书格式附后）"},{"i":8,"n":"第八条","txt":"电信主管部门收到互联争议协调申请书后，对协调申请书的内容进行初步审查。经审查发现申请协调的争议不符合本办法第二条规定的范围或者不属于本办法第三条规定的管辖范围的，应当在 5 个工作日内书面答复不予受理或告知由相关机构处理。经审查符合本办法规定要求的，电信主管部门应当在 7 日内正式开始进行协调。"},{"i":9,"n":"第九条","txt":"电信主管部门的协调工作按下列程序进行： （一）听取争议双方的陈述，确定主要分歧，开展必要的调查研究，提出初步协调意见。如争议双方接受初步协调意见，则结束协调工作。 （二）如争议一方或双方均不接受初步协调意见的，在征求争议双方的相关主管部门意见或有关专家意见后，提出最后协调意见，结束协调工作。 协调阶段应当自开始协调之日起 45 日内结束"},{"i":10,"n":"第十条","txt":"电信主管部门在协调的每个阶段，均应当出具《电信网间互联争议协调意见书》（格式附后）正本一式三份，副本若干份。正本由争议双方各执一份，电信主管部门存档一份。 省、自治区、直辖市通信管理局出具的《电信网间互联争议协调意见书》副本应当报信息产业部备案。"},{"i":11,"n":"第十一条","txt":"协调不能使争议双方达成协议的，电信主管部门应当根据不同类型的互联争议，随机邀请电信技术、经济、法律方面的专家进行公开论证。电信主管部门至少应当在论证前 7 日向应邀专家通报论证事项和有关情况。"},{"i":12,"n":"第十二条","txt":"论证会由下列人员参加： （一）电信主管部门的代表； （二）电信技术、经济、法律方面的专家； （三）争议双方当事人。 必要时，可以邀请新闻单位参加。 论证会由电信主管部门主持。"},{"i":13,"n":"第十三条","txt":"处理互联争议邀请的专家由电信技术、经济、法律方面的专家组成。 每次论证会邀请的电信技术、经济、法律专家不少于 5 人。"},{"i":14,"n":"第十四条","txt":"论证会应当遵循下列程序进行： （一）争议双方的陈述； （二）电信主管部门对争议协调的意见； （三）专家发表论证意见或建议，并提出网间互联争议解决方案。 在论证期间，对需要进一步由有关方面说明的情况或需要现场调查的项目，由电信主管部门组织调查研究，并请专家再次论证和提出网间互联争议解决方案。"},{"i":15,"n":"第十五条","txt":"电信主管部门应当根据所邀专家的公开论证结论和提出的网间互联争议解决方案，在 45 日内作出行政决定。 电信主管部门作出行政决定应当充分尊重专家的论证意见和建议。对未予采纳的建议和意见，应当向专家作出说明，但涉及国家机密的除外。 行政决定一般应由电信主管部门领导集体讨论决定，由主要负责人签署。 行政决定作出后，应当向信息产业部行政复议机构备案。 电信主管部门对作出的行政决定应当以适当方式向社会公布。"},{"i":16,"n":"第十六条","txt":"互联双方在电信主管部门作出的行政决定前，可以自行达成互联协议，并报电信主管部门备案。"},{"i":17,"n":"第十七条","txt":"行政决定作出后，争议双方应当在决定规定的时限内自觉履行。"},{"i":18,"n":"第十八条","txt":"争议一方或双方对行政决定不服，可以依法申请行政复议或者提起行政诉讼。行政复议或行政诉讼期间，行政决定不停止执行。"},{"i":19,"n":"第十九条","txt":"违反本办法规定，拒不执行电信主管部门依法作出的互联争议解决行政决定的，由电信主管部门依据《中华人民共和国电信条例》第七十三条的规定予以处罚。"},{"i":20,"n":"第二十条","txt":"处理互联争议的电信主管部门工作人员在互联争议处理活动中，徇私舞弊、收受贿赂、滥用职权、泄露秘密，构成犯罪的，依法追究刑事责任；尚未构成犯罪的，依法给予行政处分。"},{"i":21,"n":"第二十一条","txt":"本办法自 2002 年 1 月 1 日起施行。"}],"dianxinshebeijinwangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了保证公用电信网的安全畅通，加强电信设备进网管理，维护电信用户和电信业务经营者的合法权益，根据《中华人民共和国电信条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称电信设备是指电信终端设备、无线电通信设备和涉及网间互联的设备。 电信终端设备是指连接在公用电信网末端，为用户提供发送和接收信息功能的电信设备。 无线电通信设备是指连接在公用电信网上，以无线电为通信手段的电信设备。 涉及网间互联的设备是指涉及不同电信业务经营者的网络之间或者不同电信业务的网络之间互联互通的电信设备。"},{"i":3,"n":"第三条","txt":"国家对接入公用电信网的电信终端设备、无线电通信设备和涉及网间互联的电信设备实行进网许可制度。 实行进网许可制度的电信设备必须获得工业和信息化部颁发的进网许可证；未获得进网许可证的，不得接入公用电信网使用和在国内销售。"},{"i":4,"n":"第四条","txt":"实行进网许可制度的电信设备目录由工业和信息化部会同国务院产品质量监督部门制定和公布。"},{"i":5,"n":"第五条","txt":"电信设备生产企业（以下简称生产企业）申请电信设备进网许可必须符合国家法律、法规和政策规定。申请进网许可的电信设备必须符合国家标准、通信行业标准以及工业和信息化部的规定。电信设备生产企业应当具有完善的质量保证体系和售后服务措施。"},{"i":6,"n":"第六条","txt":"生产企业申请电信设备进网许可，应当附送国务院产品质量监督部门认可的电信设备检测机构出具的检测报告或者认证机构出具的产品认证证书。 检测机构对申请进网许可的电信设备进行检测的依据、检测规程和出具的检测报告应当符合国家或工业和信息化部的规定。"},{"i":7,"n":"第七条","txt":"工业和信息化部电信管理局具体负责全国电信设备进网管理和监督检查工作。 省、自治区、直辖市通信管理局负责本行政区域内电信设备进网管理和监督检查工作。 经工业和信息化部授权的受理机构承担电信设备进网许可申请的具体受理事宜。"},{"i":8,"n":"第八条","txt":"生产企业申请电信设备进网许可，应当向工业和信息化部授权的受理机构提交下列申请材料： （一）电信设备进网许可申请表（由工业和信息化部提供格式文本）。申请表应当由生产企业法定代表人或其授权人签字并加盖公章。境外生产企业应当委托中国境内的代理机构提交申请表，并出具委托书； （二）企业法人营业执照。境内生产企业应当提供企业法人营业执照。受境外生产企业委托代理申请电信设备进网许可的代理机构，应当提供代理机构有效执照； （三）企业情况介绍。包括企业概况、生产条件、仪表配备、质量保证体系和售后服务措施等内容。对国家规定包修、包换和包退的产品，还应提供履行有关责任的文件； （四）质量体系认证证书或审核报告。通过质量体系认证的，提供认证证书；未通过质量体系认证的，提供满足相关要求的质量体系审核机构出具的质量体系审核报告； （五）电信设备介绍。包括设备功能、性能指标、原理框图、内外观照片和使用说明等内容；"},{"i":9,"n":"第九条","txt":"自受理机构收到完备的申请材料之日起60日内，工业和信息化部电信管理局对生产企业提交的申请材料进行审查，经审查符合条件的，颁发进网许可证并核发进网许可标志；不符合条件的，书面答复生产企业。"},{"i":10,"n":"第十条","txt":"生产企业通过质量体系认证的，其提供检测机构检测的样品由生产企业按规定数量自行选取。 生产企业未通过质量体系认证的，其提供检测机构检测的样品由省、自治区、直辖市通信管理局按工业和信息化部规定的抽样办法执行。"},{"i":11,"n":"第十一条","txt":"申请进网许可的无线电通信设备、涉及网间互联的设备或者新产品，应当在中国境内的电信网上或者工业和信息化部指定的模拟实验网上进行至少三个月的试验，并由试验单位出具试验报告。 工业和信息化部电信管理局组织专家对前款电信设备总体技术方案、试验报告、检测报告等进行评审，根据专家评审意见，经审查符合条件的，颁发进网许可证。"},{"i":12,"n":"第十二条","txt":"生产企业对获得进网许可证的电信设备进行技术、外型改动的，须进行检测或重新办理进网许可证。 对获得进网许可证的电信设备外型改动较小，生产企业要求减免测试项目的，可以将改动前后的照片、电路原理图、改动说明和改动后的样品等交检测机构进行审核。检测机构向工业和信息化部电信管理局出具审核意见，检测机构审核认为可以减免测试项目的，经工业和信息化部电信管理局同意，可以减免测试项目。"},{"i":13,"n":"第十三条","txt":"实行进网许可制度但尚无国家标准、行业标准的电信新设备，由生产企业自行将样品送到检测机构，检测机构根据国际标准或者企业标准进行检测，并出具检测报告。 工业和信息化部电信管理局对检测报告和有关材料进行审查，在符合国家产业政策和不影响网络安全畅通的条件下，批准进网试验，待国家标准、行业标准颁布后再按程序办理进网许可证。"},{"i":14,"n":"第十四条","txt":"我国与其它国家或地区政府间签署电信设备检测实验室和检测报告相互认可协议的，按协议规定执行。"},{"i":15,"n":"第十五条","txt":"生产企业应当在其获得进网许可的电信设备上粘贴进网许可标志。进网许可标志由工业和信息化部统一印制和核发。进网许可标志属于质量标志。 未获得进网许可和进网许可证失效的电信设备上不得加贴进网许可标志。"},{"i":16,"n":"第十六条","txt":"进网许可证和进网许可标志不得转让、涂改、伪造和冒用。"},{"i":17,"n":"第十七条","txt":"进网许可证的有效期为3年。 生产企业需要继续生产和销售已获得进网许可的电信设备的，在进网许可证有效期届满前三个月，应当重新申请办理进网许可证，并附送一年内的送样检测报告或产品质量监督抽查报告，原证交回。"},{"i":18,"n":"第十八条","txt":"电信设备进网许可证中规定的内容发生变化的，生产企业应当重新办理进网许可证。"},{"i":19,"n":"第十九条","txt":"获得进网许可证的生产企业应当向其经销商以及需要进网许可证复印件的用户提供复印件，复印件应当由生产企业负责人签字并加盖公章。生产企业应当对复印件编号登记。"},{"i":20,"n":"第二十条","txt":"生产企业应当在获得进网许可的电信设备包装上和刊登的广告中标明进网许可证编号。"},{"i":21,"n":"第二十一条","txt":"工业和信息化部定期向社会公布获得进网许可证的电信设备和生产企业。 获得进网许可证的生产企业应当接受所在的省、自治区、直辖市通信管理局的监督管理。 任何单位不得对已获得进网许可证的电信设备进行重复检测、发证。"},{"i":22,"n":"第二十二条","txt":"省、自治区、直辖市通信管理局应当于每年12月31日前，对本行政区域内获得进网许可的电信设备和生产企业进行年度检查，并于第二年1月31日前，将年度检查情况汇总报工业和信息化部电信管理局。"},{"i":23,"n":"第二十三条","txt":"获得电信设备进网许可证的生产企业应当保证电信设备获得进网许可证前后的一致性，保证产品质量稳定、可靠，不得降低产品质量和性能。 工业和信息化部组织对电信设备获得进网许可证前后的一致性进行监督检查；配合国务院产品质量监督部门对获得进网许可证的电信设备进行质量跟踪和监督抽查，并向社会公布抽查结果。"},{"i":24,"n":"第二十四条","txt":"获得进网许可的电信设备及其外包装必须标有国家规定的中文标识；产品必须附有中文说明书和保修卡；对国家规定包修、包换和包退的产品，还应有相应的凭证。"},{"i":25,"n":"第二十五条","txt":"实行进网许可制度的电信设备未获得进网许可的，电信业务经营者不得使用。"},{"i":26,"n":"第二十六条","txt":"用户有权自主选择电信终端设备，电信业务经营者不得拒绝用户使用自备的已经取得进网许可的电信终端设备。"},{"i":27,"n":"第二十七条","txt":"电信设备检测机构或产品质量认证机构必须执行国家标准、行业标准和工业和信息化部规定。检测机构或产品质量认证机构及其工作人员不得弄虚作假，不得利用职务之便剽窃或泄露生产企业的技术秘密。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，销售未获得进网许可的电信终端设备的，由省、自治区、直辖市通信管理局责令改正，并处1万元以上10万元以下罚款。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，伪造、冒用、转让进网许可证，编造进网许可证编号或粘贴伪造的进网许可标志的，由工业和信息化部或者省、自治区、直辖市通信管理局没收违法所得，并处违法所得3倍以上5倍以下罚款；没有违法所得或者违法所得不足1万元的，处1万元以上10万元以下罚款。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，生产企业获得进网许可证后降低产品质量和性能的，由产品质量监督部门依照有关法律法规予以处罚。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，生产企业未在获得进网许可的设备外包装和刊登的广告中注明进网许可证编号的，由工业和信息化部或者省、自治区、直辖市通信管理局责令改正，并给予警告。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，生产企业有下列行为之一的，由工业和信息化部或者省、自治区、直辖市通信管理局责令限期改正；情节严重的，给予警告： （一）申请进网许可时提供不真实申请材料的； （二）不能保证电信设备获得进网许可证前后的一致性的； （三）售后服务不落实，对国家规定包修、包换和包退的产品不履行相应义务的； （四）不按规定参加年检或者年检结果不合格的； （五）不接受工业和信息化部对电信设备获得进网许可证前后的一致性组织进行的监督检查或者检查结果不合格的。 违反前款第一项规定，尚未取得进网许可证的，工业和信息化部不予受理或者不予许可，生产企业在一年内不得再次申请进网许可；已取得进网许可证的，工业和信息化部撤销进网许可证，生产企业在三年内不得再次申请进网许可。"},{"i":33,"n":"第三十三条","txt":"违反本办法规定，电信业务经营者拒绝用户自备的获得进网许可的电信终端设备进网的，由省、自治区、直辖市通信管理局责令改正，并向电信用户赔礼道歉，赔偿电信用户损失；拒不改正并赔礼道歉、赔偿损失的，处以警告，并处1万元以上10万元以下的罚款；情节严重的，责令停业整顿。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定，对已获得进网许可证的电信设备进行重复检测、发证的，由工业和信息化部责令改正。"},{"i":35,"n":"第三十五条","txt":"违反本办法规定，检测机构、产品质量认证机构有下列行为之一的，工业和信息化部对其出具的检测报告或认证证书不予承认: （一）弄虚作假，有作弊行为的； （二）不按规定标准进行检测或认证的； （三）不按工业和信息化部规定出具检测报告或认证证书的。"},{"i":36,"n":"第三十六条","txt":"从事电信设备进网许可申请受理、检测、审批及有关工作的人员滥用职权、徇私舞弊或者利用职务之便剽窃、泄露生产企业技术秘密的，依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"对进入公用电信网的电信设备抗震性能的管理办法，工业和信息化部另行制定。"},{"i":38,"n":"第三十八条","txt":"未实行进网许可制度的电信设备可以由生产企业自愿向国务院产品质量监督部门认可的电信设备进网认证机构申请产品认证。"},{"i":39,"n":"第三十九条","txt":"本办法自发布之日起施行。1998年12月31日信息产业部发布的《电信设备进网审批管理办法》同时废止。"}],"dianqidianzichanpinyouhaiwuzhixianzhishiyongguanli37cafa-2":[{"i":1,"n":"第一条","txt":"为了控制和减少电器电子产品废弃后对环境造成的污染，促进电器电子行业清洁生产和资源综合利用，鼓励绿色消费，保护环境和人体健康，根据《中华人民共和国清洁生产促进法》、《中华人民共和国固体废物污染环境防治法》、《废弃电器电子产品回收处理管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、销售和进口电器电子产品，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法下列术语的含义是： （一）电器电子产品，是指依靠电流或电磁场工作或者以产生、传输和测量电流和电磁场为目的，额定工作电压为直流电不超过1500伏特、交流电不超过1000伏特的设备及配套产品。其中涉及电能生产、传输和分配的设备除外。 （二）电器电子产品污染，是指电器电子产品中含有的有害物质超过国家标准或行业标准，对环境、资源、人类身体健康以及生命、财产安全造成破坏、损害、浪费或其他不良影响。 （三）电器电子产品有害物质限制使用，是指为减少或消除电器电子产品污染而采取的下列措施： 1．设计、生产过程中，通过改变设计方案、调整工艺流程、更换使用材料、革新制造方式等限制使用电器电子产品中的有害物质的技术措施； 2．设计、生产、销售以及进口过程中，标注有害物质名称及其含量，标注电器电子产品环保使用期限等措施； 3．销售过程中，严格进货渠道，拒绝销售不符合电器电子产品有害物质限制使用国家标准或"},{"i":4,"n":"第四条","txt":"工业和信息化部、发展改革委、科技部、财政部、环境保护部、商务部、海关总署、质检总局在各自的职责范围内对电器电子产品有害物质限制使用进行管理和监督。"},{"i":5,"n":"第五条","txt":"工业和信息化部会同国务院有关主管部门制定有利于电器电子产品有害物质限制使用的措施，落实电器电子产品有害物质限制使用的有关规定。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市工业和信息化、发展改革、科技、财政、环境保护、商务、海关、质检等主管部门在各自的职责范围内，对电器电子产品有害物质限制使用实施监督管理。 省、自治区、直辖市工业和信息化主管部门负责牵头建立省级电器电子产品有害物质限制使用工作协调机制，负责协调解决本行政区域内电器电子产品有害物质限制使用工作中的重大事项及问题。"},{"i":7,"n":"第七条","txt":"国家鼓励、支持电器电子产品有害物质限制使用的科学研究、技术开发和国际合作，积极推广电器电子产品有害物质替代与减量化等技术、装备。"},{"i":8,"n":"第八条","txt":"工业和信息化部、国务院有关主管部门对积极开发、研制严于本办法规定的电器电子产品的组织和个人，可以给予表扬或奖励。 省、自治区、直辖市工业和信息化主管部门和其他相关主管部门对在电器电子产品有害物质限制使用工作以及相关活动中做出显著成绩的组织和个人，可以给予表扬或奖励。"},{"i":9,"n":"第九条","txt":"电器电子产品设计者在设计电器电子产品时，不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，在满足工艺要求的前提下应当按照电器电子产品有害物质限制使用国家标准或行业标准，采用无害或低害、易于降解、便于回收利用等方案。"},{"i":10,"n":"第十条","txt":"电器电子产品生产者在生产电器电子产品时，不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，应当按照电器电子产品有害物质限制使用国家标准或行业标准，采用资源利用率高、易回收处理、有利于环境保护的材料、技术和工艺，限制或者淘汰有害物质在产品中的使用。 电器电子产品生产者不得将不符合本办法要求的电器电子产品出厂、销售。"},{"i":11,"n":"第十一条","txt":"进口的电器电子产品不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，应当符合电器电子产品有害物质限制使用国家标准或行业标准。 出入境检验检疫机构依法对进口的电器电子产品实施口岸验证和法定检验。海关验核出入境检验检疫机构签发的《入境货物通关单》并按规定办理通关手续。"},{"i":12,"n":"第十二条","txt":"电器电子产品生产者、进口者制作、使用电器电子产品包装物时，不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，应当采用无害、易于降解和便于回收利用的材料，遵守包装物使用的国家标准或行业标准。"},{"i":13,"n":"第十三条","txt":"电器电子产品生产者、进口者应当按照电器电子产品有害物质限制使用标识的国家标准或行业标准，对其投放市场的电器电子产品中含有的有害物质进行标注，标明有害物质的名称、含量、所在部件及其产品可否回收利用，以及不当利用或者处置可能会对环境和人类健康造成影响的信息等；由于产品体积、形状、表面材质或功能的限制不能在产品上标注的，应当在产品说明中注明。"},{"i":14,"n":"第十四条","txt":"电器电子产品生产者、进口者应当按照电器电子产品有害物质限制使用标识的国家标准或行业标准，在其生产或进口的电器电子产品上标注环保使用期限；由于产品体积、形状、表面材质或功能的限制不能在产品上标注的，应当在产品说明中注明。"},{"i":15,"n":"第十五条","txt":"电器电子产品的环保使用期限由电器电子产品的生产者或进口者自行确定。相关行业组织可根据技术发展水平，制定包含产品类目、确定方法、具体期限等内容的相关电器电子产品环保使用期限的指导意见。 工业和信息化部鼓励相关行业组织将制定的电器电子产品环保使用期限的指导意见报送工业和信息化部。"},{"i":16,"n":"第十六条","txt":"电器电子产品销售者不得销售违反电器电子产品有害物质限制使用国家标准或行业标准的电器电子产品。"},{"i":17,"n":"第十七条","txt":"电器电子产品有害物质限制使用采取目录管理的方式。工业和信息化部根据产业发展的实际状况，商发展改革委、科技部、财政部、环境保护部、商务部、海关总署、质检总局编制、调整、发布达标管理目录。"},{"i":18,"n":"第十八条","txt":"国家建立电器电子产品有害物质限制使用合格评定制度。纳入达标管理目录的电器电子产品，应当符合电器电子产品有害物质限制使用限量要求的国家标准或行业标准，按照电器电子产品有害物质限制使用合格评定制度进行管理。 工业和信息化部根据电器电子产品有害物质限制使用工作整体安排，向国家认证认可监督主管部门提出建立电器电子产品有害物质限制使用合格评定制度的建议。国家认证认可监督主管部门依据职能会同工业和信息化部制定、发布并组织实施合格评定制度。工业和信息化部根据实际情况，会同财政部等部门对合格评定结果建立相关采信机制。"},{"i":19,"n":"第十九条","txt":"违反本办法，有下列情形之一的，由商务、海关、质检等部门在各自的职责范围内依法予以处罚： （一）电器电子产品生产者违反本办法第十条的规定，所采用的材料、技术和工艺违反电器电子产品有害物质限制使用国家标准或行业标准的，以及将不符合本办法要求的电器电子产品出厂、销售的； （二）电器电子产品进口者违反本办法第十一条的规定，进口的电器电子产品违反电器电子产品有害物质限制使用国家标准或行业标准的； （三）电器电子产品生产者、进口者违反本办法第十二条的规定，制作或使用的电器电子产品包装物违反包装物使用国家标准或行业标准的； （四）电器电子产品生产者、进口者违反本办法第十三条的规定，未标注电器电子产品有害物质的名称、含量、所在部件及其产品可否回收利用，以及不当利用或者处置可能会对环境和人类健康造成影响等信息的； （五）电器电子产品生产者、进口者违反本办法第十四条的规定，未标注电器电子产品环保使用期限的"},{"i":20,"n":"第二十条","txt":"有关部门的工作人员滥用职权，徇私舞弊，纵容、包庇违反本办法规定的行为的，或者帮助违反本办法规定的当事人逃避查处的，依法给予行政处分。"},{"i":21,"n":"第二十一条","txt":"任何组织和个人有权对违反本办法规定的行为向有关部门投诉、举报。"},{"i":22,"n":"第二十二条","txt":"本办法由工业和信息化部商发展改革委、科技部、财政部、环境保护部、商务部、海关总署、质检总局解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2016年7月1日起施行。2006年2月28日公布的《电子信息产品污染控制管理办法》（原信息产业部、发展改革委、商务部、海关总署、工商总局、质检总局、原环保总局令第39号）同时废止。"}],"dianqidianzichanpinyouhaiwuzhixianzhishiyongguanli37cafa":[{"i":1,"n":"第一条","txt":"为了控制和减少电器电子产品废弃后对环境造成的污染，促进电器电子行业清洁生产和资源综合利用，鼓励绿色消费，保护环境和人体健康，根据《中华人民共和国清洁生产促进法》、《中华人民共和国固体废物污染环境防治法》、《废弃电器电子产品回收处理管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、销售和进口电器电子产品，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法下列术语的含义是： （一）电器电子产品，是指依靠电流或电磁场工作或者以产生、传输和测量电流和电磁场为目的，额定工作电压为直流电不超过1500伏特、交流电不超过1000伏特的设备及配套产品。其中涉及电能生产、传输和分配的设备除外。 （二）电器电子产品污染，是指电器电子产品中含有的有害物质超过国家标准或行业标准，对环境、资源、人类身体健康以及生命、财产安全造成破坏、损害、浪费或其他不良影响。 （三）电器电子产品有害物质限制使用，是指为减少或消除电器电子产品污染而采取的下列措施： 1．设计、生产过程中，通过改变设计方案、调整工艺流程、更换使用材料、革新制造方式等限制使用电器电子产品中的有害物质的技术措施； 2．设计、生产、销售以及进口过程中，标注有害物质名称及其含量，标注电器电子产品环保使用期限等措施； 3．销售过程中，严格进货渠道，拒绝销售不符合电器电子产品有害物质限制使用国家标准或"},{"i":4,"n":"第四条","txt":"工业和信息化部、发展改革委、科技部、财政部、环境保护部、商务部、海关总署、质检总局在各自的职责范围内对电器电子产品有害物质限制使用进行管理和监督。"},{"i":5,"n":"第五条","txt":"工业和信息化部会同国务院有关主管部门制定有利于电器电子产品有害物质限制使用的措施，落实电器电子产品有害物质限制使用的有关规定。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市工业和信息化、发展改革、科技、财政、环境保护、商务、海关、质检等主管部门在各自的职责范围内，对电器电子产品有害物质限制使用实施监督管理。 省、自治区、直辖市工业和信息化主管部门负责牵头建立省级电器电子产品有害物质限制使用工作协调机制，负责协调解决本行政区域内电器电子产品有害物质限制使用工作中的重大事项及问题。"},{"i":7,"n":"第七条","txt":"国家鼓励、支持电器电子产品有害物质限制使用的科学研究、技术开发和国际合作，积极推广电器电子产品有害物质替代与减量化等技术、装备。"},{"i":8,"n":"第八条","txt":"工业和信息化部、国务院有关主管部门对积极开发、研制严于本办法规定的电器电子产品的组织和个人，可以给予表扬或奖励。 省、自治区、直辖市工业和信息化主管部门和其他相关主管部门对在电器电子产品有害物质限制使用工作以及相关活动中做出显著成绩的组织和个人，可以给予表扬或奖励。"},{"i":9,"n":"第九条","txt":"电器电子产品设计者在设计电器电子产品时，不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，在满足工艺要求的前提下应当按照电器电子产品有害物质限制使用国家标准或行业标准，采用无害或低害、易于降解、便于回收利用等方案。"},{"i":10,"n":"第十条","txt":"电器电子产品生产者在生产电器电子产品时，不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，应当按照电器电子产品有害物质限制使用国家标准或行业标准，采用资源利用率高、易回收处理、有利于环境保护的材料、技术和工艺，限制或者淘汰有害物质在产品中的使用。 电器电子产品生产者不得将不符合本办法要求的电器电子产品出厂、销售。"},{"i":11,"n":"第十一条","txt":"进口的电器电子产品不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，应当符合电器电子产品有害物质限制使用国家标准或行业标准。 出入境检验检疫机构依法对进口的电器电子产品实施口岸验证和法定检验。海关验核出入境检验检疫机构签发的《入境货物通关单》并按规定办理通关手续。"},{"i":12,"n":"第十二条","txt":"电器电子产品生产者、进口者制作、使用电器电子产品包装物时，不得违反强制性标准或法律、行政法规和规章规定必须执行的标准，应当采用无害、易于降解和便于回收利用的材料，遵守包装物使用的国家标准或行业标准。"},{"i":13,"n":"第十三条","txt":"电器电子产品生产者、进口者应当按照电器电子产品有害物质限制使用标识的国家标准或行业标准，对其投放市场的电器电子产品中含有的有害物质进行标注，标明有害物质的名称、含量、所在部件及其产品可否回收利用，以及不当利用或者处置可能会对环境和人类健康造成影响的信息等；由于产品体积、形状、表面材质或功能的限制不能在产品上标注的，应当在产品说明中注明。"},{"i":14,"n":"第十四条","txt":"电器电子产品生产者、进口者应当按照电器电子产品有害物质限制使用标识的国家标准或行业标准，在其生产或进口的电器电子产品上标注环保使用期限；由于产品体积、形状、表面材质或功能的限制不能在产品上标注的，应当在产品说明中注明。"},{"i":15,"n":"第十五条","txt":"电器电子产品的环保使用期限由电器电子产品的生产者或进口者自行确定。相关行业组织可根据技术发展水平，制定包含产品类目、确定方法、具体期限等内容的相关电器电子产品环保使用期限的指导意见。 工业和信息化部鼓励相关行业组织将制定的电器电子产品环保使用期限的指导意见报送工业和信息化部。"},{"i":16,"n":"第十六条","txt":"电器电子产品销售者不得销售违反电器电子产品有害物质限制使用国家标准或行业标准的电器电子产品。"},{"i":17,"n":"第十七条","txt":"电器电子产品有害物质限制使用采取目录管理的方式。工业和信息化部根据产业发展的实际状况，商发展改革委、科技部、财政部、环境保护部、商务部、海关总署、质检总局编制、调整、发布达标管理目录。"},{"i":18,"n":"第十八条","txt":"国家建立电器电子产品有害物质限制使用合格评定制度。纳入达标管理目录的电器电子产品，应当符合电器电子产品有害物质限制使用限量要求的国家标准或行业标准，按照电器电子产品有害物质限制使用合格评定制度进行管理。 工业和信息化部根据电器电子产品有害物质限制使用工作整体安排，向国家认证认可监督主管部门提出建立电器电子产品有害物质限制使用合格评定制度的建议。国家认证认可监督主管部门依据职能会同工业和信息化部制定、发布并组织实施合格评定制度。工业和信息化部根据实际情况，会同财政部等部门对合格评定结果建立相关采信机制。"},{"i":19,"n":"第十九条","txt":"违反本办法，有下列情形之一的，由商务、海关、质检等部门在各自的职责范围内依法予以处罚： （一）电器电子产品生产者违反本办法第十条的规定，所采用的材料、技术和工艺违反电器电子产品有害物质限制使用国家标准或行业标准的，以及将不符合本办法要求的电器电子产品出厂、销售的； （二）电器电子产品进口者违反本办法第十一条的规定，进口的电器电子产品违反电器电子产品有害物质限制使用国家标准或行业标准的； （三）电器电子产品生产者、进口者违反本办法第十二条的规定，制作或使用的电器电子产品包装物违反包装物使用国家标准或行业标准的； （四）电器电子产品生产者、进口者违反本办法第十三条的规定，未标注电器电子产品有害物质的名称、含量、所在部件及其产品可否回收利用，以及不当利用或者处置可能会对环境和人类健康造成影响等信息的； （五）电器电子产品生产者、进口者违反本办法第十四条的规定，未标注电器电子产品环保使用期限的"},{"i":20,"n":"第二十条","txt":"有关部门的工作人员滥用职权，徇私舞弊，纵容、包庇违反本办法规定的行为的，或者帮助违反本办法规定的当事人逃避查处的，依法给予行政处分。"},{"i":21,"n":"第二十一条","txt":"任何组织和个人有权对违反本办法规定的行为向有关部门投诉、举报。"},{"i":22,"n":"第二十二条","txt":"本办法由工业和信息化部商发展改革委、科技部、财政部、环境保护部、商务部、海关总署、质检总局解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2016年7月1日起施行。2006年2月28日公布的《电子信息产品污染控制管理办法》（原信息产业部、发展改革委、商务部、海关总署、工商总局、质检总局、原环保总局令第39号）同时废止。"}],"dianzizhaobiaotoubiaobanfa":[{"i":1,"n":"第一条","txt":"为了规范电子招标投标活动，促进电子招标投标健康发展，根据《中华人民共和国招标投标法》、《中华人民共和国招标投标法实施条例》（以下分别简称招标投标法、招标投标法实施条例），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行电子招标投标活动，适用本办法。 本办法所称电子招标投标活动是指以数据电文形式，依托电子招标投标系统完成的全部或者部分招标投标交易、公共服务和行政监督活动。 数据电文形式与纸质形式的招标投标活动具有同等法律效力。"},{"i":3,"n":"第三条","txt":"电子招标投标系统根据功能的不同，分为交易平台、公共服务平台和行政监督平台。 交易平台是以数据电文形式完成招标投标交易活动的信息平台。公共服务平台是满足交易平台之间信息交换、资源共享需要，并为市场主体、行政监督部门和社会公众提供信息服务的信息平台。行政监督平台是行政监督部门和监察机关在线监督电子招标投标活动的信息平台。 电子招标投标系统的开发、检测、认证、运营应当遵守本办法及所附《电子招标投标系统技术规范》（以下简称技术规范）。"},{"i":4,"n":"第四条","txt":"国务院发展改革部门负责指导协调全国电子招标投标活动，各级地方人民政府发展改革部门负责指导协调本行政区域内电子招标投标活动。各级人民政府发展改革、工业和信息化、住房城乡建设、交通运输、铁道、水利、商务等部门，按照规定的职责分工，对电子招标投标活动实施监督，依法查处电子招标投标活动中的违法行为。 依法设立的招标投标交易场所的监管机构负责督促、指导招标投标交易场所推进电子招标投标工作，配合有关部门对电子招标投标活动实施监督。 省级以上人民政府有关部门对本行政区域内电子招标投标系统的建设、运营，以及相关检测、认证活动实施监督。 监察机关依法对与电子招标投标活动有关的监察对象实施监察。"},{"i":5,"n":"第五条","txt":"电子招标投标交易平台按照标准统一、互联互通、公开透明、安全高效的原则以及市场化、专业化、集约化方向建设和运营。"},{"i":6,"n":"第六条","txt":"依法设立的招标投标交易场所、招标人、招标代理机构以及其他依法设立的法人组织可以按行业、专业类别，建设和运营电子招标投标交易平台。国家鼓励电子招标投标交易平台平等竞争。"},{"i":7,"n":"第七条","txt":"电子招标投标交易平台应当按照本办法和技术规范规定，具备下列主要功能： （一）在线完成招标投标全部交易过程； （二）编辑、生成、对接、交换和发布有关招标投标数据信息； （三）提供行政监督部门和监察机关依法实施监督和受理投诉所需的监督通道； （四）本办法和技术规范规定的其他功能。"},{"i":8,"n":"第八条","txt":"电子招标投标交易平台应当按照技术规范规定，执行统一的信息分类和编码标准，为各类电子招标投标信息的互联互通和交换共享开放数据接口、公布接口要求。 电子招标投标交易平台接口应当保持技术中立，与各类需要分离开发的工具软件相兼容对接，不得限制或者排斥符合技术规范规定的工具软件与其对接。"},{"i":9,"n":"第九条","txt":"电子招标投标交易平台应当允许社会公众、市场主体免费注册登录和获取依法公开的招标投标信息，为招标投标活动当事人、行政监督部门和监察机关按各自职责和注册权限登录使用交易平台提供必要条件。"},{"i":10,"n":"第十条","txt":"电子招标投标交易平台应当依照《中华人民共和国认证认可条例》等有关规定进行检测、认证，通过检测、认证的电子招标投标交易平台应当在省级以上电子招标投标公共服务平台上公布。 电子招标投标交易平台服务器应当设在中华人民共和国境内。"},{"i":11,"n":"第十一条","txt":"电子招标投标交易平台运营机构应当是依法成立的法人，拥有一定数量的专职信息技术、招标专业人员。"},{"i":12,"n":"第十二条","txt":"电子招标投标交易平台运营机构应当根据国家有关法律法规及技术规范，建立健全电子招标投标交易平台规范运行和安全管理制度，加强监控、检测，及时发现和排除隐患。"},{"i":13,"n":"第十三条","txt":"电子招标投标交易平台运营机构应当采用可靠的身份识别、权限控制、加密、病毒防范等技术，防范非授权操作，保证交易平台的安全、稳定、可靠。"},{"i":14,"n":"第十四条","txt":"电子招标投标交易平台运营机构应当采取有效措施，验证初始录入信息的真实性，并确保数据电文不被篡改、不遗漏和可追溯。"},{"i":15,"n":"第十五条","txt":"电子招标投标交易平台运营机构不得以任何手段限制或者排斥潜在投标人，不得泄露依法应当保密的信息，不得弄虚作假、串通投标或者为弄虚作假、串通投标提供便利。"},{"i":16,"n":"第十六条","txt":"招标人或者其委托的招标代理机构应当在其使用的电子招标投标交易平台注册登记，选择使用除招标人或招标代理机构之外第三方运营的电子招标投标交易平台的，还应当与电子招标投标交易平台运营机构签订使用合同，明确服务内容、服务质量、服务费用等权利和义务，并对服务过程中相关信息的产权归属、保密责任、存档等依法作出约定。 电子招标投标交易平台运营机构不得以技术和数据接口配套为由，要求潜在投标人购买指定的工具软件。"},{"i":17,"n":"第十七条","txt":"招标人或者其委托的招标代理机构应当在资格预审公告、招标公告或者投标邀请书中载明潜在投标人访问电子招标投标交易平台的网络地址和方法。依法必须进行公开招标项目的上述相关公告应当在电子招标投标交易平台和国家指定的招标公告媒介同步发布。"},{"i":18,"n":"第十八条","txt":"招标人或者其委托的招标代理机构应当及时将数据电文形式的资格预审文件、招标文件加载至电子招标投标交易平台，供潜在投标人下载或者查阅。"},{"i":19,"n":"第十九条","txt":"数据电文形式的资格预审公告、招标公告、资格预审文件、招标文件等应当标准化、格式化，并符合有关法律法规以及国家有关部门颁发的标准文本的要求。"},{"i":20,"n":"第二十条","txt":"除本办法和技术规范规定的注册登记外，任何单位和个人不得在招标投标活动中设置注册登记、投标报名等前置条件限制潜在投标人下载资格预审文件或者招标文件。"},{"i":21,"n":"第二十一条","txt":"在投标截止时间前，电子招标投标交易平台运营机构不得向招标人或者其委托的招标代理机构以外的任何单位和个人泄露下载资格预审文件、招标文件的潜在投标人名称、数量以及可能影响公平竞争的其他信息。"},{"i":22,"n":"第二十二条","txt":"招标人对资格预审文件、招标文件进行澄清或者修改的，应当通过电子招标投标交易平台以醒目的方式公告澄清或者修改的内容，并以有效方式通知所有已下载资格预审文件或者招标文件的潜在投标人。"},{"i":23,"n":"第二十三条","txt":"电子招标投标交易平台的运营机构，以及与该机构有控股或者管理关系可能影响招标公正性的任何单位和个人，不得在该交易平台进行的招标项目中投标和代理投标。"},{"i":24,"n":"第二十四条","txt":"投标人应当在资格预审公告、招标公告或者投标邀请书载明的电子招标投标交易平台注册登记，如实递交有关信息，并经电子招标投标交易平台运营机构验证。"},{"i":25,"n":"第二十五条","txt":"投标人应当通过资格预审公告、招标公告或者投标邀请书载明的电子招标投标交易平台递交数据电文形式的资格预审申请文件或者投标文件。"},{"i":26,"n":"第二十六条","txt":"电子招标投标交易平台应当允许投标人离线编制投标文件，并且具备分段或者整体加密、解密功能。 投标人应当按照招标文件和电子招标投标交易平台的要求编制并加密投标文件。 投标人未按规定加密的投标文件，电子招标投标交易平台应当拒收并提示。"},{"i":27,"n":"第二十七条","txt":"投标人应当在投标截止时间前完成投标文件的传输递交，并可以补充、修改或者撤回投标文件。投标截止时间前未完成投标文件传输的，视为撤回投标文件。 投标截止时间后送达的投标文件，电子招标投标交易平台应当拒收。 电子招标投标交易平台收到投标人送达的投标文件，应当即时向投标人发出确认回执通知，并妥善保存投标文件。 在投标截止时间前，除投标人补充、修改或者撤回投标文件外，任何单位和个人不得解密、提取投标文件。"},{"i":28,"n":"第二十八条","txt":"资格预审申请文件的编制、加密、递交、传输、接收确认等，适用本办法关于投标文件的规定。"},{"i":29,"n":"第二十九条","txt":"电子开标应当按照招标文件确定的时间，在电子招标投标交易平台上公开进行，所有投标人均应当准时在线参加开标。"},{"i":30,"n":"第三十条","txt":"开标时，电子招标投标交易平台自动提取所有投标文件，提示招标人和投标人按招标文件规定方式按时在线解密。解密全部完成后，应当向所有投标人公布投标人名称、投标价格和招标文件规定的其他内容。"},{"i":31,"n":"第三十一条","txt":"因投标人原因造成投标文件未解密的，视为撤销其投标文件；因投标人之外的原因造成投标文件未解密的，视为撤回其投标文件，投标人有权要求责任方赔偿因此遭受的直接损失。部分投标文件未解密的，其他投标文件的开标可以继续进行。 招标人可以在招标文件中明确投标文件解密失败的补救方案，投标文件应按照招标文件的要求作出响应。"},{"i":32,"n":"第三十二条","txt":"电子招标投标交易平台应当生成开标记录并向社会公众公布，但依法应当保密的除外。"},{"i":33,"n":"第三十三条","txt":"电子评标应当在有效监控和保密的环境下在线进行。 根据国家规定应当进入依法设立的招标投标交易场所的招标项目，评标委员会成员应当在依法设立的招标投标交易场所登录招标项目所使用的电子招标投标交易平台进行评标。 评标中需要投标人对投标文件澄清或者说明的，招标人和投标人应当通过电子招标投标交易平台交换数据电文。"},{"i":34,"n":"第三十四条","txt":"评标委员会完成评标后，应当通过电子招标投标交易平台向招标人提交数据电文形式的评标报告。"},{"i":35,"n":"第三十五条","txt":"依法必须进行招标的项目中标候选人和中标结果应当在电子招标投标交易平台进行公示和公布。"},{"i":36,"n":"第三十六条","txt":"招标人确定中标人后，应当通过电子招标投标交易平台以数据电文形式向中标人发出中标通知书，并向未中标人发出中标结果通知书。 招标人应当通过电子招标投标交易平台，以数据电文形式与中标人签订合同。"},{"i":37,"n":"第三十七条","txt":"鼓励招标人、中标人等相关主体及时通过电子招标投标交易平台递交和公布中标合同履行情况的信息。"},{"i":38,"n":"第三十八条","txt":"资格预审申请文件的解密、开启、评审、发出结果通知书等，适用本办法关于投标文件的规定。"},{"i":39,"n":"第三十九条","txt":"投标人或者其他利害关系人依法对资格预审文件、招标文件、开标和评标结果提出异议，以及招标人答复，均应当通过电子招标投标交易平台进行。"},{"i":40,"n":"第四十条","txt":"招标投标活动中的下列数据电文应当按照《中华人民共和国电子签名法》和招标文件的要求进行电子签名并进行电子存档： （一）资格预审公告、招标公告或者投标邀请书； （二）资格预审文件、招标文件及其澄清、补充和修改； （三）资格预审申请文件、投标文件及其澄清和说明； （四）资格审查报告、评标报告； （五）资格预审结果通知书和中标通知书； （六）合同； （七）国家规定的其他文件。"},{"i":41,"n":"第四十一条","txt":"电子招标投标交易平台应当依法及时公布下列主要信息： （一）招标人名称、地址、联系人及联系方式； （二）招标项目名称、内容范围、规模、资金来源和主要技术要求； （三）招标代理机构名称、资格、项目负责人及联系方式； （四）投标人名称、资质和许可范围、项目负责人； （五）中标人名称、中标金额、签约时间、合同期限； （六）国家规定的公告、公示和技术规范规定公布和交换的其他信息。 鼓励招标投标活动当事人通过电子招标投标交易平台公布项目完成质量、期限、结算金额等合同履行情况。"},{"i":42,"n":"第四十二条","txt":"各级人民政府有关部门应当按照《中华人民共和国政府信息公开条例》等规定，在本部门网站及时公布并允许下载下列信息： （一）有关法律法规规章及规范性文件； （二）取得相关工程、服务资质证书或货物生产、经营许可证的单位名称、营业范围及年检情况； （三）取得有关职称、职业资格的从业人员的姓名、电子证书编号； （四）对有关违法行为作出的行政处理决定和招标投标活动的投诉处理情况； （五）依法公开的工商、税务、海关、金融等相关信息。"},{"i":43,"n":"第四十三条","txt":"设区的市级以上人民政府发展改革部门会同有关部门，按照政府主导、共建共享、公益服务的原则，推动建立本地区统一的电子招标投标公共服务平台，为电子招标投标交易平台、招标投标活动当事人、社会公众和行政监督部门、监察机关提供信息服务。"},{"i":44,"n":"第四十四条","txt":"电子招标投标公共服务平台应当按照本办法和技术规范规定，具备下列主要功能： （一）链接各级人民政府及其部门网站，收集、整合和发布有关法律法规规章及规范性文件、行政许可、行政处理决定、市场监管和服务的相关信息； （二）连接电子招标投标交易平台、国家规定的公告媒介，交换、整合和发布本办法第四十一条规定的信息； （三）连接依法设立的评标专家库，实现专家资源共享； （四）支持不同电子认证服务机构数字证书的兼容互认； （五）提供行政监督部门和监察机关依法实施监督、监察所需的监督通道； （六）整合分析相关数据信息，动态反映招标投标市场运行状况、相关市场主体业绩和信用情况。 属于依法必须公开的信息，公共服务平台应当无偿提供。 公共服务平台应同时遵守本办法第八条至第十五条规定。"},{"i":45,"n":"第四十五条","txt":"电子招标投标交易平台应当按照本办法和技术规范规定，在任一电子招标投标公共服务平台注册登记，并向电子招标投标公共服务平台及时提供本办法第四十一条规定的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当按照本办法和技术规范规定，开放数据接口、公布接口要求，与电子招标投标交易平台及时交换招标投标活动所必需的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当按照本办法和技术规范规定，开放数据接口、公布接口要求，与上一层级电子招标投标公共服务平台连接并注册登记，及时交换本办法第四十四条规定的信息，以及双方协商确定的其他信息。 电子招标投标公共服务平台应当允许社会公众、市场主体免费注册登录和获取依法公开的招标投标信息，为招标人、投标人、行政监督部门和监察机关按各自职责和注册权限登录使用公共服务平台提供必要条件。"},{"i":46,"n":"第四十六条","txt":"电子招标投标活动及相关主体应当自觉接受行政监督部门、监察机关依法实施的监督、监察。"},{"i":47,"n":"第四十七条","txt":"行政监督部门、监察机关结合电子政务建设，提升电子招标投标监督能力，依法设置并公布有关法律法规规章、行政监督的依据、职责权限、监督环节、程序和时限、信息交换要求和联系方式等相关内容。"},{"i":48,"n":"第四十八条","txt":"电子招标投标交易平台和公共服务平台应当按照本办法和技术规范规定，向行政监督平台开放数据接口、公布接口要求，按有关规定及时对接交换和公布有关招标投标信息。 行政监督平台应当开放数据接口，公布数据接口要求，不得限制和排斥已通过检测认证的电子招标投标交易平台和公共服务平台与其对接交换信息，并参照执行本办法第八条至第十五条的有关规定。"},{"i":49,"n":"第四十九条","txt":"电子招标投标交易平台应当依法设置电子招标投标工作人员的职责权限，如实记录招标投标过程、数据信息来源，以及每一操作环节的时间、网络地址和工作人员，并具备电子归档功能。 电子招标投标公共服务平台应当记录和公布相关交换数据信息的来源、时间并进行电子归档备份。 任何单位和个人不得伪造、篡改或者损毁电子招标投标活动信息。"},{"i":50,"n":"第五十条","txt":"行政监督部门、监察机关及其工作人员，除依法履行职责外，不得干预电子招标投标活动，并遵守有关信息保密的规定。"},{"i":51,"n":"第五十一条","txt":"投标人或者其他利害关系人认为电子招标投标活动不符合有关规定的，通过相关行政监督平台进行投诉。"},{"i":52,"n":"第五十二条","txt":"行政监督部门和监察机关在依法监督检查招标投标活动或者处理投诉时，通过其平台发出的行政监督或者行政监察指令，招标投标活动当事人和电子招标投标交易平台、公共服务平台的运营机构应当执行，并如实提供相关信息，协助调查处理。"},{"i":53,"n":"第五十三条","txt":"电子招标投标系统有下列情形的，责令改正；拒不改正的，不得交付使用，已经运营的应当停止运营。 （一）不具备本办法及技术规范规定的主要功能； （二）不向行政监督部门和监察机关提供监督通道； （三）不执行统一的信息分类和编码标准； （四）不开放数据接口、不公布接口要求； （五）不按照规定注册登记、对接、交换、公布信息； （六）不满足规定的技术和安全保障要求； （七）未按照规定通过检测和认证。"},{"i":54,"n":"第五十四条","txt":"招标人或者电子招标投标系统运营机构存在以下情形的，视为限制或者排斥潜在投标人，依照招标投标法第五十一条规定处罚。 （一）利用技术手段对享有相同权限的市场主体提供有差别的信息； （二）拒绝或者限制社会公众、市场主体免费注册并获取依法必须公开的招标投标信息； （三）违规设置注册登记、投标报名等前置条件； （四）故意与各类需要分离开发并符合技术规范规定的工具软件不兼容对接； （五）故意对递交或者解密投标文件设置障碍。"},{"i":55,"n":"第五十五条","txt":"电子招标投标交易平台运营机构有下列情形的，责令改正，并按照有关规定处罚。 （一）违反规定要求投标人注册登记、收取费用； （二）要求投标人购买指定的工具软件； （三）其他侵犯招标投标活动当事人合法权益的情形。"},{"i":56,"n":"第五十六条","txt":"电子招标投标系统运营机构向他人透露已获取招标文件的潜在投标人的名称、数量、投标文件内容或者对投标文件的评审和比较以及其他可能影响公平竞争的招标投标信息，参照招标投标法第五十二条关于招标人泄密的规定予以处罚。"},{"i":57,"n":"第五十七条","txt":"招标投标活动当事人和电子招标投标系统运营机构协助招标人、投标人串通投标的，依照招标投标法第五十三条和招标投标法实施条例第六十七条规定处罚。"},{"i":58,"n":"第五十八条","txt":"招标投标活动当事人和电子招标投标系统运营机构伪造、篡改、损毁招标投标信息，或者以其他方式弄虚作假的，依照招标投标法第五十四条和招标投标法实施条例第六十八条规定处罚。"},{"i":59,"n":"第五十九条","txt":"电子招标投标系统运营机构未按照本办法和技术规范规定履行初始录入信息验证义务，造成招标投标活动当事人损失的，应当承担相应的赔偿责任。"},{"i":60,"n":"第六十条","txt":"有关行政监督部门及其工作人员不履行职责，或者利用职务便利非法干涉电子招标投标活动的，依照有关法律法规处理。"},{"i":61,"n":"第六十一条","txt":"招标投标协会应当按照有关规定，加强电子招标投标活动的自律管理和服务。"},{"i":62,"n":"第六十二条","txt":"电子招标投标某些环节需要同时使用纸质文件的，应当在招标文件中明确约定；当纸质文件与数据电文不一致时，除招标文件特别约定外，以数据电文为准。"},{"i":63,"n":"第六十三条","txt":"本办法未尽事宜，按照有关法律、法规、规章执行。"},{"i":64,"n":"第六十四条","txt":"本办法由国家发展和改革委员会会同有关部门负责解释。"},{"i":65,"n":"第六十五条","txt":"技术规范作为本办法的附件，与本办法具有同等效力。"},{"i":66,"n":"第六十六条","txt":"本办法自2013年5月1日起施行。"}],"dianzirenzhengfuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范电子认证服务行为，对电子认证服务提供者实施监督管理，根据《中华人民共和国电子签名法》和其他法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称电子认证服务，是指为电子签名相关各方提供真实性、可靠性验证的活动。 本办法所称电子认证服务提供者，是指为需要第三方认证的电子签名提供认证服务的机构（以下称为“电子认证服务机构”）。 向社会公众提供服务的电子认证服务机构应当依法设立。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内设立电子认证服务机构和为电子签名提供电子认证服务，适用本办法。"},{"i":4,"n":"第四条","txt":"中华人民共和国工业和信息化部（以下简称“工业和信息化部”）依法对电子认证服务机构和电子认证服务实施监督管理。"},{"i":5,"n":"第五条","txt":"电子认证服务机构应当具备下列条件： （一）具有独立的企业法人资格。 （二）具有与提供电子认证服务相适应的人员。从事电子认证服务的专业技术人员、运营管理人员、安全管理人员和客户服务人员不少于三十名，并且应当符合相应岗位技能要求。 （三）注册资本不低于人民币三千万元。 （四）具有固定的经营场所和满足电子认证服务要求的物理环境。 （五）具有符合国家有关安全标准的技术和设备。 （六）具有国家密码管理机构同意使用密码的证明文件。 （七）法律、行政法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"申请电子认证服务许可的，应当向工业和信息化部提交下列材料： （一）书面申请。 （二）人员证明。 （三）企业法人营业执照副本及复印件。 （四）经营场所证明。 （五）国家有关认证检测机构出具的技术、设备、物理环境符合国家有关安全标准的凭证。 （六）国家密码管理机构同意使用密码的证明文件。"},{"i":7,"n":"第七条","txt":"工业和信息化部对提交的申请材料进行形式审查。申请材料齐全、符合法定形式的，应当向申请人出具受理通知书。申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部内容。"},{"i":8,"n":"第八条","txt":"工业和信息化部对决定受理的申请材料进行实质审查。需要对有关内容进行核实的，指派两名以上工作人员实地进行核查。"},{"i":9,"n":"第九条","txt":"工业和信息化部对与申请人有关事项书面征求中华人民共和国商务部等有关部门的意见。"},{"i":10,"n":"第十条","txt":"工业和信息化部应当自接到申请之日起四十五日内作出准予许可或者不予许可的书面决定。不予许可的，应当书面通知申请人并说明理由；准予许可的，颁发《电子认证服务许可证》，并公布下列信息： （一）《电子认证服务许可证》编号。 （二）电子认证服务机构名称。 （三）发证机关和发证日期。 电子认证服务许可相关信息发生变更的，工业和信息化部应当及时公布。 《电子认证服务许可证》的有效期为五年。"},{"i":11,"n":"第十一条","txt":"电子认证服务机构不得倒卖、出租、出借或者以其他形式非法转让《电子认证服务许可证》。"},{"i":12,"n":"第十二条","txt":"取得认证资格的电子认证服务机构，在提供电子认证服务之前，应当通过互联网公布下列信息： （一）机构名称和法定代表人。 （二）机构住所和联系办法。 （三）《电子认证服务许可证》编号。 （四）发证机关和发证日期。 （五）《电子认证服务许可证》有效期的起止时间。"},{"i":13,"n":"第十三条","txt":"电子认证服务机构在《电子认证服务许可证》的有效期内变更公司名称、住所、法定代表人、注册资本的，应当在完成工商变更登记之日起15日内办理《电子认证服务许可证》变更手续。"},{"i":14,"n":"第十四条","txt":"《电子认证服务许可证》的有效期届满需要延续的，电子认证服务机构应当在许可证有效期届满三十日前向工业和信息化部申请办理延续手续，并自办结之日起五日内按照本办法第十二条的规定公布相关信息。"},{"i":15,"n":"第十五条","txt":"电子认证服务机构应当按照工业和信息化部公布的《电子认证业务规则规范》等要求，制定本机构的电子认证业务规则和相应的证书策略，在提供电子认证服务前予以公布，并向工业和信息化部备案。 电子认证业务规则和证书策略发生变更的，电子认证服务机构应当予以公布，并自公布之日起三十日内向工业和信息化部备案。"},{"i":16,"n":"第十六条","txt":"电子认证服务机构应当按照公布的电子认证业务规则提供电子认证服务。"},{"i":17,"n":"第十七条","txt":"电子认证服务机构应当保证提供下列服务： （一）制作、签发、管理电子签名认证证书。 （二）确认签发的电子签名认证证书的真实性。 （三）提供电子签名认证证书目录信息查询服务。 （四）提供电子签名认证证书状态信息查询服务。"},{"i":18,"n":"第十八条","txt":"电子认证服务机构应当履行下列义务： （一）保证电子签名认证证书内容在有效期内完整、准确。 （二）保证电子签名依赖方能够证实或者了解电子签名认证证书所载内容及其他有关事项。 （三）妥善保存与电子认证服务相关的信息。"},{"i":19,"n":"第十九条","txt":"电子认证服务机构应当建立完善的安全管理和内部审计制度。"},{"i":20,"n":"第二十条","txt":"电子认证服务机构应当遵守国家的保密规定，建立完善的保密制度。 电子认证服务机构对电子签名人和电子签名依赖方的资料，负有保密的义务。"},{"i":21,"n":"第二十一条","txt":"电子认证服务机构在受理电子签名认证证书申请前，应当向申请人告知下列事项： （一）电子签名认证证书和电子签名的使用条件。 （二）服务收费的项目和标准。 （三）保存和使用证书持有人信息的权限和责任。 （四）电子认证服务机构的责任范围。 （五）证书持有人的责任范围。 （六）其他需要事先告知的事项。"},{"i":22,"n":"第二十二条","txt":"电子认证服务机构受理电子签名认证申请后，应当与证书申请人签订合同，明确双方的权利义务。"},{"i":23,"n":"第二十三条","txt":"电子认证服务机构在《电子认证服务许可证》的有效期内拟终止电子认证服务的，应当在终止服务六十日前向工业和信息化部报告，并办理《电子认证服务许可证》注销手续。"},{"i":24,"n":"第二十四条","txt":"电子认证服务机构拟暂停或者终止电子认证服务的，应当在暂停或者终止电子认证服务九十日前，就业务承接及其他有关事项通知有关各方。 电子认证服务机构拟暂停或者终止电子认证服务的，应当在暂停或者终止电子认证服务六十日前向工业和信息化部报告，并与其他电子认证服务机构就业务承接进行协商，作出妥善安排。"},{"i":25,"n":"第二十五条","txt":"电子认证服务机构拟暂停或者终止电子认证服务，未能就业务承接事项与其他电子认证服务机构达成协议的，应当申请工业和信息化部安排其他电子认证服务机构承接其业务。"},{"i":26,"n":"第二十六条","txt":"电子认证服务机构被依法吊销电子认证服务许可的，其业务承接事项按照工业和信息化部的规定处理。"},{"i":27,"n":"第二十七条","txt":"电子认证服务机构有根据工业和信息化部的安排承接其他机构开展的电子认证服务业务的义务。"},{"i":28,"n":"第二十八条","txt":"电子签名认证证书应当准确载明下列内容： （一）签发电子签名认证证书的电子认证服务机构名称。 （二）证书持有人名称。 （三）证书序列号。 （四）证书有效期。 （五）证书持有人的电子签名验证数据。 （六）电子认证服务机构的电子签名。 （七）工业和信息化部规定的其他内容。"},{"i":29,"n":"第二十九条","txt":"有下列情况之一的，电子认证服务机构可以撤销其签发的电子签名认证证书： （一）证书持有人申请撤销证书。 （二）证书持有人提供的信息不真实。 （三）证书持有人没有履行双方合同规定的义务。 （四）证书的安全性不能得到保证。 （五）法律、行政法规规定的其他情况。"},{"i":30,"n":"第三十条","txt":"有下列情况之一的，电子认证服务机构应当对申请人提供的证明身份的有关材料进行查验，并对有关材料进行审查： （一）申请人申请电子签名认证证书。 （二）证书持有人申请更新证书。 （三）证书持有人申请撤销证书。"},{"i":31,"n":"第三十一条","txt":"电子认证服务机构更新或者撤销电子签名认证证书时，应当予以公告。"},{"i":32,"n":"第三十二条","txt":"工业和信息化部对电子认证服务机构进行定期、不定期的监督检查，监督检查的内容主要包括法律法规符合性、安全运营管理、风险管理等。 工业和信息化部对电子认证服务机构实行监督检查时，应当记录监督检查的情况和处理结果，由监督检查人员签字后归档。公众有权查阅监督检查记录。 工业和信息化部对电子认证服务机构实行监督检查，不得妨碍电子认证服务机构正常的生产经营活动，不得收取任何费用。"},{"i":33,"n":"第三十三条","txt":"取得电子认证服务许可的电子认证服务机构，在电子认证服务许可的有效期内不得降低其设立时所应具备的条件。"},{"i":34,"n":"第三十四条","txt":"电子认证服务机构应当如实向工业和信息化部报送认证业务开展情况报告、财务会计报告等有关资料。"},{"i":35,"n":"第三十五条","txt":"电子认证服务机构有下列情况之一的，应当及时向工业和信息化部报告： （一）重大系统、关键设备事故。 （二）重大财产损失。 （三）重大法律诉讼。 （四）关键岗位人员变动。"},{"i":36,"n":"第三十六条","txt":"电子认证服务机构应当对其从业人员进行岗位培训。"},{"i":37,"n":"第三十七条","txt":"工业和信息化部根据监督管理工作的需要，可以委托有关省、自治区和直辖市信息产业主管部门承担具体的监督管理事项。"},{"i":38,"n":"第三十八条","txt":"电子认证服务机构向工业和信息化部隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动的真实材料的，由工业和信息化部责令改正，给予警告或者处以5000元以上1万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"工业和信息化部与省、自治区、直辖市信息产业主管部门的工作人员，不依法履行监督管理职责的，由工业和信息化部或者省、自治区、直辖市信息产业主管部门依据职权视情节轻重，分别给予警告、记过、记大过、降级、撤职、开除的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"电子认证服务机构违反本办法第十三条、第十五条、第二十七条的规定的，由工业和信息化部依据职权责令限期改正，处以警告，可以并处1万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"电子认证服务机构违反本办法第三十三条的规定的，由工业和信息化部依据职权责令限期改正，处以3万元以下的罚款，并将上述情况向社会公告。"},{"i":42,"n":"第四十二条","txt":"经工业和信息化部根据有关协议或者对等原则核准后，中华人民共和国境外的电子认证服务机构在境外签发的电子签名认证证书与依照本办法设立的电子认证服务机构签发的电子签名认证证书具有同等的法律效力。"},{"i":43,"n":"第四十三条","txt":"本办法自2009年3月31日起施行。2005年2月8日发布的《电子认证服务管理办法》（中华人民共和国信息产业部令第35号）同时废止。"}],"dianhuayonghuzhenshishenfenxinxidengjiguiding":[{"i":1,"n":"第一条","txt":"为了规范电话用户真实身份信息登记活动，保障电话用户和电信业务经营者的合法权益，维护网络信息安全，促进电信业的健康发展，根据《全国人民代表大会常务委员会关于加强网络信息保护的决定》和《中华人民共和国电信条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的电话用户真实身份信息登记活动，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称电话用户真实身份信息登记，是指电信业务经营者为用户办理固定电话、移动电话（含无线上网卡，下同）等入网手续，在与用户签订协议或者确认提供服务时，如实登记用户提供的真实身份信息的活动。 本规定所称入网，是指用户办理固定电话装机、移机、过户，移动电话开户、过户等。"},{"i":4,"n":"第四条","txt":"工业和信息化部和各省、自治区、直辖市通信管理局（以下统称电信管理机构）依法对电话用户真实身份信息登记工作实施监督管理。"},{"i":5,"n":"第五条","txt":"电信业务经营者应当依法登记和保护电话用户办理入网手续时提供的真实身份信息。"},{"i":6,"n":"第六条","txt":"电信业务经营者为用户办理入网手续时，应当要求用户出示有效证件、提供真实身份信息，用户应当予以配合。 用户委托他人办理入网手续的，电信业务经营者应当要求受托人出示用户和受托人的有效证件，并提供用户和受托人的真实身份信息。"},{"i":7,"n":"第七条","txt":"个人办理电话用户真实身份信息登记的，可以出示下列有效证件之一： （一）居民身份证、临时居民身份证或者户口簿； （二）中国人民解放军军人身份证件、中国人民武装警察身份证件； （三）港澳居民来往内地通行证、台湾居民来往大陆通行证或者其他有效旅行证件； （四）外国公民护照； （五）法律、行政法规和国家规定的其他有效身份证件。"},{"i":8,"n":"第八条","txt":"单位办理电话用户真实身份信息登记的，可以出示下列有效证件之一： （一）组织机构代码证； （二）营业执照； （三）事业单位法人证书或者社会团体法人登记证书； （四）法律、行政法规和国家规定的其他有效证件或者证明文件。 单位办理登记的，除出示以上证件之一外，还应当出示经办人的有效证件和单位的授权书。"},{"i":9,"n":"第九条","txt":"电信业务经营者应当对用户出示的证件进行查验，并如实登记证件类别以及证件上所记载的姓名（名称）、号码、住址信息；对于用户委托他人办理入网手续的，应当同时查验受托人的证件并登记受托人的上述信息。 为了方便用户提供身份信息、办理入网手续，保护用户的合法权益，电信业务经营者复印用户身份证件的，应当在复印件上注明电信业务经营者名称、复印目的和日期。"},{"i":10,"n":"第十条","txt":"用户拒绝出示有效证件，拒绝提供其证件上所记载的身份信息，冒用他人的证件，或者使用伪造、变造的证件的，电信业务经营者不得为其办理入网手续。"},{"i":11,"n":"第十一条","txt":"电信业务经营者在向电话用户提供服务期间及终止向其提供服务后两年内，应当留存用户办理入网手续时提供的身份信息和相关材料。"},{"i":12,"n":"第十二条","txt":"电信业务经营者应当建立健全用户真实身份信息保密管理制度。 电信业务经营者及其工作人员对在提供服务过程中登记的用户真实身份信息应当严格保密，不得泄露、篡改或者毁损，不得出售或者非法向他人提供，不得用于提供服务之外的目的。"},{"i":13,"n":"第十三条","txt":"电话用户真实身份信息发生或者可能发生泄露、毁损、丢失的，电信业务经营者应当立即采取补救措施；造成或者可能造成严重后果的，应当立即向相关电信管理机构报告，配合相关部门进行的调查处理。 电信管理机构应当对报告或者发现的可能违反电话用户真实身份信息保护规定的行为的影响进行评估；影响特别重大的，相关省、自治区、直辖市通信管理局应当向工业和信息化部报告。电信管理机构在依据本规定作出处理决定前，可以要求电信业务经营者暂停有关行为，电信业务经营者应当执行。"},{"i":14,"n":"第十四条","txt":"电信业务经营者委托他人代理电话入网手续、登记电话用户真实身份信息的，应当对代理人的用户真实身份信息登记和保护工作进行监督和管理，不得委托不符合本规定有关用户真实身份信息登记和保护要求的代理人代办相关手续。"},{"i":15,"n":"第十五条","txt":"电信业务经营者应当对其电话用户真实身份信息登记和保护情况每年至少进行一次自查，并对其工作人员进行电话用户真实身份信息登记和保护相关知识、技能和安全责任培训。"},{"i":16,"n":"第十六条","txt":"电信管理机构应当对电信业务经营者的电话用户真实身份信息登记和保护情况实施监督检查。电信管理机构实施监督检查时，可以要求电信业务经营者提供相关材料，进入其生产经营场所调查情况，电信业务经营者应当予以配合。 电信管理机构实施监督检查，应当记录监督检查的情况，不得妨碍电信业务经营者正常的经营或者服务活动，不得收取任何费用。 电信管理机构及其工作人员对在实施监督检查过程中知悉的电话用户真实身份信息应当予以保密，不得泄露、篡改或者毁损，不得出售或者非法向他人提供。"},{"i":17,"n":"第十七条","txt":"电信业务经营者违反本规定第六条、第九条至第十五条的规定，或者不配合电信管理机构依照本规定开展的监督检查的，由电信管理机构依据职权责令限期改正，予以警告，可以并处一万元以上三万元以下罚款，向社会公告。其中，《中华人民共和国电信条例》规定法律责任的，依照其规定处理；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"用户以冒用、伪造、变造的证件办理入网手续的，电信业务经营者不得为其提供服务，并由相关部门依照《中华人民共和国居民身份证法》、《中华人民共和国治安管理处罚法》、《现役军人和人民武装警察居民身份证申领发放办法》等规定处理。"},{"i":19,"n":"第十九条","txt":"电信管理机构工作人员在对电话用户真实身份信息登记工作实施监督管理的过程中玩忽职守、滥用职权、徇私舞弊的，依法给予处理；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"电信业务经营者应当通过电话、短信息、书面函件或者公告等形式告知用户并采取便利措施，为本规定施行前尚未提供真实身份信息或者所提供身份信息不全的电话用户补办登记手续。 电信业务经营者为电话用户补办登记手续，不得擅自加重用户责任。 电信业务经营者应当在向尚未提供真实身份信息的用户确认提供服务时，要求用户提供真实身份信息。"},{"i":21,"n":"第二十一条","txt":"本规定自2013年9月1日起施行。"}],"kongjianwutidengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强国家对空间活动的管理，建立我国的空间物体登记制度，维护我国作为空间物体发射国的合法权益，有效履行《关于登记射入外层空间物体的公约》（以下简称（登记公约》）缔约国的义务，制订本办法。"},{"i":2,"n":"第二条","txt":"本办法所称空间物体是指进入外层空间的人造地球卫星、载人航天、空间探测器、空间站、运载工具及其部件、以及其他人造物体。 短暂穿越外层空间的高空探测火箭和弹道导弹，不属于空间物体。"},{"i":3,"n":"第三条","txt":"本办法适用于在我国境内发射的所有空间物体，以及我国作为共同发射国在境外发射的空间物体。 发射国是指发射或促使发射空间物体的国家，以及从其领土或设施发射空间物体的国家。"},{"i":4,"n":"第四条","txt":"国家实行空间物体登记制度，所有从事发射或促成发射空间物体的政府部门、法人、其他组织和自然人均应依照本办法的规定履行登记义务。"},{"i":5,"n":"第五条","txt":"国防科学技术工业委员会（以下简称国防科工委）负责空间物体的国内登记管理工作，日常事务由国防科工委国际合作司负责。 涉及其他共同发射国的国内登记，必要时由国防科工委商外交部确定登记者。"},{"i":6,"n":"第六条","txt":"国家建立和保存空间物体国家登记册。国家登记册的主要内容包括：登记编号、登记者、空间物体所有者、空间物体名称、空间物体基本特性、空间物体发射者、运载器名称、发射日期、发射场名称、空间物体基本轨道参数、空间物体的发射及入轨情况等。 空间物体国家登记册登记表格式见附件。"},{"i":7,"n":"第七条","txt":"除本办法第八条　规定外，空间物体应由空间物体的所有者进行国内登记。有多个所有者的空间物体由该物体的主要所有者代表全体所有者进行登记。 空间物体发射者应对该物体的国内登记提供必要的协助。"},{"i":8,"n":"第八条","txt":"在我国境内发射的空间物体的所有者为其他国家政府、法人、其他组织或自然人时，应由承担国际商业发射服务的公司进行国内登记。"},{"i":9,"n":"第九条","txt":""},{"i":10,"n":"第七条","txt":"和第八条　所述空间物体登记者应在空间物体进入空间轨道 60 天内，按照本办法第六条　所规定的内容，向国防科工委提交登记资料，履行登记手续。 依本办法所登记的空间物体的状态有重大改变（如轨道变化、解体、停止工作、返回及再入大气层等）时，空间物体登记者应在空间物体状态改变后 60 天内进行变更登记。"},{"i":11,"n":"第十条","txt":"在空间物体国家登记册中专设香港、澳门分册。香港特别行政区和澳门特别行政区拥有或发射的空间物体的具体登记办法另行制定。"},{"i":12,"n":"第十一条","txt":"空间物体国家登记册由国防科工委保存。 经国防科工委同意，国内有关政府部门和经政府主管部门批准的法人、其他组织和自然人可向登记册保存机关申请查询。"},{"i":13,"n":"第十二条","txt":"空间物体的国际登记，依照《登记公约》的有关规定，由国防科工委在空间物体国内登记后 60 天内，通过外交部向联合国秘书处进行登记。"},{"i":14,"n":"第十三条","txt":"根据《登记公约》第四条　第一款的规定，空间物体国际登记的主要内容包括：发射国国名、空间物体名称及登记号码、发射日期和地点、基本轨道参数、空间物体的一般功能等。"},{"i":15,"n":"第十四条","txt":"我国作为共同发射国的空间物体的国际登记，由外交部根据《登记公约》的有关规定商有关国家确定登记国。"},{"i":16,"n":"第十五条","txt":"本办法中涉及国内登记的有关规定由国防科工委负责解释；涉及《登记公约》条　款及国际登记的有关规定由外交部负责解释。"},{"i":17,"n":"第十六条","txt":"本办法自发布之日起施行。 附件：空间物体国家登记册登记表 （略）"}],"wangluojiedaixinxizhongjiejigouyewuhuodongguanliza8f48e7-2":[{"i":1,"n":"第一条","txt":"为规范网络借贷信息中介机构业务活动，保护出借人、借款人、网络借贷信息中介机构及相关当事人合法权益，促进网络借贷行业健康发展，更好满足中小微企业和个人投融资需求，根据《关于促进互联网金融健康发展的指导意见》提出的总体要求和监管原则，依据《中华人民共和国民法通则》、《中华人民共和国公司法》、《中华人民共和国合同法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中国境内从事网络借贷信息中介业务活动，适用本办法，法律法规另有规定的除外。 本办法所称网络借贷是指个体和个体之间通过互联网平台实现的直接借贷。个体包含自然人、法人及其他组织。网络借贷信息中介机构是指依法设立，专门从事网络借贷信息中介业务活动的金融信息中介公司。该类机构以互联网为主要渠道，为借款人与出借人（即贷款人）实现直接借贷提供信息搜集、信息公布、资信评估、信息交互、借贷撮合等服务。 本办法所称地方金融监管部门是指各省级人民政府承担地方金融监管职责的部门。"},{"i":3,"n":"第三条","txt":"网络借贷信息中介机构按照依法、诚信、自愿、公平的原则为借款人和出借人提供信息服务，维护出借人与借款人合法权益，不得提供增信服务，不得直接或间接归集资金，不得非法集资，不得损害国家利益和社会公共利益。 借款人与出借人遵循借贷自愿、诚实守信、责任自负、风险自担的原则承担借贷风险。网络借贷信息中介机构承担客观、真实、全面、及时进行信息披露的责任，不承担借贷违约风险。"},{"i":4,"n":"第四条","txt":"按照《关于促进互联网金融健康发展的指导意见》中“鼓励创新、防范风险、趋利避害、健康发展”的总体要求和“依法监管、适度监管、分类监管、协同监管、创新监管”的监管原则，落实各方管理责任。国务院银行业监督管理机构及其派出机构负责制定网络借贷信息中介机构业务活动监督管理制度，并实施行为监管。各省级人民政府负责本辖区网络借贷信息中介机构的机构监管。工业和信息化部负责对网络借贷信息中介机构业务活动涉及的电信业务进行监管。公安部牵头负责对网络借贷信息中介机构的互联网服务进行安全监管，依法查处违反网络安全监管的违法违规活动，打击网络借贷涉及的金融犯罪及相关犯罪。国家互联网信息办公室负责对金融信息服务、互联网信息内容等业务进行监管。"},{"i":5,"n":"第五条","txt":"拟开展网络借贷信息中介服务的网络借贷信息中介机构及其分支机构，应当在领取营业执照后，于10个工作日以内携带有关材料向工商登记注册地地方金融监管部门备案登记。 地方金融监管部门负责为网络借贷信息中介机构办理备案登记。地方金融监管部门应当在网络借贷信息中介机构提交的备案登记材料齐备时予以受理，并在各省（区、市）规定的时限内完成备案登记手续。备案登记不构成对网络借贷信息中介机构经营能力、合规程度、资信状况的认可和评价。 地方金融监管部门有权根据本办法和相关监管规则对备案登记后的网络借贷信息中介机构进行评估分类，并及时将备案登记信息及分类结果在官方网站上公示。 网络借贷信息中介机构完成地方金融监管部门备案登记后，应当按照通信主管部门的相关规定申请相应的电信业务经营许可；未按规定申请电信业务经营许可的，不得开展网络借贷信息中介业务。 网络借贷信息中介机构备案登记、评估分类等具体细则另行制定。"},{"i":6,"n":"第六条","txt":"开展网络借贷信息中介业务的机构，应当在经营范围中实质明确网络借贷信息中介，法律、行政法规另有规定的除外。"},{"i":7,"n":"第七条","txt":"网络借贷信息中介机构备案登记事项发生变更的，应当在5个工作日以内向工商登记注册地地方金融监管部门报告并进行备案信息变更。"},{"i":8,"n":"第八条","txt":"经备案的网络借贷信息中介机构拟终止网络借贷信息中介服务的，应当在终止业务前提前至少10个工作日，书面告知工商登记注册地地方金融监管部门，并办理备案注销。 经备案登记的网络借贷信息中介机构依法解散或者依法宣告破产的，除依法进行清算外，由工商登记注册地地方金融监管部门注销其备案。"},{"i":9,"n":"第九条","txt":"网络借贷信息中介机构应当履行下列义务： （一）依据法律法规及合同约定为出借人与借款人提供直接借贷信息的采集整理、甄别筛选、网上发布，以及资信评估、借贷撮合、融资咨询、在线争议解决等相关服务； （二）对出借人与借款人的资格条件、信息的真实性、融资项目的真实性、合法性进行必要审核； （三）采取措施防范欺诈行为，发现欺诈行为或其他损害出借人利益的情形，及时公告并终止相关网络借贷活动； （四）持续开展网络借贷知识普及和风险教育活动，加强信息披露工作，引导出借人以小额分散的方式参与网络借贷，确保出借人充分知悉借贷风险； （五）按照法律法规和网络借贷有关监管规定要求报送相关信息，其中网络借贷有关债权债务信息要及时向有关数据统计部门报送并登记； （六）妥善保管出借人与借款人的资料和交易信息，不得删除、篡改，不得非法买卖、泄露出借人与借款人的基本信息和交易信息； （七）依法履行客户身份识别、可疑交易报"},{"i":10,"n":"第十条","txt":"网络借贷信息中介机构不得从事或者接受委托从事下列活动： （一）为自身或变相为自身融资； （二）直接或间接接受、归集出借人的资金； （三）直接或变相向出借人提供担保或者承诺保本保息； （四）自行或委托、授权第三方在互联网、固定电话、移动电话等电子渠道以外的物理场所进行宣传或推介融资项目； （五）发放贷款，但法律法规另有规定的除外； （六）将融资项目的期限进行拆分； （七）自行发售理财等金融产品募集资金，代销银行理财、券商资管、基金、保险或信托产品等金融产品； （八）开展类资产证券化业务或实现以打包资产、证券化资产、信托资产、基金份额等形式的债权转让行为； （九）除法律法规和网络借贷有关监管规定允许外，与其他机构投资、代理销售、经纪等业务进行任何形式的混合、捆绑、代理； （十）虚构、夸大融资项目的真实性、收益前景，隐瞒融资项目的瑕疵及风险，以歧义性语言或其他欺骗性手段等进行虚假片面宣传或促"},{"i":11,"n":"第十一条","txt":"参与网络借贷的出借人与借款人应当为网络借贷信息中介机构核实的实名注册用户。"},{"i":12,"n":"第十二条","txt":"借款人应当履行下列义务： （一）提供真实、准确、完整的用户信息及融资信息； （二）提供在所有网络借贷信息中介机构未偿还借款信息； （三）保证融资项目真实、合法，并按照约定用途使用借贷资金，不得用于出借等其他目的； （四）按照约定向出借人如实报告影响或可能影响出借人权益的重大信息； （五）确保自身具有与借款金额相匹配的还款能力并按照合同约定还款； （六）借贷合同及有关协议约定的其他义务。"},{"i":13,"n":"第十三条","txt":"借款人不得从事下列行为： （一）通过故意变换身份、虚构融资项目、夸大融资项目收益前景等形式的欺诈借款； （二）同时通过多个网络借贷信息中介机构，或者通过变换项目名称、对项目内容进行非实质性变更等方式，就同一融资项目进行重复融资； （三）在网络借贷信息中介机构以外的公开场所发布同一融资项目的信息； （四）已发现网络借贷信息中介机构提供的服务中含有本办法第十条所列内容，仍进行交易； （五）法律法规和网络借贷有关监管规定禁止从事的其他活动。"},{"i":14,"n":"第十四条","txt":"参与网络借贷的出借人，应当具备投资风险意识、风险识别能力、拥有非保本类金融产品投资的经历并熟悉互联网。"},{"i":15,"n":"第十五条","txt":"参与网络借贷的出借人应当履行下列义务： （一）向网络借贷信息中介机构提供真实、准确、完整的身份等信息； （二）出借资金为来源合法的自有资金； （三）了解融资项目信贷风险，确认具有相应的风险认知和承受能力； （四）自行承担借贷产生的本息损失； （五）借贷合同及有关协议约定的其他义务。"},{"i":16,"n":"第十六条","txt":"网络借贷信息中介机构在互联网、固定电话、移动电话等电子渠道以外的物理场所只能进行信用信息采集、核实、贷后跟踪、抵质押管理等风险管理及网络借贷有关监管规定明确的部分必要经营环节。"},{"i":17,"n":"第十七条","txt":"网络借贷金额应当以小额为主。网络借贷信息中介机构应当根据本机构风险管理能力，控制同一借款人在同一网络借贷信息中介机构平台及不同网络借贷信息中介机构平台的借款余额上限，防范信贷集中风险。 同一自然人在同一网络借贷信息中介机构平台的借款余额上限不超过人民币20万元；同一法人或其他组织在同一网络借贷信息中介机构平台的借款余额上限不超过人民币100万元；同一自然人在不同网络借贷信息中介机构平台借款总余额不超过人民币100万元；同一法人或其他组织在不同网络借贷信息中介机构平台借款总余额不超过人民币500万元。"},{"i":18,"n":"第十八条","txt":"网络借贷信息中介机构应当按照国家网络安全相关规定和国家信息安全等级保护制度的要求，开展信息系统定级备案和等级测试，具有完善的防火墙、入侵检测、数据加密以及灾难恢复等网络安全设施和管理制度，建立信息科技管理、科技风险管理和科技审计有关制度，配置充足的资源，采取完善的管理控制措施和技术手段保障信息系统安全稳健运行，保护出借人与借款人的信息安全。 网络借贷信息中介机构应当记录并留存借贷双方上网日志信息，信息交互内容等数据，留存期限为自借贷合同到期起5年；每两年至少开展一次全面的安全评估，接受国家或行业主管部门的信息安全检查和审计。 网络借贷信息中介机构成立两年以内，应当建立或使用与其业务规模相匹配的应用级灾备系统设施。"},{"i":19,"n":"第十九条","txt":"网络借贷信息中介机构应当为单一融资项目设置募集期，最长不超过20个工作日。"},{"i":20,"n":"第二十条","txt":"借款人支付的本金和利息应当归出借人所有。网络借贷信息中介机构应当与出借人、借款人另行约定费用标准和支付方式。"},{"i":21,"n":"第二十一条","txt":"网络借贷信息中介机构应当加强与金融信用信息基础数据库运行机构、征信机构等的业务合作，依法提供、查询和使用有关金融信用信息。"},{"i":22,"n":"第二十二条","txt":"各方参与网络借贷信息中介机构业务活动，需要对出借人与借款人的基本信息和交易信息等使用电子签名、电子认证时，应当遵守法律法规的规定，保障数据的真实性、完整性及电子签名、电子认证的法律效力。 网络借贷信息中介机构使用第三方数字认证系统，应当对第三方数字认证机构进行定期评估，保证有关认证安全可靠并具有独立性。"},{"i":23,"n":"第二十三条","txt":"网络借贷信息中介机构应当采取适当的方法和技术，记录并妥善保存网络借贷业务活动数据和资料，做好数据备份。保存期限应当符合法律法规及网络借贷有关监管规定的要求。借贷合同到期后应当至少保存５年。"},{"i":24,"n":"第二十四条","txt":"网络借贷信息中介机构暂停、终止业务时应当至少提前10个工作日通过官方网站等有效渠道向出借人与借款人公告，并通过移动电话、固定电话等渠道通知出借人与借款人。网络借贷信息中介机构业务暂停或者终止，不影响已经签订的借贷合同当事人有关权利义务。 网络借贷信息中介机构因解散或宣告破产而终止的，应当在解散或破产前，妥善处理已撮合存续的借贷业务，清算事宜按照有关法律法规的规定办理。 网络借贷信息中介机构清算时，出借人与借款人的资金分别属于出借人与借款人，不属于网络借贷信息中介机构的财产，不列入清算财产。"},{"i":25,"n":"第二十五条","txt":"未经出借人授权，网络借贷信息中介机构不得以任何形式代出借人行使决策。"},{"i":26,"n":"第二十六条","txt":"网络借贷信息中介机构应当向出借人以醒目方式提示网络借贷风险和禁止性行为，并经出借人确认。 网络借贷信息中介机构应当对出借人的年龄、财务状况、投资经验、风险偏好、风险承受能力等进行尽职评估，不得向未进行风险评估的出借人提供交易服务。 网络借贷信息中介机构应当根据风险评估结果对出借人实行分级管理，设置可动态调整的出借限额和出借标的限制。"},{"i":27,"n":"第二十七条","txt":"网络借贷信息中介机构应当加强出借人与借款人信息管理，确保出借人与借款人信息采集、处理及使用的合法性和安全性。 网络借贷信息中介机构及其资金存管机构、其他各类外包服务机构等应当为业务开展过程中收集的出借人与借款人信息保密，未经出借人与借款人同意，不得将出借人与借款人提供的信息用于所提供服务之外的目的。 在中国境内收集的出借人与借款人信息的储存、处理和分析应当在中国境内进行。除法律法规另有规定外，网络借贷信息中介机构不得向境外提供境内出借人和借款人信息。"},{"i":28,"n":"第二十八条","txt":"网络借贷信息中介机构应当实行自身资金与出借人和借款人资金的隔离管理，并选择符合条件的银行业金融机构作为出借人与借款人的资金存管机构。"},{"i":29,"n":"第二十九条","txt":"出借人与网络借贷信息中介机构之间、出借人与借款人之间、借款人与网络借贷信息中介机构之间等纠纷，可以通过以下途径解决： （一）自行和解； （二）请求行业自律组织调解； （三）向仲裁部门申请仲裁； （四）向人民法院提起诉讼。"},{"i":30,"n":"第三十条","txt":"网络借贷信息中介机构应当在其官方网站上向出借人充分披露借款人基本信息、融资项目基本信息、风险评估及可能产生的风险结果、已撮合未到期融资项目资金运用情况等有关信息。 披露内容应符合法律法规关于国家秘密、商业秘密、个人隐私的有关规定。"},{"i":31,"n":"第三十一条","txt":"网络借贷信息中介机构应当及时在其官方网站显著位置披露本机构所撮合借贷项目等经营管理信息。 网络借贷信息中介机构应当在其官方网站上建立业务活动经营管理信息披露专栏，定期以公告形式向公众披露年度报告、法律法规、网络借贷有关监管规定。 网络借贷信息中介机构应当聘请会计师事务所定期对本机构出借人与借款人资金存管、信息披露情况、信息科技基础设施安全、经营合规性等重点环节实施审计，并且应当聘请有资质的信息安全测评认证机构定期对信息安全实施测评认证，向出借人与借款人等披露审计和测评认证结果。 网络借贷信息中介机构应当引入律师事务所、信息系统安全评价等第三方机构，对网络信息中介机构合规和信息系统稳健情况进行评估。 网络借贷信息中介机构应当将定期信息披露公告文稿和相关备查文件报送工商登记注册地地方金融监管部门，并置备于机构住所供社会公众查阅。"},{"i":32,"n":"第三十二条","txt":"网络借贷信息中介机构的董事、监事、高级管理人员应当忠实、勤勉地履行职责，保证披露的信息真实、准确、完整、及时、公平，不得有虚假记载、误导性陈述或者重大遗漏。 借款人应当配合网络借贷信息中介机构及出借人对融资项目有关信息的调查核实，保证提供的信息真实、准确、完整。 网络借贷信息披露具体细则另行制定。"},{"i":33,"n":"第三十三条","txt":"国务院银行业监督管理机构及其派出机构负责制定统一的规范发展政策措施和监督管理制度，负责网络借贷信息中介机构的日常行为监管，指导和配合地方人民政府做好网络借贷信息中介机构的机构监管和风险处置工作，建立跨部门跨地区监管协调机制。 各地方金融监管部门具体负责本辖区网络借贷信息中介机构的机构监管，包括对本辖区网络借贷信息中介机构的规范引导、备案管理和风险防范、处置工作。"},{"i":34,"n":"第三十四条","txt":"中国互联网金融协会从事网络借贷行业自律管理，并履行下列职责： （一）制定自律规则、经营细则和行业标准并组织实施，教育会员遵守法律法规和网络借贷有关监管规定； （二）依法维护会员的合法权益，协调会员关系，组织相关培训，向会员提供行业信息、法律咨询等服务，调解纠纷； （三）受理有关投诉和举报，开展自律检查； （四）成立网络借贷专业委员会； （五）法律法规和网络借贷有关监管规定赋予的其他职责。"},{"i":35,"n":"第三十五条","txt":"借款人、出借人、网络借贷信息中介机构、资金存管机构、担保人等应当签订资金存管协议，明确各自权利义务和违约责任。 资金存管机构对出借人与借款人开立和使用资金账户进行管理和监督，并根据合同约定，对出借人与借款人的资金进行存管、划付、核算和监督。 资金存管机构承担实名开户和履行合同约定及借贷交易指令表面一致性的形式审核责任，但不承担融资项目及借贷交易信息真实性的实质审核责任。 资金存管机构应当按照网络借贷有关监管规定报送数据信息并依法接受相关监督管理。"},{"i":36,"n":"第三十六条","txt":"网络借贷信息中介机构应当在下列重大事件发生后，立即采取应急措施并向工商登记注册地地方金融监管部门报告： （一）因经营不善等原因出现重大经营风险； （二）网络借贷信息中介机构或其董事、监事、高级管理人员发生重大违法违规行为； （三）因商业欺诈行为被起诉，包括违规担保、夸大宣传、虚构隐瞒事实、发布虚假信息、签订虚假合同、错误处置资金等行为。 地方金融监管部门应当建立网络借贷行业重大事件的发现、报告和处置制度，制定处置预案，及时、有效地协调处置有关重大事件。 地方金融监管部门应当及时将本辖区网络借贷信息中介机构重大风险及处置情况信息报送省级人民政府、国务院银行业监督管理机构和中国人民银行。"},{"i":37,"n":"第三十七条","txt":"除本办法第七条规定的事项外，网络借贷信息中介机构发生下列情形的，应当在5个工作日以内向工商登记注册地地方金融监管部门报告： （一）因违规经营行为被查处或被起诉； （二）董事、监事、高级管理人员违反境内外相关法律法规行为； （三）国务院银行业监督管理机构、地方金融监管部门等要求的其他情形。"},{"i":38,"n":"第三十八条","txt":"网络借贷信息中介机构应当聘请会计师事务所进行年度审计，并在上一会计年度结束之日起4个月内向工商登记注册地地方金融监管部门报送年度审计报告。"},{"i":39,"n":"第三十九条","txt":"地方金融监管部门存在未依照本办法规定报告重大风险和处置情况、未依照本办法规定向国务院银行业监督管理机构提供行业统计或行业报告等违反法律法规及本办法规定情形的，应当对有关责任人依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"网络借贷信息中介机构违反法律法规和网络借贷有关监管规定，有关法律法规有处罚规定的，依照其规定给予处罚；有关法律法规未作处罚规定的，工商登记注册地地方金融监管部门可以采取监管谈话、出具警示函、责令改正、通报批评、将其违法违规和不履行公开承诺等情况记入诚信档案并公布等监管措施，以及给予警告、人民币３万元以下罚款和依法可以采取的其他处罚措施；构成犯罪的，依法追究刑事责任。 网络借贷信息中介机构违反法律规定从事非法集资活动或欺诈的，按照相关法律法规和工作机制处理；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"网络借贷信息中介机构的出借人及借款人违反法律法规和网络借贷有关监管规定，依照有关规定给予处罚；构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"银行业金融机构及国务院银行业监督管理机构批准设立的其他金融机构和省级人民政府批准设立的融资担保公司、小额贷款公司等投资设立具有独立法人资格的网络借贷信息中介机构，设立办法另行制定。"},{"i":43,"n":"第四十三条","txt":"中国互联网金融协会网络借贷专业委员会按照《关于促进互联网金融健康发展的指导意见》和协会章程开展自律并接受相关监管部门指导。"},{"i":44,"n":"第四十四条","txt":"本办法实施前设立的网络借贷信息中介机构不符合本办法规定的，除违法犯罪行为按照本办法第四十条处理外，由地方金融监管部门要求其整改，整改期不超过12个月。"},{"i":45,"n":"第四十五条","txt":"省级人民政府可以根据本办法制定实施细则，并报国务院银行业监督管理机构备案。"},{"i":46,"n":"第四十六条","txt":"本办法解释权归国务院银行业监督管理机构、工业和信息化部、公安部、国家互联网信息办公室。"},{"i":47,"n":"第四十七条","txt":"本办法所称不超过、以下、以内，包括本数。"}],"wangluochubanfuwuguanliguiding-2":[{"i":1,"n":"第一条","txt":"为了规范网络出版服务秩序，促进网络出版服务业健康有序发展，根据《出版管理条例》、《互联网信息服务管理办法》及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事网络出版服务，适用本规定。 本规定所称网络出版服务，是指通过信息网络向公众提供网络出版物。 本规定所称网络出版物，是指通过信息网络向公众提供的，具有编辑、制作、加工等出版特征的数字化作品，范围主要包括： （一）文学、艺术、科学等领域内具有知识性、思想性的文字、图片、地图、游戏、动漫、音视频读物等原创数字化作品； （二）与已出版的图书、报纸、期刊、音像制品、电子出版物等内容相一致的数字化作品； （三）将上述作品通过选择、编排、汇集等方式形成的网络文献数据库等数字化作品； （四）国家新闻出版广电总局认定的其他类型的数字化作品。 网络出版服务的具体业务分类另行制定。"},{"i":3,"n":"第三条","txt":"从事网络出版服务，应当遵守宪法和有关法律、法规，坚持为人民服务、为社会主义服务的方向，坚持社会主义先进文化的前进方向，弘扬社会主义核心价值观，传播和积累一切有益于提高民族素质、推动经济发展、促进社会进步的思想道德、科学技术和文化知识，满足人民群众日益增长的精神文化需要。"},{"i":4,"n":"第四条","txt":"国家新闻出版广电总局作为网络出版服务的行业主管部门，负责全国网络出版服务的前置审批和监督管理工作。工业和信息化部作为互联网行业主管部门，依据职责对全国网络出版服务实施相应的监督管理。 地方人民政府各级出版行政主管部门和各省级电信主管部门依据各自职责对本行政区域内网络出版服务及接入服务实施相应的监督管理工作并做好配合工作。"},{"i":5,"n":"第五条","txt":"出版行政主管部门根据已经取得的违法嫌疑证据或者举报，对涉嫌违法从事网络出版服务的行为进行查处时，可以检查与涉嫌违法行为有关的物品和经营场所；对有证据证明是与违法行为有关的物品，可以查封或者扣押。"},{"i":6,"n":"第六条","txt":"国家鼓励图书、音像、电子、报纸、期刊出版单位从事网络出版服务，加快与新媒体的融合发展。 国家鼓励组建网络出版服务行业协会，按照章程，在出版行政主管部门的指导下制定行业自律规范，倡导网络文明，传播健康有益内容，抵制不良有害内容。"},{"i":7,"n":"第七条","txt":"从事网络出版服务，必须依法经过出版行政主管部门批准，取得《网络出版服务许可证》。"},{"i":8,"n":"第八条","txt":"图书、音像、电子、报纸、期刊出版单位从事网络出版服务，应当具备以下条件： （一）有确定的从事网络出版业务的网站域名、智能终端应用程序等出版平台； （二）有确定的网络出版服务范围； （三）有从事网络出版服务所需的必要的技术设备，相关服务器和存储设备必须存放在中华人民共和国境内。"},{"i":9,"n":"第九条","txt":"其他单位从事网络出版服务，除第八条所列条件外，还应当具备以下条件： （一）有确定的、不与其他出版单位相重复的，从事网络出版服务主体的名称及章程； （二）有符合国家规定的法定代表人和主要负责人，法定代表人必须是在境内长久居住的具有完全行为能力的中国公民，法定代表人和主要负责人至少1人应当具有中级以上出版专业技术人员职业资格； （三）除法定代表人和主要负责人外，有适应网络出版服务范围需要的8名以上具有国家新闻出版广电总局认可的出版及相关专业技术职业资格的专职编辑出版人员，其中具有中级以上职业资格的人员不得少于3名； （四）有从事网络出版服务所需的内容审校制度； （五）有固定的工作场所； （六）法律、行政法规和国家新闻出版广电总局规定的其他条件。"},{"i":10,"n":"第十条","txt":"中外合资经营、中外合作经营和外资经营的单位不得从事网络出版服务。 网络出版服务单位与境内中外合资经营、中外合作经营、外资经营企业或境外组织及个人进行网络出版服务业务的项目合作，应当事前报国家新闻出版广电总局审批。"},{"i":11,"n":"第十一条","txt":"申请从事网络出版服务，应当向所在地省、自治区、直辖市出版行政主管部门提出申请，经审核同意后，报国家新闻出版广电总局审批。国家新闻出版广电总局应当自受理申请之日起60日内，作出批准或者不予批准的决定。不批准的，应当说明理由。"},{"i":12,"n":"第十二条","txt":"从事网络出版服务的申报材料，应该包括下列内容： （一）《网络出版服务许可证申请表》； （二）单位章程及资本来源性质证明； （三）网络出版服务可行性分析报告，包括资金使用、产品规划、技术条件、设备配备、机构设置、人员配备、市场分析、风险评估、版权保护措施等； （四）法定代表人和主要负责人的简历、住址、身份证明文件； （五）编辑出版等相关专业技术人员的国家认可的职业资格证明和主要从业经历及培训证明； （六）工作场所使用证明； （七）网站域名注册证明、相关服务器存放在中华人民共和国境内的承诺。 本规定第八条所列单位从事网络出版服务的，仅提交前款（一）、（六）、（七）项规定的材料。"},{"i":13,"n":"第十三条","txt":"设立网络出版服务单位的申请者应自收到批准决定之日起30日内办理注册登记手续： （一）持批准文件到所在地省、自治区、直辖市出版行政主管部门领取并填写《网络出版服务许可登记表》； （二）省、自治区、直辖市出版行政主管部门对《网络出版服务许可登记表》审核无误后，在10日内向申请者发放《网络出版服务许可证》； （三）《网络出版服务许可登记表》一式三份，由申请者和省、自治区、直辖市出版行政主管部门各存一份，另一份由省、自治区、直辖市出版行政主管部门在15日内报送国家新闻出版广电总局备案。"},{"i":14,"n":"第十四条","txt":"《网络出版服务许可证》有效期为5年。有效期届满，需继续从事网络出版服务活动的，应于有效期届满60日前按本规定第十一条的程序提出申请。出版行政主管部门应当在该许可有效期届满前作出是否准予延续的决定。批准的，换发《网络出版服务许可证》。"},{"i":15,"n":"第十五条","txt":"网络出版服务经批准后，申请者应持批准文件、《网络出版服务许可证》到所在地省、自治区、直辖市电信主管部门办理相关手续。"},{"i":16,"n":"第十六条","txt":"网络出版服务单位变更《网络出版服务许可证》许可登记事项、资本结构，合并或者分立，设立分支机构的，应依据本规定第十一条办理审批手续，并应持批准文件到所在地省、自治区、直辖市电信主管部门办理相关手续。"},{"i":17,"n":"第十七条","txt":"网络出版服务单位中止网络出版服务的，应当向所在地省、自治区、直辖市出版行政主管部门备案，并说明理由和期限；网络出版服务单位中止网络出版服务不得超过180日。 网络出版服务单位终止网络出版服务的，应当自终止网络出版服务之日起30日内，向所在地省、自治区、直辖市出版行政主管部门办理注销手续后到省、自治区、直辖市电信主管部门办理相关手续。省、自治区、直辖市出版行政主管部门将相关信息报国家新闻出版广电总局备案。"},{"i":18,"n":"第十八条","txt":"网络出版服务单位自登记之日起满180日未开展网络出版服务的，由原登记的出版行政主管部门注销登记，并报国家新闻出版广电总局备案。同时，通报相关省、自治区、直辖市电信主管部门。 因不可抗力或者其他正当理由发生上述所列情形的，网络出版服务单位可以向原登记的出版行政主管部门申请延期。"},{"i":19,"n":"第十九条","txt":"网络出版服务单位应当在其网站首页上标明出版行政主管部门核发的《网络出版服务许可证》编号。 互联网相关服务提供者在为网络出版服务单位提供人工干预搜索排名、广告、推广等服务时，应当查验服务对象的《网络出版服务许可证》及业务范围。"},{"i":20,"n":"第二十条","txt":"网络出版服务单位应当按照批准的业务范围从事网络出版服务，不得超出批准的业务范围从事网络出版服务。"},{"i":21,"n":"第二十一条","txt":"网络出版服务单位不得转借、出租、出卖《网络出版服务许可证》或以任何形式转让网络出版服务许可。 网络出版服务单位允许其他网络信息服务提供者以其名义提供网络出版服务，属于前款所称禁止行为。"},{"i":22,"n":"第二十二条","txt":"网络出版服务单位实行特殊管理股制度，具体办法由国家新闻出版广电总局另行制定。"},{"i":23,"n":"第二十三条","txt":"网络出版服务单位实行编辑责任制度，保障网络出版物内容合法。 网络出版服务单位实行出版物内容审核责任制度、责任编辑制度、责任校对制度等管理制度，保障网络出版物出版质量。 在网络上出版其他出版单位已在境内合法出版的作品且不改变原出版物内容的，须在网络出版物的相应页面显著标明原出版单位名称以及书号、刊号、网络出版物号或者网址信息。"},{"i":24,"n":"第二十四条","txt":"网络出版物不得含有以下内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）散布谣言，扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、色情、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":25,"n":"第二十五条","txt":"为保护未成年人合法权益，网络出版物不得含有诱发未成年人模仿违反社会公德和违法犯罪行为的内容，不得含有恐怖、残酷等妨害未成年人身心健康的内容，不得含有披露未成年人个人隐私的内容。"},{"i":26,"n":"第二十六条","txt":"网络出版服务单位出版涉及国家安全、社会安定等方面重大选题的内容，应当按照国家新闻出版广电总局有关重大选题备案管理的规定办理备案手续。未经备案的重大选题内容，不得出版。"},{"i":27,"n":"第二十七条","txt":"网络游戏上网出版前，必须向所在地省、自治区、直辖市出版行政主管部门提出申请，经审核同意后，报国家新闻出版广电总局审批。"},{"i":28,"n":"第二十八条","txt":"网络出版物的内容不真实或不公正，致使公民、法人或者其他组织合法权益受到侵害的，相关网络出版服务单位应当停止侵权，公开更正，消除影响，并依法承担其他民事责任。"},{"i":29,"n":"第二十九条","txt":"国家对网络出版物实行标识管理，具体办法由国家新闻出版广电总局另行制定。"},{"i":30,"n":"第三十条","txt":"网络出版物必须符合国家的有关规定和标准要求，保证出版物质量。 网络出版物使用语言文字，必须符合国家法律规定和有关标准规范。"},{"i":31,"n":"第三十一条","txt":"网络出版服务单位应当按照国家有关规定或技术标准，配备应用必要的设备和系统，建立健全各项管理制度，保障信息安全、内容合法，并为出版行政主管部门依法履行监督管理职责提供技术支持。"},{"i":32,"n":"第三十二条","txt":"网络出版服务单位在网络上提供境外出版物，应当取得著作权合法授权。其中，出版境外著作权人授权的网络游戏，须按本规定第二十七条办理审批手续。"},{"i":33,"n":"第三十三条","txt":"网络出版服务单位发现其出版的网络出版物含有本规定第二十四条、第二十五条所列内容的，应当立即删除，保存有关记录，并向所在地县级以上出版行政主管部门报告。"},{"i":34,"n":"第三十四条","txt":"网络出版服务单位应记录所出版作品的内容及其时间、网址或者域名，记录应当保存60日，并在国家有关部门依法查询时，予以提供。"},{"i":35,"n":"第三十五条","txt":"网络出版服务单位须遵守国家统计规定，依法向出版行政主管部门报送统计资料。"},{"i":36,"n":"第三十六条","txt":"网络出版服务的监督管理实行属地管理原则。 各地出版行政主管部门应当加强对本行政区域内的网络出版服务单位及其出版活动的日常监督管理，履行下列职责： （一）对网络出版服务单位进行行业监管，对网络出版服务单位违反本规定的情况进行查处并报告上级出版行政主管部门； （二）对网络出版服务进行监管，对违反本规定的行为进行查处并报告上级出版行政主管部门； （三）对网络出版物内容和质量进行监管，定期组织内容审读和质量检查，并将结果向上级出版行政主管部门报告； （四）对网络出版从业人员进行管理，定期组织岗位、业务培训和考核； （五）配合上级出版行政主管部门、协调相关部门、指导下级出版行政主管部门开展工作。"},{"i":37,"n":"第三十七条","txt":"出版行政主管部门应当加强监管队伍和机构建设，采取必要的技术手段对网络出版服务进行管理。出版行政主管部门依法履行监督检查等执法职责时，网络出版服务单位应当予以配合，不得拒绝、阻挠。 各省、自治区、直辖市出版行政主管部门应当定期将本行政区域内的网络出版服务监督管理情况向国家新闻出版广电总局提交书面报告。"},{"i":38,"n":"第三十八条","txt":"网络出版服务单位实行年度核验制度，年度核验每年进行一次。省、自治区、直辖市出版行政主管部门负责对本行政区域内的网络出版服务单位实施年度核验并将有关情况报国家新闻出版广电总局备案。年度核验内容包括网络出版服务单位的设立条件、登记项目、出版经营情况、出版质量、遵守法律规范、内部管理情况等。"},{"i":39,"n":"第三十九条","txt":"年度核验按照以下程序进行： （一）网络出版服务单位提交年度自检报告，内容包括：本年度政策法律执行情况，奖惩情况，网站出版、管理、运营绩效情况，网络出版物目录，对年度核验期内的违法违规行为的整改情况，编辑出版人员培训管理情况等；并填写由国家新闻出版广电总局统一印制的《网络出版服务年度核验登记表》，与年度自检报告一并报所在地省、自治区、直辖市出版行政主管部门； （二）省、自治区、直辖市出版行政主管部门对本行政区域内的网络出版服务单位的设立条件、登记项目、开展业务及执行法规等情况进行全面审核，并在收到网络出版服务单位的年度自检报告和《网络出版服务年度核验登记表》等年度核验材料的45日内完成全面审核查验工作。对符合年度核验要求的网络出版服务单位予以登记，并在其《网络出版服务许可证》上加盖年度核验章； （三）省、自治区、直辖市出版行政主管部门应于完成全面审核查验工作的15日内将年度核验情况及有关"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，暂缓年度核验： （一）正在停业整顿的； （二）违反出版法规规章，应予处罚的； （三）未按要求执行出版行政主管部门相关管理规定的； （四）内部管理混乱，无正当理由未开展实质性网络出版服务活动的； （五）存在侵犯著作权等其他违法嫌疑需要进一步核查的。 暂缓年度核验的期限由省、自治区、直辖市出版行政主管部门确定，报国家新闻出版广电总局备案，最长不得超过180日。暂缓年度核验期间，须停止网络出版服务。 暂缓核验期满，按本规定重新办理年度核验手续。"},{"i":41,"n":"第四十一条","txt":"已经不具备本规定第八条、第九条规定条件的，责令限期改正；逾期仍未改正的，不予通过年度核验，由国家新闻出版广电总局撤销《网络出版服务许可证》，所在地省、自治区、直辖市出版行政主管部门注销登记，并通知当地电信主管部门依法处理。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市出版行政主管部门可根据实际情况，对本行政区域内的年度核验事项进行调整，相关情况报国家新闻出版广电总局备案。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市出版行政主管部门可以向社会公布年度核验结果。"},{"i":44,"n":"第四十四条","txt":"从事网络出版服务的编辑出版等相关专业技术人员及其负责人应当符合国家关于编辑出版等相关专业技术人员职业资格管理的有关规定。 网络出版服务单位的法定代表人或主要负责人应按照有关规定参加出版行政主管部门组织的岗位培训，并取得国家新闻出版广电总局统一印制的《岗位培训合格证书》。未按规定参加岗位培训或培训后未取得《岗位培训合格证书》的，不得继续担任法定代表人或主要负责人。"},{"i":45,"n":"第四十五条","txt":"国家制定有关政策，保障、促进网络出版服务业的发展与繁荣。鼓励宣传科学真理、传播先进文化、倡导科学精神、塑造美好心灵、弘扬社会正气等有助于形成先进网络文化的网络出版服务，推动健康文化、优秀文化产品的数字化、网络化传播。 网络出版服务单位依法从事网络出版服务，任何组织和个人不得干扰、阻止和破坏。"},{"i":46,"n":"第四十六条","txt":"国家支持、鼓励下列优秀的、重点的网络出版物的出版： （一）对阐述、传播宪法确定的基本原则有重大作用的； （二）对弘扬社会主义核心价值观，进行爱国主义、集体主义、社会主义和民族团结教育以及弘扬社会公德、职业道德、家庭美德、个人品德有重要意义的； （三）对弘扬民族优秀文化，促进国际文化交流有重大作用的； （四）具有自主知识产权和优秀文化内涵的； （五）对推进文化创新，及时反映国内外新的科学文化成果有重大贡献的； （六）对促进公共文化服务有重大作用的； （七）专门以未成年人为对象、内容健康的或者其他有利于未成年人健康成长的； （八）其他具有重要思想价值、科学价值或者文化艺术价值的。"},{"i":47,"n":"第四十七条","txt":"对为发展、繁荣网络出版服务业作出重要贡献的单位和个人，按照国家有关规定给予奖励。"},{"i":48,"n":"第四十八条","txt":"国家保护网络出版物著作权人的合法权益。网络出版服务单位应当遵守《中华人民共和国著作权法》、《信息网络传播权保护条例》、《计算机软件保护条例》等著作权法律法规。"},{"i":49,"n":"第四十九条","txt":"对非法干扰、阻止和破坏网络出版物出版的行为，出版行政主管部门及其他有关部门，应当及时采取措施，予以制止。"},{"i":50,"n":"第五十条","txt":"网络出版服务单位违反本规定的，出版行政主管部门可以采取下列行政措施： （一）下达警示通知书； （二）通报批评、责令改正； （三）责令公开检讨； （四）责令删除违法内容。 警示通知书由国家新闻出版广电总局制定统一格式，由出版行政主管部门下达给相关网络出版服务单位。 本条所列的行政措施可以并用。"},{"i":51,"n":"第五十一条","txt":"未经批准，擅自从事网络出版服务，或者擅自上网出版网络游戏（含境外著作权人授权的网络游戏），根据《出版管理条例》第六十一条、《互联网信息服务管理办法》第十九条的规定，由出版行政主管部门、工商行政管理部门依照法定职权予以取缔，并由所在地省级电信主管部门依据有关部门的通知，按照《互联网信息服务管理办法》第十九条的规定给予责令关闭网站等处罚；已经触犯刑法的，依法追究刑事责任；尚不够刑事处罚的，删除全部相关网络出版物，没收违法所得和从事违法出版活动的主要设备、专用工具，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；侵犯他人合法权益的，依法承担民事责任。"},{"i":52,"n":"第五十二条","txt":"出版、传播含有本规定第二十四条、第二十五条禁止内容的网络出版物的，根据《出版管理条例》第六十二条、《互联网信息服务管理办法》第二十条的规定，由出版行政主管部门责令删除相关内容并限期改正，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下罚款；违法经营额不足1万元的，可以处5万元以下罚款；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》，由电信主管部门依据出版行政主管部门的通知吊销其电信业务经营许可或者责令关闭网站；构成犯罪的，依法追究刑事责任。 为从事本条第一款行为的网络出版服务单位提供人工干预搜索排名、广告、推广等相关服务的，由出版行政主管部门责令其停止提供相关服务。"},{"i":53,"n":"第五十三条","txt":"违反本规定第二十一条的，根据《出版管理条例》第六十六条的规定，由出版行政主管部门责令停止违法行为，给予警告，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》。"},{"i":54,"n":"第五十四条","txt":"有下列行为之一的，根据《出版管理条例》第六十七条的规定，由出版行政主管部门责令改正，给予警告；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》： （一）网络出版服务单位变更《网络出版服务许可证》登记事项、资本结构，超出批准的服务范围从事网络出版服务，合并或者分立，设立分支机构，未依据本规定办理审批手续的； （二）网络出版服务单位未按规定出版涉及重大选题出版物的； （三）网络出版服务单位擅自中止网络出版服务超过180日的； （四）网络出版物质量不符合有关规定和标准的。"},{"i":55,"n":"第五十五条","txt":"违反本规定第三十四条的，根据《互联网信息服务管理办法》第二十一条的规定，由省级电信主管部门责令改正；情节严重的，责令停业整顿或者暂时关闭网站。"},{"i":56,"n":"第五十六条","txt":"网络出版服务单位未依法向出版行政主管部门报送统计资料的，依据《新闻出版统计管理办法》处罚。"},{"i":57,"n":"第五十七条","txt":"网络出版服务单位违反本规定第二章规定，以欺骗或者贿赂等不正当手段取得许可的，由国家新闻出版广电总局撤销其相应许可。"},{"i":58,"n":"第五十八条","txt":"有下列行为之一的，由出版行政主管部门责令改正，予以警告，并处3万元以下罚款： （一）违反本规定第十条，擅自与境内外中外合资经营、中外合作经营和外资经营的企业进行涉及网络出版服务业务的合作的； （二）违反本规定第十九条，未标明有关许可信息或者未核验有关网站的《网络出版服务许可证》的； （三）违反本规定第二十三条，未按规定实行编辑责任制度等管理制度的； （四）违反本规定第三十一条，未按规定或标准配备应用有关系统、设备或未健全有关管理制度的； （五）未按本规定要求参加年度核验的； （六）违反本规定第四十四条，网络出版服务单位的法定代表人或主要负责人未取得《岗位培训合格证书》的； （七）违反出版行政主管部门关于网络出版其他管理规定的。"},{"i":59,"n":"第五十九条","txt":"网络出版服务单位违反本规定被处以吊销许可证行政处罚的，其法定代表人或者主要负责人自许可证被吊销之日起10年内不得担任网络出版服务单位的法定代表人或者主要负责人。 从事网络出版服务的编辑出版等相关专业技术人员及其负责人违反本规定，情节严重的，由原发证机关吊销其资格证书。"},{"i":60,"n":"第六十条","txt":"本规定所称出版物内容审核责任制度、责任编辑制度、责任校对制度等管理制度，参照《图书质量保障体系》的有关规定执行。"},{"i":61,"n":"第六十一条","txt":"本规定自2016年3月10日起施行。原国家新闻出版总署、信息产业部2002年6月27日颁布的《互联网出版管理暂行规定》同时废止。"}],"guifanhulianwangxinxifuwushichangzhixuruoganguidin311944":[{"i":1,"n":"第一条","txt":"为了规范互联网信息服务市场秩序，保护互联网信息服务提供者和用户的合法权益，促进互联网行业的健康发展，根据《中华人民共和国电信条例》、《互联网信息服务管理办法》等法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事互联网信息服务及与互联网信息服务有关的活动，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"工业和信息化部和各省、自治区、直辖市通信管理局（以下统称“电信管理机构”）依法对互联网信息服务活动实施监督管理。"},{"i":4,"n":"第四条","txt":"互联网信息服务提供者应当遵循平等、自愿、公平、诚信的原则提供服务。"},{"i":5,"n":"第五条","txt":"互联网信息服务提供者不得实施下列侵犯其他互联网信息服务提供者合法权益的行为： （一）恶意干扰用户终端上其他互联网信息服务提供者的服务，或者恶意干扰与互联网信息服务相关的软件等产品（“与互联网信息服务相关的软件等产品”以下简称“产品”）的下载、安装、运行和升级； （二）捏造、散布虚假事实损害其他互联网信息服务提供者的合法权益，或者诋毁其他互联网信息服务提供者的服务或者产品； （三）恶意对其他互联网信息服务提供者的服务或者产品实施不兼容； （四）欺骗、误导或者强迫用户使用或者不使用其他互联网信息服务提供者的服务或者产品； （五）恶意修改或者欺骗、误导、强迫用户修改其他互联网信息服务提供者的服务或者产品参数； （六）其他违反国家法律规定，侵犯其他互联网信息服务提供者合法权益的行为。"},{"i":6,"n":"第六条","txt":"对互联网信息服务提供者的服务或者产品进行评测，应当客观公正。 评测方公开或者向用户提供评测结果的，应当同时提供评测实施者、评测方法、数据来源、用户原始评价、评测手段和评测环境等与评测活动相关的信息。评测结果应当真实准确，与评测活动相关的信息应当完整全面。被评测的服务或者产品与评测方的服务或者产品相同或者功能类似的，评测结果中不得含有评测方的主观评价。 被评测方对评测结果有异议的，可以自行或者委托第三方就评测结果进行再评测，评测方应当予以配合。 评测方不得利用评测结果，欺骗、误导、强迫用户对被评测方的服务或者产品作出处置。 本规定所称评测，是指提供平台供用户评价，或者以其他方式对互联网信息服务或者产品的性能等进行评价和测试。"},{"i":7,"n":"第七条","txt":"互联网信息服务提供者不得实施下列侵犯用户合法权益的行为： （一）无正当理由拒绝、拖延或者中止向用户提供互联网信息服务或者产品； （二）无正当理由限定用户使用或者不使用其指定的互联网信息服务或者产品； （三）以欺骗、误导或者强迫等方式向用户提供互联网信息服务或者产品； （四）提供的互联网信息服务或者产品与其向用户所作的宣传或者承诺不符； （五）擅自改变服务协议或者业务规程，降低服务质量或者加重用户责任； （六）与其他互联网信息服务提供者的服务或者产品不兼容时，未主动向用户提示和说明； （七）未经提示并由用户主动选择同意，修改用户浏览器配置或者其他设置； （八）其他违反国家法律规定，侵犯用户合法权益的行为。"},{"i":8,"n":"第八条","txt":"互联网信息服务提供者在用户终端上进行软件下载、安装、运行、升级、卸载等操作的，应当提供明确、完整的软件功能等信息，并事先征得用户同意。 互联网信息服务提供者不得实施下列行为： （一）欺骗、误导或者强迫用户下载、安装、运行、升级、卸载软件； （二）未提供与软件安装方式同等或者更便捷的卸载方式； （三）在未受其他软件影响和人为破坏的情况下，未经用户主动选择同意，软件卸载后有可执行代码或者其他不必要的文件驻留在用户终端。"},{"i":9,"n":"第九条","txt":"互联网信息服务终端软件捆绑其他软件的，应当以显著的方式提示用户，由用户主动选择是否安装或者使用，并提供独立的卸载或者关闭方式，不得附加不合理条件。"},{"i":10,"n":"第十条","txt":"互联网信息服务提供者在用户终端弹出广告或者其他与终端软件功能无关的信息窗口的，应当以显著的方式向用户提供关闭或者退出窗口的功能标识。"},{"i":11,"n":"第十一条","txt":"未经用户同意，互联网信息服务提供者不得收集与用户相关、能够单独或者与其他信息结合识别用户的信息（以下简称“用户个人信息”），不得将用户个人信息提供给他人，但是法律、行政法规另有规定的除外。 互联网信息服务提供者经用户同意收集用户个人信息的，应当明确告知用户收集和处理用户个人信息的方式、内容和用途，不得收集其提供服务所必需以外的信息，不得将用户个人信息用于其提供服务之外的目的。"},{"i":12,"n":"第十二条","txt":"互联网信息服务提供者应当妥善保管用户个人信息；保管的用户个人信息泄露或者可能泄露时，应当立即采取补救措施；造成或者可能造成严重后果的，应当立即向准予其互联网信息服务许可或者备案的电信管理机构报告，并配合相关部门进行的调查处理。"},{"i":13,"n":"第十三条","txt":"互联网信息服务提供者应当加强系统安全防护，依法维护用户上载信息的安全，保障用户对上载信息的使用、修改和删除。 互联网信息服务提供者不得有下列行为： （一）无正当理由擅自修改或者删除用户上载信息； （二）未经用户同意，向他人提供用户上载信息，但是法律、行政法规另有规定的除外； （三）擅自或者假借用户名义转移用户上载信息，或者欺骗、误导、强迫用户转移其上载信息； （四）其他危害用户上载信息安全的行为。"},{"i":14,"n":"第十四条","txt":"互联网信息服务提供者应当以显著的方式公布有效联系方式，接受用户及其他互联网信息服务提供者的投诉，并自接到投诉之日起十五日内作出答复。"},{"i":15,"n":"第十五条","txt":"互联网信息服务提供者认为其他互联网信息服务提供者实施违反本规定的行为，侵犯其合法权益并对用户权益造成或者可能造成重大影响的，应当立即向准予该其他互联网信息服务提供者互联网信息服务许可或者备案的电信管理机构报告。 电信管理机构应当对报告或者发现的可能违反本规定的行为的影响进行评估；影响特别重大的，相关省、自治区、直辖市通信管理局应当向工业和信息化部报告。电信管理机构在依据本规定作出处理决定前，可以要求互联网信息服务提供者暂停有关行为，互联网信息服务提供者应当执行。"},{"i":16,"n":"第十六条","txt":"互联网信息服务提供者违反本规定第五条、第七条或者第十三条的规定，由电信管理机构依据职权责令改正，处以警告，可以并处一万元以上三万元以下的罚款，向社会公告；其中，《中华人民共和国电信条例》或者《互联网信息服务管理办法》规定法律责任的，依照其规定处理。"},{"i":17,"n":"第十七条","txt":"评测方违反本规定第六条的规定的，由电信管理机构依据职权处以警告，可以并处一万元以上三万元以下的罚款，向社会公告。"},{"i":18,"n":"第十八条","txt":"互联网信息服务提供者违反本规定第八条、第九条、第十条、第十一条、第十二条或者第十四条的规定的，由电信管理机构依据职权处以警告，可以并处一万元以上三万元以下的罚款，向社会公告。"},{"i":19,"n":"第十九条","txt":"互联网信息服务提供者违反本规定第十五条规定，不执行电信管理机构暂停有关行为的要求的，由电信管理机构依据职权处以警告，向社会公告。"},{"i":20,"n":"第二十条","txt":"互联网信息服务提供者违反其他法律、行政法规规定的，依照其规定处理。"},{"i":21,"n":"第二十一条","txt":"本规定自2012年3月15日起施行。"}],"bianjingdiqudimianwuxiandianyewupinlvguojixietiaogc0f6c5":[{"i":1,"n":"第一条","txt":"为了加强边境地区无线电频率和无线电台（站）管理，规范地面无线电业务频率国际协调活动，维护我国无线电频谱资源权益和空中电波秩序，根据《中华人民共和国无线电管理条例》和国际电信联盟《无线电规则》，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国边境地区地面无线电业务频率国际协调及监督管理活动，适用本规定。 本规定所称地面无线电业务频率国际协调（以下简称频率协调），是指为了实现无线电频率高效利用，减少和避免边境地区无线电台（站）与境外无线电台（站）之间的有害干扰，国家无线电管理机构与相邻国家无线电管理机构就边境地区地面无线电业务频率划分、规划、分配和使用等事宜，进行双边会谈，签订和履行相关双边协议、会议纪要等的活动。"},{"i":3,"n":"第三条","txt":"国家无线电管理机构统一负责频率协调并监督检查有关双边协议、会议纪要及其他双方协调一致事项的执行情况。 边境省、自治区无线电管理机构负责本辖区内电磁环境测试、监督检查等频率协调相关工作。"},{"i":4,"n":"第四条","txt":"频率协调应当遵循平等互利、合作共赢的原则，遵守我国无线电管理法律、行政法规和《无线电规则》以及我国与相邻国家签订的双边协议、会议纪要。"},{"i":5,"n":"第五条","txt":"按照本规定与相邻国家完成频率协调的无线电台（站）和频率，受双方保护；列入国际频率登记总表的无线电台（站）和频率，受国际保护。"},{"i":6,"n":"第六条","txt":"国家无线电管理机构与相邻国家无线电管理机构就频率的划分、规划和分配做出特别安排的，应当依据《无线电规则》的规定进行双边会谈，协商一致。"},{"i":7,"n":"第七条","txt":"国家无线电管理机构与相邻国家无线电管理机构进行双边会谈，应当根据有关部门职责和会谈内容，邀请有关部门和相关边境省、自治区无线电管理机构等单位组成频率协调代表团，并按照批准的会谈预案进行会谈。"},{"i":8,"n":"第八条","txt":"双边会谈需要进行技术准备的，经与相邻国家无线电管理机构协商一致，国家无线电管理机构可以会同有关部门、相关边境省、自治区无线电管理机构等单位，组织技术专家与相邻国家无线电管理机构进行技术会谈。"},{"i":9,"n":"第九条","txt":"进行双边会谈，经与相邻国家无线电管理机构协商一致，可以签订会议纪要。会议纪要应当载明会谈内容、进程及相关成果。会议纪要由国家无线电管理机构频率协调代表团团长签署。"},{"i":10,"n":"第十条","txt":"双边会谈结束，经协商一致以国家无线电管理机构名义与相邻国家无线电管理机构签订双边协议的，由国家无线电管理机构负责人或者其授权代表签署。"},{"i":11,"n":"第十一条","txt":"会谈签订的双边协议、会议纪要，依法履行国内相关批准或者登记等手续后，由国家无线电管理机构通知相邻国家无线电管理机构和国内相关单位，但双边协议、会议纪要中另有规定的除外。"},{"i":12,"n":"第十二条","txt":"双边协议、会议纪要以中文和另一方的官方文字写成，两种文本同等作准。必要时，可使用双方同意的一种第三国文字。 双边协议应当规定有效期，有效期一般不少于两年。"},{"i":13,"n":"第十三条","txt":"边境地区无线电台（站）使用频率的协调，主要采用函件形式开展。 在边境地区设置批量无线电台（站）或者重要无线电台（站），其拟使用的频率，经与相邻国家无线电管理机构协商，可以纳入双边会谈。纳入双边会谈的，会谈程序同时适用本规定第二章相关规定。"},{"i":14,"n":"第十四条","txt":"边境地区无线电台（站）使用频率需要获得双方保护或者国际保护的，设台用户应当向所在地的省、自治区无线电管理机构或者其上级业务主管部门提出频率协调申请。"},{"i":15,"n":"第十五条","txt":"申请在边境地区设置使用无线电台（站），符合下列情形之一的，省、自治区无线电管理机构应当告知申请人需要进行频率协调: （一）根据我国与相邻国家签订的双边协议或者会议纪要应当进行协调的； （二）无线电信号可能产生跨境覆盖，并对境外合法无线电台（站）及其使用的相应频率造成有害干扰的； （三）用于跨境通信的； （四）《无线电规则》规定应当进行协调的其他情形。 前款所称境外合法无线电台（站），是指列入国际频率登记总表的无线电台（站）或者与我国完成频率协调的无线电台（站）。"},{"i":16,"n":"第十六条","txt":"未经频率协调或者未列入国际频率登记总表的无线电台（站）及其使用的相应频率，不得向我国无线电管理机构提出干扰保护要求（《无线电规则》另有规定的除外），不得对境外合法无线电台（站）及其使用的相应频率造成有害干扰。 本规定第十五条第一款第二项和第三项规定的无线电台（站）未经频率协调的，不得核发无线电台执照，不得擅自设置使用。"},{"i":17,"n":"第十七条","txt":"设台用户申请频率协调的，应当按照国际电信联盟或者有关双边协议、会议纪要规定的格式（由国家无线电管理机构提供范本）填写有关资料，经所在的省、自治区无线电管理机构或者其上级业务主管部门审查后报国家无线电管理机构。"},{"i":18,"n":"第十八条","txt":"省、自治区无线电管理机构或者设台用户的上级业务主管部门收到频率协调资料后，应当对站址、电磁兼容和干扰情况进行审查，提出预协调意见并连同相关材料报国家无线电管理机构。"},{"i":19,"n":"第十九条","txt":"国家无线电管理机构根据《无线电规则》或者有关双边协议、会议纪要，对频率协调资料和预协调意见进行审核。 经审核符合《无线电规则》或者有关双边协议、会议纪要的，国家无线电管理机构向国际电信联盟或者相邻国家无线电管理机构发送协调函件。"},{"i":20,"n":"第二十条","txt":"境外地面无线电业务寻求与我国进行频率协调的，由国家无线电管理机构统一受理相邻国家无线电管理机构的协调函件，按照本规定第十九条第一款进行审核，并根据频率协调涉及的地域、频段和业务，征求有关部门和相关省、自治区无线电管理机构等单位意见。 受询单位应当在规定的时限内，将本单位对相邻国家无线电管理机构协调函件的意见反馈国家无线电管理机构。在规定时限内不反馈意见的，按照《无线电规则》或者有关双边协议的规定，视为无反对意见。 国家无线电管理机构根据审核结果和征求意见情况，形成关于频率协调的意见，反馈相邻国家无线电管理机构；必要时，抄送国际电信联盟。"},{"i":21,"n":"第二十一条","txt":"相邻国家无线电管理机构对国家无线电管理机构关于频率协调的意见或者协调函件有异议并请求进一步协调，国家无线电管理机构同意再次协调的，有关部门和相关省、自治区无线电管理机构等单位应当配合进行协调。"},{"i":22,"n":"第二十二条","txt":"频率协调完成后，国家无线电管理机构将协调结果通知有关部门和相关省、自治区无线电管理机构以及设台用户。"},{"i":23,"n":"第二十三条","txt":"设台用户或者其上级业务主管部门应当按照国际电信联盟或者有关双边协议、会议纪要的规定，将完成频率协调的无线电台（站）资料（含电子资料）报国家无线电管理机构，由国家无线电管理机构履行国际电信联盟通知登记程序，或者列入国家频率总表。"},{"i":24,"n":"第二十四条","txt":"双边协议、会议纪要生效或者无线电台（站）使用频率的协调完成后，相关频率使用人和设台用户应当按照双边协议、会议纪要或者协调结果的要求，按时完成相关的频率和台站调整、设备更换等工作，并向国家无线电管理机构报告执行进展情况。"},{"i":25,"n":"第二十五条","txt":"国家无线电管理机构根据有关双边协议执行情况和国家对外方针政策，及时处理有关双边协议延续、废止、重签、修订等事宜。"},{"i":26,"n":"第二十六条","txt":"边境省、自治区无线电管理机构应当按照国家有关标准和技术规范，建立频率协调所需的无线电台（站）数据库和监测数据库，定期对边境地区口岸、机场、港口及人口密集区等频率协调重点区域开展电磁环境测试，并记录相关数据。 边境省、自治区无线电管理机构监测到不符合《无线电规则》或者有关双边协议、会议纪要、协调结果规定的境外无线电信号后，应当及时报告国家无线电管理机构，由国家无线电管理机构审查后向国际电信联盟或者相关国家无线电管理机构提出申诉；情况重大或者紧急的，应当及时专报国家无线电管理机构，由国家无线电管理机构作出应对方案，相关边境省、自治区无线电管理机构应当配合执行。"},{"i":27,"n":"第二十七条","txt":"频率协调完成后，相邻国家无线电台（站）违反《无线电规则》或者有关双边协议、会议纪要、协调结果的规定，对我国边境地区无线电台（站）和频率造成有害干扰的，受干扰单位可以报请国家无线电管理机构向国际电信联盟或者相关国家无线电管理机构提出干扰申诉。"},{"i":28,"n":"第二十八条","txt":"频率协调完成后，因电波传播等客观原因与境外合法无线电台（站）仍存在相互干扰的，可以再次进行协调。"},{"i":29,"n":"第二十九条","txt":"在边境地区未按照《无线电规则》或者有关双边协议、会议纪要、协调结果规定的频率、功率等参数设置使用无线电台（站）的，由国家无线电管理机构或者相关省、自治区无线电管理机构责令限期改正，并依照《中华人民共和国无线电管理条例》等规定处罚。"},{"i":30,"n":"第三十条","txt":"未经频率协调，设置使用的无线电台（站）对境外合法无线电台（站）及其使用的相应频率造成有害干扰并受到相邻国家无线电管理机构干扰申诉的，由国家无线电管理机构或者相关省、自治区无线电管理机构责令消除干扰，并依照《中华人民共和国无线电管理条例》等规定处罚。"},{"i":31,"n":"第三十一条","txt":"本规定所称地面无线电业务，是指除空间无线电业务或者射电天文以外的任何无线电业务，包括固定业务、陆地移动业务、水上移动业务、港口操作业务、航空移动业务、广播业务、无线电定位业务、无线电导航业务、气象辅助业务、业余业务、安全业务等。"},{"i":32,"n":"第三十二条","txt":"境外空间无线电业务与我国地面无线电业务进行频率协调的，依据《无线电规则》的有关规定进行。 航空无线电专用频率国际协调办法另行制定。"},{"i":33,"n":"第三十三条","txt":"本规定自2017年2月1日起施行。原信息产业部2007年7月19日发布的《边境地区地面无线电业务国际频率协调暂行规定》（信部无〔2007〕336号）同时废止。"}],"tongxingongchengjianshexiangmuzhaobiaotoubiaoguanl22c6d2":[{"i":1,"n":"第一条","txt":"为了规范通信工程建设项目招标投标活动，根据《中华人民共和国招标投标法》（以下简称《招标投标法》）和《中华人民共和国招标投标法实施条例》（以下简称《实施条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行通信工程建设项目招标投标活动，适用本办法。 前款所称通信工程建设项目，是指通信工程以及与通信工程建设有关的货物、服务。其中，通信工程包括通信设施或者通信网络的新建、改建、扩建、拆除等施工；与通信工程建设有关的货物，是指构成通信工程不可分割的组成部分，且为实现通信工程基本功能所必需的设备、材料等；与通信工程建设有关的服务，是指为完成通信工程所需的勘察、设计、监理等服务。 依法必须进行招标的通信工程建设项目的具体范围和规模标准，依据国家有关规定确定。"},{"i":3,"n":"第三条","txt":"工业和信息化部和各省、自治区、直辖市通信管理局（以下统称为“通信行政监督部门”）依法对通信工程建设项目招标投标活动实施监督。"},{"i":4,"n":"第四条","txt":"工业和信息化部鼓励按照《电子招标投标办法》进行通信工程建设项目电子招标投标。"},{"i":5,"n":"第五条","txt":"工业和信息化部建立“通信工程建设项目招标投标管理信息平台”（以下简称“管理平台”），实行通信工程建设项目招标投标活动信息化管理。"},{"i":6,"n":"第六条","txt":"国有资金占控股或者主导地位的依法必须进行招标的通信工程建设项目，应当公开招标；但有下列情形之一的，可以邀请招标： （一）技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择； （二）采用公开招标方式的费用占项目合同金额的比例过大。 有前款第一项所列情形，招标人邀请招标的，应当向其知道或者应当知道的全部潜在投标人发出投标邀请书。 采用公开招标方式的费用占项目合同金额的比例超过1.5%，且采用邀请招标方式的费用明显低于公开招标方式的费用的，方可被认定为有本条第一款第二项所列情形。"},{"i":7,"n":"第七条","txt":"除《招标投标法》第六十六条和《实施条例》第九条规定的可以不进行招标的情形外，潜在投标人少于3个的，可以不进行招标。 招标人为适用前款规定弄虚作假的，属于《招标投标法》第四条规定的规避招标。"},{"i":8,"n":"第八条","txt":"依法必须进行招标的通信工程建设项目的招标人自行办理招标事宜的，应当自发布招标公告或者发出投标邀请书之日起2日内通过“管理平台”向通信行政监督部门提交《通信工程建设项目自行招标备案表》(见附录一)。"},{"i":9,"n":"第九条","txt":"招标代理机构代理招标业务，适用《招标投标法》、《实施条例》和本办法关于招标人的规定。"},{"i":10,"n":"第十条","txt":"公开招标的项目，招标人采用资格预审办法对潜在投标人进行资格审查的，应当发布资格预审公告、编制资格预审文件。招标人发布资格预审公告后，可不再发布招标公告。 依法必须进行招标的通信工程建设项目的资格预审公告和招标公告，除在国家发展和改革委员会依法指定的媒介发布外，还应当在“管理平台”发布。在不同媒介发布的同一招标项目的资格预审公告或者招标公告的内容应当一致。"},{"i":11,"n":"第十一条","txt":"资格预审公告、招标公告或者投标邀请书应当载明下列内容： （一）招标人的名称和地址； （二）招标项目的性质、内容、规模、技术要求和资金来源； （三）招标项目的实施或者交货时间和地点要求； （四）获取招标文件或者资格预审文件的时间、地点和方法； （五）对招标文件或者资格预审文件收取的费用； （六）提交资格预审申请文件或者投标文件的地点和截止时间。 招标人对投标人的资格要求，应当在资格预审公告、招标公告或者投标邀请书中载明。"},{"i":12,"n":"第十二条","txt":"资格预审文件一般包括下列内容： （一）资格预审公告； （二）申请人须知； （三）资格要求； （四）业绩要求； （五）资格审查标准和方法； （六）资格预审结果的通知方式； （七）资格预审申请文件格式。 资格预审应当按照资格预审文件载明的标准和方法进行，资格预审文件没有规定的标准和方法不得作为资格预审的依据。"},{"i":13,"n":"第十三条","txt":"招标人应当根据招标项目的特点和需要编制招标文件。招标文件一般包括下列内容： （一）招标公告或者投标邀请书； （二）投标人须知； （三）投标文件格式； （四）项目的技术要求； （五）投标报价要求； （六）评标标准、方法和条件； （七）网络与信息安全有关要求； （八）合同主要条款。 招标文件应当载明所有评标标准、方法和条件，并能够指导评标工作，在评标过程中不得作任何改变。"},{"i":14,"n":"第十四条","txt":"招标人应当在招标文件中以显著的方式标明实质性要求、条件以及不满足实质性要求和条件的投标将被否决的提示；对于非实质性要求和条件，应当规定允许偏差的最大范围、最高项数和调整偏差的方法。"},{"i":15,"n":"第十五条","txt":"编制依法必须进行招标的通信工程建设项目资格预审文件和招标文件，应当使用国家发展和改革委员会会同有关行政监督部门制定的标准文本及工业和信息化部制定的范本。"},{"i":16,"n":"第十六条","txt":"勘察设计招标项目的评标标准一般包括下列内容： （一）投标人的资质、业绩、财务状况和履约表现； （二）项目负责人的资格和业绩； （三）勘察设计团队人员； （四）技术方案和技术创新； （五）质量标准及质量管理措施； （六）技术支持与保障； （七）投标价格； （八）组织实施方案及进度安排。"},{"i":17,"n":"第十七条","txt":"监理招标项目的评标标准一般包括下列内容： （一）投标人的资质、业绩、财务状况和履约表现； （二）项目总监理工程师的资格和业绩； （三）主要监理人员及安全监理人员； （四）监理大纲； （五）质量和安全管理措施； （六）投标价格。"},{"i":18,"n":"第十八条","txt":"施工招标项目的评标标准一般包括下列内容： （一）投标人的资质、业绩、财务状况和履约表现； （二）项目负责人的资格和业绩； （三）专职安全生产管理人员； （四）主要施工设备及施工安全防护设施； （五）质量和安全管理措施； （六）投标价格； （七）施工组织设计及安全生产应急预案。"},{"i":19,"n":"第十九条","txt":"与通信工程建设有关的货物招标项目的评标标准一般包括下列内容： （一）投标人的资质、业绩、财务状况和履约表现； （二）投标价格； （三）技术标准及质量标准； （四）组织供货计划； （五）售后服务。"},{"i":20,"n":"第二十条","txt":"评标方法包括综合评估法、经评审的最低投标价法或者法律、行政法规允许的其他评标方法。 鼓励通信工程建设项目使用综合评估法进行评标。"},{"i":21,"n":"第二十一条","txt":"通信工程建设项目需要划分标段的，招标人应当在招标文件中载明允许投标人中标的最多标段数。"},{"i":22,"n":"第二十二条","txt":"通信工程建设项目已确定投资计划并落实资金来源的，招标人可以将多个同类通信工程建设项目集中进行招标。 招标人进行集中招标的，应当遵守《招标投标法》、《实施条例》和本办法有关依法必须进行招标的项目的规定。"},{"i":23,"n":"第二十三条","txt":"招标人进行集中招标的，应当在招标文件中载明工程或者有关货物、服务的类型、预估招标规模、中标人数量及每个中标人对应的中标份额等；对与工程或者有关服务进行集中招标的，还应当载明每个中标人对应的实施地域。"},{"i":24,"n":"第二十四条","txt":"招标人可以对多个同类通信工程建设项目的潜在投标人进行集中资格预审。招标人进行集中资格预审的，应当发布资格预审公告，明确集中资格预审的适用范围和有效期限，并且应当预估项目规模，合理设定资格、技术和商务条件，不得限制、排斥潜在投标人。 招标人进行集中资格预审，应当遵守国家有关勘察、设计、施工、监理等资质管理的规定。 集中资格预审后，通信工程建设项目的招标人应当继续完成招标程序，不得直接发包工程；直接发包工程的，属于《招标投标法》第四条规定的规避招标。"},{"i":25,"n":"第二十五条","txt":"招标人根据招标项目的具体情况，可以在发售招标文件截止之日后，组织潜在投标人踏勘项目现场和召开投标预备会。 招标人组织潜在投标人踏勘项目现场或者召开投标预备会的，应当向全部潜在投标人发出邀请。"},{"i":26,"n":"第二十六条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件送达投标地点。通信工程建设项目划分标段的，投标人应当在投标文件上标明相应的标段。 未通过资格预审的申请人提交的投标文件，以及逾期送达或者不按照招标文件要求密封的投标文件，招标人应当拒收。 招标人收到投标文件后，不得开启，并应当如实记载投标文件的送达时间和密封情况，存档备查。"},{"i":27,"n":"第二十七条","txt":"通信工程建设项目投标人少于3个的，不得开标，招标人在分析招标失败的原因并采取相应措施后，应当依法重新招标。划分标段的通信工程建设项目某一标段的投标人少于3个的，该标段不得开标，招标人在分析招标失败的原因并采取相应措施后，应当依法对该标段重新招标。 投标人认为存在低于成本价投标情形的，可以在开标现场提出异议，并在评标完成前向招标人提交书面材料。招标人应当及时将书面材料转交评标委员会。"},{"i":28,"n":"第二十八条","txt":"招标人应当根据《招标投标法》和《实施条例》的规定开标，记录开标过程并存档备查。招标人应当记录下列内容： （一）开标时间和地点； （二）投标人名称、投标价格等唱标内容； （三）开标过程是否经过公证； （四）投标人提出的异议。 开标记录应当由投标人代表、唱标人、记录人和监督人签字。 因不可抗力或者其他特殊原因需要变更开标地点的，招标人应提前通知所有潜在投标人，确保其有足够的时间能够到达开标地点。"},{"i":29,"n":"第二十九条","txt":"评标由招标人依法组建的评标委员会负责。 通信工程建设项目评标委员会的专家成员应当具备下列条件： （一）从事通信相关领域工作满8年并具有高级职称或者同等专业水平。掌握通信新技术的特殊人才经工作单位推荐，可以视为具备本项规定的条件； （二）熟悉国家和通信行业有关招标投标以及通信建设管理的法律、行政法规和规章，并具有与招标项目有关的实践经验； （三）能够认真、公正、诚实、廉洁地履行职责； （四）未因违法、违纪被取消评标资格或者未因在招标、评标以及其他与招标投标有关活动中从事违法行为而受过行政处罚或者刑事处罚; （五）身体健康，能够承担评标工作。 工业和信息化部统一组建和管理通信工程建设项目评标专家库，各省、自治区、直辖市通信管理局负责本行政区域内评标专家的监督管理工作。"},{"i":30,"n":"第三十条","txt":"依法必须进行招标的通信工程建设项目，评标委员会的专家应当从通信工程建设项目评标专家库内相关专业的专家名单中采取随机抽取方式确定；个别技术复杂、专业性强或者国家有特殊要求，采取随机抽取方式确定的专家难以保证胜任评标工作的招标项目，可以由招标人从通信工程建设项目评标专家库内相关专业的专家名单中直接确定。 依法必须进行招标的通信工程建设项目的招标人应当通过“管理平台”抽取评标委员会的专家成员，通信行政监督部门可以对抽取过程进行远程监督或者现场监督。"},{"i":31,"n":"第三十一条","txt":"依法必须进行招标的通信工程建设项目技术复杂、评审工作量大，其评标委员会需要分组评审的，每组成员人数应为5人以上，且每组每个成员应对所有投标文件进行评审。评标委员会的分组方案应当经全体成员同意。 评标委员会设负责人的，其负责人由评标委员会成员推举产生或者由招标人确定。评标委员会其他成员与负责人享有同等的表决权。"},{"i":32,"n":"第三十二条","txt":"评标委员会成员应当客观、公正地对投标文件提出评审意见，并对所提出的评审意见负责。 招标文件没有规定的评标标准和方法不得作为评标依据。"},{"i":33,"n":"第三十三条","txt":"评标过程中，评标委员会收到低于成本价投标的书面质疑材料、发现投标人的综合报价明显低于其他投标报价或者设有标底时明显低于标底，认为投标报价可能低于成本的，应当书面要求该投标人作出书面说明并提供相关证明材料。招标人要求以某一单项报价核定是否低于成本的，应当在招标文件中载明。 投标人不能合理说明或者不能提供相关证明材料的，评标委员会应当否决其投标。"},{"i":34,"n":"第三十四条","txt":"投标人以他人名义投标或者投标人经资格审查不合格的，评标委员会应当否决其投标。 部分投标人在开标后撤销投标文件或者部分投标人被否决投标后，有效投标不足3个且明显缺乏竞争的，评标委员会应当否决全部投标。有效投标不足3个，评标委员会未否决全部投标的，应当在评标报告中说明理由。 依法必须进行招标的通信工程建设项目，评标委员会否决全部投标的，招标人应当重新招标。"},{"i":35,"n":"第三十五条","txt":"评标完成后，评标委员会应当根据《招标投标法》和《实施条例》的有关规定向招标人提交评标报告和中标候选人名单。 招标人进行集中招标的，评标委员会应当推荐不少于招标文件载明的中标人数量的中标候选人，并标明排序。 评标委员会分组的，应当形成统一、完整的评标报告。"},{"i":36,"n":"第三十六条","txt":"评标报告应当包括下列内容： （一）基本情况； （二）开标记录和投标一览表； （三）评标方法、评标标准或者评标因素一览表； （四）评标专家评分原始记录表和否决投标的情况说明； （五）经评审的价格或者评分比较一览表和投标人排序； （六）推荐的中标候选人名单及其排序； （七）签订合同前要处理的事宜； （八）澄清、说明、补正事项纪要； （九）评标委员会成员名单及本人签字、拒绝在评标报告上签字的评标委员会成员名单及其陈述的不同意见和理由。"},{"i":37,"n":"第三十七条","txt":"依法必须进行招标的通信工程建设项目的招标人应当自收到评标报告之日起3日内通过“管理平台”公示中标候选人，公示期不得少于3日。"},{"i":38,"n":"第三十八条","txt":"招标人应当根据《招标投标法》和《实施条例》的有关规定确定中标人。 招标人进行集中招标的，应当依次确定排名靠前的中标候选人为中标人，且中标人数量及每个中标人对应的中标份额等应当与招标文件载明的内容一致。招标人与中标人订立的合同中应当明确中标价格、预估合同份额等主要条款。 中标人不能履行合同的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人，也可以对中标人的中标份额进行调整，但应当在招标文件中载明调整规则。"},{"i":39,"n":"第三十九条","txt":"在确定中标人之前，招标人不得与投标人就投标价格、投标方案等实质性内容进行谈判。 招标人不得向中标人提出压低报价、增加工作量、增加配件、增加售后服务量、缩短工期或其他违背中标人的投标文件实质性内容的要求。"},{"i":40,"n":"第四十条","txt":"依法必须进行招标的通信工程建设项目的招标人应当自确定中标人之日起15日内，通过“管理平台”向通信行政监督部门提交《通信工程建设项目招标投标情况报告表》（见附录二）。"},{"i":41,"n":"第四十一条","txt":"招标人应建立完整的招标档案，并按国家有关规定保存。招标档案应当包括下列内容： （一）招标文件； （二）中标人的投标文件； （三）评标报告； （四）中标通知书； （五）招标人与中标人签订的书面合同； （六）向通信行政监督部门提交的《通信工程建设项目自行招标备案表》、《通信工程建设项目招标投标情况报告表》； （七）其他需要存档的内容。"},{"i":42,"n":"第四十二条","txt":"招标人进行集中招标的，应当在所有项目实施完成之日起30日内通过“管理平台”向通信行政监督部门报告项目实施情况。"},{"i":43,"n":"第四十三条","txt":"通信行政监督部门对通信工程建设项目招标投标活动实施监督检查，可以查阅、复制招标投标活动中有关文件、资料，调查有关情况，相关单位和人员应当配合。必要时，通信行政监督部门可以责令暂停招标投标活动。 通信行政监督部门的工作人员对监督检查过程中知悉的国家秘密、商业秘密，应当依法予以保密。"},{"i":44,"n":"第四十四条","txt":"招标人在发布招标公告、发出投标邀请书或者售出招标文件或资格预审文件后无正当理由终止招标的，由通信行政监督部门处以警告，可以并处1万元以上3万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"依法必须进行招标的通信工程建设项目的招标人或者招标代理机构有下列情形之一的，由通信行政监督部门责令改正，可以处3万元以下的罚款： （一）招标人自行招标，未按规定向通信行政监督部门备案； （二）未通过“管理平台”确定评标委员会的专家； （三）招标人未通过“管理平台”公示中标候选人； （四）确定中标人后，未按规定向通信行政监督部门提交招标投标情况报告。"},{"i":46,"n":"第四十六条","txt":"招标人有下列情形之一的，由通信行政监督部门责令改正，可以处3万元以下的罚款，对单位直接负责的主管人员和其他直接责任人员依法给予处分；对中标结果造成实质性影响，且不能采取补救措施予以纠正的，招标人应当重新招标或者评标： （一）编制的资格预审文件、招标文件中未载明所有资格审查或者评标的标准和方法； （二）招标文件中含有要求投标人多轮次报价、投标人保证报价不高于历史价格等违法条款； （三）不按规定组建资格审查委员会； （四）投标人数量不符合法定要求时未重新招标而直接发包； （五）开标过程、开标记录不符合《招标投标法》、《实施条例》和本办法的规定； （六）违反《实施条例》第三十二条的规定限制、排斥投标人； （七）以任何方式要求评标委员会成员以其指定的投标人作为中标候选人、以招标文件未规定的评标标准和方法作为评标依据，或者以其他方式非法干涉评标活动，影响评标结果。"},{"i":47,"n":"第四十七条","txt":"招标人进行集中招标或者集中资格预审，违反本办法第二十三条、第二十四条、第三十五条或者第三十八条规定的，由通信行政监督部门责令改正，可以处3万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"通信行政监督部门建立通信工程建设项目招标投标情况通报制度，定期通报通信工程建设项目招标投标总体情况、公开招标及招标备案情况、重大违法违约事件等信息。"},{"i":49,"n":"第四十九条","txt":"本办法自2014年7月1日起施行。原中华人民共和国信息产业部2000年9月22日公布的《通信建设项目招标投标管理暂行规定》（中华人民共和国信息产业部令第2号）同时废止。 附录：《通信工程建设项目招标投标管理办法》附录.wps"}],"tongxinjianshegongchengzhiliangjianduguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强通信建设工程质量监督管理，保证通信建设工程质量，根据《中华人民共和国建筑法》《中华人民共和国电信条例》《建设工程质量管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内实施通信建设工程质量监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责全国通信建设工程质量的监督管理，省、自治区、直辖市通信管理局负责本行政区域内通信建设工程质量的监督管理。 工业和信息化部和省、自治区、直辖市通信管理局（以下统称电信管理机构）设立的通信建设工程质量监督机构（以下简称通信质量监督机构）依照本规定具体实施通信建设工程质量监督工作。"},{"i":4,"n":"第四条","txt":"通信建设工程的建设单位、勘察单位、设计单位、施工单位、监理单位（以下统称工程质量责任主体）应当遵守工程建设法律、法规及相关规定，履行质量责任和义务，对建设工程质量负责。"},{"i":5,"n":"第五条","txt":"电信管理机构及通信质量监督机构实施通信建设工程质量监督管理应当遵循客观、公开、公平、公正的原则。"},{"i":6,"n":"第六条","txt":"工业和信息化部建立通信建设工程质量监督管理信息平台（以下简称质监管理平台），实行通信建设工程质量监督的信息化管理。 工业和信息化部建立通信建设工程质量违法行为信息库，推进通信建设领域诚信体系建设。"},{"i":7,"n":"第七条","txt":"通信建设工程质量监督经费由同级财政预算予以保障，电信管理机构应当在监管经费中统筹安排。电信管理机构及通信质量监督机构实施质量监督不得向工程质量责任主体收取任何费用。"},{"i":8,"n":"第八条","txt":"任何单位和个人对通信建设工程质量事故、质量缺陷都有权举报和投诉。"},{"i":9,"n":"第九条","txt":"工业和信息化部通信质量监督机构（以下简称部通信质量监督机构）具体实施以下通信建设工程质量监督工作： （一）对省、自治区、直辖市通信管理局设立的通信质量监督机构（以下简称省通信质量监督机构）进行业务指导； （二）对基础电信业务经营者集团公司管理的通信建设工程实施质量监督，协调省通信质量监督机构联合实施通信建设工程质量监督，对通信建设工程质量监督人员（以下简称质量监督人员）进行培训考核； （三）受理通信建设工程质量的举报和投诉，参与调查处理通信建设工程质量事故； （四）记录通信建设工程质量违法行为信息并录入通信建设工程质量违法行为信息库； （五）工业和信息化部确定的其他工作。"},{"i":10,"n":"第十条","txt":"省通信质量监督机构具体实施以下通信建设工程质量监督工作： （一）实施本行政区域内通信建设工程质量监督； （二）受理本行政区域内通信建设工程质量的举报和投诉，参与调查处理本行政区域内通信建设工程质量事故； （三）记录通信建设工程质量违法行为信息并录入通信建设工程质量违法行为信息库； （四）省、自治区、直辖市通信管理局确定的其他工作。 省通信质量监督机构可以根据本行政区域实际情况和工作需要，设立分支机构承担通信建设工程质量监督工作。"},{"i":11,"n":"第十一条","txt":"通信质量监督机构应当健全通信建设工程质量监督工作制度，加强对质量监督人员的管理，建立与通信建设工程质量监督工作相适应的信息化管理条件。"},{"i":12,"n":"第十二条","txt":"通信质量监督机构可以聘请通信建设工程专业技术人员参与通信建设工程质量监督工作。"},{"i":13,"n":"第十三条","txt":"通信质量监督机构应当定期汇总、整理通信建设工程质量监督情况并报送电信管理机构。"},{"i":14,"n":"第十四条","txt":"工业和信息化部建立通信质量监督机构和质量监督人员名录库，统一向社会公布通信质量监督机构名录。"},{"i":15,"n":"第十五条","txt":"电信管理机构应当加强对通信质量监督机构的监督管理，定期组织对其考核。"},{"i":16,"n":"第十六条","txt":"通信质量监督机构实施通信建设工程质量监督的主要内容包括： （一）检查工程质量责任主体执行建设工程质量法律、法规和通信建设工程强制性标准的情况； （二）检查工程质量责任主体落实工程质量责任和义务、建立质量保证体系和质量责任制度情况； （三）检查影响工程质量、安全和主要使用功能的关键部位和环节； （四）检查工程使用的主要材料、设备的质量； （五）检查工程防雷、抗震等情况； （六）检查工程质量监督申报、工程竣工验收的组织形式及相关资料。"},{"i":17,"n":"第十七条","txt":"建设单位应当在通信建设工程开工5个工作日前办理通信建设工程质量监督申报手续。投资规模较小的通信建设工程项目可以集中办理通信建设工程质量监督申报手续。 建设单位办理通信建设工程质量监督申报手续，应当通过质监管理平台提交《通信建设工程质量监督申报表》和以下文件材料： （一）项目立项批准文件； （二）施工图设计审查批准文件； （三）工程勘察、设计、施工、监理等单位的资质等级证书； （四）其他相关文件。"},{"i":18,"n":"第十八条","txt":"通信质量监督机构收到通信建设工程质量监督申报后，应当根据通信建设工程的特点，制定通信建设工程质量监督工作方案，确定通信建设工程质量监督的具体内容、方式和监督工作计划，并通过质监管理平台将《通信建设工程质量监督通知书》通知建设单位。"},{"i":19,"n":"第十九条","txt":"通信质量监督机构采用抽查方式对通信建设工程实施质量监督，并填写《通信建设工程质量监督记录表》。"},{"i":20,"n":"第二十条","txt":"通信质量监督机构实施通信建设工程质量监督发现有影响通信建设工程质量的问题时，应当通知有关工程质量责任主体，责令限期改正。 有关工程质量责任主体应当按要求改正，并通过质监管理平台提交《通信建设工程质量问题整改情况反馈表》。"},{"i":21,"n":"第二十一条","txt":"建设单位应当自通信建设工程竣工验收合格之日起15日内，通过质监管理平台提交《通信建设工程竣工验收备案表》及通信建设工程竣工验收报告。 通信质量监督机构收到竣工验收报告后，应当重点对基本建设程序、竣工验收的组织形式、竣工验收资料是否符合有关规定进行监督，发现有违反有关规定的行为的，应当责令停止使用，限期改正。建设单位改正后，应当重新组织工程竣工验收。"},{"i":22,"n":"第二十二条","txt":"通信质量监督机构应当建立通信建设工程质量监督档案，并按照有关规定妥善保存。"},{"i":23,"n":"第二十三条","txt":"电信管理机构组织通信建设工程质量专项检查，检查工程质量责任主体建立工程质量管理制度情况、落实相关责任和义务等情况，并在《通信建设工程质量专项检查表》中如实记录专项检查情况。"},{"i":24,"n":"第二十四条","txt":"电信管理机构实施通信建设工程质量专项检查，应当随机抽取检查对象，通过质量监督人员名录库随机选派检查人员，并及时向社会公布检查情况及对违法行为的查处结果。"},{"i":25,"n":"第二十五条","txt":"电信管理机构应当建立通信建设工程质量监督通报制度，对建设单位办理通信建设工程质量监督申报手续、竣工验收备案手续，工程质量责任主体落实工程质量责任和义务，违法行为查处，以及相关工程质量责任主体对工程质量问题改正情况等进行通报。"},{"i":26,"n":"第二十六条","txt":"发生通信建设工程质量事故的，参照通信建设工程生产安全事故报告和调查处理程序处理。"},{"i":27,"n":"第二十七条","txt":"电信管理机构及通信质量监督机构实施通信建设工程质量监督检查，有权要求被监督检查单位提供有关工程文件和资料，进入被监督检查单位的施工现场和有关场所进行检查，并采取检测、拍照、录像等方式进行取证，向有关单位和个人调查情况并取得证明材料。 工程质量责任主体应当接受、配合电信管理机构及通信质量监督机构实施的监督检查，不得拒绝或者阻碍质量监督人员依法执行职务。"},{"i":28,"n":"第二十八条","txt":"工程质量责任主体有下列情形之一的，责令改正，可以处一万元以上三万元以下罚款： （一）违反本规定第二十条的规定，未按要求对影响工程质量的问题进行整改的; （二）违反本规定第二十七条的规定，不配合通信建设工程质量监督检查的； （三）通过质监管理平台提交虚假材料的。 建设单位未依法办理通信建设工程质量监督申报或竣工验收备案手续的，依据《建设工程质量管理条例》第五十六条规定予以处罚。"},{"i":29,"n":"第二十九条","txt":"工程质量责任主体违反法律、法规或者不执行通信建设工程强制性标准，降低工程质量的，依据相关法律、法规处理，并在行业内进行通报。"},{"i":30,"n":"第三十条","txt":"瞒报、谎报通信建设工程质量事故或者拖延报告期限的，对直接责任人和其他责任人员，依法给予处分，在行业内进行通报，并通报其他相关部门。"},{"i":31,"n":"第三十一条","txt":"工程质量责任主体违反通信建设工程质量管理规定，受到行政处罚的，由电信管理机构记入信用记录，并依照有关法律、行政法规的规定予以公示。"},{"i":32,"n":"第三十二条","txt":"工程质量责任主体违反通信建设工程质量管理规定的，由工程所在地的省、自治区、直辖市通信管理局处罚；属于基础电信业务经营者集团公司管理通信建设工程的，由工业和信息化部处罚。 电信管理机构和通信质量监督机构工作人员在通信建设工程质量监督管理工作中玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"本规定所规定的表格式样，由工业和信息化部统一制作，并根据需要调整。"},{"i":34,"n":"第三十四条","txt":"抢险救灾通信建设工程和涉密通信建设工程不适用本规定。"},{"i":35,"n":"第三十五条","txt":"本规定自2018年7月1日起施行。2001年12月19日公布的《通信工程质量监督管理规定》（原信息产业部令第18号）同时废止。"}],"tongxinduanxinxifuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范通信短信息（以下简称短信息）服务行为，维护用户的合法权益，促进短信息服务市场的健康发展，根据《全国人民代表大会常务委员会关于加强网络信息保护的决定》、《中华人民共和国电信条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供、使用短信息服务，适用本规定。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责对全国的短信息服务实施监督管理。 省、自治区、直辖市通信管理局负责对本行政区域内的短信息服务实施监督管理。 工业和信息化部和省、自治区、直辖市通信管理局统称电信管理机构。"},{"i":4,"n":"第四条","txt":"提供、使用短信息服务的，应当遵守法律、行政法规和电信管理机构的相关规定，不得利用短信息服务从事违法活动。"},{"i":5,"n":"第五条","txt":"鼓励有关行业协会依法制定短信息服务的自律性管理制度，引导会员加强自律管理。"},{"i":6,"n":"第六条","txt":"经营短信息服务的，应当依法取得电信业务经营许可。 基础电信业务经营者不得为未取得电信业务经营许可的单位或者个人提供用于经营短信息服务的网络或者业务接入服务。"},{"i":7,"n":"第七条","txt":"基础电信业务经营者应当准确记录接入其网络的短信息服务提供者的名称、接入代码和接入地点等信息。"},{"i":8,"n":"第八条","txt":"短信息服务提供者应当制定短信息服务规则，并将与用户相关的内容通过服务合同或者入网协议等方式告知用户，不得利用格式条款侵犯用户合法权益。"},{"i":9,"n":"第九条","txt":"短信息服务需向用户收费的，短信息服务提供者应当保证计费符合相关法律规定和电信标准，并事先明确告知用户服务内容、资费标准、收费方式和退订方式等。"},{"i":10,"n":"第十条","txt":"短信息服务提供者发送短信息，应当将发送端电话号码或者代码一并发送，不得发送缺少发送端电话号码或者代码的短信息，不得发送含有虚假、冒用的发送端电话号码或者代码的短信息。"},{"i":11,"n":"第十一条","txt":"短信息服务提供者应当在其服务系统中记录短信息发送和接收时间、发送端和接收端电话号码或者代码、用户订阅和退订情况等信息，端口类短信息还应当保存短信息内容。 前款规定的记录应当保存至少5个月，其中用户订阅和退订情况应当保存至短信息服务提供者与用户服务关系终止后5个月。"},{"i":12,"n":"第十二条","txt":"短信息服务提供者提供端口类短信息服务，应当要求短信息内容提供者提供真实身份信息，并进行查验和登记。"},{"i":13,"n":"第十三条","txt":"短信息服务提供者提供端口类短信息服务，应当按照电信管理机构批准的码号结构、位长、用途和使用范围使用端口号。未经电信管理机构批准，不得转让或者出租端口号。"},{"i":14,"n":"第十四条","txt":"短信息服务提供者在业务活动中收集、使用用户个人信息，应当严格遵守有关法律法规的规定。"},{"i":15,"n":"第十五条","txt":"短信息服务提供者应当建立和执行网络与信息安全管理制度，采取安全防范措施，加强公共信息巡查。"},{"i":16,"n":"第十六条","txt":"短信息服务提供者、短信息内容提供者不得制作、复制、发布和传播含有《中华人民共和国电信条例》等法律法规规定的禁止性内容的短信息。"},{"i":17,"n":"第十七条","txt":"发送公益性短信息的，由省级以上人民政府有关部门提前10个工作日向电信管理机构提供短信息发送时间、发送内容、发送范围、发送机构等信息，电信管理机构协调短信息服务提供者发送；不属于公益性短信息的，及时告知有关部门并说明理由。 涉及自然灾害、事故灾难、公共卫生事件和社会安全事件预警和处置等应急公益性短信息，情况紧急需要先行发送的，短信息服务提供者应当按照有关应急预案和机制及时免费发送，有关部门事后应当向电信管理机构提供有关信息。"},{"i":18,"n":"第十八条","txt":"短信息服务提供者、短信息内容提供者未经用户同意或者请求，不得向其发送商业性短信息。用户同意后又明确表示拒绝接收商业性短信息的，应当停止向其发送。 短信息服务提供者、短信息内容提供者请求用户同意接收商业性短信息的，应当说明拟发送商业性短信息的类型、频次和期限等信息。用户未回复的，视为不同意接收。用户明确拒绝或者未回复的，不得再次向其发送内容相同或者相似的短信息。 基础电信业务经营者对通过其电信网发送端口类商业性短信息的，应当保证有关用户已经同意或者请求接收有关短信息。"},{"i":19,"n":"第十九条","txt":"短信息服务提供者、短信息内容提供者用于发送业务管理和服务类短信息的端口，不得用于发送商业性短信息。"},{"i":20,"n":"第二十条","txt":"短信息服务提供者、短信息内容提供者向用户发送商业性短信息，应当提供便捷和有效的拒绝接收方式并随短信息告知用户，不得以任何形式对用户拒绝接收短信息设置障碍。"},{"i":21,"n":"第二十一条","txt":"短信息服务提供者、短信息内容提供者向用户发送商业性短信息，应当在短信息中明确注明短信息内容提供者的名称。"},{"i":22,"n":"第二十二条","txt":"短信息服务提供者应当建立短信息管理制度和预警监测机制，通过规范管理、技术手段和合同约定等措施，防范未经用户同意或者请求发送的商业性短信息。"},{"i":23,"n":"第二十三条","txt":"基础电信业务经营者发现短信息服务提供者、短信息内容提供者违反本规定第十八条发送商业性短信息的，应当采取必要的措施暂停或者停止为其提供相关的电信资源，并保存有关记录。"},{"i":24,"n":"第二十四条","txt":"鼓励用户自主选择使用短信息安全应用软件等适当的安全防护手段，提高自我防护能力。"},{"i":25,"n":"第二十五条","txt":"短信息服务提供者应当建立投诉处理机制，公布有效、便捷的联系方式，接受与短信息服务有关的投诉。"},{"i":26,"n":"第二十六条","txt":"工业和信息化部委托12321网络不良与垃圾信息举报受理中心（以下简称举报中心）受理短信息服务举报。"},{"i":27,"n":"第二十七条","txt":"用户认为其受到商业性短信息侵扰或者收到含有法律法规规定的禁止性内容的短信息的，可以向短信息服务提供者投诉或者向举报中心举报。 举报中心受理用户举报后，应当在5个工作日内转送短信息服务提供者处理。发现存在违法行为的，应当及时报告国家有关部门处理。 短信息服务提供者收到用户投诉或者举报中心转办的举报，经核实后应当及时采取有效手段，并在15个工作日内向投诉方或举报中心反馈处置结果。"},{"i":28,"n":"第二十八条","txt":"短信息服务提供者发现被投诉或者举报的短信息明显含有本规定第十六条规定的内容的，应当立即停止发送，保存有关记录，并及时向国家有关机关报告；涉及本单位的，应当立即开展调查，采取有效的防范或者处理措施，并及时将调查结果报告电信管理机构。"},{"i":29,"n":"第二十九条","txt":"用户与短信息服务提供者发生短信息服务争议的，可以依法向电信管理机构委托的电信用户申诉受理机构申诉。"},{"i":30,"n":"第三十条","txt":"电信管理机构对短信息服务活动实施监督检查时，短信息服务提供者、短信息内容提供者应当予以配合并按照要求提供相关材料。 电信管理机构实施监督检查，应当记录监督检查的情况，不得妨碍短信息服务提供者、短信息内容提供者正常的经营或者服务活动，不得收取任何费用。"},{"i":31,"n":"第三十一条","txt":"电信管理机构实施电信业务经营许可年检时，应当对短信息服务提供者执行本规定的情况进行审查。"},{"i":32,"n":"第三十二条","txt":"电信管理机构应当将短信息服务提供者违反本规定的行为记入信用档案并予以公布。必要时，电信管理机构可以对短信息服务提供者的负责人进行监管谈话。"},{"i":33,"n":"第三十三条","txt":"违反本规定第六条第一款、第十三条规定的，由电信管理机构依据《中华人民共和国电信条例》第六十九条规定处罚。"},{"i":34,"n":"第三十四条","txt":"基础电信业务经营者、短信息服务提供者违反本规定第七条至第十二条、第十五条、第十八条至第二十一条、第二十七条第三款规定的，由电信管理机构依据职权责令限期改正，予以警告，可以并处一万元以上三万元以下罚款，向社会公告。 短信息内容提供者违反本规定第十八条至第二十一条规定的，由有关部门按照国家有关法律、行政法规予以处罚。"},{"i":35,"n":"第三十五条","txt":"违反本规定第十六条规定的，依据《中华人民共和国电信条例》第六十六条规定处罚。"},{"i":36,"n":"第三十六条","txt":"电信管理机构、举报中心工作人员在短信息服务监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处理；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"本规定下列用语的含义是： （一）短信息服务，是指利用电信网向移动电话、固定电话等通信终端用户，提供有限长度的文字、数据、声音、图像等信息的电信业务。 （二）短信息服务提供者，是指提供短信息发送、存储、转发和接收等基础网络服务，以及利用基础网络设施和服务为其他组织和个人发送短信息提供平台的电信业务经营者（包含但不限于基础电信业务、增值电信业务中的信息服务业务和移动通信转售业务经营者）。 （三）短信息内容提供者，是指将其短信息通过短信息服务提供者发送的组织或者个人。 （四）端口类短信息，是指短信息服务提供者利用自有端口或者行业类应用端口发送的短信息。 （五）商业性短信息，是指用于介绍、推销商品、服务或者商业投资机会的短信息。 （六）公益性短信息，是指各级人民政府相关部门等单位向用户发送的，旨在服务社会公共利益，倡导社会公序良俗、预防或处置突发事件、提醒群众防灾避灾等非盈利性质的短信息。"},{"i":38,"n":"第三十八条","txt":"利用互联网向固定电话、移动电话等通信终端用户提供文字、数据、声音、图像等具有短信息特征的信息递送类服务，参照本规定执行。依法需经有关主管部门审核同意的，应当经有关部门审核同意。"},{"i":39,"n":"第三十九条","txt":"本规定自2015年6月30日起施行。"}],"tongxinwangluoanquanfanghuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对通信网络安全的管理，提高通信网络安全防护能力，保障通信网络安全畅通，根据《中华人民共和国电信条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的电信业务经营者和互联网域名服务提供者（以下统称 “ 通信网络运行单位 ” ）管理和运行的公用通信网和互联网（以下统称 “ 通信网络 ” ）的网络安全防护工作，适用本办法。 本办法所称互联网域名服务，是指设置域名数据库或者域名解析服务器，为域名持有者提供域名注册或者权威解析服务的行为。 本办法所称网络安全防护工作，是指为防止通信网络阻塞、中断、瘫痪或者被非法控制，以及为防止通信网络中传输、存储、处理的数据信息丢失、泄露或者被篡改而开展的工作。"},{"i":3,"n":"第三条","txt":"通信网络安全防护工作坚持积极防御、综合防范、分级保护的原则。"},{"i":4,"n":"第四条","txt":"中华人民共和国工业和信息化部（以下简称工业和信息化部）负责全国通信网络安全防护工作的统一指导、协调和检查，组织建立健全通信网络安全防护体系，制定通信行业相关标准。 各省、自治区、直辖市通信管理局（以下简称通信管理局）依据本办法的规定，对本行政区域内的通信网络安全防护工作进行指导、协调和检查。 工业和信息化部与通信管理局统称 “ 电信管理机构 ” 。"},{"i":5,"n":"第五条","txt":"通信网络运行单位应当按照电信管理机构的规定和通信行业标准开展通信网络安全防护工作，对本单位通信网络安全负责。"},{"i":6,"n":"第六条","txt":"通信网络运行单位新建、改建、扩建通信网络工程项目，应当同步建设通信网络安全保障设施，并与主体工程同时进行验收和投入运行。 通信网络安全保障设施的新建、改建、扩建费用，应当纳入本单位建设项目概算。"},{"i":7,"n":"第七条","txt":"通信网络运行单位应当对本单位已正式投入运行的通信网络进行单元划分，并按照各通信网络单元遭到破坏后可能对国家安全、经济运行、社会秩序、公众利益的危害程度，由低到高分别划分为一级、二级、三级、四级、五级。 电信管理机构应当组织专家对通信网络单元的分级情况进行评审。 通信网络运行单位应当根据实际情况适时调整通信网络单元的划分和级别，并按照前款规定进行评审。"},{"i":8,"n":"第八条","txt":"通信网络运行单位应当在通信网络定级评审通过后三十日内，将通信网络单元的划分和定级情况按照以下规定向电信管理机构备案： （一）基础电信业务经营者集团公司向工业和信息化部申请办理其直接管理的通信网络单元的备案；基础电信业务经营者各省（自治区、直辖市）子公司、分公司向当地通信管理局申请办理其负责管理的通信网络单元的备案； （二）增值电信业务经营者向作出电信业务经营许可决定的电信管理机构备案； （三）互联网域名服务提供者向工业和信息化部备案。"},{"i":9,"n":"第九条","txt":"通信网络运行单位办理通信网络单元备案，应当提交以下信息： （一）通信网络单元的名称、级别和主要功能； （二）通信网络单元责任单位的名称和联系方式； （三）通信网络单元主要负责人的姓名和联系方式； （四）通信网络单元的拓扑架构、网络边界、主要软硬件及型号和关键设施位置； （五）电信管理机构要求提交的涉及通信网络安全的其他信息。 前款规定的备案信息发生变化的，通信网络运行单位应当自信息变化之日起三十日内向电信管理机构变更备案。 通信网络运行单位报备的信息应当真实、完整。"},{"i":10,"n":"第十条","txt":"电信管理机构应当对备案信息的真实性、完整性进行核查，发现备案信息不真实、不完整的，通知备案单位予以补正。"},{"i":11,"n":"第十一条","txt":"通信网络运行单位应当落实与通信网络单元级别相适应的安全防护措施，并按照以下规定进行符合性评测： （一）三级及三级以上通信网络单元应当每年进行一次符合性评测； （二）二级通信网络单元应当每两年进行一次符合性评测。 通信网络单元的划分和级别调整的，应当自调整完成之日起九十日内重新进行符合性评测。 通信网络运行单位应当在评测结束后三十日内，将通信网络单元的符合性评测结果、整改情况或者整改计划报送通信网络单元的备案机构。"},{"i":12,"n":"第十二条","txt":"通信网络运行单位应当按照以下规定组织对通信网络单元进行安全风险评估，及时消除重大网络安全隐患： （一）三级及三级以上通信网络单元应当每年进行一次安全风险评估； （二）二级通信网络单元应当每两年进行一次安全风险评估。 国家重大活动举办前，通信网络单元应当按照电信管理机构的要求进行安全风险评估。 通信网络运行单位应当在安全风险评估结束后三十日内，将安全风险评估结果、隐患处理情况或者处理计划报送通信网络单元的备案机构。"},{"i":13,"n":"第十三条","txt":"通信网络运行单位应当对通信网络单元的重要线路、设备、系统和数据等进行备份。"},{"i":14,"n":"第十四条","txt":"通信网络运行单位应当组织演练，检验通信网络安全防护措施的有效性。 通信网络运行单位应当参加电信管理机构组织开展的演练。"},{"i":15,"n":"第十五条","txt":"通信网络运行单位应当建设和运行通信网络安全监测系统，对本单位通信网络的安全状况进行监测。"},{"i":16,"n":"第十六条","txt":"通信网络运行单位可以委托专业机构开展通信网络安全评测、评估、监测等工作。 工业和信息化部应当根据通信网络安全防护工作的需要，加强对前款规定的受托机构的安全评测、评估、监测能力指导。"},{"i":17,"n":"第十七条","txt":"电信管理机构应当对通信网络运行单位开展通信网络安全防护工作的情况进行检查。 电信管理机构可以采取以下检查措施： （一）查阅通信网络运行单位的符合性评测报告和风险评估报告； （二）查阅通信网络运行单位有关网络安全防护的文档和工作记录； （三）向通信网络运行单位工作人员询问了解有关情况； （四）查验通信网络运行单位的有关设施； （五）对通信网络进行技术性分析和测试； （六）法律、行政法规规定的其他检查措施。"},{"i":18,"n":"第十八条","txt":"电信管理机构可以委托专业机构开展通信网络安全检查活动。"},{"i":19,"n":"第十九条","txt":"通信网络运行单位应当配合电信管理机构及其委托的专业机构开展检查活动，对于检查中发现的重大网络安全隐患，应当及时整改。"},{"i":20,"n":"第二十条","txt":"电信管理机构对通信网络安全防护工作进行检查，不得影响通信网络的正常运行，不得收取任何费用，不得要求接受检查的单位购买指定品牌或者指定单位的安全软件、设备或者其他产品。"},{"i":21,"n":"第二十一条","txt":"电信管理机构及其委托的专业机构的工作人员对于检查工作中获悉的国家秘密、商业秘密和个人隐私，有保密的义务。"},{"i":22,"n":"第二十二条","txt":"违反本办法第六条第一款、第七条第一款和第三款、第八条、第九条、第十一条、第十二条、第十三条、第十四条、第十五条、第十九条规定的，由电信管理机构依据职权责令改正；拒不改正的，给予警告，并处五千元以上三万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"电信管理机构的工作人员违反本办法第二十条、第二十一条规定的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本办法自 2010 年 3 月 1 日起施行。"}],"tongxinxingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范通信行政处罚行为，保障和监督各级通信主管部门有效实施行政管理，依法进行行政处罚，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》及相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织实施违反通信行政管理秩序的行为，依照法律、法规或者规章的规定，应当给予行政处罚的，由通信主管部门按照《中华人民共和国行政处罚法》和本规定的程序实施。 本规定所称通信主管部门，是指信息产业部、国家邮政局、省、自治区、直辖市通信管理局、邮政（管理）局及法律、法规授权的具有通信行政管理职能的组织。"},{"i":3,"n":"第三条","txt":"各级通信主管部门实施行政处罚应当遵循公正、公开的原则。"},{"i":4,"n":"第四条","txt":"通信行政处罚由违法行为发生地的通信主管部门依照职权管辖。 法律、行政法规另有规定的，从其规定。"},{"i":5,"n":"第五条","txt":"上级通信主管部门可以办理下级通信主管部门管辖的行政处罚案件；下级通信主管部门对其管辖的行政处罚案件，认为需要由上级通信主管部门办理时，可以报请上一级通信主管部门决定。"},{"i":6,"n":"第六条","txt":"两个以上同级通信主管部门都有管辖权的行政处罚案件，由最初受理的通信主管部门管辖；主要违法行为发生地的通信主管部门管辖更为适宜的，可以移送主要违法行为发生地的通信主管部门管辖。"},{"i":7,"n":"第七条","txt":"两个以上同级通信主管部门对管辖发生争议的，报请共同的上一级通信主管部门指定管辖。"},{"i":8,"n":"第八条","txt":"通信主管部门发现查处的案件不属于自己管辖时，应当及时将案件移送有管辖权的通信主管部门或者其他行政机关管辖，受移送的通信主管部门对管辖有异议的，应当报请共同的上一级通信主管部门指定管辖。 违法行为构成犯罪的，移送司法机关管辖。"},{"i":9,"n":"第九条","txt":"通信行政执法人员（以下简称执法人员）依法进行调查、检查或者当场作出行政处罚决定时，应当向当事人或者有关人员出示行政执法证件。"},{"i":10,"n":"第十条","txt":"当事人进行口头陈述和申辩的，执法人员应当制作笔录。通信主管部门对当事人提出的事实、理由和证据应当进行复核，经复核能够成立的，应当采纳。 通信主管部门不得因当事人申辩而加重处罚。"},{"i":11,"n":"第十一条","txt":"经当事人口头或者书面申请，执法人员、听证主持人有下列情形之一的，应当回避： （一） 是本案当事人或者委托代理人的近亲属； （二） 与本案有利害关系； （三） 与本案当事人有其他关系，可能影响对案件公正处理的。"},{"i":12,"n":"第十二条","txt":"当事人提出回避申请，应当说明理由。执法人员、听证主持人应当将当事人的回避申请报告本部门负责人，由本部门负责人决定其是否回避；本部门负责人担任听证主持人的，由本机关负责人决定其是否回避。"},{"i":13,"n":"第十三条","txt":"违法事实确凿并有法定依据，对公民处以 50 元以下、对法人或者其他组织处以 1000 元以下罚款或者警告的行政处罚的，可以当场作出处罚决定。"},{"i":14,"n":"第十四条","txt":"执法人员当场作出行政处罚决定的，应当填写统一编号的《行政处罚（当场）决定书》，当场交付当事人，并告知当事人，如不服行政处罚决定，可以依法申请行政复议或者提起行政诉讼。"},{"i":15,"n":"第十五条","txt":"执法人员应当自作出行政处罚（当场）决定之日起 3 日内向所属通信主管部门报告并备案。"},{"i":16,"n":"第十六条","txt":"实施通信行政处罚，除适用简易程序外，应当适用一般程序。"},{"i":17,"n":"第十七条","txt":"除依法可以当场决定行政处罚外，执法人员发现公民、法人或其他组织有违法行为依法应当给予通信行政处罚的，应当填写《行政处罚立案呈批表》报本机关负责人批准。"},{"i":18,"n":"第十八条","txt":"符合下列条件的，应当在 7 日内立案： （一） 有违法行为发生； （二） 违法行为依照法律、法规和规章应受通信行政处罚； （三） 属于本级通信主管部门管辖。"},{"i":19,"n":"第十九条","txt":"通信主管部门应当对案件进行全面、客观、公正地调查，收集证据；必要时依照法律、法规和规章的规定，可以进行检查。 证据包括书证、物证、证人证言、视听资料、鉴定结论、勘验笔录和现场笔录。证据必须查证属实，才能作为认定事实的依据。"},{"i":20,"n":"第二十条","txt":"执法人员调查收集证据或者进行检查时不得少于二人。 执法人员在调查案件时询问证人或当事人（以下统称被询问人），应当制作《询问笔录》。笔录经被询问人阅核后，由询问人和被询问人签名或盖章。"},{"i":21,"n":"第二十一条","txt":"通信主管部门为调查案件需要，有权依法进行现场勘验，对重要的书证，有权进行复制。 执法人员对与案件有关的物品或者场所进行勘验检查时，应当通知当事人到场，制作《勘验检查笔录》，当事人拒不到场的，可以请在场的其他人作证。"},{"i":22,"n":"第二十二条","txt":"通信主管部门在调查案件时，对专门性问题，交由法定鉴定部门进行鉴定；没有法定鉴定部门的，应当提交公认的鉴定机构进行鉴定。鉴定人进行鉴定后，应当制作《鉴定意见书》。"},{"i":23,"n":"第二十三条","txt":"通信主管部门收集证据时，可以采用抽样取证的方法。在证据可能灭失或者以后难以取得的情况下，经本通信主管部门负责人批准，可以先行登记保存。 对证据进行抽样取证或者登记保存，应当有当事人在场。当事人不在场或者拒绝到场的，执法人员可以请有关人员见证并注明。 对抽样取证或者登记保存的物品，应当制作《抽样取证凭证》或《证据登记保存清单》。"},{"i":24,"n":"第二十四条","txt":"对先行登记保存的证据，应当在 7 日内作出下列处理决定： （一） 需要进行技术检验或者鉴定的，送交检验或者鉴定； （二） 依法不需要暂扣的物品，退还当事人； （三） 依法应当移交有关部门处理的，移交有关部门。"},{"i":25,"n":"第二十五条","txt":"执法人员在调查结束后，认为案件基本事实清楚，主要证据充分，应当制作《案件处理意见报告》，报本通信主管部门负责人审查。"},{"i":26,"n":"第二十六条","txt":"通信主管部门负责人对《案件处理意见报告》审核后，认为应当给予行政处罚的，通信主管部门应当制作《行政处罚意见告知书》，送达当事人，告知拟给予的行政处罚内容及事实、理由和依据，并告知当事人可以在收到该告知书之日起3 日内，向通信主管部门进行陈述和申辩，符合听证条件的，可以要求该通信主管部门按照本章第三节的规定举行听证。"},{"i":27,"n":"第二十七条","txt":"案件调查完毕后，通信主管部门负责人应当及时审查有关案件调查材料、当事人陈述和申辩材料、听证会笔录和听证会报告书，根据情况分别作出予以行政处罚、不予行政处罚或者移送其他有关机关处理的决定。"},{"i":28,"n":"第二十八条","txt":"通信主管部门作出给予行政处罚决定的，应当制作《行政处罚决定书》。行政处罚决定书应当载明下列事项： （一） 当事人的姓名或者名称、地址； （二） 违反法律、法规或者规章的事实和证据； （三） 行政处罚的种类和依据； （四） 行政处罚的履行方式和期限； （五） 不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六） 作出行政处罚决定的通信主管部门的名称、印章和日期。"},{"i":29,"n":"第二十九条","txt":"通信行政处罚案件应当自立案之日起 60 日内办理完毕；经通信主管部门负责人批准可以延长，但不得超过 90日；特殊情况下 90 日内不能办理完毕的，报经上一级通信主管部门批准，可以延长至 180 日。"},{"i":30,"n":"第三十条","txt":"通信主管部门拟作出责令停产停业（关闭网站）、吊销许可证或者执照、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利。当事人要求听证的，应当组织听证。 本条前款所称较大数额，是指对公民罚款 1 万元以上、对法人或其他组织罚款 10 万元以上；地方通信主管部门也可以按照省、自治区、直辖市人大常委会或者人民政府规定的标准执行。"},{"i":31,"n":"第三十一条","txt":"听证由拟作出行政处罚的通信主管部门组织。具体实施工作由其法制工作机构或者承担法制工作的机构负责。"},{"i":32,"n":"第三十二条","txt":"当事人要求听证的，应当在收到《行政处罚意见告知书》之日起 3 日内以书面或口头形式提出。口头形式提出的，案件调查人员应当记录在案，并由当事人签字。 案件调查人员应当在当事人要求听证之日起 3 日内告知法制工作机构或者承担法制工作的机构，并将案卷一并移送。"},{"i":33,"n":"第三十三条","txt":"当事人提出听证要求后，法制工作机构或者承担法制工作的机构应当在举行听证 7 日前送达《行政处罚听证会通知书》，告知当事人举行听证的时间、地点、听证会主持人名单及可以申请回避和可以委托代理人等事项，并通知案件调查人员。"},{"i":34,"n":"第三十四条","txt":"当事人应当按期参加听证。当事人有正当理由要求延期的，经批准可以延期一次；当事人未按期参加听证并且未事先说明理由的，视为放弃听证权利。"},{"i":35,"n":"第三十五条","txt":"听证会参加人由听证主持人、听证记录员、案件调查人员、当事人及其委托代理人组成。 听证主持人、听证记录员应当由法制工作机构工作人员或者其他相应工作人员等非本案调查人员担任。 当事人委托代理人参加听证的，应当提交委托书。"},{"i":36,"n":"第三十六条","txt":"除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。"},{"i":37,"n":"第三十七条","txt":"当事人在听证中的权利和义务： （一） 有权对案件涉及的事实、适用法律及相关情况进行陈述和申辩； （二） 有权对案件调查人员提出的证据质证并提出新的证据； （三） 如实回答主持人的提问； （四） 遵守听证程序。"},{"i":38,"n":"第三十八条","txt":"听证应当按照下列程序进行： （一） 听证记录员宣布听证会纪律、当事人权利和义务。听证主持人宣布案由，核实听证参加人名单，宣布听证开始； （二） 案件调查人员提出当事人违法的事实、证据，说明拟作出的行政处罚的内容及法律依据； （三） 当事人或者其委托代理人对案件的事实、证据、适用的法律等进行陈述和申辩，可以向听证会提交新的证据； （四） 听证主持人就案件的有关问题向当事人、案件调查人员、证人询问； （五） 案件调查人员、当事人或者其委托代理人经听证主持人允许，可以就有关证据进行质问，也可以向到场的证人发问； （六） 当事人或者其委托代理人作最后陈述； （七） 听证主持人宣布听证结束。听证笔录交当事人审核无误后签字或者盖章。"},{"i":39,"n":"第三十九条","txt":"听证结束后，听证主持人应当依据听证情况，制作《行政处罚听证会报告书》并提出处理意见，连同听证笔录，报本通信主管部门负责人审查。"},{"i":40,"n":"第四十条","txt":"行政处罚决定书应当在宣告后当场交付当事人，由当事人在送达回证上记明收到日期，签名或者盖章。当事人不在场的，应当在 7 日内依照民事诉讼法的有关规定，将行政处罚决定书送达当事人。"},{"i":41,"n":"第四十一条","txt":"当事人拒绝接收行政处罚决定书的，送达人应当邀请第三方单位的代表到场见证，并说明情况，将行政处罚决定书留其单位或者住所，在送达回证上记明拒收事由、送达日期，由送达人、见证人签名或者盖章，即视为送达。"},{"i":42,"n":"第四十二条","txt":"行政处罚决定依法作出后，当事人应当按照行政处罚决定书规定的内容、方式和期限，履行行政处罚决定。 当事人对行政处罚决定不服申请行政复议或者提起行政诉讼的，行政处罚不停止执行，法律另有规定的除外。"},{"i":43,"n":"第四十三条","txt":"执法人员当场收缴罚款的，应当向当事人出具省级财政部门统一制发的罚款收据。通信主管部门应当在法定期限内将罚款交付指定银行。"},{"i":44,"n":"第四十四条","txt":"对生效的行政处罚决定，当事人逾期不履行的，作出行政处罚的通信主管部门可以依法申请人民法院强制执行，申请执行书应当自当事人的法定起诉期限届满之日起 180 日内向人民法院提出。 对当事人作出罚款决定的，当事人到期不缴纳罚款，作出行政处罚的通信主管部门可以依法从到期之次日起，每日按罚款数额的 3% 加处罚款。"},{"i":45,"n":"第四十五条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，当事人应当书面申请，经作出行政处罚决定的通信主管部门批准，可以暂缓或者分期缴纳。"},{"i":46,"n":"第四十六条","txt":"罚款、没收的违法所得或者拍卖非法财物的款项，必须全部上缴国库，任何单位和个人不得以任何形式截留、私分或者变相私分。"},{"i":47,"n":"第四十七条","txt":"行政处罚案件终结后，应当填写《行政处罚结案表》，并将全部案件材料立卷归档。"},{"i":48,"n":"第四十八条","txt":"通信主管部门查处违法案件，应当使用信息产业部统一格式的文书（附后）。"},{"i":49,"n":"第四十九条","txt":"本规定自发布之日起施行。本规定施行前制定的规章和其他规范性文件与本规定不一致的，按本规定执行。原邮电部 1995 年 10 月 27 日发布的《通信行政处罚程序暂行规定》同时废止。"}],"daolujidongcheliangshengchanqiyejichanpinzhunrugua4c1ec0":[{"i":1,"n":"第一条","txt":"为了规范道路机动车辆生产企业及产品准入管理，维护公民生命、财产安全和公共安全，促进汽车产业发展，根据《中华人民共和国行政许可法》《中华人民共和国道路交通安全法》《国务院对确需保留的行政审批项目设定行政许可的决定》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对从事道路机动车辆生产的企业及其生产的在境内使用的道路机动车辆产品实行分类准入管理。 道路机动车辆生产企业及产品分为乘用车类、货车类、客车类、专用车类、摩托车类、挂车类六类。客车类道路机动车辆生产企业及产品分为整车类和改装类。 本办法所称道路机动车辆，是指由动力装置驱动或牵引，上道路行驶的供人员乘用或用于运送物品以及进行工程专项作业的轮式车辆，不包括汽车列车、无轨电车、有轨电车、轮式专用机械车、拖拉机及拖拉机运输机组。"},{"i":3,"n":"第三条","txt":"工业和信息化部负责全国道路机动车辆生产企业及产品准入和监督管理工作。 省、自治区、直辖市人民政府工业和信息化主管部门依照本办法规定配合工业和信息化部实施本行政区域内道路机动车辆生产企业及产品准入和监督管理有关工作。"},{"i":4,"n":"第四条","txt":"道路机动车辆生产企业应当按照道路机动车辆生产企业及产品准入的内容组织生产，承担道路机动车辆产品质量和生产一致性责任。"},{"i":5,"n":"第五条","txt":"申请道路机动车辆生产企业准入的，应当具备下列条件： （一）具有法人资格； （二）按照国家有关投资管理规定完成投资项目手续并建设完成； （三）有与从事生产活动相适应的场所、资金和人员等； （四）有与从事生产活动相适应的产品设计开发能力、生产能力、生产一致性保证能力、售后服务保障能力等； （五）法律、行政法规、规章规定的其他条件。"},{"i":6,"n":"第六条","txt":"申请道路机动车辆产品准入的，应当具备下列条件： （一）取得道路机动车辆生产企业准入； （二）生产的道路机动车辆产品能够满足安全、环保、节能、防盗等技术标准以及工业和信息化部制定发布的安全技术条件； （三）法律、行政法规、规章规定的其他条件。"},{"i":7,"n":"第七条","txt":"申请道路机动车辆生产企业准入的，应当向工业和信息化部提交下列材料： （一）道路机动车辆生产企业准入申请书（示范文本由工业和信息化部制作并公布）； （二）根据国家有关投资管理规定办理完成投资项目手续的文件； （三）加盖企业公章的企业章程及营业执照副本复印件； （四）企业法定代表人签署的依法开展道路机动车辆产品生产承诺书。"},{"i":8,"n":"第八条","txt":"申请道路机动车辆产品准入的，应当向工业和信息化部提交下列材料： （一）道路机动车辆产品及类别、特点、技术功能等情况说明； （二）道路机动车辆产品主要技术参数，包括表征道路机动车辆产品基本特征的参数，与道路机动车辆产品安全、环保、节能、防盗性能相关的参数和图片等； （三）道路机动车辆产品检验资料，包括检验项目统计表、样车情况说明、检验检测机构出具的检验报告等（列入强制性产品认证目录的道路机动车辆产品零部件检验报告可以由强制性产品认证证书替代）； （四）合法使用道路机动车辆产品商标的说明材料（仅在首次申请包含该商标的道路机动车辆产品准入时提供）、道路机动车辆产品依法进行环保信息公开情况等其他资料。"},{"i":9,"n":"第九条","txt":"道路机动车辆生产企业有权自主选择依法取得相关资质认定的检验检测机构开展道路机动车辆产品检验；开展整车检验的，应当选择取得国家级产品质量监督检验中心资质的检验检测机构。 送检的道路机动车辆产品应当由申请人制造，相关技术参数应与申请准入的道路机动车辆产品一致。"},{"i":10,"n":"第十条","txt":"工业和信息化部收到道路机动车辆生产企业及产品准入申请后，应当依法进行审查，对于申请材料不齐全或者不符合规定形式的，当场或者在五个工作日内一次性告知申请人需要补正的全部内容；对于申请材料齐全、符合规定形式的，应当予以受理。"},{"i":11,"n":"第十一条","txt":"工业和信息化部委托技术服务机构组织专家对道路机动车辆生产企业及产品准入申请进行技术审查。"},{"i":12,"n":"第十二条","txt":"技术服务机构应当客观、公正实施技术审查，如实向工业和信息化部报告审查结果。"},{"i":13,"n":"第十三条","txt":"技术服务机构不得泄露因审查活动知悉的商业秘密，开展技术审查不得向申请准入的企业收取任何费用。"},{"i":14,"n":"第十四条","txt":"工业和信息化部应当对符合准入条件的道路机动车辆生产企业及产品予以公示，公示期为五个工作日。 公示期内社会公众提出异议的，工业和信息化部可以委托技术服务机构组织专家进行复核。"},{"i":15,"n":"第十五条","txt":"工业和信息化部应当自受理准入申请之日起二十个工作日内作出准入或者不予准入的决定。决定准入的，应当以公告形式向社会发布；决定不予准入的，应当书面通知申请人并说明理由。二十个工作日内不能作出决定的，经工业和信息化部负责人批准，可以延长十个工作日，并将延长期限的理由告知申请人。 技术审查、复核所需时间不计算在前款规定的期限内，所需时间应当书面告知申请人。"},{"i":16,"n":"第十六条","txt":"道路机动车辆生产企业取得相关准入后方可生产、销售相应的道路机动车辆产品。 道路机动车辆生产企业应当持续保持准入条件。"},{"i":17,"n":"第十七条","txt":"道路机动车辆生产企业变更法定代表人、企业名称、注册地址、注册商标、股权结构的，应当在依法完成变更登记手续后及时报工业和信息化部备案。 报送备案应当提交变更情形的说明、变更前后加盖企业公章的营业执照副本复印件等材料，涉及办理投资项目手续的还应当提交相关的投资项目文件。"},{"i":18,"n":"第十八条","txt":"道路机动车辆生产企业变更道路机动车辆产品技术参数的，应当符合相关技术标准及道路机动车辆同一型号命名等技术规范要求，并在道路机动车辆产品投入生产前报工业和信息化部备案。 报送备案应当提交申请变更道路机动车辆产品型号、名称、类别，变更的原因及内容，符合安全、环保、节能、防盗等相关技术标准、技术条件的声明，以及相关检验项目统计表、检验报告等。"},{"i":19,"n":"第十九条","txt":"道路机动车辆生产企业变更生产地址的，应当按照本办法第七条的规定向工业和信息化部提交有关材料。工业和信息化部应当依照本办法的规定进行审查。"},{"i":20,"n":"第二十条","txt":"工业和信息化部对符合本办法规定条件的变更事项以公告形式发布。"},{"i":21,"n":"第二十一条","txt":"道路机动车辆生产企业按照本办法规定变更企业名称、注册地址、生产地址、注册商标、道路机动车辆产品技术参数等的，可以在工业和信息化部发布变更公告后的六个月内继续销售按照原准入事项生产的库存道路机动车辆产品，但国家政策、标准另有规定的除外。"},{"i":22,"n":"第二十二条","txt":"依法取得的道路机动车辆生产企业及产品准入，不得出租、出借、买卖或者以其他形式非法转让。"},{"i":23,"n":"第二十三条","txt":"道路机动车辆生产企业应当建立道路机动车辆产品出厂合格证明（以下简称合格证）管理制度，规范合格证制作、发放、传送、追溯、备案等工作，实时填报、传送合格证电子信息，在道路机动车辆产品检验合格准予出厂后随车配发合格证。 合格证载明的信息应当与获得准入的道路机动车辆产品技术参数，以及道路机动车辆产品实际的技术参数一致。合格证不得涂改、复制、买卖、伪造和抵押。"},{"i":24,"n":"第二十四条","txt":"鼓励道路机动车辆生产企业进行技术创新。因采用新技术、新工艺、新材料等原因，不能满足本办法规定的准入条件的，企业在申请道路机动车辆生产企业及产品准入时可以提出相关准入条件豁免申请。 工业和信息化部应当评估其必要性、充分性，根据技术审查和评估结果，作出是否准入的决定。决定准入的，工业和信息化部可以设置准入有效期、实施区域等限制性措施。"},{"i":25,"n":"第二十五条","txt":"鼓励道路机动车辆生产企业实施企业集团化管理。 符合规定条件的企业集团可以试点开展道路机动车辆产品自我检验；成员企业可以委托企业集团内部取得同类别道路机动车辆生产企业准入的其他企业生产其取得准入的道路机动车辆产品；工业和信息化部可以简化其成员企业的准入审查要求。"},{"i":26,"n":"第二十六条","txt":"工业和信息化部推行道路机动车辆产品系族管理，鼓励道路机动车辆生产企业按照系族提出道路机动车辆产品准入申请。"},{"i":27,"n":"第二十七条","txt":"工业和信息化部优化平板、仓栅、厢式、自卸货车管理。 货车类道路机动车辆生产企业可以委托上装生产企业完成平板、仓栅、厢式、自卸货车产品的上装生产作业。货车类道路机动车辆生产企业对采用本企业生产的底盘进行上装生产的平板、仓栅、厢式、自卸货车产品进行统一道路机动车辆产品准入申请，承担产品质量和生产一致性责任。"},{"i":28,"n":"第二十八条","txt":"鼓励道路机动车辆生产企业之间开展研发和产能合作，允许符合规定条件的道路机动车辆生产企业委托加工生产。 鼓励道路机动车辆研发设计企业与生产企业合作，允许符合规定条件的研发设计企业借用生产企业的生产能力申请道路机动车辆生产企业及产品准入。"},{"i":29,"n":"第二十九条","txt":"特别规定事项的具体管理办法由工业和信息化部另行制定。"},{"i":30,"n":"第三十条","txt":"工业和信息化部应当加强对道路机动车辆生产企业及产品准入的监督管理，建立和完善以随机抽查为重点的日常监督检查制度。对于社会反映集中、问题性质严重的道路机动车辆生产企业及产品，工业和信息化部应当组织开展专项监督检查。"},{"i":31,"n":"第三十一条","txt":"道路机动车辆生产企业应当加强自查，发现生产、销售的道路机动车辆产品存在安全、环保、节能、防盗等严重问题的，应当立即停止相关产品的生产、销售，采取措施进行整改，并及时向工业和信息化部及所在地的省、自治区、直辖市人民政府工业和信息化主管部门报告。 省、自治区、直辖市人民政府工业和信息化主管部门发现本行政区域内道路机动车辆生产企业不能保持准入条件、生产一致性发生重大变化或者有其他违法违规生产经营行为的，应当及时向工业和信息化部报告。"},{"i":32,"n":"第三十二条","txt":"道路机动车辆生产企业不能保持准入条件，生产的道路机动车辆产品存在影响公共安全、人身健康、生命财产安全等隐患的，工业和信息化部应当责令停止生产、销售相关产品，并责令立即改正。"},{"i":33,"n":"第三十三条","txt":"道路机动车辆生产企业买卖、伪造合格证，合格证载明的信息与获得准入的道路机动车辆产品技术参数不一致或者与道路机动车辆产品实际的技术参数不一致，或者有其他违反合格证管理规定的，工业和信息化部应当责令限期整改，视情节轻重暂停道路机动车辆生产企业合格证电子信息传送。"},{"i":34,"n":"第三十四条","txt":"道路机动车辆生产企业不能维持正常生产经营的，工业和信息化部应当予以特别公示。特别公示前，应当书面告知道路机动车辆生产企业，并听取申辩意见。 经特别公示的道路机动车辆生产企业，工业和信息化部在公示期间不予办理准入变更。道路机动车辆生产企业申请移出特别公示的，工业和信息化部应当对其保持道路机动车辆生产企业及产品准入条件情况进行核查。 不能维持正常生产经营是指：连续两年年均乘用车产量少于2000辆、货车产量少于1000辆、客车（整车类）产量少于1000辆、客车（改装类）产量少于100辆、摩托车产量少于5000辆、通用货车挂车产量少于100辆。工业和信息化部可以根据产业发展情况调整有关产量数值。"},{"i":35,"n":"第三十五条","txt":"道路机动车辆生产企业破产、自愿终止道路机动车辆生产，或者存在法律、行政法规规定的其他情形的，工业和信息化部应当依法撤销、注销相关的道路机动车辆生产企业及产品准入。"},{"i":36,"n":"第三十六条","txt":"承担道路机动车辆产品检验的检验检测机构应当在完成道路机动车辆产品检验后的三个月内保证检验样品的可追溯性，六年内保证检验记录、试验图像、影像资料等数据资料的可追溯性。工业和信息化部对检验检测机构开展道路机动车辆产品准入检验情况进行检查。"},{"i":37,"n":"第三十七条","txt":"工业和信息化部建立信用记录制度，将道路机动车辆生产企业、检验检测机构失信行为记入信用档案。"},{"i":38,"n":"第三十八条","txt":"隐瞒有关情况或者提供虚假材料申请道路机动车辆生产企业及产品准入的，工业和信息化部不予受理或者不予准入，并给予警告；申请人在一年内不得再次申请道路机动车辆生产企业及产品准入。 以欺骗、贿赂等不正当手段取得道路机动车辆生产企业及产品准入的，工业和信息化部应当撤销道路机动车辆生产企业及产品准入；申请人在三年内不得再次申请道路机动车辆生产企业及产品准入。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，未经准入擅自生产、销售道路机动车辆产品的，工业和信息化部应当依照《中华人民共和国道路交通安全法》第一百零三条第三款的规定予以处罚。"},{"i":40,"n":"第四十条","txt":"违反本办法规定，在报送备案时隐瞒有关情况、提供虚假材料的，工业和信息化部不予备案或者撤销备案，并给予警告。"},{"i":41,"n":"第四十一条","txt":"违反本办法规定，出租、出借、买卖或者以其他形式非法转让道路机动车辆生产企业及产品准入的，工业和信息化部给予警告，并责令立即改正。"},{"i":42,"n":"第四十二条","txt":"道路机动车辆生产企业在监督检查中隐瞒有关情况、提供虚假资料，或者不接受工业和信息化主管部门监督检查的，工业和信息化部给予警告。"},{"i":43,"n":"第四十三条","txt":"检验检测机构出具虚假检验报告或者检验结果存在重大失误的，工业和信息化部向检验检测机构资质管理部门进行通报。"},{"i":44,"n":"第四十四条","txt":"工业和信息化部工作人员在道路机动车辆生产企业及产品准入管理中玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"道路机动车辆生产企业及产品准入审查要求，工业和信息化部另行制定。"},{"i":46,"n":"第四十六条","txt":"新能源汽车生产企业及产品准入管理适用本办法，相关规章另有规定的，依照其规定执行。"},{"i":47,"n":"第四十七条","txt":"本办法自2019年6月1日起施行。2002年11月30日公布的《摩托车生产准入管理办法》（原国家经济贸易委员会令第43号）同时废止。"}],"zhongdianyongnengdanweijienengguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强重点用能单位的节能管理，提高能源利用效率和经济效益，保护环境，根据《中华人民共和国节约能源法》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称重点用能单位是指： （一）年综合能源消费量 1 万吨标准煤以上（含 1 万吨，下同）的用能单位； （二）各省、自治区、直辖市经济贸易委员会（经济委员会、计划与经济委员会，下同）指定的年综合能源消费量 5000 吨标准煤以上（含 5000 吨，下同）、不足 1 万吨标准煤的用能单位。能源消费的核算单位是法人企业。"},{"i":3,"n":"第三条","txt":"重点用能单位应遵守《中华人民共和国节约能源法》及本办法的规定，按照合理用能的原则，加强节能管理，推进技术进步，提高能源利用效率，降低成本，提高效益，减少环境污染。"},{"i":4,"n":"第四条","txt":"国家经济贸易委员会负责全国重点用能单位节能监督管理工作。国务院有关部门在各自的职责范围内协助做好重点用能单位节能监督管理工作。各省、自治区、直辖市经济贸易委员会负责本行政区内重点用能单位节能监督管理工作。"},{"i":5,"n":"第五条","txt":"国家经济贸易委员会会同国家统计局定期公布年综合能源消费量 1 万吨标准煤以上的重点用能单位名单，并定期发布年综合能源消费量 1 万吨标准煤以上的重点用能单位能源利用状况公报。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市经济贸易委员会会同同级统计部门，定期公布本行政区内年综合能源消费量 5000 吨标准煤以上、不足 1 万吨标准煤的重点用能单位名单，并报国家经济贸易委员会备案；定期发布本行政区内年综合能源消费量 5000吨标准煤以上、不足 1 万吨标准煤的重点用能单位能源利用状况公报。"},{"i":7,"n":"第七条","txt":"各省、自治区、直辖市经济贸易委员会按照年综合能源消费量制定重点用能单位分级管理方案并报国家经济贸易委员会备案。 实施分级管理的主管经济贸易委员会履行下列职责： （一）组织对重点用能单位的固定资产投资工程项目可行性研究报告中的节能篇（章）提出评价意见； （二）监督检查重点用能单位的主要耗能设备和工艺系统能源利用状况，委托具有检验测试资格的单位对重点用能单位进行节能的检验测试； （三）会同同级质量技术监督管理部门检查重点用能单位能源计量工作，会同同级统计管理部门检查重点用能单位能源消费和能源利用状况统计工作。"},{"i":8,"n":"第八条","txt":"国家经济贸易委员会和省、自治区、直辖市经济贸易委员会负责委托具有培训条件的单位，对重点用能单位的能源管理人员进行节能培训。"},{"i":9,"n":"第九条","txt":"重点用能单位应贯彻执行国家的节能法律、法规、方针、政策和标准。"},{"i":10,"n":"第十条","txt":"重点用能单位应接受主管经济贸易委员会对其能源利用状况的监督、检查。"},{"i":11,"n":"第十一条","txt":"重点用能单位应建立健全节能管理制度，运用科学的管理方法和先进的技术手段，制定并组织实施本单位节能计划和节能技术进步措施，合理有效地利用能源。"},{"i":12,"n":"第十二条","txt":"重点用能单位每年应安排一定数额资金用于节能科研开发、节能技术改造和节能宣传与培训。"},{"i":13,"n":"第十三条","txt":"重点用能单位应健全能源计量、监测管理制度，配备合格的能源计量器具、仪表，能源计量器具的配备和管理应达到《企业能源计量器具配备和管理导则》规定的国家标准。"},{"i":14,"n":"第十四条","txt":"重点用能单位应建立能源消费统计和能源利用状况报告制度。重点用能单位应指定专人负责能源统计，建立健全原始记录和统计台帐。 重点用能单位应在每年 1 月底前向主管经济贸易委员会报送上一年度的能源利用状况报告。报告应包括能源购入、能源加工转换与消费、单位产品能耗、主要耗能设备和工艺能耗、能源利用效率、能源管理、节能措施和节能经济效益分析、预测能源消费等。"},{"i":15,"n":"第十五条","txt":"重点用能单位应建立能源消耗成本管理制度。重点用能单位应根据国家经济贸易委员会和省、自治区、直辖市经济贸易委员会会同有关部门制定的单位产品能耗限额，制定先进、合理的企业单位产品能耗限额，实行能源消耗成本管理。"},{"i":16,"n":"第十六条","txt":"重点用能单位应建立有利于节约能源、降低消耗、提高经济效益的节能工作责任制。明确节能工作岗位的任务和责任，通过岗位责任制和能耗定额管理等形式将能源使用管理制度化、落实到人，纳入经济责任制。"},{"i":17,"n":"第十七条","txt":"重点用能单位应开展节能宣传与培训。主要耗能设备操作人员未经节能培训不得上岗。"},{"i":18,"n":"第十八条","txt":"重点用能单位应设立能源管理岗位，聘任的能源管理人员应熟悉国家有关节能法律、法规、方针、政策，具有节能知识、三年以上实际工作经验和工程师以上（含工程师）职称，并报主管经济贸易委员会备案。能源管理人员负责对本单位的能源利用状况进行监督检查。"},{"i":19,"n":"第十九条","txt":"各级人民政府对在节能管理和节能技术进步中取得显著成绩的重点用能单位和个人给予表彰和奖励。"},{"i":20,"n":"第二十条","txt":"重点用能单位应制定节奖超罚办法，安排一定的节能奖励资金，对节能工作中取得成绩的集体和个人给予奖励；对浪费能源的集体和个人给予惩罚。"},{"i":21,"n":"第二十一条","txt":"重点用能单位违反本办法第十条规定，拒绝接受监督、检查的；或违反本办法第十四条规定，未建立能源消费统计和能源利用状况报告制度的；或违反本办法第十八条规定，未设立能源管理岗位或所聘能源管理人员不符合要求的，由主管经济贸易委员会以书面形式责令限期改正。逾期未改正的，对其及有关负责人给予通报批评。"},{"i":22,"n":"第二十二条","txt":"重点用能单位虚报、瞒报、拒报、迟报、伪造、篡改能源消费统计资料的，按《中华人民共和国统计法》的有关规定予以处罚。"},{"i":23,"n":"第二十三条","txt":"本办法由国家经济贸易委员会负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自公布之日起施行。"}],"feijingyingxinghulianwangxinxifuwubeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范非经营性互联网信息服务备案及备案管理，促进互联网信息服务业的健康发展，根据《互联网信息服务管理办法》、《中华人民共和国电信条例》及其他相关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供非经营性互联网信息服务，履行备案手续，实施备案管理，适用本办法。"},{"i":3,"n":"第三条","txt":"中华人民共和国信息产业部（以下简称 “ 信息产业部 ” ）对全国非经营性互联网信息服务备案管理工作进行监督指导，省、自治区、直辖市通信管理局（以下简称 “ 省通信管理局 ” ）具体实施非经营性互联网信息服务的备案管理工作。 拟从事非经营性互联网信息服务的，应当向其住所所在地省通信管理局履行备案手续。"},{"i":4,"n":"第四条","txt":"省通信管理局在备案管理中应当遵循公开、公平、公正的原则，提供便民、优质、高效的服务。 非经营性互联网信息服务提供者从事非经营性互联网信息服务时，应当遵守国家的有关规定，接受有关部门依法实施的监督管理。"},{"i":5,"n":"第五条","txt":"在中华人民共和国境内提供非经营性互联网信息服务，应当依法履行备案手续。 未经备案，不得在中华人民共和国境内从事非经营性互联网信息服务。 本办法所称在中华人民共和国境内提供非经营性互联网信息服务，是指在中华人民共和国境内的组织或个人利用通过互联网域名访问的网站或者利用仅能通过互联网 IP 地址访问的网站，提供非经营性互联网信息服务。"},{"i":6,"n":"第六条","txt":"省通信管理局通过信息产业部备案管理系统，采用网上备案方式进行备案管理。"},{"i":7,"n":"第七条","txt":"拟从事非经营性互联网信息服务的，应当通过信息产业部备案管理系统如实填报《非经营性互联网信息服务备案登记表》（以下简称 “ 《备案登记表》 ” ，格式见本办法附录），履行备案手续。 信息产业部根据实际情况，对《备案登记表》进行调整和公布。"},{"i":8,"n":"第八条","txt":"拟通过接入经营性互联网络从事非经营性互联网信息服务的，可以委托因特网接入服务业务经营者、因特网数据中心业务经营者和以其他方式为其网站提供接入服务的电信业务经营者代为履行备案、备案变更、备案注销等手续。"},{"i":9,"n":"第九条","txt":"拟通过接入中国教育和科研计算机网、中国科学技术网、中国国际经济贸易互联网、中国长城互联网等公益性互联网络从事非经营性互联网信息服务的，可以由为其网站提供互联网接入服务的公益性互联网络单位代为履行备案、备案变更、备案注销等手续。"},{"i":10,"n":"第十条","txt":"因特网接入服务业务经营者、因特网数据中心业务经营者以及以其他方式为网站提供接入服务的电信业务经营者和公益性互联网络单位（以下统称 “ 互联网接入服务提供者 ” ）不得在已知或应知拟从事非经营性互联网信息服务的组织或者个人的备案信息不真实的情况下，为其代为履行备案、备案变更、备案注销等手续。"},{"i":11,"n":"第十一条","txt":"拟从事新闻、出版、教育、医疗保健、药品和医疗器械、文化、广播电影电视节目等互联网信息服务，根据法律、行政法规以及国家有关规定应经有关主管部门审核同意的，在履行备案手续时，还应向其住所所在地省通信管理局提交相关主管部门审核同意的文件。 拟从事电子公告服务的，在履行备案手续时，还应当向其住所所在地省通信管理局提交电子公告服务专项备案材料。"},{"i":12,"n":"第十二条","txt":"省通信管理局在收到备案人提交的备案材料后，材料齐全的，应在二十个工作日内予以备案，向其发放备案电子验证标识和备案编号，并通过信息产业部备案管理系统向社会公布有关备案信息；材料不齐全的，不予备案，在二十个工作日内通知备案人并说明理由。"},{"i":13,"n":"第十三条","txt":"非经营性互联网信息服务提供者应当在其网站开通时在主页底部的中央位置标明其备案编号，并在备案编号下方按要求链接信息产业部备案管理系统网址，供公众查询核对。 非经营性互联网信息服务提供者应当在其网站开通时，按照信息产业部备案管理系统的要求，将备案电子验证标识放置在其网站的指定目录下。"},{"i":14,"n":"第十四条","txt":"非经营性互联网信息服务提供者在备案有效期内需要变更其《备案登记表》中填报的信息的，应当提前三十日登陆信息产业部备案系统向原备案机关履行备案变更手续。"},{"i":15,"n":"第十五条","txt":"非经营性互联网信息服务提供者在备案有效期内需要终止提供服务的，应当在服务终止之日登陆信息产业部备案系统向原备案机关履行备案注销手续。"},{"i":16,"n":"第十六条","txt":"非经营性互联网信息服务提供者应当保证所提供的信息内容合法。 本办法所称非经营性互联网信息服务提供者提供的信息内容，是指互联网信息服务提供者的网站的互联网域名或 IP 地址下所包括的信息内容。"},{"i":17,"n":"第十七条","txt":"省通信管理局应当建立信誉管理、社会监督、情况调查等管理机制，对非经营性互联网信息服务活动实施监督管理。"},{"i":18,"n":"第十八条","txt":"互联网接入服务提供者不得为未经备案的组织或者个人从事非经营性互联网信息服务提供互联网接入服务。 对被省通信管理局处以暂时关闭网站或关闭网站处罚的非经营性互联网信息服务提供者或者非法从事非经营性互联网信息服务的组织或者个人，互联网接入服务提供者应立即暂停或终止向其提供互联网接入服务。"},{"i":19,"n":"第十九条","txt":"互联网接入服务提供者应当记录其接入的非经营性互联网信息服务提供者的备案信息。 互联网接入服务提供者应当依照国家有关规定做好用户信息动态管理、记录留存、有害信息报告等网络信息安全管理工作，根据信息产业部和省通信管理局的要求对所接入用户进行监督。"},{"i":20,"n":"第二十条","txt":"省通信管理局依法对非经营性互联网信息服务备案实行年度审核。 省通信管理局通过信息产业部备案管理系统，采用网上方式进行年度审核。"},{"i":21,"n":"第二十一条","txt":"非经营性互联网信息服务提供者应当在每年规定时间登陆信息产业部备案管理系统，履行年度审核手续。"},{"i":22,"n":"第二十二条","txt":"违反本办法第五条的规定，未履行备案手续提供非经营性互联网信息服务的，由住所所在地省通信管理局责令限期改正，并处一万元罚款；拒不改正的，关闭网站。 超出备案的项目提供服务的，由住所所在地省通信管理局责令限期改正，并处五千元以上一万元以下罚款；拒不改正的，关闭网站并注销备案。"},{"i":23,"n":"第二十三条","txt":"违反本办法第七条第一款的规定，填报虚假备案信息的，由住所所在地省通信管理局关闭网站并注销备案。"},{"i":24,"n":"第二十四条","txt":"违反本办法第十条、第十八条、第十九条的规定的，由违法行为发生地省通信管理局责令改正，并处一万元罚款。"},{"i":25,"n":"第二十五条","txt":"违反本办法第十三条的规定，未在其备案编号下方链接信息产业部备案管理系统网址的，或未将备案电子验证标识放置在其网站指定目录下的，由住所所在地省通信管理局责令改正，并处五千元以上一万元以下罚款。"},{"i":26,"n":"第二十六条","txt":"违反本办法第十四条、第十五条的规定，未在规定时间履行备案变更手续，或未依法履行备案注销手续的，由住所所在地省通信管理局责令限期改正，并处一万元罚款。"},{"i":27,"n":"第二十七条","txt":"非经营性信息服务提供者违反国家有关法律规定，依法应暂停或终止服务的，省通信管理局可根据法律、行政法规授权的同级机关的书面认定意见，暂时关闭网站，或关闭网站并注销备案。"},{"i":28,"n":"第二十八条","txt":"在年度审核时，非经营性互联网信息服务提供者有下列情况之一的，由其住所所在地的省通信管理局通过信息产业部备案系统等媒体通告责令其限期改正；拒不改正的，关闭网站并注销备案： （一）未在规定时间登陆备案网站提交年度审核信息的； （二）新闻、教育、公安、安全、文化、广播电影电视、出版、保密等国家部门依法对各自主管的专项内容提出年度审核否决意见的。"},{"i":29,"n":"第二十九条","txt":"本办法自 2005 年 3 月 20 日起施行。"}]};
